# Measurable Controlled Latent Trajectory Reasoning (M-CLTR) toy prototype
# Run this in Colab as a single cell.

import math, random, time
from dataclasses import dataclass
from typing import Dict, Tuple

import numpy as np
import torch
import torch.nn as nn
import torch.nn.functional as F

# -----------------------------
# Reproducibility / device
# -----------------------------
SEED = 7
random.seed(SEED)
np.random.seed(SEED)
torch.manual_seed(SEED)
if torch.cuda.is_available():
    torch.cuda.manual_seed_all(SEED)

device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
print("Device:", device)

# -----------------------------
# Task configuration
# -----------------------------
A_MAX = 30
B_MAX = 30
A_CLASSES = A_MAX + 1
B_CLASSES = B_MAX + 1
N_CLASSES = 61  # outputs in [0, 60]

T = 4           # latent iterations
D = 64          # latent size
K = 4           # failure memory size

# control / policy thresholds (measurable, fixed)
RESTART_THR = 0.25
STORE_THR = 0.35
OVERWRITE_THR = 0.55
EVAL_DECAY_GAMMA = 0.35
REPULSION_BETA = 0.25

# training settings
WARMUP_EPOCHS = 3
CONTROL_EPOCHS = 4
BASELINE_EPOCHS = 5
STEPS_PER_EPOCH = 180
BATCH_SIZE = 256
LR = 3e-3

# -----------------------------
# Utilities
# -----------------------------
def one_hot(v: torch.Tensor, n: int) -> torch.Tensor:
    return F.one_hot(v.long(), n).float()

def encode_x(a: torch.Tensor, b: torch.Tensor) -> torch.Tensor:
    # one-hot representation of the two integers
    return torch.cat([one_hot(a, A_CLASSES), one_hot(b, B_CLASSES)], dim=-1)

def task_value(a: torch.Tensor, b: torch.Tensor, mode: torch.Tensor) -> torch.Tensor:
    # mode 0: sum mod 61, mode 1: product mod 61
    sumv = (a + b) % N_CLASSES
    prodv = (a * b) % N_CLASSES
    return torch.where(mode == 0, sumv, prodv)

def project_to_ball(z: torch.Tensor, radius: float = 5.0) -> torch.Tensor:
    norm = z.norm(dim=-1, keepdim=True).clamp_min(1e-6)
    scale = torch.clamp(radius / norm, max=1.0)
    return z * scale

def repulsion(cand: torch.Tensor,
              mem: torch.Tensor,
              mem_age: torch.Tensor,
              mem_mask: torch.Tensor,
              beta: float = REPULSION_BETA,
              gamma: float = EVAL_DECAY_GAMMA) -> torch.Tensor:
    """
    cand:     [B, D]
    mem:      [B, K, D]
    mem_age:  [B, K]
    mem_mask: [B, K]
    returns:  [B, D]
    """
    if not mem_mask.any():
        return torch.zeros_like(cand)

    cand_exp = cand.unsqueeze(1)  # [B, 1, D]
    diff = cand_exp - mem         # [B, K, D]
    dist = diff.norm(dim=-1, keepdim=True).clamp_min(1e-6)
    direction = diff / dist

    sim = F.cosine_similarity(cand_exp.expand_as(mem), mem, dim=-1)  # [B, K]
    weights = mem_mask.float() * torch.exp(-gamma * mem_age.float())  # [B, K]

    rep = (weights.unsqueeze(-1) * sim.unsqueeze(-1) * direction).sum(dim=1)
    return beta * rep

# -----------------------------
# Data generation
# -----------------------------
def make_batch(bs: int, force_switch=None, fixed_switch_step=None):
    """
    force_switch:
        True  -> always switch (end_mode != start_mode)
        False -> never switch (end_mode = start_mode)
        None  -> mixed data, 50% switch / 50% no-switch
    fixed_switch_step:
        if not None, use this step for switch samples (0-based step index).
        Example: fixed_switch_step=1 means switch occurs starting at step 1.
    """
    a = torch.randint(0, A_CLASSES, (bs,), device=device)
    b = torch.randint(0, B_CLASSES, (bs,), device=device)

    start_mode = torch.randint(0, 2, (bs,), device=device)

    if force_switch is True:
        end_mode = 1 - start_mode
        if fixed_switch_step is None:
            switch_step = torch.randint(1, T, (bs,), device=device)
        else:
            switch_step = torch.full((bs,), fixed_switch_step, device=device, dtype=torch.long)
    elif force_switch is False:
        end_mode = start_mode.clone()
        switch_step = torch.full((bs,), T, device=device, dtype=torch.long)
    else:
        end_mode = torch.randint(0, 2, (bs,), device=device)
        switch_step = torch.randint(1, T, (bs,), device=device)
        no_switch = torch.rand(bs, device=device) < 0.5
        switch_step = torch.where(no_switch, torch.full_like(switch_step, T), switch_step)

    ctrl_seq = []
    for t in range(T):
        tvec = torch.full_like(switch_step, t)
        mt = torch.where(tvec < switch_step, start_mode, end_mode)
        ctrl_seq.append(one_hot(mt, 2))
    ctrl_seq = torch.stack(ctrl_seq, dim=1)  # [B, T, 2]

    final_mode = torch.where(torch.full_like(switch_step, T - 1) < switch_step, start_mode, end_mode)
    target = task_value(a, b, final_mode)

    x = encode_x(a, b)
    start_ctrl = one_hot(start_mode, 2)
    return a, b, start_mode, end_mode, switch_step, x, start_ctrl, ctrl_seq, target

# -----------------------------
# Models
# -----------------------------
class MCLTR(nn.Module):
    def __init__(self, x_dim=62, ctrl_dim=2, d=D, n_classes=N_CLASSES):
        super().__init__()
        self.d = d
        self.x_dim = x_dim
        self.ctrl_dim = ctrl_dim

        self.init = nn.Sequential(
            nn.Linear(x_dim + ctrl_dim, d),
            nn.ReLU(),
            nn.Linear(d, d),
        )

        self.transition = nn.Sequential(
            nn.Linear(d + x_dim + ctrl_dim, d),
            nn.ReLU(),
            nn.Linear(d, d),
        )

        self.decoder = nn.Linear(d, n_classes)

        self.evaluator = nn.Sequential(
            nn.Linear(d + x_dim + ctrl_dim, 64),
            nn.ReLU(),
            nn.Linear(64, 1),
        )

        self.ctrl_to_latent = nn.Linear(ctrl_dim, d)
        self.x_to_latent = nn.Linear(x_dim, d)

    def project(self, z: torch.Tensor, radius: float = 5.0) -> torch.Tensor:
        return project_to_ball(z, radius=radius)

class StaticBaseline(nn.Module):
    def __init__(self, x_dim=62, ctrl_dim=2, d=D, n_classes=N_CLASSES):
        super().__init__()
        self.net = nn.Sequential(
            nn.Linear(x_dim + ctrl_dim, d),
            nn.ReLU(),
            nn.Linear(d, d),
            nn.ReLU(),
            nn.Linear(d, n_classes),
        )

    def forward(self, x: torch.Tensor, start_ctrl: torch.Tensor) -> torch.Tensor:
        return self.net(torch.cat([x, start_ctrl], dim=-1))

# -----------------------------
# MCLTR forward pass
# -----------------------------
@torch.no_grad()
def _argmax_correctness(logits: torch.Tensor, target: torch.Tensor) -> torch.Tensor:
    pred = logits.argmax(dim=-1)
    return (pred == target).float()

def run_mcltr(
    model: MCLTR,
    x: torch.Tensor,
    start_ctrl: torch.Tensor,
    ctrl_seq: torch.Tensor,
    target: torch.Tensor = None,
    controlled: bool = True,
    use_memory: bool = True,
):
    """
    Returns:
        final_logits, loss, action_counts, metrics_dict
    """
    B = x.size(0)
    z0 = model.init(torch.cat([x, start_ctrl], dim=-1))
    z = z0.clone()

    # memory (per batch element)
    mem = torch.zeros(B, K, model.d, device=x.device)
    mem_age = torch.zeros(B, K, device=x.device)
    mem_mask = torch.zeros(B, K, dtype=torch.bool, device=x.device)
    mem_ptr = torch.zeros(B, dtype=torch.long, device=x.device)

    prev_score = torch.full((B,), 0.5, device=x.device)

    total_ce = torch.tensor(0.0, device=x.device)
    total_bce = torch.tensor(0.0, device=x.device)

    action_counts = torch.zeros(3, device=x.device)  # continue, overwrite, restart
    step_scores = []
    step_deltas = []

    for t in range(T):
        ctrl = ctrl_seq[:, t, :]  # [B, 2]

        inp = torch.cat([z, x, ctrl], dim=-1)
        delta = torch.tanh(model.transition(inp))
        cand = 0.85 * z + 0.25 * delta + 0.05 * model.ctrl_to_latent(ctrl) + 0.05 * model.x_to_latent(x)

        if controlled and use_memory:
            cand = cand - repulsion(cand, mem, mem_age, mem_mask)

        logits = model.decoder(cand)
        score = torch.sigmoid(model.evaluator(torch.cat([cand, x, ctrl], dim=-1))).squeeze(-1)

        step_scores.append(score.detach().mean().item())
        step_deltas.append((score - prev_score).detach().mean().item())

        if target is not None:
            ce_t = F.cross_entropy(logits, target)
            total_ce = total_ce + (1.0 + 0.2 * t) * ce_t

            # evaluator supervision: predicted correctness of candidate state
            pred = logits.argmax(dim=-1)
            correct = (pred == target).float()
            total_bce = total_bce + F.binary_cross_entropy(score, correct)

        if controlled:
            if t == 0:
                z_next = cand
                action = torch.zeros(B, dtype=torch.long, device=x.device)  # continue
            else:
                restart = (score < RESTART_THR) & (score < prev_score - 0.03)
                overwrite = (~restart) & (score < OVERWRITE_THR) & (score < prev_score - 0.01)

                z_next = cand.clone()
                z_next[overwrite] = model.project(cand[overwrite])
                z_next[restart] = z0[restart]

                action = torch.zeros(B, dtype=torch.long, device=x.device)
                action[overwrite] = 1
                action[restart] = 2

            action_counts += torch.stack([
                (action == 0).sum(),
                (action == 1).sum(),
                (action == 2).sum()
            ]).float()
        else:
            z_next = cand
            action_counts[0] += B

        if controlled and use_memory:
            # age all stored entries
            mem_age[mem_mask] += 1.0

            # store low-confidence states
            store_bad = score < STORE_THR
            idx = torch.where(store_bad)[0]
            if idx.numel() > 0:
                slot = mem_ptr[idx] % K
                mem[idx, slot] = cand.detach()[idx]
                mem_age[idx, slot] = 0.0
                mem_mask[idx, slot] = True
                mem_ptr[idx] = (mem_ptr[idx] + 1) % K

        prev_score = score.detach()
        z = z_next

    final_logits = model.decoder(z)

    if target is not None:
        final_ce = F.cross_entropy(final_logits, target)
        loss = final_ce + 0.15 * (total_ce / T) + 0.10 * (total_bce / T)
    else:
        loss = None

    metrics = {
        "step_scores": step_scores,
        "step_deltas": step_deltas,
    }
    return final_logits, loss, action_counts, metrics

# -----------------------------
# Training loops
# -----------------------------
def train_mcltr(model: MCLTR, opt: torch.optim.Optimizer,
                epochs: int, steps_per_epoch: int,
                controlled: bool, force_switch=None, fixed_switch_step=None,
                tag="MCLTR"):
    model.train()
    for ep in range(epochs):
        t0 = time.time()
        running_loss = 0.0
        running_acc = 0.0
        running_actions = torch.zeros(3, device=device)

        for _ in range(steps_per_epoch):
            a, b, start_mode, end_mode, switch_step, x, start_ctrl, ctrl_seq, target = make_batch(
                BATCH_SIZE,
                force_switch=force_switch,
                fixed_switch_step=fixed_switch_step
            )
            final_logits, loss, action_counts, _ = run_mcltr(
                model,
                x, start_ctrl, ctrl_seq,
                target=target,
                controlled=controlled,
                use_memory=controlled
            )

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(model.parameters(), 1.0)
            opt.step()

            running_loss += loss.item()
            running_acc += (final_logits.argmax(dim=-1) == target).float().mean().item()
            running_actions += action_counts.detach()

        elapsed = time.time() - t0
        avg_loss = running_loss / steps_per_epoch
        avg_acc = running_acc / steps_per_epoch
        action_rates = (running_actions / (steps_per_epoch * BATCH_SIZE * T)).detach().cpu().numpy()
        print(f"{tag} epoch {ep+1}/{epochs} | loss {avg_loss:.4f} | acc {avg_acc:.4f} | "
              f"actions C/O/R {action_rates[0]:.3f}/{action_rates[1]:.3f}/{action_rates[2]:.3f} | "
              f"{elapsed:.1f}s")

def train_baseline(model: StaticBaseline, opt: torch.optim.Optimizer,
                   epochs: int, steps_per_epoch: int, tag="Baseline"):
    model.train()
    for ep in range(epochs):
        t0 = time.time()
        running_loss = 0.0
        running_acc = 0.0

        for _ in range(steps_per_epoch):
            a, b, start_mode, end_mode, switch_step, x, start_ctrl, ctrl_seq, target = make_batch(
                BATCH_SIZE, force_switch=False
            )

            logits = model(x, start_ctrl)
            loss = F.cross_entropy(logits, target)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(model.parameters(), 1.0)
            opt.step()

            running_loss += loss.item()
            running_acc += (logits.argmax(dim=-1) == target).float().mean().item()

        elapsed = time.time() - t0
        print(f"{tag} epoch {ep+1}/{epochs} | loss {running_loss/steps_per_epoch:.4f} | "
              f"acc {running_acc/steps_per_epoch:.4f} | {elapsed:.1f}s")

# -----------------------------
# Evaluation
# -----------------------------
@torch.no_grad()
def eval_mcltr(model: MCLTR, batches: int, bs: int, force_switch=None,
               fixed_switch_step=None, controlled=True, name="MCLTR"):
    model.eval()
    total = 0
    correct = 0
    action_counts = torch.zeros(3, device=device)

    # keep a few examples for inspection
    samples = []

    for _ in range(batches):
        a, b, start_mode, end_mode, switch_step, x, start_ctrl, ctrl_seq, target = make_batch(
            bs, force_switch=force_switch, fixed_switch_step=fixed_switch_step
        )
        final_logits, _, counts, _ = run_mcltr(
            model, x, start_ctrl, ctrl_seq,
            target=None,
            controlled=controlled,
            use_memory=controlled
        )
        pred = final_logits.argmax(dim=-1)
        correct += (pred == target).sum().item()
        total += target.numel()
        action_counts += counts

        if len(samples) < 6:
            for i in range(min(6 - len(samples), bs)):
                samples.append({
                    "a": int(a[i].item()),
                    "b": int(b[i].item()),
                    "start_mode": int(start_mode[i].item()),
                    "end_mode": int(end_mode[i].item()),
                    "switch_step": int(switch_step[i].item()),
                    "target": int(target[i].item()),
                    "pred": int(pred[i].item()),
                })

    acc = correct / total
    action_rates = (action_counts / (total * T)).detach().cpu().numpy()
    summary = {
        "acc": acc,
        "continue_rate": float(action_rates[0]),
        "overwrite_rate": float(action_rates[1]),
        "restart_rate": float(action_rates[2]),
        "samples": samples,
    }
    return summary

@torch.no_grad()
def eval_baseline(model: StaticBaseline, batches: int, bs: int, force_switch=None, name="Baseline"):
    model.eval()
    total = 0
    correct = 0
    samples = []

    for _ in range(batches):
        a, b, start_mode, end_mode, switch_step, x, start_ctrl, ctrl_seq, target = make_batch(
            bs, force_switch=force_switch
        )
        logits = model(x, start_ctrl)
        pred = logits.argmax(dim=-1)
        correct += (pred == target).sum().item()
        total += target.numel()

        if len(samples) < 6:
            for i in range(min(6 - len(samples), bs)):
                samples.append({
                    "a": int(a[i].item()),
                    "b": int(b[i].item()),
                    "start_mode": int(start_mode[i].item()),
                    "end_mode": int(end_mode[i].item()),
                    "switch_step": int(switch_step[i].item()),
                    "target": int(target[i].item()),
                    "pred": int(pred[i].item()),
                })

    return {"acc": correct / total, "samples": samples}

# -----------------------------
# Instantiate models
# -----------------------------
mcltr = MCLTR().to(device)
baseline = StaticBaseline().to(device)

opt_mcltr = torch.optim.AdamW(mcltr.parameters(), lr=LR, weight_decay=1e-4)
opt_base = torch.optim.AdamW(baseline.parameters(), lr=LR, weight_decay=1e-4)

# -----------------------------
# Train MCLTR
# Phase 1: warmup without actions/memory
# Phase 2: controlled training with actions/memory
# -----------------------------
print("\n=== Training MCLTR: warmup (continue-only) ===")
train_mcltr(
    mcltr, opt_mcltr,
    epochs=WARMUP_EPOCHS,
    steps_per_epoch=STEPS_PER_EPOCH,
    controlled=False,
    force_switch=None,          # mixed tasks
    fixed_switch_step=None,
    tag="MCLTR-warmup"
)

print("\n=== Training MCLTR: controlled phase (continue / overwrite / restart) ===")
train_mcltr(
    mcltr, opt_mcltr,
    epochs=CONTROL_EPOCHS,
    steps_per_epoch=STEPS_PER_EPOCH,
    controlled=True,
    force_switch=None,          # mixed tasks
    fixed_switch_step=None,
    tag="MCLTR-control"
)

# -----------------------------
# Train baseline (no online control; fixed-mode only)
# -----------------------------
print("\n=== Training Static Baseline (no online control; fixed tasks only) ===")
train_baseline(
    baseline, opt_base,
    epochs=BASELINE_EPOCHS,
    steps_per_epoch=STEPS_PER_EPOCH,
    tag="Baseline"
)

# -----------------------------
# Evaluation
# -----------------------------
print("\n=== Evaluation on fixed tasks (no switch) ===")
m_fixed_ctrl = eval_mcltr(mcltr, batches=20, bs=256, force_switch=False, controlled=True)
m_fixed_free = eval_mcltr(mcltr, batches=20, bs=256, force_switch=False, controlled=False)
b_fixed = eval_baseline(baseline, batches=20, bs=256, force_switch=False)

print(f"MCLTR controlled   acc={m_fixed_ctrl['acc']:.4f} | continue={m_fixed_ctrl['continue_rate']:.3f} "
      f"overwrite={m_fixed_ctrl['overwrite_rate']:.3f} restart={m_fixed_ctrl['restart_rate']:.3f}")
print(f"MCLTR continue-only acc={m_fixed_free['acc']:.4f} | continue={m_fixed_free['continue_rate']:.3f} "
      f"overwrite={m_fixed_free['overwrite_rate']:.3f} restart={m_fixed_free['restart_rate']:.3f}")
print(f"Baseline           acc={b_fixed['acc']:.4f}")

print("\n=== Evaluation on hard switch tasks (switch at step 1, end_mode != start_mode) ===")
m_switch_ctrl = eval_mcltr(mcltr, batches=20, bs=256, force_switch=True, fixed_switch_step=1, controlled=True)
m_switch_free = eval_mcltr(mcltr, batches=20, bs=256, force_switch=True, fixed_switch_step=1, controlled=False)
b_switch = eval_baseline(baseline, batches=20, bs=256, force_switch=True)

print(f"MCLTR controlled   acc={m_switch_ctrl['acc']:.4f} | continue={m_switch_ctrl['continue_rate']:.3f} "
      f"overwrite={m_switch_ctrl['overwrite_rate']:.3f} restart={m_switch_ctrl['restart_rate']:.3f}")
print(f"MCLTR continue-only acc={m_switch_free['acc']:.4f} | continue={m_switch_free['continue_rate']:.3f} "
      f"overwrite={m_switch_free['overwrite_rate']:.3f} restart={m_switch_free['restart_rate']:.3f}")
print(f"Baseline           acc={b_switch['acc']:.4f}")

# -----------------------------
# Inspect a few examples
# -----------------------------
print("\n=== Sample predictions on hard switch tasks ===")
for i, s in enumerate(m_switch_ctrl["samples"][:6]):
    print(
        f"[{i}] a={s['a']:2d} b={s['b']:2d} start={s['start_mode']} end={s['end_mode']} "
        f"switch_step={s['switch_step']} target={s['target']:2d} pred={s['pred']:2d}"
    )

print("\nDone.")

# M-CLTR v2.5 — faithful, measurable, staged prototype
# Run this as a single Colab cell.

import math
import random
import time
from dataclasses import dataclass

import torch
import torch.nn as nn
import torch.nn.functional as F

# -----------------------------
# Reproducibility / device
# -----------------------------
SEED = 7
random.seed(SEED)
torch.manual_seed(SEED)
torch.cuda.manual_seed_all(SEED) if torch.cuda.is_available() else None

device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
print("Device:", device)

# -----------------------------
# Task / model config
# -----------------------------
A_MAX = 30
B_MAX = 30
A_CLASSES = A_MAX + 1
B_CLASSES = B_MAX + 1
N_CLASSES = 61  # answer classes modulo 61

T = 4           # latent iterations
D = 64          # latent size

STAGE1_EPOCHS = 4
STAGE2_EPOCHS = 4
STAGE3_EPOCHS = 5
STAGE4_EPOCHS = 2

STEPS_PER_EPOCH = 80
BATCH_SIZE = 96
LR_BACKBONE = 2e-3
LR_EVAL = 2e-3
LR_POLICY = 2e-3
LR_FINETUNE = 2e-4

# -----------------------------
# Helpers
# -----------------------------
def one_hot(v: torch.Tensor, n: int) -> torch.Tensor:
    return F.one_hot(v.long(), n).float()

def make_step_feat(t: int, batch_size: int, device: torch.device) -> torch.Tensor:
    if T == 1:
        s = 0.0
    else:
        s = float(t) / float(T - 1)
    return torch.full((batch_size, 1), s, device=device)

def project_overwrite(z: torch.Tensor, radius: float = 3.5) -> torch.Tensor:
    norm = z.norm(dim=-1, keepdim=True).clamp_min(1e-6)
    scale = torch.clamp(radius / norm, max=1.0)
    return z * scale

def task_value(a: torch.Tensor, b: torch.Tensor, mode: torch.Tensor) -> torch.Tensor:
    # mode 0 = add, mode 1 = multiply
    addv = (a + b) % N_CLASSES
    mulv = (a * b) % N_CLASSES
    return torch.where(mode == 0, addv, mulv)

def make_batch(
    batch_size: int,
    switch_prob: float = 0.5,
    fixed_switch: bool | None = None,
    fixed_switch_step: int | None = None,
):
    """
    Returns:
      a, b, start_mode, end_mode, switch_step, x, start_ctrl, ctrl_seq, target
    """
    a = torch.randint(0, A_CLASSES, (batch_size,), device=device)
    b = torch.randint(0, B_CLASSES, (batch_size,), device=device)

    start_mode = torch.randint(0, 2, (batch_size,), device=device)

    if fixed_switch is True:
        end_mode = 1 - start_mode
        switch_step = torch.full((batch_size,), fixed_switch_step if fixed_switch_step is not None else 1,
                                 device=device, dtype=torch.long)
    elif fixed_switch is False:
        end_mode = start_mode.clone()
        switch_step = torch.full((batch_size,), T, device=device, dtype=torch.long)
    else:
        do_switch = (torch.rand(batch_size, device=device) < switch_prob)
        end_mode = torch.where(do_switch, 1 - start_mode, start_mode)
        # if switch happens, choose a switch step in [1, T-1], else no switch
        if T > 1:
            rand_step = torch.randint(1, T, (batch_size,), device=device)
        else:
            rand_step = torch.zeros(batch_size, device=device, dtype=torch.long)
        switch_step = torch.where(do_switch, rand_step, torch.full_like(rand_step, T))

    # x = [one-hot(a), one-hot(b), one-hot(start_mode)]
    x = torch.cat([one_hot(a, A_CLASSES), one_hot(b, B_CLASSES), one_hot(start_mode, 2)], dim=-1)

    # control sequence: current mode at each step
    ctrl_seq = []
    for t in range(T):
        mt = torch.where(torch.full_like(switch_step, t) < switch_step, start_mode, end_mode)
        ctrl_seq.append(one_hot(mt, 2))
    ctrl_seq = torch.stack(ctrl_seq, dim=1)  # [B, T, 2]

    # final mode is the mode active at the last step
    final_mode = torch.where(torch.full_like(switch_step, T - 1) < switch_step, start_mode, end_mode)
    target = task_value(a, b, final_mode)

    start_ctrl = one_hot(start_mode, 2)
    return a, b, start_mode, end_mode, switch_step, x, start_ctrl, ctrl_seq, target

def topk_acc(logits: torch.Tensor, target: torch.Tensor, k: int = 1) -> float:
    topk = logits.topk(k, dim=-1).indices
    return (topk == target.unsqueeze(-1)).any(dim=-1).float().mean().item()

# -----------------------------
# Model
# -----------------------------
class MCLTRNet(nn.Module):
    def __init__(self, x_dim=64, ctrl_dim=2, d=D, n_classes=N_CLASSES):
        super().__init__()
        self.d = d
        self.x_dim = x_dim
        self.ctrl_dim = ctrl_dim
        self.n_classes = n_classes

        self.init_net = nn.Sequential(
            nn.Linear(x_dim + ctrl_dim, d),
            nn.GELU(),
            nn.Linear(d, d),
        )

        self.trans = nn.Sequential(
            nn.Linear(d + x_dim + ctrl_dim + 1, d),
            nn.GELU(),
            nn.Linear(d, d),
        )

        self.dec = nn.Linear(d, n_classes)

        self.eval_net = nn.Sequential(
            nn.Linear(d + x_dim + ctrl_dim + 1, 64),
            nn.GELU(),
            nn.Linear(64, 1),
        )

        self.policy_net = nn.Sequential(
            nn.Linear(d + 3, 64),  # cand z + eval score + delta + step scalar
            nn.GELU(),
            nn.Linear(64, 3),      # continue / overwrite / restart
        )

        self.norm = nn.LayerNorm(d)

        self._init_weights()

    def _init_weights(self):
        for m in self.modules():
            if isinstance(m, nn.Linear):
                nn.init.xavier_uniform_(m.weight)
                if m.bias is not None:
                    nn.init.zeros_(m.bias)

    def init_state(self, x: torch.Tensor, start_ctrl: torch.Tensor) -> torch.Tensor:
        z0 = self.init_net(torch.cat([x, start_ctrl], dim=-1))
        return self.norm(z0)

    def step_update(self, z: torch.Tensor, x: torch.Tensor, ctrl: torch.Tensor, t: int) -> torch.Tensor:
        stepf = make_step_feat(t, z.size(0), z.device)
        inp = torch.cat([z, x, ctrl, stepf], dim=-1)
        delta = torch.tanh(self.trans(inp))
        cand = self.norm(z + 0.6 * delta)
        return cand

    def eval_score(self, z: torch.Tensor, x: torch.Tensor, ctrl: torch.Tensor, t: int) -> torch.Tensor:
        stepf = make_step_feat(t, z.size(0), z.device)
        inp = torch.cat([z, x, ctrl, stepf], dim=-1)
        return torch.sigmoid(self.eval_net(inp)).squeeze(-1)

    def policy_logits(self, z: torch.Tensor, score: torch.Tensor, delta: torch.Tensor, t: int) -> torch.Tensor:
        stepf = make_step_feat(t, z.size(0), z.device)
        inp = torch.cat([z, score.unsqueeze(-1), delta.unsqueeze(-1), stepf], dim=-1)
        return self.policy_net(inp)

    def decode(self, z: torch.Tensor) -> torch.Tensor:
        return self.dec(z)

# -----------------------------
# Rollouts / oracle utilities
# -----------------------------
@torch.no_grad()
def rollout_continue(model: MCLTRNet, z: torch.Tensor, x: torch.Tensor, ctrl_seq: torch.Tensor, start_t: int) -> torch.Tensor:
    for t in range(start_t, T):
        z = model.step_update(z, x, ctrl_seq[:, t, :], t)
    return z

@torch.no_grad()
def final_target_prob(model: MCLTRNet, z: torch.Tensor, x: torch.Tensor, ctrl_seq: torch.Tensor, start_t: int, target: torch.Tensor) -> torch.Tensor:
    final_z = rollout_continue(model, z, x, ctrl_seq, start_t)
    logits = model.decode(final_z)
    probs = F.softmax(logits, dim=-1)
    return probs.gather(1, target.unsqueeze(1)).squeeze(1)

@torch.no_grad()
def oracle_action_for_state(model: MCLTRNet, cand: torch.Tensor, z0: torch.Tensor, x: torch.Tensor, ctrl_seq: torch.Tensor, t: int, target: torch.Tensor):
    """
    Return:
      best_action: 0 continue, 1 overwrite, 2 restart
      best_prob: target probability after finishing trajectory with the best action
    """
    states = [
        cand,
        project_overwrite(cand),
        z0,
    ]

    probs = []
    for s in states:
        p = final_target_prob(model, s, x, ctrl_seq, t + 1, target)
        probs.append(p)

    probs = torch.stack(probs, dim=-1)  # [B, 3]

    # Mild tie preference: continue > overwrite > restart
    tie_bias = torch.tensor([2e-3, 1e-3, 0.0], device=probs.device).unsqueeze(0)
    action = (probs + tie_bias).argmax(dim=-1)
    best_prob = probs.gather(1, action.unsqueeze(1)).squeeze(1)
    return action, best_prob

# -----------------------------
# Training stages
# -----------------------------
def train_backbone(model: MCLTRNet, epochs: int, steps_per_epoch: int):
    model.train()
    for p in model.eval_net.parameters():
        p.requires_grad = False
    for p in model.policy_net.parameters():
        p.requires_grad = False

    params = list(model.init_net.parameters()) + list(model.trans.parameters()) + list(model.dec.parameters()) + list(model.norm.parameters())
    opt = torch.optim.AdamW(params, lr=LR_BACKBONE, weight_decay=1e-4)
    loss_fn = nn.CrossEntropyLoss()

    print("\n=== Stage 1: Backbone pretraining on fixed tasks ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_acc = 0.0

        for _ in range(steps_per_epoch):
            _, _, _, _, _, x, start_ctrl, ctrl_seq, target = make_batch(BATCH_SIZE, fixed_switch=False)

            z = model.init_state(x, start_ctrl)
            for t in range(T):
                z = model.step_update(z, x, ctrl_seq[:, t, :], t)

            logits = model.decode(z)
            loss = loss_fn(logits, target)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(params, 1.0)
            opt.step()

            total_loss += loss.item()
            total_acc += (logits.argmax(dim=-1) == target).float().mean().item()

        print(f"Backbone epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} | acc {total_acc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s")

def train_evaluator(model: MCLTRNet, epochs: int, steps_per_epoch: int):
    model.eval()
    for p in model.init_net.parameters():
        p.requires_grad = False
    for p in model.trans.parameters():
        p.requires_grad = False
    for p in model.dec.parameters():
        p.requires_grad = False
    for p in model.norm.parameters():
        p.requires_grad = False
    for p in model.eval_net.parameters():
        p.requires_grad = True
    for p in model.policy_net.parameters():
        p.requires_grad = False

    opt = torch.optim.AdamW(model.eval_net.parameters(), lr=LR_EVAL, weight_decay=1e-4)
    mse = nn.MSELoss()

    print("\n=== Stage 2: Evaluator training (predict final target probability from current latent state) ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_corr = 0.0
        total_samples = 0

        for _ in range(steps_per_epoch):
            _, _, _, _, _, x, start_ctrl, ctrl_seq, target = make_batch(BATCH_SIZE, switch_prob=0.5, fixed_switch=None)

            # Collect step-level samples along the continue-only trajectory
            z = model.init_state(x, start_ctrl)

            step_z = []
            step_x = []
            step_ctrl = []
            step_t = []
            labels = []

            for t in range(T):
                cand = model.step_update(z, x, ctrl_seq[:, t, :], t)
                # label = final target probability if we continue from cand to the end
                p_target = final_target_prob(model, cand, x, ctrl_seq, t + 1, target)
                step_z.append(cand.detach())
                step_x.append(x.detach())
                step_ctrl.append(ctrl_seq[:, t, :].detach())
                step_t.append(torch.full((BATCH_SIZE, 1), float(t) / max(1, (T - 1)), device=device))
                labels.append(p_target.detach())

                z = cand  # continue-only path

            step_z = torch.cat(step_z, dim=0)
            step_x = torch.cat(step_x, dim=0)
            step_ctrl = torch.cat(step_ctrl, dim=0)
            step_t = torch.cat(step_t, dim=0)
            labels = torch.cat(labels, dim=0).clamp(0.0, 1.0)

            pred = model.eval_score(step_z, step_x, step_ctrl, 0)  # time already encoded in x? no, use step_t explicitly below
            # Recompute with explicit step time feature through a temporary wrapper
            # (avoid changing the architecture; use the net directly here)
            inp = torch.cat([step_z, step_x, step_ctrl, step_t], dim=-1)
            pred = torch.sigmoid(model.eval_net(inp)).squeeze(-1)

            loss = mse(pred, labels)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(model.eval_net.parameters(), 1.0)
            opt.step()

            total_loss += loss.item()

            # simple calibration proxy on the minibatch
            corr = ((pred > 0.5) == (labels > 0.5)).float().mean().item()
            total_corr += corr
            total_samples += 1

        print(f"Evaluator epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} | bin-acc {total_corr/total_samples:.4f} | {time.time()-t0:.1f}s")

def train_policy(model: MCLTRNet, epochs: int, steps_per_epoch: int):
    model.eval()
    for p in model.init_net.parameters():
        p.requires_grad = False
    for p in model.trans.parameters():
        p.requires_grad = False
    for p in model.dec.parameters():
        p.requires_grad = False
    for p in model.norm.parameters():
        p.requires_grad = False
    for p in model.eval_net.parameters():
        p.requires_grad = False
    for p in model.policy_net.parameters():
        p.requires_grad = True

    opt = torch.optim.AdamW(model.policy_net.parameters(), lr=LR_POLICY, weight_decay=1e-4)
    ce = nn.CrossEntropyLoss(weight=torch.tensor([1.0, 1.3, 1.3], device=device))

    print("\n=== Stage 3: Policy training (imitate oracle action: continue / overwrite / restart) ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        counts = torch.zeros(3, device=device)

        for _ in range(steps_per_epoch):
            _, _, _, _, _, x, start_ctrl, ctrl_seq, target = make_batch(BATCH_SIZE, switch_prob=0.5, fixed_switch=None)

            z0 = model.init_state(x, start_ctrl)
            z = z0
            prev_score = torch.full((BATCH_SIZE,), 0.5, device=device)

            loss_accum = 0.0
            batch_steps = 0

            for t in range(T):
                cand = model.step_update(z, x, ctrl_seq[:, t, :], t)

                step_t = make_step_feat(t, BATCH_SIZE, device)
                eval_inp = torch.cat([cand.detach(), x.detach(), ctrl_seq[:, t, :].detach(), step_t], dim=-1)
                score = torch.sigmoid(model.eval_net(eval_inp)).squeeze(-1).detach()
                delta = (score - prev_score).detach()

                oracle_a, oracle_best_prob = oracle_action_for_state(model, cand.detach(), z0.detach(), x.detach(), ctrl_seq.detach(), t, target)

                logits = model.policy_logits(cand.detach(), score, delta, t)
                loss = ce(logits, oracle_a)

                loss_accum = loss_accum + loss
                batch_steps += 1

                # for trajectory collection during policy training, keep continue-only latent path
                z = cand.detach()
                prev_score = score

                counts += torch.stack([
                    (oracle_a == 0).sum(),
                    (oracle_a == 1).sum(),
                    (oracle_a == 2).sum()
                ]).float()

            loss_final = loss_accum / max(1, batch_steps)

            opt.zero_grad(set_to_none=True)
            loss_final.backward()
            torch.nn.utils.clip_grad_norm_(model.policy_net.parameters(), 1.0)
            opt.step()

            total_loss += loss_final.item()

        rates = (counts / (steps_per_epoch * BATCH_SIZE * T)).detach().cpu().numpy()
        print(
            f"Policy epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} | "
            f"oracle-action rates C/O/R {rates[0]:.3f}/{rates[1]:.3f}/{rates[2]:.3f} | {time.time()-t0:.1f}s"
        )

def joint_finetune(model: MCLTRNet, epochs: int, steps_per_epoch: int):
    # Keep evaluator and policy frozen; adapt backbone a bit to the controlled trajectory.
    model.train()
    for p in model.init_net.parameters():
        p.requires_grad = True
    for p in model.trans.parameters():
        p.requires_grad = True
    for p in model.dec.parameters():
        p.requires_grad = True
    for p in model.norm.parameters():
        p.requires_grad = True
    for p in model.eval_net.parameters():
        p.requires_grad = False
    for p in model.policy_net.parameters():
        p.requires_grad = False

    params = list(model.init_net.parameters()) + list(model.trans.parameters()) + list(model.dec.parameters()) + list(model.norm.parameters())
    opt = torch.optim.AdamW(params, lr=LR_FINETUNE, weight_decay=1e-4)
    ce = nn.CrossEntropyLoss()

    print("\n=== Stage 4: Light backbone fine-tuning under controlled inference ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_acc = 0.0

        for _ in range(steps_per_epoch):
            _, _, _, _, _, x, start_ctrl, ctrl_seq, target = make_batch(BATCH_SIZE, switch_prob=0.5, fixed_switch=None)

            z0 = model.init_state(x, start_ctrl)
            z = z0
            prev_score = torch.full((BATCH_SIZE,), 0.5, device=device)

            for t in range(T):
                cand = model.step_update(z, x, ctrl_seq[:, t, :], t)

                step_t = make_step_feat(t, BATCH_SIZE, device)
                eval_inp = torch.cat([cand.detach(), x.detach(), ctrl_seq[:, t, :].detach(), step_t], dim=-1)
                score = torch.sigmoid(model.eval_net(eval_inp)).squeeze(-1).detach()
                delta = (score - prev_score).detach()

                with torch.no_grad():
                    logits_pi = model.policy_logits(cand.detach(), score, delta, t)
                    action = logits_pi.argmax(dim=-1)

                z_next = cand
                overwrite_mask = action == 1
                restart_mask = action == 2
                z_next = z_next.clone()
                z_next[overwrite_mask] = project_overwrite(z_next[overwrite_mask])
                z_next[restart_mask] = z0[restart_mask]

                z = z_next
                prev_score = score

            logits = model.decode(z)
            loss = ce(logits, target)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(params, 1.0)
            opt.step()

            total_loss += loss.item()
            total_acc += (logits.argmax(dim=-1) == target).float().mean().item()

        print(f"Fine-tune epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} | acc {total_acc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s")

# -----------------------------
# Inference / evaluation
# -----------------------------
@torch.no_grad()
def run_model(model: MCLTRNet, x: torch.Tensor, start_ctrl: torch.Tensor, ctrl_seq: torch.Tensor, controlled: bool):
    z0 = model.init_state(x, start_ctrl)
    z = z0
    prev_score = torch.full((x.size(0),), 0.5, device=x.device)
    actions = []

    for t in range(T):
        cand = model.step_update(z, x, ctrl_seq[:, t, :], t)

        if controlled:
            step_t = make_step_feat(t, x.size(0), x.device)
            eval_inp = torch.cat([cand, x, ctrl_seq[:, t, :], step_t], dim=-1)
            score = torch.sigmoid(model.eval_net(eval_inp)).squeeze(-1)
            delta = score - prev_score
            logits_pi = model.policy_logits(cand, score, delta, t)
            action = logits_pi.argmax(dim=-1)
        else:
            action = torch.zeros(x.size(0), dtype=torch.long, device=x.device)

        z_next = cand.clone()
        overwrite_mask = action == 1
        restart_mask = action == 2
        z_next[overwrite_mask] = project_overwrite(z_next[overwrite_mask])
        z_next[restart_mask] = z0[restart_mask]

        actions.append(action)
        z = z_next

        if controlled:
            prev_score = score

    logits = model.decode(z)
    actions = torch.stack(actions, dim=1)  # [B, T]
    return logits, actions

@torch.no_grad()
def evaluate(model: MCLTRNet, controlled: bool, fixed_switch: bool | None, fixed_switch_step: int | None = None, batches: int = 30, bs: int = 128):
    model.eval()
    total = 0
    correct = 0
    action_counts = torch.zeros(3, device=device)
    score_correct = []
    score_incorrect = []

    for _ in range(batches):
        _, _, _, _, _, x, start_ctrl, ctrl_seq, target = make_batch(
            bs,
            switch_prob=0.5,
            fixed_switch=fixed_switch,
            fixed_switch_step=fixed_switch_step,
        )
        logits, actions = run_model(model, x, start_ctrl, ctrl_seq, controlled=controlled)
        pred = logits.argmax(dim=-1)

        correct_mask = (pred == target)
        correct += correct_mask.sum().item()
        total += target.numel()

        if controlled:
            action_counts += torch.stack([
                (actions == 0).sum(),
                (actions == 1).sum(),
                (actions == 2).sum()
            ]).float()

        # evaluator calibration proxy: average predicted score on final latent state
        z0 = model.init_state(x, start_ctrl)
        z = z0
        prev_score = torch.full((x.size(0),), 0.5, device=x.device)
        for t in range(T):
            cand = model.step_update(z, x, ctrl_seq[:, t, :], t)
            step_t = make_step_feat(t, x.size(0), x.device)
            eval_inp = torch.cat([cand, x, ctrl_seq[:, t, :], step_t], dim=-1)
            score = torch.sigmoid(model.eval_net(eval_inp)).squeeze(-1)
            delta = score - prev_score
            if controlled:
                logits_pi = model.policy_logits(cand, score, delta, t)
                action = logits_pi.argmax(dim=-1)
            else:
                action = torch.zeros(x.size(0), dtype=torch.long, device=x.device)

            z_next = cand.clone()
            overwrite_mask = action == 1
            restart_mask = action == 2
            z_next[overwrite_mask] = project_overwrite(z_next[overwrite_mask])
            z_next[restart_mask] = z0[restart_mask]
            z = z_next
            prev_score = score

        final_step_t = make_step_feat(T - 1, x.size(0), x.device)
        final_eval_inp = torch.cat([z, x, ctrl_seq[:, -1, :], final_step_t], dim=-1)
        final_score = torch.sigmoid(model.eval_net(final_eval_inp)).squeeze(-1)

        score_correct.append(final_score[correct_mask].mean().item() if correct_mask.any() else float("nan"))
        score_incorrect.append(final_score[~correct_mask].mean().item() if (~correct_mask).any() else float("nan"))

    acc = correct / total
    out = {
        "acc": acc,
        "score_correct_mean": float(torch.tensor([v for v in score_correct if not math.isnan(v)]).mean().item()) if any(not math.isnan(v) for v in score_correct) else float("nan"),
        "score_incorrect_mean": float(torch.tensor([v for v in score_incorrect if not math.isnan(v)]).mean().item()) if any(not math.isnan(v) for v in score_incorrect) else float("nan"),
    }
    if controlled:
        rates = (action_counts / (batches * bs * T)).detach().cpu().numpy()
        out["continue_rate"] = float(rates[0])
        out["overwrite_rate"] = float(rates[1])
        out["restart_rate"] = float(rates[2])
    return out

# -----------------------------
# Build / train
# -----------------------------
model = MCLTRNet().to(device)

train_backbone(model, STAGE1_EPOCHS, STEPS_PER_EPOCH)
train_evaluator(model, STAGE2_EPOCHS, STEPS_PER_EPOCH)
train_policy(model, STAGE3_EPOCHS, STEPS_PER_EPOCH)
joint_finetune(model, STAGE4_EPOCHS, STEPS_PER_EPOCH // 2)

# -----------------------------
# Final evaluation
# -----------------------------
print("\n=== Final evaluation: fixed tasks (no switch) ===")
fixed_continue = evaluate(model, controlled=False, fixed_switch=False, batches=20, bs=128)
fixed_control = evaluate(model, controlled=True, fixed_switch=False, batches=20, bs=128)
print(f"Continue-only acc: {fixed_continue['acc']:.4f}")
print(f"Controlled acc:    {fixed_control['acc']:.4f}")
print(f"Controlled action rates C/O/R: {fixed_control['continue_rate']:.3f}/{fixed_control['overwrite_rate']:.3f}/{fixed_control['restart_rate']:.3f}")

print("\n=== Final evaluation: hard switch tasks (switch at step 1) ===")
switch_continue = evaluate(model, controlled=False, fixed_switch=True, fixed_switch_step=1, batches=20, bs=128)
switch_control = evaluate(model, controlled=True, fixed_switch=True, fixed_switch_step=1, batches=20, bs=128)
print(f"Continue-only acc: {switch_continue['acc']:.4f}")
print(f"Controlled acc:    {switch_control['acc']:.4f}")
print(f"Controlled action rates C/O/R: {switch_control['continue_rate']:.3f}/{switch_control['overwrite_rate']:.3f}/{switch_control['restart_rate']:.3f}")

print("\n=== Evaluator calibration proxy ===")
print(f"Controlled / fixed   : score(correct)={fixed_control['score_correct_mean']:.4f}, score(incorrect)={fixed_control['score_incorrect_mean']:.4f}")
print(f"Controlled / switch  : score(correct)={switch_control['score_correct_mean']:.4f}, score(incorrect)={switch_control['score_incorrect_mean']:.4f}")

print("\n=== Sample predictions on hard switch tasks ===")
with torch.no_grad():
    _, _, _, _, _, x, start_ctrl, ctrl_seq, target = make_batch(8, fixed_switch=True, fixed_switch_step=1)
    logits_c, actions_c = run_model(model, x, start_ctrl, ctrl_seq, controlled=True)
    pred_c = logits_c.argmax(dim=-1)
    for i in range(8):
        a_idx = int(torch.argmax(x[i, :A_CLASSES]).item())
        b_idx = int(torch.argmax(x[i, A_CLASSES:A_CLASSES+B_CLASSES]).item())
        sm = int(torch.argmax(start_ctrl[i]).item())
        em = int(torch.argmax(ctrl_seq[i, -1]).item())
        print(
            f"[{i}] a={a_idx:2d} b={b_idx:2d} start={sm} end={em} "
            f"target={int(target[i].item()):2d} pred={int(pred_c[i].item()):2d} "
            f"actions={actions_c[i].tolist()}"
        )

print("\nDone.")

# M-CLTR v3.2 — corrected modular prototype
# Fixes the policy-training autograd issue by computing oracle labels under no_grad
# but computing policy logits with gradients enabled.
# Base knowledge provider is separate and swappable.
# M-CLTR is the reasoning layer that uses base knowledge, not a separate worker.

import copy
import math
import random
import time
from typing import Optional, List

import torch
import torch.nn as nn
import torch.nn.functional as F

# -----------------------------
# Reproducibility / device
# -----------------------------
SEED = 7
random.seed(SEED)
torch.manual_seed(SEED)
if torch.cuda.is_available():
    torch.cuda.manual_seed_all(SEED)

device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
print("Device:", device)

# -----------------------------
# Config
# -----------------------------
A_MAX = 30
B_MAX = 30
A_CLASSES = A_MAX + 1
B_CLASSES = B_MAX + 1
N_CLASSES = 61  # answer classes modulo 61

X_DIM = A_CLASSES + B_CLASSES + 2   # a, b, start_mode
K_DIM = 64                          # base knowledge vector size
Z_DIM = 96                          # latent reasoning state size

T = 6                                # latent iterations

BASE_EPOCHS = 6
REASONER_EPOCHS = 6
EVAL_EPOCHS = 4
POLICY_EPOCHS = 4
FINETUNE_EPOCHS = 1

STEPS_PER_EPOCH = 70
BATCH_SIZE = 128

LR_BASE = 2e-3
LR_REASONER = 2e-3
LR_EVAL = 2e-3
LR_POLICY = 2e-3
LR_FINETUNE = 3e-4

TRAIN_SWITCH_PROB_REASONER = 0.30
TRAIN_SWITCH_PROB_POLICY = 0.50

USE_FAILURE_MEMORY = False
MEM_CAPACITY = 6
MEM_BETA = 0.18
MEM_GAMMA = 0.35
MEM_STORE_THR = 0.35

CARRY_Z = 0.86
DELTA_W = 0.10
CTRL_W = 0.02
K_W = 0.02
OVERWRITE_BLEND = 0.65

# -----------------------------
# Helpers
# -----------------------------
def one_hot(v: torch.Tensor, n: int) -> torch.Tensor:
    return F.one_hot(v.long(), n).float()

def step_feature(t: int, batch_size: int, device: torch.device) -> torch.Tensor:
    if T <= 1:
        s = 0.0
    else:
        s = float(t) / float(T - 1)
    return torch.full((batch_size, 1), s, device=device)

def task_value(a: torch.Tensor, b: torch.Tensor, mode: torch.Tensor) -> torch.Tensor:
    addv = (a + b) % N_CLASSES
    mulv = (a * b) % N_CLASSES
    return torch.where(mode == 0, addv, mulv)

def make_batch(
    batch_size: int,
    switch_prob: float = 0.5,
    fixed_switch: Optional[bool] = None,
    fixed_switch_step: Optional[int] = None,
):
    a = torch.randint(0, A_CLASSES, (batch_size,), device=device)
    b = torch.randint(0, B_CLASSES, (batch_size,), device=device)
    start_mode = torch.randint(0, 2, (batch_size,), device=device)

    if fixed_switch is True:
        end_mode = 1 - start_mode
        switch_step = torch.full(
            (batch_size,),
            fixed_switch_step if fixed_switch_step is not None else 2,
            device=device,
            dtype=torch.long,
        )
    elif fixed_switch is False:
        end_mode = start_mode.clone()
        switch_step = torch.full((batch_size,), T, device=device, dtype=torch.long)
    else:
        do_switch = torch.rand(batch_size, device=device) < switch_prob
        end_mode = torch.where(do_switch, 1 - start_mode, start_mode)
        if T > 1:
            rand_step = torch.randint(1, T, (batch_size,), device=device)
        else:
            rand_step = torch.zeros(batch_size, device=device, dtype=torch.long)
        switch_step = torch.where(do_switch, rand_step, torch.full_like(rand_step, T))

    x = torch.cat(
        [one_hot(a, A_CLASSES), one_hot(b, B_CLASSES), one_hot(start_mode, 2)],
        dim=-1,
    )

    ctrl_seq = []
    for t in range(T):
        current_mode = torch.where(torch.full_like(switch_step, t) < switch_step, start_mode, end_mode)
        ctrl_seq.append(one_hot(current_mode, 2))
    ctrl_seq = torch.stack(ctrl_seq, dim=1)  # [B, T, 2]

    final_mode = torch.where(torch.full_like(switch_step, T - 1) < switch_step, start_mode, end_mode)
    target = task_value(a, b, final_mode)
    start_ctrl = one_hot(start_mode, 2)

    return a, b, start_mode, end_mode, switch_step, x, start_ctrl, ctrl_seq, target

# -----------------------------
# Small MLP
# -----------------------------
class MLP(nn.Module):
    def __init__(self, in_dim: int, out_dim: int, hidden: int = 128, dropout: float = 0.0):
        super().__init__()
        layers: List[nn.Module] = [
            nn.Linear(in_dim, hidden),
            nn.GELU(),
        ]
        if dropout > 0:
            layers.append(nn.Dropout(dropout))
        layers.extend([
            nn.Linear(hidden, hidden),
            nn.GELU(),
            nn.Linear(hidden, out_dim),
        ])
        self.net = nn.Sequential(*layers)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.net(x)

# -----------------------------
# Base knowledge provider
# -----------------------------
class BaseKnowledgeProvider(nn.Module):
    def __init__(self, x_dim: int = X_DIM, k_dim: int = K_DIM):
        super().__init__()
        self.net = nn.Sequential(
            nn.Linear(x_dim, 128),
            nn.GELU(),
            nn.Linear(128, k_dim),
            nn.LayerNorm(k_dim),
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.net(x)

# -----------------------------
# Direct baseline
# -----------------------------
class DirectSolver(nn.Module):
    def __init__(self, base: BaseKnowledgeProvider, k_dim: int = K_DIM, n_classes: int = N_CLASSES):
        super().__init__()
        self.base = base
        self.head = nn.Sequential(
            nn.Linear(k_dim, 128),
            nn.GELU(),
            nn.Linear(128, n_classes),
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        k0 = self.base(x)
        return self.head(k0)

# -----------------------------
# Failure memory (optional)
# -----------------------------
class FailureMemory:
    def __init__(self, capacity: int, z_dim: int, enabled: bool = False,
                 beta: float = 0.18, gamma: float = 0.35, store_thr: float = 0.35):
        self.capacity = capacity
        self.z_dim = z_dim
        self.enabled = enabled
        self.beta = beta
        self.gamma = gamma
        self.store_thr = store_thr

        self.mem = None
        self.age = None
        self.mask = None
        self.ptr = None

    def reset(self, batch_size: int, device: torch.device):
        self.mem = torch.zeros(batch_size, self.capacity, self.z_dim, device=device)
        self.age = torch.zeros(batch_size, self.capacity, device=device)
        self.mask = torch.zeros(batch_size, self.capacity, dtype=torch.bool, device=device)
        self.ptr = torch.zeros(batch_size, dtype=torch.long, device=device)

    def repel(self, z: torch.Tensor) -> torch.Tensor:
        if not self.enabled or self.mem is None:
            return torch.zeros_like(z)

        zexp = z.unsqueeze(1)  # [B, 1, D]
        diff = zexp - self.mem  # [B, K, D]
        dist = diff.norm(dim=-1, keepdim=True).clamp_min(1e-6)
        direction = diff / dist

        znorm = F.normalize(zexp.expand_as(self.mem), dim=-1)
        mnorm = F.normalize(self.mem.clamp_min(1e-6), dim=-1)
        sim = (znorm * mnorm).sum(dim=-1)  # [B, K]

        weights = self.mask.float() * torch.exp(-self.gamma * self.age.float())
        rep = (weights.unsqueeze(-1) * sim.unsqueeze(-1) * direction).sum(dim=1)
        return self.beta * rep

    def update(self, cand: torch.Tensor, score: torch.Tensor):
        if not self.enabled or self.mem is None:
            return

        self.age[self.mask] += 1.0
        low = score < self.store_thr
        idx = torch.where(low)[0]
        if idx.numel() == 0:
            return

        slots = self.ptr[idx] % self.capacity
        self.mem[idx, slots] = cand.detach()[idx]
        self.age[idx, slots] = 0.0
        self.mask[idx, slots] = True
        self.ptr[idx] = (self.ptr[idx] + 1) % self.capacity

# -----------------------------
# M-CLTR reasoning layer
# -----------------------------
class MCLTRReasoner(nn.Module):
    def __init__(
        self,
        base: BaseKnowledgeProvider,
        x_dim: int = X_DIM,
        k_dim: int = K_DIM,
        z_dim: int = Z_DIM,
        n_classes: int = N_CLASSES,
    ):
        super().__init__()
        self.base = base
        self.x_dim = x_dim
        self.k_dim = k_dim
        self.z_dim = z_dim
        self.n_classes = n_classes

        self.init_net = MLP(x_dim + k_dim, z_dim, hidden=128)
        self.trans = MLP(z_dim + x_dim + k_dim + 2 + 1, z_dim, hidden=128)
        self.decoder = nn.Linear(z_dim, n_classes)

        self.evaluator = MLP(z_dim + x_dim + k_dim + 2 + 1, 1, hidden=96)
        self.policy = MLP(z_dim + 2 + 3, 3, hidden=96)  # z + ctrl + score/delta/step

        self.z_norm = nn.LayerNorm(z_dim)
        self.k_proj = nn.Linear(k_dim, z_dim)
        self.ctrl_proj = nn.Linear(2, z_dim)

        self._init_weights()

    def _init_weights(self):
        for m in self.modules():
            if isinstance(m, nn.Linear):
                nn.init.xavier_uniform_(m.weight)
                if m.bias is not None:
                    nn.init.zeros_(m.bias)

    def knowledge(self, x: torch.Tensor) -> torch.Tensor:
        return self.base(x)

    def build_eval_input(self, z: torch.Tensor, x: torch.Tensor, k0: torch.Tensor, ctrl: torch.Tensor, t: int) -> torch.Tensor:
        st = step_feature(t, z.size(0), z.device)
        return torch.cat([z, x, k0, ctrl, st], dim=-1)

    def build_policy_input(self, z: torch.Tensor, ctrl: torch.Tensor, score: torch.Tensor, delta: torch.Tensor, t: int) -> torch.Tensor:
        st = step_feature(t, z.size(0), z.device)
        return torch.cat([z, ctrl, score.unsqueeze(-1), delta.unsqueeze(-1), st], dim=-1)

    def init_state(self, x: torch.Tensor, k0: torch.Tensor) -> torch.Tensor:
        z0 = self.init_net(torch.cat([x, k0], dim=-1))
        return self.z_norm(z0)

    def step_update(self, z: torch.Tensor, x: torch.Tensor, k0: torch.Tensor, ctrl: torch.Tensor, t: int) -> torch.Tensor:
        inp = self.build_eval_input(z, x, k0, ctrl, t)
        delta = torch.tanh(self.trans(inp))
        ctrl_shift = torch.tanh(self.ctrl_proj(ctrl))
        k_shift = torch.tanh(self.k_proj(k0))
        cand = self.z_norm(
            CARRY_Z * z
            + DELTA_W * delta
            + CTRL_W * ctrl_shift
            + K_W * k_shift
        )
        return cand

    def eval_score(self, z: torch.Tensor, x: torch.Tensor, k0: torch.Tensor, ctrl: torch.Tensor, t: int) -> torch.Tensor:
        inp = self.build_eval_input(z, x, k0, ctrl, t)
        return torch.sigmoid(self.evaluator(inp)).squeeze(-1)

    def policy_logits(self, z: torch.Tensor, ctrl: torch.Tensor, score: torch.Tensor, delta: torch.Tensor, t: int) -> torch.Tensor:
        inp = self.build_policy_input(z, ctrl, score, delta, t)
        return self.policy(inp)

    def decode(self, z: torch.Tensor) -> torch.Tensor:
        return self.decoder(z)

    def overwrite_state(self, cand: torch.Tensor, z0: torch.Tensor) -> torch.Tensor:
        return self.z_norm(OVERWRITE_BLEND * cand + (1.0 - OVERWRITE_BLEND) * z0)

    def continue_rollout_from_state(
        self,
        z_start: torch.Tensor,
        x: torch.Tensor,
        k0: torch.Tensor,
        ctrl_seq: torch.Tensor,
        start_t: int,
        use_memory: bool = False,
    ) -> torch.Tensor:
        z = z_start
        mem = FailureMemory(MEM_CAPACITY, self.z_dim, enabled=use_memory, beta=MEM_BETA, gamma=MEM_GAMMA, store_thr=MEM_STORE_THR)
        if use_memory:
            mem.reset(z.size(0), z.device)

        for t in range(start_t, T):
            cand = self.step_update(z, x, k0, ctrl_seq[:, t, :], t)
            if use_memory:
                cand = cand - mem.repel(cand)
            if use_memory:
                dummy_score = torch.zeros(cand.size(0), device=cand.device)
                mem.update(cand, dummy_score)
            z = cand
        return z

    def rollout(
        self,
        x: torch.Tensor,
        ctrl_seq: torch.Tensor,
        controlled: bool = True,
        use_memory: bool = False,
        return_trace: bool = False,
    ):
        k0 = self.knowledge(x)
        z0 = self.init_state(x, k0)
        z = z0

        mem = FailureMemory(MEM_CAPACITY, self.z_dim, enabled=use_memory, beta=MEM_BETA, gamma=MEM_GAMMA, store_thr=MEM_STORE_THR)
        if use_memory:
            mem.reset(x.size(0), x.device)

        actions = []
        scores = []
        deltas = []
        prev_score = torch.full((x.size(0),), 0.5, device=x.device)

        for t in range(T):
            cand = self.step_update(z, x, k0, ctrl_seq[:, t, :], t)
            if use_memory:
                cand = cand - mem.repel(cand)

            score = self.eval_score(cand, x, k0, ctrl_seq[:, t, :], t)
            delta = score - prev_score

            if controlled:
                logits = self.policy_logits(cand, ctrl_seq[:, t, :], score, delta, t)
                action = logits.argmax(dim=-1)
            else:
                action = torch.zeros(x.size(0), dtype=torch.long, device=x.device)

            z_next = cand.clone()
            overwrite_mask = action == 1
            restart_mask = action == 2

            if overwrite_mask.any():
                z_next[overwrite_mask] = self.overwrite_state(cand[overwrite_mask], z0[overwrite_mask])
            if restart_mask.any():
                z_next[restart_mask] = z0[restart_mask]

            if use_memory:
                mem.update(cand, score)

            actions.append(action)
            scores.append(score.detach())
            deltas.append(delta.detach())
            z = z_next
            prev_score = score.detach()

        logits = self.decode(z)
        if return_trace:
            return logits, torch.stack(actions, dim=1), torch.stack(scores, dim=1), torch.stack(deltas, dim=1), k0, z0, z
        return logits, torch.stack(actions, dim=1), k0, z0

# -----------------------------
# Oracle utilities
# -----------------------------
@torch.no_grad()
def final_target_prob_from_state(
    reasoner: MCLTRReasoner,
    z_start: torch.Tensor,
    x: torch.Tensor,
    k0: torch.Tensor,
    ctrl_seq: torch.Tensor,
    start_t: int,
    target: torch.Tensor,
) -> torch.Tensor:
    z = reasoner.continue_rollout_from_state(z_start, x, k0, ctrl_seq, start_t, use_memory=False)
    logits = reasoner.decode(z)
    probs = F.softmax(logits, dim=-1)
    return probs.gather(1, target.unsqueeze(1)).squeeze(1)

@torch.no_grad()
def oracle_action_for_state(
    reasoner: MCLTRReasoner,
    cand: torch.Tensor,
    z0: torch.Tensor,
    x: torch.Tensor,
    k0: torch.Tensor,
    ctrl_seq: torch.Tensor,
    t: int,
    target: torch.Tensor,
):
    states = [
        cand,
        reasoner.overwrite_state(cand, z0),
        z0,
    ]
    probs = []
    for s in states:
        p = final_target_prob_from_state(reasoner, s, x, k0, ctrl_seq, t + 1, target)
        probs.append(p)
    probs = torch.stack(probs, dim=-1)  # [B, 3]

    bias = torch.tensor([2e-3, 1e-3, 0.0], device=probs.device).unsqueeze(0)
    action = (probs + bias).argmax(dim=-1)
    best_prob = probs.gather(1, action.unsqueeze(1)).squeeze(1)
    return action, best_prob

# -----------------------------
# Training helpers
# -----------------------------
def set_requires_grad(module: nn.Module, flag: bool):
    for p in module.parameters():
        p.requires_grad = flag

def train_direct_base(direct_model: DirectSolver, epochs: int, steps_per_epoch: int):
    direct_model.train()
    opt = torch.optim.AdamW(direct_model.parameters(), lr=LR_BASE, weight_decay=1e-4)
    loss_fn = nn.CrossEntropyLoss()

    print("\n=== Stage 1: Base knowledge pretraining (direct solver, fixed tasks) ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_acc = 0.0

        for _ in range(steps_per_epoch):
            _, _, _, _, _, x, _, _, target = make_batch(BATCH_SIZE, fixed_switch=False)
            logits = direct_model(x)
            loss = loss_fn(logits, target)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(direct_model.parameters(), 1.0)
            opt.step()

            total_loss += loss.item()
            total_acc += (logits.argmax(dim=-1) == target).float().mean().item()

        print(f"Base epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} | acc {total_acc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s")

def train_reasoner_fixed(reasoner: MCLTRReasoner, epochs: int, steps_per_epoch: int):
    reasoner.train()
    set_requires_grad(reasoner.base, False)
    set_requires_grad(reasoner.init_net, True)
    set_requires_grad(reasoner.trans, True)
    set_requires_grad(reasoner.decoder, True)
    set_requires_grad(reasoner.evaluator, False)
    set_requires_grad(reasoner.policy, False)
    set_requires_grad(reasoner.k_proj, True)
    set_requires_grad(reasoner.ctrl_proj, True)
    set_requires_grad(reasoner.z_norm, True)

    params = list(reasoner.init_net.parameters()) + list(reasoner.trans.parameters()) + list(reasoner.decoder.parameters()) + list(reasoner.k_proj.parameters()) + list(reasoner.ctrl_proj.parameters()) + list(reasoner.z_norm.parameters())
    opt = torch.optim.AdamW(params, lr=LR_REASONER, weight_decay=1e-4)
    loss_fn = nn.CrossEntropyLoss()

    print("\n=== Stage 2: Reasoner pretraining (continue-only rollouts, mixed tasks) ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_acc = 0.0

        for _ in range(steps_per_epoch):
            _, _, _, _, _, x, _, ctrl_seq, target = make_batch(
                BATCH_SIZE, switch_prob=TRAIN_SWITCH_PROB_REASONER, fixed_switch=None
            )
            logits, _, _, _ = reasoner.rollout(x, ctrl_seq, controlled=False, use_memory=False, return_trace=False)
            loss = loss_fn(logits, target)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(params, 1.0)
            opt.step()

            total_loss += loss.item()
            total_acc += (logits.argmax(dim=-1) == target).float().mean().item()

        print(f"Reasoner epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} | acc {total_acc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s")

def train_evaluator(reasoner: MCLTRReasoner, epochs: int, steps_per_epoch: int):
    reasoner.eval()
    set_requires_grad(reasoner.base, False)
    set_requires_grad(reasoner.init_net, False)
    set_requires_grad(reasoner.trans, False)
    set_requires_grad(reasoner.decoder, False)
    set_requires_grad(reasoner.evaluator, True)
    set_requires_grad(reasoner.policy, False)
    set_requires_grad(reasoner.k_proj, False)
    set_requires_grad(reasoner.ctrl_proj, False)
    set_requires_grad(reasoner.z_norm, False)

    opt = torch.optim.AdamW(reasoner.evaluator.parameters(), lr=LR_EVAL, weight_decay=1e-4)
    mse = nn.MSELoss()

    print("\n=== Stage 3: Evaluator training (predict final correctness probability) ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_binacc = 0.0

        for _ in range(steps_per_epoch):
            _, _, _, _, _, x, _, ctrl_seq, target = make_batch(
                BATCH_SIZE, switch_prob=TRAIN_SWITCH_PROB_POLICY, fixed_switch=None
            )

            with torch.no_grad():
                k0 = reasoner.knowledge(x)
                z = reasoner.init_state(x, k0)

                step_z = []
                step_x = []
                step_k0 = []
                step_ctrl = []
                step_t = []
                labels = []

                for t in range(T):
                    cand = reasoner.step_update(z, x, k0, ctrl_seq[:, t, :], t)
                    p_target = final_target_prob_from_state(reasoner, cand, x, k0, ctrl_seq, t + 1, target)

                    step_z.append(cand.detach())
                    step_x.append(x.detach())
                    step_k0.append(k0.detach())
                    step_ctrl.append(ctrl_seq[:, t, :].detach())
                    step_t.append(step_feature(t, BATCH_SIZE, device))
                    labels.append(p_target.detach())

                    z = cand

                step_z = torch.cat(step_z, dim=0)
                step_x = torch.cat(step_x, dim=0)
                step_k0 = torch.cat(step_k0, dim=0)
                step_ctrl = torch.cat(step_ctrl, dim=0)
                step_t = torch.cat(step_t, dim=0)
                labels = torch.cat(labels, dim=0).clamp(0.0, 1.0)

            inp = torch.cat([step_z, step_x, step_k0, step_ctrl, step_t], dim=-1)
            pred = torch.sigmoid(reasoner.evaluator(inp)).squeeze(-1)

            loss = mse(pred, labels)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(reasoner.evaluator.parameters(), 1.0)
            opt.step()

            total_loss += loss.item()
            total_binacc += ((pred > 0.5) == (labels > 0.5)).float().mean().item()

        print(f"Evaluator epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} | bin-acc {total_binacc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s")

def train_policy(reasoner: MCLTRReasoner, epochs: int, steps_per_epoch: int):
    reasoner.eval()
    set_requires_grad(reasoner.base, False)
    set_requires_grad(reasoner.init_net, False)
    set_requires_grad(reasoner.trans, False)
    set_requires_grad(reasoner.decoder, False)
    set_requires_grad(reasoner.evaluator, False)
    set_requires_grad(reasoner.policy, True)
    set_requires_grad(reasoner.k_proj, False)
    set_requires_grad(reasoner.ctrl_proj, False)
    set_requires_grad(reasoner.z_norm, False)

    opt = torch.optim.AdamW(reasoner.policy.parameters(), lr=LR_POLICY, weight_decay=1e-4)
    ce = nn.CrossEntropyLoss(weight=torch.tensor([1.0, 1.15, 1.15], device=device))

    print("\n=== Stage 4: Policy training (oracle imitation: continue / overwrite / restart) ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        action_counts = torch.zeros(3, device=device)

        for _ in range(steps_per_epoch):
            _, _, _, _, _, x, _, ctrl_seq, target = make_batch(
                BATCH_SIZE, switch_prob=TRAIN_SWITCH_PROB_POLICY, fixed_switch=None
            )

            with torch.no_grad():
                k0 = reasoner.knowledge(x)
                z0 = reasoner.init_state(x, k0)
                z = z0
                prev_score = torch.full((BATCH_SIZE,), 0.5, device=x.device)

                oracle_actions_per_step = []
                cand_cache = []
                score_cache = []
                delta_cache = []

                for t in range(T):
                    cand = reasoner.step_update(z, x, k0, ctrl_seq[:, t, :], t)
                    score = reasoner.eval_score(cand, x, k0, ctrl_seq[:, t, :], t)
                    delta = score - prev_score

                    oracle_a, _ = oracle_action_for_state(reasoner, cand, z0, x, k0, ctrl_seq, t, target)

                    oracle_actions_per_step.append(oracle_a)
                    cand_cache.append(cand.detach())
                    score_cache.append(score.detach())
                    delta_cache.append(delta.detach())

                    z = cand
                    prev_score = score

                oracle_actions = torch.stack(oracle_actions_per_step, dim=1)  # [B, T]

            # IMPORTANT:
            # policy logits are computed WITH gradients, while oracle labels stay under no_grad
            batch_loss = 0.0
            for t in range(T):
                cand = cand_cache[t]
                score = score_cache[t]
                delta = delta_cache[t]
                logits = reasoner.policy_logits(cand, ctrl_seq[:, t, :], score, delta, t)
                batch_loss = batch_loss + ce(logits, oracle_actions[:, t])

                action_counts += torch.stack([
                    (oracle_actions[:, t] == 0).sum(),
                    (oracle_actions[:, t] == 1).sum(),
                    (oracle_actions[:, t] == 2).sum()
                ]).float()

            loss = batch_loss / T

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(reasoner.policy.parameters(), 1.0)
            opt.step()

            total_loss += loss.item()

        rates = (action_counts / (steps_per_epoch * BATCH_SIZE * T)).detach().cpu().numpy()
        print(
            f"Policy epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} | "
            f"oracle-action rates C/O/R {rates[0]:.3f}/{rates[1]:.3f}/{rates[2]:.3f} | {time.time()-t0:.1f}s"
        )

def finetune_reasoner(reasoner: MCLTRReasoner, epochs: int, steps_per_epoch: int):
    reasoner.train()
    set_requires_grad(reasoner.base, False)
    set_requires_grad(reasoner.init_net, True)
    set_requires_grad(reasoner.trans, True)
    set_requires_grad(reasoner.decoder, True)
    set_requires_grad(reasoner.evaluator, False)
    set_requires_grad(reasoner.policy, False)
    set_requires_grad(reasoner.k_proj, True)
    set_requires_grad(reasoner.ctrl_proj, True)
    set_requires_grad(reasoner.z_norm, True)

    params = list(reasoner.init_net.parameters()) + list(reasoner.trans.parameters()) + list(reasoner.decoder.parameters()) + list(reasoner.k_proj.parameters()) + list(reasoner.ctrl_proj.parameters()) + list(reasoner.z_norm.parameters())
    opt = torch.optim.AdamW(params, lr=LR_FINETUNE, weight_decay=1e-4)
    loss_fn = nn.CrossEntropyLoss()

    print("\n=== Stage 5: Optional light finetune under controlled inference ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_acc = 0.0

        for _ in range(steps_per_epoch):
            _, _, _, _, _, x, _, ctrl_seq, target = make_batch(
                BATCH_SIZE, switch_prob=TRAIN_SWITCH_PROB_POLICY, fixed_switch=None
            )
            logits, _, _, _ = reasoner.rollout(x, ctrl_seq, controlled=True, use_memory=USE_FAILURE_MEMORY, return_trace=False)
            loss = loss_fn(logits, target)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(params, 1.0)
            opt.step()

            total_loss += loss.item()
            total_acc += (logits.argmax(dim=-1) == target).float().mean().item()

        print(f"Finetune epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} | acc {total_acc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s")

# -----------------------------
# Evaluation
# -----------------------------
@torch.no_grad()
def evaluate_direct(direct_model: DirectSolver, batches: int, bs: int, fixed_switch: Optional[bool], fixed_switch_step: Optional[int] = None):
    direct_model.eval()
    total = 0
    correct = 0
    for _ in range(batches):
        _, _, _, _, _, x, _, _, target = make_batch(bs, switch_prob=0.5, fixed_switch=fixed_switch, fixed_switch_step=fixed_switch_step)
        logits = direct_model(x)
        pred = logits.argmax(dim=-1)
        correct += (pred == target).sum().item()
        total += target.numel()
    return correct / total

@torch.no_grad()
def evaluate_reasoner(
    reasoner: MCLTRReasoner,
    batches: int,
    bs: int,
    fixed_switch: Optional[bool],
    fixed_switch_step: Optional[int] = None,
    controlled: bool = True,
    use_memory: bool = False,
):
    reasoner.eval()
    total = 0
    correct = 0
    action_counts = torch.zeros(3, device=device)

    score_correct = []
    score_incorrect = []
    samples = []

    for _ in range(batches):
        _, _, _, _, _, x, start_ctrl, ctrl_seq, target = make_batch(
            bs, switch_prob=0.5, fixed_switch=fixed_switch, fixed_switch_step=fixed_switch_step
        )

        logits, actions, scores, deltas, k0, z0, zT = reasoner.rollout(
            x, ctrl_seq, controlled=controlled, use_memory=use_memory, return_trace=True
        )
        pred = logits.argmax(dim=-1)
        mask = pred == target

        correct += mask.sum().item()
        total += target.numel()

        if controlled:
            action_counts += torch.stack([
                (actions == 0).sum(),
                (actions == 1).sum(),
                (actions == 2).sum()
            ]).float()

        final_eval_inp = reasoner.build_eval_input(zT, x, k0, ctrl_seq[:, -1, :], T - 1)
        final_score = torch.sigmoid(reasoner.evaluator(final_eval_inp)).squeeze(-1)

        score_correct.append(final_score[mask].mean().item() if mask.any() else float("nan"))
        score_incorrect.append(final_score[~mask].mean().item() if (~mask).any() else float("nan"))

        if len(samples) < 6:
            for i in range(min(6 - len(samples), bs)):
                samples.append({
                    "a": int(torch.argmax(x[i, :A_CLASSES]).item()),
                    "b": int(torch.argmax(x[i, A_CLASSES:A_CLASSES+B_CLASSES]).item()),
                    "start_mode": int(torch.argmax(start_ctrl[i]).item()),
                    "end_mode": int(torch.argmax(ctrl_seq[i, -1]).item()),
                    "target": int(target[i].item()),
                    "pred": int(pred[i].item()),
                    "actions": actions[i].tolist(),
                })

    out = {
        "acc": correct / total,
        "score_correct_mean": float(torch.tensor([v for v in score_correct if not math.isnan(v)]).mean().item()) if any(not math.isnan(v) for v in score_correct) else float("nan"),
        "score_incorrect_mean": float(torch.tensor([v for v in score_incorrect if not math.isnan(v)]).mean().item()) if any(not math.isnan(v) for v in score_incorrect) else float("nan"),
        "samples": samples,
    }
    if controlled:
        rates = (action_counts / (batches * bs * T)).detach().cpu().numpy()
        out["continue_rate"] = float(rates[0])
        out["overwrite_rate"] = float(rates[1])
        out["restart_rate"] = float(rates[2])
    return out

# -----------------------------
# Build, train, evaluate
# -----------------------------
base = BaseKnowledgeProvider().to(device)
direct = DirectSolver(base).to(device)

train_direct_base(direct, BASE_EPOCHS, STEPS_PER_EPOCH)

base_frozen = copy.deepcopy(base).to(device)
for p in base_frozen.parameters():
    p.requires_grad = False

reasoner = MCLTRReasoner(base_frozen).to(device)

train_reasoner_fixed(reasoner, REASONER_EPOCHS, STEPS_PER_EPOCH)
train_evaluator(reasoner, EVAL_EPOCHS, STEPS_PER_EPOCH)
train_policy(reasoner, POLICY_EPOCHS, STEPS_PER_EPOCH)
finetune_reasoner(reasoner, FINETUNE_EPOCHS, STEPS_PER_EPOCH // 2)

print("\n=== Final evaluation: direct base baseline ===")
base_fixed = evaluate_direct(direct, batches=20, bs=128, fixed_switch=False)
base_switch = evaluate_direct(direct, batches=20, bs=128, fixed_switch=True, fixed_switch_step=2)
print(f"Direct baseline | fixed acc:  {base_fixed:.4f}")
print(f"Direct baseline | switch acc: {base_switch:.4f}")

print("\n=== Final evaluation: M-CLTR reasoning layer (continue-only) ===")
reasoner_fixed_free = evaluate_reasoner(reasoner, batches=20, bs=128, fixed_switch=False, controlled=False, use_memory=USE_FAILURE_MEMORY)
reasoner_switch_free = evaluate_reasoner(reasoner, batches=20, bs=128, fixed_switch=True, fixed_switch_step=2, controlled=False, use_memory=USE_FAILURE_MEMORY)
print(f"Reasoner continue-only | fixed acc:  {reasoner_fixed_free['acc']:.4f}")
print(f"Reasoner continue-only | switch acc: {reasoner_switch_free['acc']:.4f}")

print("\n=== Final evaluation: M-CLTR controlled reasoning ===")
reasoner_fixed_ctrl = evaluate_reasoner(reasoner, batches=20, bs=128, fixed_switch=False, controlled=True, use_memory=USE_FAILURE_MEMORY)
reasoner_switch_ctrl = evaluate_reasoner(reasoner, batches=20, bs=128, fixed_switch=True, fixed_switch_step=2, controlled=True, use_memory=USE_FAILURE_MEMORY)
print(f"Reasoner controlled   | fixed acc:  {reasoner_fixed_ctrl['acc']:.4f}")
print(f"Reasoner controlled   | switch acc: {reasoner_switch_ctrl['acc']:.4f}")
print(f"Controlled action rates C/O/R (fixed):  {reasoner_fixed_ctrl['continue_rate']:.3f}/{reasoner_fixed_ctrl['overwrite_rate']:.3f}/{reasoner_fixed_ctrl['restart_rate']:.3f}")
print(f"Controlled action rates C/O/R (switch): {reasoner_switch_ctrl['continue_rate']:.3f}/{reasoner_switch_ctrl['overwrite_rate']:.3f}/{reasoner_switch_ctrl['restart_rate']:.3f}")

print("\n=== Evaluator calibration proxy ===")
print(f"Fixed  | score(correct)={reasoner_fixed_ctrl['score_correct_mean']:.4f}, score(incorrect)={reasoner_fixed_ctrl['score_incorrect_mean']:.4f}")
print(f"Switch | score(correct)={reasoner_switch_ctrl['score_correct_mean']:.4f}, score(incorrect)={reasoner_switch_ctrl['score_incorrect_mean']:.4f}")

print("\n=== Sample predictions on hard switch tasks ===")
for i, s in enumerate(reasoner_switch_ctrl["samples"][:8]):
    print(
        f"[{i}] a={s['a']:2d} b={s['b']:2d} start={s['start_mode']} end={s['end_mode']} "
        f"target={s['target']:2d} pred={s['pred']:2d} actions={s['actions']}"
    )

print("\nDone.")

# M-CLTR v4 — real small data, multi-seed, multi-level sweep
# One-cell Colab prototype.
#
# What it tests:
# 1) A base knowledge provider learns digit representations from real data (sklearn digits).
# 2) A static baseline head uses only base knowledge + start mode (no online control).
# 3) M-CLTR uses the same base knowledge, but reasons through a latent trajectory.
# 4) We test multiple difficulty levels:
#       level 0 = easy / no switch
#       level 1 = medium / mid-trajectory switch
#       level 2 = hard / early switch
# 5) We sweep multiple random seeds and report mean/std.
#
# Target task:
# - The digits image is mapped to one of two binary tasks depending on the mode.
# - mode 0 -> parity (even=0, odd=1)
# - mode 1 -> low/high (0-4=0, 5-9=1)
# - The mode can switch during the latent reasoning trajectory.
# - Final answer depends on the final mode at the last step.
#
# M-CLTR should help on switch levels because it can adjust the latent state online.

import copy
import math
import random
import time
from collections import defaultdict

import numpy as np
import torch
import torch.nn as nn
import torch.nn.functional as F

from sklearn.datasets import load_digits
from sklearn.model_selection import train_test_split

# -----------------------------
# Device / reproducibility
# -----------------------------
DEVICE = torch.device("cuda" if torch.cuda.is_available() else "cpu")
print("Device:", DEVICE)

# -----------------------------
# Global config
# -----------------------------
T = 6
LATENT_DIM = 96
KNOWLEDGE_DIM = 64
NUM_CLASSES = 2

BASE_EPOCHS = 5
BASE_STEPS_PER_EPOCH = 40

DIRECT_EPOCHS = 4
DIRECT_STEPS_PER_EPOCH = 40

REASONER_EPOCHS = 5
REASONER_STEPS_PER_EPOCH = 40

EVAL_EPOCHS = 3
EVAL_STEPS_PER_EPOCH = 40

POLICY_EPOCHS = 3
POLICY_STEPS_PER_EPOCH = 40

FINETUNE_EPOCHS = 1
FINETUNE_STEPS_PER_EPOCH = 30

BATCH_SIZE = 128

LR_BASE = 2e-3
LR_DIRECT = 2e-3
LR_REASONER = 2e-3
LR_EVAL = 2e-3
LR_POLICY = 2e-3
LR_FINETUNE = 3e-4

# M-CLTR dynamics
CARRY_Z = 0.86
DELTA_W = 0.10
CTRL_W = 0.02
K_W = 0.02
OVERWRITE_BLEND = 0.65

# Optional failure memory
USE_FAILURE_MEMORY = False
MEM_CAPACITY = 6
MEM_BETA = 0.18
MEM_GAMMA = 0.35
MEM_STORE_THR = 0.35

# Levels / difficulty
LEVELS = [0, 1, 2]
LEVEL_NAMES = {
    0: "easy / no switch",
    1: "medium / mid switch",
    2: "hard / early switch",
}
LEVEL_TO_SWITCH_STEP = {
    0: T,          # no switch
    1: T // 2,     # mid switch
    2: 1,          # early switch
}

# Seeds for sweep
SEEDS = [7, 17, 27]

# -----------------------------
# Data
# -----------------------------
digits = load_digits()
X_all = torch.tensor(digits.data, dtype=torch.float32) / 16.0  # [N, 64], scaled to [0,1]
y_all = torch.tensor(digits.target, dtype=torch.long)

# Fix the split so seed sweep only changes training initialization / sampling, not dataset partition.
X_train_np, X_test_np, y_train_np, y_test_np = train_test_split(
    X_all.numpy(),
    y_all.numpy(),
    test_size=0.30,
    random_state=0,
    stratify=y_all.numpy(),
)

X_train = torch.tensor(X_train_np, dtype=torch.float32, device=DEVICE)
y_train = torch.tensor(y_train_np, dtype=torch.long, device=DEVICE)
X_test = torch.tensor(X_test_np, dtype=torch.float32, device=DEVICE)
y_test = torch.tensor(y_test_np, dtype=torch.long, device=DEVICE)

X_DIM = X_train.shape[1]

# -----------------------------
# Utilities
# -----------------------------
def set_seed(seed: int):
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    if torch.cuda.is_available():
        torch.cuda.manual_seed_all(seed)

def one_hot(v: torch.Tensor, n: int) -> torch.Tensor:
    return F.one_hot(v.long(), n).float()

def step_feature(t: int, batch_size: int, device: torch.device) -> torch.Tensor:
    if T <= 1:
        s = 0.0
    else:
        s = float(t) / float(T - 1)
    return torch.full((batch_size, 1), s, device=device)

def sample_indices(n: int, batch_size: int) -> torch.Tensor:
    return torch.randint(0, n, (batch_size,), device=DEVICE)

def make_task_targets(digit_labels: torch.Tensor, mode: torch.Tensor) -> torch.Tensor:
    # mode 0 -> parity (even=0, odd=1)
    # mode 1 -> low/high (0-4=0, 5-9=1)
    parity = (digit_labels % 2).long()
    lowhigh = (digit_labels >= 5).long()
    return torch.where(mode == 0, parity, lowhigh)

def make_control_sequence(start_mode: torch.Tensor, end_mode: torch.Tensor, switch_step: int) -> torch.Tensor:
    # ctrl_seq[t] is the current mode at step t
    ctrl_seq = []
    for t in range(T):
        current = torch.where(torch.full_like(start_mode, t) < switch_step, start_mode, end_mode)
        ctrl_seq.append(one_hot(current, 2))
    return torch.stack(ctrl_seq, dim=1)  # [B, T, 2]

def make_reasoning_batch(
    x_pool: torch.Tensor,
    y_pool: torch.Tensor,
    batch_size: int,
    level: int = None,
    random_level: bool = False,
):
    idx = sample_indices(x_pool.size(0), batch_size)
    x = x_pool[idx]
    digit_labels = y_pool[idx]

    if random_level:
        level = random.choice(LEVELS)
    elif level is None:
        level = 0

    switch_step = LEVEL_TO_SWITCH_STEP[level]

    start_mode = torch.randint(0, 2, (batch_size,), device=DEVICE)
    if level == 0:
        end_mode = start_mode.clone()
    else:
        end_mode = 1 - start_mode

    start_ctrl = one_hot(start_mode, 2)
    ctrl_seq = make_control_sequence(start_mode, end_mode, switch_step)
    final_mode = torch.where(torch.full_like(start_mode, T - 1) < switch_step, start_mode, end_mode)
    target = make_task_targets(digit_labels, final_mode)

    return x, digit_labels, start_mode, end_mode, start_ctrl, ctrl_seq, target, level

def summary_mean_std(values):
    vals = np.array(values, dtype=np.float64)
    return float(vals.mean()), float(vals.std(ddof=1)) if len(vals) > 1 else 0.0

# -----------------------------
# Modules
# -----------------------------
class MLP(nn.Module):
    def __init__(self, in_dim: int, out_dim: int, hidden: int = 128):
        super().__init__()
        self.net = nn.Sequential(
            nn.Linear(in_dim, hidden),
            nn.GELU(),
            nn.Linear(hidden, hidden),
            nn.GELU(),
            nn.Linear(hidden, out_dim),
        )

    def forward(self, x):
        return self.net(x)

class BaseKnowledgeProvider(nn.Module):
    """
    Base knowledge provider: image -> knowledge vector.
    Trained first on digit classification, then frozen.
    """
    def __init__(self, x_dim: int = X_DIM, k_dim: int = KNOWLEDGE_DIM):
        super().__init__()
        self.encoder = nn.Sequential(
            nn.Linear(x_dim, 128),
            nn.GELU(),
            nn.Linear(128, k_dim),
            nn.LayerNorm(k_dim),
        )
        self.classifier = nn.Sequential(
            nn.Linear(k_dim, 64),
            nn.GELU(),
            nn.Linear(64, 10),
        )

        for m in self.modules():
            if isinstance(m, nn.Linear):
                nn.init.xavier_uniform_(m.weight)
                if m.bias is not None:
                    nn.init.zeros_(m.bias)

    def encode(self, x: torch.Tensor) -> torch.Tensor:
        return self.encoder(x)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        k0 = self.encode(x)
        return self.classifier(k0)

class DirectStaticBaseline(nn.Module):
    """
    Static baseline head: uses base knowledge + start mode only.
    No online control, no latent trajectory.
    """
    def __init__(self, base: BaseKnowledgeProvider, k_dim: int = KNOWLEDGE_DIM):
        super().__init__()
        self.base = base
        self.head = MLP(k_dim + 2, NUM_CLASSES, hidden=96)

    def forward(self, x: torch.Tensor, start_ctrl: torch.Tensor) -> torch.Tensor:
        with torch.no_grad():
            k0 = self.base.encode(x)
        inp = torch.cat([k0, start_ctrl], dim=-1)
        return self.head(inp)

class FailureMemory:
    def __init__(self, capacity: int, z_dim: int, enabled: bool = False,
                 beta: float = 0.18, gamma: float = 0.35, store_thr: float = 0.35):
        self.capacity = capacity
        self.z_dim = z_dim
        self.enabled = enabled
        self.beta = beta
        self.gamma = gamma
        self.store_thr = store_thr
        self.mem = None
        self.age = None
        self.mask = None
        self.ptr = None

    def reset(self, batch_size: int):
        self.mem = torch.zeros(batch_size, self.capacity, self.z_dim, device=DEVICE)
        self.age = torch.zeros(batch_size, self.capacity, device=DEVICE)
        self.mask = torch.zeros(batch_size, self.capacity, dtype=torch.bool, device=DEVICE)
        self.ptr = torch.zeros(batch_size, dtype=torch.long, device=DEVICE)

    def repel(self, z: torch.Tensor) -> torch.Tensor:
        if not self.enabled or self.mem is None:
            return torch.zeros_like(z)
        zexp = z.unsqueeze(1)  # [B,1,D]
        diff = zexp - self.mem
        dist = diff.norm(dim=-1, keepdim=True).clamp_min(1e-6)
        direction = diff / dist

        znorm = F.normalize(zexp.expand_as(self.mem), dim=-1)
        mnorm = F.normalize(self.mem.clamp_min(1e-6), dim=-1)
        sim = (znorm * mnorm).sum(dim=-1)  # [B,K]

        weights = self.mask.float() * torch.exp(-self.gamma * self.age.float())
        rep = (weights.unsqueeze(-1) * sim.unsqueeze(-1) * direction).sum(dim=1)
        return self.beta * rep

    def update(self, cand: torch.Tensor, score: torch.Tensor):
        if not self.enabled or self.mem is None:
            return
        self.age[self.mask] += 1.0
        low = score < self.store_thr
        idx = torch.where(low)[0]
        if idx.numel() == 0:
            return
        slots = self.ptr[idx] % self.capacity
        self.mem[idx, slots] = cand.detach()[idx]
        self.age[idx, slots] = 0.0
        self.mask[idx, slots] = True
        self.ptr[idx] = (self.ptr[idx] + 1) % self.capacity

class MCLTRReasoner(nn.Module):
    """
    M-CLTR reasoning layer.
    Base model supplies knowledge; this module performs the reasoning trajectory.
    """
    def __init__(self, base: BaseKnowledgeProvider, x_dim: int = X_DIM, k_dim: int = KNOWLEDGE_DIM, z_dim: int = LATENT_DIM):
        super().__init__()
        self.base = base
        self.x_dim = x_dim
        self.k_dim = k_dim
        self.z_dim = z_dim

        self.init_net = MLP(x_dim + k_dim + 2, z_dim, hidden=128)
        self.trans = MLP(z_dim + x_dim + k_dim + 2 + 1, z_dim, hidden=128)
        self.decoder = nn.Linear(z_dim, NUM_CLASSES)

        self.evaluator = MLP(z_dim + x_dim + k_dim + 2 + 1, 1, hidden=96)
        self.policy = MLP(z_dim + 2 + 3, 3, hidden=96)  # latent + ctrl + score/delta/step

        self.z_norm = nn.LayerNorm(z_dim)
        self.k_proj = nn.Linear(k_dim, z_dim)
        self.ctrl_proj = nn.Linear(2, z_dim)

        for m in self.modules():
            if isinstance(m, nn.Linear):
                nn.init.xavier_uniform_(m.weight)
                if m.bias is not None:
                    nn.init.zeros_(m.bias)

    def build_eval_input(self, z, x, k0, ctrl, t: int):
        return torch.cat([z, x, k0, ctrl, step_feature(t, z.size(0), z.device)], dim=-1)

    def build_policy_input(self, z, ctrl, score, delta, t: int):
        return torch.cat([z, ctrl, score.unsqueeze(-1), delta.unsqueeze(-1), step_feature(t, z.size(0), z.device)], dim=-1)

    def knowledge(self, x):
        return self.base.encode(x)

    def init_state(self, x, k0, start_ctrl):
        z0 = self.init_net(torch.cat([x, k0, start_ctrl], dim=-1))
        return self.z_norm(z0)

    def step_update(self, z, x, k0, ctrl, t: int):
        inp = self.build_eval_input(z, x, k0, ctrl, t)
        delta = torch.tanh(self.trans(inp))
        ctrl_shift = torch.tanh(self.ctrl_proj(ctrl))
        k_shift = torch.tanh(self.k_proj(k0))
        cand = self.z_norm(
            CARRY_Z * z
            + DELTA_W * delta
            + CTRL_W * ctrl_shift
            + K_W * k_shift
        )
        return cand

    def eval_score(self, z, x, k0, ctrl, t: int):
        inp = self.build_eval_input(z, x, k0, ctrl, t)
        return torch.sigmoid(self.evaluator(inp)).squeeze(-1)

    def policy_logits(self, z, ctrl, score, delta, t: int):
        inp = self.build_policy_input(z, ctrl, score, delta, t)
        return self.policy(inp)

    def decode(self, z):
        return self.decoder(z)

    def overwrite_state(self, cand, z0):
        return self.z_norm(OVERWRITE_BLEND * cand + (1.0 - OVERWRITE_BLEND) * z0)

    def continue_rollout_from_state(self, z_start, x, k0, start_ctrl, ctrl_seq, start_t: int, use_memory: bool = False):
        z = z_start
        mem = FailureMemory(MEM_CAPACITY, self.z_dim, enabled=use_memory)
        if use_memory:
            mem.reset(z.size(0))
        for t in range(start_t, T):
            cand = self.step_update(z, x, k0, ctrl_seq[:, t, :], t)
            if use_memory:
                cand = cand - mem.repel(cand)
                mem.update(cand, torch.zeros(cand.size(0), device=cand.device))
            z = cand
        return z

    def rollout(self, x, start_ctrl, ctrl_seq, controlled: bool = True, use_memory: bool = False, return_trace: bool = False):
        k0 = self.knowledge(x)
        z0 = self.init_state(x, k0, start_ctrl)
        z = z0

        mem = FailureMemory(MEM_CAPACITY, self.z_dim, enabled=use_memory)
        if use_memory:
            mem.reset(x.size(0))

        actions = []
        scores = []
        deltas = []
        prev_score = torch.full((x.size(0),), 0.5, device=x.device)

        for t in range(T):
            cand = self.step_update(z, x, k0, ctrl_seq[:, t, :], t)
            if use_memory:
                cand = cand - mem.repel(cand)

            score = self.eval_score(cand, x, k0, ctrl_seq[:, t, :], t)
            delta = score - prev_score

            if controlled:
                logits = self.policy_logits(cand, ctrl_seq[:, t, :], score, delta, t)
                action = logits.argmax(dim=-1)
            else:
                action = torch.zeros(x.size(0), dtype=torch.long, device=x.device)

            z_next = cand.clone()
            overwrite_mask = action == 1
            restart_mask = action == 2

            if overwrite_mask.any():
                z_next[overwrite_mask] = self.overwrite_state(cand[overwrite_mask], z0[overwrite_mask])
            if restart_mask.any():
                z_next[restart_mask] = z0[restart_mask]

            if use_memory:
                mem.update(cand, score)

            actions.append(action)
            scores.append(score.detach())
            deltas.append(delta.detach())

            z = z_next
            prev_score = score.detach()

        logits = self.decode(z)
        if return_trace:
            return logits, torch.stack(actions, dim=1), torch.stack(scores, dim=1), torch.stack(deltas, dim=1), k0, z0, z
        return logits, torch.stack(actions, dim=1), k0, z0

# -----------------------------
# Oracle utilities
# -----------------------------
@torch.no_grad()
def final_target_prob_from_state(reasoner: MCLTRReasoner, z_start, x, k0, start_ctrl, ctrl_seq, start_t: int, target):
    z = reasoner.continue_rollout_from_state(z_start, x, k0, start_ctrl, ctrl_seq, start_t, use_memory=False)
    logits = reasoner.decode(z)
    probs = F.softmax(logits, dim=-1)
    return probs.gather(1, target.unsqueeze(1)).squeeze(1)

@torch.no_grad()
def oracle_action_for_state(reasoner: MCLTRReasoner, cand, z0, x, k0, start_ctrl, ctrl_seq, t: int, target):
    states = [
        cand,
        reasoner.overwrite_state(cand, z0),
        z0,
    ]
    probs = []
    for s in states:
        p = final_target_prob_from_state(reasoner, s, x, k0, start_ctrl, ctrl_seq, t + 1, target)
        probs.append(p)
    probs = torch.stack(probs, dim=-1)  # [B,3]
    bias = torch.tensor([2e-3, 1e-3, 0.0], device=probs.device).unsqueeze(0)
    action = (probs + bias).argmax(dim=-1)
    return action, probs.gather(1, action.unsqueeze(1)).squeeze(1)

# -----------------------------
# Training functions
# -----------------------------
def set_requires_grad(module: nn.Module, flag: bool):
    for p in module.parameters():
        p.requires_grad = flag

def train_base(base: BaseKnowledgeProvider, epochs: int, steps_per_epoch: int):
    base.train()
    opt = torch.optim.AdamW(base.parameters(), lr=LR_BASE, weight_decay=1e-4)
    loss_fn = nn.CrossEntropyLoss()

    print("\n=== Stage 1: base knowledge pretraining (digit classification) ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_acc = 0.0
        for _ in range(steps_per_epoch):
            idx = sample_indices(X_train.size(0), BATCH_SIZE)
            xb = X_train[idx]
            yb = y_train[idx]

            logits = base(xb)
            loss = loss_fn(logits, yb)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(base.parameters(), 1.0)
            opt.step()

            total_loss += loss.item()
            total_acc += (logits.argmax(dim=-1) == yb).float().mean().item()

        print(f"Base epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} | acc {total_acc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s")

def train_direct_head(direct_head: DirectStaticBaseline, epochs: int, steps_per_epoch: int):
    direct_head.train()
    set_requires_grad(direct_head.base, False)  # frozen base
    opt = torch.optim.AdamW(direct_head.head.parameters(), lr=LR_DIRECT, weight_decay=1e-4)
    loss_fn = nn.CrossEntropyLoss()

    print("\n=== Stage 2: direct static baseline head (no online control) ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_acc = 0.0
        for _ in range(steps_per_epoch):
            x, digit_labels, start_mode, _, start_ctrl, _, target, _ = make_reasoning_batch(
                X_train, y_train, BATCH_SIZE, random_level=True
            )
            logits = direct_head(x, start_ctrl)
            loss = loss_fn(logits, target)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(direct_head.head.parameters(), 1.0)
            opt.step()

            total_loss += loss.item()
            total_acc += (logits.argmax(dim=-1) == target).float().mean().item()

        print(f"Direct epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} | acc {total_acc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s")

def train_reasoner_continue(reasoner: MCLTRReasoner, epochs: int, steps_per_epoch: int):
    reasoner.train()
    set_requires_grad(reasoner.base, False)
    set_requires_grad(reasoner.init_net, True)
    set_requires_grad(reasoner.trans, True)
    set_requires_grad(reasoner.decoder, True)
    set_requires_grad(reasoner.evaluator, False)
    set_requires_grad(reasoner.policy, False)
    set_requires_grad(reasoner.k_proj, True)
    set_requires_grad(reasoner.ctrl_proj, True)
    set_requires_grad(reasoner.z_norm, True)

    params = list(reasoner.init_net.parameters()) + list(reasoner.trans.parameters()) + list(reasoner.decoder.parameters()) + list(reasoner.k_proj.parameters()) + list(reasoner.ctrl_proj.parameters()) + list(reasoner.z_norm.parameters())
    opt = torch.optim.AdamW(params, lr=LR_REASONER, weight_decay=1e-4)
    loss_fn = nn.CrossEntropyLoss()

    print("\n=== Stage 3: reasoner pretraining (continue-only rollouts, mixed levels) ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_acc = 0.0
        for _ in range(steps_per_epoch):
            x, digit_labels, start_mode, _, start_ctrl, ctrl_seq, target, level = make_reasoning_batch(
                X_train, y_train, BATCH_SIZE, random_level=True
            )
            logits, _, _, _ = reasoner.rollout(x, start_ctrl, ctrl_seq, controlled=False, use_memory=False, return_trace=False)
            loss = loss_fn(logits, target)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(params, 1.0)
            opt.step()

            total_loss += loss.item()
            total_acc += (logits.argmax(dim=-1) == target).float().mean().item()

        print(f"Reasoner epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} | acc {total_acc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s")

def train_evaluator(reasoner: MCLTRReasoner, epochs: int, steps_per_epoch: int):
    reasoner.eval()
    set_requires_grad(reasoner.base, False)
    set_requires_grad(reasoner.init_net, False)
    set_requires_grad(reasoner.trans, False)
    set_requires_grad(reasoner.decoder, False)
    set_requires_grad(reasoner.evaluator, True)
    set_requires_grad(reasoner.policy, False)
    set_requires_grad(reasoner.k_proj, False)
    set_requires_grad(reasoner.ctrl_proj, False)
    set_requires_grad(reasoner.z_norm, False)

    opt = torch.optim.AdamW(reasoner.evaluator.parameters(), lr=LR_EVAL, weight_decay=1e-4)
    mse = nn.MSELoss()

    print("\n=== Stage 4: evaluator training (predict final correctness probability) ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_binacc = 0.0

        for _ in range(steps_per_epoch):
            x, digit_labels, start_mode, _, start_ctrl, ctrl_seq, target, level = make_reasoning_batch(
                X_train, y_train, BATCH_SIZE, random_level=True
            )

            with torch.no_grad():
                k0 = reasoner.knowledge(x)
                z = reasoner.init_state(x, k0, start_ctrl)

                step_z = []
                step_x = []
                step_k0 = []
                step_ctrl = []
                step_t = []
                labels = []

                for t in range(T):
                    cand = reasoner.step_update(z, x, k0, ctrl_seq[:, t, :], t)
                    p_target = final_target_prob_from_state(reasoner, cand, x, k0, start_ctrl, ctrl_seq, t + 1, target)

                    step_z.append(cand.detach())
                    step_x.append(x.detach())
                    step_k0.append(k0.detach())
                    step_ctrl.append(ctrl_seq[:, t, :].detach())
                    step_t.append(step_feature(t, BATCH_SIZE, DEVICE))
                    labels.append(p_target.detach())

                    z = cand

                step_z = torch.cat(step_z, dim=0)
                step_x = torch.cat(step_x, dim=0)
                step_k0 = torch.cat(step_k0, dim=0)
                step_ctrl = torch.cat(step_ctrl, dim=0)
                step_t = torch.cat(step_t, dim=0)
                labels = torch.cat(labels, dim=0).clamp(0.0, 1.0)

            inp = torch.cat([step_z, step_x, step_k0, step_ctrl, step_t], dim=-1)
            pred = torch.sigmoid(reasoner.evaluator(inp)).squeeze(-1)

            loss = mse(pred, labels)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(reasoner.evaluator.parameters(), 1.0)
            opt.step()

            total_loss += loss.item()
            total_binacc += ((pred > 0.5) == (labels > 0.5)).float().mean().item()

        print(f"Evaluator epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} | bin-acc {total_binacc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s")

def train_policy(reasoner: MCLTRReasoner, epochs: int, steps_per_epoch: int):
    reasoner.eval()
    set_requires_grad(reasoner.base, False)
    set_requires_grad(reasoner.init_net, False)
    set_requires_grad(reasoner.trans, False)
    set_requires_grad(reasoner.decoder, False)
    set_requires_grad(reasoner.evaluator, False)
    set_requires_grad(reasoner.policy, True)
    set_requires_grad(reasoner.k_proj, False)
    set_requires_grad(reasoner.ctrl_proj, False)
    set_requires_grad(reasoner.z_norm, False)

    opt = torch.optim.AdamW(reasoner.policy.parameters(), lr=LR_POLICY, weight_decay=1e-4)
    ce = nn.CrossEntropyLoss(weight=torch.tensor([1.0, 1.15, 1.15], device=DEVICE))

    print("\n=== Stage 5: policy training (oracle imitation: continue / overwrite / restart) ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        action_counts = torch.zeros(3, device=DEVICE)

        for _ in range(steps_per_epoch):
            x, digit_labels, start_mode, _, start_ctrl, ctrl_seq, target, level = make_reasoning_batch(
                X_train, y_train, BATCH_SIZE, random_level=True
            )

            with torch.no_grad():
                k0 = reasoner.knowledge(x)
                z0 = reasoner.init_state(x, k0, start_ctrl)
                z = z0
                prev_score = torch.full((BATCH_SIZE,), 0.5, device=DEVICE)

                oracle_actions_steps = []
                cand_cache = []
                score_cache = []
                delta_cache = []

                for t in range(T):
                    cand = reasoner.step_update(z, x, k0, ctrl_seq[:, t, :], t)
                    score = reasoner.eval_score(cand, x, k0, ctrl_seq[:, t, :], t)
                    delta = score - prev_score

                    oracle_a, _ = oracle_action_for_state(reasoner, cand, z0, x, k0, start_ctrl, ctrl_seq, t, target)
                    oracle_actions_steps.append(oracle_a)
                    cand_cache.append(cand.detach())
                    score_cache.append(score.detach())
                    delta_cache.append(delta.detach())

                    z = cand
                    prev_score = score

                oracle_actions = torch.stack(oracle_actions_steps, dim=1)  # [B,T]

            batch_loss = 0.0
            for t in range(T):
                cand = cand_cache[t]
                score = score_cache[t]
                delta = delta_cache[t]
                logits = reasoner.policy_logits(cand, ctrl_seq[:, t, :], score, delta, t)
                batch_loss = batch_loss + ce(logits, oracle_actions[:, t])

                action_counts += torch.stack([
                    (oracle_actions[:, t] == 0).sum(),
                    (oracle_actions[:, t] == 1).sum(),
                    (oracle_actions[:, t] == 2).sum()
                ]).float()

            loss = batch_loss / T

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(reasoner.policy.parameters(), 1.0)
            opt.step()

            total_loss += loss.item()

        rates = (action_counts / (steps_per_epoch * BATCH_SIZE * T)).detach().cpu().numpy()
        print(
            f"Policy epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} | "
            f"oracle-action rates C/O/R {rates[0]:.3f}/{rates[1]:.3f}/{rates[2]:.3f} | {time.time()-t0:.1f}s"
        )

def finetune_reasoner(reasoner: MCLTRReasoner, epochs: int, steps_per_epoch: int):
    reasoner.train()
    set_requires_grad(reasoner.base, False)
    set_requires_grad(reasoner.init_net, True)
    set_requires_grad(reasoner.trans, True)
    set_requires_grad(reasoner.decoder, True)
    set_requires_grad(reasoner.evaluator, False)
    set_requires_grad(reasoner.policy, False)
    set_requires_grad(reasoner.k_proj, True)
    set_requires_grad(reasoner.ctrl_proj, True)
    set_requires_grad(reasoner.z_norm, True)

    params = list(reasoner.init_net.parameters()) + list(reasoner.trans.parameters()) + list(reasoner.decoder.parameters()) + list(reasoner.k_proj.parameters()) + list(reasoner.ctrl_proj.parameters()) + list(reasoner.z_norm.parameters())
    opt = torch.optim.AdamW(params, lr=LR_FINETUNE, weight_decay=1e-4)
    loss_fn = nn.CrossEntropyLoss()

    print("\n=== Stage 6: optional light finetune under controlled inference ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_acc = 0.0

        for _ in range(steps_per_epoch):
            x, digit_labels, start_mode, _, start_ctrl, ctrl_seq, target, level = make_reasoning_batch(
                X_train, y_train, BATCH_SIZE, random_level=True
            )
            logits, _, _, _ = reasoner.rollout(x, start_ctrl, ctrl_seq, controlled=True, use_memory=USE_FAILURE_MEMORY, return_trace=False)
            loss = loss_fn(logits, target)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(params, 1.0)
            opt.step()

            total_loss += loss.item()
            total_acc += (logits.argmax(dim=-1) == target).float().mean().item()

        print(f"Finetune epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} | acc {total_acc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s")

# -----------------------------
# Evaluation
# -----------------------------
@torch.no_grad()
def eval_base_digits(base: BaseKnowledgeProvider, x_pool: torch.Tensor, y_pool: torch.Tensor, batches: int = 20, bs: int = 256):
    base.eval()
    total = 0
    correct = 0
    for _ in range(batches):
        idx = sample_indices(x_pool.size(0), bs)
        xb = x_pool[idx]
        yb = y_pool[idx]
        logits = base(xb)
        pred = logits.argmax(dim=-1)
        correct += (pred == yb).sum().item()
        total += yb.numel()
    return correct / total

@torch.no_grad()
def eval_direct(direct_head: DirectStaticBaseline, x_pool: torch.Tensor, y_pool: torch.Tensor, level: int, batches: int = 20, bs: int = 256):
    direct_head.eval()
    total = 0
    correct = 0
    for _ in range(batches):
        x, digit_labels, start_mode, end_mode, start_ctrl, ctrl_seq, target, lv = make_reasoning_batch(
            x_pool, y_pool, bs, level=level, random_level=False
        )
        logits = direct_head(x, start_ctrl)
        pred = logits.argmax(dim=-1)
        correct += (pred == target).sum().item()
        total += target.numel()
    return correct / total

@torch.no_grad()
def eval_reasoner(reasoner: MCLTRReasoner, x_pool: torch.Tensor, y_pool: torch.Tensor, level: int, controlled: bool, batches: int = 20, bs: int = 256):
    reasoner.eval()
    total = 0
    correct = 0
    action_counts = torch.zeros(3, device=DEVICE)
    score_correct = []
    score_incorrect = []
    samples = []

    for _ in range(batches):
        x, digit_labels, start_mode, end_mode, start_ctrl, ctrl_seq, target, lv = make_reasoning_batch(
            x_pool, y_pool, bs, level=level, random_level=False
        )
        logits, actions, scores, deltas, k0, z0, zT = reasoner.rollout(
            x, start_ctrl, ctrl_seq, controlled=controlled, use_memory=USE_FAILURE_MEMORY, return_trace=True
        )
        pred = logits.argmax(dim=-1)
        mask = pred == target

        correct += mask.sum().item()
        total += target.numel()

        if controlled:
            action_counts += torch.stack([
                (actions == 0).sum(),
                (actions == 1).sum(),
                (actions == 2).sum()
            ]).float()

        final_eval_inp = reasoner.build_eval_input(zT, x, k0, ctrl_seq[:, -1, :], T - 1)
        final_score = torch.sigmoid(reasoner.evaluator(final_eval_inp)).squeeze(-1)

        score_correct.append(final_score[mask].mean().item() if mask.any() else float("nan"))
        score_incorrect.append(final_score[~mask].mean().item() if (~mask).any() else float("nan"))

        if len(samples) < 6:
            for i in range(min(6 - len(samples), bs)):
                samples.append({
                    "digit": int(digit_labels[i].item()),
                    "start_mode": int(start_mode[i].item()),
                    "end_mode": int(end_mode[i].item()),
                    "target": int(target[i].item()),
                    "pred": int(pred[i].item()),
                    "actions": actions[i].tolist(),
                })

    out = {
        "acc": correct / total,
        "score_correct_mean": float(np.nanmean(score_correct)),
        "score_incorrect_mean": float(np.nanmean(score_incorrect)),
        "samples": samples,
    }
    if controlled:
        rates = (action_counts / (batches * bs * T)).detach().cpu().numpy()
        out["continue_rate"] = float(rates[0])
        out["overwrite_rate"] = float(rates[1])
        out["restart_rate"] = float(rates[2])
    return out

# -----------------------------
# One-seed experiment
# -----------------------------
def run_one_seed(seed: int):
    set_seed(seed)
    print(f"\n\n##############################")
    print(f"Seed = {seed}")
    print(f"##############################")

    # Fresh models per seed
    base = BaseKnowledgeProvider().to(DEVICE)
    direct_head = DirectStaticBaseline(base).to(DEVICE)

    # Stage 1: train base knowledge provider on digit classification
    train_base(base, BASE_EPOCHS, BASE_STEPS_PER_EPOCH)

    # Freeze a copy of the trained base for the reasoning stack
    frozen_base = copy.deepcopy(base).to(DEVICE)
    for p in frozen_base.parameters():
        p.requires_grad = False

    # Stage 2: train direct static baseline
    direct_head.base = frozen_base
    train_direct_head(direct_head, DIRECT_EPOCHS, DIRECT_STEPS_PER_EPOCH)

    # Stage 3-6: train M-CLTR
    reasoner = MCLTRReasoner(frozen_base).to(DEVICE)
    train_reasoner_continue(reasoner, REASONER_EPOCHS, REASONER_STEPS_PER_EPOCH)
    train_evaluator(reasoner, EVAL_EPOCHS, EVAL_STEPS_PER_EPOCH)
    train_policy(reasoner, POLICY_EPOCHS, POLICY_STEPS_PER_EPOCH)
    finetune_reasoner(reasoner, FINETUNE_EPOCHS, FINETUNE_STEPS_PER_EPOCH)

    # Evaluation on levels
    per_level = {}
    for level in LEVELS:
        direct_acc = eval_direct(direct_head, X_test, y_test, level=level, batches=20, bs=256)
        reasoner_free = eval_reasoner(reasoner, X_test, y_test, level=level, controlled=False, batches=20, bs=256)
        reasoner_ctrl = eval_reasoner(reasoner, X_test, y_test, level=level, controlled=True, batches=20, bs=256)

        per_level[level] = {
            "direct_acc": direct_acc,
            "reasoner_continue_acc": reasoner_free["acc"],
            "reasoner_control_acc": reasoner_ctrl["acc"],
            "continue_rate": reasoner_ctrl.get("continue_rate", float("nan")),
            "overwrite_rate": reasoner_ctrl.get("overwrite_rate", float("nan")),
            "restart_rate": reasoner_ctrl.get("restart_rate", float("nan")),
            "score_correct": reasoner_ctrl["score_correct_mean"],
            "score_incorrect": reasoner_ctrl["score_incorrect_mean"],
            "samples": reasoner_ctrl["samples"],
        }

    # Print seed summary
    print("\n--- Seed summary ---")
    for level in LEVELS:
        r = per_level[level]
        print(
            f"Level {level} ({LEVEL_NAMES[level]}): "
            f"direct={r['direct_acc']:.4f} | "
            f"reasoner-continue={r['reasoner_continue_acc']:.4f} | "
            f"reasoner-controlled={r['reasoner_control_acc']:.4f} | "
            f"C/O/R={r['continue_rate']:.3f}/{r['overwrite_rate']:.3f}/{r['restart_rate']:.3f}"
        )

    print("\nSample predictions on hardest level:")
    for i, s in enumerate(per_level[2]["samples"][:6]):
        print(
            f"[{i}] digit={s['digit']} start={s['start_mode']} end={s['end_mode']} "
            f"target={s['target']} pred={s['pred']} actions={s['actions']}"
        )

    return per_level

# -----------------------------
# Run sweep
# -----------------------------
all_results = {}
for seed in SEEDS:
    all_results[seed] = run_one_seed(seed)

# -----------------------------
# Aggregate results
# -----------------------------
print("\n\n==============================")
print("Aggregated results across seeds")
print("==============================")

for level in LEVELS:
    direct_vals = []
    free_vals = []
    ctrl_vals = []
    c_rates = []
    o_rates = []
    r_rates = []

    for seed in SEEDS:
        rr = all_results[seed][level]
        direct_vals.append(rr["direct_acc"])
        free_vals.append(rr["reasoner_continue_acc"])
        ctrl_vals.append(rr["reasoner_control_acc"])
        c_rates.append(rr["continue_rate"])
        o_rates.append(rr["overwrite_rate"])
        r_rates.append(rr["restart_rate"])

    dm, ds = summary_mean_std(direct_vals)
    fm, fs = summary_mean_std(free_vals)
    cm, cs = summary_mean_std(ctrl_vals)
    cr_m, cr_s = summary_mean_std(c_rates)
    ow_m, ow_s = summary_mean_std(o_rates)
    rs_m, rs_s = summary_mean_std(r_rates)

    print(f"\nLevel {level} ({LEVEL_NAMES[level]})")
    print(f"  Direct baseline        : {dm:.4f} ± {ds:.4f}")
    print(f"  M-CLTR continue-only   : {fm:.4f} ± {fs:.4f}")
    print(f"  M-CLTR controlled      : {cm:.4f} ± {cs:.4f}")
    print(f"  Action rates C/O/R     : {cr_m:.3f} ± {cr_s:.3f} / {ow_m:.3f} ± {ow_s:.3f} / {rs_m:.3f} ± {rs_s:.3f}")

print("\nDone.")

# M-CLTR v4.1 — action probe on real data
# Goal:
#   - keep the base model separate
#   - keep M-CLTR as the reasoning layer
#   - directly measure whether continue / overwrite / restart is actually useful
#   - show step-wise action values and why overwrite is or is not chosen
#
# This version does NOT train a policy head.
# Instead, it measures:
#   1) continue-only rollout accuracy
#   2) forced overwrite rollout accuracy
#   3) forced restart rollout accuracy
#   4) step-wise oracle rollout accuracy
#   5) per-step action win rates (continue vs overwrite vs restart)
#
# That makes it easier to see what is happening inside the reasoning layer.

import copy
import math
import random
import time
from typing import Optional, List, Dict

import numpy as np
import torch
import torch.nn as nn
import torch.nn.functional as F

from sklearn.datasets import load_digits
from sklearn.model_selection import train_test_split

# -----------------------------
# Device / reproducibility
# -----------------------------
DEVICE = torch.device("cuda" if torch.cuda.is_available() else "cpu")
print("Device:", DEVICE)

# -----------------------------
# Config
# -----------------------------
T = 6
LATENT_DIM = 96
KNOWLEDGE_DIM = 64
NUM_CLASSES = 2

BASE_EPOCHS = 4
DIRECT_EPOCHS = 3
REASONER_EPOCHS = 4
EVAL_EPOCHS = 2

BASE_STEPS_PER_EPOCH = 35
DIRECT_STEPS_PER_EPOCH = 35
REASONER_STEPS_PER_EPOCH = 35
EVAL_STEPS_PER_EPOCH = 35

BATCH_SIZE = 96

LR_BASE = 2e-3
LR_DIRECT = 2e-3
LR_REASONER = 2e-3
LR_EVAL = 2e-3

# Latent dynamics
CARRY_Z = 0.86
DELTA_W = 0.10
CTRL_W = 0.02
K_W = 0.02
OVERWRITE_BLEND = 0.65

# Optional failure memory, off by default for the cleanest diagnostic
USE_FAILURE_MEMORY = False
MEM_CAPACITY = 6
MEM_BETA = 0.18
MEM_GAMMA = 0.35
MEM_STORE_THR = 0.35

# Levels:
# 0 = easy / no switch
# 1 = medium / mid switch
# 2 = hard / early switch
# 3 = switch + noisy input
LEVELS = [0, 1, 2, 3]
LEVEL_NAMES = {
    0: "easy / no switch",
    1: "medium / mid switch",
    2: "hard / early switch",
    3: "switch + noisy input",
}
LEVEL_TO_SWITCH_STEP = {
    0: T,
    1: T // 2,
    2: 1,
    3: T // 2,
}
NOISE_SIGMA_LEVEL3 = 0.25

# Multiple seeds, but still CPU-friendly
SEEDS = [7, 17]

# -----------------------------
# Data
# -----------------------------
digits = load_digits()
X_all = torch.tensor(digits.data, dtype=torch.float32) / 16.0
y_all = torch.tensor(digits.target, dtype=torch.long)

# Fixed split for comparability across seeds
X_train_np, X_test_np, y_train_np, y_test_np = train_test_split(
    X_all.numpy(),
    y_all.numpy(),
    test_size=0.30,
    random_state=0,
    stratify=y_all.numpy(),
)

X_train = torch.tensor(X_train_np, dtype=torch.float32, device=DEVICE)
y_train = torch.tensor(y_train_np, dtype=torch.long, device=DEVICE)
X_test = torch.tensor(X_test_np, dtype=torch.float32, device=DEVICE)
y_test = torch.tensor(y_test_np, dtype=torch.long, device=DEVICE)

X_DIM = X_train.shape[1]

# -----------------------------
# Helpers
# -----------------------------
def set_seed(seed: int):
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    if torch.cuda.is_available():
        torch.cuda.manual_seed_all(seed)

def one_hot(v: torch.Tensor, n: int) -> torch.Tensor:
    return F.one_hot(v.long(), n).float()

def step_feature(t: int, batch_size: int, device: torch.device) -> torch.Tensor:
    if T <= 1:
        s = 0.0
    else:
        s = float(t) / float(T - 1)
    return torch.full((batch_size, 1), s, device=device)

def task_value(digit_labels: torch.Tensor, mode: torch.Tensor) -> torch.Tensor:
    # mode 0 -> parity (even=0, odd=1)
    # mode 1 -> low/high (0-4=0, 5-9=1)
    parity = (digit_labels % 2).long()
    lowhigh = (digit_labels >= 5).long()
    return torch.where(mode == 0, parity, lowhigh)

def sample_indices(n: int, batch_size: int) -> torch.Tensor:
    return torch.randint(0, n, (batch_size,), device=DEVICE)

def make_reasoning_batch(
    x_pool: torch.Tensor,
    y_pool: torch.Tensor,
    batch_size: int,
    level: int = 0,
):
    idx = sample_indices(x_pool.size(0), batch_size)
    x = x_pool[idx].clone()
    digit_labels = y_pool[idx]

    if level == 3:
        noise = NOISE_SIGMA_LEVEL3 * torch.randn_like(x)
        x = torch.clamp(x + noise, 0.0, 1.0)

    start_mode = torch.randint(0, 2, (batch_size,), device=DEVICE)
    switch_step = LEVEL_TO_SWITCH_STEP[level]

    if level == 0:
        end_mode = start_mode.clone()
    else:
        end_mode = 1 - start_mode

    start_ctrl = one_hot(start_mode, 2)

    ctrl_seq = []
    for t in range(T):
        current_mode = torch.where(torch.full_like(start_mode, t) < switch_step, start_mode, end_mode)
        ctrl_seq.append(one_hot(current_mode, 2))
    ctrl_seq = torch.stack(ctrl_seq, dim=1)  # [B, T, 2]

    final_mode = torch.where(torch.full_like(start_mode, T - 1) < switch_step, start_mode, end_mode)
    target = task_value(digit_labels, final_mode)

    return x, digit_labels, start_mode, end_mode, start_ctrl, ctrl_seq, target

def mean_std(values):
    arr = np.array(values, dtype=np.float64)
    if len(arr) == 1:
        return float(arr[0]), 0.0
    return float(arr.mean()), float(arr.std(ddof=1))

# -----------------------------
# Modules
# -----------------------------
class MLP(nn.Module):
    def __init__(self, in_dim: int, out_dim: int, hidden: int = 128):
        super().__init__()
        self.net = nn.Sequential(
            nn.Linear(in_dim, hidden),
            nn.GELU(),
            nn.Linear(hidden, hidden),
            nn.GELU(),
            nn.Linear(hidden, out_dim),
        )

    def forward(self, x):
        return self.net(x)

class BaseKnowledgeProvider(nn.Module):
    """
    Base knowledge provider:
    x -> knowledge vector k0
    Trained first on digit classification, then frozen.
    """
    def __init__(self, x_dim: int = X_DIM, k_dim: int = KNOWLEDGE_DIM):
        super().__init__()
        self.encoder = nn.Sequential(
            nn.Linear(x_dim, 128),
            nn.GELU(),
            nn.Linear(128, k_dim),
            nn.LayerNorm(k_dim),
        )
        self.classifier = nn.Sequential(
            nn.Linear(k_dim, 64),
            nn.GELU(),
            nn.Linear(64, 10),
        )

        for m in self.modules():
            if isinstance(m, nn.Linear):
                nn.init.xavier_uniform_(m.weight)
                if m.bias is not None:
                    nn.init.zeros_(m.bias)

    def encode(self, x: torch.Tensor) -> torch.Tensor:
        return self.encoder(x)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        k0 = self.encode(x)
        return self.classifier(k0)

class DirectStaticBaseline(nn.Module):
    """
    Static baseline:
    uses base knowledge + start mode only
    no online control, no latent trajectory
    """
    def __init__(self, base: BaseKnowledgeProvider, k_dim: int = KNOWLEDGE_DIM):
        super().__init__()
        self.base = base
        self.head = MLP(k_dim + 2, NUM_CLASSES, hidden=96)

    def forward(self, x: torch.Tensor, start_ctrl: torch.Tensor) -> torch.Tensor:
        with torch.no_grad():
            k0 = self.base.encode(x)
        inp = torch.cat([k0, start_ctrl], dim=-1)
        return self.head(inp)

class FailureMemory:
    def __init__(self, capacity: int, z_dim: int, enabled: bool = False,
                 beta: float = 0.18, gamma: float = 0.35, store_thr: float = 0.35):
        self.capacity = capacity
        self.z_dim = z_dim
        self.enabled = enabled
        self.beta = beta
        self.gamma = gamma
        self.store_thr = store_thr
        self.mem = None
        self.age = None
        self.mask = None
        self.ptr = None

    def reset(self, batch_size: int):
        self.mem = torch.zeros(batch_size, self.capacity, self.z_dim, device=DEVICE)
        self.age = torch.zeros(batch_size, self.capacity, device=DEVICE)
        self.mask = torch.zeros(batch_size, self.capacity, dtype=torch.bool, device=DEVICE)
        self.ptr = torch.zeros(batch_size, dtype=torch.long, device=DEVICE)

    def repel(self, z: torch.Tensor) -> torch.Tensor:
        if not self.enabled or self.mem is None:
            return torch.zeros_like(z)
        zexp = z.unsqueeze(1)  # [B,1,D]
        diff = zexp - self.mem
        dist = diff.norm(dim=-1, keepdim=True).clamp_min(1e-6)
        direction = diff / dist

        znorm = F.normalize(zexp.expand_as(self.mem), dim=-1)
        mnorm = F.normalize(self.mem.clamp_min(1e-6), dim=-1)
        sim = (znorm * mnorm).sum(dim=-1)  # [B,K]

        weights = self.mask.float() * torch.exp(-self.gamma * self.age.float())
        rep = (weights.unsqueeze(-1) * sim.unsqueeze(-1) * direction).sum(dim=1)
        return self.beta * rep

    def update(self, cand: torch.Tensor, score: torch.Tensor):
        if not self.enabled or self.mem is None:
            return
        self.age[self.mask] += 1.0
        low = score < self.store_thr
        idx = torch.where(low)[0]
        if idx.numel() == 0:
            return
        slots = self.ptr[idx] % self.capacity
        self.mem[idx, slots] = cand.detach()[idx]
        self.age[idx, slots] = 0.0
        self.mask[idx, slots] = True
        self.ptr[idx] = (self.ptr[idx] + 1) % self.capacity

class MCLTRReasoner(nn.Module):
    """
    M-CLTR reasoning layer:
    - base model supplies knowledge
    - this module performs latent reasoning
    """
    def __init__(self, base: BaseKnowledgeProvider, x_dim: int = X_DIM, k_dim: int = KNOWLEDGE_DIM, z_dim: int = LATENT_DIM):
        super().__init__()
        self.base = base
        self.x_dim = x_dim
        self.k_dim = k_dim
        self.z_dim = z_dim

        self.init_net = MLP(x_dim + k_dim + 2, z_dim, hidden=128)
        self.trans = MLP(z_dim + x_dim + k_dim + 2 + 1, z_dim, hidden=128)
        self.decoder = nn.Linear(z_dim, NUM_CLASSES)

        self.evaluator = MLP(z_dim + x_dim + k_dim + 2 + 1, 1, hidden=96)

        self.z_norm = nn.LayerNorm(z_dim)
        self.k_proj = nn.Linear(k_dim, z_dim)
        self.ctrl_proj = nn.Linear(2, z_dim)

        for m in self.modules():
            if isinstance(m, nn.Linear):
                nn.init.xavier_uniform_(m.weight)
                if m.bias is not None:
                    nn.init.zeros_(m.bias)

    def knowledge(self, x):
        return self.base.encode(x)

    def build_eval_input(self, z, x, k0, ctrl, t: int):
        return torch.cat([z, x, k0, ctrl, step_feature(t, z.size(0), z.device)], dim=-1)

    def init_state(self, x, k0, start_ctrl):
        z0 = self.init_net(torch.cat([x, k0, start_ctrl], dim=-1))
        return self.z_norm(z0)

    def step_update(self, z, x, k0, ctrl, t: int):
        inp = self.build_eval_input(z, x, k0, ctrl, t)
        delta = torch.tanh(self.trans(inp))
        ctrl_shift = torch.tanh(self.ctrl_proj(ctrl))
        k_shift = torch.tanh(self.k_proj(k0))
        cand = self.z_norm(
            CARRY_Z * z
            + DELTA_W * delta
            + CTRL_W * ctrl_shift
            + K_W * k_shift
        )
        return cand

    def eval_score(self, z, x, k0, ctrl, t: int):
        inp = self.build_eval_input(z, x, k0, ctrl, t)
        return torch.sigmoid(self.evaluator(inp)).squeeze(-1)

    def decode(self, z):
        return self.decoder(z)

    def overwrite_state(self, cand, z0):
        return self.z_norm(OVERWRITE_BLEND * cand + (1.0 - OVERWRITE_BLEND) * z0)

    def continue_rollout_from_state(self, z_start, x, k0, ctrl_seq, start_t: int, use_memory: bool = False):
        z = z_start
        mem = FailureMemory(MEM_CAPACITY, self.z_dim, enabled=use_memory)
        if use_memory:
            mem.reset(z.size(0))
        for t in range(start_t, T):
            cand = self.step_update(z, x, k0, ctrl_seq[:, t, :], t)
            if use_memory:
                cand = cand - mem.repel(cand)
                mem.update(cand, torch.zeros(cand.size(0), device=cand.device))
            z = cand
        return z

    def rollout(self, x, start_ctrl, ctrl_seq, controlled: bool = False, use_memory: bool = False, return_trace: bool = False):
        k0 = self.knowledge(x)
        z0 = self.init_state(x, k0, start_ctrl)
        z = z0

        mem = FailureMemory(MEM_CAPACITY, self.z_dim, enabled=use_memory)
        if use_memory:
            mem.reset(x.size(0))

        actions = []
        scores = []
        deltas = []
        prev_score = torch.full((x.size(0),), 0.5, device=x.device)

        for t in range(T):
            cand = self.step_update(z, x, k0, ctrl_seq[:, t, :], t)
            if use_memory:
                cand = cand - mem.repel(cand)

            score = self.eval_score(cand, x, k0, ctrl_seq[:, t, :], t)
            delta = score - prev_score

            if controlled:
                raise RuntimeError("This diagnostic version does not train a policy head. Use forced modes or oracle mode instead.")
            else:
                action = torch.zeros(x.size(0), dtype=torch.long, device=x.device)

            z_next = cand
            if use_memory:
                mem.update(cand, score)

            actions.append(action)
            scores.append(score.detach())
            deltas.append(delta.detach())
            z = z_next
            prev_score = score.detach()

        logits = self.decode(z)
        if return_trace:
            return logits, torch.stack(actions, dim=1), torch.stack(scores, dim=1), torch.stack(deltas, dim=1), k0, z0, z
        return logits, torch.stack(actions, dim=1), k0, z0

# -----------------------------
# Oracle utilities
# -----------------------------
@torch.no_grad()
def final_target_prob_from_state(reasoner: MCLTRReasoner, z_start, x, k0, start_ctrl, ctrl_seq, start_t: int, target):
    z = reasoner.continue_rollout_from_state(z_start, x, k0, ctrl_seq, start_t, use_memory=False)
    logits = reasoner.decode(z)
    probs = F.softmax(logits, dim=-1)
    return probs.gather(1, target.unsqueeze(1)).squeeze(1)

@torch.no_grad()
def choose_oracle_action(reasoner: MCLTRReasoner, cand, z0, x, k0, start_ctrl, ctrl_seq, t: int, target):
    states = [
        cand,
        reasoner.overwrite_state(cand, z0),
        z0,
    ]
    probs = []
    for s in states:
        p = final_target_prob_from_state(reasoner, s, x, k0, start_ctrl, ctrl_seq, t + 1, target)
        probs.append(p)
    probs = torch.stack(probs, dim=-1)  # [B, 3]
    action = probs.argmax(dim=-1)
    best_prob = probs.gather(1, action.unsqueeze(1)).squeeze(1)
    return action, probs, best_prob

# -----------------------------
# Training
# -----------------------------
def set_requires_grad(module: nn.Module, flag: bool):
    for p in module.parameters():
        p.requires_grad = flag

def train_base(base: BaseKnowledgeProvider, epochs: int, steps_per_epoch: int):
    base.train()
    opt = torch.optim.AdamW(base.parameters(), lr=LR_BASE, weight_decay=1e-4)
    loss_fn = nn.CrossEntropyLoss()

    print("\n=== Stage 1: base knowledge pretraining (digit classification) ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_acc = 0.0
        for _ in range(steps_per_epoch):
            idx = sample_indices(X_train.size(0), BATCH_SIZE)
            xb = X_train[idx]
            yb = y_train[idx]

            logits = base(xb)
            loss = loss_fn(logits, yb)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(base.parameters(), 1.0)
            opt.step()

            total_loss += loss.item()
            total_acc += (logits.argmax(dim=-1) == yb).float().mean().item()

        print(f"Base epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} | acc {total_acc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s")

def train_direct_head(direct_head: DirectStaticBaseline, epochs: int, steps_per_epoch: int):
    direct_head.train()
    set_requires_grad(direct_head.base, False)
    opt = torch.optim.AdamW(direct_head.head.parameters(), lr=LR_DIRECT, weight_decay=1e-4)
    loss_fn = nn.CrossEntropyLoss()

    print("\n=== Stage 2: direct static baseline head (no online control) ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_acc = 0.0
        for _ in range(steps_per_epoch):
            x, digit_labels, start_mode, end_mode, start_ctrl, ctrl_seq, target = make_reasoning_batch(
                X_train, y_train, BATCH_SIZE, level=random.choice(LEVELS)
            )
            logits = direct_head(x, start_ctrl)
            loss = loss_fn(logits, target)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(direct_head.head.parameters(), 1.0)
            opt.step()

            total_loss += loss.item()
            total_acc += (logits.argmax(dim=-1) == target).float().mean().item()

        print(f"Direct epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} | acc {total_acc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s")

def train_reasoner_continue(reasoner: MCLTRReasoner, epochs: int, steps_per_epoch: int):
    reasoner.train()
    set_requires_grad(reasoner.base, False)
    set_requires_grad(reasoner.init_net, True)
    set_requires_grad(reasoner.trans, True)
    set_requires_grad(reasoner.decoder, True)
    set_requires_grad(reasoner.evaluator, False)
    set_requires_grad(reasoner.k_proj, True)
    set_requires_grad(reasoner.ctrl_proj, True)
    set_requires_grad(reasoner.z_norm, True)

    params = list(reasoner.init_net.parameters()) + list(reasoner.trans.parameters()) + list(reasoner.decoder.parameters()) + list(reasoner.k_proj.parameters()) + list(reasoner.ctrl_proj.parameters()) + list(reasoner.z_norm.parameters())
    opt = torch.optim.AdamW(params, lr=LR_REASONER, weight_decay=1e-4)
    loss_fn = nn.CrossEntropyLoss()

    print("\n=== Stage 3: reasoner pretraining (continue-only rollouts, mixed levels) ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_acc = 0.0
        for _ in range(steps_per_epoch):
            x, digit_labels, start_mode, end_mode, start_ctrl, ctrl_seq, target = make_reasoning_batch(
                X_train, y_train, BATCH_SIZE, level=random.choice(LEVELS)
            )
            k0 = reasoner.knowledge(x)
            z0 = reasoner.init_state(x, k0, start_ctrl)
            z = z0

            for t in range(T):
                z = reasoner.step_update(z, x, k0, ctrl_seq[:, t, :], t)

            logits = reasoner.decode(z)
            loss = loss_fn(logits, target)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(params, 1.0)
            opt.step()

            total_loss += loss.item()
            total_acc += (logits.argmax(dim=-1) == target).float().mean().item()

        print(f"Reasoner epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} | acc {total_acc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s")

def train_evaluator(reasoner: MCLTRReasoner, epochs: int, steps_per_epoch: int):
    reasoner.eval()
    set_requires_grad(reasoner.base, False)
    set_requires_grad(reasoner.init_net, False)
    set_requires_grad(reasoner.trans, False)
    set_requires_grad(reasoner.decoder, False)
    set_requires_grad(reasoner.evaluator, True)
    set_requires_grad(reasoner.k_proj, False)
    set_requires_grad(reasoner.ctrl_proj, False)
    set_requires_grad(reasoner.z_norm, False)

    opt = torch.optim.AdamW(reasoner.evaluator.parameters(), lr=LR_EVAL, weight_decay=1e-4)
    mse = nn.MSELoss()

    print("\n=== Stage 4: evaluator training (predict final correctness probability) ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_binacc = 0.0

        for _ in range(steps_per_epoch):
            x, digit_labels, start_mode, end_mode, start_ctrl, ctrl_seq, target = make_reasoning_batch(
                X_train, y_train, BATCH_SIZE, level=random.choice(LEVELS)
            )

            with torch.no_grad():
                k0 = reasoner.knowledge(x)
                z = reasoner.init_state(x, k0, start_ctrl)

                step_z = []
                step_x = []
                step_k0 = []
                step_ctrl = []
                step_t = []
                labels = []

                for t in range(T):
                    cand = reasoner.step_update(z, x, k0, ctrl_seq[:, t, :], t)
                    p_target = final_target_prob_from_state(reasoner, cand, x, k0, start_ctrl, ctrl_seq, t + 1, target)

                    step_z.append(cand.detach())
                    step_x.append(x.detach())
                    step_k0.append(k0.detach())
                    step_ctrl.append(ctrl_seq[:, t, :].detach())
                    step_t.append(step_feature(t, BATCH_SIZE, DEVICE))
                    labels.append(p_target.detach())

                    z = cand

                step_z = torch.cat(step_z, dim=0)
                step_x = torch.cat(step_x, dim=0)
                step_k0 = torch.cat(step_k0, dim=0)
                step_ctrl = torch.cat(step_ctrl, dim=0)
                step_t = torch.cat(step_t, dim=0)
                labels = torch.cat(labels, dim=0).clamp(0.0, 1.0)

            inp = torch.cat([step_z, step_x, step_k0, step_ctrl, step_t], dim=-1)
            pred = torch.sigmoid(reasoner.evaluator(inp)).squeeze(-1)
            loss = mse(pred, labels)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(reasoner.evaluator.parameters(), 1.0)
            opt.step()

            total_loss += loss.item()
            total_binacc += ((pred > 0.5) == (labels > 0.5)).float().mean().item()

        print(f"Evaluator epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} | bin-acc {total_binacc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s")

# -----------------------------
# Rollout modes
# -----------------------------
@torch.no_grad()
def apply_action(reasoner: MCLTRReasoner, cand, z0, action: torch.Tensor):
    z_next = cand.clone()
    overwrite_mask = action == 1
    restart_mask = action == 2
    if overwrite_mask.any():
        z_next[overwrite_mask] = reasoner.overwrite_state(cand[overwrite_mask], z0[overwrite_mask])
    if restart_mask.any():
        z_next[restart_mask] = z0[restart_mask]
    return z_next

@torch.no_grad()
def rollout_mode(
    reasoner: MCLTRReasoner,
    x: torch.Tensor,
    start_ctrl: torch.Tensor,
    ctrl_seq: torch.Tensor,
    target: Optional[torch.Tensor] = None,
    mode: str = "continue",
    use_memory: bool = False,
):
    """
    mode:
      - continue: always continue
      - overwrite: always overwrite
      - restart: always restart
      - oracle: choose the action that maximizes final target probability at each step
    """
    k0 = reasoner.knowledge(x)
    z0 = reasoner.init_state(x, k0, start_ctrl)
    z = z0

    mem = FailureMemory(MEM_CAPACITY, reasoner.z_dim, enabled=use_memory)
    if use_memory:
        mem.reset(x.size(0))

    actions = []
    per_step_probs = []

    for t in range(T):
        cand = reasoner.step_update(z, x, k0, ctrl_seq[:, t, :], t)
        if use_memory:
            cand = cand - mem.repel(cand)

        if mode == "continue":
            action = torch.zeros(x.size(0), dtype=torch.long, device=x.device)
            z_next = cand
            probs_t = None

        elif mode == "overwrite":
            action = torch.ones(x.size(0), dtype=torch.long, device=x.device)
            z_next = reasoner.overwrite_state(cand, z0)
            probs_t = None

        elif mode == "restart":
            action = torch.full((x.size(0),), 2, dtype=torch.long, device=x.device)
            z_next = z0
            probs_t = None

        elif mode == "oracle":
            if target is None:
                raise ValueError("oracle mode requires target")
            action, probs, best_prob = choose_oracle_action(reasoner, cand, z0, x, k0, start_ctrl, ctrl_seq, t, target)
            z_next = apply_action(reasoner, cand, z0, action)
            probs_t = probs  # [B,3]
        else:
            raise ValueError(f"Unknown mode: {mode}")

        if use_memory:
            mem.update(cand, torch.zeros(cand.size(0), device=cand.device))

        actions.append(action)
        if probs_t is not None:
            per_step_probs.append(probs_t)
        z = z_next

    logits = reasoner.decode(z)
    out = {
        "logits": logits,
        "actions": torch.stack(actions, dim=1),
    }
    if len(per_step_probs) > 0:
        out["per_step_probs"] = torch.stack(per_step_probs, dim=1)  # [B,T,3]
    return out

# -----------------------------
# Evaluation / probing
# -----------------------------
@torch.no_grad()
def eval_base_classifier(base: BaseKnowledgeProvider, batches: int = 20, bs: int = 256):
    base.eval()
    total = 0
    correct = 0
    for _ in range(batches):
        idx = sample_indices(X_test.size(0), bs)
        xb = X_test[idx]
        yb = y_test[idx]
        logits = base(xb)
        pred = logits.argmax(dim=-1)
        correct += (pred == yb).sum().item()
        total += yb.numel()
    return correct / total

@torch.no_grad()
def eval_direct(direct_head: DirectStaticBaseline, level: int, batches: int = 20, bs: int = 256):
    direct_head.eval()
    total = 0
    correct = 0
    for _ in range(batches):
        x, digit_labels, start_mode, end_mode, start_ctrl, ctrl_seq, target = make_reasoning_batch(
            X_test, y_test, bs, level=level
        )
        logits = direct_head(x, start_ctrl)
        pred = logits.argmax(dim=-1)
        correct += (pred == target).sum().item()
        total += target.numel()
    return correct / total

@torch.no_grad()
def eval_reasoner(reasoner: MCLTRReasoner, level: int, mode: str, batches: int = 20, bs: int = 256):
    reasoner.eval()
    total = 0
    correct = 0
    all_actions = []

    for _ in range(batches):
        x, digit_labels, start_mode, end_mode, start_ctrl, ctrl_seq, target = make_reasoning_batch(
            X_test, y_test, bs, level=level
        )
        out = rollout_mode(reasoner, x, start_ctrl, ctrl_seq, target=target, mode=mode, use_memory=USE_FAILURE_MEMORY)
        pred = out["logits"].argmax(dim=-1)
        correct += (pred == target).sum().item()
        total += target.numel()
        all_actions.append(out["actions"])

    result = {
        "acc": correct / total,
    }
    if len(all_actions) > 0:
        actions = torch.cat(all_actions, dim=0)
        counts = torch.stack([
            (actions == 0).sum(),
            (actions == 1).sum(),
            (actions == 2).sum(),
        ]).float()
        rates = (counts / actions.numel()).cpu().numpy()
        result["continue_rate"] = float(rates[0])
        result["overwrite_rate"] = float(rates[1])
        result["restart_rate"] = float(rates[2])
    return result

@torch.no_grad()
def probe_action_values(reasoner: MCLTRReasoner, level: int, batches: int = 8, bs: int = 128):
    """
    This is the key diagnostic:
    for each step, measure whether continue / overwrite / restart gives the
    best final target probability from the current latent candidate.
    """
    reasoner.eval()

    best_counts = torch.zeros(T, 3, device=DEVICE)
    mean_probs = torch.zeros(T, 3, device=DEVICE)
    gain_over_continue = torch.zeros(T, device=DEVICE)
    gain_restart_over_continue = torch.zeros(T, device=DEVICE)

    traces = []

    for _ in range(batches):
        x, digit_labels, start_mode, end_mode, start_ctrl, ctrl_seq, target = make_reasoning_batch(
            X_test, y_test, bs, level=level
        )
        k0 = reasoner.knowledge(x)
        z0 = reasoner.init_state(x, k0, start_ctrl)
        z = z0

        for t in range(T):
            cand = reasoner.step_update(z, x, k0, ctrl_seq[:, t, :], t)

            cont_state = cand
            over_state = reasoner.overwrite_state(cand, z0)
            rest_state = z0

            p_cont = final_target_prob_from_state(reasoner, cont_state, x, k0, start_ctrl, ctrl_seq, t + 1, target)
            p_over = final_target_prob_from_state(reasoner, over_state, x, k0, start_ctrl, ctrl_seq, t + 1, target)
            p_rest = final_target_prob_from_state(reasoner, rest_state, x, k0, start_ctrl, ctrl_seq, t + 1, target)

            probs = torch.stack([p_cont, p_over, p_rest], dim=-1)  # [B,3]
            best = probs.argmax(dim=-1)

            for a in range(3):
                best_counts[t, a] += (best == a).sum()
            mean_probs[t, 0] += p_cont.sum()
            mean_probs[t, 1] += p_over.sum()
            mean_probs[t, 2] += p_rest.sum()

            gain_over_continue[t] += (p_over - p_cont).sum()
            gain_restart_over_continue[t] += (p_rest - p_cont).sum()

            z = cand

        if len(traces) < 4:
            # store a few sample traces for the first batch
            for i in range(min(4 - len(traces), bs)):
                traces.append({
                    "digit": int(digit_labels[i].item()),
                    "start_mode": int(start_mode[i].item()),
                    "end_mode": int(end_mode[i].item()),
                    "target": int(target[i].item()),
                })

    denom = batches * bs
    mean_probs = (mean_probs / denom).cpu().numpy()
    gain_over_continue = (gain_over_continue / denom).cpu().numpy()
    gain_restart_over_continue = (gain_restart_over_continue / denom).cpu().numpy()
    best_rates = (best_counts / denom).cpu().numpy()

    return {
        "mean_probs": mean_probs,  # [T,3]
        "best_rates": best_rates,   # [T,3]
        "gain_over_continue": gain_over_continue,
        "gain_restart_over_continue": gain_restart_over_continue,
        "traces": traces,
    }

def print_probe_summary(probe: Dict, level: int):
    print(f"\n--- Action probe: level {level} ({LEVEL_NAMES[level]}) ---")
    labels = ["continue", "overwrite", "restart"]
    for t in range(T):
        mp = probe["mean_probs"][t]
        br = probe["best_rates"][t]
        g1 = probe["gain_over_continue"][t]
        g2 = probe["gain_restart_over_continue"][t]
        print(
            f"step {t}: mean p(cont/over/rest)=({mp[0]:.3f}, {mp[1]:.3f}, {mp[2]:.3f}) | "
            f"best rates=({br[0]:.3f}, {br[1]:.3f}, {br[2]:.3f}) | "
            f"Δover-cont={g1:+.4f} | Δrestart-cont={g2:+.4f}"
        )

# -----------------------------
# One seed run
# -----------------------------
def run_one_seed(seed: int):
    set_seed(seed)
    print("\n\n##############################")
    print(f"Seed = {seed}")
    print("##############################")

    base = BaseKnowledgeProvider().to(DEVICE)
    direct_head = DirectStaticBaseline(base).to(DEVICE)

    # Stage 1: train the base knowledge provider on digit identity
    train_base(base, BASE_EPOCHS, BASE_STEPS_PER_EPOCH)

    # Freeze a copy for the reasoning layer
    frozen_base = copy.deepcopy(base).to(DEVICE)
    for p in frozen_base.parameters():
        p.requires_grad = False

    # Stage 2: train direct baseline head
    direct_head.base = frozen_base
    train_direct_head(direct_head, DIRECT_EPOCHS, DIRECT_STEPS_PER_EPOCH)

    # Stage 3: train reasoning layer in continue-only mode
    reasoner = MCLTRReasoner(frozen_base).to(DEVICE)
    train_reasoner_continue(reasoner, REASONER_EPOCHS, REASONER_STEPS_PER_EPOCH)

    # Stage 4: evaluator
    train_evaluator(reasoner, EVAL_EPOCHS, EVAL_STEPS_PER_EPOCH)

    # Evaluate by level and by mode
    seed_results = {}
    for level in LEVELS:
        direct_acc = eval_direct(direct_head, level=level, batches=20, bs=256)
        base_acc = eval_base_classifier(base, batches=20, bs=256)
        cont = eval_reasoner(reasoner, level=level, mode="continue", batches=20, bs=256)
        over = eval_reasoner(reasoner, level=level, mode="overwrite", batches=20, bs=256)
        rest = eval_reasoner(reasoner, level=level, mode="restart", batches=20, bs=256)
        oracle = eval_reasoner(reasoner, level=level, mode="oracle", batches=20, bs=256)
        probe = probe_action_values(reasoner, level=level, batches=8, bs=128)

        seed_results[level] = {
            "base_acc": base_acc,
            "direct_acc": direct_acc,
            "continue_acc": cont["acc"],
            "overwrite_acc": over["acc"],
            "restart_acc": rest["acc"],
            "oracle_acc": oracle["acc"],
            "oracle_continue_rate": oracle.get("continue_rate", float("nan")),
            "oracle_overwrite_rate": oracle.get("overwrite_rate", float("nan")),
            "oracle_restart_rate": oracle.get("restart_rate", float("nan")),
            "probe": probe,
        }

        print(f"\n--- Seed {seed} | Level {level} ({LEVEL_NAMES[level]}) ---")
        print(f"Base classifier (digit ID only)     : {base_acc:.4f}")
        print(f"Direct static baseline             : {direct_acc:.4f}")
        print(f"M-CLTR continue-only               : {cont['acc']:.4f}")
        print(f"M-CLTR forced overwrite            : {over['acc']:.4f}")
        print(f"M-CLTR forced restart              : {rest['acc']:.4f}")
        print(f"M-CLTR step-wise oracle            : {oracle['acc']:.4f}")
        print(
            f"Oracle action rates C/O/R          : "
            f"{oracle['continue_rate']:.3f}/{oracle['overwrite_rate']:.3f}/{oracle['restart_rate']:.3f}"
        )

        print_probe_summary(probe, level)

    print("\n=== Sample traces on hardest level (oracle-probe context) ===")
    hard_probe = seed_results[3]["probe"]
    for i, tr in enumerate(hard_probe["traces"]):
        print(
            f"[{i}] digit={tr['digit']} start={tr['start_mode']} end={tr['end_mode']} "
            f"target={tr['target']}"
        )

    return seed_results

# -----------------------------
# Run seeds
# -----------------------------
all_results = {}
for seed in SEEDS:
    all_results[seed] = run_one_seed(seed)

# -----------------------------
# Aggregate
# -----------------------------
print("\n\n==============================")
print("Aggregated summary across seeds")
print("==============================")

for level in LEVELS:
    base_vals = []
    direct_vals = []
    continue_vals = []
    overwrite_vals = []
    restart_vals = []
    oracle_vals = []

    oracle_c_rates = []
    oracle_o_rates = []
    oracle_r_rates = []

    probe_over_gains = []
    probe_restart_gains = []
    probe_best_over_rates = []
    probe_best_restart_rates = []

    for seed in SEEDS:
        rr = all_results[seed][level]
        base_vals.append(rr["base_acc"])
        direct_vals.append(rr["direct_acc"])
        continue_vals.append(rr["continue_acc"])
        overwrite_vals.append(rr["overwrite_acc"])
        restart_vals.append(rr["restart_acc"])
        oracle_vals.append(rr["oracle_acc"])

        oracle_c_rates.append(rr["oracle_continue_rate"])
        oracle_o_rates.append(rr["oracle_overwrite_rate"])
        oracle_r_rates.append(rr["oracle_restart_rate"])

        probe = rr["probe"]
        probe_over_gains.append(float(probe["gain_over_continue"].mean()))
        probe_restart_gains.append(float(probe["gain_restart_over_continue"].mean()))
        probe_best_over_rates.append(float(probe["best_rates"][:, 1].mean()))
        probe_best_restart_rates.append(float(probe["best_rates"][:, 2].mean()))

    bm, bs = mean_std(base_vals)
    dm, ds = mean_std(direct_vals)
    cm, cs = mean_std(continue_vals)
    om, os = mean_std(overwrite_vals)
    rm, rs = mean_std(restart_vals)
    qm, qs = mean_std(oracle_vals)

    c_rm, c_rs = mean_std(oracle_c_rates)
    o_rm, o_rs = mean_std(oracle_o_rates)
    r_rm, r_rs = mean_std(oracle_r_rates)

    g_over_m, g_over_s = mean_std(probe_over_gains)
    g_rest_m, g_rest_s = mean_std(probe_restart_gains)
    b_over_m, b_over_s = mean_std(probe_best_over_rates)
    b_rest_m, b_rest_s = mean_std(probe_best_restart_rates)

    print(f"\nLevel {level} ({LEVEL_NAMES[level]})")
    print(f"  Base classifier              : {bm:.4f} ± {bs:.4f}")
    print(f"  Direct static baseline       : {dm:.4f} ± {ds:.4f}")
    print(f"  M-CLTR continue-only         : {cm:.4f} ± {cs:.4f}")
    print(f"  M-CLTR forced overwrite      : {om:.4f} ± {os:.4f}")
    print(f"  M-CLTR forced restart        : {rm:.4f} ± {rs:.4f}")
    print(f"  M-CLTR step-wise oracle      : {qm:.4f} ± {qs:.4f}")
    print(f"  Oracle action rates C/O/R    : {c_rm:.3f} ± {c_rs:.3f} / {o_rm:.3f} ± {o_rs:.3f} / {r_rm:.3f} ± {r_rs:.3f}")
    print(f"  Probe mean Δ(over - cont)    : {g_over_m:+.4f} ± {g_over_s:.4f}")
    print(f"  Probe mean Δ(rest - cont)    : {g_rest_m:+.4f} ± {g_rest_s:.4f}")
    print(f"  Probe best-action overwrite   : {b_over_m:.3f} ± {b_over_s:.3f}")
    print(f"  Probe best-action restart     : {b_rest_m:.3f} ± {b_rest_s:.3f}")

print("\nDone.")

# M-CLTR v4.2 — overwrite vs restart diagnostic with base-strength sweep
# Real small data: sklearn digits
# Multi-seed, CPU-friendly
#
# What this tests:
# 1) Base strength sweep: weak / medium / strong base knowledge
# 2) Overwrite blend sweep: does overwrite ever become better if the projection changes?
# 3) Zero-knowledge ablation: does M-CLTR depend on base knowledge?
# 4) Step-wise oracle probe: which action is actually best at each step?
#
# Main output to inspect:
# - continue / overwrite / restart accuracies
# - oracle best-action rates
# - per-step Δ(overwrite - continue) and Δ(restart - continue)
# - normal knowledge vs zero-knowledge gap
#
# If overwrite is the right action, you should see:
# - overwrite best-rate rise
# - positive Δ(overwrite - continue)
# - overwrite accuracy approach or exceed restart on some settings
#
# If restart dominates no matter what, the issue is not just base quality;
# the latent transition / projection math is favoring restart structurally.

import copy
import math
import random
import time
from typing import Optional, Dict, List

import numpy as np
import torch
import torch.nn as nn
import torch.nn.functional as F

from sklearn.datasets import load_digits
from sklearn.model_selection import train_test_split

# -----------------------------
# Device / reproducibility
# -----------------------------
DEVICE = torch.device("cuda" if torch.cuda.is_available() else "cpu")
print("Device:", DEVICE)

# -----------------------------
# Config
# -----------------------------
T = 6
LATENT_DIM = 96
KNOWLEDGE_DIM = 64
NUM_CLASSES = 2

BATCH_SIZE = 96

BASE_EPOCH_OPTIONS = [1, 4, 8]      # weak / medium / strong base
SEEDS = [7, 17]                     # keep CPU-friendly; add more if desired

BASE_STEPS_PER_EPOCH = 35
DIRECT_STEPS_PER_EPOCH = 35
REASONER_STEPS_PER_EPOCH = 35
EVAL_STEPS_PER_EPOCH = 35

LR_BASE = 2e-3
LR_DIRECT = 2e-3
LR_REASONER = 2e-3
LR_EVAL = 2e-3

# Reasoning dynamics
CARRY_Z = 0.86
DELTA_W = 0.10
CTRL_W = 0.02
K_W = 0.02

# Overwrite blend sweep:
# 0.2 = overwrite moves strongly toward z0
# 0.5 = balanced
# 0.8 = overwrite stays close to candidate
OVERWRITE_BLENDS = [0.2, 0.5, 0.8]

# Optional failure memory, off for clean diagnostic
USE_FAILURE_MEMORY = False
MEM_CAPACITY = 6
MEM_BETA = 0.18
MEM_GAMMA = 0.35
MEM_STORE_THR = 0.35

# Difficulty levels
LEVELS = [0, 1, 2, 3]
LEVEL_NAMES = {
    0: "easy / no switch",
    1: "medium / mid switch",
    2: "hard / early switch",
    3: "switch + noisy input",
}
LEVEL_TO_SWITCH_STEP = {
    0: T,
    1: T // 2,
    2: 1,
    3: T // 2,
}
NOISE_SIGMA_LEVEL3 = 0.25

# -----------------------------
# Data
# -----------------------------
digits = load_digits()
X_all = torch.tensor(digits.data, dtype=torch.float32) / 16.0
y_all = torch.tensor(digits.target, dtype=torch.long)

X_train_np, X_test_np, y_train_np, y_test_np = train_test_split(
    X_all.numpy(),
    y_all.numpy(),
    test_size=0.30,
    random_state=0,
    stratify=y_all.numpy(),
)

X_train = torch.tensor(X_train_np, dtype=torch.float32, device=DEVICE)
y_train = torch.tensor(y_train_np, dtype=torch.long, device=DEVICE)
X_test = torch.tensor(X_test_np, dtype=torch.float32, device=DEVICE)
y_test = torch.tensor(y_test_np, dtype=torch.long, device=DEVICE)

X_DIM = X_train.shape[1]

# -----------------------------
# Utilities
# -----------------------------
def set_seed(seed: int):
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    if torch.cuda.is_available():
        torch.cuda.manual_seed_all(seed)

def one_hot(v: torch.Tensor, n: int) -> torch.Tensor:
    return F.one_hot(v.long(), n).float()

def step_feature(t: int, batch_size: int, device: torch.device) -> torch.Tensor:
    if T <= 1:
        s = 0.0
    else:
        s = float(t) / float(T - 1)
    return torch.full((batch_size, 1), s, device=device)

def sample_indices(n: int, batch_size: int) -> torch.Tensor:
    return torch.randint(0, n, (batch_size,), device=DEVICE)

def task_value(digit_labels: torch.Tensor, mode: torch.Tensor) -> torch.Tensor:
    parity = (digit_labels % 2).long()      # mode 0
    lowhigh = (digit_labels >= 5).long()    # mode 1
    return torch.where(mode == 0, parity, lowhigh)

def make_reasoning_batch(
    x_pool: torch.Tensor,
    y_pool: torch.Tensor,
    batch_size: int,
    level: int = 0,
):
    idx = sample_indices(x_pool.size(0), batch_size)
    x = x_pool[idx].clone()
    digit_labels = y_pool[idx]

    if level == 3:
        noise = NOISE_SIGMA_LEVEL3 * torch.randn_like(x)
        x = torch.clamp(x + noise, 0.0, 1.0)

    start_mode = torch.randint(0, 2, (batch_size,), device=DEVICE)
    switch_step = LEVEL_TO_SWITCH_STEP[level]

    if level == 0:
        end_mode = start_mode.clone()
    else:
        end_mode = 1 - start_mode

    start_ctrl = one_hot(start_mode, 2)

    ctrl_seq = []
    for t in range(T):
        current_mode = torch.where(torch.full_like(start_mode, t) < switch_step, start_mode, end_mode)
        ctrl_seq.append(one_hot(current_mode, 2))
    ctrl_seq = torch.stack(ctrl_seq, dim=1)  # [B, T, 2]

    final_mode = torch.where(torch.full_like(start_mode, T - 1) < switch_step, start_mode, end_mode)
    target = task_value(digit_labels, final_mode)

    return x, digit_labels, start_mode, end_mode, start_ctrl, ctrl_seq, target

def mean_std(values):
    arr = np.array(values, dtype=np.float64)
    if len(arr) == 1:
        return float(arr[0]), 0.0
    return float(arr.mean()), float(arr.std(ddof=1))

# -----------------------------
# Modules
# -----------------------------
class MLP(nn.Module):
    def __init__(self, in_dim: int, out_dim: int, hidden: int = 128):
        super().__init__()
        self.net = nn.Sequential(
            nn.Linear(in_dim, hidden),
            nn.GELU(),
            nn.Linear(hidden, hidden),
            nn.GELU(),
            nn.Linear(hidden, out_dim),
        )

    def forward(self, x):
        return self.net(x)

class BaseKnowledgeProvider(nn.Module):
    """
    Base knowledge provider:
    x -> knowledge vector k0
    Trained first on digit classification, then frozen.
    """
    def __init__(self, x_dim: int = X_DIM, k_dim: int = KNOWLEDGE_DIM):
        super().__init__()
        self.encoder = nn.Sequential(
            nn.Linear(x_dim, 128),
            nn.GELU(),
            nn.Linear(128, k_dim),
            nn.LayerNorm(k_dim),
        )
        self.classifier = nn.Sequential(
            nn.Linear(k_dim, 64),
            nn.GELU(),
            nn.Linear(64, 10),
        )

        for m in self.modules():
            if isinstance(m, nn.Linear):
                nn.init.xavier_uniform_(m.weight)
                if m.bias is not None:
                    nn.init.zeros_(m.bias)

    def encode(self, x: torch.Tensor) -> torch.Tensor:
        return self.encoder(x)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        k0 = self.encode(x)
        return self.classifier(k0)

class DirectStaticBaseline(nn.Module):
    """
    Static baseline:
    uses base knowledge + start mode only
    """
    def __init__(self, base: BaseKnowledgeProvider, k_dim: int = KNOWLEDGE_DIM):
        super().__init__()
        self.base = base
        self.head = MLP(k_dim + 2, NUM_CLASSES, hidden=96)

    def forward(self, x: torch.Tensor, start_ctrl: torch.Tensor) -> torch.Tensor:
        with torch.no_grad():
            k0 = self.base.encode(x)
        inp = torch.cat([k0, start_ctrl], dim=-1)
        return self.head(inp)

class FailureMemory:
    def __init__(self, capacity: int, z_dim: int, enabled: bool = False,
                 beta: float = 0.18, gamma: float = 0.35, store_thr: float = 0.35):
        self.capacity = capacity
        self.z_dim = z_dim
        self.enabled = enabled
        self.beta = beta
        self.gamma = gamma
        self.store_thr = store_thr
        self.mem = None
        self.age = None
        self.mask = None
        self.ptr = None

    def reset(self, batch_size: int):
        self.mem = torch.zeros(batch_size, self.capacity, self.z_dim, device=DEVICE)
        self.age = torch.zeros(batch_size, self.capacity, device=DEVICE)
        self.mask = torch.zeros(batch_size, self.capacity, dtype=torch.bool, device=DEVICE)
        self.ptr = torch.zeros(batch_size, dtype=torch.long, device=DEVICE)

    def repel(self, z: torch.Tensor) -> torch.Tensor:
        if not self.enabled or self.mem is None:
            return torch.zeros_like(z)
        zexp = z.unsqueeze(1)
        diff = zexp - self.mem
        dist = diff.norm(dim=-1, keepdim=True).clamp_min(1e-6)
        direction = diff / dist

        znorm = F.normalize(zexp.expand_as(self.mem), dim=-1)
        mnorm = F.normalize(self.mem.clamp_min(1e-6), dim=-1)
        sim = (znorm * mnorm).sum(dim=-1)

        weights = self.mask.float() * torch.exp(-self.gamma * self.age.float())
        rep = (weights.unsqueeze(-1) * sim.unsqueeze(-1) * direction).sum(dim=1)
        return self.beta * rep

    def update(self, cand: torch.Tensor, score: torch.Tensor):
        if not self.enabled or self.mem is None:
            return
        self.age[self.mask] += 1.0
        low = score < self.store_thr
        idx = torch.where(low)[0]
        if idx.numel() == 0:
            return
        slots = self.ptr[idx] % self.capacity
        self.mem[idx, slots] = cand.detach()[idx]
        self.age[idx, slots] = 0.0
        self.mask[idx, slots] = True
        self.ptr[idx] = (self.ptr[idx] + 1) % self.capacity

class MCLTRReasoner(nn.Module):
    """
    M-CLTR reasoning layer:
    base model supplies knowledge; this module performs latent reasoning.
    """
    def __init__(self, base: BaseKnowledgeProvider, x_dim: int = X_DIM, k_dim: int = KNOWLEDGE_DIM, z_dim: int = LATENT_DIM):
        super().__init__()
        self.base = base
        self.x_dim = x_dim
        self.k_dim = k_dim
        self.z_dim = z_dim

        self.init_net = MLP(x_dim + k_dim + 2, z_dim, hidden=128)
        self.trans = MLP(z_dim + x_dim + k_dim + 2 + 1, z_dim, hidden=128)
        self.decoder = nn.Linear(z_dim, NUM_CLASSES)

        self.evaluator = MLP(z_dim + x_dim + k_dim + 2 + 1, 1, hidden=96)

        self.z_norm = nn.LayerNorm(z_dim)
        self.k_proj = nn.Linear(k_dim, z_dim)
        self.ctrl_proj = nn.Linear(2, z_dim)

        for m in self.modules():
            if isinstance(m, nn.Linear):
                nn.init.xavier_uniform_(m.weight)
                if m.bias is not None:
                    nn.init.zeros_(m.bias)

    def knowledge(self, x):
        return self.base.encode(x)

    def build_eval_input(self, z, x, k0, ctrl, t: int):
        return torch.cat([z, x, k0, ctrl, step_feature(t, z.size(0), z.device)], dim=-1)

    def init_state(self, x, k0, start_ctrl):
        z0 = self.init_net(torch.cat([x, k0, start_ctrl], dim=-1))
        return self.z_norm(z0)

    def step_update(self, z, x, k0, ctrl, t: int):
        inp = self.build_eval_input(z, x, k0, ctrl, t)
        delta = torch.tanh(self.trans(inp))
        ctrl_shift = torch.tanh(self.ctrl_proj(ctrl))
        k_shift = torch.tanh(self.k_proj(k0))
        cand = self.z_norm(
            CARRY_Z * z
            + DELTA_W * delta
            + CTRL_W * ctrl_shift
            + K_W * k_shift
        )
        return cand

    def eval_score(self, z, x, k0, ctrl, t: int):
        inp = self.build_eval_input(z, x, k0, ctrl, t)
        return torch.sigmoid(self.evaluator(inp)).squeeze(-1)

    def decode(self, z):
        return self.decoder(z)

    def overwrite_state(self, cand, z0, blend: float):
        return self.z_norm(blend * cand + (1.0 - blend) * z0)

# -----------------------------
# Oracle utilities
# -----------------------------
@torch.no_grad()
def final_target_prob_from_state(reasoner: MCLTRReasoner, z_start, x, k0, start_ctrl, ctrl_seq, start_t: int, target):
    z = z_start
    mem = FailureMemory(MEM_CAPACITY, reasoner.z_dim, enabled=USE_FAILURE_MEMORY)
    if USE_FAILURE_MEMORY:
        mem.reset(z.size(0))
    for t in range(start_t, T):
        cand = reasoner.step_update(z, x, k0, ctrl_seq[:, t, :], t)
        if USE_FAILURE_MEMORY:
            cand = cand - mem.repel(cand)
            mem.update(cand, torch.zeros(cand.size(0), device=cand.device))
        z = cand
    logits = reasoner.decode(z)
    probs = F.softmax(logits, dim=-1)
    return probs.gather(1, target.unsqueeze(1)).squeeze(1)

@torch.no_grad()
def choose_oracle_action(reasoner: MCLTRReasoner, cand, z0, x, k0, start_ctrl, ctrl_seq, t: int, target, blend: float):
    states = [
        cand,
        reasoner.overwrite_state(cand, z0, blend=blend),
        z0,
    ]
    probs = []
    for s in states:
        p = final_target_prob_from_state(reasoner, s, x, k0, start_ctrl, ctrl_seq, t + 1, target)
        probs.append(p)
    probs = torch.stack(probs, dim=-1)  # [B,3]
    action = probs.argmax(dim=-1)
    best_prob = probs.gather(1, action.unsqueeze(1)).squeeze(1)
    return action, probs, best_prob

# -----------------------------
# Training
# -----------------------------
def set_requires_grad(module: nn.Module, flag: bool):
    for p in module.parameters():
        p.requires_grad = flag

def train_base(base: BaseKnowledgeProvider, epochs: int, steps_per_epoch: int):
    base.train()
    opt = torch.optim.AdamW(base.parameters(), lr=LR_BASE, weight_decay=1e-4)
    loss_fn = nn.CrossEntropyLoss()

    print("\n=== Stage 1: base knowledge pretraining (digit classification) ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_acc = 0.0
        for _ in range(steps_per_epoch):
            idx = sample_indices(X_train.size(0), BATCH_SIZE)
            xb = X_train[idx]
            yb = y_train[idx]

            logits = base(xb)
            loss = loss_fn(logits, yb)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(base.parameters(), 1.0)
            opt.step()

            total_loss += loss.item()
            total_acc += (logits.argmax(dim=-1) == yb).float().mean().item()

        print(f"Base epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} | acc {total_acc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s")

def train_direct_head(direct_head: DirectStaticBaseline, epochs: int, steps_per_epoch: int):
    direct_head.train()
    set_requires_grad(direct_head.base, False)
    opt = torch.optim.AdamW(direct_head.head.parameters(), lr=LR_DIRECT, weight_decay=1e-4)
    loss_fn = nn.CrossEntropyLoss()

    print("\n=== Stage 2: direct static baseline head (no online control) ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_acc = 0.0
        for _ in range(steps_per_epoch):
            x, digit_labels, start_mode, end_mode, start_ctrl, ctrl_seq, target = make_reasoning_batch(
                X_train, y_train, BATCH_SIZE, level=random.choice(LEVELS)
            )
            logits = direct_head(x, start_ctrl)
            loss = loss_fn(logits, target)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(direct_head.head.parameters(), 1.0)
            opt.step()

            total_loss += loss.item()
            total_acc += (logits.argmax(dim=-1) == target).float().mean().item()

        print(f"Direct epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} | acc {total_acc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s")

def train_reasoner_continue(reasoner: MCLTRReasoner, epochs: int, steps_per_epoch: int):
    reasoner.train()
    set_requires_grad(reasoner.base, False)
    set_requires_grad(reasoner.init_net, True)
    set_requires_grad(reasoner.trans, True)
    set_requires_grad(reasoner.decoder, True)
    set_requires_grad(reasoner.evaluator, False)
    set_requires_grad(reasoner.k_proj, True)
    set_requires_grad(reasoner.ctrl_proj, True)
    set_requires_grad(reasoner.z_norm, True)

    params = list(reasoner.init_net.parameters()) + list(reasoner.trans.parameters()) + list(reasoner.decoder.parameters()) + list(reasoner.k_proj.parameters()) + list(reasoner.ctrl_proj.parameters()) + list(reasoner.z_norm.parameters())
    opt = torch.optim.AdamW(params, lr=LR_REASONER, weight_decay=1e-4)
    loss_fn = nn.CrossEntropyLoss()

    print("\n=== Stage 3: reasoner pretraining (continue-only rollouts, mixed levels) ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_acc = 0.0
        for _ in range(steps_per_epoch):
            x, digit_labels, start_mode, end_mode, start_ctrl, ctrl_seq, target = make_reasoning_batch(
                X_train, y_train, BATCH_SIZE, level=random.choice(LEVELS)
            )
            k0 = reasoner.knowledge(x)
            z = reasoner.init_state(x, k0, start_ctrl)
            for t in range(T):
                z = reasoner.step_update(z, x, k0, ctrl_seq[:, t, :], t)

            logits = reasoner.decode(z)
            loss = loss_fn(logits, target)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(params, 1.0)
            opt.step()

            total_loss += loss.item()
            total_acc += (logits.argmax(dim=-1) == target).float().mean().item()

        print(f"Reasoner epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} | acc {total_acc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s")

def train_evaluator(reasoner: MCLTRReasoner, epochs: int, steps_per_epoch: int):
    reasoner.eval()
    set_requires_grad(reasoner.base, False)
    set_requires_grad(reasoner.init_net, False)
    set_requires_grad(reasoner.trans, False)
    set_requires_grad(reasoner.decoder, False)
    set_requires_grad(reasoner.evaluator, True)
    set_requires_grad(reasoner.k_proj, False)
    set_requires_grad(reasoner.ctrl_proj, False)
    set_requires_grad(reasoner.z_norm, False)

    opt = torch.optim.AdamW(reasoner.evaluator.parameters(), lr=LR_EVAL, weight_decay=1e-4)
    mse = nn.MSELoss()

    print("\n=== Stage 4: evaluator training (predict final correctness probability) ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_binacc = 0.0

        for _ in range(steps_per_epoch):
            x, digit_labels, start_mode, end_mode, start_ctrl, ctrl_seq, target = make_reasoning_batch(
                X_train, y_train, BATCH_SIZE, level=random.choice(LEVELS)
            )

            with torch.no_grad():
                k0 = reasoner.knowledge(x)
                z = reasoner.init_state(x, k0, start_ctrl)

                step_z = []
                step_x = []
                step_k0 = []
                step_ctrl = []
                step_t = []
                labels = []

                for t in range(T):
                    cand = reasoner.step_update(z, x, k0, ctrl_seq[:, t, :], t)
                    p_target = final_target_prob_from_state(reasoner, cand, x, k0, start_ctrl, ctrl_seq, t + 1, target)

                    step_z.append(cand.detach())
                    step_x.append(x.detach())
                    step_k0.append(k0.detach())
                    step_ctrl.append(ctrl_seq[:, t, :].detach())
                    step_t.append(step_feature(t, BATCH_SIZE, DEVICE))
                    labels.append(p_target.detach())

                    z = cand

                step_z = torch.cat(step_z, dim=0)
                step_x = torch.cat(step_x, dim=0)
                step_k0 = torch.cat(step_k0, dim=0)
                step_ctrl = torch.cat(step_ctrl, dim=0)
                step_t = torch.cat(step_t, dim=0)
                labels = torch.cat(labels, dim=0).clamp(0.0, 1.0)

            inp = torch.cat([step_z, step_x, step_k0, step_ctrl, step_t], dim=-1)
            pred = torch.sigmoid(reasoner.evaluator(inp)).squeeze(-1)
            loss = mse(pred, labels)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(reasoner.evaluator.parameters(), 1.0)
            opt.step()

            total_loss += loss.item()
            total_binacc += ((pred > 0.5) == (labels > 0.5)).float().mean().item()

        print(f"Evaluator epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} | bin-acc {total_binacc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s")

# -----------------------------
# Rollouts
# -----------------------------
@torch.no_grad()
def rollout_mode(
    reasoner: MCLTRReasoner,
    x: torch.Tensor,
    start_ctrl: torch.Tensor,
    ctrl_seq: torch.Tensor,
    target: Optional[torch.Tensor] = None,
    mode: str = "continue",
    blend: float = 0.5,
    k0_override: Optional[torch.Tensor] = None,
    use_memory: bool = False,
):
    """
    mode:
      - continue
      - overwrite
      - restart
      - oracle
    """
    k0 = reasoner.knowledge(x) if k0_override is None else k0_override
    z0 = reasoner.init_state(x, k0, start_ctrl)
    z = z0

    mem = FailureMemory(MEM_CAPACITY, reasoner.z_dim, enabled=use_memory)
    if use_memory:
        mem.reset(x.size(0))

    actions = []
    per_step_probs = []

    for t in range(T):
        cand = reasoner.step_update(z, x, k0, ctrl_seq[:, t, :], t)
        if use_memory:
            cand = cand - mem.repel(cand)

        if mode == "continue":
            action = torch.zeros(x.size(0), dtype=torch.long, device=x.device)
            z_next = cand

        elif mode == "overwrite":
            action = torch.ones(x.size(0), dtype=torch.long, device=x.device)
            z_next = reasoner.overwrite_state(cand, z0, blend=blend)

        elif mode == "restart":
            action = torch.full((x.size(0),), 2, dtype=torch.long, device=x.device)
            z_next = z0

        elif mode == "oracle":
            if target is None:
                raise ValueError("oracle mode requires target")
            action, probs, _ = choose_oracle_action(reasoner, cand, z0, x, k0, start_ctrl, ctrl_seq, t, target, blend=blend)
            z_next = torch.empty_like(cand)
            # apply chosen action elementwise
            overwrite_mask = action == 1
            restart_mask = action == 2
            continue_mask = action == 0
            z_next[continue_mask] = cand[continue_mask]
            if overwrite_mask.any():
                z_next[overwrite_mask] = reasoner.overwrite_state(cand[overwrite_mask], z0[overwrite_mask], blend=blend)
            if restart_mask.any():
                z_next[restart_mask] = z0[restart_mask]
            per_step_probs.append(probs)

        else:
            raise ValueError(f"Unknown mode: {mode}")

        if use_memory:
            mem.update(cand, torch.zeros(cand.size(0), device=cand.device))

        actions.append(action)
        z = z_next

    logits = reasoner.decode(z)
    out = {
        "logits": logits,
        "actions": torch.stack(actions, dim=1),
        "k0": k0,
        "z0": z0,
    }
    if mode == "oracle":
        out["per_step_probs"] = torch.stack(per_step_probs, dim=1) if len(per_step_probs) > 0 else None
    return out

# -----------------------------
# Evaluation / diagnostics
# -----------------------------
@torch.no_grad()
def eval_base_classifier(base: BaseKnowledgeProvider, batches: int = 20, bs: int = 256):
    base.eval()
    total = 0
    correct = 0
    for _ in range(batches):
        idx = sample_indices(X_test.size(0), bs)
        xb = X_test[idx]
        yb = y_test[idx]
        logits = base(xb)
        pred = logits.argmax(dim=-1)
        correct += (pred == yb).sum().item()
        total += yb.numel()
    return correct / total

@torch.no_grad()
def eval_direct(direct_head: DirectStaticBaseline, level: int, batches: int = 20, bs: int = 256):
    direct_head.eval()
    total = 0
    correct = 0
    for _ in range(batches):
        x, digit_labels, start_mode, end_mode, start_ctrl, ctrl_seq, target = make_reasoning_batch(
            X_test, y_test, bs, level=level
        )
        logits = direct_head(x, start_ctrl)
        pred = logits.argmax(dim=-1)
        correct += (pred == target).sum().item()
        total += target.numel()
    return correct / total

@torch.no_grad()
def eval_rollout(reasoner: MCLTRReasoner, level: int, mode: str, blend: float, zero_knowledge: bool, batches: int = 20, bs: int = 256):
    reasoner.eval()
    total = 0
    correct = 0
    action_counts = torch.zeros(3, device=DEVICE)
    for _ in range(batches):
        x, digit_labels, start_mode, end_mode, start_ctrl, ctrl_seq, target = make_reasoning_batch(
            X_test, y_test, bs, level=level
        )
        k0_override = torch.zeros((bs, KNOWLEDGE_DIM), device=DEVICE) if zero_knowledge else None
        out = rollout_mode(
            reasoner,
            x,
            start_ctrl,
            ctrl_seq,
            target=target if mode == "oracle" else None,
            mode=mode,
            blend=blend,
            k0_override=k0_override,
            use_memory=USE_FAILURE_MEMORY,
        )
        pred = out["logits"].argmax(dim=-1)
        correct += (pred == target).sum().item()
        total += target.numel()
        action_counts += torch.stack([
            (out["actions"] == 0).sum(),
            (out["actions"] == 1).sum(),
            (out["actions"] == 2).sum(),
        ]).float()

    rates = (action_counts / (batches * bs * T)).cpu().numpy()
    return {
        "acc": correct / total,
        "continue_rate": float(rates[0]),
        "overwrite_rate": float(rates[1]),
        "restart_rate": float(rates[2]),
    }

@torch.no_grad()
def probe_actions(reasoner: MCLTRReasoner, level: int, blend: float, zero_knowledge: bool, batches: int = 8, bs: int = 128):
    """
    For each step:
      - compute mean final target probability if we continue / overwrite / restart
      - compute best-action rates
      - compute deltas relative to continue
    """
    reasoner.eval()

    best_counts = torch.zeros(T, 3, device=DEVICE)
    mean_probs = torch.zeros(T, 3, device=DEVICE)
    gain_over_continue = torch.zeros(T, device=DEVICE)
    gain_restart_over_continue = torch.zeros(T, device=DEVICE)

    for _ in range(batches):
        x, digit_labels, start_mode, end_mode, start_ctrl, ctrl_seq, target = make_reasoning_batch(
            X_test, y_test, bs, level=level
        )

        k0 = torch.zeros((bs, KNOWLEDGE_DIM), device=DEVICE) if zero_knowledge else reasoner.knowledge(x)
        z0 = reasoner.init_state(x, k0, start_ctrl)
        z = z0

        for t in range(T):
            cand = reasoner.step_update(z, x, k0, ctrl_seq[:, t, :], t)

            cont_state = cand
            over_state = reasoner.overwrite_state(cand, z0, blend=blend)
            rest_state = z0

            p_cont = final_target_prob_from_state(reasoner, cont_state, x, k0, start_ctrl, ctrl_seq, t + 1, target)
            p_over = final_target_prob_from_state(reasoner, over_state, x, k0, start_ctrl, ctrl_seq, t + 1, target)
            p_rest = final_target_prob_from_state(reasoner, rest_state, x, k0, start_ctrl, ctrl_seq, t + 1, target)

            probs = torch.stack([p_cont, p_over, p_rest], dim=-1)  # [B,3]
            best = probs.argmax(dim=-1)

            for a in range(3):
                best_counts[t, a] += (best == a).sum()

            mean_probs[t, 0] += p_cont.sum()
            mean_probs[t, 1] += p_over.sum()
            mean_probs[t, 2] += p_rest.sum()

            gain_over_continue[t] += (p_over - p_cont).sum()
            gain_restart_over_continue[t] += (p_rest - p_cont).sum()

            z = cand

    denom = batches * bs
    mean_probs = (mean_probs / denom).cpu().numpy()
    best_rates = (best_counts / denom).cpu().numpy()
    gain_over_continue = (gain_over_continue / denom).cpu().numpy()
    gain_restart_over_continue = (gain_restart_over_continue / denom).cpu().numpy()

    return {
        "mean_probs": mean_probs,                 # [T,3]
        "best_rates": best_rates,                 # [T,3]
        "gain_over_continue": gain_over_continue, # [T]
        "gain_restart_over_continue": gain_restart_over_continue,
    }

def print_probe_summary(probe: Dict, level: int, blend: float, zero_knowledge: bool):
    zk = "zero-knowledge" if zero_knowledge else "normal-knowledge"
    print(f"\n--- Action probe: level {level} ({LEVEL_NAMES[level]}), blend={blend:.2f}, {zk} ---")
    for t in range(T):
        mp = probe["mean_probs"][t]
        br = probe["best_rates"][t]
        g1 = probe["gain_over_continue"][t]
        g2 = probe["gain_restart_over_continue"][t]
        print(
            f"step {t}: mean p(cont/over/rest)=({mp[0]:.3f}, {mp[1]:.3f}, {mp[2]:.3f}) | "
            f"best rates=({br[0]:.3f}, {br[1]:.3f}, {br[2]:.3f}) | "
            f"Δover-cont={g1:+.4f} | Δrestart-cont={g2:+.4f}"
        )

# -----------------------------
# One experiment run
# -----------------------------
def run_one_seed_and_base_strength(seed: int, base_epochs: int):
    set_seed(seed)
    print("\n\n##############################")
    print(f"Seed = {seed} | base_epochs = {base_epochs}")
    print("##############################")

    base = BaseKnowledgeProvider().to(DEVICE)
    direct_head = DirectStaticBaseline(base).to(DEVICE)

    # Train the base knowledge provider
    print("\n=== Stage 1: base knowledge pretraining (digit classification) ===")
    opt_base = torch.optim.AdamW(base.parameters(), lr=LR_BASE, weight_decay=1e-4)
    ce_digits = nn.CrossEntropyLoss()
    for ep in range(base_epochs):
        t0 = time.time()
        total_loss = 0.0
        total_acc = 0.0
        for _ in range(BASE_STEPS_PER_EPOCH):
            idx = sample_indices(X_train.size(0), BATCH_SIZE)
            xb = X_train[idx]
            yb = y_train[idx]
            logits = base(xb)
            loss = ce_digits(logits, yb)

            opt_base.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(base.parameters(), 1.0)
            opt_base.step()

            total_loss += loss.item()
            total_acc += (logits.argmax(dim=-1) == yb).float().mean().item()
        print(f"Base epoch {ep+1}/{base_epochs} | loss {total_loss/BASE_STEPS_PER_EPOCH:.4f} | acc {total_acc/BASE_STEPS_PER_EPOCH:.4f} | {time.time()-t0:.1f}s")

    # Freeze a copy
    frozen_base = copy.deepcopy(base).to(DEVICE)
    for p in frozen_base.parameters():
        p.requires_grad = False

    # Train direct head
    direct_head.base = frozen_base
    print("\n=== Stage 2: direct static baseline head (no online control) ===")
    opt_direct = torch.optim.AdamW(direct_head.head.parameters(), lr=LR_DIRECT, weight_decay=1e-4)
    ce_task = nn.CrossEntropyLoss()
    for ep in range(DIRECT_EPOCHS):
        t0 = time.time()
        total_loss = 0.0
        total_acc = 0.0
        for _ in range(DIRECT_STEPS_PER_EPOCH):
            x, digit_labels, start_mode, end_mode, start_ctrl, ctrl_seq, target = make_reasoning_batch(
                X_train, y_train, BATCH_SIZE, level=random.choice(LEVELS)
            )
            logits = direct_head(x, start_ctrl)
            loss = ce_task(logits, target)

            opt_direct.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(direct_head.head.parameters(), 1.0)
            opt_direct.step()

            total_loss += loss.item()
            total_acc += (logits.argmax(dim=-1) == target).float().mean().item()
        print(f"Direct epoch {ep+1}/{DIRECT_EPOCHS} | loss {total_loss/DIRECT_STEPS_PER_EPOCH:.4f} | acc {total_acc/DIRECT_STEPS_PER_EPOCH:.4f} | {time.time()-t0:.1f}s")

    # Train reasoner
    reasoner = MCLTRReasoner(frozen_base).to(DEVICE)

    print("\n=== Stage 3: reasoner pretraining (continue-only rollouts, mixed levels) ===")
    set_requires_grad(reasoner.base, False)
    set_requires_grad(reasoner.init_net, True)
    set_requires_grad(reasoner.trans, True)
    set_requires_grad(reasoner.decoder, True)
    set_requires_grad(reasoner.evaluator, False)
    set_requires_grad(reasoner.k_proj, True)
    set_requires_grad(reasoner.ctrl_proj, True)
    set_requires_grad(reasoner.z_norm, True)

    params_reasoner = list(reasoner.init_net.parameters()) + list(reasoner.trans.parameters()) + list(reasoner.decoder.parameters()) + list(reasoner.k_proj.parameters()) + list(reasoner.ctrl_proj.parameters()) + list(reasoner.z_norm.parameters())
    opt_reasoner = torch.optim.AdamW(params_reasoner, lr=LR_REASONER, weight_decay=1e-4)

    for ep in range(REASONER_EPOCHS):
        t0 = time.time()
        total_loss = 0.0
        total_acc = 0.0
        for _ in range(REASONER_STEPS_PER_EPOCH):
            x, digit_labels, start_mode, end_mode, start_ctrl, ctrl_seq, target = make_reasoning_batch(
                X_train, y_train, BATCH_SIZE, level=random.choice(LEVELS)
            )
            k0 = reasoner.knowledge(x)
            z = reasoner.init_state(x, k0, start_ctrl)
            for t in range(T):
                z = reasoner.step_update(z, x, k0, ctrl_seq[:, t, :], t)
            logits = reasoner.decode(z)
            loss = ce_task(logits, target)

            opt_reasoner.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(params_reasoner, 1.0)
            opt_reasoner.step()

            total_loss += loss.item()
            total_acc += (logits.argmax(dim=-1) == target).float().mean().item()
        print(f"Reasoner epoch {ep+1}/{REASONER_EPOCHS} | loss {total_loss/REASONER_STEPS_PER_EPOCH:.4f} | acc {total_acc/REASONER_STEPS_PER_EPOCH:.4f} | {time.time()-t0:.1f}s")

    # Evaluator
    print("\n=== Stage 4: evaluator training (predict final correctness probability) ===")
    set_requires_grad(reasoner.evaluator, True)
    set_requires_grad(reasoner.init_net, False)
    set_requires_grad(reasoner.trans, False)
    set_requires_grad(reasoner.decoder, False)
    set_requires_grad(reasoner.k_proj, False)
    set_requires_grad(reasoner.ctrl_proj, False)
    set_requires_grad(reasoner.z_norm, False)

    opt_eval = torch.optim.AdamW(reasoner.evaluator.parameters(), lr=LR_EVAL, weight_decay=1e-4)
    mse = nn.MSELoss()

    for ep in range(EVAL_EPOCHS):
        t0 = time.time()
        total_loss = 0.0
        total_binacc = 0.0

        for _ in range(EVAL_STEPS_PER_EPOCH):
            x, digit_labels, start_mode, end_mode, start_ctrl, ctrl_seq, target = make_reasoning_batch(
                X_train, y_train, BATCH_SIZE, level=random.choice(LEVELS)
            )

            with torch.no_grad():
                k0 = reasoner.knowledge(x)
                z = reasoner.init_state(x, k0, start_ctrl)

                step_z = []
                step_x = []
                step_k0 = []
                step_ctrl = []
                step_t = []
                labels = []

                for t in range(T):
                    cand = reasoner.step_update(z, x, k0, ctrl_seq[:, t, :], t)
                    p_target = final_target_prob_from_state(reasoner, cand, x, k0, start_ctrl, ctrl_seq, t + 1, target)

                    step_z.append(cand.detach())
                    step_x.append(x.detach())
                    step_k0.append(k0.detach())
                    step_ctrl.append(ctrl_seq[:, t, :].detach())
                    step_t.append(step_feature(t, BATCH_SIZE, DEVICE))
                    labels.append(p_target.detach())
                    z = cand

                step_z = torch.cat(step_z, dim=0)
                step_x = torch.cat(step_x, dim=0)
                step_k0 = torch.cat(step_k0, dim=0)
                step_ctrl = torch.cat(step_ctrl, dim=0)
                step_t = torch.cat(step_t, dim=0)
                labels = torch.cat(labels, dim=0).clamp(0.0, 1.0)

            inp = torch.cat([step_z, step_x, step_k0, step_ctrl, step_t], dim=-1)
            pred = torch.sigmoid(reasoner.evaluator(inp)).squeeze(-1)
            loss = mse(pred, labels)

            opt_eval.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(reasoner.evaluator.parameters(), 1.0)
            opt_eval.step()

            total_loss += loss.item()
            total_binacc += ((pred > 0.5) == (labels > 0.5)).float().mean().item()

        print(f"Evaluator epoch {ep+1}/{EVAL_EPOCHS} | loss {total_loss/EVAL_STEPS_PER_EPOCH:.4f} | bin-acc {total_binacc/EVAL_STEPS_PER_EPOCH:.4f} | {time.time()-t0:.1f}s")

    # Baseline base accuracy
    base_acc = eval_base_classifier(base, batches=15, bs=256)

    # Now the diagnostic sweep:
    # - no policy training
    # - compare continue / overwrite / restart / oracle
    # - probe overwrite vs restart
    results = {}
    for level in LEVELS:
        results[level] = {}

        direct_acc = eval_direct(direct_head, level=level, batches=15, bs=256)
        cont_normal = eval_rollout(reasoner, level=level, mode="continue", blend=0.5, zero_knowledge=False, batches=15, bs=256)
        cont_zero = eval_rollout(reasoner, level=level, mode="continue", blend=0.5, zero_knowledge=True, batches=15, bs=256)

        results[level]["base_acc"] = base_acc
        results[level]["direct_acc"] = direct_acc
        results[level]["continue_normal"] = cont_normal["acc"]
        results[level]["continue_zero"] = cont_zero["acc"]

        for blend in OVERWRITE_BLENDS:
            over = eval_rollout(reasoner, level=level, mode="overwrite", blend=blend, zero_knowledge=False, batches=15, bs=256)
            rest = eval_rollout(reasoner, level=level, mode="restart", blend=blend, zero_knowledge=False, batches=15, bs=256)
            oracle = eval_rollout(reasoner, level=level, mode="oracle", blend=blend, zero_knowledge=False, batches=15, bs=256)
            probe = probe_actions(reasoner, level=level, blend=blend, zero_knowledge=False, batches=6, bs=128)
            probe_zero = probe_actions(reasoner, level=level, blend=blend, zero_knowledge=True, batches=6, bs=128)

            results[level][blend] = {
                "overwrite_acc": over["acc"],
                "restart_acc": rest["acc"],
                "oracle_acc": oracle["acc"],
                "oracle_c": oracle["continue_rate"],
                "oracle_o": oracle["overwrite_rate"],
                "oracle_r": oracle["restart_rate"],
                "probe": probe,
                "probe_zero": probe_zero,
            }

        print(f"\n--- Seed {seed} | base_epochs {base_epochs} | Level {level} ({LEVEL_NAMES[level]}) ---")
        print(f"Base classifier (digit ID only)      : {base_acc:.4f}")
        print(f"Direct static baseline              : {direct_acc:.4f}")
        print(f"M-CLTR continue-only (normal k0)    : {cont_normal['acc']:.4f}")
        print(f"M-CLTR continue-only (zero k0)      : {cont_zero['acc']:.4f}")
        print(f"Zero-knowledge gap                   : {cont_normal['acc'] - cont_zero['acc']:+.4f}")

        for blend in OVERWRITE_BLENDS:
            r = results[level][blend]
            print(f"\n  Blend={blend:.2f}")
            print(f"    Forced overwrite acc             : {r['overwrite_acc']:.4f}")
            print(f"    Forced restart acc               : {r['restart_acc']:.4f}")
            print(f"    Step-wise oracle acc             : {r['oracle_acc']:.4f}")
            print(f"    Oracle action rates C/O/R         : {r['oracle_c']:.3f}/{r['oracle_o']:.3f}/{r['oracle_r']:.3f}")
            print_probe_summary(r["probe"], level, blend, zero_knowledge=False)
            print_probe_summary(r["probe_zero"], level, blend, zero_knowledge=True)

    return results

# -----------------------------
# Run sweep
# -----------------------------
all_results = {}
for base_epochs in BASE_EPOCH_OPTIONS:
    all_results[base_epochs] = {}
    for seed in SEEDS:
        all_results[base_epochs][seed] = run_one_seed_and_base_strength(seed, base_epochs)

# -----------------------------
# Aggregate summary
# -----------------------------
print("\n\n==============================")
print("Aggregated summary across seeds and base strengths")
print("==============================")

for base_epochs in BASE_EPOCH_OPTIONS:
    print(f"\n################################")
    print(f"Base epochs = {base_epochs}")
    print(f"################################")
    for level in LEVELS:
        base_vals = []
        direct_vals = []
        cont_vals = []
        cont_zero_vals = []

        blend_summaries = {b: {"over": [], "rest": [], "oracle": [], "orc": [], "oro": [], "orr": [],
                               "probe_over": [], "probe_rest": [], "probe_best_over": [], "probe_best_rest": [],
                               "probe_over_zero": [], "probe_rest_zero": []}
                           for b in OVERWRITE_BLENDS}

        for seed in SEEDS:
            rr = all_results[base_epochs][seed][level]
            base_vals.append(rr["base_acc"])
            direct_vals.append(rr["direct_acc"])
            cont_vals.append(rr["continue_normal"])
            cont_zero_vals.append(rr["continue_zero"])

            for b in OVERWRITE_BLENDS:
                r = rr[b]
                blend_summaries[b]["over"].append(r["overwrite_acc"])
                blend_summaries[b]["rest"].append(r["restart_acc"])
                blend_summaries[b]["oracle"].append(r["oracle_acc"])
                blend_summaries[b]["orc"].append(r["oracle_c"])
                blend_summaries[b]["oro"].append(r["oracle_o"])
                blend_summaries[b]["orr"].append(r["oracle_r"])

                blend_summaries[b]["probe_over"].append(float(r["probe"]["gain_over_continue"].mean()))
                blend_summaries[b]["probe_rest"].append(float(r["probe"]["gain_restart_over_continue"].mean()))
                blend_summaries[b]["probe_best_over"].append(float(r["probe"]["best_rates"][:, 1].mean()))
                blend_summaries[b]["probe_best_rest"].append(float(r["probe"]["best_rates"][:, 2].mean()))

                blend_summaries[b]["probe_over_zero"].append(float(r["probe_zero"]["gain_over_continue"].mean()))
                blend_summaries[b]["probe_rest_zero"].append(float(r["probe_zero"]["gain_restart_over_continue"].mean()))

        bm, bs = mean_std(base_vals)
        dm, ds = mean_std(direct_vals)
        cm, cs = mean_std(cont_vals)
        czm, czs = mean_std(cont_zero_vals)

        print(f"\nLevel {level} ({LEVEL_NAMES[level]})")
        print(f"  Base classifier              : {bm:.4f} ± {bs:.4f}")
        print(f"  Direct static baseline       : {dm:.4f} ± {ds:.4f}")
        print(f"  Continue-only (normal k0)    : {cm:.4f} ± {cs:.4f}")
        print(f"  Continue-only (zero k0)      : {czm:.4f} ± {czs:.4f}")
        print(f"  Zero-knowledge gap           : {(cm - czm):+.4f}")

        for b in OVERWRITE_BLENDS:
            om, os = mean_std(blend_summaries[b]["over"])
            rm, rs = mean_std(blend_summaries[b]["rest"])
            qm, qs = mean_std(blend_summaries[b]["oracle"])
            orc_m, orc_s = mean_std(blend_summaries[b]["orc"])
            oro_m, oro_s = mean_std(blend_summaries[b]["oro"])
            orr_m, orr_s = mean_std(blend_summaries[b]["orr"])
            go_m, go_s = mean_std(blend_summaries[b]["probe_over"])
            gr_m, gr_s = mean_std(blend_summaries[b]["probe_rest"])
            bo_m, bo_s = mean_std(blend_summaries[b]["probe_best_over"])
            br_m, br_s = mean_std(blend_summaries[b]["probe_best_rest"])
            goz_m, goz_s = mean_std(blend_summaries[b]["probe_over_zero"])
            grz_m, grz_s = mean_std(blend_summaries[b]["probe_rest_zero"])

            print(f"\n  Blend={b:.2f}")
            print(f"    Forced overwrite acc        : {om:.4f} ± {os:.4f}")
            print(f"    Forced restart acc          : {rm:.4f} ± {rs:.4f}")
            print(f"    Step-wise oracle acc        : {qm:.4f} ± {qs:.4f}")
            print(f"    Oracle action rates C/O/R   : {orc_m:.3f} ± {orc_s:.3f} / {oro_m:.3f} ± {oro_s:.3f} / {orr_m:.3f} ± {orr_s:.3f}")
            print(f"    Probe mean Δ(over-cont)     : {go_m:+.4f} ± {go_s:.4f}")
            print(f"    Probe mean Δ(rest-cont)     : {gr_m:+.4f} ± {gr_s:.4f}")
            print(f"    Probe best-action overwrite : {bo_m:.3f} ± {bo_s:.3f}")
            print(f"    Probe best-action restart   : {br_m:.3f} ± {br_s:.3f}")
            print(f"    Zero-k Δ(over-cont)         : {goz_m:+.4f} ± {goz_s:.4f}")
            print(f"    Zero-k Δ(rest-cont)         : {grz_m:+.4f} ± {grz_s:.4f}")

print("\nDone.")

# M-CLTR v5 — overwrite vs restart stress test with stronger diagnostics
# CPU-friendly, multi-seed, digits data
#
# What this version changes:
# 1) Base model is kept separate and swappable.
# 2) Reasoning layer is separate from knowledge.
# 3) No learned policy is trained here; instead we probe the actual effect of actions.
# 4) Overwrite is tested in several measurable forms:
#    - fixed blend
#    - gated blend using evaluator score
#    - clipped correction
# 5) We sweep base strength so you can see whether overwrite fails because of
#    the base, the overwrite math, or both.
#
# Main question answered by the output:
#   "When does overwrite beat restart, and what makes it happen?"

import copy
import math
import random
import time
from typing import Dict, List, Optional, Tuple

import numpy as np
import torch
import torch.nn as nn
import torch.nn.functional as F

from sklearn.datasets import load_digits
from sklearn.model_selection import train_test_split

# -----------------------------
# Device / reproducibility
# -----------------------------
DEVICE = torch.device("cuda" if torch.cuda.is_available() else "cpu")
print("Device:", DEVICE)

def set_seed(seed: int):
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    if torch.cuda.is_available():
        torch.cuda.manual_seed_all(seed)

# -----------------------------
# Config
# -----------------------------
T = 6
LATENT_DIM = 96
KNOWLEDGE_DIM = 64
NUM_CLASSES = 2

BATCH_SIZE = 96

SEEDS = [7, 17]
BASE_EPOCH_OPTIONS = [1, 4, 8]  # weak / medium / strong base

BASE_STEPS_PER_EPOCH = 35
DIRECT_STEPS_PER_EPOCH = 35
REASONER_STEPS_PER_EPOCH = 35
EVAL_STEPS_PER_EPOCH = 35

LR_BASE = 2e-3
LR_DIRECT = 2e-3
LR_REASONER = 2e-3
LR_EVAL = 2e-3

# Reasoning dynamics
CARRY_Z = 0.86
DELTA_W = 0.10
CTRL_W = 0.02
K_W = 0.02

# Levels
LEVELS = [0, 1, 2, 3]
LEVEL_NAMES = {
    0: "easy / no switch",
    1: "medium / mid switch",
    2: "hard / early switch",
    3: "switch + noisy input",
}
LEVEL_TO_SWITCH_STEP = {
    0: T,
    1: T // 2,
    2: 1,
    3: T // 2,
}
NOISE_SIGMA_LEVEL3 = 0.25

# Overwrite diagnostics
FIXED_OVERWRITE_ALPHAS = [0.2, 0.5, 0.8]
CLIPPED_OVERWRITE_STEPS = [0.75, 1.5, 3.0]
GATED_OVERWRITE_BOUNDS = [(0.05, 0.95), (0.10, 0.90)]

# Optional failure memory. Keep off first for clean overwrite-vs-restart diagnosis.
USE_FAILURE_MEMORY = False
MEM_CAPACITY = 6
MEM_BETA = 0.18
MEM_GAMMA = 0.35
MEM_STORE_THR = 0.35

# -----------------------------
# Data
# -----------------------------
digits = load_digits()
X_all = torch.tensor(digits.data, dtype=torch.float32) / 16.0
y_all = torch.tensor(digits.target, dtype=torch.long)

X_train_np, X_test_np, y_train_np, y_test_np = train_test_split(
    X_all.numpy(),
    y_all.numpy(),
    test_size=0.30,
    random_state=0,
    stratify=y_all.numpy(),
)

X_train = torch.tensor(X_train_np, dtype=torch.float32, device=DEVICE)
y_train = torch.tensor(y_train_np, dtype=torch.long, device=DEVICE)
X_test = torch.tensor(X_test_np, dtype=torch.float32, device=DEVICE)
y_test = torch.tensor(y_test_np, dtype=torch.long, device=DEVICE)

X_DIM = X_train.shape[1]

# -----------------------------
# Utilities
# -----------------------------
def one_hot(v: torch.Tensor, n: int) -> torch.Tensor:
    return F.one_hot(v.long(), n).float()

def sample_indices(n: int, batch_size: int) -> torch.Tensor:
    return torch.randint(0, n, (batch_size,), device=DEVICE)

def step_feature(t: int, batch_size: int, device: torch.device) -> torch.Tensor:
    s = 0.0 if T <= 1 else float(t) / float(T - 1)
    return torch.full((batch_size, 1), s, device=device)

def task_value(digit_labels: torch.Tensor, mode: torch.Tensor) -> torch.Tensor:
    # mode 0 = parity, mode 1 = high/low
    parity = (digit_labels % 2).long()
    highlow = (digit_labels >= 5).long()
    return torch.where(mode == 0, parity, highlow)

def make_reasoning_batch(
    x_pool: torch.Tensor,
    y_pool: torch.Tensor,
    batch_size: int,
    level: int = 0,
):
    idx = sample_indices(x_pool.size(0), batch_size)
    x = x_pool[idx].clone()
    digit_labels = y_pool[idx]

    if level == 3:
        x = torch.clamp(x + NOISE_SIGMA_LEVEL3 * torch.randn_like(x), 0.0, 1.0)

    start_mode = torch.randint(0, 2, (batch_size,), device=DEVICE)
    switch_step = LEVEL_TO_SWITCH_STEP[level]
    end_mode = start_mode.clone() if level == 0 else 1 - start_mode

    start_ctrl = one_hot(start_mode, 2)

    ctrl_seq = []
    for t in range(T):
        current_mode = torch.where(torch.full_like(start_mode, t) < switch_step, start_mode, end_mode)
        ctrl_seq.append(one_hot(current_mode, 2))
    ctrl_seq = torch.stack(ctrl_seq, dim=1)  # [B, T, 2]

    final_mode = torch.where(torch.full_like(start_mode, T - 1) < switch_step, start_mode, end_mode)
    target = task_value(digit_labels, final_mode)

    return x, digit_labels, start_mode, end_mode, start_ctrl, ctrl_seq, target

def mean_std(values):
    arr = np.array(values, dtype=np.float64)
    if len(arr) == 1:
        return float(arr[0]), 0.0
    return float(arr.mean()), float(arr.std(ddof=1))

def set_requires_grad(module: nn.Module, flag: bool):
    for p in module.parameters():
        p.requires_grad = flag

# -----------------------------
# Modules
# -----------------------------
class MLP(nn.Module):
    def __init__(self, in_dim: int, out_dim: int, hidden: int = 128):
        super().__init__()
        self.net = nn.Sequential(
            nn.Linear(in_dim, hidden),
            nn.GELU(),
            nn.Linear(hidden, hidden),
            nn.GELU(),
            nn.Linear(hidden, out_dim),
        )

    def forward(self, x):
        return self.net(x)

class BaseKnowledgeProvider(nn.Module):
    """
    Base model:
      x -> knowledge vector k0
      k0 -> digit classifier
    """
    def __init__(self, x_dim: int = X_DIM, k_dim: int = KNOWLEDGE_DIM):
        super().__init__()
        self.encoder = nn.Sequential(
            nn.Linear(x_dim, 128),
            nn.GELU(),
            nn.Linear(128, k_dim),
            nn.LayerNorm(k_dim),
        )
        self.classifier = nn.Sequential(
            nn.Linear(k_dim, 64),
            nn.GELU(),
            nn.Linear(64, 10),
        )

        for m in self.modules():
            if isinstance(m, nn.Linear):
                nn.init.xavier_uniform_(m.weight)
                if m.bias is not None:
                    nn.init.zeros_(m.bias)

    def encode(self, x: torch.Tensor) -> torch.Tensor:
        return self.encoder(x)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.classifier(self.encode(x))

class DirectStaticBaseline(nn.Module):
    """
    Static baseline:
      uses base knowledge + start mode only.
    """
    def __init__(self, base: BaseKnowledgeProvider, k_dim: int = KNOWLEDGE_DIM):
        super().__init__()
        self.base = base
        self.head = MLP(k_dim + 2, NUM_CLASSES, hidden=96)

    def forward(self, x: torch.Tensor, start_ctrl: torch.Tensor) -> torch.Tensor:
        with torch.no_grad():
            k0 = self.base.encode(x)
        inp = torch.cat([k0, start_ctrl], dim=-1)
        return self.head(inp)

class FailureMemory:
    def __init__(self, capacity: int, z_dim: int, enabled: bool = False,
                 beta: float = 0.18, gamma: float = 0.35, store_thr: float = 0.35):
        self.capacity = capacity
        self.z_dim = z_dim
        self.enabled = enabled
        self.beta = beta
        self.gamma = gamma
        self.store_thr = store_thr
        self.mem = None
        self.age = None
        self.mask = None
        self.ptr = None

    def reset(self, batch_size: int):
        self.mem = torch.zeros(batch_size, self.capacity, self.z_dim, device=DEVICE)
        self.age = torch.zeros(batch_size, self.capacity, device=DEVICE)
        self.mask = torch.zeros(batch_size, self.capacity, dtype=torch.bool, device=DEVICE)
        self.ptr = torch.zeros(batch_size, dtype=torch.long, device=DEVICE)

    def repel(self, z: torch.Tensor) -> torch.Tensor:
        if not self.enabled or self.mem is None:
            return torch.zeros_like(z)
        zexp = z.unsqueeze(1)
        diff = zexp - self.mem
        dist = diff.norm(dim=-1, keepdim=True).clamp_min(1e-6)
        direction = diff / dist

        znorm = F.normalize(zexp.expand_as(self.mem), dim=-1)
        mnorm = F.normalize(self.mem.clamp_min(1e-6), dim=-1)
        sim = (znorm * mnorm).sum(dim=-1)

        weights = self.mask.float() * torch.exp(-self.gamma * self.age.float())
        rep = (weights.unsqueeze(-1) * sim.unsqueeze(-1) * direction).sum(dim=1)
        return self.beta * rep

    def update(self, cand: torch.Tensor, score: torch.Tensor):
        if not self.enabled or self.mem is None:
            return
        self.age[self.mask] += 1.0
        low = score < self.store_thr
        idx = torch.where(low)[0]
        if idx.numel() == 0:
            return
        slots = self.ptr[idx] % self.capacity
        self.mem[idx, slots] = cand.detach()[idx]
        self.age[idx, slots] = 0.0
        self.mask[idx, slots] = True
        self.ptr[idx] = (self.ptr[idx] + 1) % self.capacity

class MCLTRReasoner(nn.Module):
    """
    M-CLTR reasoning layer:
      base model supplies knowledge k0,
      reasoner performs latent trajectory control.
    """
    def __init__(self, base: BaseKnowledgeProvider, x_dim: int = X_DIM, k_dim: int = KNOWLEDGE_DIM, z_dim: int = LATENT_DIM):
        super().__init__()
        self.base = base
        self.x_dim = x_dim
        self.k_dim = k_dim
        self.z_dim = z_dim

        self.init_net = MLP(x_dim + k_dim + 2, z_dim, hidden=128)
        self.trans = MLP(z_dim + x_dim + k_dim + 2 + 1, z_dim, hidden=128)
        self.decoder = nn.Linear(z_dim, NUM_CLASSES)

        self.evaluator = MLP(z_dim + x_dim + k_dim + 2 + 1, 1, hidden=96)

        self.z_norm = nn.LayerNorm(z_dim)
        self.k_proj = nn.Linear(k_dim, z_dim)
        self.ctrl_proj = nn.Linear(2, z_dim)

        for m in self.modules():
            if isinstance(m, nn.Linear):
                nn.init.xavier_uniform_(m.weight)
                if m.bias is not None:
                    nn.init.zeros_(m.bias)

    def knowledge(self, x):
        return self.base.encode(x)

    def build_step_input(self, z, x, k0, ctrl, t: int):
        return torch.cat([z, x, k0, ctrl, step_feature(t, z.size(0), z.device)], dim=-1)

    def init_state(self, x, k0, start_ctrl):
        z0 = self.init_net(torch.cat([x, k0, start_ctrl], dim=-1))
        return self.z_norm(z0)

    def step_update(self, z, x, k0, ctrl, t: int):
        inp = self.build_step_input(z, x, k0, ctrl, t)
        delta = torch.tanh(self.trans(inp))
        ctrl_shift = torch.tanh(self.ctrl_proj(ctrl))
        k_shift = torch.tanh(self.k_proj(k0))
        cand = self.z_norm(
            CARRY_Z * z
            + DELTA_W * delta
            + CTRL_W * ctrl_shift
            + K_W * k_shift
        )
        return cand

    def eval_score(self, z, x, k0, ctrl, t: int):
        inp = self.build_step_input(z, x, k0, ctrl, t)
        return torch.sigmoid(self.evaluator(inp)).squeeze(-1)

    def decode(self, z):
        return self.decoder(z)

# -----------------------------
# Overwrite operators
# -----------------------------
def overwrite_fixed_blend(cand: torch.Tensor, z0: torch.Tensor, alpha: float) -> torch.Tensor:
    # alpha=1 means keep candidate; alpha=0 means full restart anchor
    return z0 + alpha * (cand - z0)

def overwrite_clipped(cand: torch.Tensor, z0: torch.Tensor, max_step: float) -> torch.Tensor:
    # Move from z0 toward cand but clip the step size in latent space.
    delta = cand - z0
    norm = delta.norm(dim=-1, keepdim=True).clamp_min(1e-6)
    scale = torch.clamp(max_step / norm, max=1.0)
    return z0 + delta * scale

def overwrite_gated_by_score(
    cand: torch.Tensor,
    z0: torch.Tensor,
    score: torch.Tensor,
    alpha_min: float = 0.10,
    alpha_max: float = 0.90,
) -> torch.Tensor:
    # Higher evaluator score => keep more of cand.
    alpha = alpha_min + (alpha_max - alpha_min) * score.unsqueeze(-1)
    return z0 + alpha * (cand - z0)

# -----------------------------
# Oracle utilities
# -----------------------------
@torch.no_grad()
def rollout_continue_only_from_state(
    reasoner: MCLTRReasoner,
    z_start: torch.Tensor,
    x: torch.Tensor,
    k0: torch.Tensor,
    start_ctrl: torch.Tensor,
    ctrl_seq: torch.Tensor,
    start_t: int,
    target: torch.Tensor,
):
    z = z_start
    mem = FailureMemory(MEM_CAPACITY, reasoner.z_dim, enabled=USE_FAILURE_MEMORY)
    if USE_FAILURE_MEMORY:
        mem.reset(z.size(0))

    for t in range(start_t, T):
        cand = reasoner.step_update(z, x, k0, ctrl_seq[:, t, :], t)
        if USE_FAILURE_MEMORY:
            cand = cand - mem.repel(cand)
            mem.update(cand, torch.zeros(cand.size(0), device=cand.device))
        z = cand

    logits = reasoner.decode(z)
    probs = F.softmax(logits, dim=-1)
    return probs.gather(1, target.unsqueeze(1)).squeeze(1)

@torch.no_grad()
def stepwise_oracle_action(
    reasoner: MCLTRReasoner,
    cand: torch.Tensor,
    z0: torch.Tensor,
    x: torch.Tensor,
    k0: torch.Tensor,
    start_ctrl: torch.Tensor,
    ctrl_seq: torch.Tensor,
    t: int,
    target: torch.Tensor,
    overwrite_kind: str,
    overwrite_arg,
):
    """
    Returns best action among:
      continue, overwrite, restart
    based on final target probability after finishing the rollout.
    """
    if overwrite_kind == "fixed":
        over_state = overwrite_fixed_blend(cand, z0, float(overwrite_arg))
    elif overwrite_kind == "clip":
        over_state = overwrite_clipped(cand, z0, float(overwrite_arg))
    elif overwrite_kind == "gated":
        # evaluator score is used only as a gating signal here
        score = reasoner.eval_score(cand, x, k0, ctrl_seq[:, t, :], t)
        alpha_min, alpha_max = overwrite_arg
        over_state = overwrite_gated_by_score(cand, z0, score, alpha_min=alpha_min, alpha_max=alpha_max)
    else:
        raise ValueError(f"Unknown overwrite_kind: {overwrite_kind}")

    cont_prob = rollout_continue_only_from_state(reasoner, cand, x, k0, start_ctrl, ctrl_seq, t + 1, target)
    over_prob = rollout_continue_only_from_state(reasoner, over_state, x, k0, start_ctrl, ctrl_seq, t + 1, target)
    rest_prob = rollout_continue_only_from_state(reasoner, z0, x, k0, start_ctrl, ctrl_seq, t + 1, target)

    probs = torch.stack([cont_prob, over_prob, rest_prob], dim=-1)  # [B,3]
    action = probs.argmax(dim=-1)
    return action, probs

# -----------------------------
# Training
# -----------------------------
def train_base(base: BaseKnowledgeProvider, epochs: int, steps_per_epoch: int):
    base.train()
    opt = torch.optim.AdamW(base.parameters(), lr=LR_BASE, weight_decay=1e-4)
    loss_fn = nn.CrossEntropyLoss()

    print("\n=== Stage 1: base knowledge pretraining (digit classification) ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_acc = 0.0
        for _ in range(steps_per_epoch):
            idx = sample_indices(X_train.size(0), BATCH_SIZE)
            xb = X_train[idx]
            yb = y_train[idx]

            logits = base(xb)
            loss = loss_fn(logits, yb)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(base.parameters(), 1.0)
            opt.step()

            total_loss += loss.item()
            total_acc += (logits.argmax(dim=-1) == yb).float().mean().item()

        print(f"Base epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} | acc {total_acc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s")

def train_direct_head(direct_head: DirectStaticBaseline, epochs: int, steps_per_epoch: int):
    direct_head.train()
    set_requires_grad(direct_head.base, False)
    opt = torch.optim.AdamW(direct_head.head.parameters(), lr=LR_DIRECT, weight_decay=1e-4)
    loss_fn = nn.CrossEntropyLoss()

    print("\n=== Stage 2: direct static baseline head (no online control) ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_acc = 0.0
        for _ in range(steps_per_epoch):
            x, _, _, _, start_ctrl, _, target = make_reasoning_batch(X_train, y_train, BATCH_SIZE, level=random.choice(LEVELS))
            logits = direct_head(x, start_ctrl)
            loss = loss_fn(logits, target)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(direct_head.head.parameters(), 1.0)
            opt.step()

            total_loss += loss.item()
            total_acc += (logits.argmax(dim=-1) == target).float().mean().item()

        print(f"Direct epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} | acc {total_acc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s")

def train_reasoner_continue(reasoner: MCLTRReasoner, epochs: int, steps_per_epoch: int):
    reasoner.train()
    set_requires_grad(reasoner.base, False)
    set_requires_grad(reasoner.init_net, True)
    set_requires_grad(reasoner.trans, True)
    set_requires_grad(reasoner.decoder, True)
    set_requires_grad(reasoner.evaluator, False)
    set_requires_grad(reasoner.k_proj, True)
    set_requires_grad(reasoner.ctrl_proj, True)
    set_requires_grad(reasoner.z_norm, True)

    params = (
        list(reasoner.init_net.parameters()) +
        list(reasoner.trans.parameters()) +
        list(reasoner.decoder.parameters()) +
        list(reasoner.k_proj.parameters()) +
        list(reasoner.ctrl_proj.parameters()) +
        list(reasoner.z_norm.parameters())
    )
    opt = torch.optim.AdamW(params, lr=LR_REASONER, weight_decay=1e-4)
    loss_fn = nn.CrossEntropyLoss()

    print("\n=== Stage 3: reasoner pretraining (continue-only rollouts, mixed levels) ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_acc = 0.0
        for _ in range(steps_per_epoch):
            x, _, _, _, start_ctrl, ctrl_seq, target = make_reasoning_batch(
                X_train, y_train, BATCH_SIZE, level=random.choice(LEVELS)
            )
            k0 = reasoner.knowledge(x)
            z = reasoner.init_state(x, k0, start_ctrl)
            for t in range(T):
                z = reasoner.step_update(z, x, k0, ctrl_seq[:, t, :], t)

            logits = reasoner.decode(z)
            loss = loss_fn(logits, target)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(params, 1.0)
            opt.step()

            total_loss += loss.item()
            total_acc += (logits.argmax(dim=-1) == target).float().mean().item()

        print(f"Reasoner epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} | acc {total_acc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s")

def train_evaluator(reasoner: MCLTRReasoner, epochs: int, steps_per_epoch: int):
    reasoner.eval()
    set_requires_grad(reasoner.base, False)
    set_requires_grad(reasoner.init_net, False)
    set_requires_grad(reasoner.trans, False)
    set_requires_grad(reasoner.decoder, False)
    set_requires_grad(reasoner.evaluator, True)
    set_requires_grad(reasoner.k_proj, False)
    set_requires_grad(reasoner.ctrl_proj, False)
    set_requires_grad(reasoner.z_norm, False)

    opt = torch.optim.AdamW(reasoner.evaluator.parameters(), lr=LR_EVAL, weight_decay=1e-4)
    mse = nn.MSELoss()

    print("\n=== Stage 4: evaluator training (predict final correctness probability) ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_binacc = 0.0

        for _ in range(steps_per_epoch):
            x, _, _, _, start_ctrl, ctrl_seq, target = make_reasoning_batch(
                X_train, y_train, BATCH_SIZE, level=random.choice(LEVELS)
            )

            with torch.no_grad():
                k0 = reasoner.knowledge(x)
                z = reasoner.init_state(x, k0, start_ctrl)

                step_z, step_x, step_k0, step_ctrl, step_t, labels = [], [], [], [], [], []

                for t in range(T):
                    cand = reasoner.step_update(z, x, k0, ctrl_seq[:, t, :], t)
                    p_target = rollout_continue_only_from_state(
                        reasoner, cand, x, k0, start_ctrl, ctrl_seq, t + 1, target
                    )

                    step_z.append(cand.detach())
                    step_x.append(x.detach())
                    step_k0.append(k0.detach())
                    step_ctrl.append(ctrl_seq[:, t, :].detach())
                    step_t.append(step_feature(t, BATCH_SIZE, DEVICE))
                    labels.append(p_target.detach())
                    z = cand

                step_z = torch.cat(step_z, dim=0)
                step_x = torch.cat(step_x, dim=0)
                step_k0 = torch.cat(step_k0, dim=0)
                step_ctrl = torch.cat(step_ctrl, dim=0)
                step_t = torch.cat(step_t, dim=0)
                labels = torch.cat(labels, dim=0).clamp(0.0, 1.0)

            inp = torch.cat([step_z, step_x, step_k0, step_ctrl, step_t], dim=-1)
            pred = torch.sigmoid(reasoner.evaluator(inp)).squeeze(-1)
            loss = mse(pred, labels)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(reasoner.evaluator.parameters(), 1.0)
            opt.step()

            total_loss += loss.item()
            total_binacc += ((pred > 0.5) == (labels > 0.5)).float().mean().item()

        print(f"Evaluator epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} | bin-acc {total_binacc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s")

# -----------------------------
# Evaluation helpers
# -----------------------------
@torch.no_grad()
def eval_base_classifier(base: BaseKnowledgeProvider, batches: int = 20, bs: int = 256):
    base.eval()
    total = 0
    correct = 0
    for _ in range(batches):
        idx = sample_indices(X_test.size(0), bs)
        xb = X_test[idx]
        yb = y_test[idx]
        logits = base(xb)
        pred = logits.argmax(dim=-1)
        correct += (pred == yb).sum().item()
        total += yb.numel()
    return correct / total

@torch.no_grad()
def eval_direct(direct_head: DirectStaticBaseline, level: int, batches: int = 20, bs: int = 256):
    direct_head.eval()
    total = 0
    correct = 0
    for _ in range(batches):
        x, _, _, _, start_ctrl, _, target = make_reasoning_batch(X_test, y_test, bs, level=level)
        logits = direct_head(x, start_ctrl)
        pred = logits.argmax(dim=-1)
        correct += (pred == target).sum().item()
        total += target.numel()
    return correct / total

@torch.no_grad()
def run_rollout(
    reasoner: MCLTRReasoner,
    x: torch.Tensor,
    start_ctrl: torch.Tensor,
    ctrl_seq: torch.Tensor,
    mode: str,
    overwrite_kind: Optional[str] = None,
    overwrite_arg=None,
    target: Optional[torch.Tensor] = None,
    zero_knowledge: bool = False,
):
    k0 = torch.zeros((x.size(0), KNOWLEDGE_DIM), device=DEVICE) if zero_knowledge else reasoner.knowledge(x)
    z0 = reasoner.init_state(x, k0, start_ctrl)
    z = z0

    mem = FailureMemory(MEM_CAPACITY, reasoner.z_dim, enabled=USE_FAILURE_MEMORY)
    if USE_FAILURE_MEMORY:
        mem.reset(x.size(0))

    actions = []

    for t in range(T):
        cand = reasoner.step_update(z, x, k0, ctrl_seq[:, t, :], t)
        if USE_FAILURE_MEMORY:
            cand = cand - mem.repel(cand)

        if mode == "continue":
            action = torch.zeros(x.size(0), dtype=torch.long, device=x.device)
            z_next = cand

        elif mode == "restart":
            action = torch.full((x.size(0),), 2, dtype=torch.long, device=x.device)
            z_next = z0

        elif mode == "overwrite":
            if overwrite_kind is None:
                raise ValueError("overwrite mode requires overwrite_kind")
            if overwrite_kind == "fixed":
                z_next = overwrite_fixed_blend(cand, z0, float(overwrite_arg))
            elif overwrite_kind == "clip":
                z_next = overwrite_clipped(cand, z0, float(overwrite_arg))
            elif overwrite_kind == "gated":
                score = reasoner.eval_score(cand, x, k0, ctrl_seq[:, t, :], t)
                alpha_min, alpha_max = overwrite_arg
                z_next = overwrite_gated_by_score(cand, z0, score, alpha_min=alpha_min, alpha_max=alpha_max)
            else:
                raise ValueError(f"Unknown overwrite_kind: {overwrite_kind}")
            action = torch.ones(x.size(0), dtype=torch.long, device=x.device)

        elif mode == "oracle":
            if target is None:
                raise ValueError("oracle mode requires target")
            if overwrite_kind is None:
                raise ValueError("oracle mode requires overwrite_kind")
            action, _ = stepwise_oracle_action(
                reasoner, cand, z0, x, k0, start_ctrl, ctrl_seq, t, target,
                overwrite_kind=overwrite_kind, overwrite_arg=overwrite_arg
            )
            z_next = torch.empty_like(cand)
            cont_mask = action == 0
            over_mask = action == 1
            rest_mask = action == 2
            z_next[cont_mask] = cand[cont_mask]
            if over_mask.any():
                if overwrite_kind == "fixed":
                    z_next[over_mask] = overwrite_fixed_blend(cand[over_mask], z0[over_mask], float(overwrite_arg))
                elif overwrite_kind == "clip":
                    z_next[over_mask] = overwrite_clipped(cand[over_mask], z0[over_mask], float(overwrite_arg))
                elif overwrite_kind == "gated":
                    score = reasoner.eval_score(cand, x, k0, ctrl_seq[:, t, :], t)
                    alpha_min, alpha_max = overwrite_arg
                    z_next[over_mask] = overwrite_gated_by_score(
                        cand[over_mask], z0[over_mask], score[over_mask], alpha_min=alpha_min, alpha_max=alpha_max
                    )
            if rest_mask.any():
                z_next[rest_mask] = z0[rest_mask]

        else:
            raise ValueError(f"Unknown mode: {mode}")

        if USE_FAILURE_MEMORY:
            mem.update(cand, torch.zeros(cand.size(0), device=cand.device))

        actions.append(action)
        z = z_next

    logits = reasoner.decode(z)
    return logits, torch.stack(actions, dim=1), k0, z0

@torch.no_grad()
def eval_rollout(
    reasoner: MCLTRReasoner,
    level: int,
    mode: str,
    overwrite_kind: Optional[str],
    overwrite_arg,
    zero_knowledge: bool,
    batches: int = 20,
    bs: int = 256,
):
    reasoner.eval()
    total = 0
    correct = 0
    action_counts = torch.zeros(3, device=DEVICE)

    for _ in range(batches):
        x, _, _, _, start_ctrl, ctrl_seq, target = make_reasoning_batch(X_test, y_test, bs, level=level)
        logits, actions, _, _ = run_rollout(
            reasoner,
            x,
            start_ctrl,
            ctrl_seq,
            mode=mode,
            overwrite_kind=overwrite_kind,
            overwrite_arg=overwrite_arg,
            target=target if mode == "oracle" else None,
            zero_knowledge=zero_knowledge,
        )
        pred = logits.argmax(dim=-1)
        correct += (pred == target).sum().item()
        total += target.numel()
        action_counts += torch.stack([
            (actions == 0).sum(),
            (actions == 1).sum(),
            (actions == 2).sum(),
        ]).float()

    rates = (action_counts / (batches * bs * T)).cpu().numpy()
    return {
        "acc": correct / total,
        "continue_rate": float(rates[0]),
        "overwrite_rate": float(rates[1]),
        "restart_rate": float(rates[2]),
    }

@torch.no_grad()
def probe_actions(
    reasoner: MCLTRReasoner,
    level: int,
    overwrite_kind: str,
    overwrite_arg,
    zero_knowledge: bool,
    batches: int = 6,
    bs: int = 128,
):
    """
    For each step:
      - mean final target prob for continue / overwrite / restart
      - best-action rates
      - delta vs continue
    """
    reasoner.eval()

    best_counts = torch.zeros(T, 3, device=DEVICE)
    mean_probs = torch.zeros(T, 3, device=DEVICE)
    gain_over_continue = torch.zeros(T, device=DEVICE)
    gain_restart_over_continue = torch.zeros(T, device=DEVICE)

    for _ in range(batches):
        x, _, _, _, start_ctrl, ctrl_seq, target = make_reasoning_batch(X_test, y_test, bs, level=level)
        k0 = torch.zeros((bs, KNOWLEDGE_DIM), device=DEVICE) if zero_knowledge else reasoner.knowledge(x)
        z0 = reasoner.init_state(x, k0, start_ctrl)
        z = z0

        for t in range(T):
            cand = reasoner.step_update(z, x, k0, ctrl_seq[:, t, :], t)

            # continue
            cont_state = cand
            p_cont = rollout_continue_only_from_state(reasoner, cont_state, x, k0, start_ctrl, ctrl_seq, t + 1, target)

            # overwrite
            if overwrite_kind == "fixed":
                over_state = overwrite_fixed_blend(cand, z0, float(overwrite_arg))
            elif overwrite_kind == "clip":
                over_state = overwrite_clipped(cand, z0, float(overwrite_arg))
            elif overwrite_kind == "gated":
                score = reasoner.eval_score(cand, x, k0, ctrl_seq[:, t, :], t)
                alpha_min, alpha_max = overwrite_arg
                over_state = overwrite_gated_by_score(cand, z0, score, alpha_min=alpha_min, alpha_max=alpha_max)
            else:
                raise ValueError(f"Unknown overwrite_kind: {overwrite_kind}")

            p_over = rollout_continue_only_from_state(reasoner, over_state, x, k0, start_ctrl, ctrl_seq, t + 1, target)
            p_rest = rollout_continue_only_from_state(reasoner, z0, x, k0, start_ctrl, ctrl_seq, t + 1, target)

            probs = torch.stack([p_cont, p_over, p_rest], dim=-1)
            best = probs.argmax(dim=-1)

            for a in range(3):
                best_counts[t, a] += (best == a).sum()

            mean_probs[t, 0] += p_cont.sum()
            mean_probs[t, 1] += p_over.sum()
            mean_probs[t, 2] += p_rest.sum()

            gain_over_continue[t] += (p_over - p_cont).sum()
            gain_restart_over_continue[t] += (p_rest - p_cont).sum()

            z = cand

    denom = batches * bs
    mean_probs = (mean_probs / denom).cpu().numpy()
    best_rates = (best_counts / denom).cpu().numpy()
    gain_over_continue = (gain_over_continue / denom).cpu().numpy()
    gain_restart_over_continue = (gain_restart_over_continue / denom).cpu().numpy()

    return {
        "mean_probs": mean_probs,
        "best_rates": best_rates,
        "gain_over_continue": gain_over_continue,
        "gain_restart_over_continue": gain_restart_over_continue,
    }

def print_probe_summary(probe: Dict, level: int, overwrite_kind: str, overwrite_arg, zero_knowledge: bool):
    zk = "zero-knowledge" if zero_knowledge else "normal-knowledge"
    print(f"\n--- Action probe: level {level} ({LEVEL_NAMES[level]}), {overwrite_kind}={overwrite_arg}, {zk} ---")
    for t in range(T):
        mp = probe["mean_probs"][t]
        br = probe["best_rates"][t]
        g1 = probe["gain_over_continue"][t]
        g2 = probe["gain_restart_over_continue"][t]
        print(
            f"step {t}: mean p(cont/over/rest)=({mp[0]:.3f}, {mp[1]:.3f}, {mp[2]:.3f}) | "
            f"best rates=({br[0]:.3f}, {br[1]:.3f}, {br[2]:.3f}) | "
            f"Δover-cont={g1:+.4f} | Δrestart-cont={g2:+.4f}"
        )

# -----------------------------
# One experiment run
# -----------------------------
def run_one_seed_and_base_strength(seed: int, base_epochs: int):
    set_seed(seed)
    print("\n\n##############################")
    print(f"Seed = {seed} | base_epochs = {base_epochs}")
    print("##############################")

    base = BaseKnowledgeProvider().to(DEVICE)
    direct_head = DirectStaticBaseline(base).to(DEVICE)

    # Stage 1: base knowledge
    train_base(base, base_epochs, BASE_STEPS_PER_EPOCH)

    # Freeze a copy for all downstream work
    frozen_base = copy.deepcopy(base).to(DEVICE)
    for p in frozen_base.parameters():
        p.requires_grad = False

    # Stage 2: direct static baseline
    direct_head.base = frozen_base
    print("\n=== Stage 2: direct static baseline head (no online control) ===")
    opt_direct = torch.optim.AdamW(direct_head.head.parameters(), lr=LR_DIRECT, weight_decay=1e-4)
    ce_task = nn.CrossEntropyLoss()
    for ep in range(4):
        t0 = time.time()
        total_loss = 0.0
        total_acc = 0.0
        for _ in range(DIRECT_STEPS_PER_EPOCH):
            x, _, _, _, start_ctrl, _, target = make_reasoning_batch(X_train, y_train, BATCH_SIZE, level=random.choice(LEVELS))
            logits = direct_head(x, start_ctrl)
            loss = ce_task(logits, target)

            opt_direct.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(direct_head.head.parameters(), 1.0)
            opt_direct.step()

            total_loss += loss.item()
            total_acc += (logits.argmax(dim=-1) == target).float().mean().item()
        print(f"Direct epoch {ep+1}/4 | loss {total_loss/DIRECT_STEPS_PER_EPOCH:.4f} | acc {total_acc/DIRECT_STEPS_PER_EPOCH:.4f} | {time.time()-t0:.1f}s")

    # Stage 3: reasoner continue-only pretraining
    reasoner = MCLTRReasoner(frozen_base).to(DEVICE)
    train_reasoner_continue(reasoner, epochs=4, steps_per_epoch=REASONER_STEPS_PER_EPOCH)

    # Stage 4: evaluator
    train_evaluator(reasoner, epochs=2, steps_per_epoch=EVAL_STEPS_PER_EPOCH)

    # Diagnostics
    base_acc = eval_base_classifier(base, batches=15, bs=256)

    results = {}
    for level in LEVELS:
        results[level] = {}
        direct_acc = eval_direct(direct_head, level=level, batches=15, bs=256)
        cont_normal = eval_rollout(reasoner, level=level, mode="continue", overwrite_kind=None, overwrite_arg=None, zero_knowledge=False, batches=15, bs=256)
        cont_zero = eval_rollout(reasoner, level=level, mode="continue", overwrite_kind=None, overwrite_arg=None, zero_knowledge=True, batches=15, bs=256)

        results[level]["base_acc"] = base_acc
        results[level]["direct_acc"] = direct_acc
        results[level]["continue_normal"] = cont_normal["acc"]
        results[level]["continue_zero"] = cont_zero["acc"]

        # Compare overwrite operators against restart
        for overwrite_kind, arg_list in [
            ("fixed", FIXED_OVERWRITE_ALPHAS),
            ("clip", CLIPPED_OVERWRITE_STEPS),
            ("gated", GATED_OVERWRITE_BOUNDS),
        ]:
            results[level][overwrite_kind] = {}
            for arg in arg_list:
                over = eval_rollout(reasoner, level=level, mode="overwrite", overwrite_kind=overwrite_kind, overwrite_arg=arg, zero_knowledge=False, batches=15, bs=256)
                rest = eval_rollout(reasoner, level=level, mode="restart", overwrite_kind=None, overwrite_arg=None, zero_knowledge=False, batches=15, bs=256)
                oracle = eval_rollout(reasoner, level=level, mode="oracle", overwrite_kind=overwrite_kind, overwrite_arg=arg, zero_knowledge=False, batches=15, bs=256)
                probe = probe_actions(reasoner, level=level, overwrite_kind=overwrite_kind, overwrite_arg=arg, zero_knowledge=False, batches=6, bs=128)
                probe_zero = probe_actions(reasoner, level=level, overwrite_kind=overwrite_kind, overwrite_arg=arg, zero_knowledge=True, batches=6, bs=128)

                results[level][overwrite_kind][arg] = {
                    "overwrite_acc": over["acc"],
                    "restart_acc": rest["acc"],
                    "oracle_acc": oracle["acc"],
                    "oracle_c": oracle["continue_rate"],
                    "oracle_o": oracle["overwrite_rate"],
                    "oracle_r": oracle["restart_rate"],
                    "probe": probe,
                    "probe_zero": probe_zero,
                }

        print(f"\n--- Seed {seed} | base_epochs {base_epochs} | Level {level} ({LEVEL_NAMES[level]}) ---")
        print(f"Base classifier (digit ID only)      : {base_acc:.4f}")
        print(f"Direct static baseline               : {direct_acc:.4f}")
        print(f"M-CLTR continue-only (normal k0)     : {cont_normal['acc']:.4f}")
        print(f"M-CLTR continue-only (zero k0)       : {cont_zero['acc']:.4f}")
        print(f"Zero-knowledge gap                   : {cont_normal['acc'] - cont_zero['acc']:+.4f}")

        for overwrite_kind, arg_list in [
            ("fixed", FIXED_OVERWRITE_ALPHAS),
            ("clip", CLIPPED_OVERWRITE_STEPS),
            ("gated", GATED_OVERWRITE_BOUNDS),
        ]:
            for arg in arg_list:
                r = results[level][overwrite_kind][arg]
                print(f"\n  Overwrite mode = {overwrite_kind}, arg = {arg}")
                print(f"    Forced overwrite acc             : {r['overwrite_acc']:.4f}")
                print(f"    Forced restart acc               : {r['restart_acc']:.4f}")
                print(f"    Step-wise oracle acc             : {r['oracle_acc']:.4f}")
                print(f"    Oracle action rates C/O/R         : {r['oracle_c']:.3f}/{r['oracle_o']:.3f}/{r['oracle_r']:.3f}")
                print_probe_summary(r["probe"], level, overwrite_kind, arg, zero_knowledge=False)
                print_probe_summary(r["probe_zero"], level, overwrite_kind, arg, zero_knowledge=True)

    return results

# -----------------------------
# Run sweep
# -----------------------------
all_results = {}
for base_epochs in BASE_EPOCH_OPTIONS:
    all_results[base_epochs] = {}
    for seed in SEEDS:
        all_results[base_epochs][seed] = run_one_seed_and_base_strength(seed, base_epochs)

# -----------------------------
# Aggregate summary
# -----------------------------
print("\n\n==============================")
print("Aggregated summary across seeds and base strengths")
print("==============================")

for base_epochs in BASE_EPOCH_OPTIONS:
    print(f"\n################################")
    print(f"Base epochs = {base_epochs}")
    print(f"################################")
    for level in LEVELS:
        base_vals = []
        direct_vals = []
        cont_vals = []
        cont_zero_vals = []

        summary = {}
        for overwrite_kind, arg_list in [
            ("fixed", FIXED_OVERWRITE_ALPHAS),
            ("clip", CLIPPED_OVERWRITE_STEPS),
            ("gated", GATED_OVERWRITE_BOUNDS),
        ]:
            summary[overwrite_kind] = {arg: {
                "over": [], "rest": [], "oracle": [], "orc": [], "oro": [], "orr": [],
                "probe_over": [], "probe_rest": [], "probe_best_over": [], "probe_best_rest": [],
                "probe_over_zero": [], "probe_rest_zero": []
            } for arg in arg_list}

        for seed in SEEDS:
            rr = all_results[base_epochs][seed][level]
            base_vals.append(rr["base_acc"])
            direct_vals.append(rr["direct_acc"])
            cont_vals.append(rr["continue_normal"])
            cont_zero_vals.append(rr["continue_zero"])

            for overwrite_kind, arg_list in [
                ("fixed", FIXED_OVERWRITE_ALPHAS),
                ("clip", CLIPPED_OVERWRITE_STEPS),
                ("gated", GATED_OVERWRITE_BOUNDS),
            ]:
                for arg in arg_list:
                    r = rr[overwrite_kind][arg]
                    summary[overwrite_kind][arg]["over"].append(r["overwrite_acc"])
                    summary[overwrite_kind][arg]["rest"].append(r["restart_acc"])
                    summary[overwrite_kind][arg]["oracle"].append(r["oracle_acc"])
                    summary[overwrite_kind][arg]["orc"].append(r["oracle_c"])
                    summary[overwrite_kind][arg]["oro"].append(r["oracle_o"])
                    summary[overwrite_kind][arg]["orr"].append(r["oracle_r"])
                    summary[overwrite_kind][arg]["probe_over"].append(float(r["probe"]["gain_over_continue"].mean()))
                    summary[overwrite_kind][arg]["probe_rest"].append(float(r["probe"]["gain_restart_over_continue"].mean()))
                    summary[overwrite_kind][arg]["probe_best_over"].append(float(r["probe"]["best_rates"][:, 1].mean()))
                    summary[overwrite_kind][arg]["probe_best_rest"].append(float(r["probe"]["best_rates"][:, 2].mean()))
                    summary[overwrite_kind][arg]["probe_over_zero"].append(float(r["probe_zero"]["gain_over_continue"].mean()))
                    summary[overwrite_kind][arg]["probe_rest_zero"].append(float(r["probe_zero"]["gain_restart_over_continue"].mean()))

        bm, bs = mean_std(base_vals)
        dm, ds = mean_std(direct_vals)
        cm, cs = mean_std(cont_vals)
        czm, czs = mean_std(cont_zero_vals)

        print(f"\nLevel {level} ({LEVEL_NAMES[level]})")
        print(f"  Base classifier              : {bm:.4f} ± {bs:.4f}")
        print(f"  Direct static baseline       : {dm:.4f} ± {ds:.4f}")
        print(f"  Continue-only (normal k0)    : {cm:.4f} ± {cs:.4f}")
        print(f"  Continue-only (zero k0)      : {czm:.4f} ± {czs:.4f}")
        print(f"  Zero-knowledge gap           : {(cm - czm):+.4f}")

        for overwrite_kind, arg_list in [
            ("fixed", FIXED_OVERWRITE_ALPHAS),
            ("clip", CLIPPED_OVERWRITE_STEPS),
            ("gated", GATED_OVERWRITE_BOUNDS),
        ]:
            for arg in arg_list:
                d = summary[overwrite_kind][arg]
                om, os = mean_std(d["over"])
                rm, rs = mean_std(d["rest"])
                qm, qs = mean_std(d["oracle"])
                orc_m, orc_s = mean_std(d["orc"])
                oro_m, oro_s = mean_std(d["oro"])
                orr_m, orr_s = mean_std(d["orr"])
                go_m, go_s = mean_std(d["probe_over"])
                gr_m, gr_s = mean_std(d["probe_rest"])
                bo_m, bo_s = mean_std(d["probe_best_over"])
                br_m, br_s = mean_std(d["probe_best_rest"])
                goz_m, goz_s = mean_std(d["probe_over_zero"])
                grz_m, grz_s = mean_std(d["probe_rest_zero"])

                print(f"\n  Overwrite mode = {overwrite_kind}, arg = {arg}")
                print(f"    Forced overwrite acc        : {om:.4f} ± {os:.4f}")
                print(f"    Forced restart acc          : {rm:.4f} ± {rs:.4f}")
                print(f"    Step-wise oracle acc        : {qm:.4f} ± {qs:.4f}")
                print(f"    Oracle action rates C/O/R   : {orc_m:.3f} ± {orc_s:.3f} / {oro_m:.3f} ± {oro_s:.3f} / {orr_m:.3f} ± {orr_s:.3f}")
                print(f"    Probe mean Δ(over-cont)     : {go_m:+.4f} ± {go_s:.4f}")
                print(f"    Probe mean Δ(rest-cont)     : {gr_m:+.4f} ± {gr_s:.4f}")
                print(f"    Probe best-action overwrite : {bo_m:.3f} ± {bo_s:.4f}")
                print(f"    Probe best-action restart   : {br_m:.3f} ± {br_s:.4f}")
                print(f"    Zero-k Δ(over-cont)         : {goz_m:+.4f} ± {goz_s:.4f}")
                print(f"    Zero-k Δ(rest-cont)         : {grz_m:+.4f} ± {gr_s:.4f}")

print("\nDone.")

# M-CLTR v5.1 corrected — overwrite vs restart diagnostic with mistake injection
# Single Colab cell, CPU-friendly
#
# Tests:
# 1) Base strength sweep: weak / medium / strong base knowledge
# 2) Realistic latent mistake injection
# 3) Overwrite variants: weak blend, context overwrite, gated overwrite
# 4) Restart vs overwrite vs continue
# 5) Zero-knowledge ablation
#
# Key modeling choice:
# - The M-CLTR reasoner only receives the base knowledge vector k0 and control mode.
# - It does NOT see raw x directly.
# - This keeps it as a plug-and-play latent control layer.

import copy
import math
import random
import time
from typing import Dict, Optional, Tuple

import numpy as np
import torch
import torch.nn as nn
import torch.nn.functional as F

from sklearn.datasets import load_digits
from sklearn.model_selection import train_test_split

# -----------------------------
# Device / reproducibility
# -----------------------------
DEVICE = torch.device("cuda" if torch.cuda.is_available() else "cpu")
print("Device:", DEVICE)

def set_seed(seed: int):
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    if torch.cuda.is_available():
        torch.cuda.manual_seed_all(seed)

# -----------------------------
# Config
# -----------------------------
T = 6
X_DIM = 64
K_DIM = 64
Z_DIM = 96
TASK_CLASSES = 2
DIGIT_CLASSES = 10

BATCH_SIZE = 128

SEEDS = [7, 17]
BASE_EPOCH_SWEEP = [1, 4, 8]

BASE_STEPS_PER_EPOCH = 24
DIRECT_STEPS_PER_EPOCH = 24
REASONER_STEPS_PER_EPOCH = 24
EVAL_STEPS_PER_EPOCH = 24

BASE_EVAL_BATCHES = 12
TASK_EVAL_BATCHES = 12
PROBE_BATCHES = 4

LR_BASE = 2e-3
LR_DIRECT = 2e-3
LR_REASONER = 2e-3
LR_EVAL = 2e-3

TRAIN_LEVELS = [0, 1, 2]
EVAL_LEVELS = [0, 1, 2, 3, 4]

# Overwrite diagnostic specs
OVERWRITE_SPECS = [
    ("weak", 0.20),
    ("weak", 0.50),
    ("weak", 0.80),
    ("context", 0.50),
    ("gated", (0.05, 0.95)),
]

LEVEL_SPECS = {
    0: {"name": "easy / no switch",            "switch_step": T,       "input_noise": 0.00, "corrupt_step": None, "corrupt_severity": 0.00},
    1: {"name": "medium / mid switch",         "switch_step": T // 2,  "input_noise": 0.00, "corrupt_step": None, "corrupt_severity": 0.00},
    2: {"name": "hard / early switch",         "switch_step": 1,       "input_noise": 0.00, "corrupt_step": None, "corrupt_severity": 0.00},
    3: {"name": "switch + latent mistake",     "switch_step": T // 2,  "input_noise": 0.00, "corrupt_step": 2,    "corrupt_severity": 0.35},
    4: {"name": "switch + noise + mistake",    "switch_step": 1,       "input_noise": 0.15, "corrupt_step": 1,    "corrupt_severity": 0.45},
}

# -----------------------------
# Data
# -----------------------------
digits = load_digits()
X_all = torch.tensor(digits.data, dtype=torch.float32) / 16.0
y_all = torch.tensor(digits.target, dtype=torch.long)

X_train_np, X_test_np, y_train_np, y_test_np = train_test_split(
    X_all.numpy(),
    y_all.numpy(),
    test_size=0.30,
    random_state=0,
    stratify=y_all.numpy(),
)

X_train = torch.tensor(X_train_np, dtype=torch.float32, device=DEVICE)
y_train = torch.tensor(y_train_np, dtype=torch.long, device=DEVICE)
X_test = torch.tensor(X_test_np, dtype=torch.float32, device=DEVICE)
y_test = torch.tensor(y_test_np, dtype=torch.long, device=DEVICE)

# -----------------------------
# Helpers
# -----------------------------
def one_hot(v: torch.Tensor, n: int) -> torch.Tensor:
    return F.one_hot(v.long(), n).float()

def step_feature(t: int, batch_size: int, device: torch.device) -> torch.Tensor:
    s = 0.0 if T <= 1 else float(t) / float(T - 1)
    return torch.full((batch_size, 1), s, device=device)

def mean_std(values):
    arr = np.asarray(values, dtype=np.float64)
    if arr.size == 1:
        return float(arr.item()), 0.0
    return float(arr.mean()), float(arr.std(ddof=1))

def sample_indices(n: int, batch_size: int) -> torch.Tensor:
    return torch.randint(0, n, (batch_size,), device=DEVICE)

def task_value(digit_labels: torch.Tensor, mode: torch.Tensor) -> torch.Tensor:
    parity = (digit_labels % 2).long()
    highlow = (digit_labels >= 5).long()
    return torch.where(mode == 0, parity, highlow)

def get_level_spec(level: int) -> Dict:
    return LEVEL_SPECS[level]

def inject_mistake(z: torch.Tensor, severity: float) -> torch.Tensor:
    if severity <= 0:
        return z
    rolled = torch.roll(z, shifts=1, dims=-1)
    mixed = (1.0 - severity) * z + severity * rolled
    mixed = mixed + (0.50 * severity) * torch.randn_like(z)
    return mixed

def level_name(level: int) -> str:
    return LEVEL_SPECS[level]["name"]

def spec_to_str(spec: Tuple):
    kind, arg = spec
    if kind == "gated":
        lo, hi = arg
        return f"gated({lo:.2f},{hi:.2f})"
    return f"{kind}({arg:.2f})"

# -----------------------------
# Batch generation
# -----------------------------
def make_reasoning_batch(
    x_pool: torch.Tensor,
    y_pool: torch.Tensor,
    batch_size: int,
    level: int,
):
    spec = get_level_spec(level)

    idx = sample_indices(x_pool.size(0), batch_size)
    x = x_pool[idx].clone()

    if spec["input_noise"] > 0:
        x = torch.clamp(x + spec["input_noise"] * torch.randn_like(x), 0.0, 1.0)

    digit_labels = y_pool[idx]
    start_mode = torch.randint(0, 2, (batch_size,), device=DEVICE)

    switch_step = spec["switch_step"]
    end_mode = start_mode.clone() if switch_step >= T else 1 - start_mode

    start_ctrl = one_hot(start_mode, 2)

    t_ids = torch.arange(T, device=DEVICE).unsqueeze(0)
    curr_modes = torch.where(
        t_ids < switch_step,
        start_mode.unsqueeze(1),
        end_mode.unsqueeze(1),
    )
    ctrl_seq = one_hot(curr_modes, 2)  # [B, T, 2]

    final_mode = start_mode if switch_step >= T else end_mode
    target = task_value(digit_labels, final_mode)

    return x, digit_labels, start_mode, end_mode, start_ctrl, ctrl_seq, target

# -----------------------------
# Models
# -----------------------------
class MLP(nn.Module):
    def __init__(self, in_dim: int, out_dim: int, hidden: int = 128):
        super().__init__()
        self.net = nn.Sequential(
            nn.Linear(in_dim, hidden),
            nn.GELU(),
            nn.Linear(hidden, hidden),
            nn.GELU(),
            nn.Linear(hidden, out_dim),
        )

    def forward(self, x):
        return self.net(x)

class BaseKnowledgeProvider(nn.Module):
    """
    x -> k0
    k0 is the plug-and-play knowledge vector used by M-CLTR.
    """
    def __init__(self, x_dim: int = X_DIM, k_dim: int = K_DIM):
        super().__init__()
        self.encoder = nn.Sequential(
            nn.Linear(x_dim, 128),
            nn.GELU(),
            nn.Linear(128, k_dim),
            nn.LayerNorm(k_dim),
        )
        self.classifier = nn.Sequential(
            nn.Linear(k_dim, 64),
            nn.GELU(),
            nn.Linear(64, DIGIT_CLASSES),
        )

        for m in self.modules():
            if isinstance(m, nn.Linear):
                nn.init.xavier_uniform_(m.weight)
                if m.bias is not None:
                    nn.init.zeros_(m.bias)

    def encode(self, x: torch.Tensor) -> torch.Tensor:
        return self.encoder(x)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        k0 = self.encode(x)
        return self.classifier(k0)

class DirectStaticBaseline(nn.Module):
    """
    Static baseline: uses k0 + start mode only.
    """
    def __init__(self, k_dim: int = K_DIM):
        super().__init__()
        self.head = MLP(k_dim + 2, TASK_CLASSES, hidden=96)

        for m in self.modules():
            if isinstance(m, nn.Linear):
                nn.init.xavier_uniform_(m.weight)
                if m.bias is not None:
                    nn.init.zeros_(m.bias)

    def forward(self, k0: torch.Tensor, start_ctrl: torch.Tensor) -> torch.Tensor:
        return self.head(torch.cat([k0, start_ctrl], dim=-1))

class MCLTRReasoner(nn.Module):
    """
    M-CLTR reasoning layer:
    - receives base knowledge vector k0
    - keeps a latent state z
    - exposes continue / overwrite / restart diagnostics
    """
    def __init__(self, base: BaseKnowledgeProvider, k_dim: int = K_DIM, z_dim: int = Z_DIM):
        super().__init__()
        self.base = base
        self.k_dim = k_dim
        self.z_dim = z_dim

        self.init_net = MLP(k_dim + 2, z_dim, hidden=128)
        self.trans_net = MLP(z_dim + k_dim + 2 + 1, z_dim, hidden=128)
        self.context_net = MLP(k_dim + 2 + 1, z_dim, hidden=128)
        self.evaluator = MLP(z_dim + k_dim + 2 + 1, 1, hidden=96)
        self.decoder = nn.Linear(z_dim, TASK_CLASSES)

        self.z_norm = nn.LayerNorm(z_dim)
        self.ctx_norm = nn.LayerNorm(z_dim)

        for m in self.modules():
            if isinstance(m, nn.Linear):
                nn.init.xavier_uniform_(m.weight)
                if m.bias is not None:
                    nn.init.zeros_(m.bias)

    def knowledge(self, x: torch.Tensor) -> torch.Tensor:
        return self.base.encode(x)

    def init_state(self, k0: torch.Tensor, start_ctrl: torch.Tensor) -> torch.Tensor:
        z0 = self.init_net(torch.cat([k0, start_ctrl], dim=-1))
        return self.z_norm(z0)

    def context_state(self, k0: torch.Tensor, ctrl: torch.Tensor, t: int) -> torch.Tensor:
        step = step_feature(t, k0.size(0), k0.device)
        ctx = self.context_net(torch.cat([k0, ctrl, step], dim=-1))
        return self.ctx_norm(ctx)

    def step_update(self, z: torch.Tensor, k0: torch.Tensor, ctrl: torch.Tensor, t: int) -> torch.Tensor:
        step = step_feature(t, z.size(0), z.device)
        inp = torch.cat([z, k0, ctrl, step], dim=-1)
        delta = torch.tanh(self.trans_net(inp))
        cand = self.z_norm(0.80 * z + 0.20 * delta)
        return cand

    def eval_score(self, z: torch.Tensor, k0: torch.Tensor, ctrl: torch.Tensor, t: int) -> torch.Tensor:
        step = step_feature(t, z.size(0), z.device)
        inp = torch.cat([z, k0, ctrl, step], dim=-1)
        return torch.sigmoid(self.evaluator(inp)).squeeze(-1)

    def decode(self, z: torch.Tensor) -> torch.Tensor:
        return self.decoder(z)

    def overwrite_state(
        self,
        cand: torch.Tensor,
        z0: torch.Tensor,
        k0: torch.Tensor,
        ctrl: torch.Tensor,
        t: int,
        overwrite_spec: Tuple,
    ) -> torch.Tensor:
        kind, arg = overwrite_spec

        if kind == "weak":
            alpha = float(arg)
            fresh = z0
            return self.z_norm(alpha * cand + (1.0 - alpha) * fresh)

        if kind == "context":
            alpha = float(arg)
            fresh = self.context_state(k0, ctrl, t)
            return self.z_norm(alpha * cand + (1.0 - alpha) * fresh)

        if kind == "gated":
            lo, hi = arg
            gate = self.eval_score(cand, k0, ctrl, t)
            alpha = lo + (hi - lo) * gate
            fresh = self.context_state(k0, ctrl, t)
            return self.z_norm(alpha.unsqueeze(-1) * cand + (1.0 - alpha.unsqueeze(-1)) * fresh)

        raise ValueError(f"Unknown overwrite spec kind: {kind}")

# -----------------------------
# Training utilities
# -----------------------------
def set_requires_grad(module: nn.Module, flag: bool):
    for p in module.parameters():
        p.requires_grad = flag

# -----------------------------
# Rollout helpers
# -----------------------------
@torch.no_grad()
def continue_rollout_from_state(
    reasoner: MCLTRReasoner,
    z_start: torch.Tensor,
    k0: torch.Tensor,
    ctrl_seq: torch.Tensor,
    start_t: int,
    level: int,
) -> torch.Tensor:
    spec = get_level_spec(level)
    z = z_start
    for t in range(start_t, T):
        z = reasoner.step_update(z, k0, ctrl_seq[:, t, :], t)
        if spec["corrupt_step"] is not None and t == spec["corrupt_step"]:
            z = inject_mistake(z, spec["corrupt_severity"])
    return z

@torch.no_grad()
def final_target_prob_from_state(
    reasoner: MCLTRReasoner,
    z_start: torch.Tensor,
    k0: torch.Tensor,
    ctrl_seq: torch.Tensor,
    start_t: int,
    target: torch.Tensor,
    level: int,
) -> torch.Tensor:
    z_final = continue_rollout_from_state(reasoner, z_start, k0, ctrl_seq, start_t, level)
    logits = reasoner.decode(z_final)
    probs = F.softmax(logits, dim=-1)
    return probs.gather(1, target.unsqueeze(1)).squeeze(1)

@torch.no_grad()
def choose_oracle_action(
    reasoner: MCLTRReasoner,
    cand: torch.Tensor,
    z0: torch.Tensor,
    k0: torch.Tensor,
    ctrl_seq: torch.Tensor,
    t: int,
    target: torch.Tensor,
    overwrite_spec: Tuple,
    level: int,
):
    cont_state = cand
    over_state = reasoner.overwrite_state(cand, z0, k0, ctrl_seq[:, t, :], t, overwrite_spec)
    rest_state = z0

    p_cont = final_target_prob_from_state(reasoner, cont_state, k0, ctrl_seq, t + 1, target, level)
    p_over = final_target_prob_from_state(reasoner, over_state, k0, ctrl_seq, t + 1, target, level)
    p_rest = final_target_prob_from_state(reasoner, rest_state, k0, ctrl_seq, t + 1, target, level)

    probs = torch.stack([p_cont, p_over, p_rest], dim=-1)
    tie_bias = torch.tensor([2e-3, 1e-3, 0.0], device=probs.device).unsqueeze(0)
    action = (probs + tie_bias).argmax(dim=-1)
    best_prob = probs.gather(1, action.unsqueeze(1)).squeeze(1)
    return action, probs, best_prob

# -----------------------------
# Training
# -----------------------------
def train_base(base: BaseKnowledgeProvider, epochs: int, steps_per_epoch: int):
    base.train()
    opt = torch.optim.AdamW(base.parameters(), lr=LR_BASE, weight_decay=1e-4)
    ce = nn.CrossEntropyLoss()

    print("\n=== Stage 1: base knowledge pretraining (digit classification) ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_acc = 0.0

        for _ in range(steps_per_epoch):
            idx = sample_indices(X_train.size(0), BATCH_SIZE)
            xb = X_train[idx]
            yb = y_train[idx]

            logits = base(xb)
            loss = ce(logits, yb)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(base.parameters(), 1.0)
            opt.step()

            total_loss += loss.item()
            total_acc += (logits.argmax(dim=-1) == yb).float().mean().item()

        print(f"Base epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} | acc {total_acc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s")

def train_direct_head(
    base: BaseKnowledgeProvider,
    direct: DirectStaticBaseline,
    epochs: int,
    steps_per_epoch: int,
):
    direct.train()
    set_requires_grad(base, False)
    opt = torch.optim.AdamW(direct.parameters(), lr=LR_DIRECT, weight_decay=1e-4)
    ce = nn.CrossEntropyLoss()

    print("\n=== Stage 2: direct static baseline head (no online control) ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_acc = 0.0

        for _ in range(steps_per_epoch):
            level = random.choice(TRAIN_LEVELS)
            x, digit_labels, start_mode, end_mode, start_ctrl, ctrl_seq, target = make_reasoning_batch(
                X_train, y_train, BATCH_SIZE, level=level
            )

            with torch.no_grad():
                k0 = base.encode(x)

            logits = direct(k0, start_ctrl)
            loss = ce(logits, target)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(direct.parameters(), 1.0)
            opt.step()

            total_loss += loss.item()
            total_acc += (logits.argmax(dim=-1) == target).float().mean().item()

        print(f"Direct epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} | acc {total_acc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s")

def train_reasoner_continue_only(
    base: BaseKnowledgeProvider,
    reasoner: MCLTRReasoner,
    epochs: int,
    steps_per_epoch: int,
):
    reasoner.train()
    set_requires_grad(base, False)
    set_requires_grad(reasoner.init_net, True)
    set_requires_grad(reasoner.trans_net, True)
    set_requires_grad(reasoner.context_net, False)
    set_requires_grad(reasoner.evaluator, False)
    set_requires_grad(reasoner.decoder, True)
    set_requires_grad(reasoner.z_norm, True)
    set_requires_grad(reasoner.ctx_norm, False)

    params = (
        list(reasoner.init_net.parameters())
        + list(reasoner.trans_net.parameters())
        + list(reasoner.decoder.parameters())
        + list(reasoner.z_norm.parameters())
    )
    opt = torch.optim.AdamW(params, lr=LR_REASONER, weight_decay=1e-4)
    ce = nn.CrossEntropyLoss()

    print("\n=== Stage 3: reasoner pretraining (continue-only rollouts, mixed levels) ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_acc = 0.0

        for _ in range(steps_per_epoch):
            level = random.choice(TRAIN_LEVELS)
            x, digit_labels, start_mode, end_mode, start_ctrl, ctrl_seq, target = make_reasoning_batch(
                X_train, y_train, BATCH_SIZE, level=level
            )

            with torch.no_grad():
                k0 = base.encode(x)

            z = reasoner.init_state(k0, start_ctrl)
            for t in range(T):
                z = reasoner.step_update(z, k0, ctrl_seq[:, t, :], t)

            logits = reasoner.decode(z)
            loss = ce(logits, target)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(params, 1.0)
            opt.step()

            total_loss += loss.item()
            total_acc += (logits.argmax(dim=-1) == target).float().mean().item()

        print(f"Reasoner epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} | acc {total_acc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s")

def train_evaluator(
    base: BaseKnowledgeProvider,
    reasoner: MCLTRReasoner,
    epochs: int,
    steps_per_epoch: int,
):
    reasoner.eval()
    set_requires_grad(base, False)
    set_requires_grad(reasoner.init_net, False)
    set_requires_grad(reasoner.trans_net, False)
    set_requires_grad(reasoner.context_net, False)
    set_requires_grad(reasoner.decoder, False)
    set_requires_grad(reasoner.z_norm, False)
    set_requires_grad(reasoner.ctx_norm, False)
    set_requires_grad(reasoner.evaluator, True)

    opt = torch.optim.AdamW(reasoner.evaluator.parameters(), lr=LR_EVAL, weight_decay=1e-4)
    mse = nn.MSELoss()

    print("\n=== Stage 4: evaluator training (predict final correctness probability) ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_binacc = 0.0

        for _ in range(steps_per_epoch):
            level = random.choice(EVAL_LEVELS)
            x, digit_labels, start_mode, end_mode, start_ctrl, ctrl_seq, target = make_reasoning_batch(
                X_train, y_train, BATCH_SIZE, level=level
            )

            with torch.no_grad():
                k0 = base.encode(x)
                z = reasoner.init_state(k0, start_ctrl)

                step_z = []
                step_k0 = []
                step_ctrl = []
                step_t = []
                labels = []

                for t in range(T):
                    cand = reasoner.step_update(z, k0, ctrl_seq[:, t, :], t)
                    p_target = final_target_prob_from_state(
                        reasoner, cand, k0, ctrl_seq, t + 1, target, level
                    )

                    step_z.append(cand.detach())
                    step_k0.append(k0.detach())
                    step_ctrl.append(ctrl_seq[:, t, :].detach())
                    step_t.append(step_feature(t, BATCH_SIZE, DEVICE))
                    labels.append(p_target.detach())
                    z = cand

                step_z = torch.cat(step_z, dim=0)
                step_k0 = torch.cat(step_k0, dim=0)
                step_ctrl = torch.cat(step_ctrl, dim=0)
                step_t = torch.cat(step_t, dim=0)
                labels = torch.cat(labels, dim=0).clamp(0.0, 1.0)

            inp = torch.cat([step_z, step_k0, step_ctrl, step_t], dim=-1)
            pred = torch.sigmoid(reasoner.evaluator(inp)).squeeze(-1)
            loss = mse(pred, labels)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(reasoner.evaluator.parameters(), 1.0)
            opt.step()

            total_loss += loss.item()
            total_binacc += ((pred > 0.5) == (labels > 0.5)).float().mean().item()

        print(f"Evaluator epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} | bin-acc {total_binacc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s")

# -----------------------------
# Rollout / evaluation
# -----------------------------
@torch.no_grad()
def rollout_reasoner(
    reasoner: MCLTRReasoner,
    k0: torch.Tensor,
    start_ctrl: torch.Tensor,
    ctrl_seq: torch.Tensor,
    target: Optional[torch.Tensor],
    level: int,
    mode: str,
    overwrite_spec: Optional[Tuple] = None,
    zero_k0: bool = False,
):
    if zero_k0:
        k0 = torch.zeros_like(k0)

    z0 = reasoner.init_state(k0, start_ctrl)
    z = z0
    spec = get_level_spec(level)

    actions = []
    step_scores = []

    for t in range(T):
        cand = reasoner.step_update(z, k0, ctrl_seq[:, t, :], t)

        # Inject latent mistake in designated probe levels
        if spec["corrupt_step"] is not None and t == spec["corrupt_step"]:
            cand = inject_mistake(cand, spec["corrupt_severity"])

        if mode == "continue":
            action = torch.zeros(k0.size(0), dtype=torch.long, device=k0.device)
            z_next = cand

        elif mode == "overwrite":
            if overwrite_spec is None:
                raise ValueError("overwrite_spec is required for overwrite mode")
            action = torch.ones(k0.size(0), dtype=torch.long, device=k0.device)
            z_next = reasoner.overwrite_state(cand, z0, k0, ctrl_seq[:, t, :], t, overwrite_spec)

        elif mode == "restart":
            action = torch.full((k0.size(0),), 2, dtype=torch.long, device=k0.device)
            z_next = z0

        elif mode == "oracle":
            if overwrite_spec is None:
                raise ValueError("overwrite_spec is required for oracle mode")
            action, probs, _ = choose_oracle_action(
                reasoner, cand, z0, k0, ctrl_seq, t, target, overwrite_spec, level
            )
            z_next = torch.empty_like(cand)

            cont_mask = action == 0
            over_mask = action == 1
            rest_mask = action == 2

            if cont_mask.any():
                z_next[cont_mask] = cand[cont_mask]
            if over_mask.any():
                z_next[over_mask] = reasoner.overwrite_state(
                    cand[over_mask],
                    z0[over_mask],
                    k0[over_mask],
                    ctrl_seq[over_mask, t, :],
                    t,
                    overwrite_spec,
                )
            if rest_mask.any():
                z_next[rest_mask] = z0[rest_mask]

            step_scores.append(probs)

        else:
            raise ValueError(f"Unknown rollout mode: {mode}")

        actions.append(action)
        z = z_next

    logits = reasoner.decode(z)
    pred = logits.argmax(dim=-1)

    final_ctrl = ctrl_seq[:, -1, :]
    final_eval = reasoner.eval_score(z, k0, final_ctrl, T - 1)

    out = {
        "logits": logits,
        "pred": pred,
        "actions": torch.stack(actions, dim=1),
        "final_eval": final_eval,
        "z0": z0,
    }
    if mode == "oracle":
        out["step_probs"] = torch.stack(step_scores, dim=1)
    return out

@torch.no_grad()
def eval_base_classifier(base: BaseKnowledgeProvider, batches: int = 12, bs: int = 256):
    base.eval()
    total = 0
    correct = 0
    for _ in range(batches):
        idx = sample_indices(X_test.size(0), bs)
        xb = X_test[idx]
        yb = y_test[idx]
        logits = base(xb)
        pred = logits.argmax(dim=-1)
        correct += (pred == yb).sum().item()
        total += yb.numel()
    return correct / total

@torch.no_grad()
def eval_direct_baseline(
    base: BaseKnowledgeProvider,
    direct: DirectStaticBaseline,
    level: int,
    batches: int = 12,
    bs: int = 256,
):
    direct.eval()
    base.eval()
    total = 0
    correct = 0
    for _ in range(batches):
        x, digit_labels, start_mode, end_mode, start_ctrl, ctrl_seq, target = make_reasoning_batch(
            X_test, y_test, bs, level=level
        )
        k0 = base.encode(x)
        logits = direct(k0, start_ctrl)
        pred = logits.argmax(dim=-1)
        correct += (pred == target).sum().item()
        total += target.numel()
    return correct / total

@torch.no_grad()
def eval_rollout_mode(
    base: BaseKnowledgeProvider,
    reasoner: MCLTRReasoner,
    level: int,
    mode: str,
    overwrite_spec: Tuple,
    zero_k0: bool,
    batches: int = 12,
    bs: int = 256,
):
    base.eval()
    reasoner.eval()

    total = 0
    correct = 0
    action_counts = torch.zeros(3, device=DEVICE)
    score_correct = []
    score_incorrect = []

    for _ in range(batches):
        x, digit_labels, start_mode, end_mode, start_ctrl, ctrl_seq, target = make_reasoning_batch(
            X_test, y_test, bs, level=level
        )
        k0 = base.encode(x)

        out = rollout_reasoner(
            reasoner,
            k0,
            start_ctrl,
            ctrl_seq,
            target=target if mode == "oracle" else None,
            level=level,
            mode=mode,
            overwrite_spec=overwrite_spec,
            zero_k0=zero_k0,
        )

        pred = out["pred"]
        correct_mask = pred == target
        correct += correct_mask.sum().item()
        total += target.numel()

        if mode == "oracle":
            action_counts += torch.stack([
                (out["actions"] == 0).sum(),
                (out["actions"] == 1).sum(),
                (out["actions"] == 2).sum(),
            ]).float()

        score = out["final_eval"]
        if correct_mask.any():
            score_correct.append(score[correct_mask].mean().item())
        if (~correct_mask).any():
            score_incorrect.append(score[~correct_mask].mean().item())

    result = {
        "acc": correct / total,
        "score_correct_mean": float(np.mean(score_correct)) if len(score_correct) else float("nan"),
        "score_incorrect_mean": float(np.mean(score_incorrect)) if len(score_incorrect) else float("nan"),
    }
    if mode == "oracle":
        rates = (action_counts / (batches * bs * T)).detach().cpu().numpy()
        result["continue_rate"] = float(rates[0])
        result["overwrite_rate"] = float(rates[1])
        result["restart_rate"] = float(rates[2])
    return result

@torch.no_grad()
def probe_actions(
    base: BaseKnowledgeProvider,
    reasoner: MCLTRReasoner,
    level: int,
    overwrite_spec: Tuple,
    zero_k0: bool,
    batches: int = 4,
    bs: int = 128,
):
    base.eval()
    reasoner.eval()

    best_counts = torch.zeros(T, 3, device=DEVICE)
    mean_probs = torch.zeros(T, 3, device=DEVICE)
    gain_over_continue = torch.zeros(T, device=DEVICE)
    gain_restart_over_continue = torch.zeros(T, device=DEVICE)

    for _ in range(batches):
        x, digit_labels, start_mode, end_mode, start_ctrl, ctrl_seq, target = make_reasoning_batch(
            X_test, y_test, bs, level=level
        )
        k0 = base.encode(x)
        if zero_k0:
            k0 = torch.zeros_like(k0)

        z0 = reasoner.init_state(k0, start_ctrl)
        z = z0
        spec = get_level_spec(level)

        for t in range(T):
            cand = reasoner.step_update(z, k0, ctrl_seq[:, t, :], t)

            if spec["corrupt_step"] is not None and t == spec["corrupt_step"]:
                cand = inject_mistake(cand, spec["corrupt_severity"])

            cont_state = cand
            over_state = reasoner.overwrite_state(cand, z0, k0, ctrl_seq[:, t, :], t, overwrite_spec)
            rest_state = z0

            p_cont = final_target_prob_from_state(reasoner, cont_state, k0, ctrl_seq, t + 1, target, level)
            p_over = final_target_prob_from_state(reasoner, over_state, k0, ctrl_seq, t + 1, target, level)
            p_rest = final_target_prob_from_state(reasoner, rest_state, k0, ctrl_seq, t + 1, target, level)

            probs = torch.stack([p_cont, p_over, p_rest], dim=-1)
            best = probs.argmax(dim=-1)

            for a in range(3):
                best_counts[t, a] += (best == a).sum()

            mean_probs[t, 0] += p_cont.sum()
            mean_probs[t, 1] += p_over.sum()
            mean_probs[t, 2] += p_rest.sum()

            gain_over_continue[t] += (p_over - p_cont).sum()
            gain_restart_over_continue[t] += (p_rest - p_cont).sum()

            z = cand

    denom = batches * bs
    return {
        "mean_probs": (mean_probs / denom).cpu().numpy(),
        "best_rates": (best_counts / denom).cpu().numpy(),
        "gain_over_continue": (gain_over_continue / denom).cpu().numpy(),
        "gain_restart_over_continue": (gain_restart_over_continue / denom).cpu().numpy(),
    }

def print_probe_summary(probe: Dict, level: int, overwrite_spec: Tuple, zero_k0: bool):
    zk = "zero-k0" if zero_k0 else "normal-k0"
    print(f"\n--- Action probe: level {level} ({level_name(level)}), spec={spec_to_str(overwrite_spec)}, {zk} ---")
    for t in range(T):
        mp = probe["mean_probs"][t]
        br = probe["best_rates"][t]
        g_over = probe["gain_over_continue"][t]
        g_rest = probe["gain_restart_over_continue"][t]
        print(
            f"step {t}: mean p(cont/over/rest)=({mp[0]:.3f}, {mp[1]:.3f}, {mp[2]:.3f}) | "
            f"best rates=({br[0]:.3f}, {br[1]:.3f}, {br[2]:.3f}) | "
            f"Δover-cont={g_over:+.4f} | Δrestart-cont={g_rest:+.4f}"
        )

# -----------------------------
# One run for one seed/base strength
# -----------------------------
def run_one_seed_and_base_strength(seed: int, base_epochs: int):
    set_seed(seed)
    print("\n\n##############################")
    print(f"Seed = {seed} | base_epochs = {base_epochs}")
    print("##############################")

    base = BaseKnowledgeProvider().to(DEVICE)
    direct = DirectStaticBaseline().to(DEVICE)
    reasoner = MCLTRReasoner(base).to(DEVICE)

    # Stage 1
    train_base(base, base_epochs, BASE_STEPS_PER_EPOCH)

    # Freeze base and reuse as plug-and-play knowledge provider
    frozen_base = copy.deepcopy(base).to(DEVICE)
    set_requires_grad(frozen_base, False)
    direct.base = frozen_base
    reasoner.base = frozen_base

    # Stage 2
    train_direct_head(frozen_base, direct, epochs=3, steps_per_epoch=DIRECT_STEPS_PER_EPOCH)

    # Stage 3
    train_reasoner_continue_only(frozen_base, reasoner, epochs=4, steps_per_epoch=REASONER_STEPS_PER_EPOCH)

    # Stage 4
    train_evaluator(frozen_base, reasoner, epochs=3, steps_per_epoch=EVAL_STEPS_PER_EPOCH)

    # Evaluation
    base_acc = eval_base_classifier(frozen_base, batches=BASE_EVAL_BATCHES, bs=256)

    results = {}
    for level in EVAL_LEVELS:
        results[level] = {}

        direct_acc = eval_direct_baseline(frozen_base, direct, level=level, batches=TASK_EVAL_BATCHES, bs=256)
        cont_normal = eval_rollout_mode(
            frozen_base, reasoner, level=level, mode="continue",
            overwrite_spec=OVERWRITE_SPECS[0], zero_k0=False,
            batches=TASK_EVAL_BATCHES, bs=256
        )
        cont_zero = eval_rollout_mode(
            frozen_base, reasoner, level=level, mode="continue",
            overwrite_spec=OVERWRITE_SPECS[0], zero_k0=True,
            batches=TASK_EVAL_BATCHES, bs=256
        )

        results[level]["base_acc"] = base_acc
        results[level]["direct_acc"] = direct_acc
        results[level]["continue_normal"] = cont_normal["acc"]
        results[level]["continue_zero"] = cont_zero["acc"]

        print(f"\n--- Seed {seed} | base_epochs {base_epochs} | Level {level} ({level_name(level)}) ---")
        print(f"Base classifier (digit ID only)      : {base_acc:.4f}")
        print(f"Direct static baseline              : {direct_acc:.4f}")
        print(f"M-CLTR continue-only (normal k0)    : {cont_normal['acc']:.4f}")
        print(f"M-CLTR continue-only (zero k0)      : {cont_zero['acc']:.4f}")
        print(f"Zero-knowledge gap                  : {cont_normal['acc'] - cont_zero['acc']:+.4f}")

        for spec in OVERWRITE_SPECS:
            overwrite_res = eval_rollout_mode(
                frozen_base, reasoner, level=level, mode="overwrite",
                overwrite_spec=spec, zero_k0=False,
                batches=TASK_EVAL_BATCHES, bs=256
            )
            restart_res = eval_rollout_mode(
                frozen_base, reasoner, level=level, mode="restart",
                overwrite_spec=spec, zero_k0=False,
                batches=TASK_EVAL_BATCHES, bs=256
            )
            oracle_res = eval_rollout_mode(
                frozen_base, reasoner, level=level, mode="oracle",
                overwrite_spec=spec, zero_k0=False,
                batches=TASK_EVAL_BATCHES, bs=256
            )

            probe = probe_actions(
                frozen_base, reasoner, level=level, overwrite_spec=spec, zero_k0=False,
                batches=PROBE_BATCHES, bs=128
            )
            probe_zero = probe_actions(
                frozen_base, reasoner, level=level, overwrite_spec=spec, zero_k0=True,
                batches=PROBE_BATCHES, bs=128
            )

            key = spec_to_str(spec)
            results[level][key] = {
                "overwrite_acc": overwrite_res["acc"],
                "restart_acc": restart_res["acc"],
                "oracle_acc": oracle_res["acc"],
                "oracle_c": oracle_res["continue_rate"],
                "oracle_o": oracle_res["overwrite_rate"],
                "oracle_r": oracle_res["restart_rate"],
                "probe": probe,
                "probe_zero": probe_zero,
            }

            print(f"\n  Overwrite spec = {key}")
            print(f"    Forced overwrite acc          : {overwrite_res['acc']:.4f}")
            print(f"    Forced restart acc            : {restart_res['acc']:.4f}")
            print(f"    Step-wise oracle acc          : {oracle_res['acc']:.4f}")
            print(f"    Oracle action rates C/O/R     : {oracle_res['continue_rate']:.3f}/{oracle_res['overwrite_rate']:.3f}/{oracle_res['restart_rate']:.3f}")
            print_probe_summary(probe, level, spec, zero_k0=False)
            print_probe_summary(probe_zero, level, spec, zero_k0=True)

    return results

# -----------------------------
# Run sweep
# -----------------------------
all_results = {}
for base_epochs in BASE_EPOCH_SWEEP:
    all_results[base_epochs] = {}
    for seed in SEEDS:
        all_results[base_epochs][seed] = run_one_seed_and_base_strength(seed, base_epochs)

# -----------------------------
# Aggregate summary
# -----------------------------
print("\n\n==============================")
print("Aggregated summary across seeds and base strengths")
print("==============================")

for base_epochs in BASE_EPOCH_SWEEP:
    print(f"\n################################")
    print(f"Base epochs = {base_epochs}")
    print(f"################################")

    for level in EVAL_LEVELS:
        base_vals = []
        direct_vals = []
        cont_vals = []
        cont_zero_vals = []

        spec_summaries = {
            spec_to_str(spec): {
                "over": [],
                "rest": [],
                "oracle": [],
                "orc": [],
                "oro": [],
                "orr": [],
                "probe_over": [],
                "probe_rest": [],
                "probe_best_over": [],
                "probe_best_rest": [],
                "probe_over_zero": [],
                "probe_rest_zero": [],
            }
            for spec in OVERWRITE_SPECS
        }

        for seed in SEEDS:
            rr = all_results[base_epochs][seed][level]
            base_vals.append(rr["base_acc"])
            direct_vals.append(rr["direct_acc"])
            cont_vals.append(rr["continue_normal"])
            cont_zero_vals.append(rr["continue_zero"])

            for spec in OVERWRITE_SPECS:
                key = spec_to_str(spec)
                r = rr[key]
                spec_summaries[key]["over"].append(r["overwrite_acc"])
                spec_summaries[key]["rest"].append(r["restart_acc"])
                spec_summaries[key]["oracle"].append(r["oracle_acc"])
                spec_summaries[key]["orc"].append(r["oracle_c"])
                spec_summaries[key]["oro"].append(r["oracle_o"])
                spec_summaries[key]["orr"].append(r["oracle_r"])
                spec_summaries[key]["probe_over"].append(float(r["probe"]["gain_over_continue"].mean()))
                spec_summaries[key]["probe_rest"].append(float(r["probe"]["gain_restart_over_continue"].mean()))
                spec_summaries[key]["probe_best_over"].append(float(r["probe"]["best_rates"][:, 1].mean()))
                spec_summaries[key]["probe_best_rest"].append(float(r["probe"]["best_rates"][:, 2].mean()))
                spec_summaries[key]["probe_over_zero"].append(float(r["probe_zero"]["gain_over_continue"].mean()))
                spec_summaries[key]["probe_rest_zero"].append(float(r["probe_zero"]["gain_restart_over_continue"].mean()))

        bm, bs = mean_std(base_vals)
        dm, ds = mean_std(direct_vals)
        cm, cs = mean_std(cont_vals)
        czm, czs = mean_std(cont_zero_vals)

        print(f"\nLevel {level} ({level_name(level)})")
        print(f"  Base classifier              : {bm:.4f} ± {bs:.4f}")
        print(f"  Direct static baseline       : {dm:.4f} ± {ds:.4f}")
        print(f"  Continue-only (normal k0)    : {cm:.4f} ± {cs:.4f}")
        print(f"  Continue-only (zero k0)      : {czm:.4f} ± {czs:.4f}")
        print(f"  Zero-knowledge gap           : {(cm - czm):+.4f}")

        for spec in OVERWRITE_SPECS:
            key = spec_to_str(spec)
            om, os = mean_std(spec_summaries[key]["over"])
            rm, rs = mean_std(spec_summaries[key]["rest"])
            qm, qs = mean_std(spec_summaries[key]["oracle"])
            orc_m, orc_s = mean_std(spec_summaries[key]["orc"])
            oro_m, oro_s = mean_std(spec_summaries[key]["oro"])
            orr_m, orr_s = mean_std(spec_summaries[key]["orr"])
            go_m, go_s = mean_std(spec_summaries[key]["probe_over"])
            gr_m, gr_s = mean_std(spec_summaries[key]["probe_rest"])
            bo_m, bo_s = mean_std(spec_summaries[key]["probe_best_over"])
            br_m, br_s = mean_std(spec_summaries[key]["probe_best_rest"])
            goz_m, goz_s = mean_std(spec_summaries[key]["probe_over_zero"])
            grz_m, grz_s = mean_std(spec_summaries[key]["probe_rest_zero"])

            print(f"\n  Overwrite spec = {key}")
            print(f"    Forced overwrite acc        : {om:.4f} ± {os:.4f}")
            print(f"    Forced restart acc          : {rm:.4f} ± {rs:.4f}")
            print(f"    Step-wise oracle acc        : {qm:.4f} ± {qs:.4f}")
            print(f"    Oracle action rates C/O/R   : {orc_m:.3f} ± {orc_s:.3f} / {oro_m:.3f} ± {oro_s:.3f} / {orr_m:.3f} ± {orr_s:.3f}")
            print(f"    Probe mean Δ(over-cont)     : {go_m:+.4f} ± {go_s:.4f}")
            print(f"    Probe mean Δ(rest-cont)     : {gr_m:+.4f} ± {gr_s:.4f}")
            print(f"    Probe best-action overwrite : {bo_m:.3f} ± {bo_s:.3f}")
            print(f"    Probe best-action restart   : {br_m:.3f} ± {br_s:.3f}")
            print(f"    Zero-k Δ(over-cont)         : {goz_m:+.4f} ± {goz_s:.4f}")
            print(f"    Zero-k Δ(rest-cont)         : {grz_m:+.4f} ± {grz_s:.4f}")

print("\nDone.")

# M-CLTR v6.0 — Phase 1 + Phase 2 diagnostic cell
# Goal:
#   1) Freeze a base knowledge model
#   2) Train a separate M-CLTR reasoning layer on top
#   3) Run action-truth diagnostics:
#        - continue-only
#        - forced overwrite
#        - forced restart
#        - step-wise oracle
#        - zero-knowledge ablation
#        - per-step probe: which action is best?
#
# This cell intentionally does NOT train a policy head yet.
# It is designed to answer: "what is really happening with continue / overwrite / restart?"

import copy
import math
import random
import time
from dataclasses import dataclass
from typing import Dict, List, Optional, Tuple

import numpy as np
import torch
import torch.nn as nn
import torch.nn.functional as F

from sklearn.datasets import load_digits
from sklearn.model_selection import train_test_split

# ============================================================
# Device / reproducibility
# ============================================================
DEVICE = torch.device("cuda" if torch.cuda.is_available() else "cpu")
print("Device:", DEVICE)

def set_seed(seed: int):
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    if torch.cuda.is_available():
        torch.cuda.manual_seed_all(seed)

# ============================================================
# Config
# ============================================================
T = 6
X_DIM = 64
K_DIM = 64
Z_DIM = 96
TASK_CLASSES = 2
DIGIT_CLASSES = 10

# Keep this CPU-friendly
SEEDS = [7, 17]
BASE_EPOCH_SWEEP = [1, 4]   # weak / medium
BASE_STEPS_PER_EPOCH = 24
DIRECT_STEPS_PER_EPOCH = 24
REASONER_STEPS_PER_EPOCH = 24
EVAL_STEPS_PER_EPOCH = 24

BATCH_SIZE = 128

LR_BASE = 2e-3
LR_DIRECT = 2e-3
LR_REASONER = 2e-3
LR_EVAL = 2e-3

TRAIN_LEVELS = [0, 1, 2]
EVAL_LEVELS = [0, 1, 2, 3, 4]

# Overwrite variants to test
OVERWRITE_SPECS = [
    ("weak", 0.20),
    ("weak", 0.50),
    ("weak", 0.80),
    ("context", 0.50),
    ("gated", (0.05, 0.95)),
]

LEVEL_SPECS = {
    0: {
        "name": "easy / no switch",
        "switch_step": T,
        "input_noise": 0.00,
        "corrupt_step": None,
        "corrupt_severity": 0.00,
    },
    1: {
        "name": "medium / mid switch",
        "switch_step": T // 2,
        "input_noise": 0.00,
        "corrupt_step": None,
        "corrupt_severity": 0.00,
    },
    2: {
        "name": "hard / early switch",
        "switch_step": 1,
        "input_noise": 0.00,
        "corrupt_step": None,
        "corrupt_severity": 0.00,
    },
    3: {
        "name": "switch + latent mistake",
        "switch_step": T // 2,
        "input_noise": 0.00,
        "corrupt_step": 2,
        "corrupt_severity": 0.35,
    },
    4: {
        "name": "switch + noise + mistake",
        "switch_step": 1,
        "input_noise": 0.15,
        "corrupt_step": 1,
        "corrupt_severity": 0.45,
    },
}

# ============================================================
# Data
# ============================================================
digits = load_digits()
X_all = torch.tensor(digits.data, dtype=torch.float32) / 16.0
y_all = torch.tensor(digits.target, dtype=torch.long)

X_train_np, X_test_np, y_train_np, y_test_np = train_test_split(
    X_all.numpy(),
    y_all.numpy(),
    test_size=0.30,
    random_state=0,
    stratify=y_all.numpy(),
)

X_train = torch.tensor(X_train_np, dtype=torch.float32, device=DEVICE)
y_train = torch.tensor(y_train_np, dtype=torch.long, device=DEVICE)
X_test = torch.tensor(X_test_np, dtype=torch.float32, device=DEVICE)
y_test = torch.tensor(y_test_np, dtype=torch.long, device=DEVICE)

# ============================================================
# Utilities
# ============================================================
def one_hot(v: torch.Tensor, n: int) -> torch.Tensor:
    return F.one_hot(v.long(), n).float()

def step_feature(t: int, batch_size: int, device: torch.device) -> torch.Tensor:
    if T <= 1:
        s = 0.0
    else:
        s = float(t) / float(T - 1)
    return torch.full((batch_size, 1), s, device=device)

def mean_std(values):
    arr = np.asarray(values, dtype=np.float64)
    if arr.size == 1:
        return float(arr.item()), 0.0
    return float(arr.mean()), float(arr.std(ddof=1))

def sample_indices(n: int, batch_size: int) -> torch.Tensor:
    return torch.randint(0, n, (batch_size,), device=DEVICE)

def task_value(digit_labels: torch.Tensor, mode: torch.Tensor) -> torch.Tensor:
    # mode 0 = parity, mode 1 = high/low
    parity = (digit_labels % 2).long()
    highlow = (digit_labels >= 5).long()
    return torch.where(mode == 0, parity, highlow)

def get_level_spec(level: int) -> Dict:
    return LEVEL_SPECS[level]

def level_name(level: int) -> str:
    return LEVEL_SPECS[level]["name"]

def spec_to_str(spec: Tuple):
    kind, arg = spec
    if kind == "gated":
        lo, hi = arg
        return f"gated({lo:.2f},{hi:.2f})"
    return f"{kind}({arg:.2f})"

def inject_mistake(z: torch.Tensor, severity: float) -> torch.Tensor:
    if severity <= 0:
        return z
    rolled = torch.roll(z, shifts=1, dims=-1)
    mixed = (1.0 - severity) * z + severity * rolled
    mixed = mixed + (0.50 * severity) * torch.randn_like(z)
    return mixed

def set_requires_grad(module: nn.Module, flag: bool):
    for p in module.parameters():
        p.requires_grad = flag

# ============================================================
# Batch generation
# ============================================================
def make_reasoning_batch(
    x_pool: torch.Tensor,
    y_pool: torch.Tensor,
    batch_size: int,
    level: int,
):
    spec = get_level_spec(level)

    idx = sample_indices(x_pool.size(0), batch_size)
    x = x_pool[idx].clone()

    if spec["input_noise"] > 0:
        x = torch.clamp(x + spec["input_noise"] * torch.randn_like(x), 0.0, 1.0)

    digit_labels = y_pool[idx]
    start_mode = torch.randint(0, 2, (batch_size,), device=DEVICE)

    switch_step = spec["switch_step"]
    if switch_step >= T:
        end_mode = start_mode.clone()
    else:
        end_mode = 1 - start_mode

    start_ctrl = one_hot(start_mode, 2)

    t_ids = torch.arange(T, device=DEVICE).unsqueeze(0).expand(batch_size, T)
    curr_modes = torch.where(t_ids < switch_step, start_mode.unsqueeze(1), end_mode.unsqueeze(1))
    ctrl_seq = one_hot(curr_modes, 2)  # [B, T, 2]

    final_mode = curr_modes[:, -1]
    target = task_value(digit_labels, final_mode)

    return x, digit_labels, start_mode, end_mode, start_ctrl, ctrl_seq, target

# ============================================================
# Models
# ============================================================
class MLP(nn.Module):
    def __init__(self, in_dim: int, out_dim: int, hidden: int = 128):
        super().__init__()
        self.net = nn.Sequential(
            nn.Linear(in_dim, hidden),
            nn.GELU(),
            nn.Linear(hidden, hidden),
            nn.GELU(),
            nn.Linear(hidden, out_dim),
        )

    def forward(self, x):
        return self.net(x)

class BaseKnowledgeProvider(nn.Module):
    """
    x -> k0
    Then k0 is treated as the plug-and-play knowledge input.
    """
    def __init__(self, x_dim: int = X_DIM, k_dim: int = K_DIM):
        super().__init__()
        self.encoder = nn.Sequential(
            nn.Linear(x_dim, 128),
            nn.GELU(),
            nn.Linear(128, k_dim),
            nn.LayerNorm(k_dim),
        )
        self.classifier = nn.Sequential(
            nn.Linear(k_dim, 64),
            nn.GELU(),
            nn.Linear(64, DIGIT_CLASSES),
        )

        for m in self.modules():
            if isinstance(m, nn.Linear):
                nn.init.xavier_uniform_(m.weight)
                if m.bias is not None:
                    nn.init.zeros_(m.bias)

    def encode(self, x: torch.Tensor) -> torch.Tensor:
        return self.encoder(x)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        k0 = self.encode(x)
        return self.classifier(k0)

class DirectStaticBaseline(nn.Module):
    """
    Static baseline:
    uses only k0 + start mode
    """
    def __init__(self, k_dim: int = K_DIM):
        super().__init__()
        self.head = MLP(k_dim + 2, TASK_CLASSES, hidden=96)

        for m in self.modules():
            if isinstance(m, nn.Linear):
                nn.init.xavier_uniform_(m.weight)
                if m.bias is not None:
                    nn.init.zeros_(m.bias)

    def forward(self, k0: torch.Tensor, start_ctrl: torch.Tensor) -> torch.Tensor:
        return self.head(torch.cat([k0, start_ctrl], dim=-1))

class MCLTRReasoner(nn.Module):
    """
    M-CLTR reasoning layer:
    - receives k0 from the base model
    - never directly sees raw x during reasoning
    - performs latent trajectory updates
    """
    def __init__(self, base: BaseKnowledgeProvider, k_dim: int = K_DIM, z_dim: int = Z_DIM):
        super().__init__()
        self.base = base
        self.k_dim = k_dim
        self.z_dim = z_dim

        self.init_net = MLP(k_dim + 2, z_dim, hidden=128)
        self.trans_net = MLP(z_dim + k_dim + 2 + 1, z_dim, hidden=128)
        self.context_net = MLP(k_dim + 2 + 1, z_dim, hidden=128)

        self.evaluator = MLP(z_dim + k_dim + 2 + 1, 1, hidden=96)
        self.decoder = nn.Linear(z_dim, TASK_CLASSES)

        self.z_norm = nn.LayerNorm(z_dim)
        self.ctx_norm = nn.LayerNorm(z_dim)

        for m in self.modules():
            if isinstance(m, nn.Linear):
                nn.init.xavier_uniform_(m.weight)
                if m.bias is not None:
                    nn.init.zeros_(m.bias)

    def knowledge(self, x: torch.Tensor) -> torch.Tensor:
        return self.base.encode(x)

    def init_state(self, k0: torch.Tensor, start_ctrl: torch.Tensor) -> torch.Tensor:
        z0 = self.init_net(torch.cat([k0, start_ctrl], dim=-1))
        return self.z_norm(z0)

    def context_state(self, k0: torch.Tensor, ctrl: torch.Tensor, t: int) -> torch.Tensor:
        step = step_feature(t, k0.size(0), k0.device)
        ctx = self.context_net(torch.cat([k0, ctrl, step], dim=-1))
        return self.ctx_norm(ctx)

    def step_update(self, z: torch.Tensor, k0: torch.Tensor, ctrl: torch.Tensor, t: int) -> torch.Tensor:
        step = step_feature(t, z.size(0), z.device)
        inp = torch.cat([z, k0, ctrl, step], dim=-1)
        delta = torch.tanh(self.trans_net(inp))
        cand = self.z_norm(0.80 * z + 0.20 * delta)
        return cand

    def eval_score(self, z: torch.Tensor, k0: torch.Tensor, ctrl: torch.Tensor, t: int) -> torch.Tensor:
        step = step_feature(t, z.size(0), z.device)
        inp = torch.cat([z, k0, ctrl, step], dim=-1)
        return torch.sigmoid(self.evaluator(inp)).squeeze(-1)

    def decode(self, z: torch.Tensor) -> torch.Tensor:
        return self.decoder(z)

    def overwrite_state(
        self,
        cand: torch.Tensor,
        z0: torch.Tensor,
        k0: torch.Tensor,
        ctrl: torch.Tensor,
        t: int,
        overwrite_spec: Tuple,
    ) -> torch.Tensor:
        kind, arg = overwrite_spec

        if kind == "weak":
            alpha = float(arg)
            fresh = z0
        elif kind == "context":
            alpha = float(arg)
            fresh = self.context_state(k0, ctrl, t)
        elif kind == "gated":
            lo, hi = arg
            gate = self.eval_score(cand, k0, ctrl, t)
            alpha = lo + (hi - lo) * gate
            fresh = self.context_state(k0, ctrl, t)
            return self.z_norm(alpha.unsqueeze(-1) * cand + (1.0 - alpha.unsqueeze(-1)) * fresh)
        else:
            raise ValueError(f"Unknown overwrite spec kind: {kind}")

        return self.z_norm(alpha * cand + (1.0 - alpha) * fresh)

# ============================================================
# Rollout helpers
# ============================================================
@torch.no_grad()
def continue_rollout_from_state(
    reasoner: MCLTRReasoner,
    z_start: torch.Tensor,
    k0: torch.Tensor,
    ctrl_seq: torch.Tensor,
    start_t: int,
    level: int,
) -> torch.Tensor:
    spec = get_level_spec(level)
    z = z_start
    for t in range(start_t, T):
        z = reasoner.step_update(z, k0, ctrl_seq[:, t, :], t)
        if spec["corrupt_step"] is not None and t == spec["corrupt_step"]:
            z = inject_mistake(z, spec["corrupt_severity"])
    return z

@torch.no_grad()
def final_target_prob_from_state(
    reasoner: MCLTRReasoner,
    z_start: torch.Tensor,
    k0: torch.Tensor,
    ctrl_seq: torch.Tensor,
    start_t: int,
    target: torch.Tensor,
    level: int,
) -> torch.Tensor:
    z_final = continue_rollout_from_state(reasoner, z_start, k0, ctrl_seq, start_t, level)
    logits = reasoner.decode(z_final)
    probs = F.softmax(logits, dim=-1)
    return probs.gather(1, target.unsqueeze(1)).squeeze(1)

@torch.no_grad()
def choose_oracle_action(
    reasoner: MCLTRReasoner,
    cand: torch.Tensor,
    z0: torch.Tensor,
    k0: torch.Tensor,
    ctrl_seq: torch.Tensor,
    t: int,
    target: torch.Tensor,
    overwrite_spec: Tuple,
    level: int,
):
    cont_state = cand
    over_state = reasoner.overwrite_state(cand, z0, k0, ctrl_seq[:, t, :], t, overwrite_spec)
    rest_state = z0

    p_cont = final_target_prob_from_state(reasoner, cont_state, k0, ctrl_seq, t + 1, target, level)
    p_over = final_target_prob_from_state(reasoner, over_state, k0, ctrl_seq, t + 1, target, level)
    p_rest = final_target_prob_from_state(reasoner, rest_state, k0, ctrl_seq, t + 1, target, level)

    probs = torch.stack([p_cont, p_over, p_rest], dim=-1)  # [B, 3]
    tie_bias = torch.tensor([2e-3, 1e-3, 0.0], device=probs.device).unsqueeze(0)
    action = (probs + tie_bias).argmax(dim=-1)
    best_prob = probs.gather(1, action.unsqueeze(1)).squeeze(1)
    return action, probs, best_prob

# ============================================================
# Training
# ============================================================
def train_base(base: BaseKnowledgeProvider, epochs: int, steps_per_epoch: int):
    base.train()
    opt = torch.optim.AdamW(base.parameters(), lr=LR_BASE, weight_decay=1e-4)
    ce = nn.CrossEntropyLoss()

    print("\n=== Stage 1: base knowledge pretraining (digit classification) ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_acc = 0.0

        for _ in range(steps_per_epoch):
            idx = sample_indices(X_train.size(0), BATCH_SIZE)
            xb = X_train[idx]
            yb = y_train[idx]

            logits = base(xb)
            loss = ce(logits, yb)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(base.parameters(), 1.0)
            opt.step()

            total_loss += loss.item()
            total_acc += (logits.argmax(dim=-1) == yb).float().mean().item()

        print(
            f"Base epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} "
            f"| acc {total_acc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s"
        )

def train_direct_head(
    base: BaseKnowledgeProvider,
    direct: DirectStaticBaseline,
    epochs: int,
    steps_per_epoch: int,
):
    direct.train()
    set_requires_grad(base, False)
    opt = torch.optim.AdamW(direct.parameters(), lr=LR_DIRECT, weight_decay=1e-4)
    ce = nn.CrossEntropyLoss()

    print("\n=== Stage 2: direct static baseline head (no online control) ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_acc = 0.0

        for _ in range(steps_per_epoch):
            level = random.choice(TRAIN_LEVELS)
            x, digit_labels, start_mode, end_mode, start_ctrl, ctrl_seq, target = make_reasoning_batch(
                X_train, y_train, BATCH_SIZE, level=level
            )

            with torch.no_grad():
                k0 = base.encode(x)

            logits = direct(k0, start_ctrl)
            loss = ce(logits, target)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(direct.parameters(), 1.0)
            opt.step()

            total_loss += loss.item()
            total_acc += (logits.argmax(dim=-1) == target).float().mean().item()

        print(
            f"Direct epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} "
            f"| acc {total_acc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s"
        )

def train_reasoner_continue_only(
    base: BaseKnowledgeProvider,
    reasoner: MCLTRReasoner,
    epochs: int,
    steps_per_epoch: int,
):
    reasoner.train()
    set_requires_grad(base, False)
    set_requires_grad(reasoner.init_net, True)
    set_requires_grad(reasoner.trans_net, True)
    set_requires_grad(reasoner.context_net, False)
    set_requires_grad(reasoner.evaluator, False)
    set_requires_grad(reasoner.decoder, True)
    set_requires_grad(reasoner.z_norm, True)
    set_requires_grad(reasoner.ctx_norm, False)

    params = (
        list(reasoner.init_net.parameters())
        + list(reasoner.trans_net.parameters())
        + list(reasoner.decoder.parameters())
        + list(reasoner.z_norm.parameters())
    )
    opt = torch.optim.AdamW(params, lr=LR_REASONER, weight_decay=1e-4)
    ce = nn.CrossEntropyLoss()

    print("\n=== Stage 3: reasoner pretraining (continue-only rollouts, mixed levels) ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_acc = 0.0

        for _ in range(steps_per_epoch):
            level = random.choice(TRAIN_LEVELS)
            x, digit_labels, start_mode, end_mode, start_ctrl, ctrl_seq, target = make_reasoning_batch(
                X_train, y_train, BATCH_SIZE, level=level
            )

            with torch.no_grad():
                k0 = base.encode(x)

            z = reasoner.init_state(k0, start_ctrl)
            for t in range(T):
                z = reasoner.step_update(z, k0, ctrl_seq[:, t, :], t)

            logits = reasoner.decode(z)
            loss = ce(logits, target)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(params, 1.0)
            opt.step()

            total_loss += loss.item()
            total_acc += (logits.argmax(dim=-1) == target).float().mean().item()

        print(
            f"Reasoner epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} "
            f"| acc {total_acc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s"
        )

def train_evaluator(
    base: BaseKnowledgeProvider,
    reasoner: MCLTRReasoner,
    epochs: int,
    steps_per_epoch: int,
):
    reasoner.eval()
    set_requires_grad(base, False)
    set_requires_grad(reasoner.init_net, False)
    set_requires_grad(reasoner.trans_net, False)
    set_requires_grad(reasoner.context_net, False)
    set_requires_grad(reasoner.decoder, False)
    set_requires_grad(reasoner.z_norm, False)
    set_requires_grad(reasoner.ctx_norm, False)
    set_requires_grad(reasoner.evaluator, True)

    opt = torch.optim.AdamW(reasoner.evaluator.parameters(), lr=LR_EVAL, weight_decay=1e-4)
    mse = nn.MSELoss()

    print("\n=== Stage 4: evaluator training (predict final correctness probability) ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_binacc = 0.0

        for _ in range(steps_per_epoch):
            level = random.choice(EVAL_LEVELS)
            x, digit_labels, start_mode, end_mode, start_ctrl, ctrl_seq, target = make_reasoning_batch(
                X_train, y_train, BATCH_SIZE, level=level
            )

            with torch.no_grad():
                k0 = base.encode(x)
                z = reasoner.init_state(k0, start_ctrl)

                step_z = []
                step_k0 = []
                step_ctrl = []
                step_t = []
                labels = []

                for t in range(T):
                    cand = reasoner.step_update(z, k0, ctrl_seq[:, t, :], t)
                    p_target = final_target_prob_from_state(
                        reasoner, cand, k0, ctrl_seq, t + 1, target, level
                    )

                    step_z.append(cand.detach())
                    step_k0.append(k0.detach())
                    step_ctrl.append(ctrl_seq[:, t, :].detach())
                    step_t.append(step_feature(t, BATCH_SIZE, DEVICE))
                    labels.append(p_target.detach())

                    z = cand

                step_z = torch.cat(step_z, dim=0)
                step_k0 = torch.cat(step_k0, dim=0)
                step_ctrl = torch.cat(step_ctrl, dim=0)
                step_t = torch.cat(step_t, dim=0)
                labels = torch.cat(labels, dim=0).clamp(0.0, 1.0)

            inp = torch.cat([step_z, step_k0, step_ctrl, step_t], dim=-1)
            pred = torch.sigmoid(reasoner.evaluator(inp)).squeeze(-1)
            loss = mse(pred, labels)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(reasoner.evaluator.parameters(), 1.0)
            opt.step()

            total_loss += loss.item()
            total_binacc += ((pred > 0.5) == (labels > 0.5)).float().mean().item()

        print(
            f"Evaluator epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} "
            f"| bin-acc {total_binacc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s"
        )

# ============================================================
# Rollout / evaluation
# ============================================================
@torch.no_grad()
def rollout_reasoner(
    reasoner: MCLTRReasoner,
    k0: torch.Tensor,
    start_ctrl: torch.Tensor,
    ctrl_seq: torch.Tensor,
    target: Optional[torch.Tensor],
    level: int,
    mode: str,
    overwrite_spec: Optional[Tuple] = None,
    zero_k0: bool = False,
):
    """
    mode:
      - continue
      - overwrite
      - restart
      - oracle
    """
    if zero_k0:
        k0 = torch.zeros_like(k0)

    z0 = reasoner.init_state(k0, start_ctrl)
    z = z0

    spec = get_level_spec(level)
    actions = []
    step_probs = []

    for t in range(T):
        cand = reasoner.step_update(z, k0, ctrl_seq[:, t, :], t)

        # Optional corruption for stress-test levels
        if spec["corrupt_step"] is not None and t == spec["corrupt_step"]:
            cand = inject_mistake(cand, spec["corrupt_severity"])

        if mode == "continue":
            action = torch.zeros(k0.size(0), dtype=torch.long, device=k0.device)
            z_next = cand

        elif mode == "overwrite":
            if overwrite_spec is None:
                raise ValueError("overwrite_spec is required for overwrite mode")
            action = torch.ones(k0.size(0), dtype=torch.long, device=k0.device)
            z_next = reasoner.overwrite_state(cand, z0, k0, ctrl_seq[:, t, :], t, overwrite_spec)

        elif mode == "restart":
            action = torch.full((k0.size(0),), 2, dtype=torch.long, device=k0.device)
            z_next = z0

        elif mode == "oracle":
            if overwrite_spec is None:
                raise ValueError("overwrite_spec is required for oracle mode")
            if target is None:
                raise ValueError("oracle mode requires target")
            action, probs, _ = choose_oracle_action(
                reasoner, cand, z0, k0, ctrl_seq, t, target, overwrite_spec, level
            )
            z_next = torch.empty_like(cand)

            cont_mask = action == 0
            over_mask = action == 1
            rest_mask = action == 2

            if cont_mask.any():
                z_next[cont_mask] = cand[cont_mask]
            if over_mask.any():
                z_next[over_mask] = reasoner.overwrite_state(
                    cand[over_mask],
                    z0[over_mask],
                    k0[over_mask],
                    ctrl_seq[over_mask, t, :],
                    t,
                    overwrite_spec,
                )
            if rest_mask.any():
                z_next[rest_mask] = z0[rest_mask]

            step_probs.append(probs)

        else:
            raise ValueError(f"Unknown rollout mode: {mode}")

        actions.append(action)
        z = z_next

    logits = reasoner.decode(z)
    pred = logits.argmax(dim=-1)

    final_ctrl = ctrl_seq[:, -1, :]
    final_eval = reasoner.eval_score(z, k0, final_ctrl, T - 1)

    out = {
        "logits": logits,
        "pred": pred,
        "actions": torch.stack(actions, dim=1),
        "final_eval": final_eval,
        "z0": z0,
    }
    if mode == "oracle":
        out["step_probs"] = torch.stack(step_probs, dim=1)
    return out

@torch.no_grad()
def eval_base_classifier(base: BaseKnowledgeProvider, batches: int = 12, bs: int = 256):
    base.eval()
    total = 0
    correct = 0
    for _ in range(batches):
        idx = sample_indices(X_test.size(0), bs)
        xb = X_test[idx]
        yb = y_test[idx]
        logits = base(xb)
        pred = logits.argmax(dim=-1)
        correct += (pred == yb).sum().item()
        total += yb.numel()
    return correct / total

@torch.no_grad()
def eval_direct_baseline(
    base: BaseKnowledgeProvider,
    direct: DirectStaticBaseline,
    level: int,
    batches: int = 12,
    bs: int = 256,
):
    direct.eval()
    base.eval()
    total = 0
    correct = 0
    for _ in range(batches):
        x, digit_labels, start_mode, end_mode, start_ctrl, ctrl_seq, target = make_reasoning_batch(
            X_test, y_test, bs, level=level
        )
        k0 = base.encode(x)
        logits = direct(k0, start_ctrl)
        pred = logits.argmax(dim=-1)
        correct += (pred == target).sum().item()
        total += target.numel()
    return correct / total

@torch.no_grad()
def eval_rollout_mode(
    base: BaseKnowledgeProvider,
    reasoner: MCLTRReasoner,
    level: int,
    mode: str,
    overwrite_spec: Tuple,
    zero_k0: bool,
    batches: int = 12,
    bs: int = 256,
):
    base.eval()
    reasoner.eval()

    total = 0
    correct = 0
    action_counts = torch.zeros(3, device=DEVICE)
    score_correct = []
    score_incorrect = []

    for _ in range(batches):
        x, digit_labels, start_mode, end_mode, start_ctrl, ctrl_seq, target = make_reasoning_batch(
            X_test, y_test, bs, level=level
        )

        k0 = base.encode(x)
        out = rollout_reasoner(
            reasoner,
            k0,
            start_ctrl,
            ctrl_seq,
            target=target if mode == "oracle" else None,
            level=level,
            mode=mode,
            overwrite_spec=overwrite_spec,
            zero_k0=zero_k0,
        )

        pred = out["pred"]
        correct_mask = pred == target
        correct += correct_mask.sum().item()
        total += target.numel()

        if mode == "oracle":
            action_counts += torch.stack([
                (out["actions"] == 0).sum(),
                (out["actions"] == 1).sum(),
                (out["actions"] == 2).sum(),
            ]).float()

        score = out["final_eval"]
        if correct_mask.any():
            score_correct.append(score[correct_mask].mean().item())
        if (~correct_mask).any():
            score_incorrect.append(score[~correct_mask].mean().item())

    result = {
        "acc": correct / total,
        "score_correct_mean": float(np.mean(score_correct)) if len(score_correct) else float("nan"),
        "score_incorrect_mean": float(np.mean(score_incorrect)) if len(score_incorrect) else float("nan"),
    }
    if mode == "oracle":
        rates = (action_counts / (batches * bs * T)).detach().cpu().numpy()
        result["continue_rate"] = float(rates[0])
        result["overwrite_rate"] = float(rates[1])
        result["restart_rate"] = float(rates[2])
    return result

@torch.no_grad()
def probe_actions(
    base: BaseKnowledgeProvider,
    reasoner: MCLTRReasoner,
    level: int,
    overwrite_spec: Tuple,
    zero_k0: bool,
    batches: int = 4,
    bs: int = 128,
):
    """
    For each step:
      - mean final target probability if we continue / overwrite / restart
      - best-action rate
      - delta relative to continue
    """
    base.eval()
    reasoner.eval()

    best_counts = torch.zeros(T, 3, device=DEVICE)
    mean_probs = torch.zeros(T, 3, device=DEVICE)
    gain_over_continue = torch.zeros(T, device=DEVICE)
    gain_restart_over_continue = torch.zeros(T, device=DEVICE)

    for _ in range(batches):
        x, digit_labels, start_mode, end_mode, start_ctrl, ctrl_seq, target = make_reasoning_batch(
            X_test, y_test, bs, level=level
        )
        k0 = base.encode(x)
        if zero_k0:
            k0 = torch.zeros_like(k0)

        z0 = reasoner.init_state(k0, start_ctrl)
        z = z0
        spec = get_level_spec(level)

        for t in range(T):
            cand = reasoner.step_update(z, k0, ctrl_seq[:, t, :], t)

            if spec["corrupt_step"] is not None and t == spec["corrupt_step"]:
                cand = inject_mistake(cand, spec["corrupt_severity"])

            cont_state = cand
            over_state = reasoner.overwrite_state(cand, z0, k0, ctrl_seq[:, t, :], t, overwrite_spec)
            rest_state = z0

            p_cont = final_target_prob_from_state(reasoner, cont_state, k0, ctrl_seq, t + 1, target, level)
            p_over = final_target_prob_from_state(reasoner, over_state, k0, ctrl_seq, t + 1, target, level)
            p_rest = final_target_prob_from_state(reasoner, rest_state, k0, ctrl_seq, t + 1, target, level)

            probs = torch.stack([p_cont, p_over, p_rest], dim=-1)
            best = probs.argmax(dim=-1)

            for a in range(3):
                best_counts[t, a] += (best == a).sum()

            mean_probs[t, 0] += p_cont.sum()
            mean_probs[t, 1] += p_over.sum()
            mean_probs[t, 2] += p_rest.sum()

            gain_over_continue[t] += (p_over - p_cont).sum()
            gain_restart_over_continue[t] += (p_rest - p_cont).sum()

            z = cand

    denom = batches * bs
    return {
        "mean_probs": (mean_probs / denom).cpu().numpy(),
        "best_rates": (best_counts / denom).cpu().numpy(),
        "gain_over_continue": (gain_over_continue / denom).cpu().numpy(),
        "gain_restart_over_continue": (gain_restart_over_continue / denom).cpu().numpy(),
    }

def print_probe_summary(probe: Dict, level: int, overwrite_spec: Tuple, zero_k0: bool):
    zk = "zero-k0" if zero_k0 else "normal-k0"
    print(f"\n--- Action probe: level {level} ({level_name(level)}), spec={spec_to_str(overwrite_spec)}, {zk} ---")
    for t in range(T):
        mp = probe["mean_probs"][t]
        br = probe["best_rates"][t]
        g_over = probe["gain_over_continue"][t]
        g_rest = probe["gain_restart_over_continue"][t]
        print(
            f"step {t}: mean p(cont/over/rest)=({mp[0]:.3f}, {mp[1]:.3f}, {mp[2]:.3f}) | "
            f"best rates=({br[0]:.3f}, {br[1]:.3f}, {br[2]:.3f}) | "
            f"Δover-cont={g_over:+.4f} | Δrestart-cont={g_rest:+.4f}"
        )

# ============================================================
# One run for one seed + base strength
# ============================================================
def run_one_seed_and_base_strength(seed: int, base_epochs: int):
    set_seed(seed)
    print("\n\n##############################")
    print(f"Seed = {seed} | base_epochs = {base_epochs}")
    print("##############################")

    base = BaseKnowledgeProvider().to(DEVICE)
    direct = DirectStaticBaseline().to(DEVICE)
    reasoner = MCLTRReasoner(base).to(DEVICE)

    # Stage 1: base knowledge
    train_base(base, base_epochs, BASE_STEPS_PER_EPOCH)

    # Freeze a copy to keep the knowledge provider stable
    frozen_base = copy.deepcopy(base).to(DEVICE)
    set_requires_grad(frozen_base, False)
    direct.base = frozen_base
    reasoner.base = frozen_base

    # Stage 2: direct static baseline
    train_direct_head(frozen_base, direct, epochs=3, steps_per_epoch=DIRECT_STEPS_PER_EPOCH)

    # Stage 3: M-CLTR continue-only reasoning
    train_reasoner_continue_only(frozen_base, reasoner, epochs=4, steps_per_epoch=REASONER_STEPS_PER_EPOCH)

    # Stage 4: evaluator
    train_evaluator(frozen_base, reasoner, epochs=2, steps_per_epoch=EVAL_STEPS_PER_EPOCH)

    # Base accuracy
    base_acc = eval_base_classifier(frozen_base, batches=12, bs=256)

    results = {}
    for level in EVAL_LEVELS:
        results[level] = {}

        direct_acc = eval_direct_baseline(frozen_base, direct, level=level, batches=12, bs=256)
        cont_normal = eval_rollout_mode(
            frozen_base, reasoner, level=level, mode="continue",
            overwrite_spec=OVERWRITE_SPECS[0], zero_k0=False,
            batches=12, bs=256
        )
        cont_zero = eval_rollout_mode(
            frozen_base, reasoner, level=level, mode="continue",
            overwrite_spec=OVERWRITE_SPECS[0], zero_k0=True,
            batches=12, bs=256
        )

        results[level]["base_acc"] = base_acc
        results[level]["direct_acc"] = direct_acc
        results[level]["continue_normal"] = cont_normal["acc"]
        results[level]["continue_zero"] = cont_zero["acc"]

        print(f"\n--- Seed {seed} | base_epochs {base_epochs} | Level {level} ({level_name(level)}) ---")
        print(f"Base classifier (digit ID only)      : {base_acc:.4f}")
        print(f"Direct static baseline              : {direct_acc:.4f}")
        print(f"M-CLTR continue-only (normal k0)    : {cont_normal['acc']:.4f}")
        print(f"M-CLTR continue-only (zero k0)      : {cont_zero['acc']:.4f}")
        print(f"Zero-knowledge gap                  : {cont_normal['acc'] - cont_zero['acc']:+.4f}")

        for spec in OVERWRITE_SPECS:
            overwrite_res = eval_rollout_mode(
                frozen_base, reasoner, level=level, mode="overwrite",
                overwrite_spec=spec, zero_k0=False,
                batches=12, bs=256
            )
            restart_res = eval_rollout_mode(
                frozen_base, reasoner, level=level, mode="restart",
                overwrite_spec=spec, zero_k0=False,
                batches=12, bs=256
            )
            oracle_res = eval_rollout_mode(
                frozen_base, reasoner, level=level, mode="oracle",
                overwrite_spec=spec, zero_k0=False,
                batches=12, bs=256
            )

            probe = probe_actions(
                frozen_base, reasoner, level=level, overwrite_spec=spec, zero_k0=False,
                batches=4, bs=128
            )
            probe_zero = probe_actions(
                frozen_base, reasoner, level=level, overwrite_spec=spec, zero_k0=True,
                batches=4, bs=128
            )

            key = spec_to_str(spec)
            results[level][key] = {
                "overwrite_acc": overwrite_res["acc"],
                "restart_acc": restart_res["acc"],
                "oracle_acc": oracle_res["acc"],
                "oracle_c": oracle_res["continue_rate"],
                "oracle_o": oracle_res["overwrite_rate"],
                "oracle_r": oracle_res["restart_rate"],
                "probe": probe,
                "probe_zero": probe_zero,
            }

            print(f"\n  Overwrite spec = {key}")
            print(f"    Forced overwrite acc          : {overwrite_res['acc']:.4f}")
            print(f"    Forced restart acc            : {restart_res['acc']:.4f}")
            print(f"    Step-wise oracle acc          : {oracle_res['acc']:.4f}")
            print(f"    Oracle action rates C/O/R     : {oracle_res['continue_rate']:.3f}/{oracle_res['overwrite_rate']:.3f}/{oracle_res['restart_rate']:.3f}")
            print_probe_summary(probe, level, spec, zero_k0=False)
            print_probe_summary(probe_zero, level, spec, zero_k0=True)

    return results

# ============================================================
# Run sweep
# ============================================================
all_results = {}
for base_epochs in BASE_EPOCH_SWEEP:
    all_results[base_epochs] = {}
    for seed in SEEDS:
        all_results[base_epochs][seed] = run_one_seed_and_base_strength(seed, base_epochs)

# ============================================================
# Aggregate summary
# ============================================================
print("\n\n==============================")
print("Aggregated summary across seeds and base strengths")
print("==============================")

for base_epochs in BASE_EPOCH_SWEEP:
    print(f"\n################################")
    print(f"Base epochs = {base_epochs}")
    print(f"################################")

    for level in EVAL_LEVELS:
        base_vals = []
        direct_vals = []
        cont_vals = []
        cont_zero_vals = []

        spec_summaries = {
            spec_to_str(spec): {
                "over": [],
                "rest": [],
                "oracle": [],
                "orc": [],
                "oro": [],
                "orr": [],
                "probe_over": [],
                "probe_rest": [],
                "probe_best_over": [],
                "probe_best_rest": [],
                "probe_over_zero": [],
                "probe_rest_zero": [],
            }
            for spec in OVERWRITE_SPECS
        }

        for seed in SEEDS:
            rr = all_results[base_epochs][seed][level]
            base_vals.append(rr["base_acc"])
            direct_vals.append(rr["direct_acc"])
            cont_vals.append(rr["continue_normal"])
            cont_zero_vals.append(rr["continue_zero"])

            for spec in OVERWRITE_SPECS:
                key = spec_to_str(spec)
                r = rr[key]
                spec_summaries[key]["over"].append(r["overwrite_acc"])
                spec_summaries[key]["rest"].append(r["restart_acc"])
                spec_summaries[key]["oracle"].append(r["oracle_acc"])
                spec_summaries[key]["orc"].append(r["oracle_c"])
                spec_summaries[key]["oro"].append(r["oracle_o"])
                spec_summaries[key]["orr"].append(r["oracle_r"])
                spec_summaries[key]["probe_over"].append(float(r["probe"]["gain_over_continue"].mean()))
                spec_summaries[key]["probe_rest"].append(float(r["probe"]["gain_restart_over_continue"].mean()))
                spec_summaries[key]["probe_best_over"].append(float(r["probe"]["best_rates"][:, 1].mean()))
                spec_summaries[key]["probe_best_rest"].append(float(r["probe"]["best_rates"][:, 2].mean()))
                spec_summaries[key]["probe_over_zero"].append(float(r["probe_zero"]["gain_over_continue"].mean()))
                spec_summaries[key]["probe_rest_zero"].append(float(r["probe_zero"]["gain_restart_over_continue"].mean()))

        bm, bs = mean_std(base_vals)
        dm, ds = mean_std(direct_vals)
        cm, cs = mean_std(cont_vals)
        czm, czs = mean_std(cont_zero_vals)

        print(f"\nLevel {level} ({level_name(level)})")
        print(f"  Base classifier              : {bm:.4f} ± {bs:.4f}")
        print(f"  Direct static baseline       : {dm:.4f} ± {ds:.4f}")
        print(f"  Continue-only (normal k0)    : {cm:.4f} ± {cs:.4f}")
        print(f"  Continue-only (zero k0)      : {czm:.4f} ± {czs:.4f}")
        print(f"  Zero-knowledge gap           : {(cm - czm):+.4f}")

        for spec in OVERWRITE_SPECS:
            key = spec_to_str(spec)
            om, os = mean_std(spec_summaries[key]["over"])
            rm, rs = mean_std(spec_summaries[key]["rest"])
            qm, qs = mean_std(spec_summaries[key]["oracle"])
            orc_m, orc_s = mean_std(spec_summaries[key]["orc"])
            oro_m, oro_s = mean_std(spec_summaries[key]["oro"])
            orr_m, orr_s = mean_std(spec_summaries[key]["orr"])
            go_m, go_s = mean_std(spec_summaries[key]["probe_over"])
            gr_m, gr_s = mean_std(spec_summaries[key]["probe_rest"])
            bo_m, bo_s = mean_std(spec_summaries[key]["probe_best_over"])
            br_m, br_s = mean_std(spec_summaries[key]["probe_best_rest"])
            goz_m, goz_s = mean_std(spec_summaries[key]["probe_over_zero"])
            grz_m, grz_s = mean_std(spec_summaries[key]["probe_rest_zero"])

            print(f"\n  Overwrite spec = {key}")
            print(f"    Forced overwrite acc        : {om:.4f} ± {os:.4f}")
            print(f"    Forced restart acc          : {rm:.4f} ± {rs:.4f}")
            print(f"    Step-wise oracle acc        : {qm:.4f} ± {qs:.4f}")
            print(f"    Oracle action rates C/O/R   : {orc_m:.3f} ± {orc_s:.3f} / {oro_m:.3f} ± {oro_s:.3f} / {orr_m:.3f} ± {orr_s:.3f}")
            print(f"    Probe mean Δ(over-cont)     : {go_m:+.4f} ± {go_s:.4f}")
            print(f"    Probe mean Δ(rest-cont)     : {gr_m:+.4f} ± {gr_s:.4f}")
            print(f"    Probe best-action overwrite : {bo_m:.3f} ± {bo_s:.3f}")
            print(f"    Probe best-action restart   : {br_m:.3f} ± {br_s:.3f}")
            print(f"    Zero-k Δ(over-cont)         : {goz_m:+.4f} ± {goz_s:.4f}")
            print(f"    Zero-k Δ(rest-cont)         : {grz_m:+.4f} ± {grz_s:.4f}")

print("\nDone.")

# M-CLTR v6.1 — overwrite redesign phase
# Goal:
#   1) Freeze a base knowledge model
#   2) Train a separate M-CLTR reasoning layer on top
#   3) Compare overwrite operators:
#        - weak blend
#        - projection-clamp overwrite
#        - gated projection overwrite
#        - gated residual overwrite
#   4) Keep the same action-truth diagnostics:
#        - continue-only
#        - forced overwrite
#        - forced restart
#        - step-wise oracle
#        - zero-knowledge ablation
#        - per-step probe: which action is best?
#
# This phase is about answering:
#   "Can overwrite become a real repair action if we redesign it better?"

import copy
import random
import time
from typing import Dict, List, Optional, Tuple

import numpy as np
import torch
import torch.nn as nn
import torch.nn.functional as F

from sklearn.datasets import load_digits
from sklearn.model_selection import train_test_split

# ============================================================
# Device / reproducibility
# ============================================================
DEVICE = torch.device("cuda" if torch.cuda.is_available() else "cpu")
print("Device:", DEVICE)

def set_seed(seed: int):
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    if torch.cuda.is_available():
        torch.cuda.manual_seed_all(seed)

# ============================================================
# Config
# ============================================================
T = 6
X_DIM = 64
K_DIM = 64
Z_DIM = 96
TASK_CLASSES = 2
DIGIT_CLASSES = 10

# CPU-friendly
SEEDS = [7, 17]
BASE_EPOCH_SWEEP = [1, 4]   # weak / medium base
BASE_STEPS_PER_EPOCH = 24
DIRECT_STEPS_PER_EPOCH = 24
REASONER_STEPS_PER_EPOCH = 24
EVAL_STEPS_PER_EPOCH = 24

BATCH_SIZE = 128

LR_BASE = 2e-3
LR_DIRECT = 2e-3
LR_REASONER = 2e-3
LR_EVAL = 2e-3

TRAIN_LEVELS = [0, 1, 2]
EVAL_LEVELS = [0, 1, 2, 3, 4]

# Overwrite operators to test
# Format:
#   ("blend", alpha)
#   ("project", max_shift)
#   ("gated_project", (min_shift, max_shift))
#   ("gated_residual", (min_alpha, max_alpha))
OVERWRITE_SPECS = [
    ("blend", 0.80),
    ("project", 6.0),
    ("gated_project", (1.0, 6.0)),
    ("gated_residual", (0.10, 0.90)),
]

LEVEL_SPECS = {
    0: {
        "name": "easy / no switch",
        "switch_step": T,
        "input_noise": 0.00,
        "corrupt_step": None,
        "corrupt_severity": 0.00,
    },
    1: {
        "name": "medium / mid switch",
        "switch_step": T // 2,
        "input_noise": 0.00,
        "corrupt_step": None,
        "corrupt_severity": 0.00,
    },
    2: {
        "name": "hard / early switch",
        "switch_step": 1,
        "input_noise": 0.00,
        "corrupt_step": None,
        "corrupt_severity": 0.00,
    },
    3: {
        "name": "switch + latent mistake",
        "switch_step": T // 2,
        "input_noise": 0.00,
        "corrupt_step": 2,
        "corrupt_severity": 0.35,
    },
    4: {
        "name": "switch + noise + mistake",
        "switch_step": 1,
        "input_noise": 0.15,
        "corrupt_step": 1,
        "corrupt_severity": 0.45,
    },
}

# ============================================================
# Data
# ============================================================
digits = load_digits()
X_all = torch.tensor(digits.data, dtype=torch.float32) / 16.0
y_all = torch.tensor(digits.target, dtype=torch.long)

X_train_np, X_test_np, y_train_np, y_test_np = train_test_split(
    X_all.numpy(),
    y_all.numpy(),
    test_size=0.30,
    random_state=0,
    stratify=y_all.numpy(),
)

X_train = torch.tensor(X_train_np, dtype=torch.float32, device=DEVICE)
y_train = torch.tensor(y_train_np, dtype=torch.long, device=DEVICE)
X_test = torch.tensor(X_test_np, dtype=torch.float32, device=DEVICE)
y_test = torch.tensor(y_test_np, dtype=torch.long, device=DEVICE)

# ============================================================
# Utilities
# ============================================================
def one_hot(v: torch.Tensor, n: int) -> torch.Tensor:
    return F.one_hot(v.long(), n).float()

def step_feature(t: int, batch_size: int, device: torch.device) -> torch.Tensor:
    if T <= 1:
        s = 0.0
    else:
        s = float(t) / float(T - 1)
    return torch.full((batch_size, 1), s, device=device)

def mean_std(values):
    arr = np.asarray(values, dtype=np.float64)
    if arr.size == 1:
        return float(arr.item()), 0.0
    return float(arr.mean()), float(arr.std(ddof=1))

def sample_indices(n: int, batch_size: int) -> torch.Tensor:
    return torch.randint(0, n, (batch_size,), device=DEVICE)

def task_value(digit_labels: torch.Tensor, mode: torch.Tensor) -> torch.Tensor:
    parity = (digit_labels % 2).long()
    highlow = (digit_labels >= 5).long()
    return torch.where(mode == 0, parity, highlow)

def get_level_spec(level: int) -> Dict:
    return LEVEL_SPECS[level]

def level_name(level: int) -> str:
    return LEVEL_SPECS[level]["name"]

def spec_to_str(spec: Tuple):
    kind, arg = spec
    if kind == "gated_project":
        lo, hi = arg
        return f"gated_project({lo:.2f},{hi:.2f})"
    if kind == "gated_residual":
        lo, hi = arg
        return f"gated_residual({lo:.2f},{hi:.2f})"
    if kind == "project":
        return f"project(max_shift={arg:.1f})"
    if kind == "blend":
        return f"blend({arg:.2f})"
    return f"{kind}({arg})"

def inject_mistake(z: torch.Tensor, severity: float) -> torch.Tensor:
    if severity <= 0:
        return z
    rolled = torch.roll(z, shifts=1, dims=-1)
    mixed = (1.0 - severity) * z + severity * rolled
    mixed = mixed + (0.50 * severity) * torch.randn_like(z)
    return mixed

def set_requires_grad(module: nn.Module, flag: bool):
    for p in module.parameters():
        p.requires_grad = flag

# ============================================================
# Batch generation
# ============================================================
def make_reasoning_batch(
    x_pool: torch.Tensor,
    y_pool: torch.Tensor,
    batch_size: int,
    level: int,
):
    spec = get_level_spec(level)

    idx = sample_indices(x_pool.size(0), batch_size)
    x = x_pool[idx].clone()

    if spec["input_noise"] > 0:
        x = torch.clamp(x + spec["input_noise"] * torch.randn_like(x), 0.0, 1.0)

    digit_labels = y_pool[idx]
    start_mode = torch.randint(0, 2, (batch_size,), device=DEVICE)

    switch_step = spec["switch_step"]
    if switch_step >= T:
        end_mode = start_mode.clone()
    else:
        end_mode = 1 - start_mode

    start_ctrl = one_hot(start_mode, 2)

    t_ids = torch.arange(T, device=DEVICE).unsqueeze(0).expand(batch_size, T)
    curr_modes = torch.where(t_ids < switch_step, start_mode.unsqueeze(1), end_mode.unsqueeze(1))
    ctrl_seq = one_hot(curr_modes, 2)  # [B, T, 2]

    final_mode = curr_modes[:, -1]
    target = task_value(digit_labels, final_mode)

    return x, digit_labels, start_mode, end_mode, start_ctrl, ctrl_seq, target

# ============================================================
# Models
# ============================================================
class MLP(nn.Module):
    def __init__(self, in_dim: int, out_dim: int, hidden: int = 128):
        super().__init__()
        self.net = nn.Sequential(
            nn.Linear(in_dim, hidden),
            nn.GELU(),
            nn.Linear(hidden, hidden),
            nn.GELU(),
            nn.Linear(hidden, out_dim),
        )

    def forward(self, x):
        return self.net(x)

class BaseKnowledgeProvider(nn.Module):
    """
    x -> k0
    Then k0 is treated as the plug-and-play knowledge input.
    """
    def __init__(self, x_dim: int = X_DIM, k_dim: int = K_DIM):
        super().__init__()
        self.encoder = nn.Sequential(
            nn.Linear(x_dim, 128),
            nn.GELU(),
            nn.Linear(128, k_dim),
            nn.LayerNorm(k_dim),
        )
        self.classifier = nn.Sequential(
            nn.Linear(k_dim, 64),
            nn.GELU(),
            nn.Linear(64, DIGIT_CLASSES),
        )

        for m in self.modules():
            if isinstance(m, nn.Linear):
                nn.init.xavier_uniform_(m.weight)
                if m.bias is not None:
                    nn.init.zeros_(m.bias)

    def encode(self, x: torch.Tensor) -> torch.Tensor:
        return self.encoder(x)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        k0 = self.encode(x)
        return self.classifier(k0)

class DirectStaticBaseline(nn.Module):
    """
    Static baseline:
    uses only k0 + start mode.
    """
    def __init__(self, k_dim: int = K_DIM):
        super().__init__()
        self.head = MLP(k_dim + 2, TASK_CLASSES, hidden=96)

        for m in self.modules():
            if isinstance(m, nn.Linear):
                nn.init.xavier_uniform_(m.weight)
                if m.bias is not None:
                    nn.init.zeros_(m.bias)

    def forward(self, k0: torch.Tensor, start_ctrl: torch.Tensor) -> torch.Tensor:
        return self.head(torch.cat([k0, start_ctrl], dim=-1))

class MCLTRReasoner(nn.Module):
    """
    M-CLTR reasoning layer:
    - receives k0 from the base model
    - never directly sees raw x during reasoning
    - performs latent trajectory updates
    """
    def __init__(self, base: BaseKnowledgeProvider, k_dim: int = K_DIM, z_dim: int = Z_DIM):
        super().__init__()
        self.base = base
        self.k_dim = k_dim
        self.z_dim = z_dim

        self.init_net = MLP(k_dim + 2, z_dim, hidden=128)
        self.trans_net = MLP(z_dim + k_dim + 2 + 1, z_dim, hidden=128)
        self.context_net = MLP(k_dim + 2 + 1, z_dim, hidden=128)

        self.evaluator = MLP(z_dim + k_dim + 2 + 1, 1, hidden=96)
        self.decoder = nn.Linear(z_dim, TASK_CLASSES)

        self.z_norm = nn.LayerNorm(z_dim)
        self.ctx_norm = nn.LayerNorm(z_dim)

        for m in self.modules():
            if isinstance(m, nn.Linear):
                nn.init.xavier_uniform_(m.weight)
                if m.bias is not None:
                    nn.init.zeros_(m.bias)

    def knowledge(self, x: torch.Tensor) -> torch.Tensor:
        return self.base.encode(x)

    def init_state(self, k0: torch.Tensor, start_ctrl: torch.Tensor) -> torch.Tensor:
        z0 = self.init_net(torch.cat([k0, start_ctrl], dim=-1))
        return self.z_norm(z0)

    def context_state(self, k0: torch.Tensor, ctrl: torch.Tensor, t: int) -> torch.Tensor:
        step = step_feature(t, k0.size(0), k0.device)
        ctx = self.context_net(torch.cat([k0, ctrl, step], dim=-1))
        return self.ctx_norm(ctx)

    def step_update(self, z: torch.Tensor, k0: torch.Tensor, ctrl: torch.Tensor, t: int) -> torch.Tensor:
        step = step_feature(t, z.size(0), z.device)
        inp = torch.cat([z, k0, ctrl, step], dim=-1)
        delta = torch.tanh(self.trans_net(inp))
        cand = self.z_norm(0.80 * z + 0.20 * delta)
        return cand

    def eval_score(self, z: torch.Tensor, k0: torch.Tensor, ctrl: torch.Tensor, t: int) -> torch.Tensor:
        step = step_feature(t, z.size(0), z.device)
        inp = torch.cat([z, k0, ctrl, step], dim=-1)
        return torch.sigmoid(self.evaluator(inp)).squeeze(-1)

    def decode(self, z: torch.Tensor) -> torch.Tensor:
        return self.decoder(z)

    def overwrite_state(
        self,
        cand: torch.Tensor,
        z0: torch.Tensor,
        k0: torch.Tensor,
        ctrl: torch.Tensor,
        t: int,
        overwrite_spec: Tuple,
    ) -> torch.Tensor:
        """
        Overwrite operators:
          - blend: plain interpolation with z0
          - project: clip latent displacement away from z0
          - gated_project: evaluator score controls allowed displacement from z0
          - gated_residual: evaluator score controls residual blend toward z0
        """
        kind, arg = overwrite_spec

        if kind == "blend":
            alpha = float(arg)
            z = alpha * cand + (1.0 - alpha) * z0
            return self.z_norm(z)

        elif kind == "project":
            max_shift = float(arg)
            delta = cand - z0
            delta_norm = delta.norm(dim=-1, keepdim=True).clamp_min(1e-6)
            scale = torch.clamp(max_shift / delta_norm, max=1.0)
            z = z0 + delta * scale
            return self.z_norm(z)

        elif kind == "gated_project":
            min_shift, max_shift = arg
            gate = self.eval_score(cand, k0, ctrl, t)  # higher => keep more candidate
            allowed = min_shift + (max_shift - min_shift) * gate
            delta = cand - z0
            delta_norm = delta.norm(dim=-1, keepdim=True).clamp_min(1e-6)
            scale = torch.clamp(allowed.unsqueeze(-1) / delta_norm, max=1.0)
            z = z0 + delta * scale
            return self.z_norm(z)

        elif kind == "gated_residual":
            lo, hi = arg
            gate = self.eval_score(cand, k0, ctrl, t)  # higher => keep more candidate
            alpha = lo + (hi - lo) * gate
            z = alpha.unsqueeze(-1) * cand + (1.0 - alpha.unsqueeze(-1)) * z0
            return self.z_norm(z)

        else:
            raise ValueError(f"Unknown overwrite spec kind: {kind}")

# ============================================================
# Rollout helpers
# ============================================================
@torch.no_grad()
def continue_rollout_from_state(
    reasoner: MCLTRReasoner,
    z_start: torch.Tensor,
    k0: torch.Tensor,
    ctrl_seq: torch.Tensor,
    start_t: int,
    level: int,
) -> torch.Tensor:
    spec = get_level_spec(level)
    z = z_start
    for t in range(start_t, T):
        z = reasoner.step_update(z, k0, ctrl_seq[:, t, :], t)
        if spec["corrupt_step"] is not None and t == spec["corrupt_step"]:
            z = inject_mistake(z, spec["corrupt_severity"])
    return z

@torch.no_grad()
def final_target_prob_from_state(
    reasoner: MCLTRReasoner,
    z_start: torch.Tensor,
    k0: torch.Tensor,
    ctrl_seq: torch.Tensor,
    start_t: int,
    target: torch.Tensor,
    level: int,
) -> torch.Tensor:
    z_final = continue_rollout_from_state(reasoner, z_start, k0, ctrl_seq, start_t, level)
    logits = reasoner.decode(z_final)
    probs = F.softmax(logits, dim=-1)
    return probs.gather(1, target.unsqueeze(1)).squeeze(1)

@torch.no_grad()
def choose_oracle_action(
    reasoner: MCLTRReasoner,
    cand: torch.Tensor,
    z0: torch.Tensor,
    k0: torch.Tensor,
    ctrl_seq: torch.Tensor,
    t: int,
    target: torch.Tensor,
    overwrite_spec: Tuple,
    level: int,
):
    cont_state = cand
    over_state = reasoner.overwrite_state(cand, z0, k0, ctrl_seq[:, t, :], t, overwrite_spec)
    rest_state = z0

    p_cont = final_target_prob_from_state(reasoner, cont_state, k0, ctrl_seq, t + 1, target, level)
    p_over = final_target_prob_from_state(reasoner, over_state, k0, ctrl_seq, t + 1, target, level)
    p_rest = final_target_prob_from_state(reasoner, rest_state, k0, ctrl_seq, t + 1, target, level)

    probs = torch.stack([p_cont, p_over, p_rest], dim=-1)  # [B, 3]
    tie_bias = torch.tensor([2e-3, 1e-3, 0.0], device=probs.device).unsqueeze(0)
    action = (probs + tie_bias).argmax(dim=-1)
    best_prob = probs.gather(1, action.unsqueeze(1)).squeeze(1)
    return action, probs, best_prob

# ============================================================
# Training
# ============================================================
def train_base(base: BaseKnowledgeProvider, epochs: int, steps_per_epoch: int):
    base.train()
    opt = torch.optim.AdamW(base.parameters(), lr=LR_BASE, weight_decay=1e-4)
    ce = nn.CrossEntropyLoss()

    print("\n=== Stage 1: base knowledge pretraining (digit classification) ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_acc = 0.0

        for _ in range(steps_per_epoch):
            idx = sample_indices(X_train.size(0), BATCH_SIZE)
            xb = X_train[idx]
            yb = y_train[idx]

            logits = base(xb)
            loss = ce(logits, yb)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(base.parameters(), 1.0)
            opt.step()

            total_loss += loss.item()
            total_acc += (logits.argmax(dim=-1) == yb).float().mean().item()

        print(
            f"Base epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} "
            f"| acc {total_acc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s"
        )

def train_direct_head(
    base: BaseKnowledgeProvider,
    direct: DirectStaticBaseline,
    epochs: int,
    steps_per_epoch: int,
):
    direct.train()
    set_requires_grad(base, False)
    opt = torch.optim.AdamW(direct.parameters(), lr=LR_DIRECT, weight_decay=1e-4)
    ce = nn.CrossEntropyLoss()

    print("\n=== Stage 2: direct static baseline head (no online control) ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_acc = 0.0

        for _ in range(steps_per_epoch):
            level = random.choice(TRAIN_LEVELS)
            x, _, _, _, start_ctrl, _, target = make_reasoning_batch(
                X_train, y_train, BATCH_SIZE, level=level
            )

            with torch.no_grad():
                k0 = base.encode(x)

            logits = direct(k0, start_ctrl)
            loss = ce(logits, target)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(direct.parameters(), 1.0)
            opt.step()

            total_loss += loss.item()
            total_acc += (logits.argmax(dim=-1) == target).float().mean().item()

        print(
            f"Direct epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} "
            f"| acc {total_acc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s"
        )

def train_reasoner_continue_only(
    base: BaseKnowledgeProvider,
    reasoner: MCLTRReasoner,
    epochs: int,
    steps_per_epoch: int,
):
    reasoner.train()
    set_requires_grad(base, False)
    set_requires_grad(reasoner.init_net, True)
    set_requires_grad(reasoner.trans_net, True)
    set_requires_grad(reasoner.context_net, False)
    set_requires_grad(reasoner.evaluator, False)
    set_requires_grad(reasoner.decoder, True)
    set_requires_grad(reasoner.z_norm, True)
    set_requires_grad(reasoner.ctx_norm, False)

    params = (
        list(reasoner.init_net.parameters())
        + list(reasoner.trans_net.parameters())
        + list(reasoner.decoder.parameters())
        + list(reasoner.z_norm.parameters())
    )
    opt = torch.optim.AdamW(params, lr=LR_REASONER, weight_decay=1e-4)
    ce = nn.CrossEntropyLoss()

    print("\n=== Stage 3: reasoner pretraining (continue-only rollouts, mixed levels) ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_acc = 0.0

        for _ in range(steps_per_epoch):
            level = random.choice(TRAIN_LEVELS)
            x, _, _, _, start_ctrl, ctrl_seq, target = make_reasoning_batch(
                X_train, y_train, BATCH_SIZE, level=level
            )

            with torch.no_grad():
                k0 = base.encode(x)

            z = reasoner.init_state(k0, start_ctrl)
            for t in range(T):
                z = reasoner.step_update(z, k0, ctrl_seq[:, t, :], t)

            logits = reasoner.decode(z)
            loss = ce(logits, target)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(params, 1.0)
            opt.step()

            total_loss += loss.item()
            total_acc += (logits.argmax(dim=-1) == target).float().mean().item()

        print(
            f"Reasoner epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} "
            f"| acc {total_acc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s"
        )

def train_evaluator(
    base: BaseKnowledgeProvider,
    reasoner: MCLTRReasoner,
    epochs: int,
    steps_per_epoch: int,
):
    reasoner.eval()
    set_requires_grad(base, False)
    set_requires_grad(reasoner.init_net, False)
    set_requires_grad(reasoner.trans_net, False)
    set_requires_grad(reasoner.context_net, False)
    set_requires_grad(reasoner.decoder, False)
    set_requires_grad(reasoner.z_norm, False)
    set_requires_grad(reasoner.ctx_norm, False)
    set_requires_grad(reasoner.evaluator, True)

    opt = torch.optim.AdamW(reasoner.evaluator.parameters(), lr=LR_EVAL, weight_decay=1e-4)
    mse = nn.MSELoss()

    print("\n=== Stage 4: evaluator training (predict final correctness probability) ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_binacc = 0.0

        for _ in range(steps_per_epoch):
            level = random.choice(EVAL_LEVELS)
            x, _, _, _, start_ctrl, ctrl_seq, target = make_reasoning_batch(
                X_train, y_train, BATCH_SIZE, level=level
            )

            with torch.no_grad():
                k0 = base.encode(x)
                z = reasoner.init_state(k0, start_ctrl)

                step_z = []
                step_k0 = []
                step_ctrl = []
                step_t = []
                labels = []

                for t in range(T):
                    cand = reasoner.step_update(z, k0, ctrl_seq[:, t, :], t)
                    p_target = final_target_prob_from_state(
                        reasoner, cand, k0, ctrl_seq, t + 1, target, level
                    )

                    step_z.append(cand.detach())
                    step_k0.append(k0.detach())
                    step_ctrl.append(ctrl_seq[:, t, :].detach())
                    step_t.append(step_feature(t, BATCH_SIZE, DEVICE))
                    labels.append(p_target.detach())

                    z = cand

                step_z = torch.cat(step_z, dim=0)
                step_k0 = torch.cat(step_k0, dim=0)
                step_ctrl = torch.cat(step_ctrl, dim=0)
                step_t = torch.cat(step_t, dim=0)
                labels = torch.cat(labels, dim=0).clamp(0.0, 1.0)

            inp = torch.cat([step_z, step_k0, step_ctrl, step_t], dim=-1)
            pred = torch.sigmoid(reasoner.evaluator(inp)).squeeze(-1)
            loss = mse(pred, labels)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(reasoner.evaluator.parameters(), 1.0)
            opt.step()

            total_loss += loss.item()
            total_binacc += ((pred > 0.5) == (labels > 0.5)).float().mean().item()

        print(
            f"Evaluator epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} "
            f"| bin-acc {total_binacc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s"
        )

# ============================================================
# Rollout / evaluation
# ============================================================
@torch.no_grad()
def rollout_reasoner(
    reasoner: MCLTRReasoner,
    k0: torch.Tensor,
    start_ctrl: torch.Tensor,
    ctrl_seq: torch.Tensor,
    target: Optional[torch.Tensor],
    level: int,
    mode: str,
    overwrite_spec: Optional[Tuple] = None,
    zero_k0: bool = False,
):
    """
    mode:
      - continue
      - overwrite
      - restart
      - oracle
    """
    if zero_k0:
        k0 = torch.zeros_like(k0)

    z0 = reasoner.init_state(k0, start_ctrl)
    z = z0

    spec = get_level_spec(level)
    actions = []
    step_probs = []

    for t in range(T):
        cand = reasoner.step_update(z, k0, ctrl_seq[:, t, :], t)

        # Optional corruption for stress-test levels
        if spec["corrupt_step"] is not None and t == spec["corrupt_step"]:
            cand = inject_mistake(cand, spec["corrupt_severity"])

        if mode == "continue":
            action = torch.zeros(k0.size(0), dtype=torch.long, device=k0.device)
            z_next = cand

        elif mode == "overwrite":
            if overwrite_spec is None:
                raise ValueError("overwrite_spec is required for overwrite mode")
            action = torch.ones(k0.size(0), dtype=torch.long, device=k0.device)
            z_next = reasoner.overwrite_state(cand, z0, k0, ctrl_seq[:, t, :], t, overwrite_spec)

        elif mode == "restart":
            action = torch.full((k0.size(0),), 2, dtype=torch.long, device=k0.device)
            z_next = z0

        elif mode == "oracle":
            if overwrite_spec is None:
                raise ValueError("overwrite_spec is required for oracle mode")
            if target is None:
                raise ValueError("oracle mode requires target")
            action, probs, _ = choose_oracle_action(
                reasoner, cand, z0, k0, ctrl_seq, t, target, overwrite_spec, level
            )
            z_next = torch.empty_like(cand)

            cont_mask = action == 0
            over_mask = action == 1
            rest_mask = action == 2

            if cont_mask.any():
                z_next[cont_mask] = cand[cont_mask]
            if over_mask.any():
                z_next[over_mask] = reasoner.overwrite_state(
                    cand[over_mask],
                    z0[over_mask],
                    k0[over_mask],
                    ctrl_seq[over_mask, t, :],
                    t,
                    overwrite_spec,
                )
            if rest_mask.any():
                z_next[rest_mask] = z0[rest_mask]

            step_probs.append(probs)

        else:
            raise ValueError(f"Unknown rollout mode: {mode}")

        actions.append(action)
        z = z_next

    logits = reasoner.decode(z)
    pred = logits.argmax(dim=-1)

    final_ctrl = ctrl_seq[:, -1, :]
    final_eval = reasoner.eval_score(z, k0, final_ctrl, T - 1)

    out = {
        "logits": logits,
        "pred": pred,
        "actions": torch.stack(actions, dim=1),
        "final_eval": final_eval,
        "z0": z0,
    }
    if mode == "oracle":
        out["step_probs"] = torch.stack(step_probs, dim=1)
    return out

@torch.no_grad()
def eval_base_classifier(base: BaseKnowledgeProvider, batches: int = 8, bs: int = 256):
    base.eval()
    total = 0
    correct = 0
    for _ in range(batches):
        idx = sample_indices(X_test.size(0), bs)
        xb = X_test[idx]
        yb = y_test[idx]
        logits = base(xb)
        pred = logits.argmax(dim=-1)
        correct += (pred == yb).sum().item()
        total += yb.numel()
    return correct / total

@torch.no_grad()
def eval_direct_baseline(
    base: BaseKnowledgeProvider,
    direct: DirectStaticBaseline,
    level: int,
    batches: int = 8,
    bs: int = 256,
):
    direct.eval()
    base.eval()
    total = 0
    correct = 0
    for _ in range(batches):
        x, _, _, _, start_ctrl, _, target = make_reasoning_batch(
            X_test, y_test, bs, level=level
        )
        k0 = base.encode(x)
        logits = direct(k0, start_ctrl)
        pred = logits.argmax(dim=-1)
        correct += (pred == target).sum().item()
        total += target.numel()
    return correct / total

@torch.no_grad()
def eval_rollout_mode(
    base: BaseKnowledgeProvider,
    reasoner: MCLTRReasoner,
    level: int,
    mode: str,
    overwrite_spec: Tuple,
    zero_k0: bool,
    batches: int = 8,
    bs: int = 256,
):
    base.eval()
    reasoner.eval()

    total = 0
    correct = 0
    action_counts = torch.zeros(3, device=DEVICE)
    score_correct = []
    score_incorrect = []

    for _ in range(batches):
        x, _, _, _, start_ctrl, ctrl_seq, target = make_reasoning_batch(
            X_test, y_test, bs, level=level
        )

        k0 = base.encode(x)
        out = rollout_reasoner(
            reasoner,
            k0,
            start_ctrl,
            ctrl_seq,
            target=target if mode == "oracle" else None,
            level=level,
            mode=mode,
            overwrite_spec=overwrite_spec,
            zero_k0=zero_k0,
        )

        pred = out["pred"]
        correct_mask = pred == target
        correct += correct_mask.sum().item()
        total += target.numel()

        if mode == "oracle":
            action_counts += torch.stack([
                (out["actions"] == 0).sum(),
                (out["actions"] == 1).sum(),
                (out["actions"] == 2).sum(),
            ]).float()

        score = out["final_eval"]
        if correct_mask.any():
            score_correct.append(score[correct_mask].mean().item())
        if (~correct_mask).any():
            score_incorrect.append(score[~correct_mask].mean().item())

    result = {
        "acc": correct / total,
        "score_correct_mean": float(np.mean(score_correct)) if len(score_correct) else float("nan"),
        "score_incorrect_mean": float(np.mean(score_incorrect)) if len(score_incorrect) else float("nan"),
    }
    if mode == "oracle":
        rates = (action_counts / (batches * bs * T)).detach().cpu().numpy()
        result["continue_rate"] = float(rates[0])
        result["overwrite_rate"] = float(rates[1])
        result["restart_rate"] = float(rates[2])
    return result

@torch.no_grad()
def probe_actions(
    base: BaseKnowledgeProvider,
    reasoner: MCLTRReasoner,
    level: int,
    overwrite_spec: Tuple,
    zero_k0: bool,
    batches: int = 4,
    bs: int = 128,
):
    """
    For each step:
      - mean final target probability if we continue / overwrite / restart
      - best-action rate
      - delta relative to continue
    """
    base.eval()
    reasoner.eval()

    best_counts = torch.zeros(T, 3, device=DEVICE)
    mean_probs = torch.zeros(T, 3, device=DEVICE)
    gain_over_continue = torch.zeros(T, device=DEVICE)
    gain_restart_over_continue = torch.zeros(T, device=DEVICE)

    for _ in range(batches):
        x, _, _, _, start_ctrl, ctrl_seq, target = make_reasoning_batch(
            X_test, y_test, bs, level=level
        )
        k0 = base.encode(x)
        if zero_k0:
            k0 = torch.zeros_like(k0)

        z0 = reasoner.init_state(k0, start_ctrl)
        z = z0
        spec = get_level_spec(level)

        for t in range(T):
            cand = reasoner.step_update(z, k0, ctrl_seq[:, t, :], t)

            if spec["corrupt_step"] is not None and t == spec["corrupt_step"]:
                cand = inject_mistake(cand, spec["corrupt_severity"])

            cont_state = cand
            over_state = reasoner.overwrite_state(cand, z0, k0, ctrl_seq[:, t, :], t, overwrite_spec)
            rest_state = z0

            p_cont = final_target_prob_from_state(reasoner, cont_state, k0, ctrl_seq, t + 1, target, level)
            p_over = final_target_prob_from_state(reasoner, over_state, k0, ctrl_seq, t + 1, target, level)
            p_rest = final_target_prob_from_state(reasoner, rest_state, k0, ctrl_seq, t + 1, target, level)

            probs = torch.stack([p_cont, p_over, p_rest], dim=-1)
            best = probs.argmax(dim=-1)

            for a in range(3):
                best_counts[t, a] += (best == a).sum()

            mean_probs[t, 0] += p_cont.sum()
            mean_probs[t, 1] += p_over.sum()
            mean_probs[t, 2] += p_rest.sum()

            gain_over_continue[t] += (p_over - p_cont).sum()
            gain_restart_over_continue[t] += (p_rest - p_cont).sum()

            z = cand

    denom = batches * bs
    return {
        "mean_probs": (mean_probs / denom).cpu().numpy(),
        "best_rates": (best_counts / denom).cpu().numpy(),
        "gain_over_continue": (gain_over_continue / denom).cpu().numpy(),
        "gain_restart_over_continue": (gain_restart_over_continue / denom).cpu().numpy(),
    }

def print_probe_summary(probe: Dict, level: int, overwrite_spec: Tuple, zero_k0: bool):
    zk = "zero-k0" if zero_k0 else "normal-k0"
    print(f"\n--- Action probe: level {level} ({level_name(level)}), spec={spec_to_str(overwrite_spec)}, {zk} ---")
    for t in range(T):
        mp = probe["mean_probs"][t]
        br = probe["best_rates"][t]
        g_over = probe["gain_over_continue"][t]
        g_rest = probe["gain_restart_over_continue"][t]
        print(
            f"step {t}: mean p(cont/over/rest)=({mp[0]:.3f}, {mp[1]:.3f}, {mp[2]:.3f}) | "
            f"best rates=({br[0]:.3f}, {br[1]:.3f}, {br[2]:.3f}) | "
            f"Δover-cont={g_over:+.4f} | Δrestart-cont={g_rest:+.4f}"
        )

# ============================================================
# One run for one seed + base strength
# ============================================================
def run_one_seed_and_base_strength(seed: int, base_epochs: int):
    set_seed(seed)
    print("\n\n##############################")
    print(f"Seed = {seed} | base_epochs = {base_epochs}")
    print("##############################")

    base = BaseKnowledgeProvider().to(DEVICE)
    direct = DirectStaticBaseline().to(DEVICE)
    reasoner = MCLTRReasoner(base).to(DEVICE)

    # Stage 1: base knowledge
    train_base(base, base_epochs, BASE_STEPS_PER_EPOCH)

    # Freeze a copy to keep the knowledge provider stable
    frozen_base = copy.deepcopy(base).to(DEVICE)
    set_requires_grad(frozen_base, False)
    direct.base = frozen_base
    reasoner.base = frozen_base

    # Stage 2: direct static baseline
    train_direct_head(frozen_base, direct, epochs=3, steps_per_epoch=DIRECT_STEPS_PER_EPOCH)

    # Stage 3: M-CLTR continue-only reasoning
    train_reasoner_continue_only(frozen_base, reasoner, epochs=4, steps_per_epoch=REASONER_STEPS_PER_EPOCH)

    # Stage 4: evaluator
    train_evaluator(frozen_base, reasoner, epochs=2, steps_per_epoch=EVAL_STEPS_PER_EPOCH)

    # Base accuracy
    base_acc = eval_base_classifier(frozen_base, batches=8, bs=256)

    results = {}
    for level in EVAL_LEVELS:
        results[level] = {}

        direct_acc = eval_direct_baseline(frozen_base, direct, level=level, batches=8, bs=256)
        cont_normal = eval_rollout_mode(
            frozen_base, reasoner, level=level, mode="continue",
            overwrite_spec=OVERWRITE_SPECS[0], zero_k0=False,
            batches=8, bs=256
        )
        cont_zero = eval_rollout_mode(
            frozen_base, reasoner, level=level, mode="continue",
            overwrite_spec=OVERWRITE_SPECS[0], zero_k0=True,
            batches=8, bs=256
        )

        results[level]["base_acc"] = base_acc
        results[level]["direct_acc"] = direct_acc
        results[level]["continue_normal"] = cont_normal["acc"]
        results[level]["continue_zero"] = cont_zero["acc"]

        print(f"\n--- Seed {seed} | base_epochs {base_epochs} | Level {level} ({level_name(level)}) ---")
        print(f"Base classifier (digit ID only)      : {base_acc:.4f}")
        print(f"Direct static baseline              : {direct_acc:.4f}")
        print(f"M-CLTR continue-only (normal k0)    : {cont_normal['acc']:.4f}")
        print(f"M-CLTR continue-only (zero k0)      : {cont_zero['acc']:.4f}")
        print(f"Zero-knowledge gap                  : {cont_normal['acc'] - cont_zero['acc']:+.4f}")

        for spec in OVERWRITE_SPECS:
            overwrite_res = eval_rollout_mode(
                frozen_base, reasoner, level=level, mode="overwrite",
                overwrite_spec=spec, zero_k0=False,
                batches=8, bs=256
            )
            restart_res = eval_rollout_mode(
                frozen_base, reasoner, level=level, mode="restart",
                overwrite_spec=spec, zero_k0=False,
                batches=8, bs=256
            )
            oracle_res = eval_rollout_mode(
                frozen_base, reasoner, level=level, mode="oracle",
                overwrite_spec=spec, zero_k0=False,
                batches=8, bs=256
            )

            probe = probe_actions(
                frozen_base, reasoner, level=level, overwrite_spec=spec, zero_k0=False,
                batches=4, bs=128
            )
            probe_zero = probe_actions(
                frozen_base, reasoner, level=level, overwrite_spec=spec, zero_k0=True,
                batches=4, bs=128
            )

            key = spec_to_str(spec)
            results[level][key] = {
                "overwrite_acc": overwrite_res["acc"],
                "restart_acc": restart_res["acc"],
                "oracle_acc": oracle_res["acc"],
                "oracle_c": oracle_res["continue_rate"],
                "oracle_o": oracle_res["overwrite_rate"],
                "oracle_r": oracle_res["restart_rate"],
                "probe": probe,
                "probe_zero": probe_zero,
            }

            print(f"\n  Overwrite spec = {key}")
            print(f"    Forced overwrite acc          : {overwrite_res['acc']:.4f}")
            print(f"    Forced restart acc            : {restart_res['acc']:.4f}")
            print(f"    Step-wise oracle acc          : {oracle_res['acc']:.4f}")
            print(f"    Oracle action rates C/O/R     : {oracle_res['continue_rate']:.3f}/{oracle_res['overwrite_rate']:.3f}/{oracle_res['restart_rate']:.3f}")
            print_probe_summary(probe, level, spec, zero_k0=False)
            print_probe_summary(probe_zero, level, spec, zero_k0=True)

    return results

# ============================================================
# Run sweep
# ============================================================
all_results = {}
for base_epochs in BASE_EPOCH_SWEEP:
    all_results[base_epochs] = {}
    for seed in SEEDS:
        all_results[base_epochs][seed] = run_one_seed_and_base_strength(seed, base_epochs)

# ============================================================
# Aggregate summary
# ============================================================
print("\n\n==============================")
print("Aggregated summary across seeds and base strengths")
print("==============================")

for base_epochs in BASE_EPOCH_SWEEP:
    print(f"\n################################")
    print(f"Base epochs = {base_epochs}")
    print(f"################################")

    for level in EVAL_LEVELS:
        base_vals = []
        direct_vals = []
        cont_vals = []
        cont_zero_vals = []

        spec_summaries = {
            spec_to_str(spec): {
                "over": [],
                "rest": [],
                "oracle": [],
                "orc": [],
                "oro": [],
                "orr": [],
                "probe_over": [],
                "probe_rest": [],
                "probe_best_over": [],
                "probe_best_rest": [],
                "probe_over_zero": [],
                "probe_rest_zero": [],
            }
            for spec in OVERWRITE_SPECS
        }

        for seed in SEEDS:
            rr = all_results[base_epochs][seed][level]
            base_vals.append(rr["base_acc"])
            direct_vals.append(rr["direct_acc"])
            cont_vals.append(rr["continue_normal"])
            cont_zero_vals.append(rr["continue_zero"])

            for spec in OVERWRITE_SPECS:
                key = spec_to_str(spec)
                r = rr[key]
                spec_summaries[key]["over"].append(r["overwrite_acc"])
                spec_summaries[key]["rest"].append(r["restart_acc"])
                spec_summaries[key]["oracle"].append(r["oracle_acc"])
                spec_summaries[key]["orc"].append(r["oracle_c"])
                spec_summaries[key]["oro"].append(r["oracle_o"])
                spec_summaries[key]["orr"].append(r["oracle_r"])
                spec_summaries[key]["probe_over"].append(float(r["probe"]["gain_over_continue"].mean()))
                spec_summaries[key]["probe_rest"].append(float(r["probe"]["gain_restart_over_continue"].mean()))
                spec_summaries[key]["probe_best_over"].append(float(r["probe"]["best_rates"][:, 1].mean()))
                spec_summaries[key]["probe_best_rest"].append(float(r["probe"]["best_rates"][:, 2].mean()))
                spec_summaries[key]["probe_over_zero"].append(float(r["probe_zero"]["gain_over_continue"].mean()))
                spec_summaries[key]["probe_rest_zero"].append(float(r["probe_zero"]["gain_restart_over_continue"].mean()))

        bm, bs = mean_std(base_vals)
        dm, ds = mean_std(direct_vals)
        cm, cs = mean_std(cont_vals)
        czm, czs = mean_std(cont_zero_vals)

        print(f"\nLevel {level} ({level_name(level)})")
        print(f"  Base classifier              : {bm:.4f} ± {bs:.4f}")
        print(f"  Direct static baseline       : {dm:.4f} ± {ds:.4f}")
        print(f"  Continue-only (normal k0)    : {cm:.4f} ± {cs:.4f}")
        print(f"  Continue-only (zero k0)      : {czm:.4f} ± {czs:.4f}")
        print(f"  Zero-knowledge gap           : {(cm - czm):+.4f}")

        for spec in OVERWRITE_SPECS:
            key = spec_to_str(spec)
            om, os = mean_std(spec_summaries[key]["over"])
            rm, rs = mean_std(spec_summaries[key]["rest"])
            qm, qs = mean_std(spec_summaries[key]["oracle"])
            orc_m, orc_s = mean_std(spec_summaries[key]["orc"])
            oro_m, oro_s = mean_std(spec_summaries[key]["oro"])
            orr_m, orr_s = mean_std(spec_summaries[key]["orr"])
            go_m, go_s = mean_std(spec_summaries[key]["probe_over"])
            gr_m, gr_s = mean_std(spec_summaries[key]["probe_rest"])
            bo_m, bo_s = mean_std(spec_summaries[key]["probe_best_over"])
            br_m, br_s = mean_std(spec_summaries[key]["probe_best_rest"])
            goz_m, goz_s = mean_std(spec_summaries[key]["probe_over_zero"])
            grz_m, grz_s = mean_std(spec_summaries[key]["probe_rest_zero"])

            print(f"\n  Overwrite spec = {key}")
            print(f"    Forced overwrite acc        : {om:.4f} ± {os:.4f}")
            print(f"    Forced restart acc          : {rm:.4f} ± {rs:.4f}")
            print(f"    Step-wise oracle acc        : {qm:.4f} ± {qs:.4f}")
            print(f"    Oracle action rates C/O/R   : {orc_m:.3f} ± {orc_s:.3f} / {oro_m:.3f} ± {oro_s:.3f} / {orr_m:.3f} ± {orr_s:.3f}")
            print(f"    Probe mean Δ(over-cont)     : {go_m:+.4f} ± {go_s:.4f}")
            print(f"    Probe mean Δ(rest-cont)     : {gr_m:+.4f} ± {gr_s:.4f}")
            print(f"    Probe best-action overwrite : {bo_m:.3f} ± {bo_s:.3f}")
            print(f"    Probe best-action restart   : {br_m:.3f} ± {br_s:.3f}")
            print(f"    Zero-k Δ(over-cont)         : {goz_m:+.4f} ± {goz_s:.4f}")
            print(f"    Zero-k Δ(rest-cont)         : {grz_m:+.4f} ± {grz_s:.4f}")

print("\nDone.")

# Phase 3 — overwrite redesign check
# Focus:
#   - compare the two strongest overwrite variants
#   - keep restart as the reference fallback
#   - run only on the harder corrupted levels
#   - keep CPU cost reasonable

import copy
import random
import time
from typing import Dict, Tuple, Optional

import numpy as np
import torch
import torch.nn.functional as F

# ------------------------------------------------------------
# Assumes these already exist from your previous cell:
#   DEVICE, T, K_DIM, Z_DIM, BATCH_SIZE
#   SEEDS, BASE_EPOCH_SWEEP
#   X_train, y_train, X_test, y_test
#   BaseKnowledgeProvider, DirectStaticBaseline, MCLTRReasoner
#   train_base, train_direct_head, train_reasoner_continue_only, train_evaluator
#   eval_base_classifier, eval_direct_baseline
#   make_reasoning_batch, inject_mistake, mean_std, sample_indices
#   set_seed, set_requires_grad, step_feature, task_value
# ------------------------------------------------------------

PHASE3_LEVELS = [3, 4]   # corrupted / recovery-focused levels only
PHASE3_SPECS = [
    ("blend", 0.80),
    ("project", 6.0),
]

BASE_STEPS_PER_EPOCH = 24
DIRECT_STEPS_PER_EPOCH = 24
REASONER_STEPS_PER_EPOCH = 24
EVAL_STEPS_PER_EPOCH = 24

TASK_EVAL_BATCHES = 12
PROBE_BATCHES = 4

def spec_name(spec: Tuple) -> str:
    kind, arg = spec
    if kind == "blend":
        return f"blend({arg:.2f})"
    if kind == "project":
        return f"project(max_shift={arg:.1f})"
    raise ValueError(f"Unknown spec: {spec}")

def normalize_z(z: torch.Tensor) -> torch.Tensor:
    return F.layer_norm(z, (z.size(-1),))

def apply_overwrite_variant(
    cand: torch.Tensor,
    z0: torch.Tensor,
    k0: torch.Tensor,
    ctrl: torch.Tensor,
    t: int,
    spec: Tuple,
    reasoner: MCLTRReasoner,
) -> torch.Tensor:
    kind, arg = spec

    if kind == "blend":
        alpha = float(arg)
        z = alpha * cand + (1.0 - alpha) * z0
        return normalize_z(z)

    if kind == "project":
        max_shift = float(arg)
        delta = cand - z0
        delta_norm = delta.norm(dim=-1, keepdim=True).clamp_min(1e-6)
        scale = torch.clamp(max_shift / delta_norm, max=1.0)
        z = z0 + scale * delta
        return normalize_z(z)

    raise ValueError(f"Unknown overwrite kind: {kind}")

@torch.no_grad()
def continue_rollout_from_state(
    reasoner: MCLTRReasoner,
    z_start: torch.Tensor,
    k0: torch.Tensor,
    ctrl_seq: torch.Tensor,
    start_t: int,
    level: int,
) -> torch.Tensor:
    spec = LEVEL_SPECS[level]
    z = z_start

    for t in range(start_t, T):
        z = reasoner.step_update(z, k0, ctrl_seq[:, t, :], t)
        if spec["corrupt_step"] is not None and t == spec["corrupt_step"]:
            z = inject_mistake(z, spec["corrupt_severity"])
    return z

@torch.no_grad()
def final_target_prob_from_state(
    reasoner: MCLTRReasoner,
    z_start: torch.Tensor,
    k0: torch.Tensor,
    ctrl_seq: torch.Tensor,
    start_t: int,
    target: torch.Tensor,
    level: int,
) -> torch.Tensor:
    z_final = continue_rollout_from_state(reasoner, z_start, k0, ctrl_seq, start_t, level)
    logits = reasoner.decode(z_final)
    probs = F.softmax(logits, dim=-1)
    return probs.gather(1, target.unsqueeze(1)).squeeze(1)

@torch.no_grad()
def choose_oracle_action(
    reasoner: MCLTRReasoner,
    cand: torch.Tensor,
    z0: torch.Tensor,
    k0: torch.Tensor,
    ctrl_seq: torch.Tensor,
    t: int,
    target: torch.Tensor,
    spec: Tuple,
    level: int,
):
    cont_state = cand
    over_state = apply_overwrite_variant(cand, z0, k0, ctrl_seq[:, t, :], t, spec, reasoner)
    rest_state = z0

    p_cont = final_target_prob_from_state(reasoner, cont_state, k0, ctrl_seq, t + 1, target, level)
    p_over = final_target_prob_from_state(reasoner, over_state, k0, ctrl_seq, t + 1, target, level)
    p_rest = final_target_prob_from_state(reasoner, rest_state, k0, ctrl_seq, t + 1, target, level)

    probs = torch.stack([p_cont, p_over, p_rest], dim=-1)  # [B, 3]
    tie_bias = torch.tensor([2e-3, 1e-3, 0.0], device=probs.device).unsqueeze(0)
    action = (probs + tie_bias).argmax(dim=-1)
    best_prob = probs.gather(1, action.unsqueeze(1)).squeeze(1)
    return action, probs, best_prob

@torch.no_grad()
def rollout_reasoner(
    reasoner: MCLTRReasoner,
    k0: torch.Tensor,
    start_ctrl: torch.Tensor,
    ctrl_seq: torch.Tensor,
    target: Optional[torch.Tensor],
    level: int,
    mode: str,
    overwrite_spec: Optional[Tuple] = None,
    zero_k0: bool = False,
):
    if zero_k0:
        k0 = torch.zeros_like(k0)

    z0 = reasoner.init_state(k0, start_ctrl)
    z = z0
    actions = []
    step_probs = []

    for t in range(T):
        cand = reasoner.step_update(z, k0, ctrl_seq[:, t, :], t)

        # Inject latent corruption on the difficult levels
        spec = LEVEL_SPECS[level]
        if spec["corrupt_step"] is not None and t == spec["corrupt_step"]:
            cand = inject_mistake(cand, spec["corrupt_severity"])

        if mode == "continue":
            action = torch.zeros(k0.size(0), dtype=torch.long, device=k0.device)
            z_next = cand

        elif mode == "overwrite":
            if overwrite_spec is None:
                raise ValueError("overwrite_spec required for overwrite mode")
            action = torch.ones(k0.size(0), dtype=torch.long, device=k0.device)
            z_next = apply_overwrite_variant(cand, z0, k0, ctrl_seq[:, t, :], t, overwrite_spec, reasoner)

        elif mode == "restart":
            action = torch.full((k0.size(0),), 2, dtype=torch.long, device=k0.device)
            z_next = z0

        elif mode == "oracle":
            if overwrite_spec is None:
                raise ValueError("overwrite_spec required for oracle mode")
            if target is None:
                raise ValueError("oracle mode requires target")
            action, probs, _ = choose_oracle_action(reasoner, cand, z0, k0, ctrl_seq, t, target, overwrite_spec, level)

            z_next = torch.empty_like(cand)
            cont_mask = action == 0
            over_mask = action == 1
            rest_mask = action == 2

            if cont_mask.any():
                z_next[cont_mask] = cand[cont_mask]
            if over_mask.any():
                z_next[over_mask] = apply_overwrite_variant(
                    cand[over_mask], z0[over_mask], k0[over_mask], ctrl_seq[over_mask, t, :], t, overwrite_spec, reasoner
                )
            if rest_mask.any():
                z_next[rest_mask] = z0[rest_mask]

            step_probs.append(probs)

        else:
            raise ValueError(f"Unknown mode: {mode}")

        actions.append(action)
        z = z_next

    logits = reasoner.decode(z)
    pred = logits.argmax(dim=-1)
    final_ctrl = ctrl_seq[:, -1, :]
    final_eval = reasoner.eval_score(z, k0, final_ctrl, T - 1)

    out = {
        "logits": logits,
        "pred": pred,
        "actions": torch.stack(actions, dim=1),
        "final_eval": final_eval,
        "z0": z0,
    }
    if mode == "oracle":
        out["step_probs"] = torch.stack(step_probs, dim=1)
    return out

@torch.no_grad()
def eval_rollout_mode(
    base: BaseKnowledgeProvider,
    reasoner: MCLTRReasoner,
    level: int,
    mode: str,
    overwrite_spec: Tuple,
    zero_k0: bool,
    batches: int = TASK_EVAL_BATCHES,
    bs: int = 256,
):
    base.eval()
    reasoner.eval()

    total = 0
    correct = 0
    action_counts = torch.zeros(3, device=DEVICE)

    score_correct = []
    score_incorrect = []

    for _ in range(batches):
        x, digit_labels, start_mode, end_mode, start_ctrl, ctrl_seq, target = make_reasoning_batch(
            X_test, y_test, bs, level=level
        )
        k0 = base.encode(x)

        out = rollout_reasoner(
            reasoner,
            k0,
            start_ctrl,
            ctrl_seq,
            target=target if mode == "oracle" else None,
            level=level,
            mode=mode,
            overwrite_spec=overwrite_spec,
            zero_k0=zero_k0,
        )

        pred = out["pred"]
        correct_mask = pred == target
        correct += correct_mask.sum().item()
        total += target.numel()

        if mode == "oracle":
            action_counts += torch.stack([
                (out["actions"] == 0).sum(),
                (out["actions"] == 1).sum(),
                (out["actions"] == 2).sum(),
            ]).float()

        score = out["final_eval"]
        if correct_mask.any():
            score_correct.append(score[correct_mask].mean().item())
        if (~correct_mask).any():
            score_incorrect.append(score[~correct_mask].mean().item())

    result = {
        "acc": correct / total,
        "score_correct_mean": float(np.mean(score_correct)) if len(score_correct) else float("nan"),
        "score_incorrect_mean": float(np.mean(score_incorrect)) if len(score_incorrect) else float("nan"),
    }

    if mode == "oracle":
        rates = (action_counts / (batches * bs * T)).detach().cpu().numpy()
        result["continue_rate"] = float(rates[0])
        result["overwrite_rate"] = float(rates[1])
        result["restart_rate"] = float(rates[2])

    return result

@torch.no_grad()
def probe_actions(
    base: BaseKnowledgeProvider,
    reasoner: MCLTRReasoner,
    level: int,
    overwrite_spec: Tuple,
    zero_k0: bool,
    batches: int = PROBE_BATCHES,
    bs: int = 128,
):
    base.eval()
    reasoner.eval()

    best_counts = torch.zeros(T, 3, device=DEVICE)
    mean_probs = torch.zeros(T, 3, device=DEVICE)
    gain_over_continue = torch.zeros(T, device=DEVICE)
    gain_restart_over_continue = torch.zeros(T, device=DEVICE)

    for _ in range(batches):
        x, digit_labels, start_mode, end_mode, start_ctrl, ctrl_seq, target = make_reasoning_batch(
            X_test, y_test, bs, level=level
        )
        k0 = base.encode(x)
        if zero_k0:
            k0 = torch.zeros_like(k0)

        z0 = reasoner.init_state(k0, start_ctrl)
        z = z0

        for t in range(T):
            cand = reasoner.step_update(z, k0, ctrl_seq[:, t, :], t)

            spec = LEVEL_SPECS[level]
            if spec["corrupt_step"] is not None and t == spec["corrupt_step"]:
                cand = inject_mistake(cand, spec["corrupt_severity"])

            cont_state = cand
            over_state = apply_overwrite_variant(cand, z0, k0, ctrl_seq[:, t, :], t, overwrite_spec, reasoner)
            rest_state = z0

            p_cont = final_target_prob_from_state(reasoner, cont_state, k0, ctrl_seq, t + 1, target, level)
            p_over = final_target_prob_from_state(reasoner, over_state, k0, ctrl_seq, t + 1, target, level)
            p_rest = final_target_prob_from_state(reasoner, rest_state, k0, ctrl_seq, t + 1, target, level)

            probs = torch.stack([p_cont, p_over, p_rest], dim=-1)
            best = probs.argmax(dim=-1)

            for a in range(3):
                best_counts[t, a] += (best == a).sum()

            mean_probs[t, 0] += p_cont.sum()
            mean_probs[t, 1] += p_over.sum()
            mean_probs[t, 2] += p_rest.sum()

            gain_over_continue[t] += (p_over - p_cont).sum()
            gain_restart_over_continue[t] += (p_rest - p_cont).sum()

            z = cand

    denom = batches * bs
    return {
        "mean_probs": (mean_probs / denom).cpu().numpy(),
        "best_rates": (best_counts / denom).cpu().numpy(),
        "gain_over_continue": (gain_over_continue / denom).cpu().numpy(),
        "gain_restart_over_continue": (gain_restart_over_continue / denom).cpu().numpy(),
    }

def print_probe_summary(probe: Dict, level: int, overwrite_spec: Tuple, zero_k0: bool):
    zk = "zero-k0" if zero_k0 else "normal-k0"
    print(f"\n--- Action probe: level {level} ({LEVEL_SPECS[level]['name']}), spec={spec_name(overwrite_spec)}, {zk} ---")
    for t in range(T):
        mp = probe["mean_probs"][t]
        br = probe["best_rates"][t]
        g_over = probe["gain_over_continue"][t]
        g_rest = probe["gain_restart_over_continue"][t]
        print(
            f"step {t}: mean p(cont/over/rest)=({mp[0]:.3f}, {mp[1]:.3f}, {mp[2]:.3f}) | "
            f"best rates=({br[0]:.3f}, {br[1]:.3f}, {br[2]:.3f}) | "
            f"Δover-cont={g_over:+.4f} | Δrestart-cont={g_rest:+.4f}"
        )

def run_phase3(seed: int, base_epochs: int):
    set_seed(seed)
    print("\n\n##############################")
    print(f"Seed = {seed} | base_epochs = {base_epochs}")
    print("##############################")

    base = BaseKnowledgeProvider().to(DEVICE)
    direct = DirectStaticBaseline().to(DEVICE)
    reasoner = MCLTRReasoner(base).to(DEVICE)

    train_base(base, base_epochs, BASE_STEPS_PER_EPOCH)

    frozen_base = copy.deepcopy(base).to(DEVICE)
    for p in frozen_base.parameters():
        p.requires_grad = False
    direct.base = frozen_base
    reasoner.base = frozen_base

    train_direct_head(frozen_base, direct, epochs=3, steps_per_epoch=DIRECT_STEPS_PER_EPOCH)
    train_reasoner_continue_only(frozen_base, reasoner, epochs=4, steps_per_epoch=REASONER_STEPS_PER_EPOCH)
    train_evaluator(frozen_base, reasoner, epochs=2, steps_per_epoch=EVAL_STEPS_PER_EPOCH)

    base_acc = eval_base_classifier(frozen_base, batches=12, bs=256)

    results = {}
    for level in PHASE3_LEVELS:
        results[level] = {}

        direct_acc = eval_direct_baseline(frozen_base, direct, level=level, batches=12, bs=256)
        cont_normal = eval_rollout_mode(
            frozen_base, reasoner, level=level, mode="continue",
            overwrite_spec=PHASE3_SPECS[0], zero_k0=False,
            batches=12, bs=256
        )
        cont_zero = eval_rollout_mode(
            frozen_base, reasoner, level=level, mode="continue",
            overwrite_spec=PHASE3_SPECS[0], zero_k0=True,
            batches=12, bs=256
        )

        results[level]["base_acc"] = base_acc
        results[level]["direct_acc"] = direct_acc
        results[level]["continue_normal"] = cont_normal["acc"]
        results[level]["continue_zero"] = cont_zero["acc"]

        print(f"\n--- Seed {seed} | base_epochs {base_epochs} | Level {level} ({LEVEL_SPECS[level]['name']}) ---")
        print(f"Base classifier              : {base_acc:.4f}")
        print(f"Direct static baseline       : {direct_acc:.4f}")
        print(f"Continue-only (normal k0)    : {cont_normal['acc']:.4f}")
        print(f"Continue-only (zero k0)      : {cont_zero['acc']:.4f}")
        print(f"Zero-knowledge gap           : {cont_normal['acc'] - cont_zero['acc']:+.4f}")

        for spec in PHASE3_SPECS:
            overwrite_res = eval_rollout_mode(
                frozen_base, reasoner, level=level, mode="overwrite",
                overwrite_spec=spec, zero_k0=False,
                batches=12, bs=256
            )
            restart_res = eval_rollout_mode(
                frozen_base, reasoner, level=level, mode="restart",
                overwrite_spec=spec, zero_k0=False,
                batches=12, bs=256
            )
            oracle_res = eval_rollout_mode(
                frozen_base, reasoner, level=level, mode="oracle",
                overwrite_spec=spec, zero_k0=False,
                batches=12, bs=256
            )

            probe = probe_actions(
                frozen_base, reasoner, level=level, overwrite_spec=spec, zero_k0=False,
                batches=PROBE_BATCHES, bs=128
            )
            probe_zero = probe_actions(
                frozen_base, reasoner, level=level, overwrite_spec=spec, zero_k0=True,
                batches=PROBE_BATCHES, bs=128
            )

            key = spec_name(spec)
            results[level][key] = {
                "overwrite_acc": overwrite_res["acc"],
                "restart_acc": restart_res["acc"],
                "oracle_acc": oracle_res["acc"],
                "oracle_c": oracle_res["continue_rate"],
                "oracle_o": oracle_res["overwrite_rate"],
                "oracle_r": oracle_res["restart_rate"],
                "probe": probe,
                "probe_zero": probe_zero,
            }

            print(f"\n  Overwrite spec = {key}")
            print(f"    Forced overwrite acc      : {overwrite_res['acc']:.4f}")
            print(f"    Forced restart acc        : {restart_res['acc']:.4f}")
            print(f"    Step-wise oracle acc      : {oracle_res['acc']:.4f}")
            print(f"    Oracle action rates C/O/R : {oracle_res['continue_rate']:.3f}/{oracle_res['overwrite_rate']:.3f}/{oracle_res['restart_rate']:.3f}")
            print_probe_summary(probe, level, spec, zero_k0=False)
            print_probe_summary(probe_zero, level, spec, zero_k0=True)

    return results

# ------------------------------------------------------------
# Run the phase 3 sweep
# ------------------------------------------------------------
all_results = {}
for base_epochs in BASE_EPOCH_SWEEP:
    all_results[base_epochs] = {}
    for seed in SEEDS:
        all_results[base_epochs][seed] = run_phase3(seed, base_epochs)

# ------------------------------------------------------------
# Aggregate summary
# ------------------------------------------------------------
print("\n\n==============================")
print("Phase 3 aggregate summary")
print("==============================")

for base_epochs in BASE_EPOCH_SWEEP:
    print(f"\n################################")
    print(f"Base epochs = {base_epochs}")
    print(f"################################")

    for level in PHASE3_LEVELS:
        base_vals = []
        direct_vals = []
        cont_vals = []
        cont_zero_vals = []

        spec_summaries = {
            spec_name(spec): {
                "over": [],
                "rest": [],
                "oracle": [],
                "orc": [],
                "oro": [],
                "orr": [],
                "probe_over": [],
                "probe_rest": [],
                "probe_best_over": [],
                "probe_best_rest": [],
                "probe_over_zero": [],
                "probe_rest_zero": [],
            }
            for spec in PHASE3_SPECS
        }

        for seed in SEEDS:
            rr = all_results[base_epochs][seed][level]
            base_vals.append(rr["base_acc"])
            direct_vals.append(rr["direct_acc"])
            cont_vals.append(rr["continue_normal"])
            cont_zero_vals.append(rr["continue_zero"])

            for spec in PHASE3_SPECS:
                key = spec_name(spec)
                r = rr[key]
                spec_summaries[key]["over"].append(r["overwrite_acc"])
                spec_summaries[key]["rest"].append(r["restart_acc"])
                spec_summaries[key]["oracle"].append(r["oracle_acc"])
                spec_summaries[key]["orc"].append(r["oracle_c"])
                spec_summaries[key]["oro"].append(r["oracle_o"])
                spec_summaries[key]["orr"].append(r["oracle_r"])
                spec_summaries[key]["probe_over"].append(float(r["probe"]["gain_over_continue"].mean()))
                spec_summaries[key]["probe_rest"].append(float(r["probe"]["gain_restart_over_continue"].mean()))
                spec_summaries[key]["probe_best_over"].append(float(r["probe"]["best_rates"][:, 1].mean()))
                spec_summaries[key]["probe_best_rest"].append(float(r["probe"]["best_rates"][:, 2].mean()))
                spec_summaries[key]["probe_over_zero"].append(float(r["probe_zero"]["gain_over_continue"].mean()))
                spec_summaries[key]["probe_rest_zero"].append(float(r["probe_zero"]["gain_restart_over_continue"].mean()))

        bm, bs = mean_std(base_vals)
        dm, ds = mean_std(direct_vals)
        cm, cs = mean_std(cont_vals)
        czm, czs = mean_std(cont_zero_vals)

        print(f"\nLevel {level} ({LEVEL_SPECS[level]['name']})")
        print(f"  Base classifier              : {bm:.4f} ± {bs:.4f}")
        print(f"  Direct static baseline       : {dm:.4f} ± {ds:.4f}")
        print(f"  Continue-only (normal k0)    : {cm:.4f} ± {cs:.4f}")
        print(f"  Continue-only (zero k0)      : {czm:.4f} ± {czs:.4f}")
        print(f"  Zero-knowledge gap           : {(cm - czm):+.4f}")

        for spec in PHASE3_SPECS:
            key = spec_name(spec)
            om, os = mean_std(spec_summaries[key]["over"])
            rm, rs = mean_std(spec_summaries[key]["rest"])
            qm, qs = mean_std(spec_summaries[key]["oracle"])
            orc_m, orc_s = mean_std(spec_summaries[key]["orc"])
            oro_m, oro_s = mean_std(spec_summaries[key]["oro"])
            orr_m, orr_s = mean_std(spec_summaries[key]["orr"])
            go_m, go_s = mean_std(spec_summaries[key]["probe_over"])
            gr_m, gr_s = mean_std(spec_summaries[key]["probe_rest"])
            bo_m, bo_s = mean_std(spec_summaries[key]["probe_best_over"])
            br_m, br_s = mean_std(spec_summaries[key]["probe_best_rest"])
            goz_m, goz_s = mean_std(spec_summaries[key]["probe_over_zero"])
            grz_m, grz_s = mean_std(spec_summaries[key]["probe_rest_zero"])

            print(f"\n  Overwrite spec = {key}")
            print(f"    Forced overwrite acc        : {om:.4f} ± {os:.4f}")
            print(f"    Forced restart acc          : {rm:.4f} ± {rs:.4f}")
            print(f"    Step-wise oracle acc        : {qm:.4f} ± {qs:.4f}")
            print(f"    Oracle action rates C/O/R   : {orc_m:.3f} ± {orc_s:.3f} / {oro_m:.3f} ± {oro_s:.3f} / {orr_m:.3f} ± {orr_s:.3f}")
            print(f"    Probe mean Δ(over-cont)     : {go_m:+.4f} ± {go_s:.4f}")
            print(f"    Probe mean Δ(rest-cont)     : {gr_m:+.4f} ± {gr_s:.4f}")
            print(f"    Probe best-action overwrite : {bo_m:.3f} ± {bo_s:.3f}")
            print(f"    Probe best-action restart   : {br_m:.3f} ± {br_s:.3f}")
            print(f"    Zero-k Δ(over-cont)         : {goz_m:+.4f} ± {goz_s:.4f}")
            print(f"    Zero-k Δ(rest-cont)         : {grz_m:+.4f} ± {grz_s:.4f}")

print("\nDone.")

# M-CLTR Phase 4 — overwrite stress test on corrupted levels only
# Compares:
#   - continue
#   - restart
#   - project(max_shift=6.0)
#   - project(max_shift=10.0)   <-- stronger overwrite
# plus an oracle for reference
#
# Assumes the previous setup code is already available in the notebook.

import copy
import math
import random
import time
from typing import Dict, Optional, Tuple

import numpy as np
import torch
import torch.nn as nn
import torch.nn.functional as F
from sklearn.datasets import load_digits
from sklearn.model_selection import train_test_split

# -----------------------------
# Device / reproducibility
# -----------------------------
DEVICE = torch.device("cuda" if torch.cuda.is_available() else "cpu")
print("Device:", DEVICE)

def set_seed(seed: int):
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    if torch.cuda.is_available():
        torch.cuda.manual_seed_all(seed)

# -----------------------------
# Config
# -----------------------------
T = 6
X_DIM = 64
K_DIM = 64
Z_DIM = 96
TASK_CLASSES = 2
DIGIT_CLASSES = 10

SEEDS = [7, 17]
BASE_EPOCH_SWEEP = [1, 4]

BATCH_SIZE = 128
BASE_STEPS_PER_EPOCH = 24
DIRECT_STEPS_PER_EPOCH = 24
REASONER_STEPS_PER_EPOCH = 24
EVAL_STEPS_PER_EPOCH = 24

LR_BASE = 2e-3
LR_DIRECT = 2e-3
LR_REASONER = 2e-3
LR_EVAL = 2e-3

TRAIN_LEVELS = [0, 1, 2]
EVAL_LEVELS = [3, 4]  # only corrupted levels for this phase

LEVEL_SPECS = {
    0: {"name": "easy / no switch",        "switch_step": T,      "input_noise": 0.00, "corrupt_step": None, "corrupt_severity": 0.00},
    1: {"name": "medium / mid switch",     "switch_step": T // 2, "input_noise": 0.00, "corrupt_step": None, "corrupt_severity": 0.00},
    2: {"name": "hard / early switch",     "switch_step": 1,      "input_noise": 0.00, "corrupt_step": None, "corrupt_severity": 0.00},
    3: {"name": "switch + latent mistake", "switch_step": T // 2, "input_noise": 0.00, "corrupt_step": 2,    "corrupt_severity": 0.35},
    4: {"name": "switch + noise + mistake","switch_step": 1,      "input_noise": 0.15, "corrupt_step": 1,    "corrupt_severity": 0.45},
}

OVERWRITE_SPECS = [
    ("project", 6.0),
    ("project", 10.0),  # stronger / more aggressive projection
]

# -----------------------------
# Data
# -----------------------------
digits = load_digits()
X_all = torch.tensor(digits.data, dtype=torch.float32) / 16.0
y_all = torch.tensor(digits.target, dtype=torch.long)

X_train_np, X_test_np, y_train_np, y_test_np = train_test_split(
    X_all.numpy(),
    y_all.numpy(),
    test_size=0.30,
    random_state=0,
    stratify=y_all.numpy(),
)

X_train = torch.tensor(X_train_np, dtype=torch.float32, device=DEVICE)
y_train = torch.tensor(y_train_np, dtype=torch.long, device=DEVICE)
X_test = torch.tensor(X_test_np, dtype=torch.float32, device=DEVICE)
y_test = torch.tensor(y_test_np, dtype=torch.long, device=DEVICE)

# -----------------------------
# Helpers
# -----------------------------
def one_hot(v: torch.Tensor, n: int) -> torch.Tensor:
    return F.one_hot(v.long(), n).float()

def step_feature(t: int, batch_size: int, device: torch.device) -> torch.Tensor:
    s = 0.0 if T <= 1 else float(t) / float(T - 1)
    return torch.full((batch_size, 1), s, device=device)

def mean_std(values):
    arr = np.asarray(values, dtype=np.float64)
    if arr.size == 1:
        return float(arr.item()), 0.0
    return float(arr.mean()), float(arr.std(ddof=1))

def sample_indices(n: int, batch_size: int) -> torch.Tensor:
    return torch.randint(0, n, (batch_size,), device=DEVICE)

def task_value(digit_labels: torch.Tensor, mode: torch.Tensor) -> torch.Tensor:
    parity = (digit_labels % 2).long()
    highlow = (digit_labels >= 5).long()
    return torch.where(mode == 0, parity, highlow)

def get_level_spec(level: int) -> Dict:
    return LEVEL_SPECS[level]

def level_name(level: int) -> str:
    return LEVEL_SPECS[level]["name"]

def spec_to_str(spec: Tuple):
    kind, arg = spec
    return f"{kind}(max_shift={arg:.1f})"

def inject_mistake(z: torch.Tensor, severity: float) -> torch.Tensor:
    if severity <= 0:
        return z
    rolled = torch.roll(z, shifts=1, dims=-1)
    mixed = (1.0 - severity) * z + severity * rolled
    mixed = mixed + (0.50 * severity) * torch.randn_like(z)
    return mixed

def set_requires_grad(module: nn.Module, flag: bool):
    for p in module.parameters():
        p.requires_grad = flag

# -----------------------------
# Batch generation
# -----------------------------
def make_reasoning_batch(
    x_pool: torch.Tensor,
    y_pool: torch.Tensor,
    batch_size: int,
    level: int,
):
    spec = get_level_spec(level)
    idx = sample_indices(x_pool.size(0), batch_size)
    x = x_pool[idx].clone()

    if spec["input_noise"] > 0:
        x = torch.clamp(x + spec["input_noise"] * torch.randn_like(x), 0.0, 1.0)

    digit_labels = y_pool[idx]
    start_mode = torch.randint(0, 2, (batch_size,), device=DEVICE)

    switch_step = spec["switch_step"]
    end_mode = start_mode.clone() if switch_step >= T else (1 - start_mode)

    start_ctrl = one_hot(start_mode, 2)
    t_ids = torch.arange(T, device=DEVICE).unsqueeze(0).expand(batch_size, T)
    curr_modes = torch.where(t_ids < switch_step, start_mode.unsqueeze(1), end_mode.unsqueeze(1))
    ctrl_seq = one_hot(curr_modes, 2)

    final_mode = curr_modes[:, -1]
    target = task_value(digit_labels, final_mode)

    return x, digit_labels, start_mode, end_mode, start_ctrl, ctrl_seq, target

# -----------------------------
# Models
# -----------------------------
class MLP(nn.Module):
    def __init__(self, in_dim: int, out_dim: int, hidden: int = 128):
        super().__init__()
        self.net = nn.Sequential(
            nn.Linear(in_dim, hidden),
            nn.GELU(),
            nn.Linear(hidden, hidden),
            nn.GELU(),
            nn.Linear(hidden, out_dim),
        )

    def forward(self, x):
        return self.net(x)

class BaseKnowledgeProvider(nn.Module):
    def __init__(self, x_dim: int = X_DIM, k_dim: int = K_DIM):
        super().__init__()
        self.encoder = nn.Sequential(
            nn.Linear(x_dim, 128),
            nn.GELU(),
            nn.Linear(128, k_dim),
            nn.LayerNorm(k_dim),
        )
        self.classifier = nn.Sequential(
            nn.Linear(k_dim, 64),
            nn.GELU(),
            nn.Linear(64, DIGIT_CLASSES),
        )
        for m in self.modules():
            if isinstance(m, nn.Linear):
                nn.init.xavier_uniform_(m.weight)
                if m.bias is not None:
                    nn.init.zeros_(m.bias)

    def encode(self, x: torch.Tensor) -> torch.Tensor:
        return self.encoder(x)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        k0 = self.encode(x)
        return self.classifier(k0)

class DirectStaticBaseline(nn.Module):
    def __init__(self, k_dim: int = K_DIM):
        super().__init__()
        self.head = MLP(k_dim + 2, TASK_CLASSES, hidden=96)
        for m in self.modules():
            if isinstance(m, nn.Linear):
                nn.init.xavier_uniform_(m.weight)
                if m.bias is not None:
                    nn.init.zeros_(m.bias)

    def forward(self, k0: torch.Tensor, start_ctrl: torch.Tensor) -> torch.Tensor:
        return self.head(torch.cat([k0, start_ctrl], dim=-1))

class MCLTRReasoner(nn.Module):
    def __init__(self, base: BaseKnowledgeProvider, k_dim: int = K_DIM, z_dim: int = Z_DIM):
        super().__init__()
        self.base = base
        self.k_dim = k_dim
        self.z_dim = z_dim

        self.init_net = MLP(k_dim + 2, z_dim, hidden=128)
        self.trans_net = MLP(z_dim + k_dim + 2 + 1, z_dim, hidden=128)
        self.context_net = MLP(k_dim + 2 + 1, z_dim, hidden=128)
        self.evaluator = MLP(z_dim + k_dim + 2 + 1, 1, hidden=96)
        self.decoder = nn.Linear(z_dim, TASK_CLASSES)

        self.z_norm = nn.LayerNorm(z_dim)
        self.ctx_norm = nn.LayerNorm(z_dim)

        for m in self.modules():
            if isinstance(m, nn.Linear):
                nn.init.xavier_uniform_(m.weight)
                if m.bias is not None:
                    nn.init.zeros_(m.bias)

    def init_state(self, k0: torch.Tensor, start_ctrl: torch.Tensor) -> torch.Tensor:
        z0 = self.init_net(torch.cat([k0, start_ctrl], dim=-1))
        return self.z_norm(z0)

    def context_state(self, k0: torch.Tensor, ctrl: torch.Tensor, t: int) -> torch.Tensor:
        step = step_feature(t, k0.size(0), k0.device)
        ctx = self.context_net(torch.cat([k0, ctrl, step], dim=-1))
        return self.ctx_norm(ctx)

    def step_update(self, z: torch.Tensor, k0: torch.Tensor, ctrl: torch.Tensor, t: int) -> torch.Tensor:
        step = step_feature(t, z.size(0), z.device)
        inp = torch.cat([z, k0, ctrl, step], dim=-1)
        delta = torch.tanh(self.trans_net(inp))
        cand = self.z_norm(0.80 * z + 0.20 * delta)
        return cand

    def eval_score(self, z: torch.Tensor, k0: torch.Tensor, ctrl: torch.Tensor, t: int) -> torch.Tensor:
        step = step_feature(t, z.size(0), z.device)
        inp = torch.cat([z, k0, ctrl, step], dim=-1)
        return torch.sigmoid(self.evaluator(inp)).squeeze(-1)

    def decode(self, z: torch.Tensor) -> torch.Tensor:
        return self.decoder(z)

# -----------------------------
# Phase-4 overwrite operators
# -----------------------------
def project_overwrite(
    cand: torch.Tensor,
    z0: torch.Tensor,
    max_shift: float,
) -> torch.Tensor:
    """
    Project the candidate toward the restart anchor z0, but cap the step size.
    This is stronger and more explicit than a soft blend.
    """
    delta = cand - z0
    delta_norm = delta.norm(dim=-1, keepdim=True).clamp_min(1e-6)
    scale = torch.clamp(torch.full_like(delta_norm, max_shift) / delta_norm, max=1.0)
    z_new = z0 + delta * scale
    return z_new

def apply_overwrite(
    reasoner: MCLTRReasoner,
    cand: torch.Tensor,
    z0: torch.Tensor,
    k0: torch.Tensor,
    ctrl: torch.Tensor,
    t: int,
    spec: Tuple,
) -> torch.Tensor:
    kind, arg = spec
    if kind == "project":
        return reasoner.z_norm(project_overwrite(cand, z0, float(arg)))
    raise ValueError(f"Unknown overwrite spec: {spec}")

# -----------------------------
# Rollout helpers
# -----------------------------
@torch.no_grad()
def continue_rollout_from_state(
    reasoner: MCLTRReasoner,
    z_start: torch.Tensor,
    k0: torch.Tensor,
    ctrl_seq: torch.Tensor,
    start_t: int,
    level: int,
) -> torch.Tensor:
    spec = get_level_spec(level)
    z = z_start
    for t in range(start_t, T):
        z = reasoner.step_update(z, k0, ctrl_seq[:, t, :], t)
        if spec["corrupt_step"] is not None and t == spec["corrupt_step"]:
            z = inject_mistake(z, spec["corrupt_severity"])
    return z

@torch.no_grad()
def final_target_prob_from_state(
    reasoner: MCLTRReasoner,
    z_start: torch.Tensor,
    k0: torch.Tensor,
    ctrl_seq: torch.Tensor,
    start_t: int,
    target: torch.Tensor,
    level: int,
) -> torch.Tensor:
    z_final = continue_rollout_from_state(reasoner, z_start, k0, ctrl_seq, start_t, level)
    logits = reasoner.decode(z_final)
    probs = F.softmax(logits, dim=-1)
    return probs.gather(1, target.unsqueeze(1)).squeeze(1)

@torch.no_grad()
def choose_oracle_action(
    reasoner: MCLTRReasoner,
    cand: torch.Tensor,
    z0: torch.Tensor,
    k0: torch.Tensor,
    ctrl_seq: torch.Tensor,
    t: int,
    target: torch.Tensor,
    overwrite_spec: Tuple,
    level: int,
):
    cont_state = cand
    over_state = apply_overwrite(reasoner, cand, z0, k0, ctrl_seq[:, t, :], t, overwrite_spec)
    rest_state = z0

    p_cont = final_target_prob_from_state(reasoner, cont_state, k0, ctrl_seq, t + 1, target, level)
    p_over = final_target_prob_from_state(reasoner, over_state, k0, ctrl_seq, t + 1, target, level)
    p_rest = final_target_prob_from_state(reasoner, rest_state, k0, ctrl_seq, t + 1, target, level)

    probs = torch.stack([p_cont, p_over, p_rest], dim=-1)
    tie_bias = torch.tensor([2e-3, 1e-3, 0.0], device=probs.device).unsqueeze(0)
    action = (probs + tie_bias).argmax(dim=-1)
    best_prob = probs.gather(1, action.unsqueeze(1)).squeeze(1)
    return action, probs, best_prob

# -----------------------------
# Training
# -----------------------------
def train_base(base: BaseKnowledgeProvider, epochs: int, steps_per_epoch: int):
    base.train()
    opt = torch.optim.AdamW(base.parameters(), lr=LR_BASE, weight_decay=1e-4)
    ce = nn.CrossEntropyLoss()

    print("\n=== Stage 1: base knowledge pretraining (digit classification) ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_acc = 0.0

        for _ in range(steps_per_epoch):
            idx = sample_indices(X_train.size(0), BATCH_SIZE)
            xb = X_train[idx]
            yb = y_train[idx]

            logits = base(xb)
            loss = ce(logits, yb)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(base.parameters(), 1.0)
            opt.step()

            total_loss += loss.item()
            total_acc += (logits.argmax(dim=-1) == yb).float().mean().item()

        print(f"Base epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} | acc {total_acc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s")

def train_direct_head(base: BaseKnowledgeProvider, direct: DirectStaticBaseline, epochs: int, steps_per_epoch: int):
    direct.train()
    set_requires_grad(base, False)
    opt = torch.optim.AdamW(direct.parameters(), lr=LR_DIRECT, weight_decay=1e-4)
    ce = nn.CrossEntropyLoss()

    print("\n=== Stage 2: direct static baseline head (no online control) ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_acc = 0.0

        for _ in range(steps_per_epoch):
            level = random.choice(TRAIN_LEVELS)
            x, _, start_mode, _, start_ctrl, _, target = make_reasoning_batch(X_train, y_train, BATCH_SIZE, level=level)

            with torch.no_grad():
                k0 = base.encode(x)

            logits = direct(k0, start_ctrl)
            loss = ce(logits, target)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(direct.parameters(), 1.0)
            opt.step()

            total_loss += loss.item()
            total_acc += (logits.argmax(dim=-1) == target).float().mean().item()

        print(f"Direct epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} | acc {total_acc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s")

def train_reasoner_continue_only(base: BaseKnowledgeProvider, reasoner: MCLTRReasoner, epochs: int, steps_per_epoch: int):
    reasoner.train()
    set_requires_grad(base, False)
    set_requires_grad(reasoner.init_net, True)
    set_requires_grad(reasoner.trans_net, True)
    set_requires_grad(reasoner.context_net, False)
    set_requires_grad(reasoner.evaluator, False)
    set_requires_grad(reasoner.decoder, True)
    set_requires_grad(reasoner.z_norm, True)
    set_requires_grad(reasoner.ctx_norm, False)

    params = list(reasoner.init_net.parameters()) + list(reasoner.trans_net.parameters()) + list(reasoner.decoder.parameters()) + list(reasoner.z_norm.parameters())
    opt = torch.optim.AdamW(params, lr=LR_REASONER, weight_decay=1e-4)
    ce = nn.CrossEntropyLoss()

    print("\n=== Stage 3: reasoner pretraining (continue-only rollouts, mixed levels) ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_acc = 0.0

        for _ in range(steps_per_epoch):
            level = random.choice(TRAIN_LEVELS)
            x, _, start_mode, _, start_ctrl, ctrl_seq, target = make_reasoning_batch(X_train, y_train, BATCH_SIZE, level=level)

            with torch.no_grad():
                k0 = base.encode(x)

            z = reasoner.init_state(k0, start_ctrl)
            for t in range(T):
                z = reasoner.step_update(z, k0, ctrl_seq[:, t, :], t)

            logits = reasoner.decode(z)
            loss = ce(logits, target)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(params, 1.0)
            opt.step()

            total_loss += loss.item()
            total_acc += (logits.argmax(dim=-1) == target).float().mean().item()

        print(f"Reasoner epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} | acc {total_acc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s")

def train_evaluator(base: BaseKnowledgeProvider, reasoner: MCLTRReasoner, epochs: int, steps_per_epoch: int):
    reasoner.eval()
    set_requires_grad(base, False)
    set_requires_grad(reasoner.init_net, False)
    set_requires_grad(reasoner.trans_net, False)
    set_requires_grad(reasoner.context_net, False)
    set_requires_grad(reasoner.decoder, False)
    set_requires_grad(reasoner.z_norm, False)
    set_requires_grad(reasoner.ctx_norm, False)
    set_requires_grad(reasoner.evaluator, True)

    opt = torch.optim.AdamW(reasoner.evaluator.parameters(), lr=LR_EVAL, weight_decay=1e-4)
    mse = nn.MSELoss()

    print("\n=== Stage 4: evaluator training (predict final correctness probability) ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_binacc = 0.0

        for _ in range(steps_per_epoch):
            level = random.choice([0, 1, 2, 3, 4])
            x, _, start_mode, _, start_ctrl, ctrl_seq, target = make_reasoning_batch(X_train, y_train, BATCH_SIZE, level=level)

            with torch.no_grad():
                k0 = base.encode(x)
                z = reasoner.init_state(k0, start_ctrl)

                step_z, step_k0, step_ctrl, step_t, labels = [], [], [], [], []

                for t in range(T):
                    cand = reasoner.step_update(z, k0, ctrl_seq[:, t, :], t)
                    p_target = final_target_prob_from_state(reasoner, cand, k0, ctrl_seq, t + 1, target, level)

                    step_z.append(cand.detach())
                    step_k0.append(k0.detach())
                    step_ctrl.append(ctrl_seq[:, t, :].detach())
                    step_t.append(step_feature(t, BATCH_SIZE, DEVICE))
                    labels.append(p_target.detach())

                    z = cand

                step_z = torch.cat(step_z, dim=0)
                step_k0 = torch.cat(step_k0, dim=0)
                step_ctrl = torch.cat(step_ctrl, dim=0)
                step_t = torch.cat(step_t, dim=0)
                labels = torch.cat(labels, dim=0).clamp(0.0, 1.0)

            inp = torch.cat([step_z, step_k0, step_ctrl, step_t], dim=-1)
            pred = torch.sigmoid(reasoner.evaluator(inp)).squeeze(-1)
            loss = mse(pred, labels)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(reasoner.evaluator.parameters(), 1.0)
            opt.step()

            total_loss += loss.item()
            total_binacc += ((pred > 0.5) == (labels > 0.5)).float().mean().item()

        print(f"Evaluator epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} | bin-acc {total_binacc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s")

# -----------------------------
# Evaluation
# -----------------------------
@torch.no_grad()
def rollout_reasoner(
    reasoner: MCLTRReasoner,
    k0: torch.Tensor,
    start_ctrl: torch.Tensor,
    ctrl_seq: torch.Tensor,
    target: Optional[torch.Tensor],
    level: int,
    mode: str,
    overwrite_spec: Optional[Tuple] = None,
    zero_k0: bool = False,
):
    if zero_k0:
        k0 = torch.zeros_like(k0)

    z0 = reasoner.init_state(k0, start_ctrl)
    z = z0
    spec = get_level_spec(level)
    actions, step_probs = [], []

    for t in range(T):
        cand = reasoner.step_update(z, k0, ctrl_seq[:, t, :], t)

        if spec["corrupt_step"] is not None and t == spec["corrupt_step"]:
            cand = inject_mistake(cand, spec["corrupt_severity"])

        if mode == "continue":
            action = torch.zeros(k0.size(0), dtype=torch.long, device=k0.device)
            z_next = cand

        elif mode == "restart":
            action = torch.full((k0.size(0),), 2, dtype=torch.long, device=k0.device)
            z_next = z0

        elif mode == "overwrite":
            if overwrite_spec is None:
                raise ValueError("overwrite_spec is required for overwrite mode")
            action = torch.ones(k0.size(0), dtype=torch.long, device=k0.device)
            z_next = apply_overwrite(reasoner, cand, z0, k0, ctrl_seq[:, t, :], t, overwrite_spec)

        elif mode == "oracle":
            if overwrite_spec is None or target is None:
                raise ValueError("oracle mode requires overwrite_spec and target")
            action, probs, _ = choose_oracle_action(reasoner, cand, z0, k0, ctrl_seq, t, target, overwrite_spec, level)
            z_next = torch.empty_like(cand)

            cont_mask = action == 0
            over_mask = action == 1
            rest_mask = action == 2

            if cont_mask.any():
                z_next[cont_mask] = cand[cont_mask]
            if over_mask.any():
                z_next[over_mask] = apply_overwrite(
                    reasoner, cand[over_mask], z0[over_mask], k0[over_mask], ctrl_seq[over_mask, t, :], t, overwrite_spec
                )
            if rest_mask.any():
                z_next[rest_mask] = z0[rest_mask]

            step_probs.append(probs)

        else:
            raise ValueError(f"Unknown mode: {mode}")

        actions.append(action)
        z = z_next

    logits = reasoner.decode(z)
    pred = logits.argmax(dim=-1)
    final_ctrl = ctrl_seq[:, -1, :]
    final_eval = reasoner.eval_score(z, k0, final_ctrl, T - 1)

    out = {
        "logits": logits,
        "pred": pred,
        "actions": torch.stack(actions, dim=1),
        "final_eval": final_eval,
        "z0": z0,
    }
    if mode == "oracle":
        out["step_probs"] = torch.stack(step_probs, dim=1)
    return out

@torch.no_grad()
def eval_base_classifier(base: BaseKnowledgeProvider, batches: int = 12, bs: int = 256):
    base.eval()
    total = 0
    correct = 0
    for _ in range(batches):
        idx = sample_indices(X_test.size(0), bs)
        xb = X_test[idx]
        yb = y_test[idx]
        logits = base(xb)
        pred = logits.argmax(dim=-1)
        correct += (pred == yb).sum().item()
        total += yb.numel()
    return correct / total

@torch.no_grad()
def eval_direct_baseline(base: BaseKnowledgeProvider, direct: DirectStaticBaseline, level: int, batches: int = 12, bs: int = 256):
    direct.eval()
    base.eval()
    total = 0
    correct = 0
    for _ in range(batches):
        x, _, start_mode, _, start_ctrl, _, target = make_reasoning_batch(X_test, y_test, bs, level=level)
        k0 = base.encode(x)
        logits = direct(k0, start_ctrl)
        pred = logits.argmax(dim=-1)
        correct += (pred == target).sum().item()
        total += target.numel()
    return correct / total

@torch.no_grad()
def eval_rollout_mode(
    base: BaseKnowledgeProvider,
    reasoner: MCLTRReasoner,
    level: int,
    mode: str,
    overwrite_spec: Tuple,
    zero_k0: bool,
    batches: int = 12,
    bs: int = 256,
):
    base.eval()
    reasoner.eval()

    total = 0
    correct = 0
    action_counts = torch.zeros(3, device=DEVICE)
    score_correct = []
    score_incorrect = []

    for _ in range(batches):
        x, _, start_mode, _, start_ctrl, ctrl_seq, target = make_reasoning_batch(X_test, y_test, bs, level=level)
        k0 = base.encode(x)

        out = rollout_reasoner(
            reasoner,
            k0,
            start_ctrl,
            ctrl_seq,
            target=target if mode == "oracle" else None,
            level=level,
            mode=mode,
            overwrite_spec=overwrite_spec,
            zero_k0=zero_k0,
        )

        pred = out["pred"]
        correct_mask = pred == target
        correct += correct_mask.sum().item()
        total += target.numel()

        if mode == "oracle":
            action_counts += torch.stack([
                (out["actions"] == 0).sum(),
                (out["actions"] == 1).sum(),
                (out["actions"] == 2).sum(),
            ]).float()

        score = out["final_eval"]
        if correct_mask.any():
            score_correct.append(score[correct_mask].mean().item())
        if (~correct_mask).any():
            score_incorrect.append(score[~correct_mask].mean().item())

    result = {
        "acc": correct / total,
        "score_correct_mean": float(np.mean(score_correct)) if len(score_correct) else float("nan"),
        "score_incorrect_mean": float(np.mean(score_incorrect)) if len(score_incorrect) else float("nan"),
    }

    if mode == "oracle":
        rates = (action_counts / (batches * bs * T)).detach().cpu().numpy()
        result["continue_rate"] = float(rates[0])
        result["overwrite_rate"] = float(rates[1])
        result["restart_rate"] = float(rates[2])

    return result

@torch.no_grad()
def probe_actions(
    base: BaseKnowledgeProvider,
    reasoner: MCLTRReasoner,
    level: int,
    overwrite_spec: Tuple,
    zero_k0: bool,
    batches: int = 4,
    bs: int = 128,
):
    base.eval()
    reasoner.eval()

    best_counts = torch.zeros(T, 3, device=DEVICE)
    mean_probs = torch.zeros(T, 3, device=DEVICE)
    gain_over_continue = torch.zeros(T, device=DEVICE)
    gain_restart_over_continue = torch.zeros(T, device=DEVICE)

    for _ in range(batches):
        x, _, start_mode, _, start_ctrl, ctrl_seq, target = make_reasoning_batch(X_test, y_test, bs, level=level)
        k0 = base.encode(x)
        if zero_k0:
            k0 = torch.zeros_like(k0)

        z0 = reasoner.init_state(k0, start_ctrl)
        z = z0
        spec = get_level_spec(level)

        for t in range(T):
            cand = reasoner.step_update(z, k0, ctrl_seq[:, t, :], t)
            if spec["corrupt_step"] is not None and t == spec["corrupt_step"]:
                cand = inject_mistake(cand, spec["corrupt_severity"])

            cont_state = cand
            over_state = apply_overwrite(reasoner, cand, z0, k0, ctrl_seq[:, t, :], t, overwrite_spec)
            rest_state = z0

            p_cont = final_target_prob_from_state(reasoner, cont_state, k0, ctrl_seq, t + 1, target, level)
            p_over = final_target_prob_from_state(reasoner, over_state, k0, ctrl_seq, t + 1, target, level)
            p_rest = final_target_prob_from_state(reasoner, rest_state, k0, ctrl_seq, t + 1, target, level)

            probs = torch.stack([p_cont, p_over, p_rest], dim=-1)
            best = probs.argmax(dim=-1)

            for a in range(3):
                best_counts[t, a] += (best == a).sum()

            mean_probs[t, 0] += p_cont.sum()
            mean_probs[t, 1] += p_over.sum()
            mean_probs[t, 2] += p_rest.sum()

            gain_over_continue[t] += (p_over - p_cont).sum()
            gain_restart_over_continue[t] += (p_rest - p_cont).sum()

            z = cand

    denom = batches * bs
    return {
        "mean_probs": (mean_probs / denom).cpu().numpy(),
        "best_rates": (best_counts / denom).cpu().numpy(),
        "gain_over_continue": (gain_over_continue / denom).cpu().numpy(),
        "gain_restart_over_continue": (gain_restart_over_continue / denom).cpu().numpy(),
    }

def print_probe_summary(probe: Dict, level: int, overwrite_spec: Tuple, zero_k0: bool):
    zk = "zero-k0" if zero_k0 else "normal-k0"
    print(f"\n--- Action probe: level {level} ({level_name(level)}), spec={spec_to_str(overwrite_spec)}, {zk} ---")
    for t in range(T):
        mp = probe["mean_probs"][t]
        br = probe["best_rates"][t]
        g_over = probe["gain_over_continue"][t]
        g_rest = probe["gain_restart_over_continue"][t]
        print(
            f"step {t}: mean p(cont/over/rest)=({mp[0]:.3f}, {mp[1]:.3f}, {mp[2]:.3f}) | "
            f"best rates=({br[0]:.3f}, {br[1]:.3f}, {br[2]:.3f}) | "
            f"Δover-cont={g_over:+.4f} | Δrestart-cont={g_rest:+.4f}"
        )

# -----------------------------
# One run
# -----------------------------
def run_one_seed_and_base_strength(seed: int, base_epochs: int):
    set_seed(seed)
    print("\n\n##############################")
    print(f"Seed = {seed} | base_epochs = {base_epochs}")
    print("##############################")

    base = BaseKnowledgeProvider().to(DEVICE)
    direct = DirectStaticBaseline().to(DEVICE)
    reasoner = MCLTRReasoner(base).to(DEVICE)

    # Stage 1
    train_base(base, base_epochs, BASE_STEPS_PER_EPOCH)

    # Freeze base and share it
    frozen_base = copy.deepcopy(base).to(DEVICE)
    set_requires_grad(frozen_base, False)
    direct.base = frozen_base
    reasoner.base = frozen_base

    # Stage 2
    train_direct_head(frozen_base, direct, epochs=3, steps_per_epoch=DIRECT_STEPS_PER_EPOCH)

    # Stage 3
    train_reasoner_continue_only(frozen_base, reasoner, epochs=4, steps_per_epoch=REASONER_STEPS_PER_EPOCH)

    # Stage 4
    train_evaluator(frozen_base, reasoner, epochs=2, steps_per_epoch=EVAL_STEPS_PER_EPOCH)

    base_acc = eval_base_classifier(frozen_base, batches=12, bs=256)

    results = {}
    for level in EVAL_LEVELS:
        results[level] = {}

        direct_acc = eval_direct_baseline(frozen_base, direct, level=level, batches=12, bs=256)
        cont_normal = eval_rollout_mode(frozen_base, reasoner, level=level, mode="continue", overwrite_spec=OVERWRITE_SPECS[0], zero_k0=False, batches=12, bs=256)
        cont_zero = eval_rollout_mode(frozen_base, reasoner, level=level, mode="continue", overwrite_spec=OVERWRITE_SPECS[0], zero_k0=True, batches=12, bs=256)

        results[level]["base_acc"] = base_acc
        results[level]["direct_acc"] = direct_acc
        results[level]["continue_normal"] = cont_normal["acc"]
        results[level]["continue_zero"] = cont_zero["acc"]

        print(f"\n--- Seed {seed} | base_epochs {base_epochs} | Level {level} ({level_name(level)}) ---")
        print(f"Base classifier (digit ID only)      : {base_acc:.4f}")
        print(f"Direct static baseline              : {direct_acc:.4f}")
        print(f"M-CLTR continue-only (normal k0)    : {cont_normal['acc']:.4f}")
        print(f"M-CLTR continue-only (zero k0)      : {cont_zero['acc']:.4f}")
        print(f"Zero-knowledge gap                  : {cont_normal['acc'] - cont_zero['acc']:+.4f}")

        for spec in OVERWRITE_SPECS:
            overwrite_res = eval_rollout_mode(frozen_base, reasoner, level=level, mode="overwrite", overwrite_spec=spec, zero_k0=False, batches=12, bs=256)
            restart_res = eval_rollout_mode(frozen_base, reasoner, level=level, mode="restart", overwrite_spec=spec, zero_k0=False, batches=12, bs=256)
            oracle_res = eval_rollout_mode(frozen_base, reasoner, level=level, mode="oracle", overwrite_spec=spec, zero_k0=False, batches=12, bs=256)

            probe = probe_actions(frozen_base, reasoner, level=level, overwrite_spec=spec, zero_k0=False, batches=4, bs=128)
            probe_zero = probe_actions(frozen_base, reasoner, level=level, overwrite_spec=spec, zero_k0=True, batches=4, bs=128)

            key = spec_to_str(spec)
            results[level][key] = {
                "overwrite_acc": overwrite_res["acc"],
                "restart_acc": restart_res["acc"],
                "oracle_acc": oracle_res["acc"],
                "oracle_c": oracle_res["continue_rate"],
                "oracle_o": oracle_res["overwrite_rate"],
                "oracle_r": oracle_res["restart_rate"],
                "probe": probe,
                "probe_zero": probe_zero,
            }

            print(f"\n  Overwrite spec = {key}")
            print(f"    Forced overwrite acc          : {overwrite_res['acc']:.4f}")
            print(f"    Forced restart acc            : {restart_res['acc']:.4f}")
            print(f"    Step-wise oracle acc          : {oracle_res['acc']:.4f}")
            print(f"    Oracle action rates C/O/R     : {oracle_res['continue_rate']:.3f}/{oracle_res['overwrite_rate']:.3f}/{oracle_res['restart_rate']:.3f}")
            print_probe_summary(probe, level, spec, zero_k0=False)
            print_probe_summary(probe_zero, level, spec, zero_k0=True)

    return results

# -----------------------------
# Run sweep
# -----------------------------
all_results = {}
for base_epochs in BASE_EPOCH_SWEEP:
    all_results[base_epochs] = {}
    for seed in SEEDS:
        all_results[base_epochs][seed] = run_one_seed_and_base_strength(seed, base_epochs)

# -----------------------------
# Aggregate summary
# -----------------------------
print("\n\n==============================")
print("Phase 4 aggregate summary")
print("==============================")

for base_epochs in BASE_EPOCH_SWEEP:
    print(f"\n################################")
    print(f"Base epochs = {base_epochs}")
    print(f"################################")

    for level in EVAL_LEVELS:
        base_vals, direct_vals, cont_vals, cont_zero_vals = [], [], [], []
        spec_summaries = {
            spec_to_str(spec): {
                "over": [], "rest": [], "oracle": [],
                "orc": [], "oro": [], "orr": [],
                "probe_over": [], "probe_rest": [],
                "probe_best_over": [], "probe_best_rest": [],
                "probe_over_zero": [], "probe_rest_zero": [],
            } for spec in OVERWRITE_SPECS
        }

        for seed in SEEDS:
            rr = all_results[base_epochs][seed][level]
            base_vals.append(rr["base_acc"])
            direct_vals.append(rr["direct_acc"])
            cont_vals.append(rr["continue_normal"])
            cont_zero_vals.append(rr["continue_zero"])

            for spec in OVERWRITE_SPECS:
                key = spec_to_str(spec)
                r = rr[key]
                spec_summaries[key]["over"].append(r["overwrite_acc"])
                spec_summaries[key]["rest"].append(r["restart_acc"])
                spec_summaries[key]["oracle"].append(r["oracle_acc"])
                spec_summaries[key]["orc"].append(r["oracle_c"])
                spec_summaries[key]["oro"].append(r["oracle_o"])
                spec_summaries[key]["orr"].append(r["oracle_r"])
                spec_summaries[key]["probe_over"].append(float(r["probe"]["gain_over_continue"].mean()))
                spec_summaries[key]["probe_rest"].append(float(r["probe"]["gain_restart_over_continue"].mean()))
                spec_summaries[key]["probe_best_over"].append(float(r["probe"]["best_rates"][:, 1].mean()))
                spec_summaries[key]["probe_best_rest"].append(float(r["probe"]["best_rates"][:, 2].mean()))
                spec_summaries[key]["probe_over_zero"].append(float(r["probe_zero"]["gain_over_continue"].mean()))
                spec_summaries[key]["probe_rest_zero"].append(float(r["probe_zero"]["gain_restart_over_continue"].mean()))

        bm, bs = mean_std(base_vals)
        dm, ds = mean_std(direct_vals)
        cm, cs = mean_std(cont_vals)
        czm, czs = mean_std(cont_zero_vals)

        print(f"\nLevel {level} ({level_name(level)})")
        print(f"  Base classifier              : {bm:.4f} ± {bs:.4f}")
        print(f"  Direct static baseline       : {dm:.4f} ± {ds:.4f}")
        print(f"  Continue-only (normal k0)    : {cm:.4f} ± {cs:.4f}")
        print(f"  Continue-only (zero k0)      : {czm:.4f} ± {czs:.4f}")
        print(f"  Zero-knowledge gap           : {(cm - czm):+.4f}")

        for spec in OVERWRITE_SPECS:
            key = spec_to_str(spec)
            om, os = mean_std(spec_summaries[key]["over"])
            rm, rs = mean_std(spec_summaries[key]["rest"])
            qm, qs = mean_std(spec_summaries[key]["oracle"])
            orc_m, orc_s = mean_std(spec_summaries[key]["orc"])
            oro_m, oro_s = mean_std(spec_summaries[key]["oro"])
            orr_m, orr_s = mean_std(spec_summaries[key]["orr"])
            go_m, go_s = mean_std(spec_summaries[key]["probe_over"])
            gr_m, gr_s = mean_std(spec_summaries[key]["probe_rest"])
            bo_m, bo_s = mean_std(spec_summaries[key]["probe_best_over"])
            br_m, br_s = mean_std(spec_summaries[key]["probe_best_rest"])
            goz_m, goz_s = mean_std(spec_summaries[key]["probe_over_zero"])
            grz_m, grz_s = mean_std(spec_summaries[key]["probe_rest_zero"])

            print(f"\n  Overwrite spec = {key}")
            print(f"    Forced overwrite acc        : {om:.4f} ± {os:.4f}")
            print(f"    Forced restart acc          : {rm:.4f} ± {rs:.4f}")
            print(f"    Step-wise oracle acc        : {qm:.4f} ± {qs:.4f}")
            print(f"    Oracle action rates C/O/R   : {orc_m:.3f} ± {orc_s:.3f} / {oro_m:.3f} ± {oro_s:.3f} / {orr_m:.3f} ± {orr_s:.3f}")
            print(f"    Probe mean Δ(over-cont)     : {go_m:+.4f} ± {go_s:.4f}")
            print(f"    Probe mean Δ(rest-cont)     : {gr_m:+.4f} ± {gr_s:.4f}")
            print(f"    Probe best-action overwrite : {bo_m:.3f} ± {bo_s:.3f}")
            print(f"    Probe best-action restart   : {br_m:.3f} ± {br_s:.3f}")
            print(f"    Zero-k Δ(over-cont)         : {goz_m:+.4f} ± {goz_s:.4f}")
            print(f"    Zero-k Δ(rest-cont)         : {grz_m:+.4f} ± {grz_s:.4f}")

print("\nDone.")

# M-CLTR Phase 5 — smarter overwrite comparison on corrupted levels only
# Compares:
#   - continue
#   - restart
#   - project(max_shift=6.0)
#   - gated_project(score -> shift range)
#   - adaptive_project(score + step-aware shift)
#   - oracle
#
# This cell assumes your previous setup cell already defined:
#   - DEVICE, T, X_DIM, K_DIM, Z_DIM, TASK_CLASSES, DIGIT_CLASSES
#   - SEEDS, BASE_EPOCH_SWEEP, TRAIN_LEVELS, BASE_STEPS_PER_EPOCH, DIRECT_STEPS_PER_EPOCH,
#     REASONER_STEPS_PER_EPOCH, EVAL_STEPS_PER_EPOCH, LR_BASE, LR_DIRECT, LR_REASONER, LR_EVAL
#   - LEVEL_SPECS, X_train, y_train, X_test, y_test
#   - BaseKnowledgeProvider, DirectStaticBaseline, MCLTRReasoner
#   - train_base, train_direct_head, train_reasoner_continue_only, train_evaluator
#   - eval_base_classifier, eval_direct_baseline, make_reasoning_batch
#   - mean_std, one_hot, step_feature, sample_indices, task_value, inject_mistake, set_requires_grad
#   - final_target_prob_from_state, continue_rollout_from_state

import copy
import random
import time
from typing import Dict, Optional, Tuple

import numpy as np
import torch
import torch.nn as nn
import torch.nn.functional as F

# -----------------------------
# Safety checks for prerequisites
# -----------------------------
_required = [
    "BaseKnowledgeProvider", "DirectStaticBaseline", "MCLTRReasoner",
    "train_base", "train_direct_head", "train_reasoner_continue_only", "train_evaluator",
    "eval_base_classifier", "eval_direct_baseline", "make_reasoning_batch",
    "mean_std", "one_hot", "step_feature", "sample_indices", "task_value", "inject_mistake",
    "set_requires_grad", "final_target_prob_from_state", "continue_rollout_from_state",
    "X_train", "y_train", "X_test", "y_test", "LEVEL_SPECS", "DEVICE", "T"
]
_missing = [name for name in _required if name not in globals()]
if _missing:
    raise RuntimeError(
        "Missing prerequisites from the earlier setup cell:\n"
        + "\n".join(f"  - {m}" for m in _missing)
    )

# -----------------------------
# Phase 5 config
# -----------------------------
SEEDS = [7, 17]
BASE_EPOCH_SWEEP = [1, 4]
EVAL_LEVELS = [3, 4]  # corrupted levels only

# Compare fixed overwrite, score-gated overwrite, and a step-aware adaptive overwrite
OVERWRITE_SPECS = [
    ("project", 6.0),
    ("gated_project", (1.0, 6.0)),
    ("adaptive_project", (0.5, 6.0)),
]

# -----------------------------
# Helpers
# -----------------------------
def set_seed(seed: int):
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    if torch.cuda.is_available():
        torch.cuda.manual_seed_all(seed)

def level_name(level: int) -> str:
    return LEVEL_SPECS[level]["name"]

def spec_to_str(spec: Tuple) -> str:
    kind, arg = spec
    if kind == "project":
        return f"project(max_shift={arg:.1f})"
    if kind == "gated_project":
        lo, hi = arg
        return f"gated_project({lo:.2f},{hi:.2f})"
    if kind == "adaptive_project":
        lo, hi = arg
        return f"adaptive_project({lo:.2f},{hi:.2f})"
    return f"{kind}({arg})"

def get_level_spec(level: int) -> Dict:
    return LEVEL_SPECS[level]

def mean_std(values):
    arr = np.asarray(values, dtype=np.float64)
    if arr.size == 1:
        return float(arr.item()), 0.0
    return float(arr.mean()), float(arr.std(ddof=1))

def capped_projection(cand: torch.Tensor, z0: torch.Tensor, max_shift) -> torch.Tensor:
    """
    Project candidate toward z0 while capping the travel distance along the cand-z0 ray.
    Smaller max_shift = stronger correction toward z0.
    """
    delta = cand - z0
    delta_norm = delta.norm(dim=-1, keepdim=True).clamp_min(1e-6)

    if not torch.is_tensor(max_shift):
        max_shift = torch.full_like(delta_norm, float(max_shift))
    elif max_shift.ndim == 1:
        max_shift = max_shift.unsqueeze(-1)
    else:
        max_shift = max_shift.to(delta_norm.dtype)

    scale = torch.minimum(torch.ones_like(delta_norm), max_shift / delta_norm)
    return z0 + delta * scale

def apply_overwrite_phase5(
    reasoner: MCLTRReasoner,
    cand: torch.Tensor,
    z0: torch.Tensor,
    k0: torch.Tensor,
    ctrl: torch.Tensor,
    t: int,
    spec: Tuple,
) -> torch.Tensor:
    kind, arg = spec

    if kind == "project":
        out = capped_projection(cand, z0, float(arg))
        return reasoner.z_norm(out)

    if kind == "gated_project":
        lo, hi = arg
        score = reasoner.eval_score(cand, k0, ctrl, t).clamp(0.0, 1.0).unsqueeze(-1)
        # Low score -> smaller shift -> stronger correction toward z0
        max_shift = lo + (hi - lo) * score
        out = capped_projection(cand, z0, max_shift)
        return reasoner.z_norm(out)

    if kind == "adaptive_project":
        lo, hi = arg
        score = reasoner.eval_score(cand, k0, ctrl, t).clamp(0.0, 1.0).unsqueeze(-1)
        step_frac = 0.0 if T <= 1 else float(t) / float(T - 1)
        step_frac = torch.full_like(score, step_frac)
        # Slightly more conservative later in the rollout, but still score-driven
        keep = 0.70 * score + 0.30 * step_frac
        max_shift = lo + (hi - lo) * keep
        out = capped_projection(cand, z0, max_shift)
        return reasoner.z_norm(out)

    raise ValueError(f"Unknown overwrite spec: {spec}")

# -----------------------------
# Rollout helpers
# -----------------------------
@torch.no_grad()
def final_target_prob_from_state(
    reasoner: MCLTRReasoner,
    z_start: torch.Tensor,
    k0: torch.Tensor,
    ctrl_seq: torch.Tensor,
    start_t: int,
    target: torch.Tensor,
    level: int,
) -> torch.Tensor:
    z_final = continue_rollout_from_state(reasoner, z_start, k0, ctrl_seq, start_t, level)
    logits = reasoner.decode(z_final)
    probs = F.softmax(logits, dim=-1)
    return probs.gather(1, target.unsqueeze(1)).squeeze(1)

@torch.no_grad()
def choose_oracle_action_phase5(
    reasoner: MCLTRReasoner,
    cand: torch.Tensor,
    z0: torch.Tensor,
    k0: torch.Tensor,
    ctrl_seq: torch.Tensor,
    t: int,
    target: torch.Tensor,
    overwrite_spec: Tuple,
    level: int,
):
    cont_state = cand
    over_state = apply_overwrite_phase5(reasoner, cand, z0, k0, ctrl_seq[:, t, :], t, overwrite_spec)
    rest_state = z0

    p_cont = final_target_prob_from_state(reasoner, cont_state, k0, ctrl_seq, t + 1, target, level)
    p_over = final_target_prob_from_state(reasoner, over_state, k0, ctrl_seq, t + 1, target, level)
    p_rest = final_target_prob_from_state(reasoner, rest_state, k0, ctrl_seq, t + 1, target, level)

    probs = torch.stack([p_cont, p_over, p_rest], dim=-1)
    tie_bias = torch.tensor([2e-3, 1e-3, 0.0], device=probs.device).unsqueeze(0)
    action = (probs + tie_bias).argmax(dim=-1)
    best_prob = probs.gather(1, action.unsqueeze(1)).squeeze(1)
    return action, probs, best_prob

@torch.no_grad()
def rollout_reasoner_phase5(
    reasoner: MCLTRReasoner,
    k0: torch.Tensor,
    start_ctrl: torch.Tensor,
    ctrl_seq: torch.Tensor,
    target: Optional[torch.Tensor],
    level: int,
    mode: str,
    overwrite_spec: Optional[Tuple] = None,
    zero_k0: bool = False,
):
    if zero_k0:
        k0 = torch.zeros_like(k0)

    z0 = reasoner.init_state(k0, start_ctrl)
    z = z0
    spec = get_level_spec(level)

    actions = []
    step_probs = []

    for t in range(T):
        cand = reasoner.step_update(z, k0, ctrl_seq[:, t, :], t)

        if spec["corrupt_step"] is not None and t == spec["corrupt_step"]:
            cand = inject_mistake(cand, spec["corrupt_severity"])

        if mode == "continue":
            action = torch.zeros(k0.size(0), dtype=torch.long, device=k0.device)
            z_next = cand

        elif mode == "restart":
            action = torch.full((k0.size(0),), 2, dtype=torch.long, device=k0.device)
            z_next = z0

        elif mode == "overwrite":
            if overwrite_spec is None:
                raise ValueError("overwrite_spec is required for overwrite mode")
            action = torch.ones(k0.size(0), dtype=torch.long, device=k0.device)
            z_next = apply_overwrite_phase5(reasoner, cand, z0, k0, ctrl_seq[:, t, :], t, overwrite_spec)

        elif mode == "oracle":
            if overwrite_spec is None or target is None:
                raise ValueError("oracle mode requires overwrite_spec and target")
            action, probs, _ = choose_oracle_action_phase5(
                reasoner, cand, z0, k0, ctrl_seq, t, target, overwrite_spec, level
            )
            z_next = torch.empty_like(cand)

            cont_mask = action == 0
            over_mask = action == 1
            rest_mask = action == 2

            if cont_mask.any():
                z_next[cont_mask] = cand[cont_mask]
            if over_mask.any():
                z_next[over_mask] = apply_overwrite_phase5(
                    reasoner,
                    cand[over_mask],
                    z0[over_mask],
                    k0[over_mask],
                    ctrl_seq[over_mask, t, :],
                    t,
                    overwrite_spec,
                )
            if rest_mask.any():
                z_next[rest_mask] = z0[rest_mask]

            step_probs.append(probs)

        else:
            raise ValueError(f"Unknown mode: {mode}")

        actions.append(action)
        z = z_next

    logits = reasoner.decode(z)
    pred = logits.argmax(dim=-1)

    final_ctrl = ctrl_seq[:, -1, :]
    final_eval = reasoner.eval_score(z, k0, final_ctrl, T - 1)

    out = {
        "logits": logits,
        "pred": pred,
        "actions": torch.stack(actions, dim=1),
        "final_eval": final_eval,
        "z0": z0,
    }
    if mode == "oracle":
        out["step_probs"] = torch.stack(step_probs, dim=1)
    return out

@torch.no_grad()
def eval_rollout_mode_phase5(
    base: BaseKnowledgeProvider,
    reasoner: MCLTRReasoner,
    level: int,
    mode: str,
    overwrite_spec: Tuple,
    zero_k0: bool,
    batches: int = 12,
    bs: int = 256,
):
    base.eval()
    reasoner.eval()

    total = 0
    correct = 0
    action_counts = torch.zeros(3, device=DEVICE)
    score_correct = []
    score_incorrect = []

    for _ in range(batches):
        x, _, start_mode, _, start_ctrl, ctrl_seq, target = make_reasoning_batch(
            X_test, y_test, bs, level=level
        )
        k0 = base.encode(x)

        out = rollout_reasoner_phase5(
            reasoner,
            k0,
            start_ctrl,
            ctrl_seq,
            target=target if mode == "oracle" else None,
            level=level,
            mode=mode,
            overwrite_spec=overwrite_spec,
            zero_k0=zero_k0,
        )

        pred = out["pred"]
        correct_mask = pred == target
        correct += correct_mask.sum().item()
        total += target.numel()

        if mode == "oracle":
            action_counts += torch.stack([
                (out["actions"] == 0).sum(),
                (out["actions"] == 1).sum(),
                (out["actions"] == 2).sum(),
            ]).float()

        score = out["final_eval"]
        if correct_mask.any():
            score_correct.append(score[correct_mask].mean().item())
        if (~correct_mask).any():
            score_incorrect.append(score[~correct_mask].mean().item())

    result = {
        "acc": correct / total,
        "score_correct_mean": float(np.mean(score_correct)) if len(score_correct) else float("nan"),
        "score_incorrect_mean": float(np.mean(score_incorrect)) if len(score_incorrect) else float("nan"),
    }

    if mode == "oracle":
        rates = (action_counts / (batches * bs * T)).detach().cpu().numpy()
        result["continue_rate"] = float(rates[0])
        result["overwrite_rate"] = float(rates[1])
        result["restart_rate"] = float(rates[2])

    return result

@torch.no_grad()
def probe_actions_phase5(
    base: BaseKnowledgeProvider,
    reasoner: MCLTRReasoner,
    level: int,
    overwrite_spec: Tuple,
    zero_k0: bool,
    batches: int = 4,
    bs: int = 128,
):
    base.eval()
    reasoner.eval()

    best_counts = torch.zeros(T, 3, device=DEVICE)
    mean_probs = torch.zeros(T, 3, device=DEVICE)
    gain_over_continue = torch.zeros(T, device=DEVICE)
    gain_restart_over_continue = torch.zeros(T, device=DEVICE)

    for _ in range(batches):
        x, _, start_mode, _, start_ctrl, ctrl_seq, target = make_reasoning_batch(
            X_test, y_test, bs, level=level
        )
        k0 = base.encode(x)
        if zero_k0:
            k0 = torch.zeros_like(k0)

        z0 = reasoner.init_state(k0, start_ctrl)
        z = z0
        spec = get_level_spec(level)

        for t in range(T):
            cand = reasoner.step_update(z, k0, ctrl_seq[:, t, :], t)

            if spec["corrupt_step"] is not None and t == spec["corrupt_step"]:
                cand = inject_mistake(cand, spec["corrupt_severity"])

            cont_state = cand
            over_state = apply_overwrite_phase5(reasoner, cand, z0, k0, ctrl_seq[:, t, :], t, overwrite_spec)
            rest_state = z0

            p_cont = final_target_prob_from_state(reasoner, cont_state, k0, ctrl_seq, t + 1, target, level)
            p_over = final_target_prob_from_state(reasoner, over_state, k0, ctrl_seq, t + 1, target, level)
            p_rest = final_target_prob_from_state(reasoner, rest_state, k0, ctrl_seq, t + 1, target, level)

            probs = torch.stack([p_cont, p_over, p_rest], dim=-1)
            best = probs.argmax(dim=-1)

            for a in range(3):
                best_counts[t, a] += (best == a).sum()

            mean_probs[t, 0] += p_cont.sum()
            mean_probs[t, 1] += p_over.sum()
            mean_probs[t, 2] += p_rest.sum()

            gain_over_continue[t] += (p_over - p_cont).sum()
            gain_restart_over_continue[t] += (p_rest - p_cont).sum()

            z = cand

    denom = batches * bs
    return {
        "mean_probs": (mean_probs / denom).cpu().numpy(),
        "best_rates": (best_counts / denom).cpu().numpy(),
        "gain_over_continue": (gain_over_continue / denom).cpu().numpy(),
        "gain_restart_over_continue": (gain_restart_over_continue / denom).cpu().numpy(),
    }

def print_probe_summary_phase5(probe: Dict, level: int, overwrite_spec: Tuple, zero_k0: bool):
    zk = "zero-k0" if zero_k0 else "normal-k0"
    print(f"\n--- Action probe: level {level} ({level_name(level)}), spec={spec_to_str(overwrite_spec)}, {zk} ---")
    for t in range(T):
        mp = probe["mean_probs"][t]
        br = probe["best_rates"][t]
        g_over = probe["gain_over_continue"][t]
        g_rest = probe["gain_restart_over_continue"][t]
        print(
            f"step {t}: mean p(cont/over/rest)=({mp[0]:.3f}, {mp[1]:.3f}, {mp[2]:.3f}) | "
            f"best rates=({br[0]:.3f}, {br[1]:.3f}, {br[2]:.3f}) | "
            f"Δover-cont={g_over:+.4f} | Δrestart-cont={g_rest:+.4f}"
        )

# -----------------------------
# One run for one seed/base strength
# -----------------------------
def run_phase5_one_seed_and_base_strength(seed: int, base_epochs: int):
    set_seed(seed)
    print("\n\n##############################")
    print(f"Seed = {seed} | base_epochs = {base_epochs}")
    print("##############################")

    base = BaseKnowledgeProvider().to(DEVICE)
    direct = DirectStaticBaseline().to(DEVICE)
    reasoner = MCLTRReasoner(base).to(DEVICE)

    # Stage 1
    train_base(base, base_epochs, BASE_STEPS_PER_EPOCH)

    # Freeze base and share it
    frozen_base = copy.deepcopy(base).to(DEVICE)
    set_requires_grad(frozen_base, False)
    direct.base = frozen_base
    reasoner.base = frozen_base

    # Stage 2
    train_direct_head(frozen_base, direct, epochs=3, steps_per_epoch=DIRECT_STEPS_PER_EPOCH)

    # Stage 3
    train_reasoner_continue_only(frozen_base, reasoner, epochs=4, steps_per_epoch=REASONER_STEPS_PER_EPOCH)

    # Stage 4
    train_evaluator(frozen_base, reasoner, epochs=2, steps_per_epoch=EVAL_STEPS_PER_EPOCH)

    base_acc = eval_base_classifier(frozen_base, batches=12, bs=256)

    results = {}
    for level in EVAL_LEVELS:
        results[level] = {}

        direct_acc = eval_direct_baseline(frozen_base, direct, level=level, batches=12, bs=256)
        cont_normal = eval_rollout_mode_phase5(
            frozen_base, reasoner, level=level, mode="continue",
            overwrite_spec=OVERWRITE_SPECS[0], zero_k0=False,
            batches=12, bs=256
        )
        cont_zero = eval_rollout_mode_phase5(
            frozen_base, reasoner, level=level, mode="continue",
            overwrite_spec=OVERWRITE_SPECS[0], zero_k0=True,
            batches=12, bs=256
        )

        results[level]["base_acc"] = base_acc
        results[level]["direct_acc"] = direct_acc
        results[level]["continue_normal"] = cont_normal["acc"]
        results[level]["continue_zero"] = cont_zero["acc"]

        print(f"\n--- Seed {seed} | base_epochs {base_epochs} | Level {level} ({level_name(level)}) ---")
        print(f"Base classifier (digit ID only)      : {base_acc:.4f}")
        print(f"Direct static baseline              : {direct_acc:.4f}")
        print(f"M-CLTR continue-only (normal k0)    : {cont_normal['acc']:.4f}")
        print(f"M-CLTR continue-only (zero k0)      : {cont_zero['acc']:.4f}")
        print(f"Zero-knowledge gap                  : {cont_normal['acc'] - cont_zero['acc']:+.4f}")

        for spec in OVERWRITE_SPECS:
            overwrite_res = eval_rollout_mode_phase5(
                frozen_base, reasoner, level=level, mode="overwrite",
                overwrite_spec=spec, zero_k0=False,
                batches=12, bs=256
            )
            restart_res = eval_rollout_mode_phase5(
                frozen_base, reasoner, level=level, mode="restart",
                overwrite_spec=spec, zero_k0=False,
                batches=12, bs=256
            )
            oracle_res = eval_rollout_mode_phase5(
                frozen_base, reasoner, level=level, mode="oracle",
                overwrite_spec=spec, zero_k0=False,
                batches=12, bs=256
            )

            probe = probe_actions_phase5(
                frozen_base, reasoner, level=level, overwrite_spec=spec,
                zero_k0=False, batches=4, bs=128
            )
            probe_zero = probe_actions_phase5(
                frozen_base, reasoner, level=level, overwrite_spec=spec,
                zero_k0=True, batches=4, bs=128
            )

            key = spec_to_str(spec)
            results[level][key] = {
                "overwrite_acc": overwrite_res["acc"],
                "restart_acc": restart_res["acc"],
                "oracle_acc": oracle_res["acc"],
                "oracle_c": oracle_res["continue_rate"],
                "oracle_o": oracle_res["overwrite_rate"],
                "oracle_r": oracle_res["restart_rate"],
                "probe": probe,
                "probe_zero": probe_zero,
            }

            print(f"\n  Overwrite spec = {key}")
            print(f"    Forced overwrite acc          : {overwrite_res['acc']:.4f}")
            print(f"    Forced restart acc            : {restart_res['acc']:.4f}")
            print(f"    Step-wise oracle acc          : {oracle_res['acc']:.4f}")
            print(f"    Oracle action rates C/O/R     : {oracle_res['continue_rate']:.3f}/{oracle_res['overwrite_rate']:.3f}/{oracle_res['restart_rate']:.3f}")
            print_probe_summary_phase5(probe, level, spec, zero_k0=False)
            print_probe_summary_phase5(probe_zero, level, spec, zero_k0=True)

    return results

# -----------------------------
# Run sweep
# -----------------------------
all_results = {}
for base_epochs in BASE_EPOCH_SWEEP:
    all_results[base_epochs] = {}
    for seed in SEEDS:
        all_results[base_epochs][seed] = run_phase5_one_seed_and_base_strength(seed, base_epochs)

# -----------------------------
# Aggregate summary
# -----------------------------
print("\n\n==============================")
print("Phase 5 aggregate summary")
print("==============================")

for base_epochs in BASE_EPOCH_SWEEP:
    print(f"\n################################")
    print(f"Base epochs = {base_epochs}")
    print(f"################################")

    for level in EVAL_LEVELS:
        base_vals, direct_vals, cont_vals, cont_zero_vals = [], [], [], []

        spec_summaries = {
            spec_to_str(spec): {
                "over": [], "rest": [], "oracle": [],
                "orc": [], "oro": [], "orr": [],
                "probe_over": [], "probe_rest": [],
                "probe_best_over": [], "probe_best_rest": [],
                "probe_over_zero": [], "probe_rest_zero": [],
            } for spec in OVERWRITE_SPECS
        }

        for seed in SEEDS:
            rr = all_results[base_epochs][seed][level]
            base_vals.append(rr["base_acc"])
            direct_vals.append(rr["direct_acc"])
            cont_vals.append(rr["continue_normal"])
            cont_zero_vals.append(rr["continue_zero"])

            for spec in OVERWRITE_SPECS:
                key = spec_to_str(spec)
                r = rr[key]
                spec_summaries[key]["over"].append(r["overwrite_acc"])
                spec_summaries[key]["rest"].append(r["restart_acc"])
                spec_summaries[key]["oracle"].append(r["oracle_acc"])
                spec_summaries[key]["orc"].append(r["oracle_c"])
                spec_summaries[key]["oro"].append(r["oracle_o"])
                spec_summaries[key]["orr"].append(r["oracle_r"])
                spec_summaries[key]["probe_over"].append(float(r["probe"]["gain_over_continue"].mean()))
                spec_summaries[key]["probe_rest"].append(float(r["probe"]["gain_restart_over_continue"].mean()))
                spec_summaries[key]["probe_best_over"].append(float(r["probe"]["best_rates"][:, 1].mean()))
                spec_summaries[key]["probe_best_rest"].append(float(r["probe"]["best_rates"][:, 2].mean()))
                spec_summaries[key]["probe_over_zero"].append(float(r["probe_zero"]["gain_over_continue"].mean()))
                spec_summaries[key]["probe_rest_zero"].append(float(r["probe_zero"]["gain_restart_over_continue"].mean()))

        bm, bs = mean_std(base_vals)
        dm, ds = mean_std(direct_vals)
        cm, cs = mean_std(cont_vals)
        czm, czs = mean_std(cont_zero_vals)

        print(f"\nLevel {level} ({level_name(level)})")
        print(f"  Base classifier              : {bm:.4f} ± {bs:.4f}")
        print(f"  Direct static baseline       : {dm:.4f} ± {ds:.4f}")
        print(f"  Continue-only (normal k0)    : {cm:.4f} ± {cs:.4f}")
        print(f"  Continue-only (zero k0)      : {czm:.4f} ± {czs:.4f}")
        print(f"  Zero-knowledge gap           : {(cm - czm):+.4f}")

        for spec in OVERWRITE_SPECS:
            key = spec_to_str(spec)
            om, os = mean_std(spec_summaries[key]["over"])
            rm, rs = mean_std(spec_summaries[key]["rest"])
            qm, qs = mean_std(spec_summaries[key]["oracle"])
            orc_m, orc_s = mean_std(spec_summaries[key]["orc"])
            oro_m, oro_s = mean_std(spec_summaries[key]["oro"])
            orr_m, orr_s = mean_std(spec_summaries[key]["orr"])
            go_m, go_s = mean_std(spec_summaries[key]["probe_over"])
            gr_m, gr_s = mean_std(spec_summaries[key]["probe_rest"])
            bo_m, bo_s = mean_std(spec_summaries[key]["probe_best_over"])
            br_m, br_s = mean_std(spec_summaries[key]["probe_best_rest"])
            goz_m, goz_s = mean_std(spec_summaries[key]["probe_over_zero"])
            grz_m, grz_s = mean_std(spec_summaries[key]["probe_rest_zero"])

            print(f"\n  Overwrite spec = {key}")
            print(f"    Forced overwrite acc        : {om:.4f} ± {os:.4f}")
            print(f"    Forced restart acc          : {rm:.4f} ± {rs:.4f}")
            print(f"    Step-wise oracle acc        : {qm:.4f} ± {qs:.4f}")
            print(f"    Oracle action rates C/O/R   : {orc_m:.3f} ± {orc_s:.3f} / {oro_m:.3f} ± {oro_s:.3f} / {orr_m:.3f} ± {orr_s:.3f}")
            print(f"    Probe mean Δ(over-cont)     : {go_m:+.4f} ± {go_s:.4f}")
            print(f"    Probe mean Δ(rest-cont)     : {gr_m:+.4f} ± {gr_s:.4f}")
            print(f"    Probe best-action overwrite : {bo_m:.3f} ± {bo_s:.4f}")
            print(f"    Probe best-action restart   : {br_m:.3f} ± {br_s:.4f}")
            print(f"    Zero-k Δ(over-cont)         : {goz_m:+.4f} ± {goz_s:.4f}")
            print(f"    Zero-k Δ(rest-cont)         : {grz_m:+.4f} ± {grz_s:.4f}")

print("\nDone.")

# M-CLTR Phase 6 — selective overwrite test on corrupted levels only
# Compares:
#   1) continue
#   2) restart
#   3) project(max_shift=6.0)
#   4) gated_project(1.00, 6.00)
#   5) adaptive_project(0.50, 6.00)
#
# Logs:
#   - rollout accuracy
#   - oracle action rates
#   - mean Δ(overwrite - continue)
#   - mean Δ(restart - continue)
#   - best-action rates per step
#
# This cell is self-contained and can be pasted after your existing setup.

import copy
import random
import time
from typing import Dict, Optional, Tuple

import numpy as np
import torch
import torch.nn as nn
import torch.nn.functional as F
from sklearn.datasets import load_digits
from sklearn.model_selection import train_test_split

# -----------------------------
# Device / reproducibility
# -----------------------------
DEVICE = torch.device("cuda" if torch.cuda.is_available() else "cpu")
print("Device:", DEVICE)

def set_seed(seed: int):
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    if torch.cuda.is_available():
        torch.cuda.manual_seed_all(seed)

# -----------------------------
# Config
# -----------------------------
T = 6
X_DIM = 64
K_DIM = 64
Z_DIM = 96
TASK_CLASSES = 2
DIGIT_CLASSES = 10

SEEDS = [7, 17]
BASE_EPOCH_SWEEP = [1, 4]

BATCH_SIZE = 128
BASE_STEPS_PER_EPOCH = 24
DIRECT_STEPS_PER_EPOCH = 24
REASONER_STEPS_PER_EPOCH = 24
EVAL_STEPS_PER_EPOCH = 24

LR_BASE = 2e-3
LR_DIRECT = 2e-3
LR_REASONER = 2e-3
LR_EVAL = 2e-3

TRAIN_LEVELS = [0, 1, 2]
EVAL_LEVELS = [3, 4]  # corrupted levels only

LEVEL_SPECS = {
    0: {"name": "easy / no switch",        "switch_step": T,      "input_noise": 0.00, "corrupt_step": None, "corrupt_severity": 0.00},
    1: {"name": "medium / mid switch",     "switch_step": T // 2, "input_noise": 0.00, "corrupt_step": None, "corrupt_severity": 0.00},
    2: {"name": "hard / early switch",     "switch_step": 1,      "input_noise": 0.00, "corrupt_step": None, "corrupt_severity": 0.00},
    3: {"name": "switch + latent mistake", "switch_step": T // 2, "input_noise": 0.00, "corrupt_step": 2,    "corrupt_severity": 0.35},
    4: {"name": "switch + noise + mistake","switch_step": 1,      "input_noise": 0.15, "corrupt_step": 1,    "corrupt_severity": 0.45},
}

OVERWRITE_SPECS = [
    ("project", 6.0),
    ("gated_project", (1.00, 6.00)),
    ("adaptive_project", (0.50, 6.00)),
]

# -----------------------------
# Data
# -----------------------------
digits = load_digits()
X_all = torch.tensor(digits.data, dtype=torch.float32) / 16.0
y_all = torch.tensor(digits.target, dtype=torch.long)

X_train_np, X_test_np, y_train_np, y_test_np = train_test_split(
    X_all.numpy(),
    y_all.numpy(),
    test_size=0.30,
    random_state=0,
    stratify=y_all.numpy(),
)

X_train = torch.tensor(X_train_np, dtype=torch.float32, device=DEVICE)
y_train = torch.tensor(y_train_np, dtype=torch.long, device=DEVICE)
X_test = torch.tensor(X_test_np, dtype=torch.float32, device=DEVICE)
y_test = torch.tensor(y_test_np, dtype=torch.long, device=DEVICE)

# -----------------------------
# Helpers
# -----------------------------
def one_hot(v: torch.Tensor, n: int) -> torch.Tensor:
    return F.one_hot(v.long(), n).float()

def step_feature(t: int, batch_size: int, device: torch.device) -> torch.Tensor:
    s = 0.0 if T <= 1 else float(t) / float(T - 1)
    return torch.full((batch_size, 1), s, device=device)

def mean_std(values):
    arr = np.asarray(values, dtype=np.float64)
    if arr.size == 1:
        return float(arr.item()), 0.0
    return float(arr.mean()), float(arr.std(ddof=1))

def sample_indices(n: int, batch_size: int) -> torch.Tensor:
    return torch.randint(0, n, (batch_size,), device=DEVICE)

def task_value(digit_labels: torch.Tensor, mode: torch.Tensor) -> torch.Tensor:
    parity = (digit_labels % 2).long()
    highlow = (digit_labels >= 5).long()
    return torch.where(mode == 0, parity, highlow)

def get_level_spec(level: int) -> Dict:
    return LEVEL_SPECS[level]

def level_name(level: int) -> str:
    return LEVEL_SPECS[level]["name"]

def spec_to_str(spec: Tuple):
    kind, arg = spec
    if kind == "project":
        return f"project(max_shift={float(arg):.1f})"
    if kind == "gated_project":
        lo, hi = arg
        return f"gated_project({lo:.2f},{hi:.2f})"
    if kind == "adaptive_project":
        lo, hi = arg
        return f"adaptive_project({lo:.2f},{hi:.2f})"
    return f"{kind}({arg})"

def inject_mistake(z: torch.Tensor, severity: float) -> torch.Tensor:
    if severity <= 0:
        return z
    rolled = torch.roll(z, shifts=1, dims=-1)
    mixed = (1.0 - severity) * z + severity * rolled
    mixed = mixed + (0.50 * severity) * torch.randn_like(z)
    return mixed

def set_requires_grad(module: nn.Module, flag: bool):
    for p in module.parameters():
        p.requires_grad = flag

# -----------------------------
# Batch generation
# -----------------------------
def make_reasoning_batch(
    x_pool: torch.Tensor,
    y_pool: torch.Tensor,
    batch_size: int,
    level: int,
):
    spec = get_level_spec(level)
    idx = sample_indices(x_pool.size(0), batch_size)
    x = x_pool[idx].clone()

    if spec["input_noise"] > 0:
        x = torch.clamp(x + spec["input_noise"] * torch.randn_like(x), 0.0, 1.0)

    digit_labels = y_pool[idx]
    start_mode = torch.randint(0, 2, (batch_size,), device=DEVICE)

    switch_step = spec["switch_step"]
    end_mode = start_mode.clone() if switch_step >= T else (1 - start_mode)

    start_ctrl = one_hot(start_mode, 2)
    t_ids = torch.arange(T, device=DEVICE).unsqueeze(0).expand(batch_size, T)
    curr_modes = torch.where(t_ids < switch_step, start_mode.unsqueeze(1), end_mode.unsqueeze(1))
    ctrl_seq = one_hot(curr_modes, 2)

    final_mode = curr_modes[:, -1]
    target = task_value(digit_labels, final_mode)

    return x, digit_labels, start_mode, end_mode, start_ctrl, ctrl_seq, target

# -----------------------------
# Models
# -----------------------------
class MLP(nn.Module):
    def __init__(self, in_dim: int, out_dim: int, hidden: int = 128):
        super().__init__()
        self.net = nn.Sequential(
            nn.Linear(in_dim, hidden),
            nn.GELU(),
            nn.Linear(hidden, hidden),
            nn.GELU(),
            nn.Linear(hidden, out_dim),
        )

    def forward(self, x):
        return self.net(x)

class BaseKnowledgeProvider(nn.Module):
    def __init__(self, x_dim: int = X_DIM, k_dim: int = K_DIM):
        super().__init__()
        self.encoder = nn.Sequential(
            nn.Linear(x_dim, 128),
            nn.GELU(),
            nn.Linear(128, k_dim),
            nn.LayerNorm(k_dim),
        )
        self.classifier = nn.Sequential(
            nn.Linear(k_dim, 64),
            nn.GELU(),
            nn.Linear(64, DIGIT_CLASSES),
        )
        for m in self.modules():
            if isinstance(m, nn.Linear):
                nn.init.xavier_uniform_(m.weight)
                if m.bias is not None:
                    nn.init.zeros_(m.bias)

    def encode(self, x: torch.Tensor) -> torch.Tensor:
        return self.encoder(x)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        k0 = self.encode(x)
        return self.classifier(k0)

class DirectStaticBaseline(nn.Module):
    def __init__(self, k_dim: int = K_DIM):
        super().__init__()
        self.head = MLP(k_dim + 2, TASK_CLASSES, hidden=96)
        for m in self.modules():
            if isinstance(m, nn.Linear):
                nn.init.xavier_uniform_(m.weight)
                if m.bias is not None:
                    nn.init.zeros_(m.bias)

    def forward(self, k0: torch.Tensor, start_ctrl: torch.Tensor) -> torch.Tensor:
        return self.head(torch.cat([k0, start_ctrl], dim=-1))

class MCLTRReasoner(nn.Module):
    def __init__(self, base: BaseKnowledgeProvider, k_dim: int = K_DIM, z_dim: int = Z_DIM):
        super().__init__()
        self.base = base
        self.k_dim = k_dim
        self.z_dim = z_dim

        self.init_net = MLP(k_dim + 2, z_dim, hidden=128)
        self.trans_net = MLP(z_dim + k_dim + 2 + 1, z_dim, hidden=128)
        self.context_net = MLP(k_dim + 2 + 1, z_dim, hidden=128)

        self.evaluator = MLP(z_dim + k_dim + 2 + 1, 1, hidden=96)
        self.decoder = nn.Linear(z_dim, TASK_CLASSES)

        self.z_norm = nn.LayerNorm(z_dim)
        self.ctx_norm = nn.LayerNorm(z_dim)

        for m in self.modules():
            if isinstance(m, nn.Linear):
                nn.init.xavier_uniform_(m.weight)
                if m.bias is not None:
                    nn.init.zeros_(m.bias)

    def init_state(self, k0: torch.Tensor, start_ctrl: torch.Tensor) -> torch.Tensor:
        z0 = self.init_net(torch.cat([k0, start_ctrl], dim=-1))
        return self.z_norm(z0)

    def context_state(self, k0: torch.Tensor, ctrl: torch.Tensor, t: int) -> torch.Tensor:
        step = step_feature(t, k0.size(0), k0.device)
        ctx = self.context_net(torch.cat([k0, ctrl, step], dim=-1))
        return self.ctx_norm(ctx)

    def step_update(self, z: torch.Tensor, k0: torch.Tensor, ctrl: torch.Tensor, t: int) -> torch.Tensor:
        step = step_feature(t, z.size(0), z.device)
        inp = torch.cat([z, k0, ctrl, step], dim=-1)
        delta = torch.tanh(self.trans_net(inp))
        cand = self.z_norm(0.80 * z + 0.20 * delta)
        return cand

    def eval_score(self, z: torch.Tensor, k0: torch.Tensor, ctrl: torch.Tensor, t: int) -> torch.Tensor:
        step = step_feature(t, z.size(0), z.device)
        inp = torch.cat([z, k0, ctrl, step], dim=-1)
        return torch.sigmoid(self.evaluator(inp)).squeeze(-1)

    def decode(self, z: torch.Tensor) -> torch.Tensor:
        return self.decoder(z)

# -----------------------------
# Overwrite operators
# -----------------------------
def project_overwrite(cand: torch.Tensor, z0: torch.Tensor, max_shift: float) -> torch.Tensor:
    delta = cand - z0
    delta_norm = delta.norm(dim=-1, keepdim=True).clamp_min(1e-6)
    scale = torch.clamp(torch.full_like(delta_norm, max_shift) / delta_norm, max=1.0)
    return z0 + delta * scale

def gated_project_overwrite(
    cand: torch.Tensor,
    z0: torch.Tensor,
    score: torch.Tensor,
    lo: float,
    hi: float,
) -> torch.Tensor:
    alpha = lo + (hi - lo) * score.unsqueeze(-1)
    return alpha * cand + (1.0 - alpha) * z0

def adaptive_project_overwrite(
    reasoner: MCLTRReasoner,
    cand: torch.Tensor,
    z0: torch.Tensor,
    k0: torch.Tensor,
    ctrl: torch.Tensor,
    t: int,
    lo: float,
    hi: float,
) -> torch.Tensor:
    """
    A slightly smarter overwrite:
      - if evaluator score is low, move closer to restart anchor z0
      - if evaluator score is high, keep more of cand
      - also cap maximum displacement from z0 with an adaptive limit
    """
    score = reasoner.eval_score(cand, k0, ctrl, t).clamp(0.0, 1.0)
    alpha = lo + (hi - lo) * score.unsqueeze(-1)  # keep more of cand when score is high
    blended = alpha * cand + (1.0 - alpha) * z0

    # Adaptive cap: low score => tighter cap, high score => looser cap
    max_shift = (1.0 + 5.0 * score).unsqueeze(-1)  # range approx [1, 6]
    delta = blended - z0
    delta_norm = delta.norm(dim=-1, keepdim=True).clamp_min(1e-6)
    scale = torch.clamp(max_shift / delta_norm, max=1.0)
    return z0 + delta * scale

def apply_overwrite(
    reasoner: MCLTRReasoner,
    cand: torch.Tensor,
    z0: torch.Tensor,
    k0: torch.Tensor,
    ctrl: torch.Tensor,
    t: int,
    spec: Tuple,
) -> torch.Tensor:
    kind, arg = spec
    if kind == "project":
        return reasoner.z_norm(project_overwrite(cand, z0, float(arg)))
    if kind == "gated_project":
        lo, hi = arg
        score = reasoner.eval_score(cand, k0, ctrl, t)
        out = gated_project_overwrite(cand, z0, score, float(lo), float(hi))
        return reasoner.z_norm(out)
    if kind == "adaptive_project":
        lo, hi = arg
        out = adaptive_project_overwrite(reasoner, cand, z0, k0, ctrl, t, float(lo), float(hi))
        return reasoner.z_norm(out)
    raise ValueError(f"Unknown overwrite spec: {spec}")

# -----------------------------
# Rollout helpers
# -----------------------------
@torch.no_grad()
def continue_rollout_from_state(
    reasoner: MCLTRReasoner,
    z_start: torch.Tensor,
    k0: torch.Tensor,
    ctrl_seq: torch.Tensor,
    start_t: int,
    level: int,
) -> torch.Tensor:
    spec = get_level_spec(level)
    z = z_start
    for t in range(start_t, T):
        z = reasoner.step_update(z, k0, ctrl_seq[:, t, :], t)
        if spec["corrupt_step"] is not None and t == spec["corrupt_step"]:
            z = inject_mistake(z, spec["corrupt_severity"])
    return z

@torch.no_grad()
def final_target_prob_from_state(
    reasoner: MCLTRReasoner,
    z_start: torch.Tensor,
    k0: torch.Tensor,
    ctrl_seq: torch.Tensor,
    start_t: int,
    target: torch.Tensor,
    level: int,
) -> torch.Tensor:
    z_final = continue_rollout_from_state(reasoner, z_start, k0, ctrl_seq, start_t, level)
    logits = reasoner.decode(z_final)
    probs = F.softmax(logits, dim=-1)
    return probs.gather(1, target.unsqueeze(1)).squeeze(1)

@torch.no_grad()
def choose_oracle_action(
    reasoner: MCLTRReasoner,
    cand: torch.Tensor,
    z0: torch.Tensor,
    k0: torch.Tensor,
    ctrl_seq: torch.Tensor,
    t: int,
    target: torch.Tensor,
    overwrite_spec: Tuple,
    level: int,
):
    cont_state = cand
    over_state = apply_overwrite(reasoner, cand, z0, k0, ctrl_seq[:, t, :], t, overwrite_spec)
    rest_state = z0

    p_cont = final_target_prob_from_state(reasoner, cont_state, k0, ctrl_seq, t + 1, target, level)
    p_over = final_target_prob_from_state(reasoner, over_state, k0, ctrl_seq, t + 1, target, level)
    p_rest = final_target_prob_from_state(reasoner, rest_state, k0, ctrl_seq, t + 1, target, level)

    probs = torch.stack([p_cont, p_over, p_rest], dim=-1)
    tie_bias = torch.tensor([2e-3, 1e-3, 0.0], device=probs.device).unsqueeze(0)
    action = (probs + tie_bias).argmax(dim=-1)
    return action, probs

# -----------------------------
# Training
# -----------------------------
def train_base(base: BaseKnowledgeProvider, epochs: int, steps_per_epoch: int):
    base.train()
    opt = torch.optim.AdamW(base.parameters(), lr=LR_BASE, weight_decay=1e-4)
    ce = nn.CrossEntropyLoss()

    print("\n=== Stage 1: base knowledge pretraining (digit classification) ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_acc = 0.0

        for _ in range(steps_per_epoch):
            idx = sample_indices(X_train.size(0), BATCH_SIZE)
            xb = X_train[idx]
            yb = y_train[idx]

            logits = base(xb)
            loss = ce(logits, yb)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(base.parameters(), 1.0)
            opt.step()

            total_loss += loss.item()
            total_acc += (logits.argmax(dim=-1) == yb).float().mean().item()

        print(f"Base epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} | acc {total_acc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s")

def train_direct_head(base: BaseKnowledgeProvider, direct: DirectStaticBaseline, epochs: int, steps_per_epoch: int):
    direct.train()
    set_requires_grad(base, False)
    opt = torch.optim.AdamW(direct.parameters(), lr=LR_DIRECT, weight_decay=1e-4)
    ce = nn.CrossEntropyLoss()

    print("\n=== Stage 2: direct static baseline head (no online control) ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_acc = 0.0

        for _ in range(steps_per_epoch):
            level = random.choice(TRAIN_LEVELS)
            x, _, start_mode, _, start_ctrl, _, target = make_reasoning_batch(X_train, y_train, BATCH_SIZE, level=level)

            with torch.no_grad():
                k0 = base.encode(x)

            logits = direct(k0, start_ctrl)
            loss = ce(logits, target)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(direct.parameters(), 1.0)
            opt.step()

            total_loss += loss.item()
            total_acc += (logits.argmax(dim=-1) == target).float().mean().item()

        print(f"Direct epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} | acc {total_acc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s")

def train_reasoner_continue_only(base: BaseKnowledgeProvider, reasoner: MCLTRReasoner, epochs: int, steps_per_epoch: int):
    reasoner.train()
    set_requires_grad(base, False)
    set_requires_grad(reasoner.init_net, True)
    set_requires_grad(reasoner.trans_net, True)
    set_requires_grad(reasoner.context_net, False)
    set_requires_grad(reasoner.evaluator, False)
    set_requires_grad(reasoner.decoder, True)
    set_requires_grad(reasoner.z_norm, True)
    set_requires_grad(reasoner.ctx_norm, False)

    params = list(reasoner.init_net.parameters()) + list(reasoner.trans_net.parameters()) + list(reasoner.decoder.parameters()) + list(reasoner.z_norm.parameters())
    opt = torch.optim.AdamW(params, lr=LR_REASONER, weight_decay=1e-4)
    ce = nn.CrossEntropyLoss()

    print("\n=== Stage 3: reasoner pretraining (continue-only rollouts, mixed levels) ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_acc = 0.0

        for _ in range(steps_per_epoch):
            level = random.choice(TRAIN_LEVELS)
            x, _, start_mode, _, start_ctrl, ctrl_seq, target = make_reasoning_batch(X_train, y_train, BATCH_SIZE, level=level)

            with torch.no_grad():
                k0 = base.encode(x)

            z = reasoner.init_state(k0, start_ctrl)
            for t in range(T):
                z = reasoner.step_update(z, k0, ctrl_seq[:, t, :], t)

            logits = reasoner.decode(z)
            loss = ce(logits, target)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(params, 1.0)
            opt.step()

            total_loss += loss.item()
            total_acc += (logits.argmax(dim=-1) == target).float().mean().item()

        print(f"Reasoner epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} | acc {total_acc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s")

def train_evaluator(base: BaseKnowledgeProvider, reasoner: MCLTRReasoner, epochs: int, steps_per_epoch: int):
    reasoner.eval()
    set_requires_grad(base, False)
    set_requires_grad(reasoner.init_net, False)
    set_requires_grad(reasoner.trans_net, False)
    set_requires_grad(reasoner.context_net, False)
    set_requires_grad(reasoner.decoder, False)
    set_requires_grad(reasoner.z_norm, False)
    set_requires_grad(reasoner.ctx_norm, False)
    set_requires_grad(reasoner.evaluator, True)

    opt = torch.optim.AdamW(reasoner.evaluator.parameters(), lr=LR_EVAL, weight_decay=1e-4)
    mse = nn.MSELoss()

    print("\n=== Stage 4: evaluator training (predict final correctness probability) ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_binacc = 0.0

        for _ in range(steps_per_epoch):
            level = random.choice([0, 1, 2, 3, 4])
            x, _, start_mode, _, start_ctrl, ctrl_seq, target = make_reasoning_batch(X_train, y_train, BATCH_SIZE, level=level)

            with torch.no_grad():
                k0 = base.encode(x)
                z = reasoner.init_state(k0, start_ctrl)

                step_z, step_k0, step_ctrl, step_t, labels = [], [], [], [], []

                for t in range(T):
                    cand = reasoner.step_update(z, k0, ctrl_seq[:, t, :], t)
                    p_target = final_target_prob_from_state(reasoner, cand, k0, ctrl_seq, t + 1, target, level)

                    step_z.append(cand.detach())
                    step_k0.append(k0.detach())
                    step_ctrl.append(ctrl_seq[:, t, :].detach())
                    step_t.append(step_feature(t, BATCH_SIZE, DEVICE))
                    labels.append(p_target.detach())

                    z = cand

                step_z = torch.cat(step_z, dim=0)
                step_k0 = torch.cat(step_k0, dim=0)
                step_ctrl = torch.cat(step_ctrl, dim=0)
                step_t = torch.cat(step_t, dim=0)
                labels = torch.cat(labels, dim=0).clamp(0.0, 1.0)

            inp = torch.cat([step_z, step_k0, step_ctrl, step_t], dim=-1)
            pred = torch.sigmoid(reasoner.evaluator(inp)).squeeze(-1)
            loss = mse(pred, labels)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(reasoner.evaluator.parameters(), 1.0)
            opt.step()

            total_loss += loss.item()
            total_binacc += ((pred > 0.5) == (labels > 0.5)).float().mean().item()

        print(f"Evaluator epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} | bin-acc {total_binacc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s")

# -----------------------------
# Evaluation
# -----------------------------
@torch.no_grad()
def rollout_reasoner(
    reasoner: MCLTRReasoner,
    k0: torch.Tensor,
    start_ctrl: torch.Tensor,
    ctrl_seq: torch.Tensor,
    target: Optional[torch.Tensor],
    level: int,
    mode: str,
    overwrite_spec: Optional[Tuple] = None,
    zero_k0: bool = False,
):
    if zero_k0:
        k0 = torch.zeros_like(k0)

    z0 = reasoner.init_state(k0, start_ctrl)
    z = z0
    spec = get_level_spec(level)
    actions, step_probs = [], []

    for t in range(T):
        cand = reasoner.step_update(z, k0, ctrl_seq[:, t, :], t)

        if spec["corrupt_step"] is not None and t == spec["corrupt_step"]:
            cand = inject_mistake(cand, spec["corrupt_severity"])

        if mode == "continue":
            action = torch.zeros(k0.size(0), dtype=torch.long, device=k0.device)
            z_next = cand

        elif mode == "restart":
            action = torch.full((k0.size(0),), 2, dtype=torch.long, device=k0.device)
            z_next = z0

        elif mode == "overwrite":
            if overwrite_spec is None:
                raise ValueError("overwrite_spec is required for overwrite mode")
            action = torch.ones(k0.size(0), dtype=torch.long, device=k0.device)
            z_next = apply_overwrite(reasoner, cand, z0, k0, ctrl_seq[:, t, :], t, overwrite_spec)

        elif mode == "oracle":
            if overwrite_spec is None or target is None:
                raise ValueError("oracle mode requires overwrite_spec and target")
            action, probs = choose_oracle_action(reasoner, cand, z0, k0, ctrl_seq, t, target, overwrite_spec, level)
            z_next = torch.empty_like(cand)

            cont_mask = action == 0
            over_mask = action == 1
            rest_mask = action == 2

            if cont_mask.any():
                z_next[cont_mask] = cand[cont_mask]
            if over_mask.any():
                z_next[over_mask] = apply_overwrite(
                    reasoner, cand[over_mask], z0[over_mask], k0[over_mask], ctrl_seq[over_mask, t, :], t, overwrite_spec
                )
            if rest_mask.any():
                z_next[rest_mask] = z0[rest_mask]

            step_probs.append(probs)

        else:
            raise ValueError(f"Unknown mode: {mode}")

        actions.append(action)
        z = z_next

    logits = reasoner.decode(z)
    pred = logits.argmax(dim=-1)
    final_ctrl = ctrl_seq[:, -1, :]
    final_eval = reasoner.eval_score(z, k0, final_ctrl, T - 1)

    out = {
        "logits": logits,
        "pred": pred,
        "actions": torch.stack(actions, dim=1),
        "final_eval": final_eval,
        "z0": z0,
    }
    if mode == "oracle":
        out["step_probs"] = torch.stack(step_probs, dim=1)
    return out

@torch.no_grad()
def eval_base_classifier(base: BaseKnowledgeProvider, batches: int = 12, bs: int = 256):
    base.eval()
    total = 0
    correct = 0
    for _ in range(batches):
        idx = sample_indices(X_test.size(0), bs)
        xb = X_test[idx]
        yb = y_test[idx]
        logits = base(xb)
        pred = logits.argmax(dim=-1)
        correct += (pred == yb).sum().item()
        total += yb.numel()
    return correct / total

@torch.no_grad()
def eval_direct_baseline(base: BaseKnowledgeProvider, direct: DirectStaticBaseline, level: int, batches: int = 12, bs: int = 256):
    direct.eval()
    base.eval()
    total = 0
    correct = 0
    for _ in range(batches):
        x, _, start_mode, _, start_ctrl, _, target = make_reasoning_batch(X_test, y_test, bs, level=level)
        k0 = base.encode(x)
        logits = direct(k0, start_ctrl)
        pred = logits.argmax(dim=-1)
        correct += (pred == target).sum().item()
        total += target.numel()
    return correct / total

@torch.no_grad()
def eval_rollout_mode(
    base: BaseKnowledgeProvider,
    reasoner: MCLTRReasoner,
    level: int,
    mode: str,
    overwrite_spec: Tuple,
    zero_k0: bool,
    batches: int = 12,
    bs: int = 256,
):
    base.eval()
    reasoner.eval()

    total = 0
    correct = 0
    action_counts = torch.zeros(3, device=DEVICE)
    score_correct = []
    score_incorrect = []

    for _ in range(batches):
        x, _, start_mode, _, start_ctrl, ctrl_seq, target = make_reasoning_batch(X_test, y_test, bs, level=level)
        k0 = base.encode(x)

        out = rollout_reasoner(
            reasoner,
            k0,
            start_ctrl,
            ctrl_seq,
            target=target if mode == "oracle" else None,
            level=level,
            mode=mode,
            overwrite_spec=overwrite_spec,
            zero_k0=zero_k0,
        )

        pred = out["pred"]
        correct_mask = pred == target
        correct += correct_mask.sum().item()
        total += target.numel()

        if mode == "oracle":
            action_counts += torch.stack([
                (out["actions"] == 0).sum(),
                (out["actions"] == 1).sum(),
                (out["actions"] == 2).sum(),
            ]).float()

        score = out["final_eval"]
        if correct_mask.any():
            score_correct.append(score[correct_mask].mean().item())
        if (~correct_mask).any():
            score_incorrect.append(score[~correct_mask].mean().item())

    result = {
        "acc": correct / total,
        "score_correct_mean": float(np.mean(score_correct)) if len(score_correct) else float("nan"),
        "score_incorrect_mean": float(np.mean(score_incorrect)) if len(score_incorrect) else float("nan"),
    }

    if mode == "oracle":
        rates = (action_counts / (batches * bs * T)).detach().cpu().numpy()
        result["continue_rate"] = float(rates[0])
        result["overwrite_rate"] = float(rates[1])
        result["restart_rate"] = float(rates[2])

    return result

@torch.no_grad()
def probe_actions(
    base: BaseKnowledgeProvider,
    reasoner: MCLTRReasoner,
    level: int,
    overwrite_spec: Tuple,
    zero_k0: bool,
    batches: int = 4,
    bs: int = 128,
):
    base.eval()
    reasoner.eval()

    best_counts = torch.zeros(T, 3, device=DEVICE)
    mean_probs = torch.zeros(T, 3, device=DEVICE)
    gain_over_continue = torch.zeros(T, device=DEVICE)
    gain_restart_over_continue = torch.zeros(T, device=DEVICE)

    for _ in range(batches):
        x, _, start_mode, _, start_ctrl, ctrl_seq, target = make_reasoning_batch(X_test, y_test, bs, level=level)
        k0 = base.encode(x)
        if zero_k0:
            k0 = torch.zeros_like(k0)

        z0 = reasoner.init_state(k0, start_ctrl)
        z = z0
        spec = get_level_spec(level)

        for t in range(T):
            cand = reasoner.step_update(z, k0, ctrl_seq[:, t, :], t)
            if spec["corrupt_step"] is not None and t == spec["corrupt_step"]:
                cand = inject_mistake(cand, spec["corrupt_severity"])

            cont_state = cand
            over_state = apply_overwrite(reasoner, cand, z0, k0, ctrl_seq[:, t, :], t, overwrite_spec)
            rest_state = z0

            p_cont = final_target_prob_from_state(reasoner, cont_state, k0, ctrl_seq, t + 1, target, level)
            p_over = final_target_prob_from_state(reasoner, over_state, k0, ctrl_seq, t + 1, target, level)
            p_rest = final_target_prob_from_state(reasoner, rest_state, k0, ctrl_seq, t + 1, target, level)

            probs = torch.stack([p_cont, p_over, p_rest], dim=-1)
            best = probs.argmax(dim=-1)

            for a in range(3):
                best_counts[t, a] += (best == a).sum()

            mean_probs[t, 0] += p_cont.sum()
            mean_probs[t, 1] += p_over.sum()
            mean_probs[t, 2] += p_rest.sum()

            gain_over_continue[t] += (p_over - p_cont).sum()
            gain_restart_over_continue[t] += (p_rest - p_cont).sum()

            z = cand

    denom = batches * bs
    return {
        "mean_probs": (mean_probs / denom).cpu().numpy(),
        "best_rates": (best_counts / denom).cpu().numpy(),
        "gain_over_continue": (gain_over_continue / denom).cpu().numpy(),
        "gain_restart_over_continue": (gain_restart_over_continue / denom).cpu().numpy(),
    }

def print_probe_summary(probe: Dict, level: int, overwrite_spec: Tuple, zero_k0: bool):
    zk = "zero-k0" if zero_k0 else "normal-k0"
    print(f"\n--- Action probe: level {level} ({level_name(level)}), spec={spec_to_str(overwrite_spec)}, {zk} ---")
    for t in range(T):
        mp = probe["mean_probs"][t]
        br = probe["best_rates"][t]
        g_over = probe["gain_over_continue"][t]
        g_rest = probe["gain_restart_over_continue"][t]
        print(
            f"step {t}: mean p(cont/over/rest)=({mp[0]:.3f}, {mp[1]:.3f}, {mp[2]:.3f}) | "
            f"best rates=({br[0]:.3f}, {br[1]:.3f}, {br[2]:.3f}) | "
            f"Δover-cont={g_over:+.4f} | Δrestart-cont={g_rest:+.4f}"
        )

# -----------------------------
# One run
# -----------------------------
def run_one_seed_and_base_strength(seed: int, base_epochs: int):
    set_seed(seed)
    print("\n\n##############################")
    print(f"Seed = {seed} | base_epochs = {base_epochs}")
    print("##############################")

    base = BaseKnowledgeProvider().to(DEVICE)
    direct = DirectStaticBaseline().to(DEVICE)
    reasoner = MCLTRReasoner(base).to(DEVICE)

    # Stage 1
    train_base(base, base_epochs, BASE_STEPS_PER_EPOCH)

    # Freeze base and share it
    frozen_base = copy.deepcopy(base).to(DEVICE)
    set_requires_grad(frozen_base, False)
    direct.base = frozen_base
    reasoner.base = frozen_base

    # Stage 2
    train_direct_head(frozen_base, direct, epochs=3, steps_per_epoch=DIRECT_STEPS_PER_EPOCH)

    # Stage 3
    train_reasoner_continue_only(frozen_base, reasoner, epochs=4, steps_per_epoch=REASONER_STEPS_PER_EPOCH)

    # Stage 4
    train_evaluator(frozen_base, reasoner, epochs=2, steps_per_epoch=EVAL_STEPS_PER_EPOCH)

    base_acc = eval_base_classifier(frozen_base, batches=12, bs=256)

    results = {}
    for level in EVAL_LEVELS:
        results[level] = {}

        direct_acc = eval_direct_baseline(frozen_base, direct, level=level, batches=12, bs=256)
        cont_normal = eval_rollout_mode(
            frozen_base, reasoner, level=level, mode="continue",
            overwrite_spec=OVERWRITE_SPECS[0], zero_k0=False,
            batches=12, bs=256
        )
        cont_zero = eval_rollout_mode(
            frozen_base, reasoner, level=level, mode="continue",
            overwrite_spec=OVERWRITE_SPECS[0], zero_k0=True,
            batches=12, bs=256
        )

        results[level]["base_acc"] = base_acc
        results[level]["direct_acc"] = direct_acc
        results[level]["continue_normal"] = cont_normal["acc"]
        results[level]["continue_zero"] = cont_zero["acc"]

        print(f"\n--- Seed {seed} | base_epochs {base_epochs} | Level {level} ({level_name(level)}) ---")
        print(f"Base classifier (digit ID only)      : {base_acc:.4f}")
        print(f"Direct static baseline              : {direct_acc:.4f}")
        print(f"M-CLTR continue-only (normal k0)    : {cont_normal['acc']:.4f}")
        print(f"M-CLTR continue-only (zero k0)      : {cont_zero['acc']:.4f}")
        print(f"Zero-knowledge gap                  : {cont_normal['acc'] - cont_zero['acc']:+.4f}")

        for spec in OVERWRITE_SPECS:
            overwrite_res = eval_rollout_mode(
                frozen_base, reasoner, level=level, mode="overwrite",
                overwrite_spec=spec, zero_k0=False,
                batches=12, bs=256
            )
            restart_res = eval_rollout_mode(
                frozen_base, reasoner, level=level, mode="restart",
                overwrite_spec=spec, zero_k0=False,
                batches=12, bs=256
            )
            oracle_res = eval_rollout_mode(
                frozen_base, reasoner, level=level, mode="oracle",
                overwrite_spec=spec, zero_k0=False,
                batches=12, bs=256
            )

            probe = probe_actions(
                frozen_base, reasoner, level=level, overwrite_spec=spec, zero_k0=False,
                batches=4, bs=128
            )
            probe_zero = probe_actions(
                frozen_base, reasoner, level=level, overwrite_spec=spec, zero_k0=True,
                batches=4, bs=128
            )

            key = spec_to_str(spec)
            results[level][key] = {
                "overwrite_acc": overwrite_res["acc"],
                "restart_acc": restart_res["acc"],
                "oracle_acc": oracle_res["acc"],
                "oracle_c": oracle_res["continue_rate"],
                "oracle_o": oracle_res["overwrite_rate"],
                "oracle_r": oracle_res["restart_rate"],
                "probe": probe,
                "probe_zero": probe_zero,
            }

            print(f"\n  Overwrite spec = {key}")
            print(f"    Forced overwrite acc          : {overwrite_res['acc']:.4f}")
            print(f"    Forced restart acc            : {restart_res['acc']:.4f}")
            print(f"    Step-wise oracle acc          : {oracle_res['acc']:.4f}")
            print(f"    Oracle action rates C/O/R     : {oracle_res['continue_rate']:.3f}/{oracle_res['overwrite_rate']:.3f}/{oracle_res['restart_rate']:.3f}")
            print_probe_summary(probe, level, spec, zero_k0=False)
            print_probe_summary(probe_zero, level, spec, zero_k0=True)

    return results

# -----------------------------
# Run sweep
# -----------------------------
all_results = {}
for base_epochs in BASE_EPOCH_SWEEP:
    all_results[base_epochs] = {}
    for seed in SEEDS:
        all_results[base_epochs][seed] = run_one_seed_and_base_strength(seed, base_epochs)

# -----------------------------
# Aggregate summary
# -----------------------------
print("\n\n==============================")
print("Phase 6 aggregate summary")
print("==============================")

for base_epochs in BASE_EPOCH_SWEEP:
    print(f"\n################################")
    print(f"Base epochs = {base_epochs}")
    print(f"################################")

    for level in EVAL_LEVELS:
        base_vals, direct_vals, cont_vals, cont_zero_vals = [], [], [], []
        spec_summaries = {
            spec_to_str(spec): {
                "over": [], "rest": [], "oracle": [],
                "orc": [], "oro": [], "orr": [],
                "probe_over": [], "probe_rest": [],
                "probe_best_over": [], "probe_best_rest": [],
                "probe_over_zero": [], "probe_rest_zero": [],
            } for spec in OVERWRITE_SPECS
        }

        for seed in SEEDS:
            rr = all_results[base_epochs][seed][level]
            base_vals.append(rr["base_acc"])
            direct_vals.append(rr["direct_acc"])
            cont_vals.append(rr["continue_normal"])
            cont_zero_vals.append(rr["continue_zero"])

            for spec in OVERWRITE_SPECS:
                key = spec_to_str(spec)
                r = rr[key]
                spec_summaries[key]["over"].append(r["overwrite_acc"])
                spec_summaries[key]["rest"].append(r["restart_acc"])
                spec_summaries[key]["oracle"].append(r["oracle_acc"])
                spec_summaries[key]["orc"].append(r["oracle_c"])
                spec_summaries[key]["oro"].append(r["oracle_o"])
                spec_summaries[key]["orr"].append(r["oracle_r"])
                spec_summaries[key]["probe_over"].append(float(r["probe"]["gain_over_continue"].mean()))
                spec_summaries[key]["probe_rest"].append(float(r["probe"]["gain_restart_over_continue"].mean()))
                spec_summaries[key]["probe_best_over"].append(float(r["probe"]["best_rates"][:, 1].mean()))
                spec_summaries[key]["probe_best_rest"].append(float(r["probe"]["best_rates"][:, 2].mean()))
                spec_summaries[key]["probe_over_zero"].append(float(r["probe_zero"]["gain_over_continue"].mean()))
                spec_summaries[key]["probe_rest_zero"].append(float(r["probe_zero"]["gain_restart_over_continue"].mean()))

        bm, bs = mean_std(base_vals)
        dm, ds = mean_std(direct_vals)
        cm, cs = mean_std(cont_vals)
        czm, czs = mean_std(cont_zero_vals)

        print(f"\nLevel {level} ({level_name(level)})")
        print(f"  Base classifier              : {bm:.4f} ± {bs:.4f}")
        print(f"  Direct static baseline       : {dm:.4f} ± {ds:.4f}")
        print(f"  Continue-only (normal k0)    : {cm:.4f} ± {cs:.4f}")
        print(f"  Continue-only (zero k0)      : {czm:.4f} ± {czs:.4f}")
        print(f"  Zero-knowledge gap           : {(cm - czm):+.4f}")

        for spec in OVERWRITE_SPECS:
            key = spec_to_str(spec)
            om, os = mean_std(spec_summaries[key]["over"])
            rm, rs = mean_std(spec_summaries[key]["rest"])
            qm, qs = mean_std(spec_summaries[key]["oracle"])
            orc_m, orc_s = mean_std(spec_summaries[key]["orc"])
            oro_m, oro_s = mean_std(spec_summaries[key]["oro"])
            orr_m, orr_s = mean_std(spec_summaries[key]["orr"])
            go_m, go_s = mean_std(spec_summaries[key]["probe_over"])
            gr_m, gr_s = mean_std(spec_summaries[key]["probe_rest"])
            bo_m, bo_s = mean_std(spec_summaries[key]["probe_best_over"])
            br_m, br_s = mean_std(spec_summaries[key]["probe_best_rest"])
            goz_m, goz_s = mean_std(spec_summaries[key]["probe_over_zero"])
            grz_m, grz_s = mean_std(spec_summaries[key]["probe_rest_zero"])

            print(f"\n  Overwrite spec = {key}")
            print(f"    Forced overwrite acc        : {om:.4f} ± {os:.4f}")
            print(f"    Forced restart acc          : {rm:.4f} ± {rs:.4f}")
            print(f"    Step-wise oracle acc        : {qm:.4f} ± {qs:.4f}")
            print(f"    Oracle action rates C/O/R   : {orc_m:.3f} ± {orc_s:.3f} / {oro_m:.3f} ± {oro_s:.3f} / {orr_m:.3f} ± {orr_s:.3f}")
            print(f"    Probe mean Δ(over-cont)     : {go_m:+.4f} ± {go_s:.4f}")
            print(f"    Probe mean Δ(rest-cont)     : {gr_m:+.4f} ± {gr_s:.4f}")
            print(f"    Probe best-action overwrite : {bo_m:.3f} ± {bo_s:.3f}")
            print(f"    Probe best-action restart   : {br_m:.3f} ± {br_s:.3f}")
            print(f"    Zero-k Δ(over-cont)         : {goz_m:+.4f} ± {goz_s:.4f}")
            print(f"    Zero-k Δ(rest-cont)         : {grz_m:+.4f} ± {grz_s:.4f}")

print("\nDone.")

# M-CLTR Phase 7 — rule-switch modular arithmetic with policy imitation
# Self-contained, corrected version.

import copy
import math
import random
import time
from typing import Dict, Optional, Tuple

import numpy as np
import torch
import torch.nn as nn
import torch.nn.functional as F

# -----------------------------
# Device / reproducibility
# -----------------------------
DEVICE = torch.device("cuda" if torch.cuda.is_available() else "cpu")
print("Device:", DEVICE)

def set_seed(seed: int) -> None:
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    if torch.cuda.is_available():
        torch.cuda.manual_seed_all(seed)

# -----------------------------
# Config
# -----------------------------
NUM_VALUES = 10
NUM_CLASSES = 10
OP_DIM = 2

SEQ_LEN = 6
T = SEQ_LEN

X_DIM = SEQ_LEN * (NUM_VALUES + OP_DIM)
K_DIM = 64
Z_DIM = 96

SEEDS = [7]
BASE_EPOCH_SWEEP = [1, 4]

BATCH_SIZE = 128
BASE_STEPS_PER_EPOCH = 16
DIRECT_STEPS_PER_EPOCH = 16
REASONER_STEPS_PER_EPOCH = 16
EVAL_STEPS_PER_EPOCH = 12
POLICY_STEPS_PER_EPOCH = 12

LR_BASE = 2e-3
LR_DIRECT = 2e-3
LR_REASONER = 2e-3
LR_EVAL = 2e-3
LR_POLICY = 2e-3

TRAIN_LEVELS = [0, 1, 2]
EVAL_LEVELS = [3, 4]

LEVEL_SPECS = {
    0: {"name": "easy / no switch",        "switch_step": T,      "input_noise": 0.00, "corrupt_step": None, "corrupt_severity": 0.00},
    1: {"name": "medium / mid switch",     "switch_step": T // 2, "input_noise": 0.00, "corrupt_step": None, "corrupt_severity": 0.00},
    2: {"name": "hard / early switch",     "switch_step": 1,      "input_noise": 0.00, "corrupt_step": None, "corrupt_severity": 0.00},
    3: {"name": "switch + latent mistake", "switch_step": T // 2, "input_noise": 0.00, "corrupt_step": 2,    "corrupt_severity": 0.35},
    4: {"name": "switch + noise + mistake","switch_step": 1,      "input_noise": 0.15, "corrupt_step": 1,    "corrupt_severity": 0.45},
}

OVERWRITE_SPECS = [
    ("project", 6.0),
    ("gated_project", (0.25, 0.95)),
    ("adaptive_project", (0.20, 0.90)),
]

# -----------------------------
# Helpers
# -----------------------------
def one_hot(v: torch.Tensor, n: int) -> torch.Tensor:
    return F.one_hot(v.long(), n).float()

def step_feature(t: int, batch_size: int, device: torch.device) -> torch.Tensor:
    s = 0.0 if T <= 1 else float(t) / float(T - 1)
    return torch.full((batch_size, 1), s, device=device)

def mean_std(values):
    arr = np.asarray(values, dtype=np.float64)
    if arr.size == 1:
        return float(arr.item()), 0.0
    return float(arr.mean()), float(arr.std(ddof=1))

def sample_indices(n: int, batch_size: int) -> torch.Tensor:
    return torch.randint(0, n, (batch_size,), device=DEVICE)

def get_level_spec(level: int) -> Dict:
    return LEVEL_SPECS[level]

def level_name(level: int) -> str:
    return LEVEL_SPECS[level]["name"]

def spec_to_str(spec: Tuple):
    kind, arg = spec
    if kind == "project":
        return f"project(max_shift={float(arg):.1f})"
    if kind == "gated_project":
        lo, hi = arg
        return f"gated_project({lo:.2f},{hi:.2f})"
    if kind == "adaptive_project":
        lo, hi = arg
        return f"adaptive_project({lo:.2f},{hi:.2f})"
    return f"{kind}({arg})"

def inject_mistake(z: torch.Tensor, severity: float) -> torch.Tensor:
    if severity <= 0:
        return z
    rolled = torch.roll(z, shifts=1, dims=-1)
    mixed = (1.0 - severity) * z + severity * rolled
    mixed = mixed + (0.50 * severity) * torch.randn_like(z)
    return mixed

def set_requires_grad(module: nn.Module, flag: bool):
    for p in module.parameters():
        p.requires_grad = flag

def encode_problem(nums: torch.Tensor, mode_seq: torch.Tensor) -> torch.Tensor:
    nums_oh = one_hot(nums, NUM_VALUES)
    mode_oh = one_hot(mode_seq, OP_DIM)
    x = torch.cat([nums_oh, mode_oh], dim=-1)
    return x.reshape(x.size(0), -1)

def current_step_input(nums: torch.Tensor, mode_seq: torch.Tensor, t: int) -> torch.Tensor:
    return torch.cat([one_hot(nums[:, t], NUM_VALUES), one_hot(mode_seq[:, t], OP_DIM)], dim=-1)

def task_value(nums: torch.Tensor, mode_seq: torch.Tensor) -> torch.Tensor:
    acc = nums[:, 0]
    for t in range(1, T):
        mode = mode_seq[:, t]
        add = (acc + nums[:, t]) % NUM_VALUES
        mul = (acc * nums[:, t]) % NUM_VALUES
        acc = torch.where(mode == 0, add, mul)
    return acc.long()

def make_reasoning_batch(batch_size: int, level: int):
    spec = get_level_spec(level)
    nums = torch.randint(0, NUM_VALUES, (batch_size, T), device=DEVICE)
    start_mode = torch.randint(0, 2, (batch_size,), device=DEVICE)

    switch_step = spec["switch_step"]
    end_mode = start_mode.clone() if switch_step >= T else (1 - start_mode)

    t_ids = torch.arange(T, device=DEVICE).unsqueeze(0).expand(batch_size, T)
    mode_seq = torch.where(t_ids < switch_step, start_mode.unsqueeze(1), end_mode.unsqueeze(1))

    target = task_value(nums, mode_seq)
    x = encode_problem(nums, mode_seq)
    start_ctrl = one_hot(start_mode, OP_DIM)
    ctrl_seq = one_hot(mode_seq, OP_DIM)
    return nums, mode_seq, x, start_ctrl, ctrl_seq, target

def batched_entropy(logits: torch.Tensor) -> torch.Tensor:
    probs = F.softmax(logits, dim=-1)
    ent = -(probs * (probs.clamp_min(1e-8).log())).sum(dim=-1)
    return ent / math.log(probs.size(-1))

# -----------------------------
# Models
# -----------------------------
class MLP(nn.Module):
    def __init__(self, in_dim: int, out_dim: int, hidden: int = 128):
        super().__init__()
        self.net = nn.Sequential(
            nn.Linear(in_dim, hidden),
            nn.GELU(),
            nn.Linear(hidden, hidden),
            nn.GELU(),
            nn.Linear(hidden, out_dim),
        )

    def forward(self, x):
        return self.net(x)

class BaseKnowledgeProvider(nn.Module):
    def __init__(self, x_dim: int = X_DIM, k_dim: int = K_DIM):
        super().__init__()
        self.encoder = nn.Sequential(
            nn.Linear(x_dim, 128),
            nn.GELU(),
            nn.Linear(128, k_dim),
            nn.LayerNorm(k_dim),
        )
        self.classifier = nn.Sequential(
            nn.Linear(k_dim, 64),
            nn.GELU(),
            nn.Linear(64, NUM_CLASSES),
        )
        for m in self.modules():
            if isinstance(m, nn.Linear):
                nn.init.xavier_uniform_(m.weight)
                if m.bias is not None:
                    nn.init.zeros_(m.bias)

    def encode(self, x: torch.Tensor) -> torch.Tensor:
        return self.encoder(x)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.classifier(self.encode(x))

class DirectStaticBaseline(nn.Module):
    def __init__(self, k_dim: int = K_DIM):
        super().__init__()
        self.head = MLP(k_dim + OP_DIM, NUM_CLASSES, hidden=96)
        for m in self.modules():
            if isinstance(m, nn.Linear):
                nn.init.xavier_uniform_(m.weight)
                if m.bias is not None:
                    nn.init.zeros_(m.bias)

    def forward(self, k0: torch.Tensor, start_ctrl: torch.Tensor) -> torch.Tensor:
        return self.head(torch.cat([k0, start_ctrl], dim=-1))

class MCLTRReasoner(nn.Module):
    def __init__(self, base: BaseKnowledgeProvider, k_dim: int = K_DIM, z_dim: int = Z_DIM):
        super().__init__()
        self.base = base
        self.k_dim = k_dim
        self.z_dim = z_dim

        step_input_dim = NUM_VALUES + OP_DIM + 1
        self.init_net = MLP(k_dim + OP_DIM, z_dim, hidden=128)
        self.trans_net = MLP(z_dim + k_dim + step_input_dim, z_dim, hidden=128)
        self.evaluator = MLP(z_dim + k_dim + step_input_dim, 1, hidden=96)
        self.decoder = nn.Linear(z_dim, NUM_CLASSES)
        self.z_norm = nn.LayerNorm(z_dim)

        for m in self.modules():
            if isinstance(m, nn.Linear):
                nn.init.xavier_uniform_(m.weight)
                if m.bias is not None:
                    nn.init.zeros_(m.bias)

    def init_state(self, k0: torch.Tensor, start_ctrl: torch.Tensor) -> torch.Tensor:
        z0 = self.init_net(torch.cat([k0, start_ctrl], dim=-1))
        return self.z_norm(z0)

    def step_update(self, z: torch.Tensor, k0: torch.Tensor, step_inp: torch.Tensor, t: int) -> torch.Tensor:
        step = step_feature(t, z.size(0), z.device)
        inp = torch.cat([z, k0, step_inp, step], dim=-1)
        delta = torch.tanh(self.trans_net(inp))
        cand = self.z_norm(0.80 * z + 0.20 * delta)
        return cand

    def eval_score(self, z: torch.Tensor, k0: torch.Tensor, step_inp: torch.Tensor, t: int) -> torch.Tensor:
        step = step_feature(t, z.size(0), z.device)
        inp = torch.cat([z, k0, step_inp, step], dim=-1)
        return torch.sigmoid(self.evaluator(inp)).squeeze(-1)

    def decode(self, z: torch.Tensor) -> torch.Tensor:
        return self.decoder(z)

class PolicyNet(nn.Module):
    def __init__(self, in_dim: int, hidden: int = 192):
        super().__init__()
        self.net = nn.Sequential(
            nn.Linear(in_dim, hidden),
            nn.GELU(),
            nn.Linear(hidden, hidden),
            nn.GELU(),
            nn.Linear(hidden, 3),
        )
        for m in self.modules():
            if isinstance(m, nn.Linear):
                nn.init.xavier_uniform_(m.weight)
                if m.bias is not None:
                    nn.init.zeros_(m.bias)

    def forward(self, x):
        return self.net(x)

# -----------------------------
# Overwrite operators
# -----------------------------
def project_overwrite(cand: torch.Tensor, z0: torch.Tensor, max_shift: float) -> torch.Tensor:
    delta = cand - z0
    delta_norm = delta.norm(dim=-1, keepdim=True).clamp_min(1e-6)
    scale = torch.clamp(torch.full_like(delta_norm, max_shift) / delta_norm, max=1.0)
    return z0 + delta * scale

def gated_project_overwrite(
    cand: torch.Tensor,
    z0: torch.Tensor,
    score: torch.Tensor,
    lo: float,
    hi: float,
) -> torch.Tensor:
    mix = lo + (hi - lo) * score.unsqueeze(-1)
    return mix * cand + (1.0 - mix) * z0

def adaptive_project_overwrite(
    reasoner: MCLTRReasoner,
    cand: torch.Tensor,
    z0: torch.Tensor,
    k0: torch.Tensor,
    step_inp: torch.Tensor,
    t: int,
    lo: float,
    hi: float,
) -> torch.Tensor:
    score = reasoner.eval_score(cand, k0, step_inp, t).clamp(0.0, 1.0)
    step_bias = 0.85 - 0.20 * (t / max(1, T - 1))
    mix = (lo + (hi - lo) * score) * step_bias
    mix = mix.clamp(0.05, 0.95).unsqueeze(-1)
    blended = mix * cand + (1.0 - mix) * z0

    max_shift = (1.0 + 4.0 * score).unsqueeze(-1)
    delta = blended - z0
    delta_norm = delta.norm(dim=-1, keepdim=True).clamp_min(1e-6)
    scale = torch.clamp(max_shift / delta_norm, max=1.0)
    return z0 + delta * scale

def apply_overwrite(
    reasoner: MCLTRReasoner,
    cand: torch.Tensor,
    z0: torch.Tensor,
    k0: torch.Tensor,
    step_inp: torch.Tensor,
    t: int,
    spec: Tuple,
) -> torch.Tensor:
    kind, arg = spec
    if kind == "project":
        out = project_overwrite(cand, z0, float(arg))
        return reasoner.z_norm(out)
    if kind == "gated_project":
        lo, hi = arg
        score = reasoner.eval_score(cand, k0, step_inp, t)
        out = gated_project_overwrite(cand, z0, score, float(lo), float(hi))
        return reasoner.z_norm(out)
    if kind == "adaptive_project":
        lo, hi = arg
        out = adaptive_project_overwrite(reasoner, cand, z0, k0, step_inp, t, float(lo), float(hi))
        return reasoner.z_norm(out)
    raise ValueError(f"Unknown overwrite spec: {spec}")

# -----------------------------
# Rollout helpers
# -----------------------------
@torch.no_grad()
def continue_rollout_from_state(
    reasoner: MCLTRReasoner,
    z_start: torch.Tensor,
    k0: torch.Tensor,
    nums: torch.Tensor,
    mode_seq: torch.Tensor,
    start_t: int,
    level: int,
) -> torch.Tensor:
    spec = get_level_spec(level)
    z = z_start
    for t in range(start_t, T):
        step_inp = current_step_input(nums, mode_seq, t)
        z = reasoner.step_update(z, k0, step_inp, t)
        if spec["corrupt_step"] is not None and t == spec["corrupt_step"]:
            z = inject_mistake(z, spec["corrupt_severity"])
    return z

@torch.no_grad()
def final_target_prob_from_state(
    reasoner: MCLTRReasoner,
    z_start: torch.Tensor,
    k0: torch.Tensor,
    nums: torch.Tensor,
    mode_seq: torch.Tensor,
    start_t: int,
    target: torch.Tensor,
    level: int,
) -> torch.Tensor:
    z_final = continue_rollout_from_state(reasoner, z_start, k0, nums, mode_seq, start_t, level)
    logits = reasoner.decode(z_final)
    probs = F.softmax(logits, dim=-1)
    return probs.gather(1, target.unsqueeze(1)).squeeze(1)

@torch.no_grad()
def choose_oracle_action(
    reasoner: MCLTRReasoner,
    cand: torch.Tensor,
    z0: torch.Tensor,
    k0: torch.Tensor,
    nums: torch.Tensor,
    mode_seq: torch.Tensor,
    t: int,
    target: torch.Tensor,
    overwrite_spec: Tuple,
    level: int,
):
    step_inp = current_step_input(nums, mode_seq, t)
    cont_state = cand
    over_state = apply_overwrite(reasoner, cand, z0, k0, step_inp, t, overwrite_spec)
    rest_state = z0

    p_cont = final_target_prob_from_state(reasoner, cont_state, k0, nums, mode_seq, t + 1, target, level)
    p_over = final_target_prob_from_state(reasoner, over_state, k0, nums, mode_seq, t + 1, target, level)
    p_rest = final_target_prob_from_state(reasoner, rest_state, k0, nums, mode_seq, t + 1, target, level)

    probs = torch.stack([p_cont, p_over, p_rest], dim=-1)
    tie_bias = torch.tensor([2e-3, 1e-3, 0.0], device=probs.device).unsqueeze(0)
    action = (probs + tie_bias).argmax(dim=-1)
    return action, probs

def build_policy_features(
    reasoner: MCLTRReasoner,
    cand: torch.Tensor,
    z0: torch.Tensor,
    k0: torch.Tensor,
    nums: torch.Tensor,
    mode_seq: torch.Tensor,
    t: int,
    prev_score: Optional[torch.Tensor] = None,
) -> torch.Tensor:
    step_inp = current_step_input(nums, mode_seq, t)
    score = reasoner.eval_score(cand, k0, step_inp, t).unsqueeze(-1)
    if prev_score is None:
        delta = score.clone()
    else:
        delta = score - prev_score.unsqueeze(-1)

    logits = reasoner.decode(cand)
    entropy = batched_entropy(logits).unsqueeze(-1)
    cos = F.cosine_similarity(cand, z0, dim=-1, eps=1e-6).unsqueeze(-1)
    cand_norm = cand.norm(dim=-1, keepdim=True)
    z0_norm = z0.norm(dim=-1, keepdim=True)
    k0_norm = k0.norm(dim=-1, keepdim=True)
    step = step_feature(t, cand.size(0), cand.device)

    feat = torch.cat(
        [cand, z0, k0, step_inp, score, delta, entropy, cos, cand_norm, z0_norm, k0_norm, step],
        dim=-1,
    )
    return feat

# -----------------------------
# Training
# -----------------------------
def train_base(base: BaseKnowledgeProvider, epochs: int, steps_per_epoch: int):
    base.train()
    opt = torch.optim.AdamW(base.parameters(), lr=LR_BASE, weight_decay=1e-4)
    ce = nn.CrossEntropyLoss()

    print("\n=== Stage 1: base knowledge pretraining ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_acc = 0.0
        for _ in range(steps_per_epoch):
            level = random.choice(TRAIN_LEVELS)
            nums, mode_seq, x, start_ctrl, ctrl_seq, target = make_reasoning_batch(BATCH_SIZE, level)
            logits = base(x)
            loss = ce(logits, target)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(base.parameters(), 1.0)
            opt.step()

            total_loss += loss.item()
            total_acc += (logits.argmax(dim=-1) == target).float().mean().item()

        print(f"Base epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} | acc {total_acc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s")

def train_direct_head(base: BaseKnowledgeProvider, direct: DirectStaticBaseline, epochs: int, steps_per_epoch: int):
    direct.train()
    set_requires_grad(base, False)
    opt = torch.optim.AdamW(direct.parameters(), lr=LR_DIRECT, weight_decay=1e-4)
    ce = nn.CrossEntropyLoss()

    print("\n=== Stage 2: direct static baseline head ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_acc = 0.0
        for _ in range(steps_per_epoch):
            level = random.choice(TRAIN_LEVELS)
            nums, mode_seq, x, start_ctrl, ctrl_seq, target = make_reasoning_batch(BATCH_SIZE, level)

            with torch.no_grad():
                k0 = base.encode(x)

            logits = direct(k0, start_ctrl)
            loss = ce(logits, target)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(direct.parameters(), 1.0)
            opt.step()

            total_loss += loss.item()
            total_acc += (logits.argmax(dim=-1) == target).float().mean().item()

        print(f"Direct epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} | acc {total_acc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s")

def train_reasoner_continue_only(base: BaseKnowledgeProvider, reasoner: MCLTRReasoner, epochs: int, steps_per_epoch: int):
    reasoner.train()
    set_requires_grad(base, False)
    set_requires_grad(reasoner.init_net, True)
    set_requires_grad(reasoner.trans_net, True)
    set_requires_grad(reasoner.evaluator, False)
    set_requires_grad(reasoner.decoder, True)
    set_requires_grad(reasoner.z_norm, True)

    params = list(reasoner.init_net.parameters()) + list(reasoner.trans_net.parameters()) + list(reasoner.decoder.parameters()) + list(reasoner.z_norm.parameters())
    opt = torch.optim.AdamW(params, lr=LR_REASONER, weight_decay=1e-4)
    ce = nn.CrossEntropyLoss()

    print("\n=== Stage 3: reasoner pretraining (continue-only rollouts) ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_acc = 0.0
        for _ in range(steps_per_epoch):
            level = random.choice(TRAIN_LEVELS)
            nums, mode_seq, x, start_ctrl, ctrl_seq, target = make_reasoning_batch(BATCH_SIZE, level)

            with torch.no_grad():
                k0 = base.encode(x)

            z = reasoner.init_state(k0, start_ctrl)
            for t in range(T):
                step_inp = current_step_input(nums, mode_seq, t)
                z = reasoner.step_update(z, k0, step_inp, t)

            logits = reasoner.decode(z)
            loss = ce(logits, target)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(params, 1.0)
            opt.step()

            total_loss += loss.item()
            total_acc += (logits.argmax(dim=-1) == target).float().mean().item()

        print(f"Reasoner epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} | acc {total_acc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s")

def train_evaluator(base: BaseKnowledgeProvider, reasoner: MCLTRReasoner, epochs: int, steps_per_epoch: int):
    reasoner.eval()
    set_requires_grad(base, False)
    set_requires_grad(reasoner.init_net, False)
    set_requires_grad(reasoner.trans_net, False)
    set_requires_grad(reasoner.decoder, False)
    set_requires_grad(reasoner.z_norm, False)
    set_requires_grad(reasoner.evaluator, True)

    opt = torch.optim.AdamW(reasoner.evaluator.parameters(), lr=LR_EVAL, weight_decay=1e-4)
    mse = nn.MSELoss()

    print("\n=== Stage 4: evaluator training (predict final correctness probability) ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_binacc = 0.0

        for _ in range(steps_per_epoch):
            level = random.choice([0, 1, 2, 3, 4])
            nums, mode_seq, x, start_ctrl, ctrl_seq, target = make_reasoning_batch(BATCH_SIZE, level)

            with torch.no_grad():
                k0 = base.encode(x)
                z = reasoner.init_state(k0, start_ctrl)

                step_z, step_k0, step_inp_list, step_t_list, labels = [], [], [], [], []

                for t in range(T):
                    step_inp = current_step_input(nums, mode_seq, t)
                    cand = reasoner.step_update(z, k0, step_inp, t)
                    p_target = final_target_prob_from_state(reasoner, cand, k0, nums, mode_seq, t + 1, target, level)

                    step_z.append(cand.detach())
                    step_k0.append(k0.detach())
                    step_inp_list.append(step_inp.detach())
                    step_t_list.append(step_feature(t, BATCH_SIZE, DEVICE))
                    labels.append(p_target.detach())

                    z = cand

                step_z = torch.cat(step_z, dim=0)
                step_k0 = torch.cat(step_k0, dim=0)
                step_inp_all = torch.cat(step_inp_list, dim=0)
                step_t_all = torch.cat(step_t_list, dim=0)
                labels = torch.cat(labels, dim=0).clamp(0.0, 1.0)

            inp = torch.cat([step_z, step_k0, step_inp_all, step_t_all], dim=-1)
            pred = torch.sigmoid(reasoner.evaluator(inp)).squeeze(-1)
            loss = mse(pred, labels)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(reasoner.evaluator.parameters(), 1.0)
            opt.step()

            total_loss += loss.item()
            total_binacc += ((pred > 0.5) == (labels > 0.5)).float().mean().item()

        print(f"Evaluator epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} | bin-acc {total_binacc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s")

def train_policy_imitation(
    base: BaseKnowledgeProvider,
    reasoner: MCLTRReasoner,
    policy: PolicyNet,
    overwrite_spec: Tuple,
    epochs: int,
    steps_per_epoch: int,
):
    reasoner.eval()
    policy.train()
    set_requires_grad(base, False)
    set_requires_grad(reasoner.init_net, False)
    set_requires_grad(reasoner.trans_net, False)
    set_requires_grad(reasoner.decoder, False)
    set_requires_grad(reasoner.z_norm, False)
    set_requires_grad(reasoner.evaluator, False)
    set_requires_grad(policy, True)

    opt = torch.optim.AdamW(policy.parameters(), lr=LR_POLICY, weight_decay=1e-4)
    ce = nn.CrossEntropyLoss()

    print("\n=== Stage 5: policy imitation training ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_acc = 0.0

        for _ in range(steps_per_epoch):
            level = random.choice([0, 1, 2, 3, 4])
            nums, mode_seq, x, start_ctrl, ctrl_seq, target = make_reasoning_batch(BATCH_SIZE, level)

            with torch.no_grad():
                k0 = base.encode(x)
                z0 = reasoner.init_state(k0, start_ctrl)
                z = z0
                prev_score = None

                feats = []
                labels = []

                for t in range(T):
                    step_inp = current_step_input(nums, mode_seq, t)
                    cand = reasoner.step_update(z, k0, step_inp, t)

                    spec = get_level_spec(level)
                    if spec["corrupt_step"] is not None and t == spec["corrupt_step"]:
                        cand = inject_mistake(cand, spec["corrupt_severity"])

                    feat = build_policy_features(reasoner, cand, z0, k0, nums, mode_seq, t, prev_score=prev_score)
                    action, _ = choose_oracle_action(
                        reasoner=reasoner,
                        cand=cand,
                        z0=z0,
                        k0=k0,
                        nums=nums,
                        mode_seq=mode_seq,
                        t=t,
                        target=target,
                        overwrite_spec=overwrite_spec,
                        level=level,
                    )
                    feats.append(feat.detach())
                    labels.append(action.detach())

                    prev_score = reasoner.eval_score(cand, k0, step_inp, t).detach()
                    z = cand

                feats = torch.cat(feats, dim=0)
                labels = torch.cat(labels, dim=0)

            logits = policy(feats)
            loss = ce(logits, labels)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(policy.parameters(), 1.0)
            opt.step()

            total_loss += loss.item()
            total_acc += (logits.argmax(dim=-1) == labels).float().mean().item()

        print(f"Policy epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} | label-acc {total_acc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s")

# -----------------------------
# Evaluation
# -----------------------------
@torch.no_grad()
def rollout_reasoner(
    reasoner: MCLTRReasoner,
    k0: torch.Tensor,
    start_ctrl: torch.Tensor,
    nums: torch.Tensor,
    mode_seq: torch.Tensor,
    target: Optional[torch.Tensor],
    level: int,
    mode: str,
    overwrite_spec: Optional[Tuple] = None,
    zero_k0: bool = False,
    policy: Optional[PolicyNet] = None,
):
    if zero_k0:
        k0 = torch.zeros_like(k0)

    z0 = reasoner.init_state(k0, start_ctrl)
    z = z0
    spec = get_level_spec(level)
    actions, step_probs = [], []
    prev_score = None

    for t in range(T):
        step_inp = current_step_input(nums, mode_seq, t)
        cand = reasoner.step_update(z, k0, step_inp, t)

        if spec["corrupt_step"] is not None and t == spec["corrupt_step"]:
            cand = inject_mistake(cand, spec["corrupt_severity"])

        if mode == "continue":
            action = torch.zeros(k0.size(0), dtype=torch.long, device=k0.device)
            z_next = cand

        elif mode == "restart":
            action = torch.full((k0.size(0),), 2, dtype=torch.long, device=k0.device)
            z_next = z0

        elif mode == "overwrite":
            if overwrite_spec is None:
                raise ValueError("overwrite_spec is required for overwrite mode")
            action = torch.ones(k0.size(0), dtype=torch.long, device=k0.device)
            z_next = apply_overwrite(reasoner, cand, z0, k0, step_inp, t, overwrite_spec)

        elif mode == "oracle":
            if overwrite_spec is None or target is None:
                raise ValueError("oracle mode requires overwrite_spec and target")
            action, probs = choose_oracle_action(reasoner, cand, z0, k0, nums, mode_seq, t, target, overwrite_spec, level)
            z_next = torch.empty_like(cand)

            cont_mask = action == 0
            over_mask = action == 1
            rest_mask = action == 2

            if cont_mask.any():
                z_next[cont_mask] = cand[cont_mask]
            if over_mask.any():
                z_next[over_mask] = apply_overwrite(
                    reasoner, cand[over_mask], z0[over_mask], k0[over_mask], step_inp[over_mask], t, overwrite_spec
                )
            if rest_mask.any():
                z_next[rest_mask] = z0[rest_mask]

            step_probs.append(probs)

        elif mode == "policy":
            if policy is None:
                raise ValueError("policy model required for policy mode")
            feat = build_policy_features(reasoner, cand, z0, k0, nums, mode_seq, t, prev_score=prev_score)
            logits = policy(feat)
            action = logits.argmax(dim=-1)
            z_next = torch.empty_like(cand)

            cont_mask = action == 0
            over_mask = action == 1
            rest_mask = action == 2

            if cont_mask.any():
                z_next[cont_mask] = cand[cont_mask]
            if over_mask.any():
                z_next[over_mask] = apply_overwrite(
                    reasoner, cand[over_mask], z0[over_mask], k0[over_mask], step_inp[over_mask], t, overwrite_spec
                )
            if rest_mask.any():
                z_next[rest_mask] = z0[rest_mask]

            prev_score = reasoner.eval_score(cand, k0, step_inp, t)

        else:
            raise ValueError(f"Unknown mode: {mode}")

        actions.append(action)
        z = z_next

    logits = reasoner.decode(z)
    pred = logits.argmax(dim=-1)

    # FIXED: mode_seq is [B, T], so do not index as 3D.
    final_step_inp = current_step_input(nums, mode_seq, T - 1)
    final_eval = reasoner.eval_score(z, k0, final_step_inp, T - 1)

    out = {
        "logits": logits,
        "pred": pred,
        "actions": torch.stack(actions, dim=1),
        "final_eval": final_eval,
        "z0": z0,
    }
    if mode == "oracle":
        out["step_probs"] = torch.stack(step_probs, dim=1)
    return out

@torch.no_grad()
def eval_base_classifier(base: BaseKnowledgeProvider, batches: int = 10, bs: int = 256):
    base.eval()
    total = 0
    correct = 0
    for _ in range(batches):
        level = random.choice(TRAIN_LEVELS + EVAL_LEVELS)
        nums, mode_seq, x, start_ctrl, ctrl_seq, target = make_reasoning_batch(bs, level)
        logits = base(x)
        pred = logits.argmax(dim=-1)
        correct += (pred == target).sum().item()
        total += target.numel()
    return correct / total

@torch.no_grad()
def eval_direct_baseline(base: BaseKnowledgeProvider, direct: DirectStaticBaseline, level: int, batches: int = 10, bs: int = 256):
    direct.eval()
    base.eval()
    total = 0
    correct = 0
    for _ in range(batches):
        nums, mode_seq, x, start_ctrl, ctrl_seq, target = make_reasoning_batch(bs, level)
        k0 = base.encode(x)
        logits = direct(k0, start_ctrl)
        pred = logits.argmax(dim=-1)
        correct += (pred == target).sum().item()
        total += target.numel()
    return correct / total

@torch.no_grad()
def eval_rollout_mode(
    base: BaseKnowledgeProvider,
    reasoner: MCLTRReasoner,
    level: int,
    mode: str,
    overwrite_spec: Tuple,
    zero_k0: bool,
    batches: int = 10,
    bs: int = 256,
    policy: Optional[PolicyNet] = None,
):
    base.eval()
    reasoner.eval()
    if policy is not None:
        policy.eval()

    total = 0
    correct = 0
    action_counts = torch.zeros(3, device=DEVICE)
    score_correct = []
    score_incorrect = []

    for _ in range(batches):
        nums, mode_seq, x, start_ctrl, ctrl_seq, target = make_reasoning_batch(bs, level)
        k0 = base.encode(x)

        out = rollout_reasoner(
            reasoner,
            k0,
            start_ctrl,
            nums,
            mode_seq,
            target=target if mode in ("oracle",) else None,
            level=level,
            mode=mode,
            overwrite_spec=overwrite_spec,
            zero_k0=zero_k0,
            policy=policy,
        )

        pred = out["pred"]
        correct_mask = pred == target
        correct += correct_mask.sum().item()
        total += target.numel()

        if mode in ("oracle", "policy"):
            action_counts += torch.stack([
                (out["actions"] == 0).sum(),
                (out["actions"] == 1).sum(),
                (out["actions"] == 2).sum(),
            ]).float()

        score = out["final_eval"]
        if correct_mask.any():
            score_correct.append(score[correct_mask].mean().item())
        if (~correct_mask).any():
            score_incorrect.append(score[~correct_mask].mean().item())

    result = {
        "acc": correct / total,
        "score_correct_mean": float(np.mean(score_correct)) if len(score_correct) else float("nan"),
        "score_incorrect_mean": float(np.mean(score_incorrect)) if len(score_incorrect) else float("nan"),
    }

    if mode in ("oracle", "policy"):
        rates = (action_counts / (batches * bs * T)).detach().cpu().numpy()
        result["continue_rate"] = float(rates[0])
        result["overwrite_rate"] = float(rates[1])
        result["restart_rate"] = float(rates[2])

    return result

@torch.no_grad()
def probe_actions(
    base: BaseKnowledgeProvider,
    reasoner: MCLTRReasoner,
    level: int,
    overwrite_spec: Tuple,
    zero_k0: bool,
    batches: int = 4,
    bs: int = 128,
):
    base.eval()
    reasoner.eval()

    best_counts = torch.zeros(T, 3, device=DEVICE)
    mean_probs = torch.zeros(T, 3, device=DEVICE)
    gain_over_continue = torch.zeros(T, device=DEVICE)
    gain_restart_over_continue = torch.zeros(T, device=DEVICE)

    for _ in range(batches):
        nums, mode_seq, x, start_ctrl, ctrl_seq, target = make_reasoning_batch(bs, level)
        k0 = base.encode(x)
        if zero_k0:
            k0 = torch.zeros_like(k0)

        z0 = reasoner.init_state(k0, start_ctrl)
        z = z0
        spec = get_level_spec(level)

        for t in range(T):
            step_inp = current_step_input(nums, mode_seq, t)
            cand = reasoner.step_update(z, k0, step_inp, t)
            if spec["corrupt_step"] is not None and t == spec["corrupt_step"]:
                cand = inject_mistake(cand, spec["corrupt_severity"])

            cont_state = cand
            over_state = apply_overwrite(reasoner, cand, z0, k0, step_inp, t, overwrite_spec)
            rest_state = z0

            p_cont = final_target_prob_from_state(reasoner, cont_state, k0, nums, mode_seq, t + 1, target, level)
            p_over = final_target_prob_from_state(reasoner, over_state, k0, nums, mode_seq, t + 1, target, level)
            p_rest = final_target_prob_from_state(reasoner, rest_state, k0, nums, mode_seq, t + 1, target, level)

            probs = torch.stack([p_cont, p_over, p_rest], dim=-1)
            best = probs.argmax(dim=-1)

            for a in range(3):
                best_counts[t, a] += (best == a).sum()

            mean_probs[t, 0] += p_cont.sum()
            mean_probs[t, 1] += p_over.sum()
            mean_probs[t, 2] += p_rest.sum()

            gain_over_continue[t] += (p_over - p_cont).sum()
            gain_restart_over_continue[t] += (p_rest - p_cont).sum()

            z = cand

    denom = batches * bs
    return {
        "mean_probs": (mean_probs / denom).cpu().numpy(),
        "best_rates": (best_counts / denom).cpu().numpy(),
        "gain_over_continue": (gain_over_continue / denom).cpu().numpy(),
        "gain_restart_over_continue": (gain_restart_over_continue / denom).cpu().numpy(),
    }

def print_probe_summary(probe: Dict, level: int, overwrite_spec: Tuple, zero_k0: bool):
    zk = "zero-k0" if zero_k0 else "normal-k0"
    print(f"\n--- Action probe: level {level} ({level_name(level)}), spec={spec_to_str(overwrite_spec)}, {zk} ---")
    for t in range(T):
        mp = probe["mean_probs"][t]
        br = probe["best_rates"][t]
        g_over = probe["gain_over_continue"][t]
        g_rest = probe["gain_restart_over_continue"][t]
        print(
            f"step {t}: mean p(cont/over/rest)=({mp[0]:.3f}, {mp[1]:.3f}, {mp[2]:.3f}) | "
            f"best rates=({br[0]:.3f}, {br[1]:.3f}, {br[2]:.3f}) | "
            f"Δover-cont={g_over:+.4f} | Δrestart-cont={g_rest:+.4f}"
        )

# -----------------------------
# One run
# -----------------------------
def run_one_seed_and_base_strength(seed: int, base_epochs: int):
    set_seed(seed)
    print("\n\n##############################")
    print(f"Seed = {seed} | base_epochs = {base_epochs}")
    print("##############################")

    base = BaseKnowledgeProvider().to(DEVICE)
    direct = DirectStaticBaseline().to(DEVICE)
    reasoner = MCLTRReasoner(base).to(DEVICE)
    policy = PolicyNet(
        in_dim=(Z_DIM * 2) + K_DIM + (NUM_VALUES + OP_DIM) + 8,
        hidden=192,
    ).to(DEVICE)

    train_base(base, base_epochs, BASE_STEPS_PER_EPOCH)

    frozen_base = copy.deepcopy(base).to(DEVICE)
    set_requires_grad(frozen_base, False)
    direct.base = frozen_base
    reasoner.base = frozen_base

    train_direct_head(frozen_base, direct, epochs=3, steps_per_epoch=DIRECT_STEPS_PER_EPOCH)
    train_reasoner_continue_only(frozen_base, reasoner, epochs=4, steps_per_epoch=REASONER_STEPS_PER_EPOCH)
    train_evaluator(frozen_base, reasoner, epochs=2, steps_per_epoch=EVAL_STEPS_PER_EPOCH)

    policy_overwrite_spec = ("adaptive_project", (0.20, 0.90))
    train_policy_imitation(
        frozen_base,
        reasoner,
        policy,
        overwrite_spec=policy_overwrite_spec,
        epochs=5,
        steps_per_epoch=POLICY_STEPS_PER_EPOCH,
    )

    base_acc = eval_base_classifier(frozen_base, batches=10, bs=256)

    results = {}
    for level in EVAL_LEVELS:
        results[level] = {}

        direct_acc = eval_direct_baseline(frozen_base, direct, level=level, batches=10, bs=256)
        cont_normal = eval_rollout_mode(
            frozen_base, reasoner, level=level, mode="continue",
            overwrite_spec=policy_overwrite_spec, zero_k0=False,
            batches=10, bs=256
        )
        cont_zero = eval_rollout_mode(
            frozen_base, reasoner, level=level, mode="continue",
            overwrite_spec=policy_overwrite_spec, zero_k0=True,
            batches=10, bs=256
        )

        results[level]["base_acc"] = base_acc
        results[level]["direct_acc"] = direct_acc
        results[level]["continue_normal"] = cont_normal["acc"]
        results[level]["continue_zero"] = cont_zero["acc"]

        print(f"\n--- Seed {seed} | base_epochs {base_epochs} | Level {level} ({level_name(level)}) ---")
        print(f"Base classifier (task ID only)       : {base_acc:.4f}")
        print(f"Direct static baseline              : {direct_acc:.4f}")
        print(f"M-CLTR continue-only (normal k0)    : {cont_normal['acc']:.4f}")
        print(f"M-CLTR continue-only (zero k0)      : {cont_zero['acc']:.4f}")
        print(f"Zero-knowledge gap                  : {cont_normal['acc'] - cont_zero['acc']:+.4f}")

        for spec in OVERWRITE_SPECS:
            overwrite_res = eval_rollout_mode(
                frozen_base, reasoner, level=level, mode="overwrite",
                overwrite_spec=spec, zero_k0=False,
                batches=10, bs=256
            )
            restart_res = eval_rollout_mode(
                frozen_base, reasoner, level=level, mode="restart",
                overwrite_spec=spec, zero_k0=False,
                batches=10, bs=256
            )
            oracle_res = eval_rollout_mode(
                frozen_base, reasoner, level=level, mode="oracle",
                overwrite_spec=spec, zero_k0=False,
                batches=10, bs=256
            )

            probe = probe_actions(
                frozen_base, reasoner, level=level, overwrite_spec=spec, zero_k0=False,
                batches=4, bs=128
            )
            probe_zero = probe_actions(
                frozen_base, reasoner, level=level, overwrite_spec=spec, zero_k0=True,
                batches=4, bs=128
            )

            key = spec_to_str(spec)
            results[level][key] = {
                "overwrite_acc": overwrite_res["acc"],
                "restart_acc": restart_res["acc"],
                "oracle_acc": oracle_res["acc"],
                "oracle_c": oracle_res["continue_rate"],
                "oracle_o": oracle_res["overwrite_rate"],
                "oracle_r": oracle_res["restart_rate"],
                "probe": probe,
                "probe_zero": probe_zero,
            }

            print(f"\n  Overwrite spec = {key}")
            print(f"    Forced overwrite acc          : {overwrite_res['acc']:.4f}")
            print(f"    Forced restart acc            : {restart_res['acc']:.4f}")
            print(f"    Step-wise oracle acc          : {oracle_res['acc']:.4f}")
            print(f"    Oracle action rates C/O/R     : {oracle_res['continue_rate']:.3f}/{oracle_res['overwrite_rate']:.3f}/{oracle_res['restart_rate']:.3f}")
            print_probe_summary(probe, level, spec, zero_k0=False)
            print_probe_summary(probe_zero, level, spec, zero_k0=True)

        policy_res = eval_rollout_mode(
            frozen_base, reasoner, level=level, mode="policy",
            overwrite_spec=policy_overwrite_spec, zero_k0=False,
            batches=10, bs=256, policy=policy
        )
        policy_zero = eval_rollout_mode(
            frozen_base, reasoner, level=level, mode="policy",
            overwrite_spec=policy_overwrite_spec, zero_k0=True,
            batches=10, bs=256, policy=policy
        )

        results[level]["policy_acc"] = policy_res["acc"]
        results[level]["policy_zero_acc"] = policy_zero["acc"]

        print(f"\n  Learned policy (imitated oracle)")
        print(f"    Policy rollout acc            : {policy_res['acc']:.4f}")
        print(f"    Policy zero-k0 acc            : {policy_zero['acc']:.4f}")
        print(f"    Policy action rates C/O/R     : {policy_res['continue_rate']:.3f}/{policy_res['overwrite_rate']:.3f}/{policy_res['restart_rate']:.3f}")

    return results

# -----------------------------
# Run sweep
# -----------------------------
all_results = {}
for base_epochs in BASE_EPOCH_SWEEP:
    all_results[base_epochs] = {}
    for seed in SEEDS:
        all_results[base_epochs][seed] = run_one_seed_and_base_strength(seed, base_epochs)

# -----------------------------
# Aggregate summary
# -----------------------------
print("\n\n==============================")
print("Phase 7 aggregate summary")
print("==============================")

for base_epochs in BASE_EPOCH_SWEEP:
    print(f"\n################################")
    print(f"Base epochs = {base_epochs}")
    print(f"################################")

    for level in EVAL_LEVELS:
        base_vals, direct_vals, cont_vals, cont_zero_vals = [], [], [], []
        policy_vals, policy_zero_vals = [], []

        spec_summaries = {
            spec_to_str(spec): {
                "over": [], "rest": [], "oracle": [],
                "orc": [], "oro": [], "orr": [],
                "probe_over": [], "probe_rest": [],
                "probe_best_over": [], "probe_best_rest": [],
                "probe_over_zero": [], "probe_rest_zero": [],
            } for spec in OVERWRITE_SPECS
        }

        for seed in SEEDS:
            rr = all_results[base_epochs][seed][level]
            base_vals.append(rr["base_acc"])
            direct_vals.append(rr["direct_acc"])
            cont_vals.append(rr["continue_normal"])
            cont_zero_vals.append(rr["continue_zero"])
            policy_vals.append(rr["policy_acc"])
            policy_zero_vals.append(rr["policy_zero_acc"])

            for spec in OVERWRITE_SPECS:
                key = spec_to_str(spec)
                r = rr[key]
                spec_summaries[key]["over"].append(r["overwrite_acc"])
                spec_summaries[key]["rest"].append(r["restart_acc"])
                spec_summaries[key]["oracle"].append(r["oracle_acc"])
                spec_summaries[key]["orc"].append(r["oracle_c"])
                spec_summaries[key]["oro"].append(r["oracle_o"])
                spec_summaries[key]["orr"].append(r["oracle_r"])
                spec_summaries[key]["probe_over"].append(float(r["probe"]["gain_over_continue"].mean()))
                spec_summaries[key]["probe_rest"].append(float(r["probe"]["gain_restart_over_continue"].mean()))
                spec_summaries[key]["probe_best_over"].append(float(r["probe"]["best_rates"][:, 1].mean()))
                spec_summaries[key]["probe_best_rest"].append(float(r["probe"]["best_rates"][:, 2].mean()))
                spec_summaries[key]["probe_over_zero"].append(float(r["probe_zero"]["gain_over_continue"].mean()))
                spec_summaries[key]["probe_rest_zero"].append(float(r["probe_zero"]["gain_restart_over_continue"].mean()))

        bm, bs = mean_std(base_vals)
        dm, ds = mean_std(direct_vals)
        cm, cs = mean_std(cont_vals)
        czm, czs = mean_std(cont_zero_vals)
        pm, ps = mean_std(policy_vals)
        pzm, pzs = mean_std(policy_zero_vals)

        print(f"\nLevel {level} ({level_name(level)})")
        print(f"  Base classifier              : {bm:.4f} ± {bs:.4f}")
        print(f"  Direct static baseline       : {dm:.4f} ± {ds:.4f}")
        print(f"  Continue-only (normal k0)    : {cm:.4f} ± {cs:.4f}")
        print(f"  Continue-only (zero k0)      : {czm:.4f} ± {czs:.4f}")
        print(f"  Learned policy (normal k0)   : {pm:.4f} ± {ps:.4f}")
        print(f"  Learned policy (zero k0)     : {pzm:.4f} ± {pzs:.4f}")
        print(f"  Zero-knowledge gap           : {(cm - czm):+.4f}")

        for spec in OVERWRITE_SPECS:
            key = spec_to_str(spec)
            om, os = mean_std(spec_summaries[key]["over"])
            rm, rs = mean_std(spec_summaries[key]["rest"])
            qm, qs = mean_std(spec_summaries[key]["oracle"])
            orc_m, orc_s = mean_std(spec_summaries[key]["orc"])
            oro_m, oro_s = mean_std(spec_summaries[key]["oro"])
            orr_m, orr_s = mean_std(spec_summaries[key]["orr"])
            go_m, go_s = mean_std(spec_summaries[key]["probe_over"])
            gr_m, gr_s = mean_std(spec_summaries[key]["probe_rest"])
            bo_m, bo_s = mean_std(spec_summaries[key]["probe_best_over"])
            br_m, br_s = mean_std(spec_summaries[key]["probe_best_rest"])
            goz_m, goz_s = mean_std(spec_summaries[key]["probe_over_zero"])
            grz_m, grz_s = mean_std(spec_summaries[key]["probe_rest_zero"])

            print(f"\n  Overwrite spec = {key}")
            print(f"    Forced overwrite acc        : {om:.4f} ± {os:.4f}")
            print(f"    Forced restart acc          : {rm:.4f} ± {rs:.4f}")
            print(f"    Step-wise oracle acc        : {qm:.4f} ± {qs:.4f}")
            print(f"    Oracle action rates C/O/R   : {orc_m:.3f} ± {orc_s:.3f} / {oro_m:.3f} ± {oro_s:.3f} / {orr_m:.3f} ± {orr_s:.3f}")
            print(f"    Probe mean Δ(over-cont)     : {go_m:+.4f} ± {go_s:.4f}")
            print(f"    Probe mean Δ(rest-cont)     : {gr_m:+.4f} ± {gr_s:.4f}")
            print(f"    Probe best-action overwrite : {bo_m:.3f} ± {bo_s:.3f}")
            print(f"    Probe best-action restart   : {br_m:.3f} ± {br_s:.3f}")
            print(f"    Zero-k Δ(over-cont)         : {goz_m:+.4f} ± {goz_s:.4f}")
            print(f"    Zero-k Δ(rest-cont)         : {grz_m:+.4f} ± {grz_s:.4f}")

print("\nDone.")

# Fast M-CLTR stress test for Colab T4
# - synthetic rule-switch task
# - frozen base knowledge model
# - continue / overwrite / restart / oracle comparison
# - multiple seeds and two base strengths
# - summary-only output

import copy
import math
import random
import time
from typing import Dict, Optional, Tuple

import numpy as np
import pandas as pd
import torch
import torch.nn as nn
import torch.nn.functional as F

# -----------------------------
# Device / reproducibility
# -----------------------------
DEVICE = torch.device("cuda" if torch.cuda.is_available() else "cpu")
print("Device:", DEVICE)

if DEVICE.type == "cuda":
    torch.backends.cuda.matmul.allow_tf32 = True

try:
    torch.set_float32_matmul_precision("high")
except Exception:
    pass


def set_seed(seed: int) -> None:
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    if torch.cuda.is_available():
        torch.cuda.manual_seed_all(seed)


# -----------------------------
# Config
# -----------------------------
NUM_VALUES = 8
OP_DIM = 2
NUM_CLASSES = NUM_VALUES

SEQ_LEN = 5
T = SEQ_LEN

X_DIM = SEQ_LEN * (NUM_VALUES + OP_DIM)
K_DIM = 48
Z_DIM = 64

SEEDS = [7, 17]
BASE_EPOCH_SWEEP = [2, 6]

BATCH_SIZE = 128
BASE_STEPS_PER_EPOCH = 12
DIRECT_STEPS_PER_EPOCH = 12
REASONER_STEPS_PER_EPOCH = 12
EVAL_STEPS_PER_EPOCH = 10

LR_BASE = 2e-3
LR_DIRECT = 2e-3
LR_REASONER = 2e-3
LR_EVAL = 2e-3

TRAIN_LEVELS = [0, 1, 2, 3, 4]
EVAL_LEVELS = [3, 4]

LEVEL_SPECS = {
    0: {"name": "easy / no switch",         "switch_step": T,      "input_noise": 0.00, "corrupt_step": None, "corrupt_severity": 0.00},
    1: {"name": "medium / mid switch",      "switch_step": T // 2, "input_noise": 0.00, "corrupt_step": None, "corrupt_severity": 0.00},
    2: {"name": "hard / early switch",      "switch_step": 1,      "input_noise": 0.00, "corrupt_step": None, "corrupt_severity": 0.00},
    3: {"name": "switch + latent mistake",  "switch_step": T // 2, "input_noise": 0.00, "corrupt_step": 2,    "corrupt_severity": 0.35},
    4: {"name": "switch + noise + mistake", "switch_step": 1,      "input_noise": 0.10, "corrupt_step": 1,    "corrupt_severity": 0.45},
}

OVERWRITE_SPECS = [
    ("project", 4.0),
    ("gated_project", (0.25, 0.95)),
    ("adaptive_project", (0.20, 0.90)),
]


# -----------------------------
# Helpers
# -----------------------------
def one_hot(v: torch.Tensor, n: int) -> torch.Tensor:
    return F.one_hot(v.long(), n).float()

def step_feature(t: int, batch_size: int, device: torch.device) -> torch.Tensor:
    s = 0.0 if T <= 1 else float(t) / float(T - 1)
    return torch.full((batch_size, 1), s, device=device)

def mean_std(values):
    arr = np.asarray(values, dtype=np.float64)
    if arr.size == 1:
        return float(arr.item()), 0.0
    return float(arr.mean()), float(arr.std(ddof=1))

def sample_indices(n: int, batch_size: int) -> torch.Tensor:
    return torch.randint(0, n, (batch_size,), device=DEVICE)

def get_level_spec(level: int) -> Dict:
    return LEVEL_SPECS[level]

def level_name(level: int) -> str:
    return LEVEL_SPECS[level]["name"]

def spec_to_str(spec: Tuple):
    kind, arg = spec
    if kind == "project":
        return f"project(max_shift={float(arg):.1f})"
    if kind == "gated_project":
        lo, hi = arg
        return f"gated_project({lo:.2f},{hi:.2f})"
    if kind == "adaptive_project":
        lo, hi = arg
        return f"adaptive_project({lo:.2f},{hi:.2f})"
    return f"{kind}({arg})"

def inject_mistake(z: torch.Tensor, severity: float) -> torch.Tensor:
    if severity <= 0:
        return z
    rolled = torch.roll(z, shifts=1, dims=-1)
    mixed = (1.0 - severity) * z + severity * rolled
    mixed = mixed + (0.50 * severity) * torch.randn_like(z)
    return mixed

def set_requires_grad(module: nn.Module, flag: bool):
    for p in module.parameters():
        p.requires_grad = flag

def encode_problem(nums: torch.Tensor, mode_seq: torch.Tensor) -> torch.Tensor:
    nums_oh = one_hot(nums, NUM_VALUES)
    mode_oh = one_hot(mode_seq, OP_DIM)
    x = torch.cat([nums_oh, mode_oh], dim=-1)
    return x.reshape(x.size(0), -1)

def current_step_input(nums: torch.Tensor, mode_seq: torch.Tensor, t: int) -> torch.Tensor:
    return torch.cat([one_hot(nums[:, t], NUM_VALUES), one_hot(mode_seq[:, t], OP_DIM)], dim=-1)

def task_value(nums: torch.Tensor, mode_seq: torch.Tensor) -> torch.Tensor:
    acc = nums[:, 0]
    for t in range(1, T):
        mode = mode_seq[:, t]
        add = (acc + nums[:, t]) % NUM_VALUES
        mul = (acc * nums[:, t]) % NUM_VALUES
        acc = torch.where(mode == 0, add, mul)
    return acc.long()

def make_reasoning_batch(batch_size: int, level: int):
    spec = get_level_spec(level)
    nums = torch.randint(0, NUM_VALUES, (batch_size, T), device=DEVICE)
    start_mode = torch.randint(0, 2, (batch_size,), device=DEVICE)

    switch_step = spec["switch_step"]
    end_mode = start_mode.clone() if switch_step >= T else (1 - start_mode)

    t_ids = torch.arange(T, device=DEVICE).unsqueeze(0).expand(batch_size, T)
    mode_seq = torch.where(t_ids < switch_step, start_mode.unsqueeze(1), end_mode.unsqueeze(1))

    target = task_value(nums, mode_seq)
    x = encode_problem(nums, mode_seq)

    start_ctrl = one_hot(start_mode, OP_DIM)
    ctrl_seq = one_hot(mode_seq, OP_DIM)
    return nums, mode_seq, x, start_ctrl, ctrl_seq, target

def batched_entropy(logits: torch.Tensor) -> torch.Tensor:
    probs = F.softmax(logits, dim=-1)
    ent = -(probs * (probs.clamp_min(1e-8).log())).sum(dim=-1)
    return ent / math.log(probs.size(-1))


# -----------------------------
# Models
# -----------------------------
class MLP(nn.Module):
    def __init__(self, in_dim: int, out_dim: int, hidden: int = 96):
        super().__init__()
        self.net = nn.Sequential(
            nn.Linear(in_dim, hidden),
            nn.GELU(),
            nn.Linear(hidden, hidden),
            nn.GELU(),
            nn.Linear(hidden, out_dim),
        )

    def forward(self, x):
        return self.net(x)

class BaseKnowledgeProvider(nn.Module):
    def __init__(self, x_dim: int = X_DIM, k_dim: int = K_DIM):
        super().__init__()
        self.encoder = nn.Sequential(
            nn.Linear(x_dim, 96),
            nn.GELU(),
            nn.Linear(96, k_dim),
            nn.LayerNorm(k_dim),
        )
        self.classifier = nn.Sequential(
            nn.Linear(k_dim, 64),
            nn.GELU(),
            nn.Linear(64, NUM_CLASSES),
        )
        for m in self.modules():
            if isinstance(m, nn.Linear):
                nn.init.xavier_uniform_(m.weight)
                if m.bias is not None:
                    nn.init.zeros_(m.bias)

    def encode(self, x: torch.Tensor) -> torch.Tensor:
        return self.encoder(x)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.classifier(self.encode(x))

class DirectStaticBaseline(nn.Module):
    def __init__(self, k_dim: int = K_DIM):
        super().__init__()
        self.head = MLP(k_dim + OP_DIM, NUM_CLASSES, hidden=80)
        for m in self.modules():
            if isinstance(m, nn.Linear):
                nn.init.xavier_uniform_(m.weight)
                if m.bias is not None:
                    nn.init.zeros_(m.bias)

    def forward(self, k0: torch.Tensor, start_ctrl: torch.Tensor) -> torch.Tensor:
        return self.head(torch.cat([k0, start_ctrl], dim=-1))

class MCLTRReasoner(nn.Module):
    def __init__(self, base: BaseKnowledgeProvider, k_dim: int = K_DIM, z_dim: int = Z_DIM):
        super().__init__()
        self.base = base
        self.k_dim = k_dim
        self.z_dim = z_dim

        step_input_dim = NUM_VALUES + OP_DIM + 1

        self.init_net = MLP(k_dim + OP_DIM, z_dim, hidden=96)
        self.trans_net = MLP(z_dim + k_dim + step_input_dim, z_dim, hidden=96)
        self.evaluator = MLP(z_dim + k_dim + step_input_dim, 1, hidden=64)
        self.decoder = nn.Linear(z_dim, NUM_CLASSES)

        self.z_norm = nn.LayerNorm(z_dim)

        for m in self.modules():
            if isinstance(m, nn.Linear):
                nn.init.xavier_uniform_(m.weight)
                if m.bias is not None:
                    nn.init.zeros_(m.bias)

    def init_state(self, k0: torch.Tensor, start_ctrl: torch.Tensor) -> torch.Tensor:
        z0 = self.init_net(torch.cat([k0, start_ctrl], dim=-1))
        return self.z_norm(z0)

    def step_update(self, z: torch.Tensor, k0: torch.Tensor, step_inp: torch.Tensor, t: int) -> torch.Tensor:
        step = step_feature(t, z.size(0), z.device)
        inp = torch.cat([z, k0, step_inp, step], dim=-1)
        delta = torch.tanh(self.trans_net(inp))
        cand = self.z_norm(0.82 * z + 0.18 * delta)
        return cand

    def eval_score(self, z: torch.Tensor, k0: torch.Tensor, step_inp: torch.Tensor, t: int) -> torch.Tensor:
        step = step_feature(t, z.size(0), z.device)
        inp = torch.cat([z, k0, step_inp, step], dim=-1)
        return torch.sigmoid(self.evaluator(inp)).squeeze(-1)

    def decode(self, z: torch.Tensor) -> torch.Tensor:
        return self.decoder(z)


# -----------------------------
# Overwrite operators
# -----------------------------
def project_overwrite(cand: torch.Tensor, z0: torch.Tensor, max_shift: float) -> torch.Tensor:
    delta = cand - z0
    delta_norm = delta.norm(dim=-1, keepdim=True).clamp_min(1e-6)
    scale = torch.clamp(torch.full_like(delta_norm, max_shift) / delta_norm, max=1.0)
    return z0 + delta * scale

def gated_project_overwrite(
    cand: torch.Tensor,
    z0: torch.Tensor,
    score: torch.Tensor,
    lo: float,
    hi: float,
) -> torch.Tensor:
    mix = lo + (hi - lo) * score.unsqueeze(-1)
    return mix * cand + (1.0 - mix) * z0

def adaptive_project_overwrite(
    reasoner: MCLTRReasoner,
    cand: torch.Tensor,
    z0: torch.Tensor,
    k0: torch.Tensor,
    step_inp: torch.Tensor,
    t: int,
    lo: float,
    hi: float,
) -> torch.Tensor:
    score = reasoner.eval_score(cand, k0, step_inp, t).clamp(0.0, 1.0)
    step_bias = 0.90 - 0.15 * (t / max(1, T - 1))
    mix = (lo + (hi - lo) * score) * step_bias
    mix = mix.clamp(0.05, 0.95).unsqueeze(-1)

    blended = mix * cand + (1.0 - mix) * z0

    max_shift = (1.0 + 3.0 * score).unsqueeze(-1)
    delta = blended - z0
    delta_norm = delta.norm(dim=-1, keepdim=True).clamp_min(1e-6)
    scale = torch.clamp(max_shift / delta_norm, max=1.0)
    return z0 + delta * scale

def apply_overwrite(
    reasoner: MCLTRReasoner,
    cand: torch.Tensor,
    z0: torch.Tensor,
    k0: torch.Tensor,
    step_inp: torch.Tensor,
    t: int,
    spec: Tuple,
) -> torch.Tensor:
    kind, arg = spec
    if kind == "project":
        return reasoner.z_norm(project_overwrite(cand, z0, float(arg)))
    if kind == "gated_project":
        lo, hi = arg
        score = reasoner.eval_score(cand, k0, step_inp, t)
        return reasoner.z_norm(gated_project_overwrite(cand, z0, score, float(lo), float(hi)))
    if kind == "adaptive_project":
        lo, hi = arg
        return reasoner.z_norm(adaptive_project_overwrite(reasoner, cand, z0, k0, step_inp, t, float(lo), float(hi)))
    raise ValueError(f"Unknown overwrite spec: {spec}")


# -----------------------------
# Rollout helpers
# -----------------------------
@torch.no_grad()
def continue_rollout_from_state(
    reasoner: MCLTRReasoner,
    z_start: torch.Tensor,
    k0: torch.Tensor,
    nums: torch.Tensor,
    mode_seq: torch.Tensor,
    start_t: int,
    level: int,
) -> torch.Tensor:
    spec = get_level_spec(level)
    z = z_start
    for t in range(start_t, T):
        step_inp = current_step_input(nums, mode_seq, t)
        z = reasoner.step_update(z, k0, step_inp, t)
        if spec["corrupt_step"] is not None and t == spec["corrupt_step"]:
            z = inject_mistake(z, spec["corrupt_severity"])
    return z

@torch.no_grad()
def final_target_prob_from_state(
    reasoner: MCLTRReasoner,
    z_start: torch.Tensor,
    k0: torch.Tensor,
    nums: torch.Tensor,
    mode_seq: torch.Tensor,
    start_t: int,
    target: torch.Tensor,
    level: int,
) -> torch.Tensor:
    z_final = continue_rollout_from_state(reasoner, z_start, k0, nums, mode_seq, start_t, level)
    logits = reasoner.decode(z_final)
    probs = F.softmax(logits, dim=-1)
    return probs.gather(1, target.unsqueeze(1)).squeeze(1)

@torch.no_grad()
def choose_oracle_action(
    reasoner: MCLTRReasoner,
    cand: torch.Tensor,
    z0: torch.Tensor,
    k0: torch.Tensor,
    nums: torch.Tensor,
    mode_seq: torch.Tensor,
    t: int,
    target: torch.Tensor,
    overwrite_spec: Tuple,
    level: int,
):
    step_inp = current_step_input(nums, mode_seq, t)
    cont_state = cand
    over_state = apply_overwrite(reasoner, cand, z0, k0, step_inp, t, overwrite_spec)
    rest_state = z0

    p_cont = final_target_prob_from_state(reasoner, cont_state, k0, nums, mode_seq, t + 1, target, level)
    p_over = final_target_prob_from_state(reasoner, over_state, k0, nums, mode_seq, t + 1, target, level)
    p_rest = final_target_prob_from_state(reasoner, rest_state, k0, nums, mode_seq, t + 1, target, level)

    probs = torch.stack([p_cont, p_over, p_rest], dim=-1)
    tie_bias = torch.tensor([2e-3, 1e-3, 0.0], device=probs.device).unsqueeze(0)
    action = (probs + tie_bias).argmax(dim=-1)
    return action, probs


# -----------------------------
# Training
# -----------------------------
def train_base(base: BaseKnowledgeProvider, epochs: int, steps_per_epoch: int):
    base.train()
    opt = torch.optim.AdamW(base.parameters(), lr=LR_BASE, weight_decay=1e-4)
    ce = nn.CrossEntropyLoss()

    print("\n=== Stage 1: base knowledge pretraining ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_acc = 0.0

        for _ in range(steps_per_epoch):
            level = random.choice(TRAIN_LEVELS)
            nums, mode_seq, x, start_ctrl, ctrl_seq, target = make_reasoning_batch(BATCH_SIZE, level)
            logits = base(x)
            loss = ce(logits, target)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(base.parameters(), 1.0)
            opt.step()

            total_loss += loss.item()
            total_acc += (logits.argmax(dim=-1) == target).float().mean().item()

        print(f"Base epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} | acc {total_acc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s")

def train_direct_head(base: BaseKnowledgeProvider, direct: DirectStaticBaseline, epochs: int, steps_per_epoch: int):
    direct.train()
    set_requires_grad(base, False)
    opt = torch.optim.AdamW(direct.parameters(), lr=LR_DIRECT, weight_decay=1e-4)
    ce = nn.CrossEntropyLoss()

    print("\n=== Stage 2: direct static baseline head ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_acc = 0.0

        for _ in range(steps_per_epoch):
            level = random.choice(TRAIN_LEVELS)
            nums, mode_seq, x, start_ctrl, ctrl_seq, target = make_reasoning_batch(BATCH_SIZE, level)

            with torch.no_grad():
                k0 = base.encode(x)

            logits = direct(k0, start_ctrl)
            loss = ce(logits, target)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(direct.parameters(), 1.0)
            opt.step()

            total_loss += loss.item()
            total_acc += (logits.argmax(dim=-1) == target).float().mean().item()

        print(f"Direct epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} | acc {total_acc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s")

def train_reasoner_continue_only(base: BaseKnowledgeProvider, reasoner: MCLTRReasoner, epochs: int, steps_per_epoch: int):
    reasoner.train()
    set_requires_grad(base, False)
    set_requires_grad(reasoner.init_net, True)
    set_requires_grad(reasoner.trans_net, True)
    set_requires_grad(reasoner.decoder, True)
    set_requires_grad(reasoner.z_norm, True)
    set_requires_grad(reasoner.evaluator, False)

    params = list(reasoner.init_net.parameters()) + list(reasoner.trans_net.parameters()) + list(reasoner.decoder.parameters()) + list(reasoner.z_norm.parameters())
    opt = torch.optim.AdamW(params, lr=LR_REASONER, weight_decay=1e-4)
    ce = nn.CrossEntropyLoss()

    print("\n=== Stage 3: reasoner pretraining (continue-only rollouts) ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_acc = 0.0

        for _ in range(steps_per_epoch):
            level = random.choice(TRAIN_LEVELS)
            nums, mode_seq, x, start_ctrl, ctrl_seq, target = make_reasoning_batch(BATCH_SIZE, level)

            with torch.no_grad():
                k0 = base.encode(x)

            z = reasoner.init_state(k0, start_ctrl)
            for t in range(T):
                step_inp = current_step_input(nums, mode_seq, t)
                z = reasoner.step_update(z, k0, step_inp, t)

            logits = reasoner.decode(z)
            loss = ce(logits, target)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(params, 1.0)
            opt.step()

            total_loss += loss.item()
            total_acc += (logits.argmax(dim=-1) == target).float().mean().item()

        print(f"Reasoner epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} | acc {total_acc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s")

def train_evaluator(base: BaseKnowledgeProvider, reasoner: MCLTRReasoner, epochs: int, steps_per_epoch: int):
    reasoner.eval()
    set_requires_grad(base, False)
    set_requires_grad(reasoner.init_net, False)
    set_requires_grad(reasoner.trans_net, False)
    set_requires_grad(reasoner.decoder, False)
    set_requires_grad(reasoner.z_norm, False)
    set_requires_grad(reasoner.evaluator, True)

    opt = torch.optim.AdamW(reasoner.evaluator.parameters(), lr=LR_EVAL, weight_decay=1e-4)
    mse = nn.MSELoss()

    print("\n=== Stage 4: evaluator training (predict final correctness probability) ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_binacc = 0.0

        for _ in range(steps_per_epoch):
            level = random.choice([0, 1, 2, 3, 4])
            nums, mode_seq, x, start_ctrl, ctrl_seq, target = make_reasoning_batch(BATCH_SIZE, level)

            with torch.no_grad():
                k0 = base.encode(x)
                z = reasoner.init_state(k0, start_ctrl)

                step_z, step_k0, step_inp_list, step_t_list, labels = [], [], [], [], []

                for t in range(T):
                    step_inp = current_step_input(nums, mode_seq, t)
                    cand = reasoner.step_update(z, k0, step_inp, t)
                    p_target = final_target_prob_from_state(reasoner, cand, k0, nums, mode_seq, t + 1, target, level)

                    step_z.append(cand.detach())
                    step_k0.append(k0.detach())
                    step_inp_list.append(step_inp.detach())
                    step_t_list.append(step_feature(t, BATCH_SIZE, DEVICE))
                    labels.append(p_target.detach())

                    z = cand

                step_z = torch.cat(step_z, dim=0)
                step_k0 = torch.cat(step_k0, dim=0)
                step_inp_all = torch.cat(step_inp_list, dim=0)
                step_t_all = torch.cat(step_t_list, dim=0)
                labels = torch.cat(labels, dim=0).clamp(0.0, 1.0)

            inp = torch.cat([step_z, step_k0, step_inp_all, step_t_all], dim=-1)
            pred = torch.sigmoid(reasoner.evaluator(inp)).squeeze(-1)
            loss = mse(pred, labels)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(reasoner.evaluator.parameters(), 1.0)
            opt.step()

            total_loss += loss.item()
            total_binacc += ((pred > 0.5) == (labels > 0.5)).float().mean().item()

        print(f"Evaluator epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} | bin-acc {total_binacc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s")


# -----------------------------
# Evaluation
# -----------------------------
@torch.no_grad()
def rollout_reasoner(
    reasoner: MCLTRReasoner,
    k0: torch.Tensor,
    start_ctrl: torch.Tensor,
    nums: torch.Tensor,
    mode_seq: torch.Tensor,
    target: Optional[torch.Tensor],
    level: int,
    mode: str,
    overwrite_spec: Optional[Tuple] = None,
    zero_k0: bool = False,
):
    if zero_k0:
        k0 = torch.zeros_like(k0)

    z0 = reasoner.init_state(k0, start_ctrl)
    z = z0
    spec = get_level_spec(level)
    actions, step_probs = [], []

    for t in range(T):
        step_inp = current_step_input(nums, mode_seq, t)
        cand = reasoner.step_update(z, k0, step_inp, t)

        if spec["corrupt_step"] is not None and t == spec["corrupt_step"]:
            cand = inject_mistake(cand, spec["corrupt_severity"])

        if mode == "continue":
            action = torch.zeros(k0.size(0), dtype=torch.long, device=k0.device)
            z_next = cand

        elif mode == "restart":
            action = torch.full((k0.size(0),), 2, dtype=torch.long, device=k0.device)
            z_next = z0

        elif mode == "overwrite":
            if overwrite_spec is None:
                raise ValueError("overwrite_spec is required for overwrite mode")
            action = torch.ones(k0.size(0), dtype=torch.long, device=k0.device)
            z_next = apply_overwrite(reasoner, cand, z0, k0, step_inp, t, overwrite_spec)

        elif mode == "oracle":
            if overwrite_spec is None or target is None:
                raise ValueError("oracle mode requires overwrite_spec and target")
            action, probs = choose_oracle_action(reasoner, cand, z0, k0, nums, mode_seq, t, target, overwrite_spec, level)
            z_next = torch.empty_like(cand)

            cont_mask = action == 0
            over_mask = action == 1
            rest_mask = action == 2

            if cont_mask.any():
                z_next[cont_mask] = cand[cont_mask]
            if over_mask.any():
                z_next[over_mask] = apply_overwrite(
                    reasoner, cand[over_mask], z0[over_mask], k0[over_mask], step_inp[over_mask], t, overwrite_spec
                )
            if rest_mask.any():
                z_next[rest_mask] = z0[rest_mask]

            step_probs.append(probs)

        else:
            raise ValueError(f"Unknown mode: {mode}")

        actions.append(action)
        z = z_next

    logits = reasoner.decode(z)
    pred = logits.argmax(dim=-1)

    final_step_inp = current_step_input(nums, mode_seq, T - 1)
    final_eval = reasoner.eval_score(z, k0, final_step_inp, T - 1)

    out = {
        "logits": logits,
        "pred": pred,
        "actions": torch.stack(actions, dim=1),
        "final_eval": final_eval,
        "z0": z0,
    }
    if mode == "oracle":
        out["step_probs"] = torch.stack(step_probs, dim=1)
    return out

@torch.no_grad()
def eval_base_classifier(base: BaseKnowledgeProvider, batches: int = 8, bs: int = 256):
    base.eval()
    total = 0
    correct = 0
    for _ in range(batches):
        level = random.choice(TRAIN_LEVELS + EVAL_LEVELS)
        nums, mode_seq, x, start_ctrl, ctrl_seq, target = make_reasoning_batch(bs, level)
        logits = base(x)
        pred = logits.argmax(dim=-1)
        correct += (pred == target).sum().item()
        total += target.numel()
    return correct / total

@torch.no_grad()
def eval_direct_baseline(base: BaseKnowledgeProvider, direct: DirectStaticBaseline, level: int, batches: int = 8, bs: int = 256):
    direct.eval()
    base.eval()
    total = 0
    correct = 0
    for _ in range(batches):
        nums, mode_seq, x, start_ctrl, ctrl_seq, target = make_reasoning_batch(bs, level)
        k0 = base.encode(x)
        logits = direct(k0, start_ctrl)
        pred = logits.argmax(dim=-1)
        correct += (pred == target).sum().item()
        total += target.numel()
    return correct / total

@torch.no_grad()
def eval_rollout_mode(
    base: BaseKnowledgeProvider,
    reasoner: MCLTRReasoner,
    level: int,
    mode: str,
    overwrite_spec: Tuple,
    zero_k0: bool,
    batches: int = 8,
    bs: int = 256,
):
    base.eval()
    reasoner.eval()

    total = 0
    correct = 0
    action_counts = torch.zeros(3, device=DEVICE)
    score_correct = []
    score_incorrect = []

    for _ in range(batches):
        nums, mode_seq, x, start_ctrl, ctrl_seq, target = make_reasoning_batch(bs, level)
        k0 = base.encode(x)

        out = rollout_reasoner(
            reasoner,
            k0,
            start_ctrl,
            nums,
            mode_seq,
            target=target if mode == "oracle" else None,
            level=level,
            mode=mode,
            overwrite_spec=overwrite_spec,
            zero_k0=zero_k0,
        )

        pred = out["pred"]
        correct_mask = pred == target
        correct += correct_mask.sum().item()
        total += target.numel()

        if mode == "oracle":
            action_counts += torch.stack([
                (out["actions"] == 0).sum(),
                (out["actions"] == 1).sum(),
                (out["actions"] == 2).sum(),
            ]).float()

        score = out["final_eval"]
        if correct_mask.any():
            score_correct.append(score[correct_mask].mean().item())
        if (~correct_mask).any():
            score_incorrect.append(score[~correct_mask].mean().item())

    result = {
        "acc": correct / total,
        "score_correct_mean": float(np.mean(score_correct)) if len(score_correct) else float("nan"),
        "score_incorrect_mean": float(np.mean(score_incorrect)) if len(score_incorrect) else float("nan"),
    }

    if mode == "oracle":
        rates = (action_counts / (batches * bs * T)).detach().cpu().numpy()
        result["continue_rate"] = float(rates[0])
        result["overwrite_rate"] = float(rates[1])
        result["restart_rate"] = float(rates[2])

    return result

@torch.no_grad()
def probe_actions(
    base: BaseKnowledgeProvider,
    reasoner: MCLTRReasoner,
    level: int,
    overwrite_spec: Tuple,
    zero_k0: bool,
    batches: int = 3,
    bs: int = 128,
):
    base.eval()
    reasoner.eval()

    best_counts = torch.zeros(T, 3, device=DEVICE)
    mean_probs = torch.zeros(T, 3, device=DEVICE)
    gain_over_continue = torch.zeros(T, device=DEVICE)
    gain_restart_over_continue = torch.zeros(T, device=DEVICE)

    for _ in range(batches):
        nums, mode_seq, x, start_ctrl, ctrl_seq, target = make_reasoning_batch(bs, level)
        k0 = base.encode(x)
        if zero_k0:
            k0 = torch.zeros_like(k0)

        z0 = reasoner.init_state(k0, start_ctrl)
        z = z0
        spec = get_level_spec(level)

        for t in range(T):
            step_inp = current_step_input(nums, mode_seq, t)
            cand = reasoner.step_update(z, k0, step_inp, t)
            if spec["corrupt_step"] is not None and t == spec["corrupt_step"]:
                cand = inject_mistake(cand, spec["corrupt_severity"])

            cont_state = cand
            over_state = apply_overwrite(reasoner, cand, z0, k0, step_inp, t, overwrite_spec)
            rest_state = z0

            p_cont = final_target_prob_from_state(reasoner, cont_state, k0, nums, mode_seq, t + 1, target, level)
            p_over = final_target_prob_from_state(reasoner, over_state, k0, nums, mode_seq, t + 1, target, level)
            p_rest = final_target_prob_from_state(reasoner, rest_state, k0, nums, mode_seq, t + 1, target, level)

            probs = torch.stack([p_cont, p_over, p_rest], dim=-1)
            best = probs.argmax(dim=-1)

            for a in range(3):
                best_counts[t, a] += (best == a).sum()

            mean_probs[t, 0] += p_cont.sum()
            mean_probs[t, 1] += p_over.sum()
            mean_probs[t, 2] += p_rest.sum()

            gain_over_continue[t] += (p_over - p_cont).sum()
            gain_restart_over_continue[t] += (p_rest - p_cont).sum()

            z = cand

    denom = batches * bs
    return {
        "mean_probs": (mean_probs / denom).cpu().numpy(),
        "best_rates": (best_counts / denom).cpu().numpy(),
        "gain_over_continue": (gain_over_continue / denom).cpu().numpy(),
        "gain_restart_over_continue": (gain_restart_over_continue / denom).cpu().numpy(),
    }


# -----------------------------
# One run
# -----------------------------
def run_one_seed_and_base_strength(seed: int, base_epochs: int):
    set_seed(seed)
    print("\n\n##############################")
    print(f"Seed = {seed} | base_epochs = {base_epochs}")
    print("##############################")

    base = BaseKnowledgeProvider().to(DEVICE)
    direct = DirectStaticBaseline().to(DEVICE)
    reasoner = MCLTRReasoner(base).to(DEVICE)

    train_base(base, base_epochs, BASE_STEPS_PER_EPOCH)

    frozen_base = copy.deepcopy(base).to(DEVICE)
    set_requires_grad(frozen_base, False)
    direct.base = frozen_base
    reasoner.base = frozen_base

    train_direct_head(frozen_base, direct, epochs=3, steps_per_epoch=DIRECT_STEPS_PER_EPOCH)
    train_reasoner_continue_only(frozen_base, reasoner, epochs=4, steps_per_epoch=REASONER_STEPS_PER_EPOCH)
    train_evaluator(frozen_base, reasoner, epochs=2, steps_per_epoch=EVAL_STEPS_PER_EPOCH)

    base_acc = eval_base_classifier(frozen_base, batches=8, bs=256)

    rows = []
    for level in EVAL_LEVELS:
        direct_acc = eval_direct_baseline(frozen_base, direct, level=level, batches=8, bs=256)
        cont_normal = eval_rollout_mode(
            frozen_base, reasoner, level=level, mode="continue",
            overwrite_spec=OVERWRITE_SPECS[0], zero_k0=False,
            batches=8, bs=256
        )
        cont_zero = eval_rollout_mode(
            frozen_base, reasoner, level=level, mode="continue",
            overwrite_spec=OVERWRITE_SPECS[0], zero_k0=True,
            batches=8, bs=256
        )

        for spec in OVERWRITE_SPECS:
            overwrite_res = eval_rollout_mode(
                frozen_base, reasoner, level=level, mode="overwrite",
                overwrite_spec=spec, zero_k0=False,
                batches=8, bs=256
            )
            restart_res = eval_rollout_mode(
                frozen_base, reasoner, level=level, mode="restart",
                overwrite_spec=spec, zero_k0=False,
                batches=8, bs=256
            )
            oracle_res = eval_rollout_mode(
                frozen_base, reasoner, level=level, mode="oracle",
                overwrite_spec=spec, zero_k0=False,
                batches=8, bs=256
            )

            probe = probe_actions(
                frozen_base, reasoner, level=level, overwrite_spec=spec, zero_k0=False,
                batches=3, bs=128
            )
            probe_zero = probe_actions(
                frozen_base, reasoner, level=level, overwrite_spec=spec, zero_k0=True,
                batches=3, bs=128
            )

            rows.append({
                "seed": seed,
                "base_epochs": base_epochs,
                "level": level,
                "level_name": level_name(level),
                "spec": spec_to_str(spec),
                "base_acc": base_acc,
                "direct_acc": direct_acc,
                "continue_acc": cont_normal["acc"],
                "continue_zero_acc": cont_zero["acc"],
                "zero_gap": cont_normal["acc"] - cont_zero["acc"],
                "overwrite_acc": overwrite_res["acc"],
                "restart_acc": restart_res["acc"],
                "oracle_acc": oracle_res["acc"],
                "oracle_continue_rate": oracle_res["continue_rate"],
                "oracle_overwrite_rate": oracle_res["overwrite_rate"],
                "oracle_restart_rate": oracle_res["restart_rate"],
                "probe_delta_over": float(probe["gain_over_continue"].mean()),
                "probe_delta_restart": float(probe["gain_restart_over_continue"].mean()),
                "probe_best_overwrite": float(probe["best_rates"][:, 1].mean()),
                "probe_best_restart": float(probe["best_rates"][:, 2].mean()),
                "probe_zero_delta_over": float(probe_zero["gain_over_continue"].mean()),
                "probe_zero_delta_restart": float(probe_zero["gain_restart_over_continue"].mean()),
            })

        print(f"\n--- Seed {seed} | base_epochs {base_epochs} | Level {level} ({level_name(level)}) ---")
        print(f"Base classifier (task ID only)       : {base_acc:.4f}")
        print(f"Direct static baseline              : {direct_acc:.4f}")
        print(f"M-CLTR continue-only (normal k0)    : {cont_normal['acc']:.4f}")
        print(f"M-CLTR continue-only (zero k0)      : {cont_zero['acc']:.4f}")
        print(f"Zero-knowledge gap                  : {cont_normal['acc'] - cont_zero['acc']:+.4f}")

    if DEVICE.type == "cuda":
        torch.cuda.empty_cache()

    return rows


# -----------------------------
# Run sweep
# -----------------------------
all_rows = []
for base_epochs in BASE_EPOCH_SWEEP:
    for seed in SEEDS:
        all_rows.extend(run_one_seed_and_base_strength(seed, base_epochs))

df = pd.DataFrame(all_rows)

# -----------------------------
# Compact summaries
# -----------------------------
print("\n\n==============================")
print("Control summary")
print("==============================")

control_df = df.drop_duplicates(subset=["seed", "base_epochs", "level"])[
    [
        "seed", "base_epochs", "level", "level_name",
        "base_acc", "direct_acc", "continue_acc", "continue_zero_acc", "zero_gap"
    ]
].copy()

control_summary = (
    control_df
    .groupby(["base_epochs", "level", "level_name"], as_index=False)
    .agg({
        "base_acc": ["mean", "std"],
        "direct_acc": ["mean", "std"],
        "continue_acc": ["mean", "std"],
        "continue_zero_acc": ["mean", "std"],
        "zero_gap": ["mean", "std"],
    })
)

control_summary.columns = [
    "base_epochs", "level", "level_name",
    "base_mean", "base_std",
    "direct_mean", "direct_std",
    "continue_mean", "continue_std",
    "continue_zero_mean", "continue_zero_std",
    "zero_gap_mean", "zero_gap_std",
]

print(control_summary.round(3).to_string(index=False))

print("\n\n==============================")
print("Overwrite / restart summary")
print("==============================")

spec_summary = (
    df
    .groupby(["base_epochs", "level", "level_name", "spec"], as_index=False)
    .agg({
        "overwrite_acc": ["mean", "std"],
        "restart_acc": ["mean", "std"],
        "oracle_acc": ["mean", "std"],
        "oracle_continue_rate": ["mean", "std"],
        "oracle_overwrite_rate": ["mean", "std"],
        "oracle_restart_rate": ["mean", "std"],
        "probe_delta_over": ["mean", "std"],
        "probe_delta_restart": ["mean", "std"],
        "probe_best_overwrite": ["mean", "std"],
        "probe_best_restart": ["mean", "std"],
        "probe_zero_delta_over": ["mean", "std"],
        "probe_zero_delta_restart": ["mean", "std"],
    })
)

spec_summary.columns = [
    "base_epochs", "level", "level_name", "spec",
    "overwrite_mean", "overwrite_std",
    "restart_mean", "restart_std",
    "oracle_mean", "oracle_std",
    "oracle_c_mean", "oracle_c_std",
    "oracle_o_mean", "oracle_o_std",
    "oracle_r_mean", "oracle_r_std",
    "probe_d_over_mean", "probe_d_over_std",
    "probe_d_restart_mean", "probe_d_restart_std",
    "probe_best_over_mean", "probe_best_over_std",
    "probe_best_restart_mean", "probe_best_restart_std",
    "probe_zero_d_over_mean", "probe_zero_d_over_std",
    "probe_zero_d_restart_mean", "probe_zero_d_restart_std",
]

print(spec_summary.round(3).to_string(index=False))

print("\nDone.")

# M-CLTR diagnostic cell: 4 exact conditions
# C1: normal knowledge + hidden recipe
# C2: perfect knowledge + hidden recipe
# C3: normal knowledge + visible recipe
# C4: perfect knowledge + visible recipe
#
# Task: tiny rule-switch arithmetic on sequences of length T
# - base model sees only numbers + start mode
# - recipe visibility affects what the reasoner sees at each step
# - perfect knowledge bypasses the base by injecting an oracle latent hint
#
# Output: summary tables only

import math
import random
import time
from typing import Dict, Optional, Tuple, List

import numpy as np
import pandas as pd
import torch
import torch.nn as nn
import torch.nn.functional as F

# -----------------------------
# Device / reproducibility
# -----------------------------
DEVICE = torch.device("cuda" if torch.cuda.is_available() else "cpu")
print("Device:", DEVICE)

def set_seed(seed: int) -> None:
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    if torch.cuda.is_available():
        torch.cuda.manual_seed_all(seed)

# -----------------------------
# Config
# -----------------------------
NUM_VALUES = 10
NUM_CLASSES = 10
OP_DIM = 2

T = 4  # short, multi-step, cheap to run

BASE_X_DIM = T * NUM_VALUES + OP_DIM          # numbers + start mode only
STEP_INP_DIM = NUM_VALUES + OP_DIM            # current number + current recipe info
K_DIM = 64
Z_DIM = 96

SEEDS = [7, 17]            # keep small; add more later if needed
BASE_EPOCHS = 4
REASONER_EPOCHS = 4
EVAL_EPOCHS = 2
POLICY_EPOCHS = 4

BATCH_SIZE = 128
STEPS_PER_EPOCH = 12
EVAL_BATCHES = 10

LR_BASE = 1e-3
LR_REASONER = 1e-3
LR_EVAL = 1e-3
LR_POLICY = 1e-3

TRAIN_LEVELS = [0, 1, 2, 3]
EVAL_LEVELS = [0, 1, 2, 3]

# 0 = no switch
# 1 = mid switch
# 2 = early switch
# 3 = mid switch + noise + corruption
LEVEL_SPECS = {
    0: {"name": "no switch",              "switch_step": T,      "input_noise": 0.00, "corrupt_step": None, "corrupt_severity": 0.00},
    1: {"name": "mid switch",             "switch_step": T // 2, "input_noise": 0.00, "corrupt_step": None, "corrupt_severity": 0.00},
    2: {"name": "early switch",           "switch_step": 1,      "input_noise": 0.00, "corrupt_step": None, "corrupt_severity": 0.00},
    3: {"name": "mid switch + corruption","switch_step": T // 2, "input_noise": 0.10, "corrupt_step": 2,    "corrupt_severity": 0.30},
}

CONDITIONS = [
    ("C1 normal k0 / hidden recipe",  "normal", False),
    ("C2 perfect k0 / hidden recipe", "oracle", False),
    ("C3 normal k0 / visible recipe", "normal", True),
    ("C4 perfect k0 / visible recipe","oracle", True),
]

MAX_OVERWRITE_SHIFT = 4.0
ORACLE_K0_SCALE = 3.0
ORACLE_K0_NOISE = 0.00  # keep 0 for a clean perfect-knowledge condition

# -----------------------------
# Helpers
# -----------------------------
def one_hot(v: torch.Tensor, n: int) -> torch.Tensor:
    return F.one_hot(v.long(), n).float()

def mean_std(values):
    arr = np.asarray(values, dtype=np.float64)
    if arr.size == 1:
        return float(arr.item()), 0.0
    return float(arr.mean()), float(arr.std(ddof=1))

def get_level_spec(level: int) -> Dict:
    return LEVEL_SPECS[level]

def level_name(level: int) -> str:
    return LEVEL_SPECS[level]["name"]

def step_feature(t: int, batch_size: int, device: torch.device) -> torch.Tensor:
    s = 0.0 if T <= 1 else float(t) / float(T - 1)
    return torch.full((batch_size, 1), s, device=device)

def encode_base_input(nums: torch.Tensor, start_mode: torch.Tensor) -> torch.Tensor:
    nums_oh = one_hot(nums, NUM_VALUES)             # [B, T, 10]
    nums_flat = nums_oh.reshape(nums.size(0), -1)   # [B, T*10]
    sm = one_hot(start_mode, OP_DIM)                # [B, 2]
    return torch.cat([nums_flat, sm], dim=-1)

def current_step_input(nums: torch.Tensor, mode_seq: torch.Tensor, t: int, recipe_visible: bool) -> torch.Tensor:
    num_part = one_hot(nums[:, t], NUM_VALUES)
    if recipe_visible:
        mode_part = one_hot(mode_seq[:, t], OP_DIM)
    else:
        mode_part = torch.zeros(nums.size(0), OP_DIM, device=nums.device)
    return torch.cat([num_part, mode_part], dim=-1)

def task_value(nums: torch.Tensor, mode_seq: torch.Tensor) -> torch.Tensor:
    acc = nums[:, 0]
    for t in range(1, T):
        mode = mode_seq[:, t]
        add = (acc + nums[:, t]) % NUM_VALUES
        mul = (acc * nums[:, t]) % NUM_VALUES
        acc = torch.where(mode == 0, add, mul)
    return acc.long()

def make_batch(batch_size: int, level: int):
    spec = get_level_spec(level)
    nums = torch.randint(0, NUM_VALUES, (batch_size, T), device=DEVICE)
    start_mode = torch.randint(0, 2, (batch_size,), device=DEVICE)

    switch_step = spec["switch_step"]
    end_mode = start_mode.clone() if switch_step >= T else (1 - start_mode)

    t_ids = torch.arange(T, device=DEVICE).unsqueeze(0).expand(batch_size, T)
    mode_seq = torch.where(t_ids < switch_step, start_mode.unsqueeze(1), end_mode.unsqueeze(1))

    target = task_value(nums, mode_seq)
    x_base = encode_base_input(nums, start_mode)

    if spec["input_noise"] > 0:
        x_base = torch.clamp(x_base + spec["input_noise"] * torch.randn_like(x_base), 0.0, 1.0)

    start_ctrl = one_hot(start_mode, OP_DIM)
    return nums, mode_seq, x_base, start_ctrl, target

def make_k0(base: "BaseKnowledgeProvider", x_base: torch.Tensor, target: torch.Tensor, knowledge_mode: str) -> torch.Tensor:
    if knowledge_mode == "normal":
        return base.encode(x_base)
    if knowledge_mode == "oracle":
        k0 = torch.zeros(x_base.size(0), K_DIM, device=x_base.device)
        k0[:, :NUM_CLASSES] = ORACLE_K0_SCALE * one_hot(target, NUM_CLASSES)
        if ORACLE_K0_NOISE > 0:
            k0 = k0 + ORACLE_K0_NOISE * torch.randn_like(k0)
        return k0
    raise ValueError(f"Unknown knowledge_mode: {knowledge_mode}")

def set_requires_grad(module: nn.Module, flag: bool):
    for p in module.parameters():
        p.requires_grad = flag

def batched_entropy(logits: torch.Tensor) -> torch.Tensor:
    probs = F.softmax(logits, dim=-1)
    ent = -(probs * (probs.clamp_min(1e-8).log())).sum(dim=-1)
    return ent / math.log(probs.size(-1))

# -----------------------------
# Models
# -----------------------------
class MLP(nn.Module):
    def __init__(self, in_dim: int, out_dim: int, hidden: int = 128):
        super().__init__()
        self.net = nn.Sequential(
            nn.Linear(in_dim, hidden),
            nn.GELU(),
            nn.Linear(hidden, hidden),
            nn.GELU(),
            nn.Linear(hidden, out_dim),
        )
        for m in self.modules():
            if isinstance(m, nn.Linear):
                nn.init.xavier_uniform_(m.weight)
                if m.bias is not None:
                    nn.init.zeros_(m.bias)

    def forward(self, x):
        return self.net(x)

class BaseKnowledgeProvider(nn.Module):
    def __init__(self, x_dim: int = BASE_X_DIM, k_dim: int = K_DIM):
        super().__init__()
        self.encoder = nn.Sequential(
            nn.Linear(x_dim, 128),
            nn.GELU(),
            nn.Linear(128, k_dim),
            nn.LayerNorm(k_dim),
        )
        self.classifier = nn.Sequential(
            nn.Linear(k_dim, 64),
            nn.GELU(),
            nn.Linear(64, NUM_CLASSES),
        )
        for m in self.modules():
            if isinstance(m, nn.Linear):
                nn.init.xavier_uniform_(m.weight)
                if m.bias is not None:
                    nn.init.zeros_(m.bias)

    def encode(self, x: torch.Tensor) -> torch.Tensor:
        return self.encoder(x)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.classifier(self.encode(x))

class MCLTRReasoner(nn.Module):
    def __init__(self, base: BaseKnowledgeProvider, k_dim: int = K_DIM, z_dim: int = Z_DIM):
        super().__init__()
        self.base = base
        self.k_dim = k_dim
        self.z_dim = z_dim

        self.init_net = MLP(k_dim + OP_DIM, z_dim, hidden=128)
        self.trans_net = MLP(z_dim + k_dim + STEP_INP_DIM + 1, z_dim, hidden=128)
        self.evaluator = MLP(z_dim + k_dim + STEP_INP_DIM + 1, 1, hidden=96)
        self.decoder = nn.Linear(z_dim, NUM_CLASSES)

        self.z_norm = nn.LayerNorm(z_dim)

        for m in self.modules():
            if isinstance(m, nn.Linear):
                nn.init.xavier_uniform_(m.weight)
                if m.bias is not None:
                    nn.init.zeros_(m.bias)

    def init_state(self, k0: torch.Tensor, start_ctrl: torch.Tensor) -> torch.Tensor:
        z0 = self.init_net(torch.cat([k0, start_ctrl], dim=-1))
        return self.z_norm(z0)

    def step_update(self, z: torch.Tensor, k0: torch.Tensor, step_inp: torch.Tensor, t: int) -> torch.Tensor:
        step = step_feature(t, z.size(0), z.device)
        inp = torch.cat([z, k0, step_inp, step], dim=-1)
        delta = torch.tanh(self.trans_net(inp))
        return self.z_norm(0.75 * z + 0.25 * delta)

    def eval_score(self, z: torch.Tensor, k0: torch.Tensor, step_inp: torch.Tensor, t: int) -> torch.Tensor:
        step = step_feature(t, z.size(0), z.device)
        inp = torch.cat([z, k0, step_inp, step], dim=-1)
        return torch.sigmoid(self.evaluator(inp)).squeeze(-1)

    def decode(self, z: torch.Tensor) -> torch.Tensor:
        return self.decoder(z)

class PolicyNet(nn.Module):
    def __init__(self, in_dim: int, hidden: int = 192):
        super().__init__()
        self.net = nn.Sequential(
            nn.Linear(in_dim, hidden),
            nn.GELU(),
            nn.Linear(hidden, hidden),
            nn.GELU(),
            nn.Linear(hidden, 3),
        )
        for m in self.modules():
            if isinstance(m, nn.Linear):
                nn.init.xavier_uniform_(m.weight)
                if m.bias is not None:
                    nn.init.zeros_(m.bias)

    def forward(self, x):
        return self.net(x)

# -----------------------------
# Overwrite operator
# -----------------------------
def project_overwrite(cand: torch.Tensor, z0: torch.Tensor, max_shift: float) -> torch.Tensor:
    delta = cand - z0
    delta_norm = delta.norm(dim=-1, keepdim=True).clamp_min(1e-6)
    scale = torch.clamp(torch.full_like(delta_norm, max_shift) / delta_norm, max=1.0)
    return z0 + delta * scale

def apply_overwrite(
    reasoner: MCLTRReasoner,
    cand: torch.Tensor,
    z0: torch.Tensor,
    k0: torch.Tensor,
    step_inp: torch.Tensor,
    t: int,
) -> torch.Tensor:
    out = project_overwrite(cand, z0, MAX_OVERWRITE_SHIFT)
    return reasoner.z_norm(out)

# -----------------------------
# Rollout / oracle
# -----------------------------
@torch.no_grad()
def continue_rollout_from_state(
    reasoner: MCLTRReasoner,
    z_start: torch.Tensor,
    k0: torch.Tensor,
    nums: torch.Tensor,
    mode_seq: torch.Tensor,
    start_t: int,
    level: int,
    recipe_visible: bool,
) -> torch.Tensor:
    spec = get_level_spec(level)
    z = z_start
    for t in range(start_t, T):
        step_inp = current_step_input(nums, mode_seq, t, recipe_visible=recipe_visible)
        z = reasoner.step_update(z, k0, step_inp, t)
        if spec["corrupt_step"] is not None and t == spec["corrupt_step"]:
            z = z + spec["corrupt_severity"] * torch.randn_like(z)
    return z

@torch.no_grad()
def final_target_prob_from_state(
    reasoner: MCLTRReasoner,
    z_start: torch.Tensor,
    k0: torch.Tensor,
    nums: torch.Tensor,
    mode_seq: torch.Tensor,
    start_t: int,
    target: torch.Tensor,
    level: int,
    recipe_visible: bool,
) -> torch.Tensor:
    z_final = continue_rollout_from_state(reasoner, z_start, k0, nums, mode_seq, start_t, level, recipe_visible)
    logits = reasoner.decode(z_final)
    probs = F.softmax(logits, dim=-1)
    return probs.gather(1, target.unsqueeze(1)).squeeze(1)

@torch.no_grad()
def choose_oracle_action(
    reasoner: MCLTRReasoner,
    cand: torch.Tensor,
    z0: torch.Tensor,
    k0: torch.Tensor,
    nums: torch.Tensor,
    mode_seq: torch.Tensor,
    t: int,
    target: torch.Tensor,
    level: int,
    recipe_visible: bool,
):
    step_inp = current_step_input(nums, mode_seq, t, recipe_visible=recipe_visible)
    cont_state = cand
    over_state = apply_overwrite(reasoner, cand, z0, k0, step_inp, t)
    rest_state = z0

    p_cont = final_target_prob_from_state(reasoner, cont_state, k0, nums, mode_seq, t + 1, target, level, recipe_visible)
    p_over = final_target_prob_from_state(reasoner, over_state, k0, nums, mode_seq, t + 1, target, level, recipe_visible)
    p_rest = final_target_prob_from_state(reasoner, rest_state, k0, nums, mode_seq, t + 1, target, level, recipe_visible)

    probs = torch.stack([p_cont, p_over, p_rest], dim=-1)
    tie_bias = torch.tensor([2e-3, 1e-3, 0.0], device=probs.device).unsqueeze(0)
    action = (probs + tie_bias).argmax(dim=-1)
    return action, probs

def build_policy_features(
    reasoner: MCLTRReasoner,
    cand: torch.Tensor,
    z0: torch.Tensor,
    k0: torch.Tensor,
    nums: torch.Tensor,
    mode_seq: torch.Tensor,
    t: int,
    recipe_visible: bool,
    prev_score: Optional[torch.Tensor] = None,
) -> torch.Tensor:
    step_inp = current_step_input(nums, mode_seq, t, recipe_visible=recipe_visible)
    score = reasoner.eval_score(cand, k0, step_inp, t).unsqueeze(-1)
    if prev_score is None:
        delta = score.clone()
    else:
        delta = score - prev_score.unsqueeze(-1)

    logits = reasoner.decode(cand)
    entropy = batched_entropy(logits).unsqueeze(-1)
    cos = F.cosine_similarity(cand, z0, dim=-1, eps=1e-6).unsqueeze(-1)
    cand_norm = cand.norm(dim=-1, keepdim=True)
    z0_norm = z0.norm(dim=-1, keepdim=True)
    k0_norm = k0.norm(dim=-1, keepdim=True)
    step = step_feature(t, cand.size(0), cand.device)

    feat = torch.cat([
        cand, z0, k0, step_inp,
        score, delta, entropy, cos,
        cand_norm, z0_norm, k0_norm, step
    ], dim=-1)
    return feat

# -----------------------------
# Training
# -----------------------------
def train_base(base: BaseKnowledgeProvider, epochs: int, steps_per_epoch: int):
    base.train()
    opt = torch.optim.AdamW(base.parameters(), lr=LR_BASE, weight_decay=1e-4)
    ce = nn.CrossEntropyLoss()

    print("\n=== Stage 1: base pretraining (numbers + start mode only) ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_acc = 0.0
        for _ in range(steps_per_epoch):
            level = random.choice(TRAIN_LEVELS)
            nums, mode_seq, x_base, start_ctrl, target = make_batch(BATCH_SIZE, level)
            logits = base(x_base)
            loss = ce(logits, target)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(base.parameters(), 1.0)
            opt.step()

            total_loss += loss.item()
            total_acc += (logits.argmax(dim=-1) == target).float().mean().item()

        print(f"Base epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} | acc {total_acc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s")

def train_reasoner_continue_only(base: BaseKnowledgeProvider, reasoner: MCLTRReasoner, epochs: int, steps_per_epoch: int):
    reasoner.train()
    set_requires_grad(base, False)
    set_requires_grad(reasoner.init_net, True)
    set_requires_grad(reasoner.trans_net, True)
    set_requires_grad(reasoner.decoder, True)
    set_requires_grad(reasoner.z_norm, True)
    set_requires_grad(reasoner.evaluator, False)

    params = list(reasoner.init_net.parameters()) + list(reasoner.trans_net.parameters()) + list(reasoner.decoder.parameters()) + list(reasoner.z_norm.parameters())
    opt = torch.optim.AdamW(params, lr=LR_REASONER, weight_decay=1e-4)
    ce = nn.CrossEntropyLoss()

    print("\n=== Stage 2: reasoner pretraining (continue-only rollouts) ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_acc = 0.0
        for _ in range(steps_per_epoch):
            level = random.choice(TRAIN_LEVELS)
            recipe_visible = bool(random.getrandbits(1))
            knowledge_mode = "oracle" if random.random() < 0.20 else "normal"

            nums, mode_seq, x_base, start_ctrl, target = make_batch(BATCH_SIZE, level)
            with torch.no_grad():
                k0 = make_k0(base, x_base, target, knowledge_mode)

            z = reasoner.init_state(k0, start_ctrl)
            for t in range(T):
                step_inp = current_step_input(nums, mode_seq, t, recipe_visible=recipe_visible)
                z = reasoner.step_update(z, k0, step_inp, t)

            logits = reasoner.decode(z)
            loss = ce(logits, target)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(params, 1.0)
            opt.step()

            total_loss += loss.item()
            total_acc += (logits.argmax(dim=-1) == target).float().mean().item()

        print(f"Reasoner epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} | acc {total_acc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s")

def train_evaluator(base: BaseKnowledgeProvider, reasoner: MCLTRReasoner, epochs: int, steps_per_epoch: int):
    reasoner.eval()
    set_requires_grad(base, False)
    set_requires_grad(reasoner.init_net, False)
    set_requires_grad(reasoner.trans_net, False)
    set_requires_grad(reasoner.decoder, False)
    set_requires_grad(reasoner.z_norm, False)
    set_requires_grad(reasoner.evaluator, True)

    opt = torch.optim.AdamW(reasoner.evaluator.parameters(), lr=LR_EVAL, weight_decay=1e-4)
    mse = nn.MSELoss()

    print("\n=== Stage 3: evaluator training (predict downstream correctness) ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_binacc = 0.0
        for _ in range(steps_per_epoch):
            level = random.choice(TRAIN_LEVELS)
            recipe_visible = bool(random.getrandbits(1))
            knowledge_mode = "oracle" if random.random() < 0.20 else "normal"

            nums, mode_seq, x_base, start_ctrl, target = make_batch(BATCH_SIZE, level)
            with torch.no_grad():
                k0 = make_k0(base, x_base, target, knowledge_mode)
                z = reasoner.init_state(k0, start_ctrl)

                step_z, step_k0, step_inp_list, step_t_list, labels = [], [], [], [], []

                for t in range(T):
                    step_inp = current_step_input(nums, mode_seq, t, recipe_visible=recipe_visible)
                    cand = reasoner.step_update(z, k0, step_inp, t)
                    p_target = final_target_prob_from_state(
                        reasoner, cand, k0, nums, mode_seq, t + 1, target, level, recipe_visible
                    )

                    step_z.append(cand.detach())
                    step_k0.append(k0.detach())
                    step_inp_list.append(step_inp.detach())
                    step_t_list.append(step_feature(t, BATCH_SIZE, DEVICE))
                    labels.append(p_target.detach())
                    z = cand

                step_z = torch.cat(step_z, dim=0)
                step_k0 = torch.cat(step_k0, dim=0)
                step_inp_all = torch.cat(step_inp_list, dim=0)
                step_t_all = torch.cat(step_t_list, dim=0)
                labels = torch.cat(labels, dim=0).clamp(0.0, 1.0)

            inp = torch.cat([step_z, step_k0, step_inp_all, step_t_all], dim=-1)
            pred = torch.sigmoid(reasoner.evaluator(inp)).squeeze(-1)
            loss = mse(pred, labels)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(reasoner.evaluator.parameters(), 1.0)
            opt.step()

            total_loss += loss.item()
            total_binacc += ((pred > 0.5) == (labels > 0.5)).float().mean().item()

        print(f"Evaluator epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} | bin-acc {total_binacc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s")

def train_policy_imitation(base: BaseKnowledgeProvider, reasoner: MCLTRReasoner, policy: PolicyNet, epochs: int, steps_per_epoch: int):
    reasoner.eval()
    policy.train()
    set_requires_grad(base, False)
    set_requires_grad(reasoner.init_net, False)
    set_requires_grad(reasoner.trans_net, False)
    set_requires_grad(reasoner.decoder, False)
    set_requires_grad(reasoner.z_norm, False)
    set_requires_grad(reasoner.evaluator, False)
    set_requires_grad(policy, True)

    opt = torch.optim.AdamW(policy.parameters(), lr=LR_POLICY, weight_decay=1e-4)
    ce = nn.CrossEntropyLoss()

    print("\n=== Stage 4: policy imitation training ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_acc = 0.0

        for _ in range(steps_per_epoch):
            level = random.choice(TRAIN_LEVELS)
            recipe_visible = bool(random.getrandbits(1))
            knowledge_mode = "oracle" if random.random() < 0.20 else "normal"

            nums, mode_seq, x_base, start_ctrl, target = make_batch(BATCH_SIZE, level)
            with torch.no_grad():
                k0 = make_k0(base, x_base, target, knowledge_mode)
                z0 = reasoner.init_state(k0, start_ctrl)
                z = z0
                prev_score = None

                feats = []
                labels = []

                for t in range(T):
                    step_inp = current_step_input(nums, mode_seq, t, recipe_visible=recipe_visible)
                    cand = reasoner.step_update(z, k0, step_inp, t)

                    spec = get_level_spec(level)
                    if spec["corrupt_step"] is not None and t == spec["corrupt_step"]:
                        cand = cand + spec["corrupt_severity"] * torch.randn_like(cand)

                    feat = build_policy_features(
                        reasoner, cand, z0, k0, nums, mode_seq, t,
                        recipe_visible=recipe_visible, prev_score=prev_score
                    )

                    action, _ = choose_oracle_action(
                        reasoner=reasoner,
                        cand=cand,
                        z0=z0,
                        k0=k0,
                        nums=nums,
                        mode_seq=mode_seq,
                        t=t,
                        target=target,
                        level=level,
                        recipe_visible=recipe_visible,
                    )

                    feats.append(feat.detach())
                    labels.append(action.detach())

                    prev_score = reasoner.eval_score(cand, k0, step_inp, t).detach()
                    z = cand

                feats = torch.cat(feats, dim=0)
                labels = torch.cat(labels, dim=0)

            logits = policy(feats)
            loss = ce(logits, labels)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(policy.parameters(), 1.0)
            opt.step()

            total_loss += loss.item()
            total_acc += (logits.argmax(dim=-1) == labels).float().mean().item()

        print(f"Policy epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} | label-acc {total_acc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s")

# -----------------------------
# Evaluation
# -----------------------------
@torch.no_grad()
def rollout_reasoner(
    reasoner: MCLTRReasoner,
    k0: torch.Tensor,
    start_ctrl: torch.Tensor,
    nums: torch.Tensor,
    mode_seq: torch.Tensor,
    target: Optional[torch.Tensor],
    level: int,
    mode: str,
    recipe_visible: bool,
    policy: Optional[PolicyNet] = None,
):
    z0 = reasoner.init_state(k0, start_ctrl)
    z = z0
    spec = get_level_spec(level)
    actions = []
    step_probs = []
    prev_score = None

    for t in range(T):
        step_inp = current_step_input(nums, mode_seq, t, recipe_visible=recipe_visible)
        cand = reasoner.step_update(z, k0, step_inp, t)

        if spec["corrupt_step"] is not None and t == spec["corrupt_step"]:
            cand = cand + spec["corrupt_severity"] * torch.randn_like(cand)

        if mode == "continue":
            action = torch.zeros(k0.size(0), dtype=torch.long, device=k0.device)
            z_next = cand

        elif mode == "restart":
            action = torch.full((k0.size(0),), 2, dtype=torch.long, device=k0.device)
            z_next = z0

        elif mode == "overwrite":
            action = torch.ones(k0.size(0), dtype=torch.long, device=k0.device)
            z_next = apply_overwrite(reasoner, cand, z0, k0, step_inp, t)

        elif mode == "oracle":
            if target is None:
                raise ValueError("oracle mode requires target")
            action, probs = choose_oracle_action(reasoner, cand, z0, k0, nums, mode_seq, t, target, level, recipe_visible)
            z_next = torch.empty_like(cand)
            cont_mask = action == 0
            over_mask = action == 1
            rest_mask = action == 2

            if cont_mask.any():
                z_next[cont_mask] = cand[cont_mask]
            if over_mask.any():
                z_next[over_mask] = apply_overwrite(reasoner, cand[over_mask], z0[over_mask], k0[over_mask], step_inp[over_mask], t)
            if rest_mask.any():
                z_next[rest_mask] = z0[rest_mask]

            step_probs.append(probs)

        elif mode == "policy":
            if policy is None:
                raise ValueError("policy mode requires policy")
            feat = build_policy_features(reasoner, cand, z0, k0, nums, mode_seq, t, recipe_visible=recipe_visible, prev_score=prev_score)
            logits = policy(feat)
            action = logits.argmax(dim=-1)
            z_next = torch.empty_like(cand)

            cont_mask = action == 0
            over_mask = action == 1
            rest_mask = action == 2

            if cont_mask.any():
                z_next[cont_mask] = cand[cont_mask]
            if over_mask.any():
                z_next[over_mask] = apply_overwrite(reasoner, cand[over_mask], z0[over_mask], k0[over_mask], step_inp[over_mask], t)
            if rest_mask.any():
                z_next[rest_mask] = z0[rest_mask]

            prev_score = reasoner.eval_score(cand, k0, step_inp, t)

        else:
            raise ValueError(f"Unknown mode: {mode}")

        actions.append(action)
        z = z_next

    logits = reasoner.decode(z)
    pred = logits.argmax(dim=-1)
    final_step_inp = current_step_input(nums, mode_seq, T - 1, recipe_visible=recipe_visible)
    final_eval = reasoner.eval_score(z, k0, final_step_inp, T - 1)

    out = {
        "pred": pred,
        "actions": torch.stack(actions, dim=1),
        "final_eval": final_eval,
    }
    if mode == "oracle":
        out["step_probs"] = torch.stack(step_probs, dim=1)
    return out

@torch.no_grad()
def eval_rollout_mode(
    base: BaseKnowledgeProvider,
    reasoner: MCLTRReasoner,
    level: int,
    mode: str,
    knowledge_mode: str,
    recipe_visible: bool,
    policy: Optional[PolicyNet] = None,
    batches: int = EVAL_BATCHES,
    bs: int = 128,
):
    reasoner.eval()
    if policy is not None:
        policy.eval()

    total = 0
    correct = 0
    action_counts = torch.zeros(3, device=DEVICE)
    score_correct = []
    score_incorrect = []

    for _ in range(batches):
        nums, mode_seq, x_base, start_ctrl, target = make_batch(bs, level)
        k0 = make_k0(base, x_base, target, knowledge_mode)

        out = rollout_reasoner(
            reasoner=reasoner,
            k0=k0,
            start_ctrl=start_ctrl,
            nums=nums,
            mode_seq=mode_seq,
            target=target if mode == "oracle" else None,
            level=level,
            mode=mode,
            recipe_visible=recipe_visible,
            policy=policy,
        )

        pred = out["pred"]
        correct_mask = pred == target
        correct += correct_mask.sum().item()
        total += target.numel()

        if mode in ("oracle", "policy"):
            action_counts += torch.stack([
                (out["actions"] == 0).sum(),
                (out["actions"] == 1).sum(),
                (out["actions"] == 2).sum(),
            ]).float()

        score = out["final_eval"]
        if correct_mask.any():
            score_correct.append(score[correct_mask].mean().item())
        if (~correct_mask).any():
            score_incorrect.append(score[~correct_mask].mean().item())

    result = {
        "acc": correct / total,
        "score_correct_mean": float(np.mean(score_correct)) if len(score_correct) else float("nan"),
        "score_incorrect_mean": float(np.mean(score_incorrect)) if len(score_incorrect) else float("nan"),
    }

    if mode in ("oracle", "policy"):
        rates = (action_counts / (batches * bs * T)).detach().cpu().numpy()
        result["continue_rate"] = float(rates[0])
        result["overwrite_rate"] = float(rates[1])
        result["restart_rate"] = float(rates[2])

    return result

# -----------------------------
# One run
# -----------------------------
def run_one_seed(seed: int):
    set_seed(seed)
    print("\n\n##############################")
    print(f"Seed = {seed}")
    print("##############################")

    base = BaseKnowledgeProvider().to(DEVICE)
    reasoner = MCLTRReasoner(base).to(DEVICE)
    policy = PolicyNet(
        in_dim=(2 * Z_DIM) + K_DIM + STEP_INP_DIM + 8,
        hidden=192,
    ).to(DEVICE)

    train_base(base, BASE_EPOCHS, STEPS_PER_EPOCH)
    set_requires_grad(base, False)

    train_reasoner_continue_only(base, reasoner, REASONER_EPOCHS, STEPS_PER_EPOCH)
    train_evaluator(base, reasoner, EVAL_EPOCHS, STEPS_PER_EPOCH)
    train_policy_imitation(base, reasoner, policy, POLICY_EPOCHS, STEPS_PER_EPOCH)

    rows = []

    for level in EVAL_LEVELS:
        for cond_name, knowledge_mode, recipe_visible in CONDITIONS:
            cont = eval_rollout_mode(
                base, reasoner, level=level, mode="continue",
                knowledge_mode=knowledge_mode, recipe_visible=recipe_visible,
                policy=None, batches=EVAL_BATCHES, bs=BATCH_SIZE
            )
            pol = eval_rollout_mode(
                base, reasoner, level=level, mode="policy",
                knowledge_mode=knowledge_mode, recipe_visible=recipe_visible,
                policy=policy, batches=EVAL_BATCHES, bs=BATCH_SIZE
            )
            ora = eval_rollout_mode(
                base, reasoner, level=level, mode="oracle",
                knowledge_mode=knowledge_mode, recipe_visible=recipe_visible,
                policy=None, batches=EVAL_BATCHES, bs=BATCH_SIZE
            )

            rows.append({
                "seed": seed,
                "level": level,
                "level_name": level_name(level),
                "condition": cond_name,
                "knowledge_mode": knowledge_mode,
                "recipe_visible": recipe_visible,
                "continue_acc": cont["acc"],
                "policy_acc": pol["acc"],
                "oracle_acc": ora["acc"],
                "policy_continue_rate": pol.get("continue_rate", float("nan")),
                "policy_overwrite_rate": pol.get("overwrite_rate", float("nan")),
                "policy_restart_rate": pol.get("restart_rate", float("nan")),
                "oracle_continue_rate": ora.get("continue_rate", float("nan")),
                "oracle_overwrite_rate": ora.get("overwrite_rate", float("nan")),
                "oracle_restart_rate": ora.get("restart_rate", float("nan")),
                "policy_score_correct": pol["score_correct_mean"],
                "policy_score_incorrect": pol["score_incorrect_mean"],
            })

    return pd.DataFrame(rows)

# -----------------------------
# Run sweep
# -----------------------------
all_dfs = []
for seed in SEEDS:
    all_dfs.append(run_one_seed(seed))

results_df = pd.concat(all_dfs, ignore_index=True)

# -----------------------------
# Compact summary
# -----------------------------
print("\n\n==============================")
print("Raw results")
print("==============================")
print(results_df[[
    "seed", "level", "level_name", "condition",
    "continue_acc", "policy_acc", "oracle_acc",
    "policy_continue_rate", "policy_overwrite_rate", "policy_restart_rate",
    "policy_score_correct", "policy_score_incorrect"
]].to_string(index=False))

print("\n\n==============================")
print("Aggregated summary by condition")
print("==============================")
agg = results_df.groupby("condition", as_index=False).agg(
    continue_acc_mean=("continue_acc", "mean"),
    policy_acc_mean=("policy_acc", "mean"),
    oracle_acc_mean=("oracle_acc", "mean"),
    policy_continue_rate_mean=("policy_continue_rate", "mean"),
    policy_overwrite_rate_mean=("policy_overwrite_rate", "mean"),
    policy_restart_rate_mean=("policy_restart_rate", "mean"),
    policy_score_correct_mean=("policy_score_correct", "mean"),
    policy_score_incorrect_mean=("policy_score_incorrect", "mean"),
)
agg["policy_score_gap"] = agg["policy_score_correct_mean"] - agg["policy_score_incorrect_mean"]
print(agg.to_string(index=False))

print("\nDone.")

# M-CLTR control test with oracle knowledge source
# Focus: isolate the controller from base-model learning
# Benchmark: synthetic rule-switch modular arithmetic with latent corruption
# Conditions: continue / restart / project overwrite / adaptive overwrite / learned policy / oracle
# Output: compact summary only

import math
import random
import time
from typing import Dict, Optional, Tuple

import numpy as np
import pandas as pd
import torch
import torch.nn as nn
import torch.nn.functional as F

# -----------------------------
# Device / reproducibility
# -----------------------------
DEVICE = torch.device("cuda" if torch.cuda.is_available() else "cpu")
print("Device:", DEVICE)

try:
    torch.set_float32_matmul_precision("high")
except Exception:
    pass

def set_seed(seed: int) -> None:
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    if torch.cuda.is_available():
        torch.cuda.manual_seed_all(seed)

# -----------------------------
# Config
# -----------------------------
NUM_VALUES = 10
OP_DIM = 2
T = 6

TASK_DIM = T * (NUM_VALUES + OP_DIM)
K_DIM = 64
Z_DIM = 96
NUM_CLASSES = NUM_VALUES

SEEDS = [7, 17]

BATCH_SIZE = 128
TRAIN_STEPS_PER_EPOCH = 12
EVAL_BATCHES = 8
PROBE_BATCHES = 4

REASONER_EPOCHS = 5
EVAL_EPOCHS = 2
POLICY_EPOCHS = 4

LR_REASONER = 2e-3
LR_EVAL = 2e-3
LR_POLICY = 2e-3

LEVEL_SPECS = {
    0: {"name": "no switch / no corruption",   "switch_step": T,      "corrupt_step": None, "corrupt_severity": 0.00},
    1: {"name": "mid switch / mild corruption", "switch_step": T // 2, "corrupt_step": 2,    "corrupt_severity": 0.25},
    2: {"name": "early switch / medium corruption", "switch_step": 1,  "corrupt_step": 1,    "corrupt_severity": 0.45},
    3: {"name": "mid switch / strong corruption", "switch_step": T // 2, "corrupt_step": 1,  "corrupt_severity": 0.60},
}

OVERWRITE_SPECS = [
    ("project", 4.0),
    ("gated_project", (0.25, 0.95)),
    ("adaptive_project", (0.20, 0.90)),
]

POLICY_OVERWRITE_SPEC = ("adaptive_project", (0.20, 0.90))

# -----------------------------
# Helpers
# -----------------------------
def one_hot(v: torch.Tensor, n: int) -> torch.Tensor:
    return F.one_hot(v.long(), n).float()

def step_feature(t: int, batch_size: int, device: torch.device) -> torch.Tensor:
    s = 0.0 if T <= 1 else float(t) / float(T - 1)
    return torch.full((batch_size, 1), s, device=device)

def mean_std(values):
    arr = np.asarray(values, dtype=np.float64)
    if arr.size == 1:
        return float(arr.item()), 0.0
    return float(arr.mean()), float(arr.std(ddof=1))

def level_name(level: int) -> str:
    return LEVEL_SPECS[level]["name"]

def spec_to_str(spec: Tuple) -> str:
    kind, arg = spec
    if kind == "project":
        return f"project(max_shift={float(arg):.1f})"
    if kind == "gated_project":
        lo, hi = arg
        return f"gated_project({lo:.2f},{hi:.2f})"
    if kind == "adaptive_project":
        lo, hi = arg
        return f"adaptive_project({lo:.2f},{hi:.2f})"
    return f"{kind}({arg})"

def inject_mistake(z: torch.Tensor, severity: float) -> torch.Tensor:
    if severity <= 0:
        return z
    rolled = torch.roll(z, shifts=1, dims=-1)
    mixed = (1.0 - severity) * z + severity * rolled
    mixed = mixed + (0.60 * severity) * torch.randn_like(z)
    return mixed

def encode_task(nums: torch.Tensor, mode_seq: torch.Tensor) -> torch.Tensor:
    nums_oh = one_hot(nums, NUM_VALUES)          # [B, T, 10]
    mode_oh = one_hot(mode_seq, OP_DIM)          # [B, T, 2]
    x = torch.cat([nums_oh, mode_oh], dim=-1)    # [B, T, 12]
    return x.reshape(x.size(0), -1)              # [B, 72]

def task_value(nums: torch.Tensor, mode_seq: torch.Tensor) -> torch.Tensor:
    acc = nums[:, 0]
    for t in range(1, T):
        mode = mode_seq[:, t]
        add = (acc + nums[:, t]) % NUM_VALUES
        mul = (acc * nums[:, t]) % NUM_VALUES
        acc = torch.where(mode == 0, add, mul)
    return acc.long()

def make_batch(batch_size: int, level: int):
    spec = LEVEL_SPECS[level]
    nums = torch.randint(0, NUM_VALUES, (batch_size, T), device=DEVICE)
    start_mode = torch.randint(0, 2, (batch_size,), device=DEVICE)

    switch_step = spec["switch_step"]
    end_mode = start_mode.clone() if switch_step >= T else (1 - start_mode)

    t_ids = torch.arange(T, device=DEVICE).unsqueeze(0).expand(batch_size, T)
    mode_seq = torch.where(t_ids < switch_step, start_mode.unsqueeze(1), end_mode.unsqueeze(1))

    target = task_value(nums, mode_seq)
    task_feat = encode_task(nums, mode_seq)
    start_ctrl = one_hot(start_mode, OP_DIM)

    return nums, mode_seq, task_feat, start_ctrl, target

def set_requires_grad(module: nn.Module, flag: bool):
    for p in module.parameters():
        p.requires_grad = flag

def batched_entropy(logits: torch.Tensor) -> torch.Tensor:
    probs = F.softmax(logits, dim=-1)
    ent = -(probs * (probs.clamp_min(1e-8).log())).sum(dim=-1)
    return ent / math.log(probs.size(-1))

# -----------------------------
# Oracle knowledge source
# -----------------------------
class OracleKnowledgeSource(nn.Module):
    """
    Perfect knowledge source:
      k0 = [answer_one_hot | projected task features]
    The answer slot is explicit and exact.
    """
    def __init__(self, task_dim: int, k_dim: int = K_DIM):
        super().__init__()
        assert k_dim > NUM_VALUES
        task_part_dim = k_dim - NUM_VALUES
        proj = torch.randn(task_dim, task_part_dim) / math.sqrt(task_dim)
        self.register_buffer("task_proj", proj)

    @torch.no_grad()
    def encode(self, task_feat: torch.Tensor, target: torch.Tensor) -> torch.Tensor:
        ans = one_hot(target, NUM_VALUES)
        task_part = torch.tanh(task_feat @ self.task_proj)
        return torch.cat([ans, task_part], dim=-1)

# -----------------------------
# Models
# -----------------------------
class MLP(nn.Module):
    def __init__(self, in_dim: int, out_dim: int, hidden: int = 128):
        super().__init__()
        self.net = nn.Sequential(
            nn.Linear(in_dim, hidden),
            nn.GELU(),
            nn.Linear(hidden, hidden),
            nn.GELU(),
            nn.Linear(hidden, out_dim),
        )
        for m in self.modules():
            if isinstance(m, nn.Linear):
                nn.init.xavier_uniform_(m.weight)
                if m.bias is not None:
                    nn.init.zeros_(m.bias)

    def forward(self, x):
        return self.net(x)

class MCLTRReasoner(nn.Module):
    def __init__(self, k_dim: int = K_DIM, z_dim: int = Z_DIM):
        super().__init__()
        self.k_dim = k_dim
        self.z_dim = z_dim

        self.init_net = MLP(k_dim + OP_DIM, z_dim, hidden=128)
        self.trans_net = MLP(z_dim + (NUM_VALUES + OP_DIM) + 1, z_dim, hidden=128)
        self.evaluator = MLP(z_dim + k_dim + (NUM_VALUES + OP_DIM) + 1, 1, hidden=96)
        self.decoder = nn.Linear(z_dim, NUM_VALUES)

        self.z_norm = nn.LayerNorm(z_dim)

    def init_state(self, k0: torch.Tensor, start_ctrl: torch.Tensor) -> torch.Tensor:
        z0 = self.init_net(torch.cat([k0, start_ctrl], dim=-1))
        return self.z_norm(z0)

    def step_update(self, z: torch.Tensor, step_inp: torch.Tensor, t: int) -> torch.Tensor:
        step = step_feature(t, z.size(0), z.device)
        inp = torch.cat([z, step_inp, step], dim=-1)
        delta = torch.tanh(self.trans_net(inp))
        cand = self.z_norm(0.90 * z + 0.10 * delta)
        return cand

    def eval_score(self, z: torch.Tensor, k0: torch.Tensor, step_inp: torch.Tensor, t: int) -> torch.Tensor:
        step = step_feature(t, z.size(0), z.device)
        inp = torch.cat([z, k0, step_inp, step], dim=-1)
        return torch.sigmoid(self.evaluator(inp)).squeeze(-1)

    def decode(self, z: torch.Tensor) -> torch.Tensor:
        return self.decoder(z)

class PolicyNet(nn.Module):
    def __init__(self, in_dim: int, hidden: int = 192):
        super().__init__()
        self.net = nn.Sequential(
            nn.Linear(in_dim, hidden),
            nn.GELU(),
            nn.Linear(hidden, hidden),
            nn.GELU(),
            nn.Linear(hidden, 3),
        )
        for m in self.modules():
            if isinstance(m, nn.Linear):
                nn.init.xavier_uniform_(m.weight)
                if m.bias is not None:
                    nn.init.zeros_(m.bias)

    def forward(self, x):
        return self.net(x)

# -----------------------------
# Overwrite operators
# -----------------------------
def project_overwrite(cand: torch.Tensor, z0: torch.Tensor, max_shift: float) -> torch.Tensor:
    delta = cand - z0
    delta_norm = delta.norm(dim=-1, keepdim=True).clamp_min(1e-6)
    scale = torch.clamp(torch.full_like(delta_norm, max_shift) / delta_norm, max=1.0)
    return z0 + delta * scale

def gated_project_overwrite(cand: torch.Tensor, z0: torch.Tensor, score: torch.Tensor, lo: float, hi: float) -> torch.Tensor:
    score = score.clamp(0.0, 1.0).unsqueeze(-1)
    mix = lo + (hi - lo) * score
    return mix * cand + (1.0 - mix) * z0

def adaptive_project_overwrite(
    reasoner: MCLTRReasoner,
    cand: torch.Tensor,
    z0: torch.Tensor,
    k0: torch.Tensor,
    step_inp: torch.Tensor,
    t: int,
    lo: float,
    hi: float,
) -> torch.Tensor:
    score = reasoner.eval_score(cand, k0, step_inp, t).clamp(0.0, 1.0)
    step_bias = 0.90 - 0.15 * (t / max(1, T - 1))
    mix = (lo + (hi - lo) * score) * step_bias
    mix = mix.clamp(0.05, 0.95).unsqueeze(-1)
    blended = mix * cand + (1.0 - mix) * z0

    max_shift = (1.0 + 4.0 * score).unsqueeze(-1)  # roughly [1, 5]
    delta = blended - z0
    delta_norm = delta.norm(dim=-1, keepdim=True).clamp_min(1e-6)
    scale = torch.clamp(max_shift / delta_norm, max=1.0)
    return z0 + delta * scale

def apply_overwrite(
    reasoner: MCLTRReasoner,
    cand: torch.Tensor,
    z0: torch.Tensor,
    k0: torch.Tensor,
    step_inp: torch.Tensor,
    t: int,
    spec: Tuple,
) -> torch.Tensor:
    kind, arg = spec
    if kind == "project":
        return reasoner.z_norm(project_overwrite(cand, z0, float(arg)))
    if kind == "gated_project":
        lo, hi = arg
        score = reasoner.eval_score(cand, k0, step_inp, t)
        return reasoner.z_norm(gated_project_overwrite(cand, z0, score, float(lo), float(hi)))
    if kind == "adaptive_project":
        lo, hi = arg
        return reasoner.z_norm(adaptive_project_overwrite(reasoner, cand, z0, k0, step_inp, t, float(lo), float(hi)))
    raise ValueError(f"Unknown overwrite spec: {spec}")

# -----------------------------
# Rollout helpers
# -----------------------------
@torch.no_grad()
def continue_rollout_from_state(
    reasoner: MCLTRReasoner,
    z_start: torch.Tensor,
    nums: torch.Tensor,
    mode_seq: torch.Tensor,
    start_t: int,
    level: int,
) -> torch.Tensor:
    spec = LEVEL_SPECS[level]
    z = z_start
    for t in range(start_t, T):
        step_inp = torch.cat([one_hot(nums[:, t], NUM_VALUES), one_hot(mode_seq[:, t], OP_DIM)], dim=-1)
        z = reasoner.step_update(z, step_inp, t)
        if spec["corrupt_step"] is not None and t == spec["corrupt_step"]:
            z = inject_mistake(z, spec["corrupt_severity"])
    return z

@torch.no_grad()
def final_target_prob_from_state(
    reasoner: MCLTRReasoner,
    z_start: torch.Tensor,
    nums: torch.Tensor,
    mode_seq: torch.Tensor,
    start_t: int,
    target: torch.Tensor,
    level: int,
) -> torch.Tensor:
    z_final = continue_rollout_from_state(reasoner, z_start, nums, mode_seq, start_t, level)
    probs = F.softmax(reasoner.decode(z_final), dim=-1)
    return probs.gather(1, target.unsqueeze(1)).squeeze(1)

@torch.no_grad()
def choose_oracle_action(
    reasoner: MCLTRReasoner,
    cand: torch.Tensor,
    z0: torch.Tensor,
    k0: torch.Tensor,
    nums: torch.Tensor,
    mode_seq: torch.Tensor,
    t: int,
    target: torch.Tensor,
    overwrite_spec: Tuple,
    level: int,
):
    step_inp = torch.cat([one_hot(nums[:, t], NUM_VALUES), one_hot(mode_seq[:, t], OP_DIM)], dim=-1)

    p_cont = final_target_prob_from_state(reasoner, cand, nums, mode_seq, t + 1, target, level)
    p_over_state = apply_overwrite(reasoner, cand, z0, k0, step_inp, t, overwrite_spec)
    p_over = final_target_prob_from_state(reasoner, p_over_state, nums, mode_seq, t + 1, target, level)
    p_rest = final_target_prob_from_state(reasoner, z0, nums, mode_seq, t + 1, target, level)

    probs = torch.stack([p_cont, p_over, p_rest], dim=-1)
    action = probs.argmax(dim=-1)
    return action, probs

def build_policy_features(
    reasoner: MCLTRReasoner,
    cand: torch.Tensor,
    z0: torch.Tensor,
    k0: torch.Tensor,
    nums: torch.Tensor,
    mode_seq: torch.Tensor,
    t: int,
    prev_score: Optional[torch.Tensor] = None,
) -> torch.Tensor:
    step_inp = torch.cat([one_hot(nums[:, t], NUM_VALUES), one_hot(mode_seq[:, t], OP_DIM)], dim=-1)
    score = reasoner.eval_score(cand, k0, step_inp, t).unsqueeze(-1)

    if prev_score is None:
        delta = score.clone()
    else:
        delta = score - prev_score.unsqueeze(-1)

    logits = reasoner.decode(cand)
    entropy = batched_entropy(logits).unsqueeze(-1)
    cos = F.cosine_similarity(cand, z0, dim=-1, eps=1e-6).unsqueeze(-1)
    cand_norm = cand.norm(dim=-1, keepdim=True)
    z0_norm = z0.norm(dim=-1, keepdim=True)
    k0_norm = k0.norm(dim=-1, keepdim=True)
    step = step_feature(t, cand.size(0), cand.device)

    feat = torch.cat(
        [cand, z0, k0, step_inp, score, delta, entropy, cos, cand_norm, z0_norm, k0_norm, step],
        dim=-1,
    )
    return feat

POLICY_FEAT_DIM = 2 * Z_DIM + K_DIM + (NUM_VALUES + OP_DIM) + 8

# -----------------------------
# Training
# -----------------------------
def train_reasoner(reasoner: MCLTRReasoner, oracle: OracleKnowledgeSource, epochs: int, steps_per_epoch: int):
    reasoner.train()
    set_requires_grad(reasoner, True)
    opt = torch.optim.AdamW(reasoner.parameters(), lr=LR_REASONER, weight_decay=1e-4)
    ce = nn.CrossEntropyLoss()

    print("\n=== Stage 1: reasoner pretraining (continue-only rollouts) ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_acc = 0.0

        for _ in range(steps_per_epoch):
            level = random.choice(list(LEVEL_SPECS.keys()))
            nums, mode_seq, task_feat, start_ctrl, target = make_batch(BATCH_SIZE, level)
            with torch.no_grad():
                k0 = oracle.encode(task_feat, target)

            z = reasoner.init_state(k0, start_ctrl)
            for t in range(T):
                step_inp = torch.cat([one_hot(nums[:, t], NUM_VALUES), one_hot(mode_seq[:, t], OP_DIM)], dim=-1)
                z = reasoner.step_update(z, step_inp, t)

                spec = LEVEL_SPECS[level]
                if spec["corrupt_step"] is not None and t == spec["corrupt_step"]:
                    z = inject_mistake(z, spec["corrupt_severity"])

            logits = reasoner.decode(z)
            loss = ce(logits, target)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(reasoner.parameters(), 1.0)
            opt.step()

            total_loss += loss.item()
            total_acc += (logits.argmax(dim=-1) == target).float().mean().item()

        print(f"Reasoner epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} | acc {total_acc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s")

def train_evaluator(reasoner: MCLTRReasoner, oracle: OracleKnowledgeSource, epochs: int, steps_per_epoch: int):
    reasoner.eval()
    set_requires_grad(reasoner.evaluator, True)
    set_requires_grad(reasoner.init_net, False)
    set_requires_grad(reasoner.trans_net, False)
    set_requires_grad(reasoner.decoder, False)
    set_requires_grad(reasoner.z_norm, False)

    opt = torch.optim.AdamW(reasoner.evaluator.parameters(), lr=LR_EVAL, weight_decay=1e-4)
    mse = nn.MSELoss()

    print("\n=== Stage 2: evaluator training (predict downstream correctness) ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_binacc = 0.0

        for _ in range(steps_per_epoch):
            level = random.choice(list(LEVEL_SPECS.keys()))
            nums, mode_seq, task_feat, start_ctrl, target = make_batch(BATCH_SIZE, level)
            with torch.no_grad():
                k0 = oracle.encode(task_feat, target)
                z = reasoner.init_state(k0, start_ctrl)

                cand_list, k0_list, step_list, labels = [], [], [], []
                for t in range(T):
                    step_inp = torch.cat([one_hot(nums[:, t], NUM_VALUES), one_hot(mode_seq[:, t], OP_DIM)], dim=-1)
                    cand = reasoner.step_update(z, step_inp, t)

                    spec = LEVEL_SPECS[level]
                    if spec["corrupt_step"] is not None and t == spec["corrupt_step"]:
                        cand = inject_mistake(cand, spec["corrupt_severity"])

                    p_target = final_target_prob_from_state(reasoner, cand, nums, mode_seq, t + 1, target, level)

                    cand_list.append(cand.detach())
                    k0_list.append(k0.detach())
                    step_list.append(torch.cat([step_inp.detach(), step_feature(t, BATCH_SIZE, DEVICE)], dim=-1))
                    labels.append(p_target.detach())
                    z = cand

                cand_all = torch.cat(cand_list, dim=0)
                k0_all = torch.cat(k0_list, dim=0)
                step_all = torch.cat(step_list, dim=0)
                labels = torch.cat(labels, dim=0).clamp(0.0, 1.0)

            inp = torch.cat([cand_all, k0_all, step_all], dim=-1)
            pred = torch.sigmoid(reasoner.evaluator(inp)).squeeze(-1)
            loss = mse(pred, labels)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(reasoner.evaluator.parameters(), 1.0)
            opt.step()

            total_loss += loss.item()
            total_binacc += ((pred > 0.5) == (labels > 0.5)).float().mean().item()

        print(f"Evaluator epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} | bin-acc {total_binacc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s")

def train_policy(
    reasoner: MCLTRReasoner,
    oracle: OracleKnowledgeSource,
    overwrite_spec: Tuple,
    epochs: int,
    steps_per_epoch: int,
):
    reasoner.eval()
    policy = PolicyNet(POLICY_FEAT_DIM, hidden=192).to(DEVICE)
    set_requires_grad(policy, True)

    opt = torch.optim.AdamW(policy.parameters(), lr=LR_POLICY, weight_decay=1e-4)
    ce = nn.CrossEntropyLoss()

    print("\n=== Stage 3: policy imitation training ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_acc = 0.0

        for _ in range(steps_per_epoch):
            level = random.choice(list(LEVEL_SPECS.keys()))
            nums, mode_seq, task_feat, start_ctrl, target = make_batch(BATCH_SIZE, level)

            with torch.no_grad():
                k0 = oracle.encode(task_feat, target)
                z0 = reasoner.init_state(k0, start_ctrl)
                z = z0

                feats = []
                labels = []
                prev_score = None

                for t in range(T):
                    step_inp = torch.cat([one_hot(nums[:, t], NUM_VALUES), one_hot(mode_seq[:, t], OP_DIM)], dim=-1)
                    cand = reasoner.step_update(z, step_inp, t)

                    spec = LEVEL_SPECS[level]
                    if spec["corrupt_step"] is not None and t == spec["corrupt_step"]:
                        cand = inject_mistake(cand, spec["corrupt_severity"])

                    feat = build_policy_features(reasoner, cand, z0, k0, nums, mode_seq, t, prev_score=prev_score)
                    action, _ = choose_oracle_action(
                        reasoner=reasoner,
                        cand=cand,
                        z0=z0,
                        k0=k0,
                        nums=nums,
                        mode_seq=mode_seq,
                        t=t,
                        target=target,
                        overwrite_spec=overwrite_spec,
                        level=level,
                    )

                    feats.append(feat.detach())
                    labels.append(action.detach())

                    prev_score = reasoner.eval_score(
                        cand,
                        k0,
                        step_inp,
                        t,
                    ).detach()
                    z = cand

                feats = torch.cat(feats, dim=0)
                labels = torch.cat(labels, dim=0)

            logits = policy(feats)
            loss = ce(logits, labels)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(policy.parameters(), 1.0)
            opt.step()

            total_loss += loss.item()
            total_acc += (logits.argmax(dim=-1) == labels).float().mean().item()

        print(f"Policy epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} | label-acc {total_acc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s")

    return policy

# -----------------------------
# Evaluation
# -----------------------------
@torch.no_grad()
def eval_oracle_readout(oracle: OracleKnowledgeSource, level: int, batches: int = EVAL_BATCHES, bs: int = 256):
    total = 0
    correct = 0
    for _ in range(batches):
        nums, mode_seq, task_feat, start_ctrl, target = make_batch(bs, level)
        k0 = oracle.encode(task_feat, target)
        pred = k0[:, :NUM_VALUES].argmax(dim=-1)
        correct += (pred == target).sum().item()
        total += target.numel()
    return correct / total

@torch.no_grad()
def rollout_reasoner(
    reasoner: MCLTRReasoner,
    k0: torch.Tensor,
    start_ctrl: torch.Tensor,
    nums: torch.Tensor,
    mode_seq: torch.Tensor,
    target: Optional[torch.Tensor],
    level: int,
    mode: str,
    overwrite_spec: Optional[Tuple] = None,
    policy: Optional[PolicyNet] = None,
):
    z0 = reasoner.init_state(k0, start_ctrl)
    z = z0
    spec = LEVEL_SPECS[level]
    actions = []
    step_probs = []
    prev_score = None

    for t in range(T):
        step_inp = torch.cat([one_hot(nums[:, t], NUM_VALUES), one_hot(mode_seq[:, t], OP_DIM)], dim=-1)
        cand = reasoner.step_update(z, step_inp, t)

        if spec["corrupt_step"] is not None and t == spec["corrupt_step"]:
            cand = inject_mistake(cand, spec["corrupt_severity"])

        if mode == "continue":
            action = torch.zeros(k0.size(0), dtype=torch.long, device=k0.device)
            z_next = cand

        elif mode == "restart":
            action = torch.full((k0.size(0),), 2, dtype=torch.long, device=k0.device)
            z_next = z0

        elif mode == "overwrite":
            if overwrite_spec is None:
                raise ValueError("overwrite_spec is required for overwrite mode")
            action = torch.ones(k0.size(0), dtype=torch.long, device=k0.device)
            z_next = apply_overwrite(reasoner, cand, z0, k0, step_inp, t, overwrite_spec)

        elif mode == "oracle":
            if overwrite_spec is None or target is None:
                raise ValueError("oracle mode requires overwrite_spec and target")
            action, probs = choose_oracle_action(
                reasoner, cand, z0, k0, nums, mode_seq, t, target, overwrite_spec, level
            )
            z_next = torch.empty_like(cand)

            cont_mask = action == 0
            over_mask = action == 1
            rest_mask = action == 2

            if cont_mask.any():
                z_next[cont_mask] = cand[cont_mask]
            if over_mask.any():
                z_next[over_mask] = apply_overwrite(
                    reasoner, cand[over_mask], z0[over_mask], k0[over_mask], step_inp[over_mask], t, overwrite_spec
                )
            if rest_mask.any():
                z_next[rest_mask] = z0[rest_mask]

            step_probs.append(probs)

        elif mode == "policy":
            if policy is None:
                raise ValueError("policy model required for policy mode")
            feat = build_policy_features(reasoner, cand, z0, k0, nums, mode_seq, t, prev_score=prev_score)
            logits = policy(feat)
            action = logits.argmax(dim=-1)
            z_next = torch.empty_like(cand)

            cont_mask = action == 0
            over_mask = action == 1
            rest_mask = action == 2

            if cont_mask.any():
                z_next[cont_mask] = cand[cont_mask]
            if over_mask.any():
                z_next[over_mask] = apply_overwrite(
                    reasoner, cand[over_mask], z0[over_mask], k0[over_mask], step_inp[over_mask], t, overwrite_spec
                )
            if rest_mask.any():
                z_next[rest_mask] = z0[rest_mask]

            prev_score = reasoner.eval_score(cand, k0, step_inp, t)

        else:
            raise ValueError(f"Unknown mode: {mode}")

        actions.append(action)
        z = z_next

    logits = reasoner.decode(z)
    pred = logits.argmax(dim=-1)
    final_eval = reasoner.eval_score(
        z,
        k0,
        torch.cat([one_hot(nums[:, -1], NUM_VALUES), one_hot(mode_seq[:, -1], OP_DIM)], dim=-1),
        T - 1,
    )

    out = {
        "pred": pred,
        "actions": torch.stack(actions, dim=1),
        "final_eval": final_eval,
        "z0": z0,
    }
    if mode == "oracle":
        out["step_probs"] = torch.stack(step_probs, dim=1)
    return out

@torch.no_grad()
def eval_rollout_mode(
    reasoner: MCLTRReasoner,
    oracle: OracleKnowledgeSource,
    level: int,
    mode: str,
    overwrite_spec: Optional[Tuple],
    policy: Optional[PolicyNet] = None,
    batches: int = EVAL_BATCHES,
    bs: int = 256,
):
    total = 0
    correct = 0
    action_counts = torch.zeros(3, device=DEVICE)
    score_correct = []
    score_incorrect = []

    for _ in range(batches):
        nums, mode_seq, task_feat, start_ctrl, target = make_batch(bs, level)
        k0 = oracle.encode(task_feat, target)

        out = rollout_reasoner(
            reasoner=reasoner,
            k0=k0,
            start_ctrl=start_ctrl,
            nums=nums,
            mode_seq=mode_seq,
            target=target if mode == "oracle" else None,
            level=level,
            mode=mode,
            overwrite_spec=overwrite_spec,
            policy=policy,
        )

        pred = out["pred"]
        correct_mask = pred == target
        correct += correct_mask.sum().item()
        total += target.numel()

        if mode in ("oracle", "policy"):
            action_counts += torch.stack([
                (out["actions"] == 0).sum(),
                (out["actions"] == 1).sum(),
                (out["actions"] == 2).sum(),
            ]).float()

        score = out["final_eval"]
        if correct_mask.any():
            score_correct.append(score[correct_mask].mean().item())
        if (~correct_mask).any():
            score_incorrect.append(score[~correct_mask].mean().item())

    result = {
        "acc": correct / total,
        "score_correct_mean": float(np.mean(score_correct)) if len(score_correct) else float("nan"),
        "score_incorrect_mean": float(np.mean(score_incorrect)) if len(score_incorrect) else float("nan"),
    }

    if mode in ("oracle", "policy"):
        rates = (action_counts / (batches * bs * T)).detach().cpu().numpy()
        result["continue_rate"] = float(rates[0])
        result["overwrite_rate"] = float(rates[1])
        result["restart_rate"] = float(rates[2])

    return result

@torch.no_grad()
def probe_actions(
    reasoner: MCLTRReasoner,
    oracle: OracleKnowledgeSource,
    level: int,
    overwrite_spec: Tuple,
    batches: int = PROBE_BATCHES,
    bs: int = 128,
):
    best_counts = torch.zeros(3, device=DEVICE)
    gain_over_continue = []
    gain_restart_over_continue = []

    for _ in range(batches):
        nums, mode_seq, task_feat, start_ctrl, target = make_batch(bs, level)
        k0 = oracle.encode(task_feat, target)
        z0 = reasoner.init_state(k0, start_ctrl)
        z = z0

        for t in range(T):
            step_inp = torch.cat([one_hot(nums[:, t], NUM_VALUES), one_hot(mode_seq[:, t], OP_DIM)], dim=-1)
            cand = reasoner.step_update(z, step_inp, t)

            spec = LEVEL_SPECS[level]
            if spec["corrupt_step"] is not None and t == spec["corrupt_step"]:
                cand = inject_mistake(cand, spec["corrupt_severity"])

            p_cont = final_target_prob_from_state(reasoner, cand, nums, mode_seq, t + 1, target, level)
            over_state = apply_overwrite(reasoner, cand, z0, k0, step_inp, t, overwrite_spec)
            p_over = final_target_prob_from_state(reasoner, over_state, nums, mode_seq, t + 1, target, level)
            p_rest = final_target_prob_from_state(reasoner, z0, nums, mode_seq, t + 1, target, level)

            probs = torch.stack([p_cont, p_over, p_rest], dim=-1)
            best = probs.argmax(dim=-1)

            for a in range(3):
                best_counts[a] += (best == a).sum()

            gain_over_continue.append((p_over - p_cont).mean().item())
            gain_restart_over_continue.append((p_rest - p_cont).mean().item())

            z = cand

    denom = batches * T * bs
    best_rates = (best_counts / denom).detach().cpu().numpy()

    return {
        "best_overwrite_rate": float(best_rates[1]),
        "best_restart_rate": float(best_rates[2]),
        "mean_delta_over": float(np.mean(gain_over_continue)),
        "mean_delta_restart": float(np.mean(gain_restart_over_continue)),
    }

# -----------------------------
# Run one seed
# -----------------------------
def run_one_seed(seed: int):
    set_seed(seed)
    print("\n\n##############################")
    print(f"Seed = {seed}")
    print("##############################")

    oracle = OracleKnowledgeSource(TASK_DIM, K_DIM).to(DEVICE)
    reasoner = MCLTRReasoner(K_DIM, Z_DIM).to(DEVICE)

    train_reasoner(reasoner, oracle, epochs=REASONER_EPOCHS, steps_per_epoch=TRAIN_STEPS_PER_EPOCH)
    train_evaluator(reasoner, oracle, epochs=EVAL_EPOCHS, steps_per_epoch=TRAIN_STEPS_PER_EPOCH)
    policy = train_policy(reasoner, oracle, POLICY_OVERWRITE_SPEC, epochs=POLICY_EPOCHS, steps_per_epoch=TRAIN_STEPS_PER_EPOCH)

    rows = []
    for level in LEVEL_SPECS.keys():
        oracle_readout = eval_oracle_readout(oracle, level, batches=EVAL_BATCHES, bs=256)
        cont = eval_rollout_mode(reasoner, oracle, level, mode="continue", overwrite_spec=None, policy=None)
        rest = eval_rollout_mode(reasoner, oracle, level, mode="restart", overwrite_spec=None, policy=None)

        spec_results = {}
        for spec in OVERWRITE_SPECS:
            spec_key = spec_to_str(spec)
            over = eval_rollout_mode(reasoner, oracle, level, mode="overwrite", overwrite_spec=spec, policy=None)
            oracle_act = eval_rollout_mode(reasoner, oracle, level, mode="oracle", overwrite_spec=spec, policy=None)
            probe = probe_actions(reasoner, oracle, level, overwrite_spec=spec)

            spec_results[spec_key] = {
                "overwrite_acc": over["acc"],
                "oracle_acc": oracle_act["acc"],
                "oracle_c": oracle_act["continue_rate"],
                "oracle_o": oracle_act["overwrite_rate"],
                "oracle_r": oracle_act["restart_rate"],
                "probe_over": probe["mean_delta_over"],
                "probe_restart": probe["mean_delta_restart"],
                "probe_best_over": probe["best_overwrite_rate"],
                "probe_best_restart": probe["best_restart_rate"],
            }

        policy_res = eval_rollout_mode(
            reasoner, oracle, level, mode="policy", overwrite_spec=POLICY_OVERWRITE_SPEC, policy=policy
        )

        rows.append({
            "seed": seed,
            "level": level,
            "level_name": level_name(level),
            "oracle_readout_acc": oracle_readout,
            "continue_acc": cont["acc"],
            "restart_acc": rest["acc"],
            "policy_acc": policy_res["acc"],
            "policy_continue_rate": policy_res["continue_rate"],
            "policy_overwrite_rate": policy_res["overwrite_rate"],
            "policy_restart_rate": policy_res["restart_rate"],
            "policy_score_correct": policy_res["score_correct_mean"],
            "policy_score_incorrect": policy_res["score_incorrect_mean"],
            **{f"{spec_key}__overwrite_acc": vals["overwrite_acc"] for spec_key, vals in spec_results.items()},
            **{f"{spec_key}__oracle_acc": vals["oracle_acc"] for spec_key, vals in spec_results.items()},
            **{f"{spec_key}__oracle_c": vals["oracle_c"] for spec_key, vals in spec_results.items()},
            **{f"{spec_key}__oracle_o": vals["oracle_o"] for spec_key, vals in spec_results.items()},
            **{f"{spec_key}__oracle_r": vals["oracle_r"] for spec_key, vals in spec_results.items()},
            **{f"{spec_key}__probe_over": vals["probe_over"] for spec_key, vals in spec_results.items()},
            **{f"{spec_key}__probe_restart": vals["probe_restart"] for spec_key, vals in spec_results.items()},
            **{f"{spec_key}__probe_best_over": vals["probe_best_over"] for spec_key, vals in spec_results.items()},
            **{f"{spec_key}__probe_best_restart": vals["probe_best_restart"] for spec_key, vals in spec_results.items()},
        })

    return rows

# -----------------------------
# Execute
# -----------------------------
all_rows = []
for seed in SEEDS:
    all_rows.extend(run_one_seed(seed))

raw_df = pd.DataFrame(all_rows)

# Compact summaries
summary_rows = []
for level in sorted(raw_df["level"].unique()):
    df_level = raw_df[raw_df["level"] == level]
    for spec in OVERWRITE_SPECS:
        spec_key = spec_to_str(spec)
        summary_rows.append({
            "level": level,
            "level_name": df_level["level_name"].iloc[0],
            "condition": spec_key,
            "oracle_readout_mean": df_level["oracle_readout_acc"].mean(),
            "continue_mean": df_level["continue_acc"].mean(),
            "restart_mean": df_level["restart_acc"].mean(),
            "policy_mean": df_level["policy_acc"].mean(),
            "overwrite_mean": df_level[f"{spec_key}__overwrite_acc"].mean(),
            "oracle_mean": df_level[f"{spec_key}__oracle_acc"].mean(),
            "oracle_c_mean": df_level[f"{spec_key}__oracle_c"].mean(),
            "oracle_o_mean": df_level[f"{spec_key}__oracle_o"].mean(),
            "oracle_r_mean": df_level[f"{spec_key}__oracle_r"].mean(),
            "probe_d_over_mean": df_level[f"{spec_key}__probe_over"].mean(),
            "probe_d_restart_mean": df_level[f"{spec_key}__probe_restart"].mean(),
            "probe_best_over_mean": df_level[f"{spec_key}__probe_best_over"].mean(),
            "probe_best_restart_mean": df_level[f"{spec_key}__probe_best_restart"].mean(),
        })

summary_df = pd.DataFrame(summary_rows)

print("\n\n==============================")
print("Oracle-readout ceiling")
print("==============================")
print(
    raw_df.groupby(["level", "level_name"], as_index=False)["oracle_readout_acc"]
    .mean()
    .rename(columns={"oracle_readout_acc": "oracle_readout_mean"})
    .to_string(index=False)
)

print("\n\n==============================")
print("Compact control summary")
print("==============================")
print(
    summary_df[
        [
            "level",
            "level_name",
            "condition",
            "oracle_readout_mean",
            "continue_mean",
            "restart_mean",
            "policy_mean",
            "overwrite_mean",
            "oracle_mean",
            "oracle_c_mean",
            "oracle_o_mean",
            "oracle_r_mean",
            "probe_d_over_mean",
            "probe_d_restart_mean",
            "probe_best_over_mean",
            "probe_best_restart_mean",
        ]
    ].to_string(index=False)
)

print("\nDone.")

# M-CLTR oracle-knowledge control stress test
# Goal:
#   Isolate the controller from the base-model bottleneck.
#   Use a perfect knowledge source (oracle problem encoding),
#   inject latent corruption on the trajectory, and compare:
#     1) continue
#     2) restart
#     3) project overwrite
#     4) adaptive overwrite
#     5) step-wise oracle
#
# Colab/T4-friendly: small models, compact logs, summary tables only.

import math
import random
import time
from typing import Dict, Optional, Tuple, List

import numpy as np
import pandas as pd
import torch
import torch.nn as nn
import torch.nn.functional as F

# -----------------------------
# Device / reproducibility
# -----------------------------
DEVICE = torch.device("cuda" if torch.cuda.is_available() else "cpu")
print("Device:", DEVICE)

if DEVICE.type == "cuda":
    torch.backends.cuda.matmul.allow_tf32 = True
    torch.backends.cudnn.benchmark = True

def set_seed(seed: int) -> None:
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    if torch.cuda.is_available():
        torch.cuda.manual_seed_all(seed)

# -----------------------------
# Config
# -----------------------------
NUM_VALUES = 10
OP_DIM = 2
SEQ_LEN = 6
T = SEQ_LEN

X_DIM = SEQ_LEN * (NUM_VALUES + OP_DIM)   # perfect oracle problem encoding
K_DIM = X_DIM
Z_DIM = 96

SEEDS = [7, 17]
LEVELS = [0, 1, 2, 3]

BATCH_SIZE = 128
REASONER_EPOCHS = 4
EVALUATOR_EPOCHS = 2
STEPS_PER_EPOCH = 16
EVAL_BATCHES = 10
PROBE_BATCHES = 4

LR_REASONER = 2e-3
LR_EVAL = 2e-3

# Level definitions:
# 0 = clean / no corruption
# 1 = mid switch / mild corruption
# 2 = early switch / medium corruption
# 3 = mid switch / strong corruption
LEVEL_SPECS = {
    0: {"name": "no switch / clean",               "switch_step": T,      "corrupt_steps": [],      "severity": 0.00},
    1: {"name": "mid switch / mild corruption",    "switch_step": T // 2, "corrupt_steps": [2],     "severity": 0.20},
    2: {"name": "early switch / medium corruption","switch_step": 1,      "corrupt_steps": [1, 3],  "severity": 0.35},
    3: {"name": "mid switch / strong corruption",  "switch_step": T // 2, "corrupt_steps": [1, 3],  "severity": 0.55},
}

OVERWRITE_SPECS = [
    ("project", 4.0),
    ("adaptive_project", (0.20, 0.90)),
]

# -----------------------------
# Helpers
# -----------------------------
def one_hot(v: torch.Tensor, n: int) -> torch.Tensor:
    return F.one_hot(v.long(), n).float()

def step_feature(t: int, batch_size: int, device: torch.device) -> torch.Tensor:
    s = 0.0 if T <= 1 else float(t) / float(T - 1)
    return torch.full((batch_size, 1), s, device=device)

def mean_std(values):
    arr = np.asarray(values, dtype=np.float64)
    if arr.size == 1:
        return float(arr.item()), 0.0
    return float(arr.mean()), float(arr.std(ddof=1))

def spec_to_str(spec: Tuple):
    kind, arg = spec
    if kind == "project":
        return f"project(max_shift={float(arg):.1f})"
    if kind == "adaptive_project":
        lo, hi = arg
        return f"adaptive_project({lo:.2f},{hi:.2f})"
    return f"{kind}({arg})"

def level_name(level: int) -> str:
    return LEVEL_SPECS[level]["name"]

def get_level_spec(level: int) -> Dict:
    return LEVEL_SPECS[level]

def inject_mistake(z: torch.Tensor, severity: float) -> torch.Tensor:
    if severity <= 0:
        return z
    rolled = torch.roll(z, shifts=1, dims=-1)
    mixed = (1.0 - severity) * z + severity * rolled
    mixed = mixed + (0.50 * severity) * torch.randn_like(z)
    return mixed

def apply_level_corruption(z: torch.Tensor, level: int, t: int) -> torch.Tensor:
    spec = get_level_spec(level)
    if t in spec["corrupt_steps"]:
        z = inject_mistake(z, spec["severity"])
    return z

def current_step_input(nums: torch.Tensor, mode_seq: torch.Tensor, t: int) -> torch.Tensor:
    return torch.cat([one_hot(nums[:, t], NUM_VALUES), one_hot(mode_seq[:, t], OP_DIM)], dim=-1)

def encode_problem(nums: torch.Tensor, mode_seq: torch.Tensor) -> torch.Tensor:
    nums_oh = one_hot(nums, NUM_VALUES)        # [B, T, 10]
    mode_oh = one_hot(mode_seq, OP_DIM)        # [B, T, 2]
    x = torch.cat([nums_oh, mode_oh], dim=-1)  # [B, T, 12]
    return x.reshape(x.size(0), -1)            # [B, 72]

def task_value(nums: torch.Tensor, mode_seq: torch.Tensor) -> torch.Tensor:
    # Rule 0 = add mod 10, Rule 1 = mul mod 10
    acc = nums[:, 0]
    for t in range(1, T):
        mode = mode_seq[:, t]
        add = (acc + nums[:, t]) % NUM_VALUES
        mul = (acc * nums[:, t]) % NUM_VALUES
        acc = torch.where(mode == 0, add, mul)
    return acc.long()

def make_batch(batch_size: int, level: int):
    spec = get_level_spec(level)
    nums = torch.randint(0, NUM_VALUES, (batch_size, T), device=DEVICE)
    start_mode = torch.randint(0, 2, (batch_size,), device=DEVICE)

    switch_step = spec["switch_step"]
    end_mode = start_mode.clone() if switch_step >= T else (1 - start_mode)

    t_ids = torch.arange(T, device=DEVICE).unsqueeze(0).expand(batch_size, T)
    mode_seq = torch.where(t_ids < switch_step, start_mode.unsqueeze(1), end_mode.unsqueeze(1))

    target = task_value(nums, mode_seq)
    k0 = encode_problem(nums, mode_seq)
    start_ctrl = one_hot(start_mode, OP_DIM)
    return nums, mode_seq, k0, start_ctrl, target

def set_requires_grad(module: nn.Module, flag: bool):
    for p in module.parameters():
        p.requires_grad = flag

def batched_entropy(logits: torch.Tensor) -> torch.Tensor:
    probs = F.softmax(logits, dim=-1)
    ent = -(probs * probs.clamp_min(1e-8).log()).sum(dim=-1)
    return ent / math.log(probs.size(-1))

# -----------------------------
# Models
# -----------------------------
class MLP(nn.Module):
    def __init__(self, in_dim: int, out_dim: int, hidden: int = 128):
        super().__init__()
        self.net = nn.Sequential(
            nn.Linear(in_dim, hidden),
            nn.GELU(),
            nn.Linear(hidden, hidden),
            nn.GELU(),
            nn.Linear(hidden, out_dim),
        )
        for m in self.modules():
            if isinstance(m, nn.Linear):
                nn.init.xavier_uniform_(m.weight)
                if m.bias is not None:
                    nn.init.zeros_(m.bias)

    def forward(self, x):
        return self.net(x)

class MCLTRReasoner(nn.Module):
    def __init__(self, k_dim: int = K_DIM, z_dim: int = Z_DIM):
        super().__init__()
        self.k_dim = k_dim
        self.z_dim = z_dim

        step_input_dim = NUM_VALUES + OP_DIM + 1

        self.init_net = MLP(k_dim + OP_DIM, z_dim, hidden=128)
        self.trans_net = MLP(z_dim + k_dim + step_input_dim, z_dim, hidden=128)
        self.evaluator = MLP(z_dim + k_dim + step_input_dim, 1, hidden=96)
        self.decoder = nn.Linear(z_dim, NUM_VALUES)
        self.z_norm = nn.LayerNorm(z_dim)

    def init_state(self, k0: torch.Tensor, start_ctrl: torch.Tensor) -> torch.Tensor:
        z0 = self.init_net(torch.cat([k0, start_ctrl], dim=-1))
        return self.z_norm(z0)

    def step_update(self, z: torch.Tensor, k0: torch.Tensor, step_inp: torch.Tensor, t: int) -> torch.Tensor:
        step = step_feature(t, z.size(0), z.device)
        inp = torch.cat([z, k0, step_inp, step], dim=-1)
        delta = torch.tanh(self.trans_net(inp))
        cand = self.z_norm(0.82 * z + 0.18 * delta)
        return cand

    def eval_score(self, z: torch.Tensor, k0: torch.Tensor, step_inp: torch.Tensor, t: int) -> torch.Tensor:
        step = step_feature(t, z.size(0), z.device)
        inp = torch.cat([z, k0, step_inp, step], dim=-1)
        return torch.sigmoid(self.evaluator(inp)).squeeze(-1)

    def decode(self, z: torch.Tensor) -> torch.Tensor:
        return self.decoder(z)

# -----------------------------
# Overwrite operators
# -----------------------------
def project_overwrite(cand: torch.Tensor, z0: torch.Tensor, max_shift: float) -> torch.Tensor:
    delta = cand - z0
    delta_norm = delta.norm(dim=-1, keepdim=True).clamp_min(1e-6)
    scale = torch.clamp(torch.full_like(delta_norm, max_shift) / delta_norm, max=1.0)
    return z0 + delta * scale

def adaptive_project_overwrite(
    reasoner: MCLTRReasoner,
    cand: torch.Tensor,
    z0: torch.Tensor,
    k0: torch.Tensor,
    step_inp: torch.Tensor,
    t: int,
    lo: float,
    hi: float,
) -> torch.Tensor:
    score = reasoner.eval_score(cand, k0, step_inp, t).clamp(0.0, 1.0)
    mix = lo + (hi - lo) * score
    mix = mix.clamp(0.05, 0.95).unsqueeze(-1)

    blended = mix * cand + (1.0 - mix) * z0
    max_shift = (1.0 + 4.0 * score).unsqueeze(-1)  # ~ [1,5]
    delta = blended - z0
    delta_norm = delta.norm(dim=-1, keepdim=True).clamp_min(1e-6)
    scale = torch.clamp(max_shift / delta_norm, max=1.0)
    return z0 + delta * scale

def apply_overwrite(
    reasoner: MCLTRReasoner,
    cand: torch.Tensor,
    z0: torch.Tensor,
    k0: torch.Tensor,
    step_inp: torch.Tensor,
    t: int,
    spec: Tuple,
) -> torch.Tensor:
    kind, arg = spec
    if kind == "project":
        out = project_overwrite(cand, z0, float(arg))
        return reasoner.z_norm(out)
    if kind == "adaptive_project":
        lo, hi = arg
        out = adaptive_project_overwrite(reasoner, cand, z0, k0, step_inp, t, float(lo), float(hi))
        return reasoner.z_norm(out)
    raise ValueError(f"Unknown overwrite spec: {spec}")

# -----------------------------
# Rollout helpers
# -----------------------------
@torch.no_grad()
def continue_rollout_from_state(
    reasoner: MCLTRReasoner,
    z_start: torch.Tensor,
    k0: torch.Tensor,
    nums: torch.Tensor,
    mode_seq: torch.Tensor,
    start_t: int,
    level: int,
) -> torch.Tensor:
    z = z_start
    for t in range(start_t, T):
        step_inp = current_step_input(nums, mode_seq, t)
        z = reasoner.step_update(z, k0, step_inp, t)
        z = apply_level_corruption(z, level, t)
    return z

@torch.no_grad()
def final_target_prob_from_state(
    reasoner: MCLTRReasoner,
    z_start: torch.Tensor,
    k0: torch.Tensor,
    nums: torch.Tensor,
    mode_seq: torch.Tensor,
    start_t: int,
    target: torch.Tensor,
    level: int,
) -> torch.Tensor:
    z_final = continue_rollout_from_state(reasoner, z_start, k0, nums, mode_seq, start_t, level)
    logits = reasoner.decode(z_final)
    probs = F.softmax(logits, dim=-1)
    return probs.gather(1, target.unsqueeze(1)).squeeze(1)

@torch.no_grad()
def choose_oracle_action(
    reasoner: MCLTRReasoner,
    cand: torch.Tensor,
    z0: torch.Tensor,
    k0: torch.Tensor,
    nums: torch.Tensor,
    mode_seq: torch.Tensor,
    t: int,
    target: torch.Tensor,
    overwrite_spec: Tuple,
    level: int,
):
    step_inp = current_step_input(nums, mode_seq, t)
    cont_state = cand
    over_state = apply_overwrite(reasoner, cand, z0, k0, step_inp, t, overwrite_spec)
    rest_state = z0

    p_cont = final_target_prob_from_state(reasoner, cont_state, k0, nums, mode_seq, t + 1, target, level)
    p_over = final_target_prob_from_state(reasoner, over_state, k0, nums, mode_seq, t + 1, target, level)
    p_rest = final_target_prob_from_state(reasoner, rest_state, k0, nums, mode_seq, t + 1, target, level)

    probs = torch.stack([p_cont, p_over, p_rest], dim=-1)
    tie_bias = torch.tensor([2e-3, 1e-3, 0.0], device=probs.device).unsqueeze(0)
    action = (probs + tie_bias).argmax(dim=-1)
    return action, probs

@torch.no_grad()
def probe_actions(
    reasoner: MCLTRReasoner,
    level: int,
    overwrite_spec: Tuple,
    batches: int = PROBE_BATCHES,
    bs: int = 128,
):
    best_counts = torch.zeros(T, 3, device=DEVICE)
    mean_probs = torch.zeros(T, 3, device=DEVICE)
    gain_over_continue = torch.zeros(T, device=DEVICE)
    gain_restart_over_continue = torch.zeros(T, device=DEVICE)

    for _ in range(batches):
        nums, mode_seq, k0, start_ctrl, target = make_batch(bs, level)
        z0 = reasoner.init_state(k0, start_ctrl)
        z = z0

        for t in range(T):
            step_inp = current_step_input(nums, mode_seq, t)
            cand = reasoner.step_update(z, k0, step_inp, t)
            cand = apply_level_corruption(cand, level, t)

            cont_state = cand
            over_state = apply_overwrite(reasoner, cand, z0, k0, step_inp, t, overwrite_spec)
            rest_state = z0

            p_cont = final_target_prob_from_state(reasoner, cont_state, k0, nums, mode_seq, t + 1, target, level)
            p_over = final_target_prob_from_state(reasoner, over_state, k0, nums, mode_seq, t + 1, target, level)
            p_rest = final_target_prob_from_state(reasoner, rest_state, k0, nums, mode_seq, t + 1, target, level)

            probs = torch.stack([p_cont, p_over, p_rest], dim=-1)
            best = probs.argmax(dim=-1)

            for a in range(3):
                best_counts[t, a] += (best == a).sum()

            mean_probs[t, 0] += p_cont.sum()
            mean_probs[t, 1] += p_over.sum()
            mean_probs[t, 2] += p_rest.sum()

            gain_over_continue[t] += (p_over - p_cont).sum()
            gain_restart_over_continue[t] += (p_rest - p_cont).sum()

            z = cand

    denom = batches * bs
    return {
        "mean_probs": (mean_probs / denom).cpu().numpy(),
        "best_rates": (best_counts / denom).cpu().numpy(),
        "gain_over_continue": (gain_over_continue / denom).cpu().numpy(),
        "gain_restart_over_continue": (gain_restart_over_continue / denom).cpu().numpy(),
    }

@torch.no_grad()
def rollout_reasoner(
    reasoner: MCLTRReasoner,
    k0: torch.Tensor,
    start_ctrl: torch.Tensor,
    nums: torch.Tensor,
    mode_seq: torch.Tensor,
    target: Optional[torch.Tensor],
    level: int,
    mode: str,
    overwrite_spec: Optional[Tuple] = None,
):
    z0 = reasoner.init_state(k0, start_ctrl)
    z = z0
    actions, step_probs = [], []

    for t in range(T):
        step_inp = current_step_input(nums, mode_seq, t)
        cand = reasoner.step_update(z, k0, step_inp, t)
        cand = apply_level_corruption(cand, level, t)

        if mode == "continue":
            action = torch.zeros(k0.size(0), dtype=torch.long, device=k0.device)
            z_next = cand

        elif mode == "restart":
            action = torch.full((k0.size(0),), 2, dtype=torch.long, device=k0.device)
            z_next = z0

        elif mode == "overwrite":
            if overwrite_spec is None:
                raise ValueError("overwrite_spec is required for overwrite mode")
            action = torch.ones(k0.size(0), dtype=torch.long, device=k0.device)
            z_next = apply_overwrite(reasoner, cand, z0, k0, step_inp, t, overwrite_spec)

        elif mode == "oracle":
            if overwrite_spec is None or target is None:
                raise ValueError("oracle mode requires overwrite_spec and target")
            action, probs = choose_oracle_action(reasoner, cand, z0, k0, nums, mode_seq, t, target, overwrite_spec, level)
            z_next = torch.empty_like(cand)

            cont_mask = action == 0
            over_mask = action == 1
            rest_mask = action == 2

            if cont_mask.any():
                z_next[cont_mask] = cand[cont_mask]
            if over_mask.any():
                z_next[over_mask] = apply_overwrite(
                    reasoner, cand[over_mask], z0[over_mask], k0[over_mask], step_inp[over_mask], t, overwrite_spec
                )
            if rest_mask.any():
                z_next[rest_mask] = z0[rest_mask]

            step_probs.append(probs)

        else:
            raise ValueError(f"Unknown mode: {mode}")

        actions.append(action)
        z = z_next

    logits = reasoner.decode(z)
    pred = logits.argmax(dim=-1)
    final_eval = reasoner.eval_score(z, k0, current_step_input(nums, mode_seq, T - 1), T - 1)

    out = {
        "logits": logits,
        "pred": pred,
        "actions": torch.stack(actions, dim=1),
        "final_eval": final_eval,
        "z0": z0,
    }
    if mode == "oracle":
        out["step_probs"] = torch.stack(step_probs, dim=1)
    return out

# -----------------------------
# Training
# -----------------------------
def train_reasoner(reasoner: MCLTRReasoner, epochs: int, steps_per_epoch: int):
    reasoner.train()
    set_requires_grad(reasoner.init_net, True)
    set_requires_grad(reasoner.trans_net, True)
    set_requires_grad(reasoner.decoder, True)
    set_requires_grad(reasoner.z_norm, True)
    set_requires_grad(reasoner.evaluator, False)

    params = list(reasoner.init_net.parameters()) + list(reasoner.trans_net.parameters()) + \
             list(reasoner.decoder.parameters()) + list(reasoner.z_norm.parameters())
    opt = torch.optim.AdamW(params, lr=LR_REASONER, weight_decay=1e-4)
    ce = nn.CrossEntropyLoss()

    print("\n=== Stage 1: reasoner pretraining (continue-only, clean rollouts) ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_acc = 0.0

        for _ in range(steps_per_epoch):
            level = random.choice(LEVELS)
            nums, mode_seq, k0, start_ctrl, target = make_batch(BATCH_SIZE, level)

            z = reasoner.init_state(k0, start_ctrl)
            for t in range(T):
                step_inp = current_step_input(nums, mode_seq, t)
                z = reasoner.step_update(z, k0, step_inp, t)

            logits = reasoner.decode(z)
            loss = ce(logits, target)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(params, 1.0)
            opt.step()

            total_loss += loss.item()
            total_acc += (logits.argmax(dim=-1) == target).float().mean().item()

        print(f"Reasoner epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} | acc {total_acc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s")

def train_evaluator(reasoner: MCLTRReasoner, epochs: int, steps_per_epoch: int):
    reasoner.eval()
    set_requires_grad(reasoner.init_net, False)
    set_requires_grad(reasoner.trans_net, False)
    set_requires_grad(reasoner.decoder, False)
    set_requires_grad(reasoner.z_norm, False)
    set_requires_grad(reasoner.evaluator, True)

    opt = torch.optim.AdamW(reasoner.evaluator.parameters(), lr=LR_EVAL, weight_decay=1e-4)
    mse = nn.MSELoss()

    print("\n=== Stage 2: evaluator training (predict downstream correctness) ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_binacc = 0.0

        for _ in range(steps_per_epoch):
            level = random.choice(LEVELS)
            nums, mode_seq, k0, start_ctrl, target = make_batch(BATCH_SIZE, level)

            with torch.no_grad():
                z = reasoner.init_state(k0, start_ctrl)

                step_z, step_k0, step_inp_list, step_t_list, labels = [], [], [], [], []

                for t in range(T):
                    step_inp = current_step_input(nums, mode_seq, t)
                    cand = reasoner.step_update(z, k0, step_inp, t)
                    cand = apply_level_corruption(cand, level, t)

                    p_target = final_target_prob_from_state(reasoner, cand, k0, nums, mode_seq, t + 1, target, level)

                    step_z.append(cand.detach())
                    step_k0.append(k0.detach())
                    step_inp_list.append(step_inp.detach())
                    step_t_list.append(step_feature(t, BATCH_SIZE, DEVICE))
                    labels.append(p_target.detach())

                    z = cand

                step_z = torch.cat(step_z, dim=0)
                step_k0 = torch.cat(step_k0, dim=0)
                step_inp_all = torch.cat(step_inp_list, dim=0)
                step_t_all = torch.cat(step_t_list, dim=0)
                labels = torch.cat(labels, dim=0).clamp(0.0, 1.0)

            inp = torch.cat([step_z, step_k0, step_inp_all, step_t_all], dim=-1)
            pred = torch.sigmoid(reasoner.evaluator(inp)).squeeze(-1)
            loss = mse(pred, labels)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(reasoner.evaluator.parameters(), 1.0)
            opt.step()

            total_loss += loss.item()
            total_binacc += ((pred > 0.5) == (labels > 0.5)).float().mean().item()

        print(f"Evaluator epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} | bin-acc {total_binacc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s")

# -----------------------------
# Evaluation wrappers
# -----------------------------
@torch.no_grad()
def eval_mode(
    reasoner: MCLTRReasoner,
    level: int,
    mode: str,
    overwrite_spec: Optional[Tuple] = None,
    batches: int = EVAL_BATCHES,
    bs: int = 256,
):
    reasoner.eval()
    total = 0
    correct = 0
    action_counts = torch.zeros(3, device=DEVICE)
    score_correct = []
    score_incorrect = []

    for _ in range(batches):
        nums, mode_seq, k0, start_ctrl, target = make_batch(bs, level)
        out = rollout_reasoner(
            reasoner=reasoner,
            k0=k0,
            start_ctrl=start_ctrl,
            nums=nums,
            mode_seq=mode_seq,
            target=target if mode == "oracle" else None,
            level=level,
            mode=mode,
            overwrite_spec=overwrite_spec,
        )

        pred = out["pred"]
        correct_mask = pred == target
        correct += correct_mask.sum().item()
        total += target.numel()

        if mode == "oracle":
            action_counts += torch.stack([
                (out["actions"] == 0).sum(),
                (out["actions"] == 1).sum(),
                (out["actions"] == 2).sum(),
            ]).float()

        score = out["final_eval"]
        if correct_mask.any():
            score_correct.append(score[correct_mask].mean().item())
        if (~correct_mask).any():
            score_incorrect.append(score[~correct_mask].mean().item())

    result = {
        "acc": correct / total,
        "score_correct_mean": float(np.mean(score_correct)) if len(score_correct) else float("nan"),
        "score_incorrect_mean": float(np.mean(score_incorrect)) if len(score_incorrect) else float("nan"),
    }

    if mode == "oracle":
        rates = (action_counts / (batches * bs * T)).detach().cpu().numpy()
        result["continue_rate"] = float(rates[0])
        result["overwrite_rate"] = float(rates[1])
        result["restart_rate"] = float(rates[2])

    return result

def run_one_seed(seed: int):
    set_seed(seed)
    print("\n\n##############################")
    print(f"Seed = {seed}")
    print("##############################")

    reasoner = MCLTRReasoner().to(DEVICE)

    train_reasoner(reasoner, epochs=REASONER_EPOCHS, steps_per_epoch=STEPS_PER_EPOCH)
    train_evaluator(reasoner, epochs=EVALUATOR_EPOCHS, steps_per_epoch=STEPS_PER_EPOCH)

    rows = []

    for level in LEVELS:
        cont = eval_mode(reasoner, level, mode="continue")
        rest = eval_mode(reasoner, level, mode="restart")

        print(f"\n--- Seed {seed} | Level {level} ({level_name(level)}) ---")
        print(f"Continue-only acc : {cont['acc']:.4f}")
        print(f"Restart-only acc  : {rest['acc']:.4f}")

        for spec in OVERWRITE_SPECS:
            over = eval_mode(reasoner, level, mode="overwrite", overwrite_spec=spec)
            oracle = eval_mode(reasoner, level, mode="oracle", overwrite_spec=spec)
            probe = probe_actions(reasoner, level, overwrite_spec=spec)

            rows.append({
                "seed": seed,
                "level": level,
                "level_name": level_name(level),
                "condition": spec_to_str(spec),
                "continue_acc": cont["acc"],
                "overwrite_acc": over["acc"],
                "restart_acc": rest["acc"],
                "oracle_acc": oracle["acc"],
                "oracle_c": oracle["continue_rate"],
                "oracle_o": oracle["overwrite_rate"],
                "oracle_r": oracle["restart_rate"],
                "oracle_score_correct": oracle["score_correct_mean"],
                "oracle_score_incorrect": oracle["score_incorrect_mean"],
                "probe_d_over": float(probe["gain_over_continue"].mean()),
                "probe_d_restart": float(probe["gain_restart_over_continue"].mean()),
                "probe_best_over": float(probe["best_rates"][:, 1].mean()),
                "probe_best_restart": float(probe["best_rates"][:, 2].mean()),
            })

            print(f"  {spec_to_str(spec)}")
            print(f"    forced overwrite acc : {over['acc']:.4f}")
            print(f"    step-wise oracle acc : {oracle['acc']:.4f}")
            print(f"    oracle action rates  : C/O/R = {oracle['continue_rate']:.3f}/{oracle['overwrite_rate']:.3f}/{oracle['restart_rate']:.3f}")

    return pd.DataFrame(rows)

# -----------------------------
# Run sweep
# -----------------------------
all_rows = []
for seed in SEEDS:
    df_seed = run_one_seed(seed)
    all_rows.append(df_seed)

raw = pd.concat(all_rows, ignore_index=True)

# -----------------------------
# Aggregated summary
# -----------------------------
print("\n\n==============================")
print("Compact control summary")
print("==============================")

summary_rows = []
group_cols = ["level", "level_name", "condition"]
for (level, level_name_str, cond), g in raw.groupby(group_cols):
    summary_rows.append({
        "level": level,
        "level_name": level_name_str,
        "condition": cond,
        "continue_acc_mean": g["continue_acc"].mean(),
        "continue_acc_std": g["continue_acc"].std(ddof=1) if len(g) > 1 else 0.0,
        "overwrite_acc_mean": g["overwrite_acc"].mean(),
        "overwrite_acc_std": g["overwrite_acc"].std(ddof=1) if len(g) > 1 else 0.0,
        "restart_acc_mean": g["restart_acc"].mean(),
        "restart_acc_std": g["restart_acc"].std(ddof=1) if len(g) > 1 else 0.0,
        "oracle_acc_mean": g["oracle_acc"].mean(),
        "oracle_acc_std": g["oracle_acc"].std(ddof=1) if len(g) > 1 else 0.0,
        "oracle_c_mean": g["oracle_c"].mean(),
        "oracle_o_mean": g["oracle_o"].mean(),
        "oracle_r_mean": g["oracle_r"].mean(),
        "score_gap_mean": (g["oracle_score_correct"] - g["oracle_score_incorrect"]).mean(),
        "probe_d_over_mean": g["probe_d_over"].mean(),
        "probe_d_restart_mean": g["probe_d_restart"].mean(),
        "probe_best_over_mean": g["probe_best_over"].mean(),
        "probe_best_restart_mean": g["probe_best_restart"].mean(),
    })

summary = pd.DataFrame(summary_rows).sort_values(["level", "condition"]).reset_index(drop=True)
pd.set_option("display.max_columns", None)
pd.set_option("display.width", 180)
print(summary.to_string(index=False))

print("\nDone.")

# M-CLTR controller-isolation test
# Four exact conditions:
#   C1 normal k0 / hidden recipe
#   C2 perfect k0 / hidden recipe
#   C3 normal k0 / visible recipe
#   C4 perfect k0 / visible recipe
#
# Modes:
#   continue, restart, project overwrite, adaptive overwrite,
#   heuristic evaluator-controller, oracle controller
#
# Goal:
#   isolate whether M-CLTR's control layer works once knowledge is fixed,
#   and whether recipe visibility matters.

import math
import random
import time
from typing import Dict, Tuple, Optional, List

import numpy as np
import pandas as pd
import torch
import torch.nn as nn
import torch.nn.functional as F

# -----------------------------
# Device / reproducibility
# -----------------------------
DEVICE = torch.device("cuda" if torch.cuda.is_available() else "cpu")
print("Device:", DEVICE)

def set_seed(seed: int) -> None:
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    if torch.cuda.is_available():
        torch.cuda.manual_seed_all(seed)

# Optional speed-up
torch.set_float32_matmul_precision("high")

# -----------------------------
# Config
# -----------------------------
NUM_VALUES = 10
NUM_CLASSES = 10
OP_DIM = 2

SEQ_LEN = 5
T = SEQ_LEN

# Base sees numbers + start mode only
BASE_X_DIM = SEQ_LEN * NUM_VALUES + OP_DIM

# Reasoner dimensions
K_DIM = NUM_CLASSES       # lets "perfect k0" be an exact one-hot target hint
Z_DIM = 64
STEP_INP_DIM = NUM_VALUES + OP_DIM

SEEDS = [7, 17]

BASE_EPOCHS = 4
REASONER_EPOCHS = 4
EVAL_EPOCHS = 2

BASE_STEPS_PER_EPOCH = 20
REASONER_STEPS_PER_EPOCH = 20
EVAL_STEPS_PER_EPOCH = 16

BATCH_SIZE = 128
EVAL_BATCHES = 6
ORACLE_BATCHES = 3

LR_BASE = 2e-3
LR_REASONER = 2e-3
LR_EVAL = 2e-3

# Four levels, matching the recent control tests
LEVEL_SPECS = {
    0: {"name": "no switch / clean",            "switch_step": T,      "input_noise": 0.00, "corrupt_step": None, "corrupt_severity": 0.00},
    1: {"name": "mid switch / mild corruption", "switch_step": T // 2, "input_noise": 0.00, "corrupt_step": None, "corrupt_severity": 0.00},
    2: {"name": "early switch / medium corruption", "switch_step": 1,   "input_noise": 0.00, "corrupt_step": None, "corrupt_severity": 0.00},
    3: {"name": "mid switch / strong corruption",  "switch_step": T // 2, "input_noise": 0.10, "corrupt_step": 2,    "corrupt_severity": 0.35},
}

CONDITIONS = [
    ("normal",  False, "C1 normal k0 / hidden recipe"),
    ("perfect", False, "C2 perfect k0 / hidden recipe"),
    ("normal",  True,  "C3 normal k0 / visible recipe"),
    ("perfect", True,  "C4 perfect k0 / visible recipe"),
]

# Main overwrite families to compare
OVERWRITE_SPECS = {
    "project": ("project", 4.0),
    "adaptive": ("adaptive_project", (0.20, 0.90)),
}

# Heuristic controller thresholds over evaluator score
HEURISTIC_LOW = 0.45
HEURISTIC_HIGH = 0.75

# -----------------------------
# Helpers
# -----------------------------
def one_hot(v: torch.Tensor, n: int) -> torch.Tensor:
    return F.one_hot(v.long(), n).float()

def step_feature(t: int, batch_size: int, device: torch.device) -> torch.Tensor:
    s = 0.0 if T <= 1 else float(t) / float(T - 1)
    return torch.full((batch_size, 1), s, device=device)

def mean_std(values):
    arr = np.asarray(values, dtype=np.float64)
    if arr.size == 1:
        return float(arr.item()), 0.0
    return float(arr.mean()), float(arr.std(ddof=1))

def sample_indices(n: int, batch_size: int) -> torch.Tensor:
    return torch.randint(0, n, (batch_size,), device=DEVICE)

def level_name(level: int) -> str:
    return LEVEL_SPECS[level]["name"]

def spec_to_str(spec: Tuple):
    kind, arg = spec
    if kind == "project":
        return f"project(max_shift={float(arg):.1f})"
    if kind == "adaptive_project":
        lo, hi = arg
        return f"adaptive_project({lo:.2f},{hi:.2f})"
    return f"{kind}({arg})"

def inject_mistake(z: torch.Tensor, severity: float) -> torch.Tensor:
    if severity <= 0:
        return z
    rolled = torch.roll(z, shifts=1, dims=-1)
    mixed = (1.0 - severity) * z + severity * rolled
    mixed = mixed + (0.50 * severity) * torch.randn_like(z)
    return mixed

def encode_base_input(nums: torch.Tensor, start_mode: torch.Tensor) -> torch.Tensor:
    nums_oh = one_hot(nums, NUM_VALUES).reshape(nums.size(0), -1)
    start_oh = one_hot(start_mode, OP_DIM)
    x = torch.cat([nums_oh, start_oh], dim=-1)
    return x

def task_value(nums: torch.Tensor, mode_seq: torch.Tensor) -> torch.Tensor:
    acc = nums[:, 0]
    for t in range(1, T):
        mode = mode_seq[:, t]
        add = (acc + nums[:, t]) % NUM_VALUES
        mul = (acc * nums[:, t]) % NUM_VALUES
        acc = torch.where(mode == 0, add, mul)
    return acc.long()

def make_batch(batch_size: int, level: int):
    spec = LEVEL_SPECS[level]
    nums = torch.randint(0, NUM_VALUES, (batch_size, T), device=DEVICE)
    start_mode = torch.randint(0, 2, (batch_size,), device=DEVICE)

    switch_step = spec["switch_step"]
    end_mode = start_mode.clone() if switch_step >= T else (1 - start_mode)

    t_ids = torch.arange(T, device=DEVICE).unsqueeze(0).expand(batch_size, T)
    mode_seq = torch.where(t_ids < switch_step, start_mode.unsqueeze(1), end_mode.unsqueeze(1))

    target = task_value(nums, mode_seq)
    x_base = encode_base_input(nums, start_mode)

    # optional light input noise on the hardest level
    if spec["input_noise"] > 0:
        x_base = torch.clamp(x_base + spec["input_noise"] * torch.randn_like(x_base), 0.0, 1.0)

    start_ctrl = one_hot(start_mode, OP_DIM)
    return nums, mode_seq, x_base, start_ctrl, target

def build_step_input(nums: torch.Tensor, mode_seq: torch.Tensor, recipe_visible: bool, t: int) -> torch.Tensor:
    num_oh = one_hot(nums[:, t], NUM_VALUES)
    if recipe_visible:
        mode_oh = one_hot(mode_seq[:, t], OP_DIM)
    else:
        mode_oh = torch.zeros(nums.size(0), OP_DIM, device=nums.device)
    return torch.cat([num_oh, mode_oh], dim=-1)

def set_requires_grad(module: nn.Module, flag: bool):
    for p in module.parameters():
        p.requires_grad = flag

# -----------------------------
# Models
# -----------------------------
class MLP(nn.Module):
    def __init__(self, in_dim: int, out_dim: int, hidden: int = 128):
        super().__init__()
        self.net = nn.Sequential(
            nn.Linear(in_dim, hidden),
            nn.GELU(),
            nn.Linear(hidden, hidden),
            nn.GELU(),
            nn.Linear(hidden, out_dim),
        )
        for m in self.modules():
            if isinstance(m, nn.Linear):
                nn.init.xavier_uniform_(m.weight)
                if m.bias is not None:
                    nn.init.zeros_(m.bias)

    def forward(self, x):
        return self.net(x)

class BaseModel(nn.Module):
    def __init__(self):
        super().__init__()
        self.encoder = nn.Sequential(
            nn.Linear(BASE_X_DIM, 128),
            nn.GELU(),
            nn.Linear(128, K_DIM),
            nn.LayerNorm(K_DIM),
        )
        self.classifier = nn.Sequential(
            nn.Linear(K_DIM, 64),
            nn.GELU(),
            nn.Linear(64, NUM_CLASSES),
        )
        for m in self.modules():
            if isinstance(m, nn.Linear):
                nn.init.xavier_uniform_(m.weight)
                if m.bias is not None:
                    nn.init.zeros_(m.bias)

    def encode(self, x: torch.Tensor) -> torch.Tensor:
        return self.encoder(x)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.classifier(self.encode(x))

class Reasoner(nn.Module):
    def __init__(self):
        super().__init__()
        self.init_net = MLP(K_DIM + OP_DIM, Z_DIM, hidden=128)
        self.trans_net = MLP(Z_DIM + K_DIM + STEP_INP_DIM + 1, Z_DIM, hidden=128)
        self.evaluator = MLP(Z_DIM + K_DIM + STEP_INP_DIM + 1, 1, hidden=96)
        self.decoder = nn.Linear(Z_DIM, NUM_CLASSES)
        self.z_norm = nn.LayerNorm(Z_DIM)

        for m in self.modules():
            if isinstance(m, nn.Linear):
                nn.init.xavier_uniform_(m.weight)
                if m.bias is not None:
                    nn.init.zeros_(m.bias)

    def init_state(self, k0: torch.Tensor, start_ctrl: torch.Tensor) -> torch.Tensor:
        z0 = self.init_net(torch.cat([k0, start_ctrl], dim=-1))
        return self.z_norm(z0)

    def step_update(self, z: torch.Tensor, k0: torch.Tensor, step_inp: torch.Tensor, t: int) -> torch.Tensor:
        step = step_feature(t, z.size(0), z.device)
        inp = torch.cat([z, k0, step_inp, step], dim=-1)
        delta = torch.tanh(self.trans_net(inp))
        cand = self.z_norm(0.85 * z + 0.15 * delta)
        return cand

    def eval_score(self, z: torch.Tensor, k0: torch.Tensor, step_inp: torch.Tensor, t: int) -> torch.Tensor:
        step = step_feature(t, z.size(0), z.device)
        inp = torch.cat([z, k0, step_inp, step], dim=-1)
        return torch.sigmoid(self.evaluator(inp)).squeeze(-1)

    def decode(self, z: torch.Tensor) -> torch.Tensor:
        return self.decoder(z)

# -----------------------------
# Overwrite operators
# -----------------------------
def project_overwrite(cand: torch.Tensor, z0: torch.Tensor, max_shift: float) -> torch.Tensor:
    delta = cand - z0
    delta_norm = delta.norm(dim=-1, keepdim=True).clamp_min(1e-6)
    scale = torch.clamp(torch.full_like(delta_norm, max_shift) / delta_norm, max=1.0)
    return z0 + delta * scale

def adaptive_project_overwrite(
    reasoner: Reasoner,
    cand: torch.Tensor,
    z0: torch.Tensor,
    k0: torch.Tensor,
    step_inp: torch.Tensor,
    t: int,
    lo: float,
    hi: float,
) -> torch.Tensor:
    score = reasoner.eval_score(cand, k0, step_inp, t).clamp(0.0, 1.0)

    # score-aware blend and score-aware cap
    mix = lo + (hi - lo) * score
    mix = mix.clamp(0.05, 0.95).unsqueeze(-1)

    blended = mix * cand + (1.0 - mix) * z0
    max_shift = (1.0 + 4.0 * score).unsqueeze(-1)

    delta = blended - z0
    delta_norm = delta.norm(dim=-1, keepdim=True).clamp_min(1e-6)
    scale = torch.clamp(max_shift / delta_norm, max=1.0)
    return z0 + delta * scale

def apply_overwrite(
    reasoner: Reasoner,
    cand: torch.Tensor,
    z0: torch.Tensor,
    k0: torch.Tensor,
    step_inp: torch.Tensor,
    t: int,
    spec: Tuple,
) -> torch.Tensor:
    kind, arg = spec
    if kind == "project":
        return reasoner.z_norm(project_overwrite(cand, z0, float(arg)))
    if kind == "adaptive_project":
        lo, hi = arg
        return reasoner.z_norm(adaptive_project_overwrite(reasoner, cand, z0, k0, step_inp, t, float(lo), float(hi)))
    raise ValueError(f"Unknown overwrite spec: {spec}")

# -----------------------------
# Rollout helpers
# -----------------------------
@torch.no_grad()
def continue_rollout_from_state(
    reasoner: Reasoner,
    z_start: torch.Tensor,
    k0: torch.Tensor,
    nums: torch.Tensor,
    mode_seq: torch.Tensor,
    recipe_visible: bool,
    start_t: int,
    level: int,
) -> torch.Tensor:
    spec = LEVEL_SPECS[level]
    z = z_start
    for t in range(start_t, T):
        step_inp = build_step_input(nums, mode_seq, recipe_visible, t)
        z = reasoner.step_update(z, k0, step_inp, t)
        if spec["corrupt_step"] is not None and t == spec["corrupt_step"]:
            z = inject_mistake(z, spec["corrupt_severity"])
    return z

@torch.no_grad()
def final_target_prob_from_state(
    reasoner: Reasoner,
    z_start: torch.Tensor,
    k0: torch.Tensor,
    nums: torch.Tensor,
    mode_seq: torch.Tensor,
    recipe_visible: bool,
    start_t: int,
    target: torch.Tensor,
    level: int,
) -> torch.Tensor:
    z_final = continue_rollout_from_state(
        reasoner, z_start, k0, nums, mode_seq, recipe_visible, start_t, level
    )
    logits = reasoner.decode(z_final)
    probs = F.softmax(logits, dim=-1)
    return probs.gather(1, target.unsqueeze(1)).squeeze(1)

@torch.no_grad()
def choose_oracle_action(
    reasoner: Reasoner,
    cand: torch.Tensor,
    z0: torch.Tensor,
    k0: torch.Tensor,
    nums: torch.Tensor,
    mode_seq: torch.Tensor,
    recipe_visible: bool,
    t: int,
    target: torch.Tensor,
    overwrite_spec: Tuple,
    level: int,
):
    step_inp = build_step_input(nums, mode_seq, recipe_visible, t)

    cont_state = cand
    over_state = apply_overwrite(reasoner, cand, z0, k0, step_inp, t, overwrite_spec)
    rest_state = z0

    p_cont = final_target_prob_from_state(reasoner, cont_state, k0, nums, mode_seq, recipe_visible, t + 1, target, level)
    p_over = final_target_prob_from_state(reasoner, over_state, k0, nums, mode_seq, recipe_visible, t + 1, target, level)
    p_rest = final_target_prob_from_state(reasoner, rest_state, k0, nums, mode_seq, recipe_visible, t + 1, target, level)

    probs = torch.stack([p_cont, p_over, p_rest], dim=-1)
    tie_bias = torch.tensor([2e-3, 1e-3, 0.0], device=probs.device).unsqueeze(0)
    action = (probs + tie_bias).argmax(dim=-1)
    return action, probs

@torch.no_grad()
def run_rollout(
    reasoner: Reasoner,
    k0: torch.Tensor,
    start_ctrl: torch.Tensor,
    nums: torch.Tensor,
    mode_seq: torch.Tensor,
    recipe_visible: bool,
    target: torch.Tensor,
    level: int,
    mode: str,
    overwrite_spec: Optional[Tuple] = None,
    low_thr: float = HEURISTIC_LOW,
    high_thr: float = HEURISTIC_HIGH,
):
    z0 = reasoner.init_state(k0, start_ctrl)
    z = z0
    actions = []
    step_probs = []

    for t in range(T):
        step_inp = build_step_input(nums, mode_seq, recipe_visible, t)
        cand = reasoner.step_update(z, k0, step_inp, t)

        spec = LEVEL_SPECS[level]
        if spec["corrupt_step"] is not None and t == spec["corrupt_step"]:
            cand = inject_mistake(cand, spec["corrupt_severity"])

        if mode == "continue":
            action = torch.zeros(k0.size(0), dtype=torch.long, device=k0.device)
            z_next = cand

        elif mode == "restart":
            action = torch.full((k0.size(0),), 2, dtype=torch.long, device=k0.device)
            z_next = z0

        elif mode == "overwrite":
            if overwrite_spec is None:
                raise ValueError("overwrite_spec required for overwrite mode")
            action = torch.ones(k0.size(0), dtype=torch.long, device=k0.device)
            z_next = apply_overwrite(reasoner, cand, z0, k0, step_inp, t, overwrite_spec)

        elif mode == "heuristic":
            if overwrite_spec is None:
                raise ValueError("overwrite_spec required for heuristic mode")
            score = reasoner.eval_score(cand, k0, step_inp, t)
            action = torch.where(
                score < low_thr,
                torch.full_like(score, 2, dtype=torch.long),
                torch.where(
                    score < high_thr,
                    torch.ones_like(score, dtype=torch.long),
                    torch.zeros_like(score, dtype=torch.long),
                ),
            )
            z_next = torch.empty_like(cand)
            cont_mask = action == 0
            over_mask = action == 1
            rest_mask = action == 2
            if cont_mask.any():
                z_next[cont_mask] = cand[cont_mask]
            if over_mask.any():
                z_next[over_mask] = apply_overwrite(
                    reasoner, cand[over_mask], z0[over_mask], k0[over_mask], step_inp[over_mask], t, overwrite_spec
                )
            if rest_mask.any():
                z_next[rest_mask] = z0[rest_mask]

        elif mode == "oracle":
            if overwrite_spec is None:
                raise ValueError("overwrite_spec required for oracle mode")
            action, probs = choose_oracle_action(
                reasoner, cand, z0, k0, nums, mode_seq, recipe_visible, t, target, overwrite_spec, level
            )
            z_next = torch.empty_like(cand)
            cont_mask = action == 0
            over_mask = action == 1
            rest_mask = action == 2
            if cont_mask.any():
                z_next[cont_mask] = cand[cont_mask]
            if over_mask.any():
                z_next[over_mask] = apply_overwrite(
                    reasoner, cand[over_mask], z0[over_mask], k0[over_mask], step_inp[over_mask], t, overwrite_spec
                )
            if rest_mask.any():
                z_next[rest_mask] = z0[rest_mask]
            step_probs.append(probs)

        else:
            raise ValueError(f"Unknown mode: {mode}")

        actions.append(action)
        z = z_next

    logits = reasoner.decode(z)
    pred = logits.argmax(dim=-1)
    final_eval = reasoner.eval_score(z, k0, build_step_input(nums, mode_seq, recipe_visible, T - 1), T - 1)

    out = {
        "pred": pred,
        "actions": torch.stack(actions, dim=1),
        "final_eval": final_eval,
        "z0": z0,
    }
    if mode == "oracle":
        out["step_probs"] = torch.stack(step_probs, dim=1)
    return out

# -----------------------------
# Training
# -----------------------------
def train_base(base: BaseModel, epochs: int, steps_per_epoch: int):
    base.train()
    opt = torch.optim.AdamW(base.parameters(), lr=LR_BASE, weight_decay=1e-4)
    ce = nn.CrossEntropyLoss()

    print("\n=== Stage 1: base pretraining (numbers + start mode only) ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_acc = 0.0
        for _ in range(steps_per_epoch):
            level = random.choice(list(LEVEL_SPECS.keys()))
            nums, mode_seq, x_base, start_ctrl, target = make_batch(BATCH_SIZE, level)
            logits = base(x_base)
            loss = ce(logits, target)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(base.parameters(), 1.0)
            opt.step()

            total_loss += loss.item()
            total_acc += (logits.argmax(dim=-1) == target).float().mean().item()

        print(f"Base epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} | acc {total_acc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s")

def train_reasoner(base: BaseModel, reasoner: Reasoner, epochs: int, steps_per_epoch: int):
    base.eval()
    set_requires_grad(base, False)
    set_requires_grad(reasoner, True)

    params = list(reasoner.init_net.parameters()) + list(reasoner.trans_net.parameters()) + list(reasoner.decoder.parameters()) + list(reasoner.z_norm.parameters())
    opt = torch.optim.AdamW(params, lr=2e-3, weight_decay=1e-4)
    ce = nn.CrossEntropyLoss()

    print("\n=== Stage 2: reasoner pretraining (continue-only rollouts) ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_acc = 0.0

        for _ in range(steps_per_epoch):
            level = random.choice(list(LEVEL_SPECS.keys()))
            recipe_visible = (random.random() < 0.5)
            use_perfect_k0 = (random.random() < 0.30)

            nums, mode_seq, x_base, start_ctrl, target = make_batch(BATCH_SIZE, level)

            with torch.no_grad():
                if use_perfect_k0:
                    k0 = one_hot(target, NUM_CLASSES).to(DEVICE)
                else:
                    k0 = base.encode(x_base)

            z = reasoner.init_state(k0, start_ctrl)
            for t in range(T):
                step_inp = build_step_input(nums, mode_seq, recipe_visible, t)
                z = reasoner.step_update(z, k0, step_inp, t)

                spec = LEVEL_SPECS[level]
                if spec["corrupt_step"] is not None and t == spec["corrupt_step"]:
                    z = inject_mistake(z, spec["corrupt_severity"])

            logits = reasoner.decode(z)
            loss = ce(logits, target)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(params, 1.0)
            opt.step()

            total_loss += loss.item()
            total_acc += (logits.argmax(dim=-1) == target).float().mean().item()

        print(f"Reasoner epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} | acc {total_acc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s")

def train_evaluator(base: BaseModel, reasoner: Reasoner, epochs: int, steps_per_epoch: int):
    base.eval()
    reasoner.eval()
    set_requires_grad(base, False)
    set_requires_grad(reasoner, False)
    set_requires_grad(reasoner.evaluator, True)

    opt = torch.optim.AdamW(reasoner.evaluator.parameters(), lr=LR_EVAL, weight_decay=1e-4)
    mse = nn.MSELoss()

    print("\n=== Stage 3: evaluator training (predict downstream correctness) ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_binacc = 0.0

        for _ in range(steps_per_epoch):
            level = random.choice(list(LEVEL_SPECS.keys()))
            recipe_visible = (random.random() < 0.5)
            use_perfect_k0 = (random.random() < 0.30)

            nums, mode_seq, x_base, start_ctrl, target = make_batch(BATCH_SIZE, level)

            with torch.no_grad():
                if use_perfect_k0:
                    k0 = one_hot(target, NUM_CLASSES).to(DEVICE)
                else:
                    k0 = base.encode(x_base)

                z = reasoner.init_state(k0, start_ctrl)

                zs, k0s, step_ins, step_ts, labels = [], [], [], [], []
                for t in range(T):
                    step_inp = build_step_input(nums, mode_seq, recipe_visible, t)
                    cand = reasoner.step_update(z, k0, step_inp, t)

                    spec = LEVEL_SPECS[level]
                    if spec["corrupt_step"] is not None and t == spec["corrupt_step"]:
                        cand = inject_mistake(cand, spec["corrupt_severity"])

                    p_target = final_target_prob_from_state(
                        reasoner, cand, k0, nums, mode_seq, recipe_visible, t + 1, target, level
                    )

                    zs.append(cand.detach())
                    k0s.append(k0.detach())
                    step_ins.append(step_inp.detach())
                    step_ts.append(step_feature(t, BATCH_SIZE, DEVICE))
                    labels.append(p_target.detach())

                    z = cand

                zs = torch.cat(zs, dim=0)
                k0s = torch.cat(k0s, dim=0)
                step_ins = torch.cat(step_ins, dim=0)
                step_ts = torch.cat(step_ts, dim=0)
                labels = torch.cat(labels, dim=0).clamp(0.0, 1.0)

            inp = torch.cat([zs, k0s, step_ins, step_ts], dim=-1)
            pred = torch.sigmoid(reasoner.evaluator(inp)).squeeze(-1)
            loss = mse(pred, labels)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(reasoner.evaluator.parameters(), 1.0)
            opt.step()

            total_loss += loss.item()
            total_binacc += ((pred > 0.5) == (labels > 0.5)).float().mean().item()

        print(f"Evaluator epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} | bin-acc {total_binacc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s")

# -----------------------------
# Evaluation
# -----------------------------
@torch.no_grad()
def eval_condition(
    base: BaseModel,
    reasoner: Reasoner,
    level: int,
    k0_type: str,
    recipe_visible: bool,
    mode: str,
    overwrite_spec: Optional[Tuple] = None,
    batches: int = EVAL_BATCHES,
    bs: int = 256,
    low_thr: float = HEURISTIC_LOW,
    high_thr: float = HEURISTIC_HIGH,
):
    base.eval()
    reasoner.eval()

    total = 0
    correct = 0
    action_counts = torch.zeros(3, device=DEVICE)
    score_correct = []
    score_incorrect = []

    for _ in range(batches):
        nums, mode_seq, x_base, start_ctrl, target = make_batch(bs, level)

        with torch.no_grad():
            if k0_type == "perfect":
                k0 = one_hot(target, NUM_CLASSES).to(DEVICE)
            else:
                k0 = base.encode(x_base)

        out = run_rollout(
            reasoner=reasoner,
            k0=k0,
            start_ctrl=start_ctrl,
            nums=nums,
            mode_seq=mode_seq,
            recipe_visible=recipe_visible,
            target=target,
            level=level,
            mode=mode,
            overwrite_spec=overwrite_spec,
            low_thr=low_thr,
            high_thr=high_thr,
        )

        pred = out["pred"]
        correct_mask = pred == target
        correct += correct_mask.sum().item()
        total += target.numel()

        if mode in ("heuristic", "oracle"):
            action_counts += torch.stack([
                (out["actions"] == 0).sum(),
                (out["actions"] == 1).sum(),
                (out["actions"] == 2).sum(),
            ]).float()

        score = out["final_eval"]
        if correct_mask.any():
            score_correct.append(score[correct_mask].mean().item())
        if (~correct_mask).any():
            score_incorrect.append(score[~correct_mask].mean().item())

    result = {
        "acc": correct / total,
        "score_correct_mean": float(np.mean(score_correct)) if len(score_correct) else float("nan"),
        "score_incorrect_mean": float(np.mean(score_incorrect)) if len(score_incorrect) else float("nan"),
    }

    if mode in ("heuristic", "oracle"):
        rates = (action_counts / (batches * bs * T)).detach().cpu().numpy()
        result["continue_rate"] = float(rates[0])
        result["overwrite_rate"] = float(rates[1])
        result["restart_rate"] = float(rates[2])

    return result

# -----------------------------
# One seed run
# -----------------------------
def run_one_seed(seed: int):
    set_seed(seed)
    print("\n\n##############################")
    print(f"Seed = {seed}")
    print("##############################")

    base = BaseModel().to(DEVICE)
    reasoner = Reasoner().to(DEVICE)

    # Stage 1: base pretraining
    train_base(base, BASE_EPOCHS, BASE_STEPS_PER_EPOCH)

    # Stage 2: reasoner pretraining (mixed hidden/visible recipes, mixed normal/perfect k0)
    train_reasoner(base, reasoner, REASONER_EPOCHS, REASONER_STEPS_PER_EPOCH)

    # Stage 3: evaluator training
    train_evaluator(base, reasoner, EVAL_EPOCHS, EVAL_STEPS_PER_EPOCH)

    rows = []

    for level in LEVEL_SPECS.keys():
        for k0_type, recipe_visible, cond_name in CONDITIONS:
            # Baselines
            cont = eval_condition(base, reasoner, level, k0_type, recipe_visible, mode="continue")
            rest = eval_condition(base, reasoner, level, k0_type, recipe_visible, mode="restart")
            proj = eval_condition(base, reasoner, level, k0_type, recipe_visible, mode="overwrite", overwrite_spec=OVERWRITE_SPECS["project"])
            adap = eval_condition(base, reasoner, level, k0_type, recipe_visible, mode="overwrite", overwrite_spec=OVERWRITE_SPECS["adaptive"])
            heur = eval_condition(base, reasoner, level, k0_type, recipe_visible, mode="heuristic", overwrite_spec=OVERWRITE_SPECS["adaptive"])
            oracle = eval_condition(base, reasoner, level, k0_type, recipe_visible, mode="oracle", overwrite_spec=OVERWRITE_SPECS["adaptive"], batches=ORACLE_BATCHES, bs=128)

            rows.append({
                "seed": seed,
                "level": level,
                "level_name": level_name(level),
                "condition": cond_name,
                "continue_acc": cont["acc"],
                "restart_acc": rest["acc"],
                "project_acc": proj["acc"],
                "adaptive_acc": adap["acc"],
                "heuristic_acc": heur["acc"],
                "oracle_acc": oracle["acc"],
                "heuristic_continue_rate": heur["continue_rate"],
                "heuristic_overwrite_rate": heur["overwrite_rate"],
                "heuristic_restart_rate": heur["restart_rate"],
                "oracle_continue_rate": oracle["continue_rate"],
                "oracle_overwrite_rate": oracle["overwrite_rate"],
                "oracle_restart_rate": oracle["restart_rate"],
                "heuristic_score_correct": heur["score_correct_mean"],
                "heuristic_score_incorrect": heur["score_incorrect_mean"],
                "oracle_score_correct": oracle["score_correct_mean"],
                "oracle_score_incorrect": oracle["score_incorrect_mean"],
                "score_gap": (
                    cont["score_correct_mean"] - cont["score_incorrect_mean"]
                    if (not math.isnan(cont["score_correct_mean"]) and not math.isnan(cont["score_incorrect_mean"]))
                    else float("nan")
                ),
            })

            print(f"\n--- Seed {seed} | Level {level} ({level_name(level)}) | {cond_name} ---")
            print(f"Continue-only acc : {cont['acc']:.4f}")
            print(f"Restart-only acc  : {rest['acc']:.4f}")
            print(f"Project overwrite  : {proj['acc']:.4f}")
            print(f"Adaptive overwrite : {adap['acc']:.4f}")
            print(f"Heuristic ctrl acc : {heur['acc']:.4f}")
            print(f"Oracle ctrl acc    : {oracle['acc']:.4f}")
            print(f"Heuristic C/O/R    : {heur['continue_rate']:.3f}/{heur['overwrite_rate']:.3f}/{heur['restart_rate']:.3f}")
            print(f"Oracle C/O/R       : {oracle['continue_rate']:.3f}/{oracle['overwrite_rate']:.3f}/{oracle['restart_rate']:.3f}")
            print(f"Heuristic score gap: {heur['score_correct_mean'] - heur['score_incorrect_mean'] if not (math.isnan(heur['score_correct_mean']) or math.isnan(heur['score_incorrect_mean'])) else float('nan'):.4f}")

    return pd.DataFrame(rows)

# -----------------------------
# Run
# -----------------------------
all_rows = []
for seed in SEEDS:
    df_seed = run_one_seed(seed)
    all_rows.append(df_seed)

df = pd.concat(all_rows, ignore_index=True)

print("\n\n==============================")
print("Raw results")
print("==============================")
pd.set_option("display.max_columns", None)
pd.set_option("display.width", 180)
print(df.round(4).to_string(index=False))

# -----------------------------
# Summary tables
# -----------------------------
cond_summary = (
    df.groupby(["condition"], as_index=False)
      .agg(
          continue_acc_mean=("continue_acc", "mean"),
          continue_acc_std=("continue_acc", "std"),
          restart_acc_mean=("restart_acc", "mean"),
          restart_acc_std=("restart_acc", "std"),
          project_acc_mean=("project_acc", "mean"),
          project_acc_std=("project_acc", "std"),
          adaptive_acc_mean=("adaptive_acc", "mean"),
          adaptive_acc_std=("adaptive_acc", "std"),
          heuristic_acc_mean=("heuristic_acc", "mean"),
          heuristic_acc_std=("heuristic_acc", "std"),
          oracle_acc_mean=("oracle_acc", "mean"),
          oracle_acc_std=("oracle_acc", "std"),
          heuristic_continue_rate=("heuristic_continue_rate", "mean"),
          heuristic_overwrite_rate=("heuristic_overwrite_rate", "mean"),
          heuristic_restart_rate=("heuristic_restart_rate", "mean"),
          oracle_continue_rate=("oracle_continue_rate", "mean"),
          oracle_overwrite_rate=("oracle_overwrite_rate", "mean"),
          oracle_restart_rate=("oracle_restart_rate", "mean"),
      )
)

level_summary = (
    df.groupby(["level", "level_name", "condition"], as_index=False)
      .agg(
          continue_acc_mean=("continue_acc", "mean"),
          restart_acc_mean=("restart_acc", "mean"),
          project_acc_mean=("project_acc", "mean"),
          adaptive_acc_mean=("adaptive_acc", "mean"),
          heuristic_acc_mean=("heuristic_acc", "mean"),
          oracle_acc_mean=("oracle_acc", "mean"),
          score_gap_mean=("score_gap", "mean"),
          heuristic_continue_rate=("heuristic_continue_rate", "mean"),
          heuristic_overwrite_rate=("heuristic_overwrite_rate", "mean"),
          heuristic_restart_rate=("heuristic_restart_rate", "mean"),
          oracle_continue_rate=("oracle_continue_rate", "mean"),
          oracle_overwrite_rate=("oracle_overwrite_rate", "mean"),
          oracle_restart_rate=("oracle_restart_rate", "mean"),
      )
)

print("\n\n==============================")
print("Aggregated summary by condition")
print("==============================")
print(cond_summary.round(4).to_string(index=False))

print("\n\n==============================")
print("Aggregated summary by level and condition")
print("==============================")
print(level_summary.round(4).to_string(index=False))

print("\nDone.")

# M-CLTR controller-only stress test
# Goal:
#   isolate whether a simple evaluator-based controller can improve over continue
#   when knowledge is fixed to the harder, non-trivial setting:
#       normal k0 + hidden recipe
#
# What this run does:
#   1) trains a base model on the task
#   2) trains a reasoner with continue-only rollouts
#   3) trains an evaluator to predict downstream correctness
#   4) searches for the best heuristic thresholds on a small validation slice
#   5) evaluates continue / restart / project / adaptive / heuristic / oracle
#      on all difficulty levels
#
# Output:
#   compact tables only

import math
import random
import time
from typing import Dict, Tuple, Optional, List

import numpy as np
import pandas as pd
import torch
import torch.nn as nn
import torch.nn.functional as F

# -----------------------------
# Device / reproducibility
# -----------------------------
DEVICE = torch.device("cuda" if torch.cuda.is_available() else "cpu")
print("Device:", DEVICE)
torch.set_float32_matmul_precision("high")

def set_seed(seed: int) -> None:
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    if torch.cuda.is_available():
        torch.cuda.manual_seed_all(seed)

# -----------------------------
# Config
# -----------------------------
NUM_VALUES = 10
NUM_CLASSES = 10
OP_DIM = 2

SEQ_LEN = 5
T = SEQ_LEN

BASE_X_DIM = SEQ_LEN * NUM_VALUES + OP_DIM
STEP_INP_DIM = NUM_VALUES + OP_DIM

K_DIM = NUM_CLASSES
Z_DIM = 64

SEEDS = [7, 17]

BASE_EPOCHS = 4
REASONER_EPOCHS = 4
EVAL_EPOCHS = 2

BASE_STEPS_PER_EPOCH = 20
REASONER_STEPS_PER_EPOCH = 20
EVAL_STEPS_PER_EPOCH = 16

BATCH_SIZE = 128
EVAL_BATCHES = 6
ORACLE_BATCHES = 3

LR_BASE = 2e-3
LR_REASONER = 2e-3
LR_EVAL = 2e-3

LEVEL_SPECS = {
    0: {"name": "no switch / clean",               "switch_step": T,      "input_noise": 0.00, "corrupt_step": None, "corrupt_severity": 0.00},
    1: {"name": "mid switch / mild corruption",    "switch_step": T // 2, "input_noise": 0.00, "corrupt_step": None, "corrupt_severity": 0.00},
    2: {"name": "early switch / medium corruption","switch_step": 1,      "input_noise": 0.00, "corrupt_step": None, "corrupt_severity": 0.00},
    3: {"name": "mid switch / strong corruption",  "switch_step": T // 2, "input_noise": 0.10, "corrupt_step": 2,    "corrupt_severity": 0.35},
}

# Single condition only:
# normal knowledge + hidden recipe
RECIPE_VISIBLE = False

OVERWRITE_SPECS = {
    "project": ("project", 4.0),
    "adaptive": ("adaptive_project", (0.20, 0.90)),
}

HEURISTIC_LOW_GRID = [0.30, 0.35, 0.40, 0.45, 0.50]
HEURISTIC_HIGH_GRID = [0.60, 0.70, 0.80, 0.90]

# -----------------------------
# Helpers
# -----------------------------
def one_hot(v: torch.Tensor, n: int) -> torch.Tensor:
    return F.one_hot(v.long(), n).float()

def step_feature(t: int, batch_size: int, device: torch.device) -> torch.Tensor:
    s = 0.0 if T <= 1 else float(t) / float(T - 1)
    return torch.full((batch_size, 1), s, device=device)

def mean_std(values):
    arr = np.asarray(values, dtype=np.float64)
    if arr.size == 1:
        return float(arr.item()), 0.0
    return float(arr.mean()), float(arr.std(ddof=1))

def sample_indices(n: int, batch_size: int) -> torch.Tensor:
    return torch.randint(0, n, (batch_size,), device=DEVICE)

def level_name(level: int) -> str:
    return LEVEL_SPECS[level]["name"]

def spec_to_str(spec: Tuple):
    kind, arg = spec
    if kind == "project":
        return f"project(max_shift={float(arg):.1f})"
    if kind == "adaptive_project":
        lo, hi = arg
        return f"adaptive_project({lo:.2f},{hi:.2f})"
    return f"{kind}({arg})"

def inject_mistake(z: torch.Tensor, severity: float) -> torch.Tensor:
    if severity <= 0:
        return z
    rolled = torch.roll(z, shifts=1, dims=-1)
    mixed = (1.0 - severity) * z + severity * rolled
    mixed = mixed + (0.50 * severity) * torch.randn_like(z)
    return mixed

def set_requires_grad(module: nn.Module, flag: bool):
    for p in module.parameters():
        p.requires_grad = flag

def encode_base_input(nums: torch.Tensor, start_mode: torch.Tensor) -> torch.Tensor:
    nums_oh = one_hot(nums, NUM_VALUES).reshape(nums.size(0), -1)
    start_oh = one_hot(start_mode, OP_DIM)
    return torch.cat([nums_oh, start_oh], dim=-1)

def task_value(nums: torch.Tensor, mode_seq: torch.Tensor) -> torch.Tensor:
    acc = nums[:, 0]
    for t in range(1, T):
        mode = mode_seq[:, t]
        add = (acc + nums[:, t]) % NUM_VALUES
        mul = (acc * nums[:, t]) % NUM_VALUES
        acc = torch.where(mode == 0, add, mul)
    return acc.long()

def make_batch(batch_size: int, level: int):
    spec = LEVEL_SPECS[level]
    nums = torch.randint(0, NUM_VALUES, (batch_size, T), device=DEVICE)
    start_mode = torch.randint(0, 2, (batch_size,), device=DEVICE)

    switch_step = spec["switch_step"]
    end_mode = start_mode.clone() if switch_step >= T else (1 - start_mode)

    t_ids = torch.arange(T, device=DEVICE).unsqueeze(0).expand(batch_size, T)
    mode_seq = torch.where(t_ids < switch_step, start_mode.unsqueeze(1), end_mode.unsqueeze(1))

    target = task_value(nums, mode_seq)
    x_base = encode_base_input(nums, start_mode)

    if spec["input_noise"] > 0:
        x_base = torch.clamp(x_base + spec["input_noise"] * torch.randn_like(x_base), 0.0, 1.0)

    start_ctrl = one_hot(start_mode, OP_DIM)
    return nums, mode_seq, x_base, start_ctrl, target

def build_step_input(nums: torch.Tensor, mode_seq: torch.Tensor, t: int) -> torch.Tensor:
    num_oh = one_hot(nums[:, t], NUM_VALUES)
    mode_oh = torch.zeros(nums.size(0), OP_DIM, device=nums.device)  # hidden recipe
    return torch.cat([num_oh, mode_oh], dim=-1)

# -----------------------------
# Models
# -----------------------------
class MLP(nn.Module):
    def __init__(self, in_dim: int, out_dim: int, hidden: int = 128):
        super().__init__()
        self.net = nn.Sequential(
            nn.Linear(in_dim, hidden),
            nn.GELU(),
            nn.Linear(hidden, hidden),
            nn.GELU(),
            nn.Linear(hidden, out_dim),
        )
        for m in self.modules():
            if isinstance(m, nn.Linear):
                nn.init.xavier_uniform_(m.weight)
                if m.bias is not None:
                    nn.init.zeros_(m.bias)

    def forward(self, x):
        return self.net(x)

class BaseModel(nn.Module):
    def __init__(self):
        super().__init__()
        self.encoder = nn.Sequential(
            nn.Linear(BASE_X_DIM, 128),
            nn.GELU(),
            nn.Linear(128, K_DIM),
            nn.LayerNorm(K_DIM),
        )
        self.classifier = nn.Sequential(
            nn.Linear(K_DIM, 64),
            nn.GELU(),
            nn.Linear(64, NUM_CLASSES),
        )
        for m in self.modules():
            if isinstance(m, nn.Linear):
                nn.init.xavier_uniform_(m.weight)
                if m.bias is not None:
                    nn.init.zeros_(m.bias)

    def encode(self, x: torch.Tensor) -> torch.Tensor:
        return self.encoder(x)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.classifier(self.encode(x))

class Reasoner(nn.Module):
    def __init__(self):
        super().__init__()
        self.init_net = MLP(K_DIM + OP_DIM, Z_DIM, hidden=128)
        self.trans_net = MLP(Z_DIM + K_DIM + STEP_INP_DIM + 1, Z_DIM, hidden=128)
        self.evaluator = MLP(Z_DIM + K_DIM + STEP_INP_DIM + 1, 1, hidden=96)
        self.decoder = nn.Linear(Z_DIM, NUM_CLASSES)
        self.z_norm = nn.LayerNorm(Z_DIM)

        for m in self.modules():
            if isinstance(m, nn.Linear):
                nn.init.xavier_uniform_(m.weight)
                if m.bias is not None:
                    nn.init.zeros_(m.bias)

    def init_state(self, k0: torch.Tensor, start_ctrl: torch.Tensor) -> torch.Tensor:
        z0 = self.init_net(torch.cat([k0, start_ctrl], dim=-1))
        return self.z_norm(z0)

    def step_update(self, z: torch.Tensor, k0: torch.Tensor, step_inp: torch.Tensor, t: int) -> torch.Tensor:
        step = step_feature(t, z.size(0), z.device)
        inp = torch.cat([z, k0, step_inp, step], dim=-1)
        delta = torch.tanh(self.trans_net(inp))
        return self.z_norm(0.85 * z + 0.15 * delta)

    def eval_score(self, z: torch.Tensor, k0: torch.Tensor, step_inp: torch.Tensor, t: int) -> torch.Tensor:
        step = step_feature(t, z.size(0), z.device)
        inp = torch.cat([z, k0, step_inp, step], dim=-1)
        return torch.sigmoid(self.evaluator(inp)).squeeze(-1)

    def decode(self, z: torch.Tensor) -> torch.Tensor:
        return self.decoder(z)

# -----------------------------
# Overwrite operators
# -----------------------------
def project_overwrite(cand: torch.Tensor, z0: torch.Tensor, max_shift: float) -> torch.Tensor:
    delta = cand - z0
    delta_norm = delta.norm(dim=-1, keepdim=True).clamp_min(1e-6)
    scale = torch.clamp(torch.full_like(delta_norm, max_shift) / delta_norm, max=1.0)
    return z0 + delta * scale

def adaptive_project_overwrite(
    reasoner: Reasoner,
    cand: torch.Tensor,
    z0: torch.Tensor,
    k0: torch.Tensor,
    step_inp: torch.Tensor,
    t: int,
    lo: float,
    hi: float,
) -> torch.Tensor:
    score = reasoner.eval_score(cand, k0, step_inp, t).clamp(0.0, 1.0)
    mix = lo + (hi - lo) * score
    mix = mix.clamp(0.05, 0.95).unsqueeze(-1)

    blended = mix * cand + (1.0 - mix) * z0
    max_shift = (1.0 + 4.0 * score).unsqueeze(-1)

    delta = blended - z0
    delta_norm = delta.norm(dim=-1, keepdim=True).clamp_min(1e-6)
    scale = torch.clamp(max_shift / delta_norm, max=1.0)
    return z0 + delta * scale

def apply_overwrite(
    reasoner: Reasoner,
    cand: torch.Tensor,
    z0: torch.Tensor,
    k0: torch.Tensor,
    step_inp: torch.Tensor,
    t: int,
    spec: Tuple,
) -> torch.Tensor:
    kind, arg = spec
    if kind == "project":
        return reasoner.z_norm(project_overwrite(cand, z0, float(arg)))
    if kind == "adaptive_project":
        lo, hi = arg
        return reasoner.z_norm(adaptive_project_overwrite(reasoner, cand, z0, k0, step_inp, t, float(lo), float(hi)))
    raise ValueError(f"Unknown overwrite spec: {spec}")

# -----------------------------
# Rollout helpers
# -----------------------------
@torch.no_grad()
def continue_rollout_from_state(
    reasoner: Reasoner,
    z_start: torch.Tensor,
    k0: torch.Tensor,
    nums: torch.Tensor,
    mode_seq: torch.Tensor,
    start_t: int,
    level: int,
) -> torch.Tensor:
    spec = LEVEL_SPECS[level]
    z = z_start
    for t in range(start_t, T):
        step_inp = build_step_input(nums, mode_seq, t)
        z = reasoner.step_update(z, k0, step_inp, t)
        if spec["corrupt_step"] is not None and t == spec["corrupt_step"]:
            z = inject_mistake(z, spec["corrupt_severity"])
    return z

@torch.no_grad()
def final_target_prob_from_state(
    reasoner: Reasoner,
    z_start: torch.Tensor,
    k0: torch.Tensor,
    nums: torch.Tensor,
    mode_seq: torch.Tensor,
    start_t: int,
    target: torch.Tensor,
    level: int,
) -> torch.Tensor:
    z_final = continue_rollout_from_state(reasoner, z_start, k0, nums, mode_seq, start_t, level)
    logits = reasoner.decode(z_final)
    probs = F.softmax(logits, dim=-1)
    return probs.gather(1, target.unsqueeze(1)).squeeze(1)

@torch.no_grad()
def choose_oracle_action(
    reasoner: Reasoner,
    cand: torch.Tensor,
    z0: torch.Tensor,
    k0: torch.Tensor,
    nums: torch.Tensor,
    mode_seq: torch.Tensor,
    t: int,
    target: torch.Tensor,
    overwrite_spec: Tuple,
    level: int,
):
    step_inp = build_step_input(nums, mode_seq, t)

    cont_state = cand
    over_state = apply_overwrite(reasoner, cand, z0, k0, step_inp, t, overwrite_spec)
    rest_state = z0

    p_cont = final_target_prob_from_state(reasoner, cont_state, k0, nums, mode_seq, t + 1, target, level)
    p_over = final_target_prob_from_state(reasoner, over_state, k0, nums, mode_seq, t + 1, target, level)
    p_rest = final_target_prob_from_state(reasoner, rest_state, k0, nums, mode_seq, t + 1, target, level)

    probs = torch.stack([p_cont, p_over, p_rest], dim=-1)
    tie_bias = torch.tensor([2e-3, 1e-3, 0.0], device=probs.device).unsqueeze(0)
    action = (probs + tie_bias).argmax(dim=-1)
    return action, probs

@torch.no_grad()
def run_rollout(
    reasoner: Reasoner,
    k0: torch.Tensor,
    start_ctrl: torch.Tensor,
    nums: torch.Tensor,
    mode_seq: torch.Tensor,
    target: torch.Tensor,
    level: int,
    mode: str,
    overwrite_spec: Optional[Tuple] = None,
    low_thr: float = 0.45,
    high_thr: float = 0.75,
):
    z0 = reasoner.init_state(k0, start_ctrl)
    z = z0
    actions = []
    step_probs = []

    for t in range(T):
        step_inp = build_step_input(nums, mode_seq, t)
        cand = reasoner.step_update(z, k0, step_inp, t)

        spec = LEVEL_SPECS[level]
        if spec["corrupt_step"] is not None and t == spec["corrupt_step"]:
            cand = inject_mistake(cand, spec["corrupt_severity"])

        if mode == "continue":
            action = torch.zeros(k0.size(0), dtype=torch.long, device=k0.device)
            z_next = cand

        elif mode == "restart":
            action = torch.full((k0.size(0),), 2, dtype=torch.long, device=k0.device)
            z_next = z0

        elif mode == "overwrite":
            if overwrite_spec is None:
                raise ValueError("overwrite_spec required for overwrite mode")
            action = torch.ones(k0.size(0), dtype=torch.long, device=k0.device)
            z_next = apply_overwrite(reasoner, cand, z0, k0, step_inp, t, overwrite_spec)

        elif mode == "heuristic":
            if overwrite_spec is None:
                raise ValueError("overwrite_spec required for heuristic mode")
            score = reasoner.eval_score(cand, k0, step_inp, t)
            action = torch.where(
                score < low_thr,
                torch.full_like(score, 2, dtype=torch.long),
                torch.where(
                    score < high_thr,
                    torch.ones_like(score, dtype=torch.long),
                    torch.zeros_like(score, dtype=torch.long),
                ),
            )
            z_next = torch.empty_like(cand)
            cont_mask = action == 0
            over_mask = action == 1
            rest_mask = action == 2
            if cont_mask.any():
                z_next[cont_mask] = cand[cont_mask]
            if over_mask.any():
                z_next[over_mask] = apply_overwrite(reasoner, cand[over_mask], z0[over_mask], k0[over_mask], step_inp[over_mask], t, overwrite_spec)
            if rest_mask.any():
                z_next[rest_mask] = z0[rest_mask]

        elif mode == "oracle":
            if overwrite_spec is None:
                raise ValueError("overwrite_spec required for oracle mode")
            action, probs = choose_oracle_action(reasoner, cand, z0, k0, nums, mode_seq, t, target, overwrite_spec, level)
            z_next = torch.empty_like(cand)
            cont_mask = action == 0
            over_mask = action == 1
            rest_mask = action == 2
            if cont_mask.any():
                z_next[cont_mask] = cand[cont_mask]
            if over_mask.any():
                z_next[over_mask] = apply_overwrite(reasoner, cand[over_mask], z0[over_mask], k0[over_mask], step_inp[over_mask], t, overwrite_spec)
            if rest_mask.any():
                z_next[rest_mask] = z0[rest_mask]
            step_probs.append(probs)

        else:
            raise ValueError(f"Unknown mode: {mode}")

        actions.append(action)
        z = z_next

    logits = reasoner.decode(z)
    pred = logits.argmax(dim=-1)
    final_eval = reasoner.eval_score(z, k0, build_step_input(nums, mode_seq, T - 1), T - 1)

    out = {
        "pred": pred,
        "actions": torch.stack(actions, dim=1),
        "final_eval": final_eval,
        "z0": z0,
    }
    if mode == "oracle":
        out["step_probs"] = torch.stack(step_probs, dim=1)
    return out

# -----------------------------
# Training
# -----------------------------
def train_base(base: BaseModel, epochs: int, steps_per_epoch: int):
    base.train()
    opt = torch.optim.AdamW(base.parameters(), lr=LR_BASE, weight_decay=1e-4)
    ce = nn.CrossEntropyLoss()

    print("\n=== Stage 1: base pretraining (numbers + start mode only) ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_acc = 0.0
        for _ in range(steps_per_epoch):
            level = random.choice(list(LEVEL_SPECS.keys()))
            nums, mode_seq, x_base, start_ctrl, target = make_batch(BATCH_SIZE, level)
            logits = base(x_base)
            loss = ce(logits, target)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(base.parameters(), 1.0)
            opt.step()

            total_loss += loss.item()
            total_acc += (logits.argmax(dim=-1) == target).float().mean().item()

        print(f"Base epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} | acc {total_acc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s")

def train_reasoner(base: BaseModel, reasoner: Reasoner, epochs: int, steps_per_epoch: int):
    reasoner.train()
    set_requires_grad(base, False)
    set_requires_grad(reasoner, True)

    params = list(reasoner.init_net.parameters()) + list(reasoner.trans_net.parameters()) + list(reasoner.decoder.parameters()) + list(reasoner.z_norm.parameters())
    opt = torch.optim.AdamW(params, lr=LR_REASONER, weight_decay=1e-4)
    ce = nn.CrossEntropyLoss()

    print("\n=== Stage 2: reasoner pretraining (continue-only rollouts) ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_acc = 0.0

        for _ in range(steps_per_epoch):
            level = random.choice(list(LEVEL_SPECS.keys()))
            nums, mode_seq, x_base, start_ctrl, target = make_batch(BATCH_SIZE, level)

            with torch.no_grad():
                k0 = base.encode(x_base)

            z = reasoner.init_state(k0, start_ctrl)
            for t in range(T):
                step_inp = build_step_input(nums, mode_seq, t)
                z = reasoner.step_update(z, k0, step_inp, t)

                spec = LEVEL_SPECS[level]
                if spec["corrupt_step"] is not None and t == spec["corrupt_step"]:
                    z = inject_mistake(z, spec["corrupt_severity"])

            logits = reasoner.decode(z)
            loss = ce(logits, target)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(params, 1.0)
            opt.step()

            total_loss += loss.item()
            total_acc += (logits.argmax(dim=-1) == target).float().mean().item()

        print(f"Reasoner epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} | acc {total_acc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s")

def train_evaluator(base: BaseModel, reasoner: Reasoner, epochs: int, steps_per_epoch: int):
    reasoner.eval()
    set_requires_grad(base, False)
    set_requires_grad(reasoner, False)
    set_requires_grad(reasoner.evaluator, True)

    opt = torch.optim.AdamW(reasoner.evaluator.parameters(), lr=LR_EVAL, weight_decay=1e-4)
    mse = nn.MSELoss()

    print("\n=== Stage 3: evaluator training (predict downstream correctness) ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_binacc = 0.0

        for _ in range(steps_per_epoch):
            level = random.choice(list(LEVEL_SPECS.keys()))
            nums, mode_seq, x_base, start_ctrl, target = make_batch(BATCH_SIZE, level)

            with torch.no_grad():
                k0 = base.encode(x_base)
                z = reasoner.init_state(k0, start_ctrl)

                zs, k0s, step_ins, step_ts, labels = [], [], [], [], []

                for t in range(T):
                    step_inp = build_step_input(nums, mode_seq, t)
                    cand = reasoner.step_update(z, k0, step_inp, t)

                    spec = LEVEL_SPECS[level]
                    if spec["corrupt_step"] is not None and t == spec["corrupt_step"]:
                        cand = inject_mistake(cand, spec["corrupt_severity"])

                    p_target = final_target_prob_from_state(
                        reasoner, cand, k0, nums, mode_seq, t + 1, target, level
                    )

                    zs.append(cand.detach())
                    k0s.append(k0.detach())
                    step_ins.append(step_inp.detach())
                    step_ts.append(step_feature(t, BATCH_SIZE, DEVICE))
                    labels.append(p_target.detach())

                    z = cand

                zs = torch.cat(zs, dim=0)
                k0s = torch.cat(k0s, dim=0)
                step_ins = torch.cat(step_ins, dim=0)
                step_ts = torch.cat(step_ts, dim=0)
                labels = torch.cat(labels, dim=0).clamp(0.0, 1.0)

            inp = torch.cat([zs, k0s, step_ins, step_ts], dim=-1)
            pred = torch.sigmoid(reasoner.evaluator(inp)).squeeze(-1)
            loss = mse(pred, labels)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(reasoner.evaluator.parameters(), 1.0)
            opt.step()

            total_loss += loss.item()
            total_binacc += ((pred > 0.5) == (labels > 0.5)).float().mean().item()

        print(f"Evaluator epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} | bin-acc {total_binacc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s")

# -----------------------------
# Evaluation
# -----------------------------
@torch.no_grad()
def eval_mode(
    base: BaseModel,
    reasoner: Reasoner,
    level: int,
    mode: str,
    overwrite_spec: Optional[Tuple] = None,
    batches: int = EVAL_BATCHES,
    bs: int = 256,
    low_thr: float = 0.45,
    high_thr: float = 0.75,
):
    base.eval()
    reasoner.eval()

    total = 0
    correct = 0
    action_counts = torch.zeros(3, device=DEVICE)
    score_correct = []
    score_incorrect = []

    for _ in range(batches):
        nums, mode_seq, x_base, start_ctrl, target = make_batch(bs, level)
        k0 = base.encode(x_base)

        out = run_rollout(
            reasoner=reasoner,
            k0=k0,
            start_ctrl=start_ctrl,
            nums=nums,
            mode_seq=mode_seq,
            target=target,
            level=level,
            mode=mode,
            overwrite_spec=overwrite_spec,
            low_thr=low_thr,
            high_thr=high_thr,
        )

        pred = out["pred"]
        correct_mask = pred == target
        correct += correct_mask.sum().item()
        total += target.numel()

        if mode in ("heuristic", "oracle"):
            action_counts += torch.stack([
                (out["actions"] == 0).sum(),
                (out["actions"] == 1).sum(),
                (out["actions"] == 2).sum(),
            ]).float()

        score = out["final_eval"]
        if correct_mask.any():
            score_correct.append(score[correct_mask].mean().item())
        if (~correct_mask).any():
            score_incorrect.append(score[~correct_mask].mean().item())

    result = {
        "acc": correct / total,
        "score_correct_mean": float(np.mean(score_correct)) if len(score_correct) else float("nan"),
        "score_incorrect_mean": float(np.mean(score_incorrect)) if len(score_incorrect) else float("nan"),
    }

    if mode in ("heuristic", "oracle"):
        rates = (action_counts / (batches * bs * T)).detach().cpu().numpy()
        result["continue_rate"] = float(rates[0])
        result["overwrite_rate"] = float(rates[1])
        result["restart_rate"] = float(rates[2])

    return result

@torch.no_grad()
def search_best_heuristic(base: BaseModel, reasoner: Reasoner):
    # Select thresholds on the harder validation levels only.
    # This avoids picking a threshold that only works on easy cases.
    val_levels = [2, 3]
    best = None

    for lo in HEURISTIC_LOW_GRID:
        for hi in HEURISTIC_HIGH_GRID:
            if lo >= hi:
                continue
            accs = []
            for level in val_levels:
                res = eval_mode(
                    base, reasoner, level=level, mode="heuristic",
                    overwrite_spec=OVERWRITE_SPECS["adaptive"],
                    batches=2, bs=128, low_thr=lo, high_thr=hi
                )
                accs.append(res["acc"])
            mean_acc = float(np.mean(accs))
            if best is None or mean_acc > best["mean_acc"]:
                best = {"low": lo, "high": hi, "mean_acc": mean_acc}
    return best

# -----------------------------
# One seed run
# -----------------------------
def run_one_seed(seed: int):
    set_seed(seed)
    print("\n\n##############################")
    print(f"Seed = {seed}")
    print("##############################")

    base = BaseModel().to(DEVICE)
    reasoner = Reasoner().to(DEVICE)

    train_base(base, BASE_EPOCHS, BASE_STEPS_PER_EPOCH)
    train_reasoner(base, reasoner, REASONER_EPOCHS, REASONER_STEPS_PER_EPOCH)
    train_evaluator(base, reasoner, EVAL_EPOCHS, EVAL_STEPS_PER_EPOCH)

    best_heur = search_best_heuristic(base, reasoner)
    print(f"\nBest heuristic thresholds from validation: low={best_heur['low']:.2f}, high={best_heur['high']:.2f} | val acc={best_heur['mean_acc']:.4f}")

    rows = []
    for level in LEVEL_SPECS.keys():
        cont = eval_mode(base, reasoner, level, mode="continue")
        rest = eval_mode(base, reasoner, level, mode="restart")
        proj = eval_mode(base, reasoner, level, mode="overwrite", overwrite_spec=OVERWRITE_SPECS["project"])
        adap = eval_mode(base, reasoner, level, mode="overwrite", overwrite_spec=OVERWRITE_SPECS["adaptive"])
        heur = eval_mode(
            base, reasoner, level, mode="heuristic",
            overwrite_spec=OVERWRITE_SPECS["adaptive"],
            low_thr=best_heur["low"], high_thr=best_heur["high"]
        )
        oracle = eval_mode(
            base, reasoner, level, mode="oracle",
            overwrite_spec=OVERWRITE_SPECS["adaptive"],
            batches=ORACLE_BATCHES, bs=128
        )

        rows.append({
            "seed": seed,
            "level": level,
            "level_name": level_name(level),
            "continue_acc": cont["acc"],
            "restart_acc": rest["acc"],
            "project_acc": proj["acc"],
            "adaptive_acc": adap["acc"],
            "heuristic_acc": heur["acc"],
            "oracle_acc": oracle["acc"],
            "heuristic_continue_rate": heur["continue_rate"],
            "heuristic_overwrite_rate": heur["overwrite_rate"],
            "heuristic_restart_rate": heur["restart_rate"],
            "oracle_continue_rate": oracle["continue_rate"],
            "oracle_overwrite_rate": oracle["overwrite_rate"],
            "oracle_restart_rate": oracle["restart_rate"],
            "continue_score_gap": cont["score_correct_mean"] - cont["score_incorrect_mean"]
                if not (math.isnan(cont["score_correct_mean"]) or math.isnan(cont["score_incorrect_mean"]))
                else float("nan"),
            "heuristic_score_gap": heur["score_correct_mean"] - heur["score_incorrect_mean"]
                if not (math.isnan(heur["score_correct_mean"]) or math.isnan(heur["score_incorrect_mean"]))
                else float("nan"),
            "oracle_score_gap": oracle["score_correct_mean"] - oracle["score_incorrect_mean"]
                if not (math.isnan(oracle["score_correct_mean"]) or math.isnan(oracle["score_incorrect_mean"]))
                else float("nan"),
            "best_low": best_heur["low"],
            "best_high": best_heur["high"],
        })

        print(f"\n--- Seed {seed} | Level {level} ({level_name(level)}) ---")
        print(f"Continue-only acc : {cont['acc']:.4f}")
        print(f"Restart-only acc  : {rest['acc']:.4f}")
        print(f"Project overwrite  : {proj['acc']:.4f}")
        print(f"Adaptive overwrite : {adap['acc']:.4f}")
        print(f"Heuristic ctrl acc : {heur['acc']:.4f}")
        print(f"Oracle ctrl acc    : {oracle['acc']:.4f}")
        print(f"Heuristic C/O/R    : {heur['continue_rate']:.3f}/{heur['overwrite_rate']:.3f}/{heur['restart_rate']:.3f}")
        print(f"Oracle C/O/R       : {oracle['continue_rate']:.3f}/{oracle['overwrite_rate']:.3f}/{oracle['restart_rate']:.3f}")
        print(f"Heuristic score gap: {rows[-1]['heuristic_score_gap']:.4f}")

    return pd.DataFrame(rows)

# -----------------------------
# Run
# -----------------------------
all_rows = []
for seed in SEEDS:
    all_rows.append(run_one_seed(seed))

df = pd.concat(all_rows, ignore_index=True)

pd.set_option("display.max_columns", None)
pd.set_option("display.width", 180)

print("\n\n==============================")
print("Raw results")
print("==============================")
print(df.round(4).to_string(index=False))

# -----------------------------
# Compact summaries
# -----------------------------
cond_summary = (
    df.groupby(["level", "level_name"], as_index=False)
      .agg(
          continue_acc_mean=("continue_acc", "mean"),
          continue_acc_std=("continue_acc", "std"),
          restart_acc_mean=("restart_acc", "mean"),
          restart_acc_std=("restart_acc", "std"),
          project_acc_mean=("project_acc", "mean"),
          project_acc_std=("project_acc", "std"),
          adaptive_acc_mean=("adaptive_acc", "mean"),
          adaptive_acc_std=("adaptive_acc", "std"),
          heuristic_acc_mean=("heuristic_acc", "mean"),
          heuristic_acc_std=("heuristic_acc", "std"),
          oracle_acc_mean=("oracle_acc", "mean"),
          oracle_acc_std=("oracle_acc", "std"),
          heuristic_continue_rate=("heuristic_continue_rate", "mean"),
          heuristic_overwrite_rate=("heuristic_overwrite_rate", "mean"),
          heuristic_restart_rate=("heuristic_restart_rate", "mean"),
          oracle_continue_rate=("oracle_continue_rate", "mean"),
          oracle_overwrite_rate=("oracle_overwrite_rate", "mean"),
          oracle_restart_rate=("oracle_restart_rate", "mean"),
          continue_score_gap=("continue_score_gap", "mean"),
          heuristic_score_gap=("heuristic_score_gap", "mean"),
          oracle_score_gap=("oracle_score_gap", "mean"),
      )
)

seed_summary = (
    df.groupby(["seed"], as_index=False)
      .agg(
          continue_acc=("continue_acc", "mean"),
          restart_acc=("restart_acc", "mean"),
          project_acc=("project_acc", "mean"),
          adaptive_acc=("adaptive_acc", "mean"),
          heuristic_acc=("heuristic_acc", "mean"),
          oracle_acc=("oracle_acc", "mean"),
          heuristic_overwrite_rate=("heuristic_overwrite_rate", "mean"),
          heuristic_restart_rate=("heuristic_restart_rate", "mean"),
          oracle_overwrite_rate=("oracle_overwrite_rate", "mean"),
          oracle_restart_rate=("oracle_restart_rate", "mean"),
      )
)

print("\n\n==============================")
print("Summary by level")
print("==============================")
print(cond_summary.round(4).to_string(index=False))

print("\n\n==============================")
print("Summary by seed")
print("==============================")
print(seed_summary.round(4).to_string(index=False))

print("\nDone.")

# M-CLTR next decisive test:
# Knowledge-strength sweep + recipe visibility sweep
# Goal:
#   Does controller quality improve smoothly as k0 becomes stronger?
#   Does visible recipe matter once knowledge is partially improved?
#
# This is a single self-contained run:
#   - train a weak base model
#   - train a reasoner on mixed knowledge strengths
#   - train an evaluator
#   - pick heuristic thresholds on a small validation sweep
#   - evaluate continue / restart / project / adaptive / heuristic / oracle
#     across:
#       alpha in {0.00, 0.33, 0.66, 1.00}
#       recipe_visible in {False, True}
#       levels 0..3
#   - print compact summary tables only

import math
import random
import time
from typing import Dict, Tuple, Optional, List

import numpy as np
import pandas as pd
import torch
import torch.nn as nn
import torch.nn.functional as F

# -----------------------------
# Device / reproducibility
# -----------------------------
DEVICE = torch.device("cuda" if torch.cuda.is_available() else "cpu")
print("Device:", DEVICE)

def set_seed(seed: int) -> None:
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    if torch.cuda.is_available():
        torch.cuda.manual_seed_all(seed)

torch.set_float32_matmul_precision("high")

# -----------------------------
# Config
# -----------------------------
NUM_VALUES = 10
NUM_CLASSES = 10
OP_DIM = 2

SEQ_LEN = 5
T = SEQ_LEN

BASE_X_DIM = SEQ_LEN * NUM_VALUES + OP_DIM
K_DIM = NUM_CLASSES
Z_DIM = 64
STEP_INP_DIM = NUM_VALUES + OP_DIM

SEEDS = [7, 17]          # reduce to [7] if you need a faster run
BASE_EPOCHS = 4
REASONER_EPOCHS = 4
EVAL_EPOCHS = 2

BASE_STEPS_PER_EPOCH = 20
REASONER_STEPS_PER_EPOCH = 20
EVAL_STEPS_PER_EPOCH = 16

BATCH_SIZE = 128
EVAL_BATCHES = 4
THRESHOLD_VAL_BATCHES = 3

LR_BASE = 2e-3
LR_REASONER = 2e-3
LR_EVAL = 2e-3

LEVEL_SPECS = {
    0: {"name": "no switch / clean",            "switch_step": T,      "input_noise": 0.00, "corrupt_step": None, "corrupt_severity": 0.00},
    1: {"name": "mid switch / mild corruption", "switch_step": T // 2, "input_noise": 0.00, "corrupt_step": None, "corrupt_severity": 0.00},
    2: {"name": "early switch / medium corruption", "switch_step": 1,   "input_noise": 0.00, "corrupt_step": None, "corrupt_severity": 0.00},
    3: {"name": "mid switch / strong corruption",  "switch_step": T // 2, "input_noise": 0.10, "corrupt_step": 2,    "corrupt_severity": 0.35},
}

EVAL_LEVELS = [0, 1, 2, 3]
TRAIN_LEVELS = [0, 1, 2, 3]

TRAIN_ALPHAS = [0.0, 0.33, 0.66]   # train on imperfect knowledge only
EVAL_ALPHAS = [0.0, 0.33, 0.66, 1.0]

OVERWRITE_SPECS = {
    "project": ("project", 4.0),
    "adaptive": ("adaptive_project", (0.20, 0.90)),
}

# -----------------------------
# Helpers
# -----------------------------
def one_hot(v: torch.Tensor, n: int) -> torch.Tensor:
    return F.one_hot(v.long(), n).float()

def step_feature(t: int, batch_size: int, device: torch.device) -> torch.Tensor:
    s = 0.0 if T <= 1 else float(t) / float(T - 1)
    return torch.full((batch_size, 1), s, device=device)

def mean_std(values):
    arr = np.asarray(values, dtype=np.float64)
    if arr.size == 1:
        return float(arr.item()), 0.0
    return float(arr.mean()), float(arr.std(ddof=1))

def level_name(level: int) -> str:
    return LEVEL_SPECS[level]["name"]

def inject_mistake(z: torch.Tensor, severity: float) -> torch.Tensor:
    if severity <= 0:
        return z
    rolled = torch.roll(z, shifts=1, dims=-1)
    mixed = (1.0 - severity) * z + severity * rolled
    mixed = mixed + (0.50 * severity) * torch.randn_like(z)
    return mixed

def encode_base_input(nums: torch.Tensor, start_mode: torch.Tensor) -> torch.Tensor:
    nums_oh = one_hot(nums, NUM_VALUES).reshape(nums.size(0), -1)
    start_oh = one_hot(start_mode, OP_DIM)
    return torch.cat([nums_oh, start_oh], dim=-1)

def blend_k0(normal_k0: torch.Tensor, target: torch.Tensor, alpha: float) -> torch.Tensor:
    perfect_k0 = one_hot(target, NUM_CLASSES).to(normal_k0.device)
    return (1.0 - alpha) * normal_k0 + alpha * perfect_k0

def task_value(nums: torch.Tensor, mode_seq: torch.Tensor) -> torch.Tensor:
    acc = nums[:, 0]
    for t in range(1, T):
        mode = mode_seq[:, t]
        add = (acc + nums[:, t]) % NUM_VALUES
        mul = (acc * nums[:, t]) % NUM_VALUES
        acc = torch.where(mode == 0, add, mul)
    return acc.long()

def make_batch(batch_size: int, level: int):
    spec = LEVEL_SPECS[level]
    nums = torch.randint(0, NUM_VALUES, (batch_size, T), device=DEVICE)
    start_mode = torch.randint(0, 2, (batch_size,), device=DEVICE)

    switch_step = spec["switch_step"]
    end_mode = start_mode.clone() if switch_step >= T else (1 - start_mode)

    t_ids = torch.arange(T, device=DEVICE).unsqueeze(0).expand(batch_size, T)
    mode_seq = torch.where(t_ids < switch_step, start_mode.unsqueeze(1), end_mode.unsqueeze(1))

    target = task_value(nums, mode_seq)
    x_base = encode_base_input(nums, start_mode)

    if spec["input_noise"] > 0:
        x_base = torch.clamp(x_base + spec["input_noise"] * torch.randn_like(x_base), 0.0, 1.0)

    start_ctrl = one_hot(start_mode, OP_DIM)
    return nums, mode_seq, x_base, start_ctrl, target

def build_step_input(nums: torch.Tensor, mode_seq: torch.Tensor, recipe_visible: bool, t: int) -> torch.Tensor:
    num_oh = one_hot(nums[:, t], NUM_VALUES)
    if recipe_visible:
        mode_oh = one_hot(mode_seq[:, t], OP_DIM)
    else:
        mode_oh = torch.zeros(nums.size(0), OP_DIM, device=nums.device)
    return torch.cat([num_oh, mode_oh], dim=-1)

def set_requires_grad(module: nn.Module, flag: bool):
    for p in module.parameters():
        p.requires_grad = flag

# -----------------------------
# Models
# -----------------------------
class MLP(nn.Module):
    def __init__(self, in_dim: int, out_dim: int, hidden: int = 128):
        super().__init__()
        self.net = nn.Sequential(
            nn.Linear(in_dim, hidden),
            nn.GELU(),
            nn.Linear(hidden, hidden),
            nn.GELU(),
            nn.Linear(hidden, out_dim),
        )
        for m in self.modules():
            if isinstance(m, nn.Linear):
                nn.init.xavier_uniform_(m.weight)
                if m.bias is not None:
                    nn.init.zeros_(m.bias)

    def forward(self, x):
        return self.net(x)

class BaseModel(nn.Module):
    def __init__(self):
        super().__init__()
        self.encoder = nn.Sequential(
            nn.Linear(BASE_X_DIM, 128),
            nn.GELU(),
            nn.Linear(128, K_DIM),
            nn.LayerNorm(K_DIM),
        )
        self.classifier = nn.Sequential(
            nn.Linear(K_DIM, 64),
            nn.GELU(),
            nn.Linear(64, NUM_CLASSES),
        )
        for m in self.modules():
            if isinstance(m, nn.Linear):
                nn.init.xavier_uniform_(m.weight)
                if m.bias is not None:
                    nn.init.zeros_(m.bias)

    def encode(self, x: torch.Tensor) -> torch.Tensor:
        return self.encoder(x)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.classifier(self.encode(x))

class Reasoner(nn.Module):
    def __init__(self):
        super().__init__()
        self.init_net = MLP(K_DIM + OP_DIM, Z_DIM, hidden=128)
        self.trans_net = MLP(Z_DIM + K_DIM + STEP_INP_DIM + 1, Z_DIM, hidden=128)
        self.evaluator = MLP(Z_DIM + K_DIM + STEP_INP_DIM + 1, 1, hidden=96)
        self.decoder = nn.Linear(Z_DIM, NUM_CLASSES)
        self.z_norm = nn.LayerNorm(Z_DIM)

        for m in self.modules():
            if isinstance(m, nn.Linear):
                nn.init.xavier_uniform_(m.weight)
                if m.bias is not None:
                    nn.init.zeros_(m.bias)

    def init_state(self, k0: torch.Tensor, start_ctrl: torch.Tensor) -> torch.Tensor:
        z0 = self.init_net(torch.cat([k0, start_ctrl], dim=-1))
        return self.z_norm(z0)

    def step_update(self, z: torch.Tensor, k0: torch.Tensor, step_inp: torch.Tensor, t: int) -> torch.Tensor:
        step = step_feature(t, z.size(0), z.device)
        inp = torch.cat([z, k0, step_inp, step], dim=-1)
        delta = torch.tanh(self.trans_net(inp))
        cand = self.z_norm(0.85 * z + 0.15 * delta)
        return cand

    def eval_score(self, z: torch.Tensor, k0: torch.Tensor, step_inp: torch.Tensor, t: int) -> torch.Tensor:
        step = step_feature(t, z.size(0), z.device)
        inp = torch.cat([z, k0, step_inp, step], dim=-1)
        return torch.sigmoid(self.evaluator(inp)).squeeze(-1)

    def decode(self, z: torch.Tensor) -> torch.Tensor:
        return self.decoder(z)

# -----------------------------
# Overwrite operators
# -----------------------------
def project_overwrite(cand: torch.Tensor, z0: torch.Tensor, max_shift: float) -> torch.Tensor:
    delta = cand - z0
    delta_norm = delta.norm(dim=-1, keepdim=True).clamp_min(1e-6)
    scale = torch.clamp(torch.full_like(delta_norm, max_shift) / delta_norm, max=1.0)
    return z0 + delta * scale

def adaptive_project_overwrite(
    reasoner: Reasoner,
    cand: torch.Tensor,
    z0: torch.Tensor,
    k0: torch.Tensor,
    step_inp: torch.Tensor,
    t: int,
    lo: float,
    hi: float,
) -> torch.Tensor:
    score = reasoner.eval_score(cand, k0, step_inp, t).clamp(0.0, 1.0)
    mix = lo + (hi - lo) * score
    mix = mix.clamp(0.05, 0.95).unsqueeze(-1)

    blended = mix * cand + (1.0 - mix) * z0
    max_shift = (1.0 + 4.0 * score).unsqueeze(-1)

    delta = blended - z0
    delta_norm = delta.norm(dim=-1, keepdim=True).clamp_min(1e-6)
    scale = torch.clamp(max_shift / delta_norm, max=1.0)
    return z0 + delta * scale

def apply_overwrite(
    reasoner: Reasoner,
    cand: torch.Tensor,
    z0: torch.Tensor,
    k0: torch.Tensor,
    step_inp: torch.Tensor,
    t: int,
    spec: Tuple,
) -> torch.Tensor:
    kind, arg = spec
    if kind == "project":
        return reasoner.z_norm(project_overwrite(cand, z0, float(arg)))
    if kind == "adaptive_project":
        lo, hi = arg
        return reasoner.z_norm(adaptive_project_overwrite(reasoner, cand, z0, k0, step_inp, t, float(lo), float(hi)))
    raise ValueError(f"Unknown overwrite spec: {spec}")

# -----------------------------
# Rollout helpers
# -----------------------------
@torch.no_grad()
def continue_rollout_from_state(
    reasoner: Reasoner,
    z_start: torch.Tensor,
    k0: torch.Tensor,
    nums: torch.Tensor,
    mode_seq: torch.Tensor,
    recipe_visible: bool,
    start_t: int,
    level: int,
) -> torch.Tensor:
    spec = LEVEL_SPECS[level]
    z = z_start
    for t in range(start_t, T):
        step_inp = build_step_input(nums, mode_seq, recipe_visible, t)
        z = reasoner.step_update(z, k0, step_inp, t)
        if spec["corrupt_step"] is not None and t == spec["corrupt_step"]:
            z = inject_mistake(z, spec["corrupt_severity"])
    return z

@torch.no_grad()
def final_target_prob_from_state(
    reasoner: Reasoner,
    z_start: torch.Tensor,
    k0: torch.Tensor,
    nums: torch.Tensor,
    mode_seq: torch.Tensor,
    recipe_visible: bool,
    start_t: int,
    target: torch.Tensor,
    level: int,
) -> torch.Tensor:
    z_final = continue_rollout_from_state(
        reasoner, z_start, k0, nums, mode_seq, recipe_visible, start_t, level
    )
    logits = reasoner.decode(z_final)
    probs = F.softmax(logits, dim=-1)
    return probs.gather(1, target.unsqueeze(1)).squeeze(1)

@torch.no_grad()
def choose_oracle_action(
    reasoner: Reasoner,
    cand: torch.Tensor,
    z0: torch.Tensor,
    k0: torch.Tensor,
    nums: torch.Tensor,
    mode_seq: torch.Tensor,
    recipe_visible: bool,
    t: int,
    target: torch.Tensor,
    overwrite_spec: Tuple,
    level: int,
):
    step_inp = build_step_input(nums, mode_seq, recipe_visible, t)
    cont_state = cand
    over_state = apply_overwrite(reasoner, cand, z0, k0, step_inp, t, overwrite_spec)
    rest_state = z0

    p_cont = final_target_prob_from_state(reasoner, cont_state, k0, nums, mode_seq, recipe_visible, t + 1, target, level)
    p_over = final_target_prob_from_state(reasoner, over_state, k0, nums, mode_seq, recipe_visible, t + 1, target, level)
    p_rest = final_target_prob_from_state(reasoner, rest_state, k0, nums, mode_seq, recipe_visible, t + 1, target, level)

    probs = torch.stack([p_cont, p_over, p_rest], dim=-1)
    tie_bias = torch.tensor([2e-3, 1e-3, 0.0], device=probs.device).unsqueeze(0)
    action = (probs + tie_bias).argmax(dim=-1)
    return action, probs

@torch.no_grad()
def run_rollout(
    reasoner: Reasoner,
    k0: torch.Tensor,
    start_ctrl: torch.Tensor,
    nums: torch.Tensor,
    mode_seq: torch.Tensor,
    recipe_visible: bool,
    target: torch.Tensor,
    level: int,
    mode: str,
    overwrite_spec: Optional[Tuple] = None,
    low_thr: float = 0.30,
    high_thr: float = 0.60,
):
    z0 = reasoner.init_state(k0, start_ctrl)
    z = z0
    actions = []
    step_probs = []

    for t in range(T):
        step_inp = build_step_input(nums, mode_seq, recipe_visible, t)
        cand = reasoner.step_update(z, k0, step_inp, t)

        spec = LEVEL_SPECS[level]
        if spec["corrupt_step"] is not None and t == spec["corrupt_step"]:
            cand = inject_mistake(cand, spec["corrupt_severity"])

        if mode == "continue":
            action = torch.zeros(k0.size(0), dtype=torch.long, device=k0.device)
            z_next = cand

        elif mode == "restart":
            action = torch.full((k0.size(0),), 2, dtype=torch.long, device=k0.device)
            z_next = z0

        elif mode == "overwrite_project":
            if overwrite_spec is None:
                raise ValueError("overwrite_spec required")
            action = torch.ones(k0.size(0), dtype=torch.long, device=k0.device)
            z_next = apply_overwrite(reasoner, cand, z0, k0, step_inp, t, overwrite_spec)

        elif mode == "overwrite_adaptive":
            if overwrite_spec is None:
                raise ValueError("overwrite_spec required")
            action = torch.ones(k0.size(0), dtype=torch.long, device=k0.device)
            z_next = apply_overwrite(reasoner, cand, z0, k0, step_inp, t, overwrite_spec)

        elif mode == "heuristic":
            if overwrite_spec is None:
                raise ValueError("overwrite_spec required")
            score = reasoner.eval_score(cand, k0, step_inp, t)
            action = torch.where(
                score < low_thr,
                torch.full_like(score, 2, dtype=torch.long),
                torch.where(
                    score < high_thr,
                    torch.ones_like(score, dtype=torch.long),
                    torch.zeros_like(score, dtype=torch.long),
                ),
            )

            z_next = torch.empty_like(cand)
            cont_mask = action == 0
            over_mask = action == 1
            rest_mask = action == 2

            if cont_mask.any():
                z_next[cont_mask] = cand[cont_mask]
            if over_mask.any():
                z_next[over_mask] = apply_overwrite(
                    reasoner, cand[over_mask], z0[over_mask], k0[over_mask], step_inp[over_mask], t, overwrite_spec
                )
            if rest_mask.any():
                z_next[rest_mask] = z0[rest_mask]

        elif mode == "oracle":
            if overwrite_spec is None:
                raise ValueError("overwrite_spec required")
            action, probs = choose_oracle_action(
                reasoner, cand, z0, k0, nums, mode_seq, recipe_visible, t, target, overwrite_spec, level
            )
            z_next = torch.empty_like(cand)
            cont_mask = action == 0
            over_mask = action == 1
            rest_mask = action == 2

            if cont_mask.any():
                z_next[cont_mask] = cand[cont_mask]
            if over_mask.any():
                z_next[over_mask] = apply_overwrite(
                    reasoner, cand[over_mask], z0[over_mask], k0[over_mask], step_inp[over_mask], t, overwrite_spec
                )
            if rest_mask.any():
                z_next[rest_mask] = z0[rest_mask]

            step_probs.append(probs)

        else:
            raise ValueError(f"Unknown mode: {mode}")

        actions.append(action)
        z = z_next

    logits = reasoner.decode(z)
    pred = logits.argmax(dim=-1)
    final_eval = reasoner.eval_score(z, k0, build_step_input(nums, mode_seq, recipe_visible, T - 1), T - 1)

    out = {
        "pred": pred,
        "actions": torch.stack(actions, dim=1),
        "final_eval": final_eval,
        "z0": z0,
    }
    if mode == "oracle":
        out["step_probs"] = torch.stack(step_probs, dim=1)
    return out

# -----------------------------
# Training
# -----------------------------
def train_base(base: BaseModel, epochs: int, steps_per_epoch: int):
    base.train()
    opt = torch.optim.AdamW(base.parameters(), lr=LR_BASE, weight_decay=1e-4)
    ce = nn.CrossEntropyLoss()

    print("\n=== Stage 1: base pretraining ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_acc = 0.0
        for _ in range(steps_per_epoch):
            level = random.choice(TRAIN_LEVELS)
            nums, mode_seq, x_base, start_ctrl, target = make_batch(BATCH_SIZE, level)
            logits = base(x_base)
            loss = ce(logits, target)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(base.parameters(), 1.0)
            opt.step()

            total_loss += loss.item()
            total_acc += (logits.argmax(dim=-1) == target).float().mean().item()

        print(f"Base epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} | acc {total_acc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s")

def train_reasoner(base: BaseModel, reasoner: Reasoner, epochs: int, steps_per_epoch: int):
    base.eval()
    set_requires_grad(base, False)
    set_requires_grad(reasoner, True)

    params = (
        list(reasoner.init_net.parameters()) +
        list(reasoner.trans_net.parameters()) +
        list(reasoner.decoder.parameters()) +
        list(reasoner.z_norm.parameters())
    )
    opt = torch.optim.AdamW(params, lr=LR_REASONER, weight_decay=1e-4)
    ce = nn.CrossEntropyLoss()

    print("\n=== Stage 2: reasoner pretraining (mixed knowledge strengths) ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_acc = 0.0

        for _ in range(steps_per_epoch):
            level = random.choice(TRAIN_LEVELS)
            recipe_visible = (random.random() < 0.5)
            alpha = random.choice(TRAIN_ALPHAS)

            nums, mode_seq, x_base, start_ctrl, target = make_batch(BATCH_SIZE, level)

            with torch.no_grad():
                normal_k0 = base.encode(x_base)
                k0 = blend_k0(normal_k0, target, alpha)

            z = reasoner.init_state(k0, start_ctrl)
            for t in range(T):
                step_inp = build_step_input(nums, mode_seq, recipe_visible, t)
                z = reasoner.step_update(z, k0, step_inp, t)

                spec = LEVEL_SPECS[level]
                if spec["corrupt_step"] is not None and t == spec["corrupt_step"]:
                    z = inject_mistake(z, spec["corrupt_severity"])

            logits = reasoner.decode(z)
            loss = ce(logits, target)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(params, 1.0)
            opt.step()

            total_loss += loss.item()
            total_acc += (logits.argmax(dim=-1) == target).float().mean().item()

        print(f"Reasoner epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} | acc {total_acc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s")

def train_evaluator(base: BaseModel, reasoner: Reasoner, epochs: int, steps_per_epoch: int):
    base.eval()
    reasoner.eval()
    set_requires_grad(base, False)
    set_requires_grad(reasoner, False)
    set_requires_grad(reasoner.evaluator, True)

    opt = torch.optim.AdamW(reasoner.evaluator.parameters(), lr=LR_EVAL, weight_decay=1e-4)
    mse = nn.MSELoss()

    print("\n=== Stage 3: evaluator training (predict downstream correctness) ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_binacc = 0.0

        for _ in range(steps_per_epoch):
            level = random.choice(TRAIN_LEVELS)
            recipe_visible = (random.random() < 0.5)
            alpha = random.choice(TRAIN_ALPHAS)

            nums, mode_seq, x_base, start_ctrl, target = make_batch(BATCH_SIZE, level)

            with torch.no_grad():
                normal_k0 = base.encode(x_base)
                k0 = blend_k0(normal_k0, target, alpha)
                z = reasoner.init_state(k0, start_ctrl)

                zs, k0s, step_ins, step_ts, labels = [], [], [], [], []

                for t in range(T):
                    step_inp = build_step_input(nums, mode_seq, recipe_visible, t)
                    cand = reasoner.step_update(z, k0, step_inp, t)

                    spec = LEVEL_SPECS[level]
                    if spec["corrupt_step"] is not None and t == spec["corrupt_step"]:
                        cand = inject_mistake(cand, spec["corrupt_severity"])

                    p_target = final_target_prob_from_state(
                        reasoner, cand, k0, nums, mode_seq, recipe_visible, t + 1, target, level
                    )

                    zs.append(cand.detach())
                    k0s.append(k0.detach())
                    step_ins.append(step_inp.detach())
                    step_ts.append(step_feature(t, BATCH_SIZE, DEVICE))
                    labels.append(p_target.detach())

                    z = cand

                zs = torch.cat(zs, dim=0)
                k0s = torch.cat(k0s, dim=0)
                step_ins = torch.cat(step_ins, dim=0)
                step_ts = torch.cat(step_ts, dim=0)
                labels = torch.cat(labels, dim=0).clamp(0.0, 1.0)

            inp = torch.cat([zs, k0s, step_ins, step_ts], dim=-1)
            pred = torch.sigmoid(reasoner.evaluator(inp)).squeeze(-1)
            loss = mse(pred, labels)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(reasoner.evaluator.parameters(), 1.0)
            opt.step()

            total_loss += loss.item()
            total_binacc += ((pred > 0.5) == (labels > 0.5)).float().mean().item()

        print(f"Evaluator epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} | bin-acc {total_binacc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s")

def pick_heuristic_thresholds(base: BaseModel, reasoner: Reasoner, overwrite_spec: Tuple):
    """
    Choose low/high thresholds on a small mixed validation sweep.
    This is only for the heuristic controller.
    """
    base.eval()
    reasoner.eval()

    low_grid = [0.20, 0.30, 0.40, 0.50]
    high_grid = [0.60, 0.70, 0.80, 0.90]

    best = (-1.0, None, None)
    for low in low_grid:
        for high in high_grid:
            if low >= high:
                continue
            correct = 0
            total = 0
            for _ in range(THRESHOLD_VAL_BATCHES):
                level = random.choice(TRAIN_LEVELS)
                recipe_visible = (random.random() < 0.5)
                alpha = random.choice(TRAIN_ALPHAS)

                nums, mode_seq, x_base, start_ctrl, target = make_batch(BATCH_SIZE, level)

                with torch.no_grad():
                    normal_k0 = base.encode(x_base)
                    k0 = blend_k0(normal_k0, target, alpha)

                out = run_rollout(
                    reasoner=reasoner,
                    k0=k0,
                    start_ctrl=start_ctrl,
                    nums=nums,
                    mode_seq=mode_seq,
                    recipe_visible=recipe_visible,
                    target=target,
                    level=level,
                    mode="heuristic",
                    overwrite_spec=overwrite_spec,
                    low_thr=low,
                    high_thr=high,
                )

                correct += (out["pred"] == target).sum().item()
                total += target.numel()

            acc = correct / total
            if acc > best[0]:
                best = (acc, low, high)

    best_acc, best_low, best_high = best
    print(f"\nBest heuristic thresholds from validation: low={best_low:.2f}, high={best_high:.2f} | val acc={best_acc:.4f}")
    return best_low, best_high

# -----------------------------
# Evaluation
# -----------------------------
@torch.no_grad()
def eval_condition(
    base: BaseModel,
    reasoner: Reasoner,
    level: int,
    alpha: float,
    recipe_visible: bool,
    mode: str,
    overwrite_spec: Optional[Tuple] = None,
    batches: int = EVAL_BATCHES,
    bs: int = 128,
    low_thr: float = 0.30,
    high_thr: float = 0.60,
):
    base.eval()
    reasoner.eval()

    total = 0
    correct = 0
    action_counts = torch.zeros(3, device=DEVICE)
    score_correct = []
    score_incorrect = []

    for _ in range(batches):
        nums, mode_seq, x_base, start_ctrl, target = make_batch(bs, level)

        normal_k0 = base.encode(x_base)
        k0 = blend_k0(normal_k0, target, alpha)

        out = run_rollout(
            reasoner=reasoner,
            k0=k0,
            start_ctrl=start_ctrl,
            nums=nums,
            mode_seq=mode_seq,
            recipe_visible=recipe_visible,
            target=target,
            level=level,
            mode=mode,
            overwrite_spec=overwrite_spec,
            low_thr=low_thr,
            high_thr=high_thr,
        )

        pred = out["pred"]
        correct_mask = pred == target
        correct += correct_mask.sum().item()
        total += target.numel()

        if mode in ("heuristic", "oracle"):
            action_counts += torch.stack([
                (out["actions"] == 0).sum(),
                (out["actions"] == 1).sum(),
                (out["actions"] == 2).sum(),
            ]).float()

        score = out["final_eval"]
        if correct_mask.any():
            score_correct.append(score[correct_mask].mean().item())
        if (~correct_mask).any():
            score_incorrect.append(score[~correct_mask].mean().item())

    result = {
        "acc": correct / total,
        "score_correct_mean": float(np.mean(score_correct)) if len(score_correct) else float("nan"),
        "score_incorrect_mean": float(np.mean(score_incorrect)) if len(score_incorrect) else float("nan"),
    }

    if mode in ("heuristic", "oracle"):
        rates = (action_counts / (batches * bs * T)).detach().cpu().numpy()
        result["continue_rate"] = float(rates[0])
        result["overwrite_rate"] = float(rates[1])
        result["restart_rate"] = float(rates[2])

    return result

def run_one_seed(seed: int):
    set_seed(seed)
    print("\n\n##############################")
    print(f"Seed = {seed}")
    print("##############################")

    base = BaseModel().to(DEVICE)
    reasoner = Reasoner().to(DEVICE)

    train_base(base, BASE_EPOCHS, BASE_STEPS_PER_EPOCH)
    train_reasoner(base, reasoner, REASONER_EPOCHS, REASONER_STEPS_PER_EPOCH)
    train_evaluator(base, reasoner, EVAL_EPOCHS, EVAL_STEPS_PER_EPOCH)

    heuristic_spec = OVERWRITE_SPECS["adaptive"]
    low_thr, high_thr = pick_heuristic_thresholds(base, reasoner, heuristic_spec)

    rows = []

    for level in EVAL_LEVELS:
        for recipe_visible in [False, True]:
            recipe_name = "visible recipe" if recipe_visible else "hidden recipe"

            for alpha in EVAL_ALPHAS:
                cond_name = f"alpha={alpha:.2f} | {recipe_name}"

                cont = eval_condition(base, reasoner, level, alpha, recipe_visible, mode="continue")
                rest = eval_condition(base, reasoner, level, alpha, recipe_visible, mode="restart")
                proj = eval_condition(base, reasoner, level, alpha, recipe_visible, mode="overwrite_project", overwrite_spec=OVERWRITE_SPECS["project"])
                adap = eval_condition(base, reasoner, level, alpha, recipe_visible, mode="overwrite_adaptive", overwrite_spec=OVERWRITE_SPECS["adaptive"])
                heur = eval_condition(
                    base, reasoner, level, alpha, recipe_visible, mode="heuristic",
                    overwrite_spec=OVERWRITE_SPECS["adaptive"], low_thr=low_thr, high_thr=high_thr
                )
                oracle = eval_condition(
                    base, reasoner, level, alpha, recipe_visible, mode="oracle",
                    overwrite_spec=OVERWRITE_SPECS["adaptive"], batches=max(2, EVAL_BATCHES // 2), bs=128
                )

                rows.append({
                    "seed": seed,
                    "level": level,
                    "level_name": level_name(level),
                    "recipe_visible": recipe_visible,
                    "recipe_name": recipe_name,
                    "alpha": alpha,
                    "condition": cond_name,
                    "continue_acc": cont["acc"],
                    "restart_acc": rest["acc"],
                    "project_acc": proj["acc"],
                    "adaptive_acc": adap["acc"],
                    "heuristic_acc": heur["acc"],
                    "oracle_acc": oracle["acc"],
                    "heuristic_continue_rate": heur.get("continue_rate", float("nan")),
                    "heuristic_overwrite_rate": heur.get("overwrite_rate", float("nan")),
                    "heuristic_restart_rate": heur.get("restart_rate", float("nan")),
                    "oracle_continue_rate": oracle.get("continue_rate", float("nan")),
                    "oracle_overwrite_rate": oracle.get("overwrite_rate", float("nan")),
                    "oracle_restart_rate": oracle.get("restart_rate", float("nan")),
                    "continue_score_gap": (
                        cont["score_correct_mean"] - cont["score_incorrect_mean"]
                        if not (math.isnan(cont["score_correct_mean"]) or math.isnan(cont["score_incorrect_mean"]))
                        else float("nan")
                    ),
                    "heuristic_score_gap": (
                        heur["score_correct_mean"] - heur["score_incorrect_mean"]
                        if not (math.isnan(heur["score_correct_mean"]) or math.isnan(heur["score_incorrect_mean"]))
                        else float("nan")
                    ),
                    "oracle_score_gap": (
                        oracle["score_correct_mean"] - oracle["score_incorrect_mean"]
                        if not (math.isnan(oracle["score_correct_mean"]) or math.isnan(oracle["score_incorrect_mean"]))
                        else float("nan")
                    ),
                    "best_low": low_thr,
                    "best_high": high_thr,
                })

                print(f"\n--- Seed {seed} | Level {level} ({level_name(level)}) | {cond_name} ---")
                print(f"Continue-only acc : {cont['acc']:.4f}")
                print(f"Restart-only acc  : {rest['acc']:.4f}")
                print(f"Project overwrite  : {proj['acc']:.4f}")
                print(f"Adaptive overwrite : {adap['acc']:.4f}")
                print(f"Heuristic ctrl acc : {heur['acc']:.4f}")
                print(f"Oracle ctrl acc    : {oracle['acc']:.4f}")
                print(f"Heuristic C/O/R    : {heur['continue_rate']:.3f}/{heur['overwrite_rate']:.3f}/{heur['restart_rate']:.3f}")
                print(f"Oracle C/O/R       : {oracle['continue_rate']:.3f}/{oracle['overwrite_rate']:.3f}/{oracle['restart_rate']:.3f}")
                print(
                    "Score gaps         : "
                    f"continue={rows[-1]['continue_score_gap']:.4f} | "
                    f"heuristic={rows[-1]['heuristic_score_gap']:.4f} | "
                    f"oracle={rows[-1]['oracle_score_gap']:.4f}"
                )

    return pd.DataFrame(rows)

# -----------------------------
# Run
# -----------------------------
all_rows = []
for seed in SEEDS:
    df_seed = run_one_seed(seed)
    all_rows.append(df_seed)

df = pd.concat(all_rows, ignore_index=True)

pd.set_option("display.max_columns", None)
pd.set_option("display.width", 220)

print("\n\n==============================")
print("Raw results")
print("==============================")
print(df.round(4).to_string(index=False))

# -----------------------------
# Compact summaries
# -----------------------------
print("\n\n==============================")
print("Summary by alpha and recipe visibility")
print("==============================")

summary_alpha_recipe = (
    df.groupby(["alpha", "recipe_name"], as_index=False)
      .agg(
          continue_acc_mean=("continue_acc", "mean"),
          restart_acc_mean=("restart_acc", "mean"),
          project_acc_mean=("project_acc", "mean"),
          adaptive_acc_mean=("adaptive_acc", "mean"),
          heuristic_acc_mean=("heuristic_acc", "mean"),
          oracle_acc_mean=("oracle_acc", "mean"),
          heuristic_continue_rate=("heuristic_continue_rate", "mean"),
          heuristic_overwrite_rate=("heuristic_overwrite_rate", "mean"),
          heuristic_restart_rate=("heuristic_restart_rate", "mean"),
          oracle_continue_rate=("oracle_continue_rate", "mean"),
          oracle_overwrite_rate=("oracle_overwrite_rate", "mean"),
          oracle_restart_rate=("oracle_restart_rate", "mean"),
          continue_score_gap=("continue_score_gap", "mean"),
          heuristic_score_gap=("heuristic_score_gap", "mean"),
          oracle_score_gap=("oracle_score_gap", "mean"),
      )
)
print(summary_alpha_recipe.round(4).to_string(index=False))

print("\n\n==============================")
print("Summary by level and alpha")
print("==============================")

summary_level_alpha = (
    df.groupby(["level", "level_name", "alpha"], as_index=False)
      .agg(
          continue_acc_mean=("continue_acc", "mean"),
          restart_acc_mean=("restart_acc", "mean"),
          project_acc_mean=("project_acc", "mean"),
          adaptive_acc_mean=("adaptive_acc", "mean"),
          heuristic_acc_mean=("heuristic_acc", "mean"),
          oracle_acc_mean=("oracle_acc", "mean"),
          heuristic_continue_rate=("heuristic_continue_rate", "mean"),
          heuristic_overwrite_rate=("heuristic_overwrite_rate", "mean"),
          heuristic_restart_rate=("heuristic_restart_rate", "mean"),
          oracle_continue_rate=("oracle_continue_rate", "mean"),
          oracle_overwrite_rate=("oracle_overwrite_rate", "mean"),
          oracle_restart_rate=("oracle_restart_rate", "mean"),
      )
)
print(summary_level_alpha.round(4).to_string(index=False))

print("\n\n==============================")
print("Wide view: accuracy by alpha and recipe visibility")
print("==============================")
wide = df.pivot_table(
    index=["alpha", "recipe_name"],
    values=["continue_acc", "restart_acc", "project_acc", "adaptive_acc", "heuristic_acc", "oracle_acc"],
    aggfunc="mean",
)
print(wide.round(4).to_string())

print("\nDone.")

# Final M-CLTR diagnostic sweep
# Hidden recipe only, alpha sweep, multi-seed, accuracy + speed + action rates + plots
#
# What this cell does:
#   1) trains a base model
#   2) trains a reasoner on mixed knowledge strengths
#   3) trains an evaluator
#   4) calibrates a simple heuristic controller
#   5) evaluates continue / restart / overwrite / heuristic / oracle
#   6) saves summary CSV + figures
#
# Notes:
#   - This is the clean "final paper" diagnostic for your current M-CLTR setup.
#   - A true chain-of-thought comparison needs a separate text-model benchmark.
#   - This cell reports latent-control speed and accuracy, which is the fair comparison
#     for the M-CLTR mechanism you have built.

import math
import random
import time
from typing import Dict, Tuple, Optional, List

import numpy as np
import pandas as pd
import torch
import torch.nn as nn
import torch.nn.functional as F
import matplotlib.pyplot as plt

# -----------------------------
# Device / reproducibility
# -----------------------------
DEVICE = torch.device("cuda" if torch.cuda.is_available() else "cpu")
print("Device:", DEVICE)

def set_seed(seed: int) -> None:
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    if torch.cuda.is_available():
        torch.cuda.manual_seed_all(seed)

torch.set_float32_matmul_precision("high")

# -----------------------------
# Config
# -----------------------------
NUM_VALUES = 10
NUM_CLASSES = 10
OP_DIM = 2

SEQ_LEN = 5
T = SEQ_LEN

BASE_X_DIM = SEQ_LEN * NUM_VALUES + OP_DIM  # numbers + start mode
K_DIM = NUM_CLASSES                          # lets perfect k0 be one-hot target hint
Z_DIM = 64
STEP_INP_DIM = NUM_VALUES + OP_DIM

SEEDS = [7, 17, 29]
ALPHAS = [0.00, 0.33, 0.66]   # hidden recipe only
LEVELS = {
    0: {"name": "no switch / clean",            "switch_step": T,      "input_noise": 0.00, "corrupt_step": None, "corrupt_severity": 0.00},
    1: {"name": "mid switch / mild corruption", "switch_step": T // 2, "input_noise": 0.00, "corrupt_step": None, "corrupt_severity": 0.00},
    2: {"name": "early switch / medium corruption", "switch_step": 1,   "input_noise": 0.00, "corrupt_step": None, "corrupt_severity": 0.00},
    3: {"name": "mid switch / strong corruption",  "switch_step": T // 2, "input_noise": 0.10, "corrupt_step": 2,    "corrupt_severity": 0.35},
}

TRAIN_LEVELS = [0, 1, 2, 3]
TEST_LEVELS = [0, 1, 2, 3]

BASE_EPOCHS = 4
REASONER_EPOCHS = 4
EVAL_EPOCHS = 2

BASE_STEPS_PER_EPOCH = 20
REASONER_STEPS_PER_EPOCH = 20
EVAL_STEPS_PER_EPOCH = 16

TRAIN_BATCH = 128
EVAL_BATCH = 256
ORACLE_BATCH = 128

LR_BASE = 2e-3
LR_REASONER = 2e-3
LR_EVAL = 2e-3

OVERWRITE_SPECS = {
    "project": ("project", 4.0),
    "adaptive": ("adaptive_project", (0.20, 0.90)),
}

# Heuristic thresholds are calibrated per seed on a validation slice
THRESH_GRID_LOW = [0.20, 0.25, 0.30, 0.35, 0.40, 0.45, 0.50]
THRESH_GRID_HIGH = [0.55, 0.60, 0.65, 0.70, 0.75, 0.80, 0.85, 0.90]

# -----------------------------
# Helpers
# -----------------------------
def one_hot(v: torch.Tensor, n: int) -> torch.Tensor:
    return F.one_hot(v.long(), n).float()

def step_feature(t: int, batch_size: int, device: torch.device) -> torch.Tensor:
    s = 0.0 if T <= 1 else float(t) / float(T - 1)
    return torch.full((batch_size, 1), s, device=device)

def mean_std(values):
    arr = np.asarray(values, dtype=np.float64)
    if arr.size == 1:
        return float(arr.item()), 0.0
    return float(arr.mean()), float(arr.std(ddof=1))

def get_level_spec(level: int) -> Dict:
    return LEVELS[level]

def level_name(level: int) -> str:
    return LEVELS[level]["name"]

def inject_mistake(z: torch.Tensor, severity: float) -> torch.Tensor:
    if severity <= 0:
        return z
    rolled = torch.roll(z, shifts=1, dims=-1)
    mixed = (1.0 - severity) * z + severity * rolled
    mixed = mixed + (0.50 * severity) * torch.randn_like(z)
    return mixed

def encode_base_input(nums: torch.Tensor, start_mode: torch.Tensor) -> torch.Tensor:
    nums_oh = one_hot(nums, NUM_VALUES).reshape(nums.size(0), -1)
    start_oh = one_hot(start_mode, OP_DIM)
    return torch.cat([nums_oh, start_oh], dim=-1)

def task_value(nums: torch.Tensor, mode_seq: torch.Tensor) -> torch.Tensor:
    acc = nums[:, 0]
    for t in range(1, T):
        mode = mode_seq[:, t]
        add = (acc + nums[:, t]) % NUM_VALUES
        mul = (acc * nums[:, t]) % NUM_VALUES
        acc = torch.where(mode == 0, add, mul)
    return acc.long()

def make_batch(batch_size: int, level: int):
    spec = get_level_spec(level)
    nums = torch.randint(0, NUM_VALUES, (batch_size, T), device=DEVICE)
    start_mode = torch.randint(0, 2, (batch_size,), device=DEVICE)

    switch_step = spec["switch_step"]
    end_mode = start_mode.clone() if switch_step >= T else (1 - start_mode)

    t_ids = torch.arange(T, device=DEVICE).unsqueeze(0).expand(batch_size, T)
    mode_seq = torch.where(t_ids < switch_step, start_mode.unsqueeze(1), end_mode.unsqueeze(1))

    target = task_value(nums, mode_seq)
    x_base = encode_base_input(nums, start_mode)

    if spec["input_noise"] > 0:
        x_base = torch.clamp(x_base + spec["input_noise"] * torch.randn_like(x_base), 0.0, 1.0)

    start_ctrl = one_hot(start_mode, OP_DIM)
    return nums, mode_seq, x_base, start_ctrl, target

def build_step_input(nums: torch.Tensor, mode_seq: torch.Tensor, t: int) -> torch.Tensor:
    return torch.cat([one_hot(nums[:, t], NUM_VALUES), one_hot(mode_seq[:, t], OP_DIM)], dim=-1)

def set_requires_grad(module: nn.Module, flag: bool):
    for p in module.parameters():
        p.requires_grad = flag

def mix_k0(base_k0: torch.Tensor, target: torch.Tensor, alpha: float) -> torch.Tensor:
    perfect = one_hot(target, NUM_CLASSES).to(base_k0.device)
    return (1.0 - alpha) * base_k0 + alpha * perfect

# -----------------------------
# Models
# -----------------------------
class MLP(nn.Module):
    def __init__(self, in_dim: int, out_dim: int, hidden: int = 128):
        super().__init__()
        self.net = nn.Sequential(
            nn.Linear(in_dim, hidden),
            nn.GELU(),
            nn.Linear(hidden, hidden),
            nn.GELU(),
            nn.Linear(hidden, out_dim),
        )
        for m in self.modules():
            if isinstance(m, nn.Linear):
                nn.init.xavier_uniform_(m.weight)
                if m.bias is not None:
                    nn.init.zeros_(m.bias)

    def forward(self, x):
        return self.net(x)

class BaseModel(nn.Module):
    def __init__(self):
        super().__init__()
        self.encoder = nn.Sequential(
            nn.Linear(BASE_X_DIM, 128),
            nn.GELU(),
            nn.Linear(128, K_DIM),
            nn.LayerNorm(K_DIM),
        )
        self.classifier = nn.Sequential(
            nn.Linear(K_DIM, 64),
            nn.GELU(),
            nn.Linear(64, NUM_CLASSES),
        )
        for m in self.modules():
            if isinstance(m, nn.Linear):
                nn.init.xavier_uniform_(m.weight)
                if m.bias is not None:
                    nn.init.zeros_(m.bias)

    def encode(self, x: torch.Tensor) -> torch.Tensor:
        return self.encoder(x)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.classifier(self.encode(x))

class Reasoner(nn.Module):
    def __init__(self):
        super().__init__()
        self.init_net = MLP(K_DIM + OP_DIM, Z_DIM, hidden=128)
        self.trans_net = MLP(Z_DIM + K_DIM + STEP_INP_DIM + 1, Z_DIM, hidden=128)
        self.evaluator = MLP(Z_DIM + K_DIM + STEP_INP_DIM + 1, 1, hidden=96)
        self.decoder = nn.Linear(Z_DIM, NUM_CLASSES)
        self.z_norm = nn.LayerNorm(Z_DIM)

        for m in self.modules():
            if isinstance(m, nn.Linear):
                nn.init.xavier_uniform_(m.weight)
                if m.bias is not None:
                    nn.init.zeros_(m.bias)

    def init_state(self, k0: torch.Tensor, start_ctrl: torch.Tensor) -> torch.Tensor:
        z0 = self.init_net(torch.cat([k0, start_ctrl], dim=-1))
        return self.z_norm(z0)

    def step_update(self, z: torch.Tensor, k0: torch.Tensor, step_inp: torch.Tensor, t: int) -> torch.Tensor:
        step = step_feature(t, z.size(0), z.device)
        inp = torch.cat([z, k0, step_inp, step], dim=-1)
        delta = torch.tanh(self.trans_net(inp))
        return self.z_norm(0.85 * z + 0.15 * delta)

    def eval_score(self, z: torch.Tensor, k0: torch.Tensor, step_inp: torch.Tensor, t: int) -> torch.Tensor:
        step = step_feature(t, z.size(0), z.device)
        inp = torch.cat([z, k0, step_inp, step], dim=-1)
        return torch.sigmoid(self.evaluator(inp)).squeeze(-1)

    def decode(self, z: torch.Tensor) -> torch.Tensor:
        return self.decoder(z)

# -----------------------------
# Overwrite operators
# -----------------------------
def project_overwrite(cand: torch.Tensor, z0: torch.Tensor, max_shift: float) -> torch.Tensor:
    delta = cand - z0
    delta_norm = delta.norm(dim=-1, keepdim=True).clamp_min(1e-6)
    scale = torch.clamp(torch.full_like(delta_norm, max_shift) / delta_norm, max=1.0)
    return z0 + delta * scale

def adaptive_project_overwrite(
    reasoner: Reasoner,
    cand: torch.Tensor,
    z0: torch.Tensor,
    k0: torch.Tensor,
    step_inp: torch.Tensor,
    t: int,
    lo: float,
    hi: float,
) -> torch.Tensor:
    score = reasoner.eval_score(cand, k0, step_inp, t).clamp(0.0, 1.0)
    mix = lo + (hi - lo) * score
    mix = mix.clamp(0.05, 0.95).unsqueeze(-1)
    blended = mix * cand + (1.0 - mix) * z0

    max_shift = (1.0 + 4.0 * score).unsqueeze(-1)
    delta = blended - z0
    delta_norm = delta.norm(dim=-1, keepdim=True).clamp_min(1e-6)
    scale = torch.clamp(max_shift / delta_norm, max=1.0)
    return z0 + delta * scale

def apply_overwrite(
    reasoner: Reasoner,
    cand: torch.Tensor,
    z0: torch.Tensor,
    k0: torch.Tensor,
    step_inp: torch.Tensor,
    t: int,
    spec: Tuple,
) -> torch.Tensor:
    kind, arg = spec
    if kind == "project":
        return reasoner.z_norm(project_overwrite(cand, z0, float(arg)))
    if kind == "adaptive_project":
        lo, hi = arg
        return reasoner.z_norm(adaptive_project_overwrite(reasoner, cand, z0, k0, step_inp, t, float(lo), float(hi)))
    raise ValueError(f"Unknown overwrite spec: {spec}")

# -----------------------------
# Rollout helpers
# -----------------------------
@torch.no_grad()
def continue_rollout_from_state(
    reasoner: Reasoner,
    z_start: torch.Tensor,
    k0: torch.Tensor,
    nums: torch.Tensor,
    mode_seq: torch.Tensor,
    start_t: int,
    level: int,
) -> torch.Tensor:
    spec = get_level_spec(level)
    z = z_start
    for t in range(start_t, T):
        step_inp = build_step_input(nums, mode_seq, t)
        z = reasoner.step_update(z, k0, step_inp, t)
        if spec["corrupt_step"] is not None and t == spec["corrupt_step"]:
            z = inject_mistake(z, spec["corrupt_severity"])
    return z

@torch.no_grad()
def final_target_prob_from_state(
    reasoner: Reasoner,
    z_start: torch.Tensor,
    k0: torch.Tensor,
    nums: torch.Tensor,
    mode_seq: torch.Tensor,
    start_t: int,
    target: torch.Tensor,
    level: int,
) -> torch.Tensor:
    z_final = continue_rollout_from_state(reasoner, z_start, k0, nums, mode_seq, start_t, level)
    probs = F.softmax(reasoner.decode(z_final), dim=-1)
    return probs.gather(1, target.unsqueeze(1)).squeeze(1)

@torch.no_grad()
def choose_oracle_action(
    reasoner: Reasoner,
    cand: torch.Tensor,
    z0: torch.Tensor,
    k0: torch.Tensor,
    nums: torch.Tensor,
    mode_seq: torch.Tensor,
    t: int,
    target: torch.Tensor,
    overwrite_spec: Tuple,
    level: int,
):
    step_inp = build_step_input(nums, mode_seq, t)
    cont_state = cand
    over_state = apply_overwrite(reasoner, cand, z0, k0, step_inp, t, overwrite_spec)
    rest_state = z0

    p_cont = final_target_prob_from_state(reasoner, cont_state, k0, nums, mode_seq, t + 1, target, level)
    p_over = final_target_prob_from_state(reasoner, over_state, k0, nums, mode_seq, t + 1, target, level)
    p_rest = final_target_prob_from_state(reasoner, rest_state, k0, nums, mode_seq, t + 1, target, level)

    probs = torch.stack([p_cont, p_over, p_rest], dim=-1)
    tie_bias = torch.tensor([2e-3, 1e-3, 0.0], device=probs.device).unsqueeze(0)
    action = (probs + tie_bias).argmax(dim=-1)
    return action, probs

@torch.no_grad()
def run_rollout(
    reasoner: Reasoner,
    k0: torch.Tensor,
    start_ctrl: torch.Tensor,
    nums: torch.Tensor,
    mode_seq: torch.Tensor,
    target: torch.Tensor,
    level: int,
    mode: str,
    overwrite_spec: Optional[Tuple] = None,
    low_thr: float = 0.40,
    high_thr: float = 0.60,
):
    z0 = reasoner.init_state(k0, start_ctrl)
    z = z0
    actions = []
    step_probs = []

    for t in range(T):
        step_inp = build_step_input(nums, mode_seq, t)
        cand = reasoner.step_update(z, k0, step_inp, t)

        spec = get_level_spec(level)
        if spec["corrupt_step"] is not None and t == spec["corrupt_step"]:
            cand = inject_mistake(cand, spec["corrupt_severity"])

        if mode == "continue":
            action = torch.zeros(k0.size(0), dtype=torch.long, device=k0.device)
            z_next = cand

        elif mode == "restart":
            action = torch.full((k0.size(0),), 2, dtype=torch.long, device=k0.device)
            z_next = z0

        elif mode == "overwrite":
            if overwrite_spec is None:
                raise ValueError("overwrite_spec required for overwrite mode")
            action = torch.ones(k0.size(0), dtype=torch.long, device=k0.device)
            z_next = apply_overwrite(reasoner, cand, z0, k0, step_inp, t, overwrite_spec)

        elif mode == "heuristic":
            if overwrite_spec is None:
                raise ValueError("overwrite_spec required for heuristic mode")
            score = reasoner.eval_score(cand, k0, step_inp, t)
            action = torch.where(
                score < low_thr,
                torch.full_like(score, 2, dtype=torch.long),
                torch.where(
                    score < high_thr,
                    torch.ones_like(score, dtype=torch.long),
                    torch.zeros_like(score, dtype=torch.long),
                ),
            )
            z_next = torch.empty_like(cand)
            cont_mask = action == 0
            over_mask = action == 1
            rest_mask = action == 2
            if cont_mask.any():
                z_next[cont_mask] = cand[cont_mask]
            if over_mask.any():
                z_next[over_mask] = apply_overwrite(reasoner, cand[over_mask], z0[over_mask], k0[over_mask], step_inp[over_mask], t, overwrite_spec)
            if rest_mask.any():
                z_next[rest_mask] = z0[rest_mask]

        elif mode == "oracle":
            if overwrite_spec is None:
                raise ValueError("overwrite_spec required for oracle mode")
            action, probs = choose_oracle_action(reasoner, cand, z0, k0, nums, mode_seq, t, target, overwrite_spec, level)
            z_next = torch.empty_like(cand)
            cont_mask = action == 0
            over_mask = action == 1
            rest_mask = action == 2
            if cont_mask.any():
                z_next[cont_mask] = cand[cont_mask]
            if over_mask.any():
                z_next[over_mask] = apply_overwrite(reasoner, cand[over_mask], z0[over_mask], k0[over_mask], step_inp[over_mask], t, overwrite_spec)
            if rest_mask.any():
                z_next[rest_mask] = z0[rest_mask]
            step_probs.append(probs)

        else:
            raise ValueError(f"Unknown mode: {mode}")

        actions.append(action)
        z = z_next

    logits = reasoner.decode(z)
    pred = logits.argmax(dim=-1)
    final_eval = reasoner.eval_score(z, k0, build_step_input(nums, mode_seq, T - 1), T - 1)

    out = {
        "pred": pred,
        "actions": torch.stack(actions, dim=1),
        "final_eval": final_eval,
        "z0": z0,
    }
    if mode == "oracle":
        out["step_probs"] = torch.stack(step_probs, dim=1)
    return out

# -----------------------------
# Training
# -----------------------------
def train_base(base: BaseModel, epochs: int, steps_per_epoch: int):
    base.train()
    opt = torch.optim.AdamW(base.parameters(), lr=LR_BASE, weight_decay=1e-4)
    ce = nn.CrossEntropyLoss()

    print("\n=== Stage 1: base pretraining ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_acc = 0.0
        for _ in range(steps_per_epoch):
            level = random.choice(TRAIN_LEVELS)
            nums, mode_seq, x_base, start_ctrl, target = make_batch(TRAIN_BATCH, level)
            logits = base(x_base)
            loss = ce(logits, target)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(base.parameters(), 1.0)
            opt.step()

            total_loss += loss.item()
            total_acc += (logits.argmax(dim=-1) == target).float().mean().item()

        print(f"Base epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} | acc {total_acc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s")

def train_reasoner(base: BaseModel, reasoner: Reasoner, epochs: int, steps_per_epoch: int):
    base.eval()
    set_requires_grad(base, False)
    set_requires_grad(reasoner, True)

    params = (
        list(reasoner.init_net.parameters()) +
        list(reasoner.trans_net.parameters()) +
        list(reasoner.decoder.parameters()) +
        list(reasoner.z_norm.parameters())
    )
    opt = torch.optim.AdamW(params, lr=LR_REASONER, weight_decay=1e-4)
    ce = nn.CrossEntropyLoss()

    print("\n=== Stage 2: reasoner pretraining (continue-only, hidden recipe, mixed alpha) ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_acc = 0.0

        for _ in range(steps_per_epoch):
            level = random.choice(TRAIN_LEVELS)
            alpha = random.choice(ALPHAS)
            nums, mode_seq, x_base, start_ctrl, target = make_batch(TRAIN_BATCH, level)

            with torch.no_grad():
                base_k0 = base.encode(x_base)
                k0 = mix_k0(base_k0, target, alpha)

            z = reasoner.init_state(k0, start_ctrl)
            for t in range(T):
                step_inp = build_step_input(nums, mode_seq, t)
                z = reasoner.step_update(z, k0, step_inp, t)
                spec = get_level_spec(level)
                if spec["corrupt_step"] is not None and t == spec["corrupt_step"]:
                    z = inject_mistake(z, spec["corrupt_severity"])

            logits = reasoner.decode(z)
            loss = ce(logits, target)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(params, 1.0)
            opt.step()

            total_loss += loss.item()
            total_acc += (logits.argmax(dim=-1) == target).float().mean().item()

        print(f"Reasoner epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} | acc {total_acc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s")

def train_evaluator(base: BaseModel, reasoner: Reasoner, epochs: int, steps_per_epoch: int):
    base.eval()
    reasoner.eval()
    set_requires_grad(base, False)
    set_requires_grad(reasoner, False)
    set_requires_grad(reasoner.evaluator, True)

    opt = torch.optim.AdamW(reasoner.evaluator.parameters(), lr=LR_EVAL, weight_decay=1e-4)
    mse = nn.MSELoss()

    print("\n=== Stage 3: evaluator training (predict downstream correctness) ===")
    for ep in range(epochs):
        t0 = time.time()
        total_loss = 0.0
        total_binacc = 0.0

        for _ in range(steps_per_epoch):
            level = random.choice(TRAIN_LEVELS)
            alpha = random.choice(ALPHAS)
            nums, mode_seq, x_base, start_ctrl, target = make_batch(TRAIN_BATCH, level)

            with torch.no_grad():
                base_k0 = base.encode(x_base)
                k0 = mix_k0(base_k0, target, alpha)
                z = reasoner.init_state(k0, start_ctrl)

                zs, k0s, step_ins, step_ts, labels = [], [], [], [], []

                for t in range(T):
                    step_inp = build_step_input(nums, mode_seq, t)
                    cand = reasoner.step_update(z, k0, step_inp, t)
                    spec = get_level_spec(level)
                    if spec["corrupt_step"] is not None and t == spec["corrupt_step"]:
                        cand = inject_mistake(cand, spec["corrupt_severity"])

                    p_target = final_target_prob_from_state(
                        reasoner, cand, k0, nums, mode_seq, t + 1, target, level
                    )

                    zs.append(cand.detach())
                    k0s.append(k0.detach())
                    step_ins.append(step_inp.detach())
                    step_ts.append(step_feature(t, TRAIN_BATCH, DEVICE))
                    labels.append(p_target.detach())

                    z = cand

                zs = torch.cat(zs, dim=0)
                k0s = torch.cat(k0s, dim=0)
                step_ins = torch.cat(step_ins, dim=0)
                step_ts = torch.cat(step_ts, dim=0)
                labels = torch.cat(labels, dim=0).clamp(0.0, 1.0)

            inp = torch.cat([zs, k0s, step_ins, step_ts], dim=-1)
            pred = torch.sigmoid(reasoner.evaluator(inp)).squeeze(-1)
            loss = mse(pred, labels)

            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(reasoner.evaluator.parameters(), 1.0)
            opt.step()

            total_loss += loss.item()
            total_binacc += ((pred > 0.5) == (labels > 0.5)).float().mean().item()

        print(f"Evaluator epoch {ep+1}/{epochs} | loss {total_loss/steps_per_epoch:.4f} | bin-acc {total_binacc/steps_per_epoch:.4f} | {time.time()-t0:.1f}s")

def calibrate_heuristic_thresholds(
    base: BaseModel,
    reasoner: Reasoner,
    overwrite_spec: Tuple,
    alpha: float = 0.33,
    level: int = 1,
    batches: int = 3,
    bs: int = 128,
):
    base.eval()
    reasoner.eval()

    # Collect a small validation set
    all_scores = []
    all_targets = []
    all_preds = []
    all_z0 = []
    all_k0 = []
    all_nums = []
    all_mode_seq = []
    all_start_ctrl = []

    with torch.no_grad():
        for _ in range(batches):
            nums, mode_seq, x_base, start_ctrl, target = make_batch(bs, level)
            base_k0 = base.encode(x_base)
            k0 = mix_k0(base_k0, target, alpha)
            z0 = reasoner.init_state(k0, start_ctrl)

            # Use final-step score only for calibration
            z = z0
            for t in range(T):
                step_inp = build_step_input(nums, mode_seq, t)
                z = reasoner.step_update(z, k0, step_inp, t)
            final_step_inp = build_step_input(nums, mode_seq, T - 1)
            score = reasoner.eval_score(z, k0, final_step_inp, T - 1)

            # Keep state for threshold evaluation
            all_scores.append(score.cpu())
            all_targets.append(target.cpu())
            all_nums.append(nums.cpu())
            all_mode_seq.append(mode_seq.cpu())
            all_start_ctrl.append(start_ctrl.cpu())
            all_k0.append(k0.cpu())
            all_z0.append(z0.cpu())

    scores = torch.cat(all_scores)
    targets = torch.cat(all_targets)
    nums_all = torch.cat(all_nums)
    mode_all = torch.cat(all_mode_seq)
    start_ctrl_all = torch.cat(all_start_ctrl)
    k0_all = torch.cat(all_k0)
    z0_all = torch.cat(all_z0)

    best = {"acc": -1.0, "low": None, "high": None}
    with torch.no_grad():
        for low in THRESH_GRID_LOW:
            for high in THRESH_GRID_HIGH:
                if low >= high:
                    continue
                # heuristic action from final step score only
                action = torch.where(
                    scores < low,
                    torch.full_like(scores, 2, dtype=torch.long),
                    torch.where(
                        scores < high,
                        torch.ones_like(scores, dtype=torch.long),
                        torch.zeros_like(scores, dtype=torch.long),
                    ),
                )

                # Measure what this heuristic would do on the final step
                # by simulating the final action only; this is enough to calibrate a simple controller.
                preds = []
                for i in range(scores.numel()):
                    nums_i = nums_all[i:i+1].to(DEVICE)
                    mode_i = mode_all[i:i+1].to(DEVICE)
                    k0_i = k0_all[i:i+1].to(DEVICE)
                    z0_i = z0_all[i:i+1].to(DEVICE)
                    start_ctrl_i = start_ctrl_all[i:i+1].to(DEVICE)
                    target_i = targets[i:i+1].to(DEVICE)
                    step_inp = build_step_input(nums_i, mode_i, T - 1)
                    z = reasoner.step_update(z0_i, k0_i, step_inp, T - 1)

                    a = int(action[i].item())
                    if a == 0:
                        z_next = z
                    elif a == 1:
                        z_next = apply_overwrite(reasoner, z, z0_i, k0_i, step_inp, T - 1, overwrite_spec)
                    else:
                        z_next = z0_i

                    logits = reasoner.decode(z_next)
                    pred_i = logits.argmax(dim=-1)
                    preds.append((pred_i == target_i).float().item())

                acc = float(np.mean(preds))
                if acc > best["acc"]:
                    best = {"acc": acc, "low": low, "high": high}

    return best["low"], best["high"], best["acc"]

# -----------------------------
# Evaluation
# -----------------------------
@torch.no_grad()
def eval_condition(
    base: BaseModel,
    reasoner: Reasoner,
    level: int,
    alpha: float,
    mode: str,
    overwrite_spec: Optional[Tuple],
    low_thr: float,
    high_thr: float,
    batches: int = 6,
    bs: int = 256,
):
    base.eval()
    reasoner.eval()

    total = 0
    correct = 0
    action_counts = torch.zeros(3, device=DEVICE)
    score_correct = []
    score_incorrect = []

    t0 = time.time()
    for _ in range(batches):
        nums, mode_seq, x_base, start_ctrl, target = make_batch(bs, level)
        base_k0 = base.encode(x_base)
        k0 = mix_k0(base_k0, target, alpha)

        out = run_rollout(
            reasoner=reasoner,
            k0=k0,
            start_ctrl=start_ctrl,
            nums=nums,
            mode_seq=mode_seq,
            target=target,
            level=level,
            mode=mode,
            overwrite_spec=overwrite_spec,
            low_thr=low_thr,
            high_thr=high_thr,
        )

        pred = out["pred"]
        correct_mask = pred == target
        correct += correct_mask.sum().item()
        total += target.numel()

        if mode in ("heuristic", "oracle"):
            action_counts += torch.stack([
                (out["actions"] == 0).sum(),
                (out["actions"] == 1).sum(),
                (out["actions"] == 2).sum(),
            ]).float()

        score = out["final_eval"]
        if correct_mask.any():
            score_correct.append(score[correct_mask].mean().item())
        if (~correct_mask).any():
            score_incorrect.append(score[~correct_mask].mean().item())

    elapsed = time.time() - t0
    result = {
        "acc": correct / total,
        "score_correct_mean": float(np.mean(score_correct)) if len(score_correct) else float("nan"),
        "score_incorrect_mean": float(np.mean(score_incorrect)) if len(score_incorrect) else float("nan"),
        "seconds": elapsed,
        "ms_per_example": 1000.0 * elapsed / total,
    }

    if mode in ("heuristic", "oracle"):
        rates = (action_counts / (batches * bs * T)).detach().cpu().numpy()
        result["continue_rate"] = float(rates[0])
        result["overwrite_rate"] = float(rates[1])
        result["restart_rate"] = float(rates[2])

    return result

# -----------------------------
# One seed run
# -----------------------------
def run_one_seed(seed: int):
    set_seed(seed)
    print("\n\n##############################")
    print(f"Seed = {seed}")
    print("##############################")

    base = BaseModel().to(DEVICE)
    reasoner = Reasoner().to(DEVICE)

    train_base(base, BASE_EPOCHS, BASE_STEPS_PER_EPOCH)
    train_reasoner(base, reasoner, REASONER_EPOCHS, REASONER_STEPS_PER_EPOCH)
    train_evaluator(base, reasoner, EVAL_EPOCHS, EVAL_STEPS_PER_EPOCH)

    rows = []

    for level in TEST_LEVELS:
        # Calibrate heuristic on a small validation slice at alpha=0.33
        best_low, best_high, best_val_acc = calibrate_heuristic_thresholds(
            base=base,
            reasoner=reasoner,
            overwrite_spec=OVERWRITE_SPECS["adaptive"],
            alpha=0.33,
            level=level,
            batches=2,
            bs=96,
        )
        print(f"\nBest heuristic thresholds at level {level}: low={best_low:.2f}, high={best_high:.2f} | val acc={best_val_acc:.4f}")

        for alpha in ALPHAS:
            cont = eval_condition(base, reasoner, level, alpha, "continue", None, best_low, best_high)
            rest = eval_condition(base, reasoner, level, alpha, "restart", None, best_low, best_high)
            proj = eval_condition(base, reasoner, level, alpha, "overwrite", OVERWRITE_SPECS["project"], best_low, best_high)
            adap = eval_condition(base, reasoner, level, alpha, "overwrite", OVERWRITE_SPECS["adaptive"], best_low, best_high)
            heur = eval_condition(base, reasoner, level, alpha, "heuristic", OVERWRITE_SPECS["adaptive"], best_low, best_high)
            oracle = eval_condition(base, reasoner, level, alpha, "oracle", OVERWRITE_SPECS["adaptive"], best_low, best_high, batches=3, bs=128)

            rows.append({
                "seed": seed,
                "level": level,
                "level_name": level_name(level),
                "alpha": alpha,
                "continue_acc": cont["acc"],
                "restart_acc": rest["acc"],
                "project_acc": proj["acc"],
                "adaptive_acc": adap["acc"],
                "heuristic_acc": heur["acc"],
                "oracle_acc": oracle["acc"],
                "continue_ms_per_ex": cont["ms_per_example"],
                "restart_ms_per_ex": rest["ms_per_example"],
                "project_ms_per_ex": proj["ms_per_example"],
                "adaptive_ms_per_ex": adap["ms_per_example"],
                "heuristic_ms_per_ex": heur["ms_per_example"],
                "oracle_ms_per_ex": oracle["ms_per_example"],
                "heuristic_continue_rate": heur.get("continue_rate", float("nan")),
                "heuristic_overwrite_rate": heur.get("overwrite_rate", float("nan")),
                "heuristic_restart_rate": heur.get("restart_rate", float("nan")),
                "oracle_continue_rate": oracle.get("continue_rate", float("nan")),
                "oracle_overwrite_rate": oracle.get("overwrite_rate", float("nan")),
                "oracle_restart_rate": oracle.get("restart_rate", float("nan")),
                "continue_score_gap": (
                    cont["score_correct_mean"] - cont["score_incorrect_mean"]
                    if (not math.isnan(cont["score_correct_mean"]) and not math.isnan(cont["score_incorrect_mean"]))
                    else float("nan")
                ),
                "heuristic_score_gap": (
                    heur["score_correct_mean"] - heur["score_incorrect_mean"]
                    if (not math.isnan(heur["score_correct_mean"]) and not math.isnan(heur["score_incorrect_mean"]))
                    else float("nan")
                ),
                "oracle_score_gap": (
                    oracle["score_correct_mean"] - oracle["score_incorrect_mean"]
                    if (not math.isnan(oracle["score_correct_mean"]) and not math.isnan(oracle["score_incorrect_mean"]))
                    else float("nan")
                ),
                "best_low": best_low,
                "best_high": best_high,
                "heuristic_val_acc": best_val_acc,
            })

            print(f"\n--- Seed {seed} | Level {level} ({level_name(level)}) | alpha={alpha:.2f} ---")
            print(f"Continue-only acc : {cont['acc']:.4f}")
            print(f"Restart-only acc  : {rest['acc']:.4f}")
            print(f"Project overwrite  : {proj['acc']:.4f}")
            print(f"Adaptive overwrite : {adap['acc']:.4f}")
            print(f"Heuristic ctrl acc : {heur['acc']:.4f}")
            print(f"Oracle ctrl acc    : {oracle['acc']:.4f}")
            print(f"Heuristic C/O/R    : {heur['continue_rate']:.3f}/{heur['overwrite_rate']:.3f}/{heur['restart_rate']:.3f}")
            print(f"Oracle C/O/R       : {oracle['continue_rate']:.3f}/{oracle['overwrite_rate']:.3f}/{oracle['restart_rate']:.3f}")
            print(f"Heuristic score gap: {heur['score_correct_mean'] - heur['score_incorrect_mean'] if not (math.isnan(heur['score_correct_mean']) or math.isnan(heur['score_incorrect_mean'])) else float('nan'):.4f}")

    return pd.DataFrame(rows)

# -----------------------------
# Run
# -----------------------------
all_rows = []
for seed in SEEDS:
    df_seed = run_one_seed(seed)
    all_rows.append(df_seed)

df = pd.concat(all_rows, ignore_index=True)

pd.set_option("display.max_columns", None)
pd.set_option("display.width", 220)

print("\n\n==============================")
print("Raw results")
print("==============================")
print(df.round(4).to_string(index=False))

