# -----------------------------
# Plots
# -----------------------------
def plot_accuracy_summary(df_summary: pd.DataFrame, out_path: str):
    plt.figure(figsize=(10, 6))
    modes = [
        ("continue_acc_mean", "continue_acc_std", "Continue"),
        ("restart_acc_mean", "restart_acc_std", "Restart"),
        ("project_acc_mean", "project_acc_std", "Project overwrite"),
        ("adaptive_acc_mean", "adaptive_acc_std", "Adaptive overwrite"),
        ("heuristic_acc_mean", "heuristic_acc_std", "Heuristic controller"),
        ("oracle_acc_mean", "oracle_acc_std", "Oracle controller"),
    ]
    for mean_col, std_col, label in modes:
        plt.errorbar(
            df_summary["alpha"],
            df_summary[mean_col],
            yerr=df_summary[std_col].fillna(0.0),
            marker="o",
            linewidth=2,
            capsize=4,
            label=label,
        )
    plt.xticks(ALPHAS, [f"{a:.2f}" for a in ALPHAS])
    plt.ylim(0.0, 1.05)
    plt.xlabel("Knowledge strength α")
    plt.ylabel("Accuracy")
    plt.title("M-CLTR final sweep: accuracy vs knowledge strength")
    plt.legend(frameon=False, ncol=2)
    plt.tight_layout()
    plt.savefig(out_path, dpi=200, bbox_inches="tight")
    plt.show()

def plot_action_rates(df_summary: pd.DataFrame, out_path: str):
    # one figure, grouped by alpha, showing heuristic and oracle C/O/R rates
    fig, ax = plt.subplots(figsize=(10, 6))
    width = 0.12
    x = np.arange(len(ALPHAS))

    series = [
        ("heuristic_continue_rate", "Heuristic continue"),
        ("heuristic_overwrite_rate", "Heuristic overwrite"),
        ("heuristic_restart_rate", "Heuristic restart"),
        ("oracle_continue_rate", "Oracle continue"),
        ("oracle_overwrite_rate", "Oracle overwrite"),
        ("oracle_restart_rate", "Oracle restart"),
    ]

    for i, (col, label) in enumerate(series):
        offset = (i - 2.5) * width
        ax.bar(x + offset, df_summary[col], width=width, label=label)

    ax.set_xticks(x)
    ax.set_xticklabels([f"{a:.2f}" for a in ALPHAS])
    ax.set_ylim(0.0, 1.0)
    ax.set_xlabel("Knowledge strength α")
    ax.set_ylabel("Action rate")
    ax.set_title("M-CLTR final sweep: controller action rates")
    ax.legend(frameon=False, ncol=2)
    fig.tight_layout()
    fig.savefig(out_path, dpi=200, bbox_inches="tight")
    plt.show()

def plot_speed_summary(df_summary: pd.DataFrame, out_path: str):
    plt.figure(figsize=(8, 5))
    plt.plot(df_summary["alpha"], df_summary["continue_ms_per_ex_mean"], marker="o", linewidth=2, label="Continue")
    plt.plot(df_summary["alpha"], df_summary["heuristic_ms_per_ex_mean"], marker="o", linewidth=2, label="Heuristic")
    plt.plot(df_summary["alpha"], df_summary["oracle_ms_per_ex_mean"], marker="o", linewidth=2, label="Oracle")
    plt.xticks(ALPHAS, [f"{a:.2f}" for a in ALPHAS])
    plt.xlabel("Knowledge strength α")
    plt.ylabel("ms / example")
    plt.title("M-CLTR final sweep: runtime per example")
    plt.legend(frameon=False)
    plt.tight_layout()
    plt.savefig(out_path, dpi=200, bbox_inches="tight")
    plt.show()

plot_accuracy_summary(summary_by_alpha, "mcltr_final_accuracy.png")
plot_action_rates(summary_by_alpha, "mcltr_final_action_rates.png")
plot_speed_summary(summary_by_alpha, "mcltr_final_speed.png")

